local P = LoreForeverPacks.Begin("LoreForever_Lang_svSE")
P.entries["quest:6322"] = {n="Michael Garrett",s="Michael Garrett är ett enkelt kuriruppdrag som knyter handeln i Undercity till Forsakens flygnätverk. Efter att ha hämtat förnödenheter packade av Gordon Wendham i Trade Quarter ska du leverera lådan till fladdermushanteraren Michael Garrett för att ordna flygtransport mot Sepulcher. Uppdraget visar hur Forsaken använder tränade vampyrfladdermöss för att förbinda sin huvudstad med utposter runt om i Lordaeron.",h="Michael Garrett är ett enkelt kuriruppdrag som knyter handeln i Undercity till Forsakens flygnätverk.",kw={"fladdermusmästare","flygmästare","gordon wendham","gordon's crate","michael garrett","the sepulcher","silverpine","undercity"},ang={["faction:Horde"]="För resenärer som anländer från Kalimdor är Forsakens fladdermusnätverk det främsta sättet att snabbt ta sig genom norra Eastern Kingdoms.",["race:Undead"]="För att upprätthålla Sylvanas närvaro bortom Tirisfal Glades måste du förstå den luftburna försörjningslinje som sköts av hanterare som Michael Garrett."},sec={{t="Förnödenheter till utposterna",b="Ett ungt kungarike, uthugget ur Ruins of Lordaeron, kräver ständig logistik. Utposter som Sepulcher i Silverpine Forest är beroende av varor, ammunition och förnödenheter från Undercity. Gordon Wendham packar de nödvändiga fältförnödenheterna i en enda låda i stadens Trade Quarter, men att frakta gods landvägen genom pestdrabbade skogar går långsamt och riskerar bakhåll från kvarvarande Scourge eller vilda bestar."},{t="Forsakens vingar",b="För att undvika farorna på vägarna förlitar sig Forsaken på fångna vampyrfladdermöss som föds upp och sköts av skickliga hanterare. Michael Garrett ansvarar för dessa bevingade bestar från sitt näste i Undercitys Trade Quarter. När du levererar lasten till honom kan förnödenheterna spännas fast på en fladdermus och flygas direkt över kullarna till Silverpine. På så sätt får nya kurirer lära sig hur huvudstaden samordnar sig med avlägsna bosättningar."}},faq={{q="Vem är Michael Garrett?",a="Michael Garrett är Undercitys fladdermushanterare och håller till i Trade Quarter. Han sköter flygnätverkets vampyrfladdermöss och ordnar resor och flygleveranser mellan Forsakens huvudstad och allierade flygmästare runt om i Lordaeron.",al={"michael garrett","undercitys fladdermusmästare","vem är garrett"}},{q="Vad finns i Gordon's Crate?",a="Lådan innehåller viktiga proviantvaror och fältförnödenheter som Gordon Wendham samlat ihop i Trade Quarter. De är särskilt avsedda för Forsakens styrkor vid Sepulcher i Silverpine Forest.",al={"gordon's crate","vilka förnödenheter","sepulchers låda"}},{q="Varför använda fladdermöss i stället för kärror eller hästar?",a="Landsvägarna som slingrar sig från Tirisfal Glades in i Silverpine Forest är fulla av faror, däribland kringströvande Scourge-bestar, fientliga människor och förrädisk terräng. Flygrutter med tränade jättefladdermöss går mycket snabbare och kringgår helt bakhåll på marken.",al={"varför flyga med fladdermus","varför använda fladdermöss","flygtransport av förnödenheter"}},{q="Vart går leveransen efter Michael Garrett?",a="När Michael Garrett tar emot Gordon's Crate görs lasten i ordning för att flygas direkt med fladdermus till fladdermusmästaren vid Sepulcher i Silverpine Forest. Därmed är logistikkedjan fullbordad.",al={"nästa steg","efter michael garrett","vart flyger fladdermössen"}},{q="Var i Undercity finns Michael Garrett?",a="Han finns i den sydvästra delen av Trade Quarter, samma kvarter där fladdermöss från Sepulcher landar.",al={"var finns garrett","hitta fladdermushanteraren","var finns undercitys flygmästare"}},{q="Måste du ha besökt Sepulcher innan du gör det här?",a="Om du själv vill rida på en fladdermus tillsammans med leveransen måste du först ha talat med flyghanteraren vid Sepulcher för att låsa upp flygrutten. Annars får du ta dig dit till fots.",al={"krävs sepulchers flygrutt","kan jag flyga direkt"}}},fx={["2851daa3"]={q="Varför vill Gordon Wendham att detta ska göras?",a="Gordon Wendham ansvarar för att samordna viktiga förnödenheter till The Sepulcher, de fördömdas utpost i Silverpine Forest. Eftersom han måste stanna vid sin handelsplats i Undercity och sköta varorna behöver han att du lämnar den packade lådan till Michael Garrett, så att den snabbt kan skickas iväg längs deras flygbudsrutt.",al={"varför skicka gordon's crate","gordon wendhams motiv","varför ta lådan till michael garrett"}}},fp="15,221,22.281.0,21.321.0,23.175.0,26.112.0,40.103.0,49.146.0,48.120.0,60.155.0"}
P.entries["quest:6323"] = {n="Ride to the Undercity",s="Ride to the Undercity introducerar nyblivna Forsaken-äventyrare till Hordens nätverk av flygrutter genom Lordaeron. Kurirer bär vapenbeställningar från den hårt ansatta utposten The Sepulcher och tar en fasadfladdermus direkt till Undercitys Trade Quarter för att förse områdets försvarare med nya förråd.",h="Ride to the Undercity introducerar nyblivna Forsaken-äventyrare till Hordens nätverk av flygrutter genom...",kw={"fasadfladdermus","flygmästare","gordon wendham","karos razok","podrig's order","ride to the undercity","the sepulcher","trade quarter"},ang={["faction:Horde"]="Flygmästare är den viktiga länken i Hordens territoriella expansion. De gör långa och mödosamma färder genom vildmarken till snabba taktiska förflyttningar.",["profession:Blacksmithing"]="När man levererar beställningar till Gordon Wendham får smederna en inblick i Lordaerons logistiska ryggrad, där varje järnstycke hålls vasst och redo för krig.",["race:Undead"]="Färden från Silverpine till huvudstaden visar räckvidden och organisationen i Dark Ladys nätverk och ser till att isolerade garnisoner aldrig stängs ute från Undercitys industri."},sec={{t="Vingar över Silverpine",b="För att hålla kommunikationslinjerna mellan Forsakens huvudstad och utposterna vid fronten krävs snabba och pålitliga transporter. Karos Razok, fladdermusskötaren som är stationerad vid The Sepulcher i Silverpine Forest, sköter de tränade fasadfladdermössen som transporterar budbärare och förnödenheter över det pesthärjade landskapet. Eftersom fientliga bestar, Moonrage-worgen och rester av Scourge stryker längs vägarna är det säkrast och snabbast att ta sig upp i luften för att se till att brådskande militära beställningar når huvudstaden."},{t="Beväpna fronten",b="När kuriren landar i Undercitys livliga Trade Quarter levererar hen Podrig's Order med utrustning direkt till Gordon Wendham. Som vapensmed i Undercity, hängiven Dark Ladys sak, ser Wendham till att regionala utposter som The Sepulcher har rena, stridsklara vapen. Att hålla dessa försvarsposter rustade är livsviktigt för den unga Forsaken-nationen när den säkrar sina gränser mot fienderna omkring den."}},faq={{q="Vad är syftet med flygturen till Undercity?",a="Uppdraget går ut på att leverera en officiell vapenbeställning från Deathguard Podrig vid The Sepulcher direkt till Gordon Wendham, en vapenhandlare i Undercitys Trade Quarter, samtidigt som nya mästare får lära sig att använda Forsakens flygnätverk.",al={"varför rida till undercity","målet med ride to the undercity","användning av podrig's order"}},{q="Vem är Karos Razok?",a="Karos Razok är fladdermusskötaren som är stationerad vid The Sepulcher i Silverpine Forest. Han ansvarar för flocken fasadfladdermöss som Forsaken använder för snabba resor och för att hålla kontakten med Undercity.",al={"karos razoks roll","vem är fladdermusskötaren vid the sepulcher"}},{q="Vem är Gordon Wendham?",a="Gordon Wendham är en vapensmed bland Forsaken i Undercitys Trade Quarter, alldeles intill fladdermusskötarens landningsplattform. Han är stolt över att hålla vapnen rena, vässade och redo för Lady Sylvanas styrkor vid fronten.",al={"gordon wendham","var finns gordon wendham"}},{q="Varför använder Forsaken fladdermöss för transporter?",a="Fasadfladdermöss är inhemska nattliga rovdjur som passar väl för Lordaerons pesthärjade himmel. De erbjuder snabb passage ovanför faror på marken, som vilda worgen, fientliga rötpälsar och Scourge.",al={"varför fladdermöss","forsakens flygriddjur"}},{q="Vad händer när leveransen är slutförd?",a="När Gordon Wendham har tagit emot beställningen hänvisar han kurirerna till Michael Garrett, fladdermusskötaren i Undercity, och öppnar därmed en returväg med flyg tillbaka mot The Sepulcher.",al={"what comes next","uppföljning till ride to the undercity"}},{q="Var landar fasadfladdermusen i Undercity?",a="Fasadfladdermusen landar på den upphöjda fladdermusplatsen mitt i Undercitys Trade Quarter, med omedelbar tillgång till stadens hantverkare och förnödenhetshandlare.",al={"fladdermusens landningsplats i undercity","var landar fladdermusen"}}},fx={d629dc0f={q="Varför vill Karos Razok att detta ska göras?",a="Som flygmästare i The Sepulcher ansvarar Karos Razok för flygbudsnätverket som förbinder Silverpine Forest med huvudstaden. Utposter som The Sepulcher är helt beroende av jämna leveranser och snabb kommunikation för att överleva hoten runt omkring. Genom att lämna Deathguard Podrigs beställning direkt till vapenleverantörerna i Undercity ser du till att frontens vakter får de vapen och den rustning de så desperat behöver för att försvara riket.",al={"varför skicka podrigs beställning","karos razoks motiv","varför flyga till undercity"}}},fp="21,158,21.325.0,16.313.0,52.193.0,19.148.0,22.194.0,41.178.0,43.156.0,47.139.0"}
P.entries["quest:6324"] = {n="Return to Podrig",s="Return to Podrig är ett logistikuppdrag som avslutar en budresa mellan Silverpine Forest och Undercity. Efter att ha levererat ett meddelande till huvudstaden får budet en vapenlåda att föra tillbaka till Deathguard Podrig vid The Sepulcher med hjälp av Forsakens nätverk av fladdermushållare.",h="Return to Podrig är ett logistikuppdrag som avslutar en budresa mellan Silverpine Forest och Undercity.",kw={"fladdermusmästare","gordons crate","karos razok","michael garrett","podrig","the sepulcher","silverpine","undercity"},ang={["faction:Horde"]="Det här uppdraget visar hur logistiken förbinder Undercity med avlägsna utposter över den norra kontinenten.",["race:Undead"]="Att hålla de främre garnisonerna beväpnade är avgörande för att försvara Lordaeron och trygga drottning Sylvanas spirande rike."},sec={{t="Undercitys försörjningslinje",b="Utposter runt om i Lordaeron är starkt beroende av regelbundna leveranser från Undercity för att kunna hålla verksamheten igång. Vid The Sepulcher i Silverpine Forest pressas Deathguards vaktposter av lokala worgen, rester av Dalaran och eftersläntrare från Scourge. Att förse avlägsna garnisoner med nytillverkade vapen är avgörande för att hålla regionen under Forsakens kontroll."},{t="Forsakens vingar",b="Bat Master Michael Garrett sköter det centrala nästet i Undercitys Trade Quarter och fungerar som nav för Forsakens flygresor. Även om fladdermössen naturligt hittar tillbaka till huvudstaden måste ryttare först samordna sig med lokala skötare som Karos Razok innan flygresor till avlägsna utposter kan planeras. Att flyga Gordon's Crate över Lordaerons himmel lär bud hur Forsaken håller samman sina utspridda fästen."}},faq={{q="Vad finns i Gordon's Crate?",a="Lådan innehåller nytillverkade vapen från Undercity, så att Deathguards vid The Sepulcher är rätt utrustade mot hoten i omgivningen.",al={"innehållet i gordons crate","vad levererar jag till podrig"}},{q="Vem är Deathguard Podrig?",a="Deathguard Podrig är en Forsaken-soldat stationerad vid The Sepulcher i Silverpine Forest. Han ansvarar för den lokala garnisonens logistik och försvar.",al={"podrig","vem är podrig"}},{q="Vem är Michael Garrett?",a="Michael Garrett är Forsakens fladdermusmästare stationerad i Undercitys Trade Quarter. Han ansvarar för att samordna flygrutter genom Lordaeron.",al={"michael garrett","undercitys fladdermusmästare"}},{q="Varför måste du tala med en fladdermusmästare innan du flyger någonstans?",a="Forsakens fladdermöss hittar naturligt tillbaka till det centrala nästet i Undercity, men för flygresor därifrån måste en rutt först fastställas med en lokal skötare så att du kommer fram säkert.",al={"regler för flygrutter","hur fungerar fladdermushållare"}},{q="Varför är The Sepulcher så viktigt att försörja?",a="The Sepulcher är Forsakens främsta bas i Silverpine Forest. Den befäster deras militära närvaro mot worgenflockar, hot från Moonrage och Dalarans styrkor i området.",al={"varför the sepulcher är viktigt","the sepulchers betydelse"}},{q="Vem är Karos Razok?",a="Karos Razok är fladdermusmästaren stationerad vid The Sepulcher i Silverpine Forest. Han sköter fladdermössen som förbinder utposten med Undercity.",al={"karos razok","the sepulchers fladdermusmästare"}}},fx={["02244cab"]={q="Varför vill Michael Garrett att det här ska göras?",a="Som Undercitys fladdermusmästare ansvarar Michael Garrett för flygtransporter och kurirvägar genom de Förtappades områden. Deathguard Podrig och soldaterna som håller The Sepulcher i Silverpine Forest behöver desperat nya vapen från huvudstaden. Garrett ser till att dessa livsviktiga vapen skickas effektivt med fladdermusnätverket och stärker därmed Mörka damens utposter vid gränsen mot närliggande hot.",al={"varför michael garretts låda","garretts motiv att återvända till podrig","varför skicka lådan till the sepulcher"}},eed737b1={q="Varför skickar Michael Garrett dig i stället för att åka själv?",a="Garrett måste stanna vid Undercitys fladdermusplats för att ta hand om djuren och samordna flygningar till och från huvudstaden. Eftersom du är en kapabel kurir som redan är på väg tillbaka mot Silverpine Forest ser han till att lådan levereras utan att värdefulla flygmästare eller vakter behöver lämna sina viktiga poster.",al={"varför skicka mig","varför levererar inte garrett den","varför jag ska återvända till podrig"}}},fp="16,163,25.241.0,21.324.0,26.120.0,25.138.0,23.122.0,65.184.0,44.169.0,19.139.0"}
P.entries["quest:633"] = {n="The Thandol Span",s="Det här viktiga uppdraget för Alliansen ger hjältar i uppgift att försvara den enda kvarvarande bron över Thandol Span. Efter det tragiska mordet på Ebenezer Rustlocke upptäcker Rhag Garmason en plan av den förrädiske Kam Deepfury att detonera gömda sprängämnen och kapa Ironforges livsviktiga förbindelse norrut.",h="Det här viktiga uppdraget för Alliansen ger hjältar i uppgift att försvara den enda kvarvarande bron över...",kw={"arathi highlands","dark iron","ebon rustlocke","sprängämnen","kam deepfury","magni bronzebeard","rhag garmason","thandol span","wetlands"},ang={["faction:Alliance"]="Att hålla Span är avgörande för kontinentens säkerhet. Om övergången faller blir det oerhört mycket farligare att flytta Alliansens arméer och resurser till Arathi och Lordaeron.",["profession:Engineering"]="Ingenjörer kan uppskatta den enorma sprängkraften i Deepfurys ammunitionsförråd, byggt för att demolera kolossalt dvärgstensarbete i titanernas stil.",["race:Dwarf"]="För Ironforges söner skyddar försvaret av Thandol Span kung Magni’s livlina till de nordliga allierade och riktar samtidigt ett slag mot förrädiska Dark Iron-infiltratörer."},sec={{t="En avslöjad plan",b="Efter att ha upptäckt Ebenezer Rustlockes öde i Thandol Spans underbyggnad avslöjar ett återfunnet dokument mörkare avsikter. Dark Iron-anstiftaren Kam Deepfury, arkitekten bakom brons första förstörelse, var inte färdig. Efter att redan ha rasat en av de storslagna stenbroarna hade hans sabotagenätverk placerat ett andra förråd med tung ammunition strax över den norra gränsen i Arathi Highlands, redo att slutföra jobbet."},{t="Rädda livlinan",b="Thandol Span är den främsta landvägen som förbinder de södra rikena Khaz Modan och Stormwind med de krigshärjade områdena i norr. För att säkra denna väg beordrar Rhag Garmason ett omedelbart förebyggande anfall mot sabotageförrådet i Arathi, innan Deepfurys konspiratörer kan använda det. När ammunitionen sprängs undanröjs den omedelbara faran och Ironforges tillgång till norr bevaras, men Garmason har fortfarande desperat ont om trupper för att försvara gapet."}},faq={{q="Vem är Kam Deepfury?",a="Kam Deepfury är den Dark Iron-dvärg som planerade sabotaget mot Thandol Span. Det räckte inte för honom att rasera den första valvbågen. Han gömde ytterligare sprängämnen på andra sidan ravinen i Arathi Highlands för att få den återstående bron att rasa.",al={"kam deepfury","vem sprängde thandol span","hjärnan bakom thandol span"}},{q="Varför är Thandol Span så strategiskt viktig?",a="Span är den enda landbron över den väldiga ravinen mellan Wetlands och Arathi Highlands. Om den förstörs förlorar Alliansen sin främsta landväg för förnödenheter mellan Ironforge, Stormwind och deras allierade som håller stånd i norra Lordaeron.",al={"varför är thandol span viktig","thandol spans historia"}},{q="Vad hände med Ebenezer Rustlocke?",a="Ebenezer Rustlocke var en försvarare från Ironforge som mördades i djupet under bron. Det var genom hans utredning och dokumenten som återfanns efter hans död som Rhag Garmason upptäckte Deepfurys gömda sprängämnesförråd.",al={"ebon rustlockes död","vem var rustlocke"}},{q="Var är sprängämnena gömda?",a="Sprängämnena gömdes i ett förråd strax över bron, på sidan mot Arathi Highlands, tillräckligt nära för att Deepfurys konspiratörer snabbt skulle kunna föra dem till den kvarvarande brokonstruktionen.",al={"sprängämnenas plats","var finns sprängämnena","förrådets plats"}},{q="Vem ger order om att förstöra sprängämnena?",a="Rhag Garmason, en dvärgofficer stationerad vid Thandol Span på Wetlands-sidan, ger order om att hitta och förstöra förrådet för att hedra Rustlockes offer och skydda den återstående bron.",al={"vem startar det här uppdraget","rhag garmason"}},{q="Vad händer efter att ammunitionen förstörts?",a="Det omedelbara sabotaget stoppas, men Rhag Garmason inser att hans garnison inte kan hålla den skadade bron hur länge som helst utan hjälp. I väntan på förstärkningar från Ironforge skickar han en vädjan om förstärkningar till Captain Nials i Alliansens läger vid Refuge Pointe i Arathi Highlands.",al={"vad händer efter thandol span","uppdraget vädjan till alliansen"}}},fx={a60c1dfd={q="Varför vill Rhag Garmason att sprängämnena förstörs?",a="Rhag Garmason fick veta genom Rustlockes återfunna pergament att Kam Deepfury planerade ännu en explosion med ett gömt förråd på andra sidan bron. En av Thandol Spans övergångar är redan söndersprängd. Om konspiratörerna bland Dark Iron lyckas spränga den återstående bron kommer den viktiga försörjningsvägen för Alliansen, som förbinder Khaz Modan med Lordaeron och Arathi Highlands, att kapas helt.",al={"rhag garmasons motiv","varför förstöra sprängämnena","varför förstöra sprängämnen vid thandol span"}},b9ac4adc={q="Varför skickar Rhag Garmason en äventyrare i stället för sina egna vakter?",a="Rhag och de få dvärgarna som försvarar brohuvudet är hårt pressade. De håller stånd mot fientliga angrepp medan de desperat väntar på förstärkningar. Ebenezer Rustlocke har redan fallit för konspiratörerna, och Rhag kan inte ta någon från linjen för att smyga över till fiendekontrollerat område i Arathi. Därför är du deras enda hopp om att avvärja katastrofen.",al={"varför jag","varför skicka mig","varför skickar inte rhag vakter"}}},fp="16,162,15.391.0,19.348.1,20.212.0,47.250.0,36.178.1,40.164.0,46.197.0,47.318.1"}
P.entries["quest:634"] = {n="Plea To The Alliance",s="Plea to the Alliance handlar om en desperat vädjan om förstärkningar från de överlevande dvärgförsvararna i Dun Modr, på andra sidan Thandol Span i Arathi. Efter att Dark Iron-infiltratörer massakrerat garnisonen söker dvärgarna hjälp från människostyrkorna vid Refuge Pointe, men får veta att Alliansen är hårt pressad.",h="Plea to the Alliance handlar om en desperat vädjan om förstärkningar från de överlevande dvärgförsvararna i...",kw={"arathi highlands","captain nials","dark iron","dun modr","longbraid","refuge pointe","rhag garmason","stromgarde","thandol span"},ang={["faction:Alliance"]="Mötet visar hur splittrad Alliansen fortfarande är i norra Eastern Kingdoms, där lokala garnisoner utkämpar varsin desperat strid utan gemensamma reserver.",["race:Dwarf"]="För dvärgar visar uppdraget hur smärtsamt isolerade nordliga garnisoner som Dun Modr är. Till och med gamla mänskliga allierade är för hårt ansatta för att kunna hjälpa till.",["race:Human"]="Mänskliga resenärer bevittnar Captain Nials bittra sorg. Han slits mellan att hedra Alliansens gemenskap och att kämpa för Stromgardes överlevnad."},sec={{t="Ett rop över klyftan",b="Efter förödelsen i Dun Modr och Dark Iron-dvärgarnas sabotage av Thandol Span håller de överlevande dvärgarna en osäker utpost vid norra kanten av Wetlands. Ironforges huvudstyrka har ännu inte anlänt, så Rhag Garmason och Longbraid the Grim blickar norrut mot Arathi Highlands. När Garmason får höra om ett alliansläger vid Refuge Pointe skickar han ett sändebud över den sönderslagna bron för att be Captain Nials om akut militär hjälp."},{t="Stromgardes nöd",b="När de når Refuge Pointe blir den bistra verkligheten för Alliansen i norr uppenbar. Captain Nials uttrycker sitt uppriktiga deltagande med Longbraids soldater, men kan inte avvara en enda krigare. Själva Stromgarde har fallit i ruiner, övermannat av Syndicate-rövare, Boulderfist-ogrer och Witherbark-troll. De överlevande försvararna från Stromgarde är helt upptagna med att återta sin förfäders huvudstad. Bunden av heder och sin egen desperata situation tvingas Nials skicka bud tillbaka om att dvärgarna vid bron måste klara sig själva."}},faq={{q="Vem skickar vädjan till Refuge Pointe?",a="Rhag Garmason, som är stationerad nära det förstörda brofästet vid Thandol Span på gränsen till Wetlands, skickar vädjan på Longbraid the Grims och resterna av Dun Modrs försvarares vägnar.",al={"vem framför vädjan till alliansen","rhag garmasons uppdrag","vem ber om hjälp"}},{q="Varför behöver dvärgarna hjälp från Refuge Pointe?",a="Dun Modr föll efter ett plötsligt och brutalt anfall av infiltratörer från Dark Iron-klanen, som också saboterade Thandol Span. De överlevande väntar på tunga förstärkningar från Ironforge, men är för få för att ensamma återta sin bosättning och säkra övergången.",al={"varför behövs hjälp från alliansen","varför be refuge pointe om hjälp","förstärkningar till dun modr"}},{q="Varför vägrar Captain Nials att skicka soldater?",a="Captain Nials kan inte avvara några trupper eftersom kungariket Stromgarde självt har fallit i ruiner. Människostyrkorna vid Refuge Pointe är helt upptagna med ett desperat fälttåg för att återta Stromgarde från Syndicate, ogres och skogstroll.",al={"varför hjälper inte nials","varför vägrar refuge pointe","captain nials svar"}},{q="Var ligger Refuge Pointe?",a="Refuge Pointe ligger strax vid sidan av huvudvägen i centrala Arathi Highlands, norr om övergången vid Thandol Span mellan Wetlands och Arathi.",al={"refuge pointes plats","var finns captain nials","hitta refuge pointe"}},{q="Vad hände med Dun Modr?",a="Dun Modr övermannades och plundrades av Dark Iron-klanen, som tog sig in genom bergen för att skära av landvägen mellan de södra dvärgaländerna och Alliansens nordliga områden.",al={"dun modrs historia","vad hände med dun modr","vem anföll dun modr"}},{q="Vad händer efter att Captain Nials avböjer begäran?",a="Captain Nials framför sina beklaganden till Longbraid the Grim och bekräftar att inga mänskliga förstärkningar kommer. De överlevande dvärgarna vid bron måste förlita sig på sitt eget förstånd, kringvandrande äventyrare och förstärkningar från det avlägsna Ironforge.",al={"vad händer efter plea to the alliance","uppdraget efter plea to the alliance","fortsättning på uppdragskedjan"}}},fx={["0e006c4d"]={q="Varför ber Rhag Garmason dig att överlämna vädjan i stället för att göra det själv?",a="Rhag Garmason och de överlevande bergsvakterna är fastlåsta när de försvarar sitt osäkra fäste vid Thandol Span. Dun Modr har fallit och Ironforges reserver är fortfarande långt borta, så de kan inte avvara en enda dvärg från vakttjänsten för att ta sig norrut genom farliga områden.",al={"varför jag ska framföra vädjan till alliansen","varför rhag skickar dig","varför kan inte rhag åka till refuge pointe"}}},fp="20,249,22.432.0,24.410.0,36.158.0,48.211.0,47.188.0,31.142.0,26.190.0,56.232.0"}
P.entries["quest:6341"] = {n="The Bounty of Teldrassil",s="The Bounty of Teldrassil är ett inledande ärende som Nessa Shadowsong ger i Rut'theran Village. Hon vill jämföra öfiskarnas ovanliga storlek och mängd med fiskarna som fångas längs fastlandet, och förbereder därför en samling ben och fjäll som ska skickas över sundet till Darkshore. När du lämnar paketet till byns hippogryffskötare tar du första steget mot Auberdine över havet.",h="The Bounty of Teldrassil är ett inledande ärende som Nessa Shadowsong ger i Rut'theran Village.",kw={"auberdine","bounty of teldrassil","darkshore","hippogryff","laird","nessa shadowsong","rut'theran village","vesprystus"},ang={["faction:Alliance"]="Rutten mellan Rut'theran och Auberdine är en viktig transportled som förbinder nattalvernas huvudstad med resten av norra Kalimdor.",["race:NightElf"]="För nattalvsresenärer markerar den här färden den traditionella vägen från Teldrassils trygga höjder ner till Darkshores skuggiga fastlandskust."},sec={{t="En fiskares undersökning",b="Under världsträdets väldiga grenar myllrar det av ovanligt stora och talrika havsdjur i de skyddade vattnen kring Rut'theran Village. Nessa Shadowsong ser hur lokala fiskare får upp rikliga fångster och vill ta reda på om denna livskraft också finns längs fastlandets urgamla kust, eller om den bara märks i vattnen som Teldrassil ger näring åt. För att pröva sin teori förbereder hon en samling fjäll och ben som ska undersökas av Laird, en annan fiskhandlare på andra sidan vattnet i Auberdine."},{t="Ordna resan",b="För att frakta last och resenärer över det öppna sundet mellan öns grenar och fastlandet Kalimdor krävs pålitliga vingar. I stället för att skicka paketet med en liten båt hänvisar Nessa resenärer direkt till Vesprystus, byns hippogryffmästare. När du lämnar samlingen till honom ordnar du resan på ett tränat riddjur, så att proverna kan levereras direkt till Darkshores hamn."}},faq={{q="Vad försöker Nessa undersöka?",a="Nessa Shadowsong märker att fiskarna i vattnen kring Rut'theran Village är ovanligt stora och talrika. Hon vill skicka prover av ben och fjäll över vattnet för att jämföra Teldrassils fångst med fiskarna längs Darkshores fastlandskust.",al={"nessas mål","varför jämföra fiskar","syftet med bounty of teldrassil"}},{q="Vem ska ta emot fiskproverna i Auberdine?",a="Samlingen är adresserad till Laird, en fiskhandlare i kustbyn Auberdine vid Darkshores fastlandskust.",al={"vem får nessas samling","laird i darkshore","fiskhandlare i auberdine"}},{q="Varför lämna paketet till Vesprystus i stället för att resa direkt till Auberdine?",a="Vesprystus är hippogryffmästaren i Rut'theran Village. När du lämnar samlingen till honom ordnar han direkt flygtransport, så att du kan få skjuts med en hippogryff över havet till Darkshore.",al={"varför vesprystus","vem är vesprystus","hippogryffmästare i rut'theran"}},{q="Var ligger Rut'theran Village i förhållande till Teldrassil?",a="Rut'theran Village ligger vid havsnivån, vid Teldrassils södra fot, och är förbundet med Darnassus genom en smaragdgrön portal. Det är den främsta kusthamnen och tillflyktsorten för skepp och hippogryffer som färdas till och från det väldiga trädet.",al={"rut'therans läge","var finns nessa shadowsong","hur man tar sig till rut'theran"}},{q="Vad händer efter att du lämnat samlingen till Vesprystus?",a="Vesprystus tar emot samlingen och erbjuder nästa uppdrag, Flight to Auberdine, som låter dig sväva över sundet på ryggen av en hippogryff direkt till Darkshore.",al={"nästa uppdrag flight to auberdine","efter bounty of teldrassil","vad gör vesprystus"}},{q="Är det här en del av att lämna Night Elves startområde?",a="Ja. Den här uppdragskedjan introducerar unga nattalvsäventyrare till flygrutter och leder dem från öns trädkrona ner till fastlandet Kalimdor, där de kan fortsätta sina resor i Darkshore.",al={"lämna teldrassil","nivå 10-uppdrag för nattalv","resa till darkshore"}}},fx={["4163d491"]={q="Varför behöver Nessa Shadowsong att du levererar samlingen?",a="Nessa Shadowsong sköter sina sysslor och sin forskning vid hamnen i Rut'theran Village. Resenärer lämnar ön regelbundet, så det är mycket enklare att ge hennes paket med prover till en kapabel äventyrare på väg mot Darkshore än att själv överge arbetet för att ordna transport över havet.",al={"varför jag ska hjälpa nessa","varför behöver nessa hjälp","varför skicka en äventyrare till vesprystus"}}},fp="24,191,19.308.0,17.203.0,36.189.0,47.81.0,77.158.0,62.199.0,55.128.0,58.152.0"}
P.entries["quest:6342"] = {n="Flight to Auberdine",s="Det här ärendet visar äventyrare som lämnar Teldrassil nattalvernas flygnätverk. Hippogryffmästaren Vesprystus i Rut'theran Village skickar dem över havet med ett paket ovanligt stora havsprover till Laird i Auberdine.",h="Det här ärendet visar äventyrare som lämnar Teldrassil nattalvernas flygnätverk.",kw={"auberdine","darkshore","flygrutt","flyg till auberdine","hippogryff","laird","nessa shadowsong","rut'theran village","teldrassil","vesprystus"},ang={["faction:Alliance"]="Hippogryffer utgör Alliansens främsta flygnätverk i norra Kalimdor och förbinder kustens utposter direkt med huvudstaden.",["race:NightElf"]="Att flyga hippogryff till Auberdine är en klassisk övergångsrit för unga kaldorei som lämnar Teldrassil och tar steget ut på det förfäders fastland."},sec={{t="Med vingar till Darkshore",b="För många unga äventyrare som lämnar Teldrassils grenar är Rut'theran Village gränsen mellan fristad och den större världen. En vanlig färja trafikerar sundet mellan öns trygga hamn och Kalimdors fastland, men nattalverna förlitar sig också på sina bundna hippogryffer. Med ett paket sällsynta fiskdelar från Nessa Shadowsong rider resenärerna på en av dessa bevingade bestar för att nå Darkshores kust längs sin allra första flygrutt."},{t="Märkliga fångster",b="Leveransen väcker stort intresse bland Darkshores fiskare. Laird väntar på Nessas fynd vid hamnen i Auberdine och granskar fångsten: där finns enorma fjäll stora som knytnävar och ett käkben nästan dubbelt så stort som exemplar från fastlandet. Vattnen kring Världsträdets fot tycks ge upphov till förändrade eller onormalt stora livsformer, en märklighet som antyder Teldrassils mäktiga och rastlösa natur."}},faq={{q="Vad är syftet med den här flygresan?",a="Resan ger en praktisk lektion i hur flygrutter mellan bosättningar hänger ihop och levererar samtidigt forskningsprover från ovanliga fiskar som fångats kring Rut'theran Village till Laird i Auberdine.",al={"varför flyger jag till auberdine","målet med uppdraget flyg till auberdine","varför flyga"}},{q="Vem skickar paketet, och vad innehåller det?",a="Paketet kommer från fiskarkvinnan Nessa Shadowsong. Det innehåller fiskprover från vattnen kring Rut'theran Village, däribland jättelika fjäll och ett ovanligt stort käkben.",al={"nessa's collection","vad finns i paketet","vem skickade paketet"}},{q="Varför är fiskarna från Teldrassil så stora?",a="Laird noterar att käkbenet är nästan dubbelt så stort som normalt och att fjällen är stora som en knytnäve. Vattnen runt Teldrassils Världsträd ger upphov till märkligt förstorade djur jämfört med dem vid Darkshores fastlandskust.",al={"varför är fiskarna stora","fiskarnas storlek i rut'theran","enorma fjäll"}},{q="Vem är Vesprystus?",a="Vesprystus är hippogryffmästaren i Rut'theran Village. Han tar hand om nattalvernas riddjur och samordnar flygresor över vattnet till Kalimdors fastland.",al={"vesprystus bakgrund","vem är hippogryffmästaren"}},{q="Vem är Laird?",a="Laird är en nattalvfiskare i Auberdine vid Darkshores kust. Han studerar det lokala vattenlivet och jämför fångster från fastlandet med dem som tas nära Teldrassil.",al={"lairds bakgrund","vem är laird","laird i darkshore"}},{q="Kan du resa mellan Rut'theran och Auberdine utan att flyga?",a="Ja. En reguljär färja går mellan bryggorna i Rut'theran Village och piren i Auberdine och erbjuder ett alternativ till hippogryffresan.",al={"båt till auberdine","färja till darkshore","annat sätt att ta sig till auberdine"}}},fx={ddbceafb={q="Varför skickar Vesprystus dig till Auberdine?",a="Som hippogryffmästare i Rut'theran Village ansvarar Vesprystus för viktiga resor mellan Teldrassil och Kalimdors fastland. Han har Nessas paket med ovanliga fiskprover, avsett för Laird i Auberdine, men hans främsta uppgift är att introducera resenärer till nattalvernas flygnätverk. Genom att skicka dig över vattnet på en hippogryffs rygg ser han till att du får kontakt med flygmästaren i Auberdine, så att du snabbt kan resa genom Darkshore under framtida färder.",al={"varför vill vesprystus att det här ska göras","vesprystus motiv","varför skicka paketet till auberdine"}}},fp="19,132,24.326.0,15.314.0,35.135.0,44.162.0,42.181.0,18.150.0,13.158.0,63.142.0"}
P.entries["quest:6343"] = {n="Return to Nessa",s="Det här uppdraget skickar unga resenärer från Auberdine tillbaka till Rut'theran Village med Lairds fynd till Nessa Shadowsong. Det avslutar ett introduktionsärende som lär äventyrare att resa mellan Kalimdors fastland och Teldrassil.",h="Det här uppdraget skickar unga resenärer från Auberdine tillbaka till Rut'theran Village med Lairds fynd till...",kw={"auberdine","caylais moonfeather","darkshore","laird","nessa shadowsong","åter till nessa","rut'theran village","teldrassil"},ang={["faction:Alliance"]="Auberdine och Rut'theran Village utgör en viktig sjöfartsport som förbinder norra Kalimdors nattalvboplatser med Alliansens vidare intressen i Azeroth.",["race:NightElf"]="För nattalver som för första gången lämnar Teldrassils grenar markerar det här utbytet deras första officiella ärende som knyter den nya öfristaden till Darkshores urgamla fastland."},sec={{t="Ett bud över havet",b="Efter att ha lämnat Nessa Shadowsongs första frågor till Laird i Auberdine får resenärerna i uppdrag att bära hans skriftliga iakttagelser tillbaka över vattnet. Laird ser stora skillnader mellan fiskfångsterna vid Darkshore och Teldrassils stränder och misstänker att själva världsträdet påverkar det lokala marina livet. För att ta sig tillbaka till Rut'theran Village kan äventyrarna antingen betala för en flygtur med hippogryffmästaren Caylais Moonfeather eller gå ombord på den reguljära färjan från Auberdines brygga."},{t="En märklig rikedom",b="När Nessa får Lairds svar i Rut'theran Village uttrycker hon sin fascination över de tydliga skillnaderna i det marina livet. Fiskarnas enorma storlek nära världsträdet ger lokala fiskare en omedelbar fördel, men bland Kaldorei är orsaken fortfarande en öppen fråga. Nessa beslutar sig för att dela fynden med sina bybor. Tills vidare nöjer hon sig med att skörda det rikliga havslivet och hålla noga uppsikt över vilka krafter som egentligen kan ligga bakom."}},faq={{q="Vem ger och tar emot uppdraget?",a="Uppdraget erbjuds av fiskaren Laird i Auberdine vid Darkshores kust. Det lämnas in till Nessa Shadowsong i Rut'theran Village, vid foten av Teldrassil.",al={"uppdragsgivare","var lämnar man in","vem ger uppdraget"}},{q="Vad är det snabbaste sättet tillbaka till Rut'theran Village?",a="Du kan antingen ta en snabb flygtur med hippogryff genom att tala med Caylais Moonfeather i Auberdine, eller gå ut på den långa bryggan och ta den reguljära passagerarfärjan tillbaka till hamnen i Rut'theran Village.",al={"hur tar man sig tillbaka","resa till rut'theran","färja eller hippogryff"}},{q="Varför studerar Laird fisken?",a="Laird märker att fångsterna i vattnen vid Darkshore skiljer sig kraftigt från dem kring Teldrassil. Han misstänker att världsträdets väldiga tillväxt och unika energier direkt påverkar det omgivande djurlivet.",al={"varför studera fisk","skillnad på fiskar","lairds svar och bakgrund"}},{q="Får Nessa reda på varför fiskarna är så märkliga?",a="Inte genast. Nessa lägger märke till den anmärkningsvärda skillnaden och håller med om att den bör undersökas närmare. Men tills vidare nöjer hon sig med att dela rapporten med byborna och njuta av de rikliga fångsterna.",al={"varför är fiskarna stora","teldrassils fiskmysterium"}},{q="Vad händer före det här uppdraget?",a="Det här uppdraget följer direkt efter 'Flight to Auberdine', där resenärer skickas från Rut'theran Village till Darkshore med Nessas ursprungliga brev till Laird.",al={"förutsättning","föregående uppdrag","flight to auberdine"}},{q="Vad är syftet med den här uppdragskedjan?",a="Förutom att introducera Teldrassils mystiska ekologiska påverkan på det lokala djurlivet fungerar den här leveranskedjan som en övergångsrit. Den lär unga nattalvsäventyrare att resa mellan sitt öhem och Kalimdors fastland med skepp och flygmästare.",al={"varför göra uppdraget","reseuppdrag"}}},fx={c6069b83={q="Varför vill Laird att det här brevet levereras till Nessa?",a="Laird vill att Nessa Shadowsong genast ska få veta hur dramatiskt det marina livet skiljer sig mellan Darkshores fastland och vattnen kring Teldrassil. Han misstänker att Teldrassil själv påverkar det omgivande djurlivet i havet på ett ovanligt sätt. Om han delar sina iakttagelser kan byborna förstå den märkliga rikedom de skördar.",al={"varför skicka svaret till nessa","syftet med lairds svar","varför vill laird att det här ska göras"}}},fp="15,182,26.346.0,16.385.0,36.137.0,51.151.0,31.187.0,48.205.0,29.130.0,40.204.0"}
P.entries["quest:6344"] = {n="Nessa Shadowsong",s="Nessa Shadowsong är ett introduktionsuppdrag som kurir, som Mydrannul erbjuder i Darnassus. Det leder nya äventyrare ner från Världsträdet till Rut'theran Village för att träffa fiskhandlaren Nessa Shadowsong. Uppdraget är det första steget som knyter samman huvudstaden i trädkronorna med stränderna och hamnarna nedanför.",h="Nessa Shadowsong är ett introduktionsuppdrag som kurir, som Mydrannul erbjuder i Darnassus.",kw={"auberdine","kurir","darkshore","darnassus","mydrannul","nessa shadowsong","portal","rut'theran village","the temple gardens"},ang={["faction:Alliance"]="Det här ärendet introducerar det viktiga logistiknätverk som knyter den avskilda ön Teldrassil till resten av Alliansens områden i Kalimdor.",["race:NightElf"]="För nattalvsäventyrare markerar resan den traditionella färden från Darnassus fridfulla höjder till de livliga kustleder som förbinder deras nya hem med Darkshores uråldriga stränder."},sec={{t="Ett ärende bortom trädkronorna",b="I Darnassus håller Mydrannul uppsikt över resenärer som söker arbete och mening. När fiskhandlaren Nessa Shadowsong behöver få ett paket levererat över havet till Darkshore, hänvisar Mydrannul dugliga kurirer till kusten. Många unga nattalver tillbringar sina första resor helt och hållet bland Teldrassils grenar, men det här enkla ärendet uppmuntrar dem att blicka ut mot fastlandet."},{t="Ner till kajerna",b="För att nå Rut'theran Village måste du gå genom stadens lysande portal i väster, nära The Temple Gardens. Porten leder ner genom Världsträdet till dess rötter vid havsytan, där fiskebryggor och hippogryffarens sittplatser förbinder Teldrassil med resten av Kalimdor. Där sköter Nessa Shadowsong sin handel och förbereder leveranser till hamnbosättningen Auberdine."}},faq={{q="Vem ger uppdraget?",a="Uppdraget erbjuds av Mydrannul, som finns i Warrior's Terrace i Darnassus.",al={"uppdragsgivare","var får man uppdraget nessa shadowsong","mydrannuls plats"}},{q="Hur tar jag mig till Rut'theran Village?",a="Gå västerut från The Temple Gardens i Darnassus. Gå genom den stora, lysande trädportalen för att genast förflyttas ner till Rut'theran Village vid foten av Teldrassil.",al={"hur tar man sig till rut'theran","rut'therans portal","lämna darnassus"}},{q="Vem är Nessa Shadowsong?",a="Nessa Shadowsong är en alvisk fiskleverantör som håller till vid kajerna i Rut'theran Village. Hon ansvarar för varor och paket som färdas mellan Teldrassil och fastlandet i Darkshore.",al={"nessa shadowsongs roll","vad gör nessa","nessa shadowsong npc"}},{q="Vart leder den här uppdragskedjan?",a="När du talar med Nessa fortsätter du direkt till 'The Bounty of Teldrassil', som introducerar äventyrare för flygmästaren och ger dem deras första flygtur över vattnet till Auberdine.",al={"vad kommer efter nessa shadowsong","nästa uppdrag i kedjan","teldrassils flyguppdragskedja"}},{q="Är Nessa släkt med Maiev Shadowsong?",a="De delar efternamnet Shadowsong, men det finns inga uppgifter om någon personlig koppling mellan Nessa, en enkel fiskhandlare vid kajen, och den legendariska väktaren Maiev Shadowsong.",al={"nessas relation till maiev","shadowsong-släkten","är nessa släkt med maiev"}},{q="Varför är det här ärendet viktigt för unga äventyrare?",a="Det fungerar som en vägvisare som lär nya hjältar att lämna Teldrassils krona, upptäcka kajerna nedanför och använda hippogryffernas flygrutter för att nå fastlandet i Kalimdor.",al={"varför göra uppdraget","uppdragets betydelse"}}},fx={feb9b9a4={q="Varför vill Mydrannul att det här ska göras?",a="Mydrannul gör helt enkelt en vän en tjänst. Nessa Shadowsong arbetar i Rut'theran Village som leverantör av fisk och behöver en pålitlig kurir som kan föra ett paket över havet till Darkshore. Från sin post i Darnassus håller Mydrannul utkik efter dugliga resenärer som är villiga att färdas nerför grenarna och hjälpa henne.",al={"varför hjälpa nessa","mydrannuls skäl","varför skicka till nessa shadowsong"}}},fp="16,189,26.330.0,23.299.0,22.69.0,35.149.0,24.147.0,33.151.0,37.169.0,51.154.0"}
P.entries["quest:635"] = {n="Crystal in the Mountains",s="Pendant of Myzrael pulserar i din hand och du känner en vädjan, som om någon desperat behöver hjälp. En syn visar en glänsande kristall som reser sig ur marken i Arathis norra berg, och du känner dig dragen dit.",h="Pendant of Myzrael pulserar i din hand och du känner en vädjan, som om någon desperat behöver hjälp.",kw={"arathi highlands","kristall","kristall i bergen","pendant of myzrael","myzraels skärvor","syn"},sec={{t="En tyst vädjan",b="Smycket pulserar när du håller det. Från det kommer en vädjan, som om någon försöker nå dig och verkligen behöver din hjälp. Sedan öppnar sig en syn framför dig: bergen i norra Arathi och en glänsande kristall som skjuter upp ur marken. Du känner dig dragen dit."},{t="Vid kristallen",b="När du hittar kristallen pulserar den, som om en levande kraft vore fångad inuti den."}},faq={{q="Vad sätter igång den här färden?",a="Den börjar med Pendant of Myzrael. När du håller det pulserar det, och du känner en vädjan från någon som desperat behöver din hjälp.",al={"hur får man tag på kristallen i bergen","varifrån kommer pendant of myzrael","start på kristall i bergen"}},{q="Vart leder synen?",a="Den leder till en glänsande kristall i Arathis norra berg, och du känner dig dragen dit.",al={"var finns kristallen","kristall i bergen plats","hitta kristallen från synen"}}},fp="24,152,13.210.0,14.68.1,25.121.0,27.96.0"}
P.entries["quest:6361"] = {n="A Bundle of Hides",s="Jahan Hawkwing skickar garvade hudar från The Crossroads till Thunder Bluff för läderarbete. Leveransen tar dig genom centrala Kalimdor och visar dig vindryttarnas rastplats vid The Crossroads.",h="Jahan Hawkwing skickar garvade hudar från The Crossroads till Thunder Bluff för läderarbete.",kw={"ahanu","bundle of hides","the crossroads","devrak","jahan hawkwing","läderarbete","the barrens","thunder bluff","vindryttare"},ang={["faction:Horde"]="Som medlem av Horden är du beroende av förbindelserna mellan Kalimdors baser. Orkiska bestmästare som Devrak hjälper till att överbrygga avstånden mellan allierade områden.",["race:Tauren"]="Som taurenresenär bär du hudar mellan jägarna i The Barrens, taurenernas förfäders land, och hantverkarna på Thunder Bluffs väldiga platåer."},sec={{t="Handel över savannen",b="Jägare tar med viltets hudar och kött till The Crossroads, där Jahan Hawkwing samlar skinn från hela The Barrens. Utposterna kan inte bereda alla obehandlade hudar, så han ber resenärer att bära dem västerut till Thunder Bluff. Där kan mästerläderarbetare förvandla skinnen till utrustning åt Horden."},{t="Upp i skyn",b="Stigen genom The Barrens och in i Mulgore är oländig, och quilboar och rovdjur hotar alla som bär last till fots. Jahan skickar dig till Devrak, vindryttarmästaren vid The Crossroads. Han kan frakta godset med flyg på en tränad wyvern och knyta samman Hordens utspridda bosättningar."}},faq={{q="Vem ger uppdraget A Bundle of Hides?",a="Jahan Hawkwing, en tauren vid The Crossroads i The Barrens, ger dig hudarna att bära. Han har samlat skinn från lokala bestar och behöver en pålitlig kurir som kan föra dem mot Thunder Bluff.",al={"uppdragsgivare","vem startar a bundle of hides","var får man bundle of hides"}},{q="Vem ska jag lämna hudbunten till?",a="Lämna bunten till Devrak, orchen som är vindryttarmästare vid The Crossroads utsiktspunkt. Han sköter flygresor mellan The Crossroads och andra större knutpunkter för Horden.",al={"lämna in till npc","var lämnar man hudarna","vem ska jag prata med"}},{q="Vad händer när jag lämnar hudarna till Devrak?",a="När du har gett Devrak hudarna ber han dig ta en vindryttare och flyga lasten till Ahanu, läderarbetaren högst upp på Thunder Bluffs höga klippor.",al={"nästa uppdrag","vad händer efter a bundle of hides","uppföljande uppdrag"}},{q="Varför skickas hudarna till Thunder Bluff?",a="Jahan Hawkwing samarbetar med Ahanu i Thunder Bluff, som förvandlar skinn från vilt i The Barrens till läderrustningar och varor åt taurenerna och deras allierade i Horden.",al={"varför thunder bluff","ahanu hudar","vad används hudar till"}},{q="Varför använda en vindryttare i stället för att gå?",a="Det tar tid och innebär risker att gå genom The Barrens och klättra upp på Thunder Bluffs väldiga platå, där vilda djur och quilboarflockar utgör ett hot. En vindryttare för dig snabbt ovanför dem.",al={"varför flyga till thunder bluff","resa med vindryttare"}},{q="Krävs tidigare erfarenhet av flygmästare?",a="Du får lära dig att använda flygmästarsystemet under den här tidiga leveransen. Devraks rastplats visar hur vindryttare förbinder avlägsna regioner.",al={"krav för flygrutt","behöver jag en flygrutt"}}},fx={["2d6b34f1"]={q="Varför ber Jahan Hawkwing en äventyrare att leverera skinnen?",a="Jahan Hawkwing är stationerad vid The Crossroads för att stötta samhällets handel och hantverk. I stället för att överge sin post och själv göra den långa färden över slätterna till Mulgore förlitar han sig på resande äventyrare som kan frakta varor och knyta samman de lokala jägarna med hantverkarna i Thunder Bluff.",al={"varför be mig om bundle of hides","varför behöver jahan min hjälp","varför kan inte jahan hawkwing leverera skinnen"}}},fp="17,197,24.271.0,19.282.0,38.189.0,42.150.0,46.147.0,48.153.0,40.187.0,49.133.0"}
P.entries["quest:6362"] = {n="Ride to Thunder Bluff",s="Det här uppdraget låter unga Horde-äventyrare göra sin första flygtur över Kalimdor på en vindryttare. Med en sändning garvade hudar i sin vård färdas de från The Barrens torra vägskäl för att leverera värdefulla lädervaror direkt till Thunder Bluffs höjder.",h="Det här uppdraget låter unga Horde-äventyrare göra sin första flygtur över Kalimdor på en vindryttare.",kw={"ahanu","the barrens","bundle of hides","the crossroads","devrak","hewa's armory","ride to thunder bluff","vindryttare"},ang={["faction:Horde"]="Pålitliga flygresor med vindryttare är avgörande för att knyta samman The Barrens avlägsna utposter med Hordens viktigaste fästen i Durotar och Mulgore.",["race:Tauren"]="För unga taurer som återvänder från The Barrens innebär flygturen en enkel färd rakt upp till deras folks ståtliga huvudstad."},sec={{t="Vingar över savannen",b="För många som färdas genom The Barrens blir flygturen med Devrak den första resan genom skyn på ryggen av en vindryttare. Dessa bevingade wyverner förbinder den unga Hordes utspridda bosättningar och låter resenärer slippa de farliga vägarna där quilboarer och centaurflockar stryker omkring."},{t="Hudar till vapenkammaren",b="Sändningen består av ett knippe garvade hudar från The Barrens, avsett för Ahanu, en hantverkare vid Hewa's Armory i Thunder Bluff. Ahanu håller till alldeles under den stora vindryttarhålan på den centrala platån. Han behöver råmaterial från jaktläger ute på slätterna för att utrusta traktens krigare och jägare."}},faq={{q="Vem ger uppdraget Ride to Thunder Bluff?",a="Devrak, vindryttarmästaren vid The Crossroads i The Barrens, ger resenärer uppdraget när de har samlat ihop ett knippe hudar.",al={"uppdragsgivare","var börjar ride to thunder bluff","devraks plats"}},{q="Vem är Ahanu och var finns han?",a="Ahanu är en taurenhantverkare vid Hewa's Armory i Thunder Bluff, alldeles intill foten av stadens vindryttarhåla.",al={"var finns ahanu","ahanus plats","hewa's armory"}},{q="Vad transporteras i den här leveransen?",a="Du bär på ett knippe beredda hudar från The Barrens. Ahanu ska genast använda dem till läderarbete och rustningstillverkning.",al={"vad ska jag leverera","bundle of hides"}},{q="Varför använda vindryttare i stället för att gå?",a="Vindryttare flyger raka vägen över The Barrens till Thunder Bluffs höga platåer. De slipper den längre färden till fots genom Mulgore och landar vid stadens vindryttartorn.",al={"varför flyga till thunder bluff","fördelar med flygrutter"}},{q="Var börjar den här leveranskedjan?",a="Leveransen börjar hos Jahan Hawkwing vid The Crossroads, som ordnar knippet garvade hudar i det föregående uppdraget, A Bundle of Hides.",al={"föregående uppdrag","uppdragskedjan med hudar"}},{q="Vad händer efter att hudarna har levererats?",a="När Ahanu har tagit emot hudarna visar han resenärerna uppför trappan, där de får tala direkt med Tal, Thunder Bluffs vindryttarmästare.",al={"nästa uppdrag","fortsättning på ride to thunder bluff"}}},fx={ae176b23={q="Varför skickar Devrak dig med skinnen till Thunder Bluff?",a="Som flygmästare vid Crossroads sköter Devrak vindryttarna som förbinder Hordens skilda bosättningar i Kalimdor. När en kurir anländer med ett brådskande paket skinn till Ahanu i Thunder Bluff är det Devraks uppgift att ordna en snabb resa och visa resenärer vägen när de landar på de höga mesorna.",al={"varför vill devrak att det här ska göras","devraks motiv","varför skicka bundle of hides"}},["1fe41edb"]={q="Varför behöver Devrak att du levererar skinnen i stället för att göra det själv?",a="Devrak måste stanna vid sin post på Crossroads flygplats, där han håller uppsikt över vindryttarna och tar hand om resenärer som anländer till och lämnar centrala Kalimdor. Han kan inte överge sina plikter för att uträtta ärenden i Mulgore, så en villig resenär som redan är på väg dit är det naturliga valet för leveransen.",al={"varför levererar inte devrak själv","varför devrak skickar mig","varför devrak behöver en resenär"}}},fp="21,147,25.248.0,20.256.0,42.107.0,39.110.0,43.90.0,39.156.0,37.126.0,43.107.0"}
P.entries["quest:6363"] = {n="Tal the Wind Rider Master",s="Tal, flygmästaren, sköter ett enkelt budärende mellan läderarbetare i Mulgore och köpmän i The Barrens. Läderarbetaren Ahanu anförtror ett paket färdigberedda hudar åt flygtransport från Thunder Bluff. När du lämnar det direkt till Tal, platåns flygmästare, får Hordens nya resenärer bekanta sig med vindryttarnas transportnät.",h="Tal, flygmästaren, sköter ett enkelt budärende mellan läderarbetare i Mulgore och köpmän i The Barrens.",kw={"ahanu","the crossroads","devrak","flygmästare","jahan","lädervaror","tal","thunder bluff","vindryttare"},ang={["faction:Horde"]="Stabila flygrutter mellan The Barrens och Thunder Bluff gör att förstärkningar, handelsvaror och meddelanden snabbt kan färdas genom centrala Kalimdor.",["race:Tauren"]="Vindryttarna som häckar på Thunder Bluffs klippor är en livsviktig länk som knyter Cairne Bloodhoofs isolerade folk till Hordens större allians."},sec={{t="Varor till The Crossroads",b="Handeln mellan Mulgore och The Barrens torra buskmarker är avgörande för den unga Horden. Ahanu, en läderarbetare som säljer sina varor på Thunder Bluffs nedre platå, tillverkar hållbara lädervaror för Jahan Hawkwings handelsstånd vid The Crossroads. Eftersom det tar flera timmar att gå nerför klipporna och genom The Golden Plains förlitar sig köpmännen på bevingade budbärare som snabbt kan föra ömtåliga eller brådskande paket över den klippiga bergsryggen."},{t="Platåns flygmästare",b="Tal sitter högst upp på Thunder Bluffs centrala platå och tar hand om stadens vindryttare, som också kallas wyverner. Dessa intelligenta bestar med läderartade vingar är väl lämpade för Kalimdors oförutsägbara uppvindar och karga bergstoppar. Tal samordnar flygningar till utposter som The Crossroads, så att budbärare och last snabbt kan färdas mellan taurenfolkets huvudstad och deras allierade orcher."}},faq={{q="Vem är Tal?",a="Tal är Thunder Bluffs flygmästare och ansvarar för vindryttarnas näste på den centrala platån. Han sköter flygtransporter för resenärer och budbärare som ska till The Barrens och vidare.",al={"vem är tal","tal thunder bluff","vindryttarmästaren tal"}},{q="Vem är Ahanu?",a="Ahanu är en taurenhantverkare som arbetar med läder och bor i Thunder Bluff. Han tillverkar lädervaror i större mängder och packar dem för att förse försäljare vid utposter runt om i Kalimdor, däribland Jahan Hawkwing vid The Crossroads.",al={"ahanu","vem är ahanu","ahanu thunder bluff"}},{q="Varför ska varorna till The Crossroads?",a="The Crossroads är en viktig knutpunkt för handel och militär verksamhet i The Barrens. Varor som hudar och läderkläder tillverkas i Mulgore, där det råder lugn och trygghet, och skickas dit för att förse resenärer, jägare och Hordens patruller.",al={"varför the crossroads","lädervaror the crossroads","jahan läder"}},{q="Kan jag flyga direkt till The Crossroads med paketet?",a="Du kan bara flyga till The Crossroads om du redan har besökt bosättningen och fått kontakt med Devrak, deras lokala vindryttarmästare. Om du inte har låst upp rutten än måste du ta dig dit till fots.",al={"kan jag flyga till the crossroads","tals flygrutt","hur flyger man till the crossroads"}},{q="Vad är vindryttare?",a="Vindryttare, som ofta kallas wyverner, är kännande, giftiga bevingade rovdjur som hör hemma bland Kalimdors klippor. De har varit Hordens allierade sedan det tredje kriget och tjänar som fraktionens främsta flygdjur.",al={"wyverner","vad är en vindryttare","taurenfolkets riddjur"}},{q="Vart leder budärendet sedan?",a="När du har lämnat varorna till Tal ber han dig skaffa ett riddjur och föra Ahanus paket över slätterna till Jahan Hawkwing, som väntar vid The Crossroads.",al={"nästa uppdrag","vad händer efter tal","vart ska lädervarorna"}}},fx={["989dcaf5"]={q="Varför vill Ahanu att det här ska göras?",a="Ahanu har tillverkat ett parti färdiga lädervaror åt Jahan, en köpman som bedriver handel från Crossroads i The Barrens. För att hålla handeln mellan Mulgore och Hordens övriga områden igång förlitar sig hantverkare som Ahanu på pålitliga kurirer och vindryttare som kan frakta varorna över det karga landskapet.",al={"ahanus motiv","varför skicka lädervarorna","leverans från ahanu till jahan"}}},fp="25,184,27.301.0,26.302.0,11.155.0,13.153.0,46.173.0,54.155.0,21.193.0,41.131.0"}
P.entries["quest:6364"] = {n="Return to Jahan",s="Återvänd till Jahan markerar den sista delen av en introduktion till Hordens nätverk av vindryttarfärder mellan Mulgore och The Barrens. Efter ett besök i Thunder Bluff för att lämna hudar till garvaren Ahanu tar resenärer en wyvern tillbaka till The Crossroads med färdiga lädervaror till köpmannen Jahan Hawkwing.",h="Återvänd till Jahan markerar den sista delen av en introduktion till Hordens nätverk av vindryttarfärder...",kw={"ahanu","the barrens","the crossroads","devrak","jahan hawkwing","tal","thunder bluff","vindryttare"},ang={["faction:Horde"]="Vindryttarlederna mellan Mulgore, Durotar och The Barrens är livsviktiga artärer som binder samman Hordens områden i centrala Kalimdor.",["race:Tauren"]="Handelskedjorna mellan garvare i Mulgore och utposter i The Barrens visar hur de förenade stammarna stödjer Hordens större expansion mot gränsområdena."},sec={{t="Vingar över Kalimdor",b="För många resenärer är detta ärende deras första färd genom luften på en tränad vindryttare. Tal, vindryttarmästaren som sitter högt uppe på Thunder Bluffs centrala mesa, ordnar färder över centrala Kalimdors slätter. Så länge en resenär redan har fått kontakt med en rastplats vid en annan bosättning, till exempel Devraks utpost vid The Crossroads, kan dessa bevingade bestar enkelt tillryggalägga sträckor som annars skulle kräva en farlig vandring genom Red Rocks och norra The Barrens."},{t="Handel vid The Crossroads",b="Kurirfärden fyller även ett ekonomiskt syfte vid sidan av flygträningen. Jahan Hawkwing verkar från den livliga bosättningen The Crossroads, där jägare, spejare och legosoldater samlas varje dag. Råhudar som skickas till Ahanu på Thunder Bluffs höga höjder förädlas till slitstark rustning och utrustning, och flygs sedan tillbaka till The Barrens dammiga vägskäl för att förse Hordens växande gränsområden."}},faq={{q="Vem är Jahan Hawkwing?",a="Jahan Hawkwing är en taurenköpman som håller till vid The Crossroads i The Barrens. Han köper och säljer lädervaror och förlitar sig på hantverkare i Thunder Bluff som förvandlar råa djurhudar till värdefull utrustning åt äventyrare på resa.",al={"jahan","jahan hawkwing berättelse","vem är jahan"}},{q="Varför måste jag rida tillbaka till The Crossroads?",a="Färden visar hur flygnätverket fungerar. Vindryttarmästare som Tal i Thunder Bluff kan bara skicka kurirer och passagerare till bosättningar som de själva har utforskat eller knutit kontakt med, till exempel Devraks rastplats vid The Crossroads.",al={"varför flyga tillbaka","återresa med vindryttare","hur fungerar flygleder"}},{q="Vem är Ahanu?",a="Ahanu är en skicklig läderarbetare och garvare på Thunder Bluffs höga klippor. Han tar emot råhudar som skickats från jägare i The Barrens och tillverkar färdiga varor som sedan skickas tillbaka för försäljning.",al={"ahanu","ahanu thunder bluff","vem tillverkade varorna"}},{q="Vem är Devrak?",a="Devrak är den orciska vindryttarmästaren vid The Crossroads. Han sköter rastplatsen som förbinder The Barrens med Hordens främsta fästen, som Orgrimmar och Thunder Bluff.",al={"devrak","flygmästare vid the crossroads","vindryttarmästaren devrak"}},{q="Kan man använda en vindryttare utan att först tala med mästaren på destinationen?",a="Nej. Vindryttare kan bara skickas till utposter där en resenär redan har träffat och registrerat sig hos den lokala vindryttarmästaren, så att förbindelsen mellan rastplatserna upprättas.",al={"regler för flygleder","låsa upp flygmästare","kan jag flyga vart som helst"}},{q="Vad händer efter att lädervarorna har lämnats till Jahan?",a="När de färdiga varorna levereras avslutas kurirkedjan mellan Mulgore och The Barrens. Resenärerna har då fått lära sig hur flygtransporter fungerar och kan fortsätta hjälpa garnisonen och köpmännen vid The Crossroads.",al={"fortsättning på uppdraget","vad händer sedan","efter återkomsten till jahan"}}},fx={["65054dbe"]={q="Varför vill Tal att lädervarorna återlämnas till Jahan?",a="Som vindryttarmästare i Thunder Bluff ansvarar Tal för flygresor mellan mesan och utposter som Crossroads. När du skickas tillbaka på ett riddjur med Ahanus färdiga lädervaror visar det hur effektiva vindryttarna är och slutför handelsvägen mellan hantverkarna på höjderna och Jahan Hawkwing, vars butik blomstrar nedanför.",al={"varför vill tal att det här ska göras","tals motiv","varför skicka läder till jahan"}}},fp="15,235,19.426.0,26.330.0,22.167.0,58.223.0,13.174.0,14.161.0,74.111.0,56.192.0"}
P.entries["quest:6365"] = {n="Meats to Orgrimmar",s="Vid The Crossroads skickar Zargh ett paket kött från The Barrens mot Orgrimmar. Han ber unga orcher och troll på äventyr att bära det till Devrak, vindryttarmästaren, och lära sig flygrutten till hordens huvudstad.",h="Vid The Crossroads skickar Zargh ett paket kött från The Barrens mot Orgrimmar.",kw={"the barrens","the crossroads","devrak","flygmästare","gryshka","köttleverans","orgrimmar","vindryttare","zargh"},ang={["profession:Cooking"]="Som kock hjälper du till att föra färska köttbitar från The Barrens till Gryshkas värdshus i Orgrimmar och hålla huvudstadens grytor fyllda åt besökande krigare.",["race:Orc"]="Som ork lämnar du Durotar för att jaga i The Barrens. Du kan leverera Zarghs paket och skapa en flygrutt rakt tillbaka till krigshövdingens huvudstad.",["race:Troll"]="Som Darkspear-troll vid The Crossroads hjälper du till att knyta de växande utposterna i vildmarken till Orgrimmars försörjningslinjer."},sec={{t="Färskt viltkött från The Barrens",b="Vilda djur fyller The Barrens, från zhevras och slättlöpare till kodos och åsködlor. Zargh har valt ut fina köttbitar för en personlig leverans till Gryshka, värdshusvärden i Orgrimmars Valley of Strength. I stället för att riskera den långa, dammiga färden över Southfury River till Durotar skickar han bud från The Crossroads till vindryttarnas avsats."},{t="Vingar över stäppen",b="Mötet med Devrak ger en ung krigare i Horden en första inblick i vindryttarnas flygnätverk. Vindryttarmästare förbinder avlägsna utposter som The Crossroads med hordens befästa maktcentrum i Orgrimmar. Devrak förbereder dig och lasten för en snabb flygtur över savannen."}},faq={{q="Vem skickar Zargh köttet till?",a="Zargh skickar köttet till sin vän Gryshka, värdshusvärden i Orgrimmars Valley of Strength.",al={"vem får köttet","vem är köttet till","zarghs köttmottagare"}},{q="Varför kan bara orcher och troll ta uppdraget?",a="Den här flygintroduktionen knyter samman orcher och Darkspear Trolls med deras gemensamma huvudstad, Orgrimmar. Taurer hänvisas till Thunder Bluff genom A Bundle of Hides, medan de Fördömda skickas till Silverpine Forest genom Supplying the Sepulcher.",al={"varför kan inte taurener ta uppdraget","köttuppdrag för odöda","rasbegränsning"}},{q="Vem är Devrak?",a="Devrak är en orkisk vindryttarmästare som är stationerad vid The Crossroads i The Barrens. Han ansvarar för wyvernerna som transporterar meddelanden, förnödenheter och resenärer genom Kalimdor.",al={"devrak vid the crossroads","vem är devrak"}},{q="Vad händer när man lämnar köttet till Devrak?",a="Devrak tar emot sändningen och ordnar en vindryttarfärd som för dig och köttet till Orgrimmars Skytower. Sedan levererar du det till Gryshka på hennes värdshus genom Ride to Orgrimmar.",al={"nästa uppdrag efter meats to orgrimmar","vad gör devrak"}},{q="Var finns Zargh?",a="Zargh håller till vid The Crossroads, Hordens centrala handelsplats vid huvudkorsningen i The Barrens.",al={"zarghs plats","var finns zargh"}},{q="Varför använda en vindryttare i stället för att gå?",a="Vindryttare för resenärer snabbt över det karga The Barrens och över flodravinen in i Durotar, så att ömtålig last som färskt kött når Orgrimmar innan den blir dålig.",al={"varför flyga till orgrimmar","vindryttare och kött"}}},fx={["50e2b3bf"]={q="Varför vill Zargh att köttet levereras?",a="Zargh har fått tag i några fina köttstycken och vill helt enkelt skicka dem som gåva till sin vän Gryshka, värdshusvärden på Orgrimmars centrala värdshus. Färskt kött blir snabbt dåligt i den obarmhärtiga solen över The Barrens och Durotar, så det är viktigt för honom att styckena snabbt hamnar i kunniga händer.",al={"varför skicka kött","zarghs motiv","varför zargh skickar köttstycken"}},["0b0a203b"]={q="Varför behöver Zargh dig i stället för att leverera köttet själv?",a="Zargh har sina egna plikter vid sin post på Crossroads och kan inte bara överge dem för att resa tillbaka genom Durotar. I stället för att lämna sina sysslor förlitar han sig på lovande Horderesenärer som är på väg mot huvudstaden och kan leverera paketen med det lokala vindryttarnätverket.",al={"varför gör inte zargh det själv","varför ber zargh mig","varför skicka en äventyrare"}}},fp="18,191,27.318.0,22.258.0,34.97.0,45.227.0,14.155.0,45.175.0,23.92.0,40.149.0"}
P.entries["quest:637"] = {n="Sully Balloo's Letter",s="Brevet från den drunknade skelettkroppen under Thandol Spans sönderslagna valv innehåller de sista orden från en döende dvärgsoldat vid namn Sully Balloo. Det är adresserat till hans hustru Sara i Ironforge och bär på de sista tankarna från en försvarare som gick förlorad i flodens iskalla vatten under striderna om bron.",h="Brevet från den drunknade skelettkroppen under Thandol Spans sönderslagna valv innehåller de sista orden från...",kw={"arathi","dvärgsoldat","ironforge","sara balloo","skelett","sully balloo","thandol span","vattenskadat kuvert","wetlands"},ang={["faction:Alliance"]="Brevet är en gripande påminnelse om de vanliga frontsoldaternas personliga uppoffringar när de skyddar de bräckliga landförbindelserna mellan Alliances södra och norra territorier.",["race:Dwarf"]="För Ironforges dvärgar hedrar Sullys sista ord en vapenbroder som gav sitt liv för att försvara dvärgarnas storslagna stenbyggen mot hoten från norr."},sec={{t="En röst från flodbottnen",b="Under de massiva stenpelarna som bär upp Thandol Span, den viktiga landbron mellan Wetlands och Arathi Highlands, ligger en fallen dvärgs drunknade skelett. I hans beniga grepp finns fortfarande ett vattenskadat kuvert som knappt tål att hanteras. Sidorna skrevs med stor omsorg mitt i stridens lågor och inleds med den ömsinta frasen ”Min kära Sara ...”, som bevarar soldatens röst långt efter att tidvattnet tog honom."},{t="Priset för bron",b="Thandol Span har sett hårda strider mellan Alliance-styrkor och deras fiender, från Dark Iron-sabotörer till plundrande krigarskaror som gör anspråk på gränslandet. Sully Balloo var en av de många dvärgsoldater som skickades norrut för att försvara den livsviktiga farleden. När han omkom under vågorna förblev hans öde okänt för familjen i bergen, tills en dykare till slut bärgade hans avskedsbrev."},{t="En änka i Ironforge",b="När det bärgade brevet återlämnas till Ironforge drabbas Sully Balloos änka, Sara Balloo, av en stilla förtvivlan. I den livliga dvärgstadens salar hade hon varit fast mellan sorg och ett svagt hopp, osäker på om hennes make saknades i strid eller var förlorad för alltid. När hon får se hans handskrivna ord och får veta var han vilar i vattnet tvingas hon till slut möta den bittra verkligheten om hans död."}},faq={{q="Var hittas Sully Balloos brev?",a="Brevet hålls i handen på ett nedsänkt skelett som vilar djupt på flodbottnen, direkt under Thandol Spans massiva stenpelare, som förbinder Wetlands och Arathi Highlands.",al={"brevets plats","var är sully balloo","skelett vid thandol span"}},{q="Vem var Sully Balloo?",a="Sully Balloo var en dvärgsoldat i Alliance som stupade när han försvarade Thandol Span. Innan han tog vakten vid bron skrev han ett avskedsbrev till sin hustru Sara. Brevet hittades i hans kvarlevors grepp under det iskalla vattnet.",al={"vem är sully","sully balloos historia","vem var sully balloo"}},{q="Vem är Sara Balloo?",a="Sara Balloo är Sullys änka och bor i Ironforge, dvärgarnas stora huvudstad. I månader har hon väntat på nyheter om sin makes öde vid den norra gränsen.",al={"var är sara balloo","vem är sara","sara balloos plats"}},{q="Vad händer när du lämnar över brevet?",a="När Sara Balloo får det hjärtskärande beskedet om Sullys död överväldigas hon av sorg och ber att han ska hedras med ett minnesmärke. Berättelsen fortsätter med en efterföljande begäran i Ironforge.",al={"vad händer sedan","sullys uppdragskedja","efter att brevet lämnats över"}},{q="Varför var brevet fortfarande intakt under vattnet?",a="Brevet skyddades inuti ett kuvert som soldaten höll hårt i sina kvarlevor. När det bärgas är det delvis upplöst och vattenskadat, men flera sidor med omsorgsfull handstil är fortfarande läsliga.",al={"varför går brevet att läsa","hur överlevde kuvertet"}},{q="Vilken verklig händelse inspirerade det här uppdraget?",a="Uppdraget är en hyllning till major Sullivan Ballou i 2nd Rhode Island Infantry under det amerikanska inbördeskriget. Kort före sin död vid det första slaget vid Bull Run skrev han ett berömt och poetiskt avskedsbrev till sin hustru.",al={"kuriosa om sully balloo","sullivan ballou","referens till inbördeskriget"}}},fp="21,147,25.270.0,21.357.0,20.258.1,37.154.0,21.223.0,19.136.0,42.132.1,43.207.0,49.216.0"}
P.entries["quest:638"] = {n="Trollbane",s="Vol'jin har beordrat Darkspear Trolls att återta det uråldriga svärdet Trol'kalar från det förstörda människoriket Stromgarde. Efter kung Thoras Trollbanes fall är det tänkt att klingan ska tjäna horden i framtida konflikter mot trollen i Zul'Gurub.",h="Vol'jin har beordrat Darkspear Trolls att återta det uråldriga svärdet Trol'kalar från det förstörda...",kw={"hammerfall","nimboya","stromgarde","trol'kalar","trollbane","vol'jin","zengu","zul'gurub"},ang={["faction:Horde"]="Hordens jägare Zengu väntar i Hammerfall på att det legendariska svärdet ska tas från människorna.",["race:Troll"]="Vol'jin vill särskilt åt Trol'kalar för att beväpna Darkspear Trolls mot deras uråldriga fränder i Zul'Gurub."},sec={{t="En fallen kung, ett eftertraktat svärd",b="Efter kung Thoras Trollbanes död och Stromgardes fall i ruiner har hövding Vol'jin beordrat att allt ska göras för att föra bort Trol'kalar. Denna berömda klinga har länge varit i människornas händer, men Darkspear Trolls hoppas kunna ta den i anspråk inför de förestående striderna mot djungeltrollen i Zul'Gurub."},{t="Res till Hammerfall",b="För att utföra Vol'jins order skickades en erfaren jägare vid namn Zengu till hordens utpost Hammerfall, belägen i den nordöstra delen av Arathi Highlands. Nimboya hänvisar resenärer från Stranglethorn Vale till Zengu för att hjälpa till att säkra det legendariska vapnet."}},faq={{q="Varför vill Vol'jin ha svärdet Trol'kalar?",a="Vol'jin tänker använda Trol'kalar i de kommande striderna mot de fientliga djungeltrollen i Zul'Gurub.",al={"varför trolkalar","varför trollbanes svärd","trol'kalars syfte"}},{q="Vem är Zengu?",a="Zengu är en erfaren jägare som Darkspear Trolls skickat till Hammerfall i Arathi Highlands för att övervaka återtagandet av Trol'kalar.",al={"vem är zengu","zengus roll","jägaren zengu"}},{q="Vart leder resan?",a="Resan går norrut från Stranglethorn Vale till Hammerfall, en utpost i nordöstra Arathi Highlands.",al={"vart ska man gå","uppdragets destination","var är zengu"}},{q="Vad hände med Stromgarde?",a="Stromgarde ligger i ruiner efter att dess härskare, kung Thoras Trollbane, gått bort.",al={"stromgardes tillstånd","vad hände med thoras trollbane"}}},fp="9,190,30.261.0,21.192.0,43.90.0,13.118.0,33.104.0,28.70.0"}
P.entries["quest:6381"] = {n="New Life",s="New Life är ett återställande Horde-uppdrag som Tammra Windfield erbjuder i Sun Rock Retreat. Efter att ha samlat in förtrollade frön beger du dig västerut till Charred Vales askgrå ruiner för att så dem i bördig jord. Ritualen ska väcka marken till liv igen, trots fientliga elementaler och harpyor.",h="New Life är ett återställande Horde-uppdrag som Tammra Windfield erbjuder i Sun Rock Retreat.",kw={"bloodfury-harpyor","the charred vale","cycle of rebirth","jordhögar","eldelementaler","gaea-frön","stonetalon mountains","sun rock retreat","tammra windfield"},ang={["class:Druid"]="Druider känner stark samhörighet med Tammras uppdrag och ser återställandet av Charred Vale som en nödvändig återgång till naturens sköra balans.",["class:Shaman"]="Schamaner förstår att de upprörda eldelementalerna som strövar omkring i dalen aldrig finner ro förrän själva den sargade marken börjar läka.",["profession:Herbalism"]="Örtkunniga uppskattar den kraftfulla förmågan hos tåliga frön att få frodig växtlighet att spira ur helt livlös jord.",["race:Tauren"]="För tauren är det en andlig gemenskap med Jordmodern att så förtrollade frön i sargad jord, och det uppfyller deras heliga plikt att läka sårade marker."},sec={{t="Att läka den svedda jorden",b="Charred Vale står som ett tragiskt vittnesmål om den senaste tidens förödelse, kvävt av sot, rasande eldelementaler och asätande harpyor. Tammra Windfield vägrar låta regionen gå under i ruiner. Med förtröstan på Jordmoderns uråldriga motståndskraft skickar hon resande till den förkolnade dalens hjärta för att leta efter Gaea Dirt Mounds, fläckar med bördig matjord som överlevde infernot."},{t="En grund för framtiden",b="De förtrollade Gaea-fröna som planteras i den svedda jorden är framtagna för att tåla kvarvarande elementär korruption. När de slår rot börjar de skapa ett livsviktigt ekologiskt fäste som kan stå emot förfall och locka tillbaka växtligheten till dalen. Tammra föreställer sig en långsiktig läkeprocess: när levande rötter långsamt återtar sänkan kommer de upprörda eldandarna att lugna sig, harpyorna att förlora sina ödsliga boplatser och Venture Companys rovdrift på skogen till slut att drivas bort."}},faq={{q="Vad är syftet med att plantera Gaea-fröna?",a="De förtrollade Gaea-fröna är avsedda att slå rot i Charred Vales sargade jord. De står emot korruption och skapar ett första fäste för frodig växtlighet, vilket lägger grunden för att skogen gradvis ska kunna växa upp igen och läka.",al={"varför plantera frön","syftet med new life","vad gör gaea-fröna"}},{q="Vart måste jag gå för att plantera fröna?",a="Du måste resa västerut från Sun Rock Retreat till Charred Vale. Fröna planteras i små Gaea Dirt Mounds som ligger utspridda över den förkolnade sänkan.",al={"var ligger charred vale","var planterar jag gaea-frön","fröplatser"}},{q="Vem är Tammra Windfield?",a="Tammra Windfield är en tauren-naturalist som bor i Sun Rock Retreat i Stonetalon Mountains. Hon är hängiven åt att lugna landets sårade andar och återställa områden som härjats av elementär vrede och industriell girighet.",al={"vem ger uppdraget new life","tammra som uppdragsgivare","tammra windfields bakgrund"}},{q="Vilka hot strövar omkring i Charred Vale medan fröna planteras?",a="Charred Vale är hem åt vilda eldelementaler som väckts av den senaste tidens förödelse, liksom aggressiva Bloodfury-harpyor som häckar bland de brända träden.",al={"fiender i charred vale","vad anfaller i charred vale","faror i charred vale"}},{q="Vilket uppdrag kommer före New Life?",a="New Life följer direkt efter uppdraget Cycle of Rebirth, där du hjälper Tammra att samla in de viktiga material som behövs för att förbereda de förtrollade Gaea-fröna.",al={"förutsättning för new life","uppdraget cycle of rebirth","vad leder fram till new life"}},{q="Vad hoppas Tammra ska hända med Stonetalon på lång sikt?",a="Tammra hoppas att det återväxande landet så småningom ska lugna de rasande eldelementalerna, tränga undan de rovgiriga harpyorna och överleva Venture Companys skogsavverkning, så att bergen åter blir en lummig och fridfull skog.",al={"stonetalons framtid","tammras mål","vad händer med charred vale"}}},fx={c43560c5={q="Vad är Gaeas jordkulle till för?",a="Kullarna är fläckar av bördig jord utspridda över den annars svedda och förkolnade marken i The Charred Vale. Tammra Windfield behöver att du begraver Enchanted Gaea Seeds i dem, så att fröna kan slå rot, stå emot den lokala korruptionen och sätta fart på ny växtlighet som långsamt återtar det förstörda ödemarksområdet.",al={"syftet med gaeas jordkulle","vad är gaeas jordkullar","varför plantera i jordkullarna"}}},fp="8,151,26.225.0,25.321.0,47.178.0,41.105.0,24.212.0,50.144.0,33.122.0,58.209.0"}
P.entries["quest:6382"] = {n="The Ashenvale Hunt",s="Jakten i Ashenvale är en order som leder erfarna Hordeäventyrare från The Barrens torra marker norrut till Ashenvales täta skogar. På uppdrag av Jorn Skyseer i Camp Taurajo skickas resenärer till Splintertree Post för att hjälpa Senani Thunderheart och pröva sina spårningskunskaper i ett vilt och omstritt land.",h="Jakten i Ashenvale är en order som leder erfarna Hordeäventyrare från The Barrens torra marker norrut till...",kw={"ashenvale","jakten i ashenvale","the barrens","camp taurajo","jorn skyseer","senani thunderheart","splintertree post"},ang={["class:Hunter"]="Färden från Kalimdors slätter till Ashenvale innebär en stor förändring av terrängen. Under det täta lövverket finns exotiska bestar att spåra, studera och tämja.",["faction:Horde"]="Ashenvale är en viktig strategisk gränsbygd. Ett fotfäste här ger livsviktigt timmer och mat till bosättningarna i Durotar och The Barrens.",["race:Tauren"]="Både Jorn Skyseer och Senani Thunderheart vägleder resan. De ser jakten som mer än slakt: den upprätthåller en andlig balans och är ett sätt att hedra vildmarken."},sec={{t="In i det uråldriga lövverket",b="När de har visat sin jaktförmåga på The Barrens solblekta slätter hänvisas Hordejägare och krigare till en helt annan prövningsplats. Jorn Skyseer ser när en resenär har vuxit ifrån det lokala villebrådet och visar vägen norrut till Ashenvale. För den unga Horden är dessa uråldriga skogar både en rik källa till resurser och en betydelsefull politisk och andlig gränsbygd som de måste lära sig att förstå och göra anspråk på."},{t="Splintertree Post",b="Den slingrande vägen norrut förbi The Mor'shan Rampart leder resenärerna till Splintertree Post, ett befäst Horde-läger djupt inne bland träden. Där välkomnar taurenjägaren Senani Thunderheart erfarna nykomlingar som söker större överlevnadsutmaningar. För att klara sig i Ashenvale förlitar sig Horden på skickliga spårare som kan ta sig fram bland både aggressiva inhemska rovdjur och skogens försvarares fientliga, vaksamma blickar."}},faq={{q="Vem skickar mig på jakten i Ashenvale?",a="Jorn Skyseer, en taurenjägare stationerad i Camp Taurajo i Southern Barrens, erbjuder uppdraget när du har visat din skicklighet i att jaga lokala bestar.",al={"vem ger jakten i ashenvale","uppdragsgivare för jakten i ashenvale","jorn skyseer uppdrag"}},{q="Var ligger Splintertree Post?",a="Splintertree Post ligger i östra centrala Ashenvale. Följ huvudvägen norrut från The Barrens förbi The Mor'shan Rampart och vidare genom skogen, så ligger den befästa utposten längs vägens norra sida.",al={"splintertree post plats","var finns senani thunderheart","hitta splintertree post"}},{q="Vem är Senani Thunderheart?",a="Senani Thunderheart är en taurenjägare med bas i Splintertree Post. Hon samordnar jakten i Ashenvale och lär Hordeäventyrare som anländer hur de jagar de våldsammaste rovdjuren och andarna i den uråldriga skogen.",al={"senani thunderheart","vem är senani","jägaren senani"}},{q="Vilka andra Hordeutposter finns i närheten i Ashenvale?",a="Förutom Splintertree Post har Horden Warsong Lumber Camp i öster och Zoram'gar Outpost på den avlägsna västkusten vid The Zoram Strand.",al={"hordens baser i ashenvale","andra läger i ashenvale"}},{q="Varför är Horden intresserad av att jaga i Ashenvale?",a="Den otämjda vildmarken ger viktigt kött, skinn och resurser som saknas i Durotars och The Barrens torra länder. Att möta skogens farliga bestar ses också som ett avgörande prov på Horde-krigares och jägares vilja och andliga styrka.",al={"varför jaga i ashenvale","hordens motiv i ashenvale"}},{q="Vilka utmaningar väntar efter den här resan?",a="Senani Thunderheart rekryterar erfarna jägare för att spåra upp betydande hot i skogen och skickar ut dem under trädkronorna för att jaga topprovdjur som den väldiga björnen Ursangous, katten Shadumbra och hippogryfen Sharptalon.",al={"nästa uppdrag efter jakten i ashenvale","vad ger senani dig"}}},fx={["854a1b41"]={q="Varför skickar Jorn Skyseer dig till Ashenvale?",a="Jorn Skyseer ser att din styrka växer och att du gärna antar utmaningen i jakten i The Barrens. Han anser att du har vuxit ifrån de lokala prövningarna och är redo för större ära. Ashenvales täta skogar är en vild gränsmark där Horden försöker vinna både andligt herravälde och politisk kontroll. Han vill att skickliga jägare som du hjälper till att befästa den makten.",al={"varför vill jorn skyseer att det här ska göras","jorn skyseers motiv","varför åka till ashenvale"}},["2c1005c5"]={q="Varför väljer Jorn Skyseer dig till jakten?",a="Jorn har sett dig bevisa din skicklighet och ditt mod i hela The Barrens. Som erfaren vägvisare och äldste vid Camp Taurajo är det hans uppgift att se potentialen hos framväxande krigare och skicka dem dit Horden bäst behöver styrka. Ashenvale kräver prövade och dugliga jägare, inte oprövade vakter som är bundna till utposternas försvar.",al={"varför jag ska gå på jakt i ashenvale","varför väljer jorn mig","varför skicka en äventyrare"}}},fp="18,182,23.279.0,17.332.0,35.135.0,35.180.0,27.191.0,50.124.0,52.192.0,36.177.0"}
P.entries["quest:6383"] = {n="The Ashenvale Hunt",s="Ashenvale Hunt är en traditionell rit som Senani Thunderheart leder vid Splintertree Post. Hordens jägare ska spåra upp och övervinna tre legendariska rovdjur som strövar i den uråldriga skogen: björnen Ursangous, nattsabeln Shadumbra och den vildsinta hippogryfen Sharptalon. Jakten är tänkt som mer än ett prov på stridskonst: den är en resa mot list, respekt och självkännedom.",h="Ashenvale Hunt är en traditionell rit som Senani Thunderheart leder vid Splintertree Post.",kw={"ashenvale hunt","raynewood retreat","senani thunderheart","shadumbra","sharptalon","splintertree post","the talondeep path","ursangous"},ang={["class:Hunter"]="Jakten är en klassisk övergångsrit. Den tvingar spåraren att genomsöka stora skogsområden, läsa terrängen och möta bestar som lätt kan övermanna en oförsiktig spejare.",["faction:Horde"]="I kontrast till Warsongs destruktiva kalhuggning av skogen erbjuder jakten Horden en väg till krigarheder och andlig samhörighet i det omstridda Ashenvale.",["race:Tauren"]="För taurenjägare speglar jakten på Ursangous, Shadumbra och Sharptalon en traditionell vördnad för Moder Jords skapelse. Den förenar respekt för naturens våldsamhet med jaktens heder."},sec={{t="En tauren-tradition i en uråldrig skog",b="När Horden etablerar fästen djupt inne i Ashenvale tar Moder Jords andliga läror form genom Senani Thunderheart. Till skillnad från orchernas aggressiva skogsavverkning behandlar Senani de skuggiga skogarna som en helig prövningsplats. Genom att mäta sin list mot skogens främsta rovdjur förväntas jägaren komma i kontakt med den otämjda vildmarken och utveckla den stilla ödmjukhet som överlevnad i Ashenvale kräver."},{t="De tre stora bestarna",b="Jakten kretsar kring tre ensamma legender som strövar bland trädens grenar. Nära The Talondeep Path strövar Ursangous, en väldig gammal björn vars styrka prövar den fysiska uthålligheten. Längre österut, vid gränsen nära Raynewood Retreat och de svårfångade Laughing Sisters, smyger Shadumbra fram, en smidig nattsabel som vördas för sin list. Slutligen kretsar Sharptalon söder om Splintertree Post. Den våldsamma hippogryfen behärskar skogstaket och fullbordar prövningen."}},faq={{q="Vem startar Ashenvale Hunt?",a="Jakten leds av Senani Thunderheart, en taurenjägare stationerad i Ashenvale. Hon ger utmaningen till Hordens resenärer som vill bevisa sin förmåga att överleva i vildmarken.",al={"uppdragsgivare ashenvale hunt","vem ger jakten","senani thunderheart uppdrag"}},{q="Vilka bestar måste jag spåra upp?",a="Du måste spåra upp och döda tre legendariska rovdjur: den stora björnen Ursangous, nattsabelkatten Shadumbra och den vildsinta hippogryfen Sharptalon.",al={"vilka djur ska dödas","tre bestar","ashenvale hunt mål"}},{q="Var hittar jag Ursangous?",a="Ursangous strövar i ett litet område strax väster om The Talondeep Path, bland skogens andra vilda björnar.",al={"ursangous plats","var finns björnen","hitta ursangous"}},{q="Var strövar Shadumbra?",a="Shadumbra strövar i området söder om Raynewood Retreat och jagar nära vägen där dryaderna som kallas Laughing Sisters bor.",al={"shadumbra plats","var finns shadumbra","nattsabel plats"}},{q="Var kan jag spåra Sharptalon?",a="Sharptalon patrullerar ett vidsträckt område söder om Splintertree Post och sveper fram genom träden och gläntorna.",al={"sharptalon plats","var finns sharptalon","hippogryf plats"}},{q="Varför skickar Senani Thunderheart jägare efter de här bestarna?",a="Senani ser jakten som en hedervärd prövning, inte som meningslöst dödande. Genom att mäta sin styrka mot skogens farligaste naturliga invånare ska jägarna förstå vildmarken och få insikt i sin egen inre styrka.",al={"varför genomföra jakten","jaktens syfte","jaktens bakgrund"}}},fx={e25adf54={q="Vilka är bestarna i Ashenvale-jakten?",a="Jakten utmanar dig att spåra tre legendariska rovdjur från Ashenvales urgamla skogar: Ursangous, en enorm och vildsint björn som strövar nära The Talondeep Path; Shadumbra, en svårfångad nattsabel som jagar i skogarna söder om Raynewood Retreat; och Sharptalon, en våldsam hippogryff som kretsar söder om Splintertree Post. Var och en visar skogens egen otämjda styrka och list.",al={"vilka bestar ska jag jaga","målen för jakten i ashenvale","vilka är bestarna"}},a64a5cc6={q="Varför låter Senani Thunderheart äventyrare utföra jakten i stället för de lokala vakterna?",a="The Ashenvale Hunt är ingen militär uppgift eller uppmaning till utrotning. Det är en traditionell övergångsrit som ska pröva jägarens list, styrka och beslutsamhet mot vildmarken. Splintertrees garnison har i uppgift att försvara Hordens utpost i fientligt territorium, men det här provet är en personlig färd där du söker upp skogens farligaste bestar för att bevisa ditt eget värde.",al={"varför skicka mig","varför äventyrare","varför inte vakterna vid splintertree"}}},fp="18,171,39.309.0,22.321.0,30.164.0,36.88.0,29.78.0,28.110.0,32.81.0,61.180.0"}
P.entries["quest:6384"] = {n="Ride to Orgrimmar",s="En vindryttare för hordens resenärer från The Crossroads till Orgrimmar. Med Zarghs färska köttbitar i handen flyger du till huvudstadens Skytower och lämnar dem till Innkeeper Gryshka.",h="En vindryttare för hordens resenärer från The Crossroads till Orgrimmar.",kw={"the barrens","the crossroads","devrak","doras","gryshka","orgrimmar","skytower","wind rider","zargh"},ang={["faction:Horde"]="Som medlem av horden kan du resa med vindryttare mellan The Crossroads i centrala The Barrens och Orgrimmar, där krigshövding Thrall härskar.",["profession:Cooking"]="Gryshka visar tydligt sin smak när hon tar emot Zarghs gåva: hon föredrar de finaste djuren från Kalimdor, serverade blodiga för att bevara smaken."},sec={{t="Vingar över savannen",b="Devrak skickar tränade vindryttare mellan The Crossroads och Orgrimmar. Färden går över The Barrens torra marker och når Durotars röda klippor, så att resenärerna slipper den mödosamma vandringen till fots. Högt ovanför de dammiga stigarna i kanjonen bär wyvernerna budbärare och resenärer, liksom meddelanden och handelsvaror, direkt till huvudstaden."},{t="Särskild leverans till Gryshka",b="Zargh har förberett färska köttbitar åt Innkeeper Gryshka i Orgrimmars Valley of Strength. Från den centrala Skytower är hennes värdshus en kort promenad bort. Gryshka tar emot paketet och säger ömt att Zargh vet hur man vinner en kvinnas hjärta."}},faq={{q="Vad är syftet med flygturen?",a="Färden låter dig bekanta dig med hordens vindryttarleder. Du betalar Devrak för resan från The Crossroads till Orgrimmar och tar med dig Zarghs färska köttbitar till Innkeeper Gryshka.",al={"varför flyga till orgrimmar","syftet med flyget till orgrimmar","varför kött till orgrimmar"}},{q="Var landar wind ridern i Orgrimmar?",a="Vindryttaren landar vid Orgrimmars Skytower, ovanför Valley of Strength. Ramper leder ner till det stora torget, närliggande försäljare och Gryshkas värdshus.",al={"var landar jag i org","var ligger skytower","landningsplats för flyg i orgrimmar"}},{q="Vem är Gryshka?",a="Innkeeper Gryshka driver en krog i Orgrimmars Valley of Strength. Hon välkomnar resenärer och har en varm vänskap med Zargh, som förser hennes kök med färska köttbitar.",al={"innkeeper gryshka","vem är gryshka","var finns gryshka"}},{q="Vem är Devrak?",a="Devrak är vindryttarmästaren vid The Crossroads i The Barrens. Han tar hand om wyvernerna och samordnar flygresor mellan utposten, Durotar och andra bosättningar som tillhör horden.",al={"devrak vid the crossroads","vem är devrak","wind rider-mästare vid the crossroads"}},{q="Varför skickar Zargh färskt kött till Gryshka?",a="Zargh skickar Gryshka färskt vilt från The Barrens som en gåva. Hon uppskattar de utvalda köttbitarna och säger att de vinner hennes hjärta.",al={"zarghs kött","varför skicka kött till gryshka","zargh och gryshka"}},{q="Vad ska jag göra efter att ha lämnat köttet?",a="När du har lämnat över köttet skickar Gryshka dig tillbaka till Skytower för att tala med Doras, Orgrimmars vindryttarmästare, om återresan.",al={"vad gör jag efter färden till orgrimmar","nästa uppdrag efter gryshka","vart ska jag efter leveransen"}}},fx={a3e1a2de={q="Varför vill Devrak att du flyger till Orgrimmar?",a="Devrak är vindryttarmästaren vid The Crossroads och ansvarar för att knyta ihop The Barrens med resten av Hordens flygnätverk. Genom att ordna en resa åt dig så att du kan leverera Zarghs färska paket till Gryshka håller han den viktiga kurirtrafiken mellan utposten och huvudstaden igång, samtidigt som han visar resande äventyrare hur snabbt och smidigt det går att färdas med wyvern.",al={"varför skickar devrak dig","devraks motiv","varför rida till orgrimmar"}},["715139d2"]={q="Varför skickar Devrak dig i stället för att själv flyga till Orgrimmar?",a="Devrak kan inte lämna sin plats vid The Crossroads. Som flygmästare har han ansvar för vindryttarna och samordnar flygningar för kurirer, spejare och krigare över centrala Kalimdor. Genom att överlämna försändelsen till en duglig resenär på väg mot huvudstaden ser han till att den kommer fram snabbt utan att själv behöva lämna sin post.",al={"varför skicka mig","varför kan inte devrak leverera köttet","varför ska jag rida till orgrimmar"}}},fp="17,135,22.317.0,28.245.0,35.182.0,44.150.0,15.173.0,14.172.0,41.124.0,43.145.0"}
P.entries["quest:6385"] = {n="Doras the Wind Rider Master",s="Innkeeper Gryshka behöver en kurir som kan framföra hennes tack till Zargh vid The Crossroads. Hon skickar resenärer till Doras the Wind Rider Master vid Orgrimmars flygtorn för att ordna flygresan tillbaka till The Barrens.",h="Innkeeper Gryshka behöver en kurir som kan framföra hennes tack till Zargh vid The Crossroads.",kw={"the barrens","the crossroads","doras","flygmästare","gryshka","orgrimmar","vindryttare","wyvern","zargh"},ang={["faction:Horde"]="Vindryttarnätverket förbinder Orgrimmar med viktiga regionala garnisoner och hjälper den unga horden att flytta trupper och förnödenheter genom Kalimdors vildmark.",["race:Orc"]="Sedan de kom till Kalimdor har orcher knutit starka band till dess inhemska wyverner. De förlitar sig på deras smidighet och styrka som flygande riddjur och lastdjur."},sec={{t="Ett buds svar",b="Innkeeper Gryshka tackar Zargh efter att en köttleverans från jaktmarkerna i The Barrens har kommit fram säkert. Hon har inte tid att själv resa genom Durotar och litar därför på det etablerade nätverket av luftkurirer som förbinder hordens större bosättningar och kan föra hennes brev över gränsen."},{t="Ryttarnas mästare",b="Vid flygtornet i Valley of Strength håller Doras uppsikt över Orgrimmars vindryttarnäste. De tränade wyvernerna transporterar militära meddelanden och förnödenheter mellan huvudstaden och utposter som The Crossroads, mycket snabbare än någon som färdas till fots eller med kodo-kärra."}},faq={{q="Vem är Doras?",a="Doras är Orgrimmars främsta vindryttarmästare. Han sköter stadens tränade wyverner och samordnar flygresor till avlägsna hordfästen i centrala Kalimdor.",al={"doras","vem är doras","flygmästare i orgrimmar"}},{q="Varför skickar Innkeeper Gryshka det här brevet?",a="Gryshka skickar ett tackbrev till Zargh, slaktaren vid The Crossroads, för köttleveransen som kom fram säkert till hennes värdshus i Orgrimmar.",al={"varför skicka brev","gryshkas brev","vad är brevet till för"}},{q="Var hittar man Doras?",a="Doras står högst upp i det centrala flygtornet ovanför Orgrimmars Valley of Strength. Träramper inne i tornet leder upp till honom.",al={"var finns doras","doras plats","hitta doras"}},{q="Vad händer när man ger Gryshka's Letter till Doras?",a="När du har talat med Doras förbereder han en vindryttare som tar dig tillbaka till The Barrens. Du kan överlämna Gryshka's Letter direkt till Zargh vid The Crossroads.",al={"vad händer sedan","efter doras","nästa uppdrag"}},{q="Vem är Zargh?",a="Zargh är en orcisk slaktare vid The Crossroads i The Barrens och en vän till Gryshka. Han skickade henne en gåva med fina köttbitar från The Barrens.",al={"zargh","vem är zargh"}},{q="Varför använda vindryttare i stället för att gå?",a="Landvägen från Orgrimmar genom Durotar och över Southfury River in i The Barrens är långsam och farofylld. Horden använder tämjda vindryttare för att snabbt transportera spejare, order och kurirer mellan bosättningar.",al={"varför flyga","vindryttarnas syfte","lore om flygrutter"}}},fx={a0f5ace5={q="Varför ber Gryshka en äventyrare att bära hennes brev?",a="Gryshka driver den livliga centrala värdshuset i Valley of Strength och kan inte bara lämna sin post för att vandra tillbaka till The Barrens. Du har just anlänt med en leverans från Zargh vid The Crossroads, så det är naturligt att du får ta med hennes svar. Eftersom du redan känner rutten och har låst upp flygförbindelser kan hon låta sin tacksamhet färdas snabbt tillbaka genom Hordens etablerade vindryttarnätverk utan att ta stadsvakten i Orgrimmar från dess uppgift att försvara huvudstaden.",al={"varför jag doras","varför be mig bära gryshkas brev","varför får inte en vakt bära gryshkas brev"}}},fp="27,206,17.269.0,23.265.0,13.120.0,45.126.0,25.124.0,52.149.0,13.132.0,39.234.0"}
P.entries["quest:6386"] = {n="Return to the Crossroads.",s="Gryshkas svar är på väg från Orgrimmar till Zargh i The Crossroads. En vindryttare bär det över avståndet mellan Durotar och The Barrens.",h="Gryshkas svar är på väg från Orgrimmar till Zargh i The Crossroads.",kw={"the barrens","the crossroads","devrak","doras","gryshka","brev","orgrimmar","vindryttare","wyvern","zargh"},ang={["faction:Horde"]="Vindryttarrostarna i Orgrimmar och The Crossroads förbinder hordens huvudstad med Kalimdors farofyllda slätter och transporterar handel och förnödenheter mellan dem.",["race:Orc"]="Som orch vet du att rejäla bitar av färskt vilt är bland de finaste gåvorna för att visa tillgivenhet och respekt för en blivande partner."},sec={{t="En vingad återkomst",b="Du bär Gryshkas skriftliga svar till Zargh efter att ha tagit med en bit förstklassigt kött till henne i Orgrimmar. Doras, vindryttarmästaren på Orgrimmars höga klippor, ordnar ett riddjur för färden tillbaka till The Barrens. Du har redan träffat Devrak i The Crossroads, så wyvernerna känner flygrutten. Färden går över öknen och sparar dig den långa marschen till fots över Southfury River."},{t="En match i The Barrens",b="Zarghs uppvaktning har vunnit Gryshkas varma svar. Fina förnödenheter har gjort henne glad, och Zargh firar och funderar till och med på ett stundande bröllop. Leveransen för dig också tillbaka till The Barrens centrala knutpunkt för resor."}},faq={{q="Varför måste jag använda en vindryttare för att återvända?",a="Doras skickar dig med vindryttare eftersom du redan har besökt Devrak i The Crossroads. Wyvernerna kan flyga mellan de två rastplatserna, vilket sparar tid och håller försörjningslinjerna säkra.",al={"varför flyga tillbaka","vindryttare krävs","kan jag gå till fots"}},{q="Vem är Gryshka?",a="Gryshka är värdshusvärd i Orgrimmars Valley of Strength. Zargh skickade henne utvalt kött från The Barrens i hopp om att vinna hennes gunst.",al={"gryshkas bakgrund","vem är gryshka","köttkvinnan i orgrimmar"}},{q="Vad ville Zargh uppnå genom att skicka kött till Orgrimmar?",a="Zargh skickade kött för att uppvakta Gryshka. Bland orcher är en gåva med rejält kött av hög kvalitet från The Barrens en storslagen romantisk gest.",al={"varför skickade zargh kött","zarghs motiv","zarghs brev"}},{q="Var avslutas det här uppdraget?",a="Du återvänder till Zargh i The Crossroads i The Barrens, nära vakttornet och stallen, och lämnar tillbaka Gryshka's Letter.",al={"var lämnar jag in uppdraget","plats för återkomst","vem får gryshkas brev"}},{q="Vem är Doras?",a="Doras är vindryttarmästaren vid flygrosten ovanför Orgrimmars Valley of Strength. Han sköter de flygande riddjur som färdas över Kalimdor.",al={"doras vindryttare","doras plats","flygmästare i orgrimmar"}},{q="Vad händer efter det här uppdraget?",a="Du slutför budkedjan Meats to Orgrimmar. Orgrimmar och The Crossroads är förbundna, och The Barrens ligger öppet för vidare färder.",al={"fortsättning på uppdragskedjan","nästa uppdrag efter återkomsten","fortsättning på meats to orgrimmar"}}},fx={["0a3565f0"]={q="Varför vill Doras att jag återvänder till The Crossroads?",a="Doras har inget personligt intresse i Zarghs kärleksaffär, men som vindryttarmästare i Orgrimmar ska han visa upp Hordens luftburna kurirnätverk. Nu när du har knutit ihop Orgrimmar med flygrosten vid The Crossroads visar han att systemet fungerar genom att skicka dig tillbaka med wyvern och Gryshkas svar, samtidigt som du för med dig viktig personlig korrespondens till The Barrens.",al={"varför skickar doras mig tillbaka","doras motiv för återresan till the crossroads","varför ta med gryshkas brev tillbaka"}}},fp="25,120,15.392.0,27.217.0,44.173.0,15.125.0,51.122.0,26.118.0,13.146.0,30.138.0"}
P.entries["quest:6387"] = {n="Honor Students",s="Gruvinstruktören Brock Stoneseeker belönar lovande unga lärlingar i Thelsamar med hedershackor för gruvdrift. För att ordna leveransen från Ironforge ber han äventyrare ta hjälp av den lokala gryphonmästaren Thorgrum Borrelson.",h="Gruvinstruktören Brock Stoneseeker belönar lovande unga lärlingar i Thelsamar med hedershackor för gruvdrift.",kw={"brock stoneseeker","golnir bouldertoe","gryphon","honor students","ironforge","loch modan","gruvdrift","thelsamar","thorgrum borrelson"},ang={["faction:Alliance"]="Den här förfrågan låter resenärer i Loch Modan bekanta sig med Alliansens viktiga nätverk av flygmästare och luftburna kurirer.",["profession:Mining"]="Ärendet visar dvärgarnas respekt för gruvdrift som ett disciplinerat hantverk, där kunskap om sten och malmådror ger konkret erkännande från mästarinstruktörer.",["race:Dwarf"]="För dvärgiska äventyrare speglar uppdraget det nära bandet mellan gränsbyar som Thelsamar och huvudstadens djupa salar inne i berget."},sec={{t="En gruvarbetares rättmätiga del",b="I dvärgstaden Thelsamar är gruvdrift mer än ett yrke. Den är en grundpelare för vardagens överlevnad och dvärgarnas stolthet. Brock Stoneseeker ser mängder av nya rekryter gå igenom hans utbildning, där han lär dem om bergarter och tunnelsäkerhet. Enligt traditionen ska de elever som utmärker sig få erkännande i form av en fint tillverkad hedershacka. Eftersom det lokala lagret är begränsat måste hackorna hämtas från Khaz Modan, i Ironforges hjärta."},{t="Upp i skyn",b="I stället för att lita till den långsamma, bergiga vandringen genom Dun Morogh förlitar sig Brock på kungadömets nätverk av luftburna kurirer. Thorgrum Borrelson sköter gryphonhägnet intill Thelsamar och erbjuder snabb transport till huvudstaden. När Brock lämnar sin beställning till Thorgrum inleds en kurirfärd som förbinder träningen vid den avlägsna gränsen direkt med dvärgarnas huvudstads stora smedjor."}},faq={{q="Vem är Brock Stoneseeker?",a="Brock Stoneseeker är en gruvinstruktör som bor i Thelsamar. Han lär nybörjare grundläggande kunskaper i gruvdrift och stenhantverk.",al={"brock stoneseeker","vem är brock","gruvtränare thelsamar"}},{q="Varför behöver Brock hackor från Ironforge?",a="Brock sammanställer en lista över högpresterande gruvelever som har gjort sig förtjänta av hedershackor. För att uppfylla belöningarna måste beställningen levereras till Golnir Bouldertoe, en försäljare av gruvutrustning i Ironforge.",al={"varför ironforge","varför hackor","brock's list"}},{q="Vilken roll har Thorgrum Borrelson i uppdraget?",a="Thorgrum Borrelson är Thelsamars gryphonmästare. Brock ber kurirer ta beställningslistan till honom så att de kan ordna snabb lufttransport tillbaka till Ironforge.",al={"thorgrum borrelson","vem är thorgrum","gryphonmästare thelsamar"}},{q="Vem tar emot listan i Ironforge?",a="Listan ska till slut till Golnir Bouldertoe i Ironforge, som förbereder ceremoniella hackor åt Brocks framstående elever.",al={"vem får listan","golnir bouldertoe","kontakt i ironforge"}},{q="Vart leder ärendet härnäst?",a="När du talar med Thorgrum Borrelson ordnar han en gryphonflygning direkt till Ironforge, så att du kan överlämna beställningen till Golnir Bouldertoe.",al={"nästa steg","vad följer efter honor students","efter brock's list"}},{q="Var utspelar sig uppdraget?",a="Uppdraget börjar och avslutas i Thelsamar, som ligger bland Loch Modans böljande kullar.",al={"uppdragsplats","var ligger thelsamar","var börjar honor students"}}},fx={["7a941756"]={q="Varför ber Brock Stoneseeker en äventyrare om hjälp i stället för att själv leverera listan?",a="Brock är upptagen med att utbilda blivande gruvarbetare här i Thelsamar. Han lär upp nya rekryter i hantverket och sköter sin smedja. Om han lämnade sin post för att resa hela vägen till Ironforge skulle de lokala lärlingarnas lektioner bli försenade, så en resande äventyrare passar perfekt som kurir för hans lista till staden.",al={"varför be mig hjälpa brock","varför åker inte brock till ironforge","varför kan inte brock ta med listan"}}},fp="14,147,13.290.0,19.225.0,25.94.0,41.171.0,52.138.0,35.111.0,33.142.0,32.75.0"}
P.entries["quest:6388"] = {n="Gryth Thurden",s="Det här ärendet introducerar äventyrare till Ironforges nätverk av gryphonrutter genom att ge dem i uppdrag att bära en bunt ceremoniella verktyg till stadens gryphonmästare. Kuriren får Honorary Picks av Golnir Bouldertoe och måste lämna dem till Gryth Thurden, så att de kan skickas tillbaka till Loch Modan.",h="Det här ärendet introducerar äventyrare till Ironforges nätverk av gryphonrutter genom att ge dem i uppdrag...",kw={"flygmästare","golnir bouldertoe","gryth thurden","honorary picks","ironforge","loch modan","thelsamar","thorgrum borrelson"},ang={["faction:Alliance"]="Ironforges gryphonnästen är en oumbärlig transportknutpunkt för Alliansens sändebud som reser mellan Dun Morogh, Loch Modan och de vidare kungarikena.",["profession:Mining"]="Leveransen hjälper direkt Brock Stoneseekers gruvarbetarlärlingar i Loch Modan och hyllar deras hantverk med hedershackor smidda i huvudstaden.",["race:Dwarf"]="För dvärgar är det både en stolthet från förfäderna och en praktisk nödvändighet att färdas med gryphoner. De förbinder bergshallar över förrädiska toppar."},sec={{t="En kurir åt gruvarbetarna",b="Efter resan från Loch Modan till Great Forge får kurirer en bunt Honorary Picks av Golnir Bouldertoe, avsedda för Brock Stoneseekers gruvarbetarlärlingar. I stället för att gå tillbaka över bergspassen till fots råder Golnir dem att använda dvärgarnas gryphonnätverk och skicka budbäraren genom staden för att samordna med Ironforges huvudansvarige för flygtransporter."},{t="Med flyg till Thelsamar",b="Gryth Thurden sköter flygnästena i den väldiga bergshallen och förbinder Ironforge med dvärgarnas bosättningar i Khaz Modan. Thurden går med på att ordna transport tillbaka till Thorgrum Borrelson i Thelsamar, förutsatt att äventyraren redan har spanat in rutten och talat med den lokala flygmästaren där. Leveransen lär unga hjältar vilken viktig roll flygkurirer spelar för att hålla ihop dvärgarnas rike."}},faq={{q="Vad är Honorary Picks till för?",a="Honorary Picks är ceremoniella verktyg som Golnir Bouldertoe har tillverkat i Ironforge åt eleverna till Brock Stoneseeker, en gruvarbetarlärare i Thelsamar.",al={"honorary picks","varför honorary picks","hackor åt brock"}},{q="Vem är Gryth Thurden?",a="Gryth Thurden är den främste gryphonhanteraren i Ironforge. Han övervakar flygrutter som förbinder dvärgarnas huvudstad med bosättningar i Khaz Modan och bortom.",al={"vem är gryth thurden","gryphonmästare i ironforge","gryth thurden bakgrund"}},{q="Var i Ironforge finns Gryth Thurden?",a="Gryth Thurden finns vid flygnästet i Great Forge, nära den stora centrala genomfartsleden och Ironforges portar.",al={"gryth thurden plats","var hittar man gryth thurden","flygmästare i ironforge"}},{q="Varför måste jag tala med Thorgrum Borrelson först?",a="Gryphonhanterare skickar bara ryttare längs kartlagda rutter. Innan Gryth Thurden kan skicka en ryttare till Thelsamar måste resenären ha etablerat kontakt med Thorgrum Borrelson, flygmästaren i Loch Modan.",al={"krav på thorgrum borrelson","varför behövs flygrutten till thelsamar","kan inte flyga till thelsamar"}},{q="Vad händer när jag har gett Gryth Thurden hackorna?",a="När Gryth har undersökt paketet förbereder han en gryphonflygning, så att du kan återvända till Thelsamar och lämna verktygen direkt till Brock Stoneseeker.",al={"vad händer efter gryth thurden","nästa uppdrag efter gryth thurden"}},{q="Vem skickar dig till Gryth Thurden?",a="Golnir Bouldertoe, en hantverkare som arbetar i närheten av Great Forge i Ironforge, ger dig hackorna och hänvisar dig till Gryth.",al={"vem startar gryth thurden","vem ger det här uppdraget"}}},fx={["05b277d3"]={q="Varför skickar Golnir Bouldertoe dig till Gryth Thurden?",a="Golnir Bouldertoe har förberett Honorary Picks åt Brock Stoneseekers gruvelever i Thelsamar. I stället för att låta dig vandra tillbaka till fots genom det snöiga bergspasset hänvisar Golnir dig till Gryth Thurden, gryffonmästaren i Ironforge, så att du kan lära dig att ordna en gryffonflygning direkt tillbaka över bergen.",al={"varför skicka mig till gryth","golnir bouldertoes motiv","varför vill gryth thurden ha hackorna"}}},fp="13,241,24.321.0,24.397.0,32.160.0,21.118.0,44.105.0,50.179.0,53.144.0,31.115.0"}
P.entries["quest:639"] = {n="Sigil of Strom",s="Zengu i Hammerfall vill ha sigillen som skyddar Trol'kalar, Lord Ignaeus Trollbanes svärd. Syndicate tog det första, Sigil of Strom, och en agent från Syndicate i Stromgarde har troligen det.",h="Zengu i Hammerfall vill ha sigillen som skyddar Trol'kalar, Lord Ignaeus Trollbanes svärd.",kw={"arathi highlands","hammerfall","ignaeus","sigil of strom","stromgarde","syndicate","trol'kalar","trollbane","zengu"},sec={{t="Trollbanes arv",b="I forna tider stred trollen mot Arathorian Empire, och deras skickligaste fiende var Lord Ignaeus of Strom, kallad Trollbane. Han drog ut i strid med Trol'kalar, ett namn som betyder trollslaktare på trollens gamla språk. Nu är Trollbanes söner försvagade och deras fäste ligger i ruiner."},{t="Det första sigillet",b="Flera sigill skyddar svärdet, och de överlevande från Stromgarde tog var sin del av dem. Zengu säger att alla måste hämtas tillbaka. Syndicate tog det första, och Zengu tror att en av deras agenter i Stromgarde har det. Ta tillbaka det till honom i Hammerfall."}},faq={{q="Vem är Zengu?",a="Zengu finns i Hammerfall i Arathi. Han samlar in sigillen som skyddar Trol'kalar, Lord Ignaeus Trollbanes svärd.",al={"vem ger sigil of strom","zengu hammerfall"}},{q="Vad är Trol'kalar?",a="Trol'kalar betyder trollslaktare på trollens forntida språk. Lord Ignaeus of Strom, kallad Trollbane, red ut i strid mot trollen med det.",al={"vad är trolkalar","trol'kalar betydelse","trollbanes svärd"}},{q="Varför behövs Sigil of Strom?",a="Svärdet skyddas av flera sigill, som de överlevande från Stromgarde delade upp mellan sig. Zengu vill ha dem alla, och Sigil of Strom är det första.",al={"varför hämta sigillet","syftet med sigil of strom"}},{q="Vem har Sigil of Strom?",a="Syndicate tog det. Troligen bärs det av en av deras agenter i Stromgarde.",al={"vem har sigil of strom","var finns sigil of strom","syndicate sigill"}}},fp="14,186,23.280.0,15.268.0,13.109.0,19.153.0,33.147.0,29.98.0"}
P.entries["quest:6391"] = {n="Ride to Ironforge",s="Ride to Ironforge är ett introduktionsuppdrag som skickar nyutbildade äventyrare på deras första gryfonflygning från Thelsamar i Loch Modan till dvärgarnas huvudstad. Resenären får en lista över Brock Stoneseekers främsta gruvelever och ska föra den direkt till Golnir Bouldertoe vid Great Forge.",h="Ride to Ironforge är ett introduktionsuppdrag som skickar nyutbildade äventyrare på deras första...",kw={"brock's list","deep mountain mining guild","golnir bouldertoe","great forge","gryfon","kharanos","ride to ironforge","thorgrum borrelson"},ang={["faction:Alliance"]="Gryfonernas flygnätverk utgör ryggraden i Alliansens logistik i Khaz Modan och förbinder frontgarnisonerna med den storslagna huvudstaden.",["profession:Mining"]="Uppgiften belyser direkt Deep Mountain Mining Guilds tradition att uppmärksamma lovande gruvarbetare från Loch Modans gruvor och gravera in deras utmärkelser.",["race:Dwarf"]="För unga Bronzebeard-dvärgar är det en stolt övergångsrit att flyga på gryfon till Great Forge, från avlägsna utposter till kungarikets hjärta."},sec={{t="Upp i skyn",b="För många unga bergsbor och resenärer är flygningen från Thelsamar till Ironforge deras allra första resa på ryggen av en gryfon. Den korta färden leds av gryfonmästaren Thorgrum Borrelson och tar resenärerna över Dun Moroghs snöklädda åsar, rakt in i bergsfästningens väldiga ingång."},{t="Utmärkelser från Deep Mountain Mining Guild",b="Ärendet gagnar Deep Mountain Mining Guild. Brock Stoneseeker skickar regelbundet nyheter från Thelsamar om sina mest lovande gruvelever. Vid Great Forge väntar Golnir Bouldertoe, som graverar lärlingarnas namn på ceremoniella hedershackor för att belöna deras hårda arbete i Loch Modans stenbrott och gruvor."}},faq={{q="Var börjar och slutar flygningen?",a="Resan börjar hos flygmästaren Thorgrum Borrelson i Thelsamar i Loch Modan och tar dig raka vägen till flygroostet vid Great Forge inne i Ironforge.",al={"flygrutt","vart flyger jag","resmål"}},{q="Vad är Brock's List?",a="Brock's List är en förteckning som gruvtränaren Brock Stoneseeker i Thelsamar har sammanställt. Den innehåller hans främsta elever, så att gillet i Ironforge kan belöna deras flit.",al={"brock's list berättelse","vem är brock","vad är dokumentet"}},{q="Vem är Golnir Bouldertoe?",a="Golnir Bouldertoe är en representant för Deep Mountain Mining Guild, med bas vid Great Forge i Ironforge. Han tar emot förteckningar från lokala tränare och graverar elevernas namn på hedershackor.",al={"golnirs roll","var finns golnir","vem är golnir bouldertoe"}},{q="Vad händer när du har lämnat över listan?",a="När Golnir har tagit emot förteckningen hänvisar han dig vidare till Gryth Thurden, Ironforges främste gryfonhanterare, så att du får lära känna kungarikets nätverk för lufttransporter bättre.",al={"nästa uppdrag","vad gör jag sedan","fortsättning"}},{q="Varför flyga i stället för att gå?",a="Bergsvägen och tunnlarna leder visserligen rakt fram till Ironforges portar, men uppdraget ger praktisk vägledning i hur Alliansen färdas med gryfon. Det visar nya äventyrare hur snabbt de kan ta sig mellan bosättningar.",al={"varför flyga","kan jag gå till ironforge","varför gryfon"}},{q="Vad är en hedershacka?",a="Hedershackor är ceremoniella verktyg som Deep Mountain Mining Guild tillverkar för att uppmärksamma framstående gruvelever. De har lärt sig grunderna i utgrävning och geologi av regionala instruktörer.",al={"honorary picks","hacka som belöning","hackceremoni för gruvarbetare"}}},fx={d8819fd3={q="Varför vill Thorgrum Borrelson att du rider till Ironforge?",a="Thorgrum Borrelson är gryffonmästare i Thelsamar i Loch Modan, och hans näring bygger på att resenärer lyfter från hans rastplats. Genom att ordna din flygning till Ironforge för att leverera Brock's List över lovande gruvelever till Golnir Bouldertoe visar han hur snabbt och smidigt det går att färdas med gryffon, samtidigt som han ser till att viktig skråkorrespondens når huvudstaden utan dröjsmål.",al={"thorgrum borrelsons motiv","varför skicka mig till ironforge","varför leverera brocks lista"}}},fp="17,161,19.186.0,33.171.0,37.107.0,21.124.0,25.179.0,40.143.0,37.143.0,25.179.0"}
P.entries["quest:6392"] = {n="Return to Brock",s="Efter att ha överlämnat Brock Stoneseekers brev till Ironforge får du i uppdrag att ta med en omgång Honorary Picks tillbaka till Thelsamar. Du tar hjälp av dvärgarnas nätverk för lufttransporter och går ombord på en grip med Gryth Thurden för att snabbt återvända över bergen.",h="Efter att ha överlämnat Brock Stoneseekers brev till Ironforge får du i uppdrag att ta med en omgång Honorary...",kw={"brock stoneseeker","flygmästare","grip","gryth thurden","honorary picks","ironforge","åter till brock","thelsamar"},ang={["profession:Mining"]="När du levererar Honorary Picks får Loch Modans nyaste gruvarbetare de verktyg de behöver, så att den dvärgiska traditionen av gruvdrift och prospektering kan leva vidare.",["race:Dwarf"]="Rutten mellan Ironforge och Thelsamar visar vilken viktig roll Wildhammer-gripar och Ironforges gripmästare spelar för att knyta samman dvärgarnas fästen."},sec={{t="Upp i skyn",b="Den väldiga bergsfästningen Ironforge är beroende av ett samordnat nätverk av gripbon för att hålla kontakt och bedriva handel med avlägsna bosättningar som Loch Modan. Gryth Thurden, Ironforges gripmästare, övervakar transporterna från stadens centrala flygplattform. Eftersom resenärer först måste skapa kontakt med skötaren vid ett gripbo innan de kan flyga dit, ser Gryth till att du redan har talat med Thorgrum Borrelson i Thelsamar innan han sadlar en grip för återresan."},{t="Hackor åt eleverna",b="Resan har ett praktiskt syfte utöver att låta dig prova på att flyga med grip: Brock Stoneseeker, en respekterad gruvlärare i Thelsamar, behöver ny utrustning till sina lärlingar. När Honorary Picks har överlämnats till honom kan unga gruvarbetare i hela dalen börja utvinna de rika koppar- och tennådrorna längs kullarna kring The Loch."}},faq={{q="Vem är Brock Stoneseeker?",a="Brock Stoneseeker är en dvärgisk gruvtränare som håller till i Thelsamar i Loch Modan. Han lär nybörjare att utvinna malm och sten ur de omgivande kullarna.",al={"brock stoneseeker","vem är brock","brock i thelsamar"}},{q="Varför måste jag flyga med grip för att slutföra uppdraget?",a="Uppdraget introducerar resenärer till Alliansens flygsystem. Gryth Thurden förklarar att gripar bara kan flyga dig till gripbon som du själv har besökt tidigare, till exempel Thorgrum Borrelsons bo i Thelsamar.",al={"varför flyga","uppdrag om flygrutter","gripritt"}},{q="Vad ska Honorary Picks användas till?",a="Det är nyss smidda gruvverktyg som Brock Stoneseeker beställde från Ironforge åt sina nybörjarelever, så att de kan använda dem bland de mineralrika klipporna i Loch Modan.",al={"honorary picks","vad är hackorna"}},{q="Vem är Gryth Thurden?",a="Gryth Thurden är gripmästare i Ironforge och håller till vid Great Forge. Han sköter huvudstadens ankommande och avgående flygningar i Khaz Modan och längre bort.",al={"gryth thurden","flygmästare i ironforge"}},{q="Kan jag gå tillbaka till Thelsamar i stället för att flyga?",a="Även om lektionen är tänkt att lära dig använda flygrutter bryr sig Brock Stoneseeker bara om att du tryggt överlämnar Honorary Picks till honom i Thelsamar, oavsett hur du tar dig dit.",al={"kan jag gå tillbaka","måste jag rida på grip"}},{q="Var i Thelsamar finns Brock?",a="Brock Stoneseeker finns utomhus nära smedjan och städet i Thelsamar, redo att hjälpa gruvarbetare i Loch Modan.",al={"var finns brock","brock stoneseekers plats","hitta brock"}}},fx={c8277dbd={q="Varför vill Gryth Thurden att jag levererar hackorna?",a="Gryth Thurden sköter gryffonrastplatserna i Ironforge och håller rikets flygrutter sammanlänkade. Brock Stoneseeker nere i Thelsamar väntar på en brådskande leverans av Honorary Picks åt sina gruvelever. Eftersom du redan har färdats mellan Ironforge och Thorgrum Borrelsons rastplats använder Gryth leveransen både för att uppfylla Brocks försörjningsbehov och för att se till att du lär dig färdas med gryffon genom Khaz Modan.",al={"varför vill gryth ha det här","gryth thurdens motiv","varför skicka hackorna till brock"}},be2b1abc={q="Varför skickar Gryth Thurden en äventyrare i stället för att sköta det själv?",a="Gryth Thurden kan inte lämna sin post vid Great Forge, där han övervakar den ständiga strömmen av ryttare och skötseln av Ironforges högt värderade gryffoner. Eftersom du själv bar Brocks meddelande till staden och låste upp flygrutten tillbaka till Thelsamar är du den perfekta kuriren för att prova den nyöppnade förbindelsen och leverera förnödenheterna direkt till gruvarbetaren.",al={"varför behöver gryth mig","varför skicka en äventyrare till thelsamar","varför skicka inte en kurir"}}},fp="15,145,19.279.0,20.188.0,25.143.0,55.176.0,32.95.0,21.149.0,52.176.0,36.102.0"}
P.entries["quest:6393"] = {n="Elemental War",s="Elemental War är ett uppdrag åt Tsunaman, ett sändebud för vattenelementalerna vid Sun Rock Retreat i Stonetalon Mountains. Med Neptulon the Tidehunters vilja som ledstjärna skickas äventyrare ner i de svedda djupen av The Charred Vale för att släcka brinnande eldelementaler och samla deras glödande Incendrite-kärnor. Uppdraget ger en sällsynt inblick i den uråldriga, eviga rivalitet som splittrar elementplanen.",h="Elemental War är ett uppdrag åt Tsunaman, ett sändebud för vattenelementalerna vid Sun Rock Retreat i...",kw={"the charred vale","elementkrig","eldelementaler","incendrites","neptulon","stonetalon mountains","sun rock retreat","tribunal of the tides","tsunaman"},ang={["class:Shaman"]="Schamaner vördar elementens balans, så den direkta konflikten mellan Neptulons tjänare och eldelementalerna visar tydligt den ursprungliga elementstriden.",["faction:Horde"]="Eftersom Tsunaman är stationerad vid Sun Rock Retreat kan hordens äventyrare som färdas genom Stonetalon Mountains hjälpa till i denna elementarkonflikt."},sec={{t="Uråldrig rivalitet i bergen",b="I de karga delarna av Stonetalon Mountains har ett sändebud vid namn Tsunaman anlänt till Sun Rock Retreat på Tribunal of the Tides vägnar. Under Neptulon the Tidehunters högsta vilja söker Tsunaman utkräva en uråldrig hämnd på deras eldfödda släktingar. Det här är ingen konflikt om dödligas gränser, utan en ändlös kamp mellan Azeroths urkrafter."},{t="Aska och lågor",b="Den främsta stridsplatsen är The Charred Vale, en sargad ödemark som pyr i södra Stonetalon Mountains. Eldelementaler frodas bland askan och hotar de omgivande områdena. Äventyrare anlitas för att ta sig ner i dalen, släcka dessa flamhöljda varelser och samla Incendrites – brinnande rester som blir kvar när en elemental besegras – som bevis på att de förstörts, åt Tribunal of the Tides."}},faq={{q="Vem är Tsunaman?",a="Tsunaman är ett sändebud som Tribunal of the Tides skickat till Sun Rock Retreat i Stonetalon Mountains. Med Neptulon the Tidehunters auktoritet bakom sig vill han föra krig mot eldelementaler och rekryterar äventyrare för att hjälpa till att förgöra dem.",al={"vem är tsunaman","tsunaman uppdragsgivare","vattenelemental sun rock retreat"}},{q="Varför vill Neptulon att eldelementalerna ska förgöras?",a="Neptulon the Tidehunter, vattnets Elemental Lord, hyser ett uråldrigt hat mot eldelementaler och har personligen intresserat sig för att släcka dem. Tsunaman skickades av Tribunal of the Tides för att driva detta fälttåg i Stonetalon Mountains.",al={"varför bekämpa eldelementaler","orsaken till elementkriget","neptulon eldelementaler"}},{q="Var ligger The Charred Vale?",a="The Charred Vale är ett ödelagt, askbeklätt bäcken i södra Stonetalon Mountains. Det myllrar av eldiga elementvarelser och andra farliga bestar födda ur lågor och förödelse.",al={"var ligger charred vale","eldelementalernas plats stonetalon","var hittar man incendrites"}},{q="Vad är Incendrites?",a="Incendrites är brinnande rester som blir kvar när eldelementalerna i The Charred Vale släcks. Tsunaman samlar in dessa kärnor som fysiska bevis på att de förstörts, för att vinna Tribunal of the Tides gunst.",al={"vad är incendrites","eldelementalbyte","incendrite-bakgrund"}},{q="Vad är Tribunal of the Tides?",a="Tribunal of the Tides är en auktoritet bland vattenelementalerna som tjänar Neptulon the Tidehunter. De styr elementarkrafterna och sändebud som Tsunaman för att främja Tidehunters vilja mot rivaliserande elementdomäner.",al={"tribunal of tides bakgrund","vilka är tribunal of tides","vattenelementalfraktion"}},{q="Vem är Neptulon the Tidehunter?",a="Neptulon the Tidehunter är vattnets Elemental Lord och härskar över oceanerna, haven och alla vattenelementaler. Liksom de andra elementarherrarna utkämpar han en uråldrig, evig konflikt mot rivaliserande element, särskilt eld.",al={"vem är neptulon","vattnets elementalherre","neptulon tidehunter"}}},fp="13,330,31.297.0,21.307.0,16.202.0,53.191.0,34.153.0,21.205.0,34.227.0,31.223.0"}
P.entries["quest:6394"] = {n="Thazz'ril's Pick",s="Foreman Thazz'ril råkade lämna sin förtrollade favoritgruvhacka långt inne i den norra grottan under en mineralundersökning. Grottan, som kallas Burning Blade Coven, vimlar nu av farliga bestar, och det glödande verktyget väntar på att hämtas.",h="Foreman Thazz'ril råkade lämna sin förtrollade favoritgruvhacka långt inne i den norra grottan under en...",kw={"burning blade coven","durotar","foreman thazz'ril","gruvdrift","hacka","thazz'ril","valley of trials","vattenfall"},ang={["faction:Horde"]="När horden säkrar grundläggande verktyg och röjer undan fientliga hot som Burning Blade Coven får den ett stadigt fotfäste i Valley of Trials.",["profession:Mining"]="Foreman Thazz'ril förlitar sig på sin förtrollade hacka när han undersöker mineraler i Durotar. Han hoppas hitta nya gruvmöjligheter när det lokala timret har röjts undan."},sec={{t="Ett förlorat verktyg",b="Foreman Thazz'ril, arbetsledaren i Valley of Trials, begav sig tidigare in i den norra grottan för att leta efter mineralådror. Medan han undersökte den klippiga insidan råkade han lämna sin dyrbara gruvhacka där. När han insåg sitt misstag och återvände för att hämta den hade våldsamma bestar och fientliga invånare tagit över grottan. Därför måste arbetsledaren söka hjälp hos dugliga rekryter för att få tillbaka sitt förlorade verktyg."},{t="Glöd i mörkret",b="För att göra sin dyrbara hacka lättare att använda i de dunkla djupen förtrollade Thazz'ril den med en besvärjelse som får den att lysa i mörkret. Det magiska skenet gör det lätt för äventyrare att få syn på verktyget i en vattenfallskammare i Burning Blade Coven, men för att hämta det måste de möta de farliga varelser som stryker omkring i grottans skuggor. När Thazz'ril får tillbaka hackan hoppas han kunna använda den för att hitta nya möjligheter till gruvdrift i hela dalen."}},faq={{q="Vem är Foreman Thazz'ril?",a="Foreman Thazz'ril leder arbetet och insamlingen av resurser i Valley of Trials. Han styr peonerna när de röjer timmer och förbereder marken för gruvdrift.",al={"vem är thazz'ril","thazz'rils roll","foreman thazz'ril"}},{q="Varför lyser Thazz'rils hacka?",a="Thazz'ril förtrollade sin favorithacka så att den lyser i mörkret. Därför syns den lätt även i grottans becksvarta djup.",al={"varför är hackan speciell","glödande hacka","förtrollad hacka"}},{q="Var ligger Burning Blade Coven?",a="Burning Blade Coven är ett mörkt grottsystem norr om peonernas timmerläger i Valley of Trials.",al={"var ligger burning blade coven","grottans läge","hackans grotta"}},{q="Hur tappade Thazz'ril bort sin hacka?",a="Thazz'ril lämnade sin favorithacka i den norra grottan när han undersökte den efter mineraler. När han återvände för att hämta den hade våldsamma bestar och mörka kultister tagit över grottan.",al={"hur tappade thazz'ril bort sin hacka","varför lämnade han hackan","hacka som lämnats kvar"}},{q="Var i grottan lämnade han hackan?",a="Hackan lämnades långt inne i grottan, i en underjordisk kammare med vattenfall. Den ligger där Thazz'ril senast undersökte klippväggarna.",al={"var i grottan","hackans kammare","vattenfallskammare"}},{q="Vad tänker Thazz'ril göra när han får tillbaka hackan?",a="Thazz'ril tänker hitta en grotta som lämpar sig för gruvdrift när hans peoner har huggit ner träden i omgivningen i Valley of Trials.",al={"thazz'rils framtidsplaner","vad ska thazz'ril bryta"}}},fp="16,144,11.273.0,16.311.0,25.151.0,31.106.0,33.101.0,32.163.0,40.128.0,59.133.0"}
P.entries["quest:6395"] = {n="Marla's Last Wish",s="Marla's Last Wish är ett tidigt uppdrag för de Förfallna, som Novice Elreth ger i Deathknell. Du ska leta upp de rester av Samuel Fipps som plågas av gisselns slaveri, så att han kan begravas bredvid sin mördade hustru Marla. Uppdraget visar hur det nyvaknade samhället bland de Förfallna längtar efter att hedra mänskliga band och skilja sig från det viljelösa gisslet.",h="Marla's Last Wish är ett tidigt uppdrag för de Förfallna, som Novice Elreth ger i Deathknell.",kw={"deathknell","grav","marla fipps","marla's last wish","novice elreth","kvarlevor","samuel fipps","gisslet"},ang={["class:Priest"]="Novice Elreths krav på en riktig begravning talar direkt till de Förfallna prästernas andliga plikt. De brottas med dödlighet, sorg och skändningen av Lordaerons döda.",["race:Undead"]="För de nyligen uppståndna Förfallna blir det en känslomässig förankring i deras tidigare mänskliga liv att uppfylla Marlas önskan. Det visar att medkänsla och heder inte gick under när Lordaeron föll."},sec={{t="En tragisk återförening",b="Innan det tredje kriget ödelade Lordaeron levde Marla och Samuel Fipps tillsammans som äkta makar. När pesten svepte genom deras land dukade Samuel under för smittan och återuppväcktes som en viljelös slav under gisslet. Marla undkom visserligen de levande dödas tillvaro, men hon kunde inte undkomma Samuel själv, som brutalt dödade henne i sitt viljelösa raseri. Trots att hon dog för sin makes hand kände Marla inget hat i sina sista stunder. Hennes sista önskan, som Novice Elreth minns, var att vila för evigt bredvid sin make på kyrkogården i Deathknell."},{t="Att visa de döda respekt",b="Novice Elreth skickar Förfallna äventyrare nordost om Deathknell för att hitta Samuel Fipps, som fortfarande strövar omkring bland resterna av ett förstört läger. Att göra slut på Samuels plåga fyller två syften: det renar dalen från en annalkande tjänare åt gisslet och gör att hans kvarlevor kan föras tillbaka till Marlas viloplats. Som Elreth betonar är det en viktig moralisk skillnad mellan de nyligen befriade Förfallna och gisslets viljelösa ondska att hedra de döda och respektera deras sista önskningar."}},faq={{q="Vem var Marla Fipps?",a="Marla Fipps bodde i Lordaeron och överlevde den första pesten av odödhet, men dödades av sin make Samuel efter att han förvandlats till en viljelös gast under gisslet. Hennes sista önskan var att begravas bredvid honom.",al={"marla fipps historia","vem är marla","marlas bakgrund"}},{q="Vem är Samuel Fipps?",a="Samuel Fipps var Marlas make före pesten. Han dukade under för gisslet, förlorade förståndet till Lich Kings vilja och mördade sin hustru. Han strövar omkring vid ett förstört läger nordost om Deathknell tills Förfallna äventyrare gör slut på honom.",al={"samuel fipps historia","vem är samuel fipps","var finns samuel fipps"}},{q="Varför bryr sig Novice Elreth om att de begravs tillsammans?",a="Novice Elreth var Marlas vän i livet. Utöver sina personliga känslor tror Elreth att det visar att de Förfallna har kvar sin mänsklighet och moral när de hedrar de dödas önskningar och behandlar deras kvarlevor med värdighet. Det skiljer dem från det viljelösa gisslet.",al={"varför hjälpa marla","novice elreths motiv","varför begrava samuel"}},{q="Återuppstod Marla som Förfallen?",a="Nej. Enligt Novice Elreth undkom Marla odödheten helt. Hon dog en dödlig död för sin makes hand och begravdes på kyrkogården i Deathknell.",al={"är marla odöd","blev marla en förfallen","marla fipps odöd"}},{q="Var ligger Marlas grav?",a="Marlas grav ligger på första raden av kyrkogården, strax utanför huvudkapellet i Deathknell.",al={"var ligger marlas grav","var är marla begravd","var ska jag begrava samuel"}},{q="Var hittar man Samuel Fipps?",a="Samuel Fipps strövar omkring vid ett förstört läger längs vägen nordost ut från Deathknell.",al={"var finns samuel fipps","hitta samuel fipps","var är samuel"}}},fx={e919b4a2={q="Vad ska Samuel's Remains användas till?",a="Du samlar in Samuels jordiska kvarlevor så att han till sist kan begravas bredvid sin hustru, Marla. Samuel förvandlades till en viljelös tjänare åt Scourge och tog hennes liv, men Marlas sista önskan var att de skulle få vila tillsammans för evigt på gravplatsen i Deathknell.",al={"samuels kvarlevor","varför samla in samuels kvarlevor","syftet med samuels kvarlevor"}},["74d32be4"]={q="Vem är Samuel Fipps, och varför måste du besegra honom?",a="Samuel Fipps var en gång en levande invånare i Tirisfal Glades, men föll offer för de odödas pest och blev en tanklös tjänare åt Scourge. Efter att ha dödat sin egen hustru i sitt viljelösa tillstånd strövar han nu omkring som en ghoul i det övergivna lägret nordost om Deathknell. Han kan inte få ro förrän han förgörs.",al={"varför döda samuel fipps","vem slåss jag mot i marlas sista önskan","samuel fipps bakgrund"}}},fp="17,263,16.400.0,19.346.0,20.151.0,20.210.0,56.207.0,27.142.0,31.90.0,32.78.0"}
P.entries["quest:64"] = {n="The Forgotten Heirloom",s="I Westfall har familjen Furlbrow flytt från sin gård och lämnat ett kärt arvegods kvar. Om du hämtar fickuret får de en chans att rädda något personligt ur kaoset som sprider sig i trakten.",h="I Westfall har familjen Furlbrow flytt från sin gård och lämnat ett kärt arvegods kvar.",kw={"benny blaanco","defias","furlbrow","fickur","pumpafält","verna furlbrow","garderob","westfall"},ang={["faction:Alliance"]="Familjen Furlbrows öde visar hur illa ordningen har brutit samman i kungarikets kornbod. Alliansens resenärer får hantera det som kronan har försummat.",["race:Human"]="Som människa från Stormwind ser du ärliga bönder drivas bort från sin mark av laglösa, bara en dagsmarsch från huvudstaden. Deras öde blottar kungarikets problem på hemmaplan."},sec={{t="En nattlig vräkning",b="Farmer Furlbrow och hans hustru Verna drevs bort från sin gård i Westfall av våld. Rop hördes från pumpafälten i natten och väckte dem, utan att ge dem mycket tid att samla ihop det de kunde bära. I brådskan när de flydde lämnade Furlbrow kvar fickuret som Vernas far gav honom på deras bröllopsdag. Det finns fortfarande i garderoben i deras ockuperade bondgård."},{t="Våldsverkare på fälten",b="Defias-busarna och tjuvarna, däribland Benny Blaanco, rotar nu igenom den övergivna Furlbrow-gården. För vanligt folk kan det betyda döden att återvända efter ett minne. När du hämtar fickuret ur garderoben återger du en del av värdigheten åt en familj som nästan förlorat allt till laglösheten i Westfall."}},faq={{q="Varför är fickuret så viktigt för Farmer Furlbrow?",a="Vernas far gav Farmer Furlbrow fickuret på deras bröllopsdag. För familjen Furlbrow, som nu är på flykt och har förlorat sitt levebröd, bevarar det en känslomässig koppling till deras tidigare liv och familjearv.",al={"varför fickuret är viktigt","furlbrows fickurs betydelse","vem gav furlbrow fickuret"}},{q="Vem drev familjen Furlbrow från gården?",a="Defias-rövare och plundrare drev bort familjen Furlbrow från gården under natten. Deras angrepp speglar laglösheten som tvingar många jordbrukarfamiljer att överge sina hem och åkrar under hot om våld.",al={"vem angrep gården","vem tog furlbrow-gården","vad hände med familjen furlbrow"}},{q="Var är fickuret gömt?",a="Fickuret ligger i en garderob i ett sovrum på Furlbrow-gården, bland pumpafälten väster om familjen Furlbrows läger vid vägkanten i norra Westfall. Inkräktare och Defias-banditer håller till i bondgården.",al={"var är fickuret","hitta fickuret","garderobens plats"}},{q="Vem är Benny Blaanco?",a="Benny Blaanco är en laglös man i Furlbrow-bondgården tillsammans med sina Defias-kamrater. De plundrar det övergivna hemmet och vaktar det mot dem som kan försöka ta tillbaka det.",al={"benny blaancos historia","vem är mannen i huset"}},{q="Var bor familjen Furlbrow nu?",a="Farmer Furlbrow och Verna är strandsatta vid vägkanten i Westfall. De söker skydd nära sin vagn medan de försöker överleva sammanbrottet i trakten.",al={"var är familjen furlbrow","var är farmer furlbrow"}},{q="Skickar Stormwind vakter för att hjälpa till att återta gårdar som den här?",a="Stormwinds officiella militära närvaro i Westfall är nästan obefintlig, på grund av politisk likgiltighet och avsaknad av ledarskap i huvudstaden. Folkets milis vid Sentinel Hill är inte stark nog att återta enskilda gårdar, vilket lämnar nybyggarna utsatta.",al={"stormwind hjälper westfall","varför finns inga vakter vid gården"}}},fx={["028db52d"]={q="Vad är Furlbrow's Pocket Watch?",a="Det är ett vanligt fickur, men ett ovärderligt arvegods. Vernas far gav det till Farmer Furlbrow på deras bröllopsdag. Efter att ha förlorat sin mark, sin skörd och sitt hem till stråtrövare under en enda natt är det här enda minnessaken allt det äldre paret har kvar från sitt tidigare liv.",al={"furlbrows fickur","arvegods i form av fickur","vad är furlbrows fickur"}}},fp="22,179,19.341.0,23.309.0,56.205.0,45.209.0,26.205.0,21.162.0,36.139.0,59.247.0"}
P.entries["quest:640"] = {n="The Broken Sigil",s="När du tagit den första sigillen från Syndicate skickar Zengu dig efter de två återstående, som Stromgarde-milisen håller vakt över från sina befästa positioner. Galen, son till Thoras Trollbane, slog sönder Sigil of Thoradin i bitar, och du ska bära dem till trollschamanen Tor'gan i Hammerfall.",h="När du tagit den första sigillen från Syndicate skickar Zengu dig efter de två återstående, som...",kw={"arathi highlands","trasig sigill","galen trollbane","hammerfall","sigil of thoradin","stromgarde","thoras trollbane","tor'gan","zengu"},sec={{t="En sigill i bitar",b="Tre sigill vaktar Thoras Trollbanes grav, och du har redan återtagit den första från Syndicate. De andra två är svårare att få tag på, eftersom den väl förskansade Stromgarde-milisen håller dem. Thoras son Galen delade Sigil of Thoradin i elva bitar och spred ut dem bland Stromgardes försvarare."},{t="Till Tor'gan",b="Zengu säger åt dig att hämta bitarna från försvararna i Stromgarde och ta dem till Tor'gan, trollschamanen i Hammerfall, som kan sammanfoga dem till en hel sigill."},{t="I Hammerfall",b="Tor'gan säger att Zengu berättat att du behövde hans hjälp. När han ser bitarna bedömer han att arbetet inte är alltför svårt, eftersom alla finns där och den magiska strukturen är lätt att återskapa. Han varnar dig för att blunda och förklarar snart att Sigil of Thoradin åter är hel."}},faq={{q="Vad är Sigil of Thoradin?",a="Det är en av tre sigill som skyddar Thoras Trollbanes grav. Hans son Galen delade den i elva bitar och spred ut dem bland Stromgardes försvarare.",al={"sigil of thoradin bakgrund","trasig sigill betydelse","vad är den trasiga sigillen"}},{q="Vem delade sigillen?",a="Galen, son till Thoras Trollbane, delade Sigil of Thoradin i elva bitar och spred ut dem bland Stromgardes försvarare.",al={"vem slog sönder sigillen","varför är sigillen trasig","galen trollbane sigill"}},{q="Var finns sigillfragmenten?",a="Bitarna finns hos försvararna i Stromgarde, där den väl förskansade milisen håller de återstående sigillen.",al={"var hittar man fragment","vem har fragmenten","stromgarde försvarare sigill"}},{q="Vem kan sammanfoga den trasiga sigillen?",a="Tor'gan, trollschamanen i Hammerfall, kan sammanfoga bitarna till en hel sigill.",al={"vem lagar sigillen","torgan sigill","vem sammanfogar fragmenten"}},{q="Vad hände före detta?",a="Det här följer på Sigil of Strom, där du hämtade den första sigillen från Syndicate.",al={"föregående uppdrag","vilket uppdrag kommer före the broken sigil","sigillkedjans början"}}},fp="16,187,17.257.0,10.161.0,13.268.1,30.161.0,22.127.0,35.105.0,30.80.0,22.82.0"}
P.entries["quest:6401"] = {n="Kaya's Alive",s="Kaya's Alive är ett kort Horde-uppdrag i Stonetalon Mountains som avslutar räddningen av Kaya Flathoof. Efter att ha eskorterat den unga tauren säkert förbi fientliga Grimtotem-banditer får du i uppdrag att föra de glada nyheterna om att hon överlevt till sin oroliga moster, Tammra Windfield, i Sun Rock Retreat.",h="Kaya's Alive är ett kort Horde-uppdrag i Stonetalon Mountains som avslutar räddningen av Kaya Flathoof.",kw={"flathoof","grimtotem","kaya","makaba","protect kaya","stonetalon","sun rock retreat","tammra","tauren","windfield"},ang={["faction:Horde"]="Stonetalon är ett omstritt vildmarksområde där Hordes försvarslinjer är uttänjda. Nyheter om överlevande hjälper till att bevara sammanhållningen mellan de utspridda lägren.",["race:Tauren"]="Grimtotem-hotet är en smärtsam inre splittring för Shu'halo, vilket gör det djupt personligt att skydda oskyldiga familjemedlemmar som Kaya."},sec={{t="En lättnadens suck",b="Stonetalon Mountains är fulla av faror, särskilt längs de omstridda lederna där Grimtotem-stammen slår till utan nåd. När deras by utsattes för en brutal attack befarade man att unga Kaya Flathoof hade dödats eller tillfångatagits av renegaterna. Att hon överlevde och sedan räddades ger ett sällsynt ögonblick av triumf och lättnad mitt i de pågående stamkonflikterna bland klipporna."},{t="Framme vid Sun Rock Retreat",b="När Kaya väl har förts i säkerhet ger Makaba Flathoof dig i uppdrag att personligen föra beskedet till Sun Rock Retreat. Där väntar Kayas moster, Tammra Windfield, oroligt på nyheter från lederna. När du berättar att Kaya är i säkerhet får den splittrade familjen tröst och den viktiga roll som resande hjältar spelar för att hålla avlägsna Horde-utposter i kontakt med varandra blir tydlig."}},faq={{q="Vem är Kaya Flathoof?",a="Kaya Flathoof är en ung tauren som skildes från de sina och hamnade i fara efter ett våldsamt angrepp på hennes bosättning av rebelliska Grimtotem-styrkor i Stonetalon Mountains.",al={"vem är kaya","kaya flathoof","kaya"}},{q="Vem är Tammra Windfield?",a="Tammra Windfield är Kayas moster och bor i Sun Rock Retreat i Stonetalon Mountains. Hon hade befarat att hennes brorsdotter hade omkommit i Grimtotem-attacken.",al={"tammra windfield","vem är tammra","kayas moster"}},{q="Vem attackerade Kayas by?",a="Kayas by överfölls av den aggressiva Grimtotem-klanen, en isolationistisk tauren-fraktion som är ökänd för att ge sig på både rivaliserande stammar och resande vandrare i bergen.",al={"vem attackerade kaya","attack mot byn","grimtotem-attack"}},{q="Vad kommer före det här uppdraget?",a="Det här uppdraget följer direkt efter 'Protect Kaya', ett eskortuppdrag där du försvarar Kaya Flathoof när hon flyr från sina tillfångatagare och tar sig i säkerhet.",al={"förutsättning","protect kaya","eskortuppdrag"}},{q="Var ligger Sun Rock Retreat?",a="Sun Rock Retreat ligger högt uppe i de centrala Stonetalon Mountains. Du når platsen genom att följa huvudvägen västerut och passera genom ett smalt bergspass till en skyddad sänka.",al={"sun rock retreat plats","var ligger sun rock","hitta sun rock retreat"}},{q="Varför skickar Makaba Flathoof dig i stället för att gå själv?",a="Makaba stannar i sitt läger nära Stonetalon-bergens sydöstra kant och förlitar sig på att en rask budbärare snabbt kan lugna familjen i Sun Rock Retreat.",al={"varför makaba stannar","varför skicka mig"}}},fx={["10e83b92"]={q="Varför vill Makaba Flathoof att nyheten ska föras vidare?",a="Deras by utsattes för ett brutalt angrepp, och de överlevande trodde att unga Kaya Flathoof hade gått förlorad i blodbadet. Nu när hon är i säkerhet vill Makaba genast skicka besked för att lindra sorgen hos Kayas moster, Tammra Windfield, som oroligt väntar vid Sun Rock Retreat utan att veta att hennes systerdotter överlevde.",al={"varför skicka besked till tammra","makaba flathoofs motiv","varför framföra nyheten"}}},fp="12,171,18.225.0,25.235.0,21.134.0,24.141.0,28.132.0,29.91.0,34.146.0,59.133.0"}
P.entries["quest:641"] = {n="Sigil of Thoradin",s="Tor'gans rekonstruktion av den trasiga sigillen fungerade perfekt. Den återställda Sigil of Thoradin kan nu öppna förseglingen till Trollbanes grav, och han ber dig återlämna den till Zengu i Hammerfall.",h="Tor'gans rekonstruktion av den trasiga sigillen fungerade perfekt.",kw={"arathi highlands","hammerfall","sigil of thoradin","tor'gan","trol'kalar","trollbanes grav","zengu"},sec={{t="Den återställda sigillen",b="Tor'gan säger att rekonstruktionen fungerade perfekt, och att Sigil of Thoradin nu kan öppna förseglingen till Trollbanes grav. Ta tillbaka den till Zengu i Hammerfall, som säkert har mer att göra för dig."},{t="Halvvägs där",b="Zengu frågar om du har den andra sigillen och säger sedan att de kommit halvvägs till att ta Trol'kalar ur Trollbanes grav. Ingen vet säkert var den tredje sigillen finns, eftersom de som har den flyttar runt i Arathi, men han litar på att du hittar den."}},faq={{q="Vad används Sigil of Thoradin till?",a="Den återställda sigillen kan öppna förseglingen till Trollbanes grav.",al={"sigil of thoradin användning","vad gör sigil of thoradin","varför behöver vi sigillen"}},{q="Vem ska du lämna Sigil of Thoradin till?",a="Zengu i Hammerfall. Tor'gan, som återställde sigillen, säger åt dig att lämna tillbaka den till Zengu.",al={"var lämnar jag sigillen","vem lämnar in sigil of thoradin","lämna in sigil of thoradin"}},{q="Var passar det här steget in i sökandet efter Trol'kalar?",a="Det följer efter The Broken Sigil, där Tor'gan rekonstruerade sigillen av bitarna du gav honom.",al={"framsteg i sigillkedjan","hur långt har uppdraget kommit","vilket uppdrag kommer före detta"}}},fp="17,138,18.172.0,13.230.1,39.57.0,42.79.0,54.105.0"}
P.entries["quest:642"] = {n="The Princess Trapped",s="The Princess Trapped börjar när äventyrare hittar en skimrande kristallskärva i Arathi Highlands och hör Myzraels vädjan. Hon säger sig vara en jordens prinsessa, fängslad djupt under marken. Hon påstår att fientliga jättar spärrat in henne och ber resenärer konfrontera deras koboldallierade i Drywhisker Gorge och återställa kraften i hennes kristallnätverk för kommunikation.",h="The Princess Trapped börjar när äventyrare hittar en skimrande kristallskärva i Arathi Highlands och hör...",kw={"arathi highlands","drywhisker gorge","drywhisker-kobolder","jordens prinsessa","skimrande skärvor","motes of myzrael","myzrael","the princess trapped","den tillfångatagna prinsessan"},ang={["class:Mage"]="Resonanta kristallskärvor och motes av jordenergi används för att kommunicera och leda kraft över stora avstånd. Det är ett märkligt exempel på geomantisk magi.",["class:Shaman"]="Som utövare som kommunicerar med elementens andar känner shamaner igen Myzraels påstående om att vara en jordens prinsessa, men hennes fångenskap under marken kräver noggrann granskning av elementen.",["profession:Mining"]="Gruvarbetare som tar sig nära Drywhisker Gorge och de underjordiska ådrorna i Arathi kommer att stöta på både koboldhärdar och de förtrollade kristallskärvor som hör samman med prinsessan."},sec={{t="En röst från stenen",b="Utspridda över The Rolling Plains i Arathi Highlands surrar märkliga kristallskärvor av avlägsen kraft. När du närmar dig hörs en desperat röst från djupa underjordiska grottor: Myzrael, en självutnämnd jordens prinsessa. Hon säger att forntida jättar störtade henne och band henne långt under marken, avskuren från de solbelysta landen ovanför. Kristallerna som sitter inbäddade i jorden är hennes enda sätt att nå ytan och sända vädjanden om räddning till äventyrare som vill lyssna."},{t="Förbindelsen till Drywhisker",b="För att upprätthålla sin bräckliga kontakt och börja bryta sig ur sin underjordiska isolering leder Myzrael resenärer österut mot Drywhisker Gorge. Klyftan kryllar av Drywhisker-kobolder, varelser som hon säger är allierade med jättarna som håller henne fången. Kobolderna bär på resonanta Motes of Myzrael och vaktar en stor samling skimrande skärvor. Genom att ta motes från kobolderna och använda deras energi på formationen kan räddare ge kristallsamlingen kraft och fördjupa sin kommunikation med den fängslade prinsessan."}},faq={{q="Vem är Myzrael?",a="Rösten som talar genom kristallen tillhör Myzrael, en varelse som säger sig vara en jordens prinsessa, fängslad djupt under Arathi Highlands. Hon kan inte bryta sig fri på egen hand och söker därför hjälp från äventyrare som passerar för att nå ytan.",al={"vem är den fängslade prinsessan","vem talar genom kristallen","vem är myzrael"}},{q="Vem fängslade Myzrael under höglandet?",a="Enligt Myzrael fängslades hon under Arathi av jättar. Hon säger att de band henne djupt under marken och tvingade henne att förlita sig på kristallskärvor utspridda över området för att kommunicera med dem som vandrar ovan jord.",al={"vem fängslade myzrael","vem fångade prinsessan","varför är myzrael under jorden"}},{q="Vad är Motes of Myzrael?",a="Motes of Myzrael är kristallina eller elementära fragment som bärs av Drywhisker-kobolderna. Myzrael förklarar att dessa motes rymmer nog med vilande jordkraft för att aktivera och förstärka skärvsamlingarna som behövs för att stärka hennes förbindelse med ytan.",al={"varför har kobolderna motes","motes i drywhisker gorge","vad är motes of myzrael"}},{q="Hur är Drywhisker-kobolderna kopplade till Myzraels fångvaktare?",a="Myzrael säger att Drywhisker-kobolderna i Drywhisker Gorge är allierade med jättarna som fängslade henne. De vaktar en viktig kristallsamling i klyftan och står mellan prinsessan och ytan.",al={"varför är kobolderna inblandade","drywhisker-kobolder och jättar","kobolder som samarbetar med jättar"}},{q="Hur kan Myzrael tala underifrån marken?",a="Myzrael leder sin röst genom mystiska skimrande kristallskärvor som skjuter upp ur jorden i Arathi Highlands. Dessa formationer fungerar som geomantiska sändare, så att hennes ande eller röst kan tränga genom jordens djup och nå dem som vistas på ytan.",al={"hur talar myzrael","skimrande skärvor i arathi","vad är kristallskärvorna"}},{q="Var ligger Drywhisker Gorge?",a="Drywhisker Gorge är en oländig ravin i östra Arathi Highlands. Där bor Drywhisker-kobolderna, som omringar den skimrande skärvsamling som Myzrael ber dig aktivera med de insamlade motes.",al={"var ligger drywhisker gorge","var ska jag lämna motes","var finns skärvorna i drywhisker"}}},fp="20,233,22.343.0,25.439.0,15.201.0,42.162.0,30.206.0,62.187.0,46.182.0,34.188.0"}
P.entries["quest:6421"] = {n="Boulderslide Ravine",s="Djupt inne i Boulderslide Ravine i Stonetalon Mountains har traktens kobolder börjat bryta den sällsynta mineralen Resonite i rasande takt. Taurenen Mor'rogal känner en växande spänning i jorden och skickar Horde-äventyrare att utforska ravinens grottsystem och hämta mineralprover för att ta reda på vad som ligger begravt under berget.",h="Djupt inne i Boulderslide Ravine i Stonetalon Mountains har traktens kobolder börjat bryta den sällsynta...",kw={"boulderslide ravine","earthen","kobold","mor'rogal","resonite","resonite crystal","stonetalon","sun rock retreat","titan"},ang={["class:Shaman"]="Schamaner som lyssnar till jorden kan känna den onaturliga resonansen som vibrerar genom berget medan kobolderna blottlägger reliker från titanernas urtida elementarskapande.",["profession:Mining"]="Resonite som Boulderslide-kobolderna bryter är ingen vanlig malm; dess struktur är genomsyrad av uråldriga rester av magi från forna tiders underjordiska byggare.",["race:Tauren"]="För tauren som vördar Jordmodern är upptäckten av uråldriga titanverk under bergen ett tecken på en farlig rubbning av den naturliga balansen i Stonetalon."},sec={{t="Spänningar i stenen",b="Från sin post i Sun Rock Retreat betraktar taurenen Mor'rogal Stonetalon Mountains toppar med stor oro. Själva landet verkar oroligt, med en onaturlig rastlöshet som strålar ut från sydost. Där, bland klipporna i Boulderslide Ravine, har traktens kobolder övergett sitt vanliga födosök för att aggressivt gräva efter den sällsynta mineralen Resonite, som finns under jord. För att ta reda på varför dessa vidskepliga skadedjur gräver med sådan desperat frenesi ber Mor'rogal Horde-spejare att ta sig förbi deras försvar, utforska grottans djupaste delar och hämta obearbetade mineralprover."},{t="De uråldriga vaknar",b="När den råa Resonite undersöks blir dess sanna natur tydlig: kristallerna sjunger av uråldrig jordisk magi. Kobolder som grävt blint i djupet har brutit igenom ett uråldrigt lager av världen och grävt fram en Earthen, en av de urtida stenvarelser som titanerna formade för att skulptera Kalimdors underjordiska grundvalar. Det kobolderna betraktar som ett vanligt stenbrott har rubbat en relik från urtiden, vilket tvingar taurenfolket att ingripa innan det som ligger begravt bryter sig loss."}},faq={{q="Var ligger Boulderslide Ravine?",a="Boulderslide Ravine skär in i bergen sydost om Sun Rock Retreat i Stonetalon Mountains. Ravinen leder in i ett slingrande grottsystem som kryllar av Boulderslide-kobolder.",al={"boulderslide ravine plats","var ligger boulderslide ravine","hur hittar man boulderslide ravine"}},{q="Vem ger uppdraget Boulderslide Ravine?",a="Uppdraget ges av Mor'rogal, en tauren vid Sun Rock Retreat, Horde:s främsta utpost i Stonetalon Mountains.",al={"vem startar boulderslide ravine","uppdragsgivare boulderslide ravine","mor'rogal uppdrag"}},{q="Vad är Resonite Crystals?",a="Resonite är en sällsynt mineral som finns djupt inne i Boulderslides grottsystem. Den bär spår av titanformad Earthen-magi, vilket tyder på att kristallerna bildades nära underjordiska Earthen-reliker.",al={"vad är resonite","resonite sägner","resonite-kristaller"}},{q="Varför bryter kobolderna Resonite så frenetiskt?",a="Kobolderna snubblade över Resonite när de grävde och trängde djupt in under bergen i sin glupska jakt på glänsande malm. Där störde de en uråldrig Earthen som låg begravd i berget.",al={"varför bryter kobolder malm","boulderslide-koboldernas mål","koboldernas plan i stonetalon"}},{q="Vad är en Earthen enligt taurenfolkets sägner?",a="Enligt uråldriga sägner som Mor'rogal minns är Earthen stenhuggna varelser som titanerna smidde för länge sedan för att gräva och forma själva världens berggrund.",al={"vad är earthen","earthen och titanerna","vilka är earthen"}},{q="Vad händer när uppdraget är slutfört?",a="När Mor'rogal har identifierat den jordiska magin i Resonite-kristallerna förbereder han en förtrollad motåtgärd och erbjuder uppföljningsuppdraget 'Earthen Arise'. Han skickar dig tillbaka in i grottan för att möta det uppvaknade hotet.",al={"nästa uppdrag efter boulderslide ravine","vad följer efter boulderslide ravine","uppföljning till boulderslide ravine"}}},fx={["574c7326"]={q="Varför vill Mor'rogal att det här undersöks?",a="Mor'rogal anar en oroväckande spänning i Stonetalon Mountains och fruktar att en okänd ondska rör sig under bergstopparna. Kobolderna har börjat gräva fram märkliga Resonite-kristaller i rasande takt, och Mor'rogal behöver prover och spaningsrapporter från grottornas djup för att förstå vilka uråldriga krafter de kan vara i färd med att väcka.",al={"varför undersöka boulderslide ravine","mor'rogals motiv","varför bryr sig mor'rogal"}},["6ccd8309"]={q="Vilka skickas du att bekämpa i Boulderslide Ravine?",a="Du skickas mot kobolderna i Boulderslide som hemsöker ravinen sydost om Sun Rock Retreat. Vanligtvis är de bara asätare, men de har gripits av en febrig besatthet och gräver outtröttligt djupt under jord för att bryta Resonite-malm av skäl som hotar friden i bergstrakterna.",al={"vilka finns i boulderslide ravine","fiender i boulderslide ravine","kobolder i boulderslide ravine"}}},fp="19,126,20.449.0,22.329.1,37.134.0,40.128.0,27.177.1,51.171.1,44.128.0,41.164.1"}
P.entries["quest:643"] = {n="Sigil of Arathor",s="Efter Sigil of Thoradin berättar Zengu att människoprinsen anförtrodde ännu en sigill åt Lieutenant Valorcall, som för befäl över kavalleriet. Hitta honom och för sigillet tillbaka till Zengu i Hammerfall.",h="Efter Sigil of Thoradin berättar Zengu att människoprinsen anförtrodde ännu en sigill åt Lieutenant...",kw={"arathi highlands","hammerfall","lieutenant valorcall","sigillet av arathor","stromgarde","trol'kalar","valorcall","zengu"},sec={{t="Prinsens kavalleri",b="Zengu hånskrattar åt att människorna knappt kan kalla Stromgarde sitt eget, än mindre hela Arathi Highlands, och ändå låter deras prins sina sista ryttare rida omkring på landsbygden. Zengu förstår inte varför. Viktigare är att ett av sigillen finns hos Lieutenant Valorcall, som leder ryttarna. Zengu vill att du hittar honom och för sigillet tillbaka till Hammerfall."},{t="Till häst",b="Zengu varnar för att Valorcall är svår att hinna ikapp, eftersom hästen bär honom snabbt över landet. När han är borta väntar sig Zengu att Stromgardes försvarare får ett hårt slag, och Horden kommer att vara ett sigill från att ta Trol'kalar för sig själv."}},faq={{q="Vem skickar dig för att hitta Sigil of Arathor?",a="Ordern kommer från Zengu, som väntar i Hammerfall.",al={"uppdragsgivare för sigillet av arathor","vem ger sigillet av arathor","var hittar man sigillet av arathor"}},{q="Vem har Sigil of Arathor?",a="Lieutenant Valorcall, ledaren för människornas kavalleri, som fått sigillet av människoprinsen. Zengu säger att han rider till häst och är svår att spåra.",al={"vem har sigillet av arathor","var finns valorcall","lieutenant valorcall plats"}},{q="Varför har Lieutenant Valorcall sigillet?",a="Zengu säger att människoprinsen gav honom ett av sigillen. Zengu säger inte varför.",al={"varför har valorcall sigillet","vem gav valorcall sigillet"}},{q="Var passar detta in i Trol'kalar-kedjan?",a="Det är det femte steget i den långa Trol'kalar-kedjan. Det kommer efter Sigil of Thoradin, och Sigil of Trollbane kommer därefter.",al={"trolkalar-uppdragskedjan arathor","vad kommer före sigillet av arathor","vad kommer efter sigillet av arathor"}},{q="Vart för du sigillet när du har hittat det?",a="Tillbaka till Zengu i Hammerfall.",al={"var lämnar man in sigillet av arathor","lämna in sigillet av arathor"}}},fp="16,164,20.312.0,12.231.1,43.61.0,31.175.0,45.100.0,44.136.0,46.44.0"}
P.entries["quest:644"] = {n="Sigil of Trollbane",s="Efter Sigil of Arathor skickar Zengu dig för att döda Prince Galen Trollbane och ta den sista sigillen, den som låser upp hans far Thoras Trollbanes grav. Prinsen bär den själv, långt inne i Stromgarde.",h="Efter Sigil of Arathor skickar Zengu dig för att döda Prince Galen Trollbane och ta den sista sigillen, den...",kw={"galen trollbane","hammerfall","sigil of arathor","stromgarde","trol'kalar","zengu","zul'gurub"},sec={{t="Den sista sigillen",b="Den sista sigillen som kan öppna Thoras Trollbanes grav förvaras av Thoras son, Prince Galen, som själv bär den. Han finns långt inne i Stromgarde, i ett kapell i de områden som milisen håller. Zengu varnar dig för att Galen har gott om vakter och är en skicklig krigare, så det här kan bli mycket svårt. Du ska döda honom och ta sigillen till Zengu i Hammerfall."},{t="Zengus dom",b="Zengu frågar om Ignaeus Trollbanes släktlinje är bruten. När den väl är det förklarar han att Trollbane-blod inte längre kommer att hemsöka hans folk, och att alla sigiller som behövs för att göra anspråk på Trol'kalar nu är i deras händer. Snart, lovar han, ska de slå till mot trollen i Zul'Gurub, som han hatar."}},faq={{q="Vem skickar dig för att hämta Sigil of Trollbane?",a="Det är Zengu i Hammerfall som skickar dig.",al={"uppdragsgivare för sigil of trollbane","vem ger sigil of trollbane","var börjar jag sigil of trollbane"}},{q="Var finns Prince Galen Trollbane?",a="I ett kapell långt inne i Stromgarde, i den del som milisen håller.",al={"var finns prince galen trollbane","var är galen trollbane","galen trollbane stromgarde"}},{q="Varför behövs Sigil of Trollbane?",a="Det är den sista sigillen Zengu behöver för att öppna Thoras Trollbanes grav, och Thoras son bär den själv.",al={"syftet med sigil of trollbane","varför hämta sigil of trollbane"}},{q="Vad händer efter att du har fått Sigil of Trollbane?",a="Uppdragskedjan fortsätter med Trol'kalar.",al={"nästa uppdrag efter sigil of trollbane","vad följer efter sigil of trollbane"}}},fp="18,151,14.273.0,15.267.1,49.67.0,40.101.0,37.131.0,50.77.0"}
P.entries["quest:6441"] = {n="Satyr Horns",s="Satyr Horns är ett legosoldatskontrakt som den kringresande goblinen Pixel erbjuder vid Splintertree Post i Ashenvale. Pixel ser en lukrativ handelsmöjlighet i hamnstaden Ratchet och anlitar skickliga äventyrare från Horde för att rensa ut lokala satyrgrupper och samla in deras eftertraktade horn.",h="Satyr Horns är ett legosoldatskontrakt som den kringresande goblinen Pixel erbjuder vid Splintertree Post i...",kw={"ashenvale","night run","pixel","ratchet","satyr horns","satyrnaar","splintertree post","xavian"},ang={["class:Hunter"]="Att spåra demoniska humanoider genom korrumperade skogsruiner som Satyrnaar och Night Run sätter färdigheterna i vildmarksspårning på ett farligt prov.",["class:Warlock"]="Satyrer är genomsyrade av kraftfull felmagi, vilket gör deras kvarlevor till värdefulla kuriositeter för dem som studerar demonisk kraft.",["faction:Horde"]="Att rensa ut satyrerna i centrala Ashenvale försvagar farliga demoniska fästen som hotar Splintertree Posts bräckliga försörjningsleder."},sec={{t="En lukrativ möjlighet",b="Under en vilopaus vid Hordes främsta utpost Splintertree Post får den opportunistiska goblinresenären Pixel syn på en möjlighet på gränsmarknaden. Horn från Ashenvales demoniska satyrer är mycket efterfrågade i Ratchet i The Barrens. Pixel vill inte riskera liv och lem genom att möta de korrumperade varelserna själv, så hen anlitar äventyrare på genomresa för att samla in sexton hela horn före resan söderut."},{t="De korrumperades tillhåll",b="Ashenvales satyrer håller till i utspridda, av fel besudlade ruiner i den uråldriga skogen. De är kvarlevor från deras förräderi under den uråldriga Sunderingen. För att fullgöra Pixels beställning skickas jägarna till kända satyrfästen, däribland Night Run, Satyrnaars befästa läger och Xavians skuggiga dungar. Horn från vilket som helst av dessa tillhåll ger de värdefulla demoniska troféer som efterfrågas vid Ratchets handelsbryggor."}},faq={{q="Vem är Pixel?",a="Pixel är en företagsam goblinresenär som tillfälligt bor vid Splintertree Post i Ashenvale innan hen reser söderut mot den neutrala hamnstaden Ratchet.",al={"vem ger uppdraget","pixels historia","goblin vid splintertree"}},{q="Varför vill Ratchet ha satyrhorn?",a="Pixel berättar att satyrhorn betingar ett högt pris i Ratchet, där köpmän, alkemister och samlare av exotiska föremål gärna betalar för råa demoniska reagenser och kuriosamaterial från de nordliga skogarna.",al={"varför satyrhorn","vad används hornen till","satyrhorn i ratchet"}},{q="Var finns satyrhorn i Ashenvale?",a="Satyrer håller till i flera besudlade områden i Ashenvale. Bland de mest kända tillhållen finns Night Run, nordväst om Splintertree Post, Satyrnaar strax intill huvudvägen mot Azshara och Xavian i nordöstra Ashenvale.",al={"satyrernas platser","var hittar man satyrer","night run xavian satyrnaar"}},{q="Vad är satyrer?",a="Satyrer är uråldriga nattalver som föll offer för Burning Legions demoniska korruption för tusentals år sedan. De förvandlades till behornade bestar med klövar, tjänar mörka krafter och korrumperar aktivt skogen omkring sig.",al={"vad är en satyr","satyrernas historia","är satyrer demoner"}},{q="Varför hanteras kontraktet vid Splintertree Post?",a="Splintertree Post är Hordes främsta fästning i centrala Ashenvale. Pixel använder den som ett tryggt viloställe mellan handelsresor och anlitar Horde-krigare i närheten, som redan strider mot skogens faror.",al={"satyruppdrag vid splintertree","varför bara horde"}},{q="Är Pixel lojal mot Horde?",a="Nej. Pixel är en oberoende goblinköpman som vill gå med vinst. Precis som många gobliner med bas kring Ratchet samarbetar Pixel med den som kan erbjuda värdefulla handelsvaror, utan att bry sig om fraktionspolitik.",al={"tillhör pixel horde","pixels fraktion"}}},fx={["22d423d7"]={q="Varför vill Pixel ha satyrhorn?",a="Pixel är en företagsam resenär på väg till Ratchet med blicken riktad mot handel. Hon inser att satyrhorn betingar ett högt pris i goblinhamnen och vill göra en nätt vinst innan hon fortsätter sin resa. I stället för att själv möta de farliga bestarna betalar hon gärna dugliga äventyrare för att sköta grovjobbet, så att hon kan leverera varorna.",al={"varför vill pixel ha det här","pixels motiv för satyrhorn","varför samla satyrhorn"}},fc903cbf={q="Varför jagar Pixel inte satyrerna själv?",a="Pixel medger gärna att hon inte kan mäta sig med de våldsamma, magikunniga satyrer som lurar bland Ashenvales ruiner. Hon saknar stridsförmågan att överleva ett möte på platser som Satyrnaar eller Xavian och förlitar sig helt på erfarna legosoldater som passerar genom Splintertree Post för att skaffa varorna åt henne.",al={"varför behöver pixel mig","varför kan inte pixel hämta hornen","varför anlita en äventyrare"}}},fp="11,147,23.301.0,23.319.0,13.120.0,34.177.0,44.184.0,16.175.0,50.176.0,44.188.0"}
P.entries["quest:6442"] = {n="Naga at the Zoram Strand",s="Naga at the Zoram Strand är ett uppdrag från Horde där äventyrare ska driva bort de aggressiva ormliknande inkräktarna längs nordvästra Ashenvales kust. Trollkvinnan Marukai, som är stationerad vid Zoram'gar Outpost, vill säkra den omstridda kusten genom att driva bort Wrathtail-nagorna från ruinerna av det forna Zoram.",h="Naga at the Zoram Strand är ett uppdrag från Horde där äventyrare ska driva bort de aggressiva ormliknande...",kw={"ashenvale","marukai","nagor","wrathtail","wrathtail-huvuden","the zoram strand","zoram'gar outpost"},ang={["faction:Horde"]="Att hålla Zoram'gar Outpost är avgörande för Hordes expansion i Ashenvale. Därför är det en fråga om militär överlevnad att röja undan nagorna.",["race:Orc"]="Marukais raka strategi, att driva tillbaka fienden med brutal kraft, passar den pragmatiska krigarkulturen hos orcer som håller en gräns utpost."},sec={{t="Ett osäkert fäste",b="Hordes närvaro vid The Zoram Strand är osäker. Utposten är omgiven av fientligt Night Elf-territorium och häftiga skärmytslingar i Ashenvales skogar, och utgör en livsviktig förbindelse med kusten. Men aggressiva nagor som oväntat kravlar i land hotar att skära av Hordes tillgång till havet och övermanna den lilla garnisonen innan den hinner befästa sin position ordentligt."},{t="Det dödsdömda Zorams ekon",b="The Zoram Strands sandbankar döljer de krossade resterna av Zoram, en forntida alvstad som svaldes av den stora delningen för tusentals år sedan. Marukai och utpostens försvarare vet inte mycket om varför den ormliknande stammen Wrathtail har kravlat upp ur djuphavsravinerna just nu, men deras plötsliga intresse för de sjunkna ruinerna bådar illa för alla som rör sig ovanför ytan."},{t="Överlevnadens pris",b="Marukai ser på situationen som en fråga om enkel överlevnad: förnuft spelar ingen roll när svärd och treuddar är dragna. Genom att kräva tjugo avhuggna huvuden från Wrathtail-inkräktarna tänker hon kasta tillbaka de ormliknande monstren i djupet med ren våldskraft och säkra strandlinjen åt Horde."}},faq={{q="Vem ger uppdraget Naga at the Zoram Strand?",a="Uppdraget ges av Marukai, en troll av Darkspear-stammen som är stationerad vid Hordes utpost Zoram'gar längs The Zoram Strand i nordvästra Ashenvale.",al={"uppdragsgivare","vem startar uppdraget","var finns marukai"}},{q="Vad är historien bakom The Zoram Strand?",a="Stranden markerar platsen där den forntida, dödsdömda staden Zoram vilar. Den förstördes och sjönk under det stora havet för länge sedan under den stora delningen. Ruinerna ligger nu delvis under vatten längs Ashenvales kust.",al={"vad är zoram","zorams historia","sjunken stad"}},{q="Varför attackerar nagorna stranden?",a="Hordes garnison känner inte till den exakta anledningen till att Wrathtail-stammen har kommit. De vet bara att varelserna har strömmat upp ur djuphavet för att göra anspråk på de sjunkna ruinerna och driva bort alla som bor på land.",al={"varför är nagorna här","wrathtails motiv","nagornas mål"}},{q="Vilka fiender måste jag bekämpa i det här uppdraget?",a="Du måste döda medlemmar av Wrathtail-nagastammen som kravlar över stränderna och genom vågorna vid The Zoram Strand. Samla tjugo av deras avhuggna huvuden åt Marukai.",al={"vilka nagor","wrathtail-huvuden","fiender att bekämpa"}},{q="Vilket uppdrag följer efter Naga at the Zoram Strand?",a="Marukai ger dig inga fler uppgifter efter det här. Hon tackar dig helt enkelt och ber om att fler av dina likar ska hjälpa till att hålla stranden.",al={"nästa uppdrag","uppföljning","marukais nästa uppdrag"}},{q="Varför bryr sig Horde om den här avlägsna stranden?",a="Ashenvale är hårt omstritt mellan Horde och Night Elves. Ett säkrat brohuvud vid The Zoram Strand ger Horde strategisk tillgång till sjövägar och försörjningslinjer bort från de täta skogarna inåt landet.",al={"varför är horde här","zoram'gar outposts syfte"}}},fx={b1ee6e7c={q="Varför vill Marukai att nagorna dödas?",a="Marukai ser nagorna som ett aktivt hot mot Hordens närvaro vid strandremsan. Horden har kämpat hårt för att inta och säkra den här utposten längs Ashenvales kust. Vilka mystiska skäl de ormlika inkräktarna än har för att gå i land hotar deras växande antal att övermanna lägret om de inte gallras ut och drivs tillbaka ner i havets djup.",al={"varför vill marukai ha det här","marukais motiv","varför döda nagor vid the zoram strand"}},["7626cdcb"]={q="Vilka är Wrathtail-nagorna, och varför befinner de sig vid The Zoram Strand?",a="Wrathtail-stammen av nagor har krupit upp ur havet för att ta över ruinerna av Zoram, en uråldrig kaldoreisk stad som förstördes och hamnade under vatten under Sunderingen. Deras djupare avsikter är fortfarande okända för Hordens försvarare, men deras framskridande närvaro och fientliga angrepp längs strandlinjen gör dem till ett omedelbart hot mot alla som närmar sig stranden.",al={"vilka är wrathtail","wrathtail-nagornas bakgrund","varför är wrathtail här"}}},fp="24,178,21.310.0,22.333.0,21.242.0,45.121.0,44.207.0,37.160.0,48.151.0,44.119.0,48.177.0"}
P.entries["quest:645"] = {n="Trol'kalar",s="När du följer Sigil of Trollbane upptäcker Zengu att de fyra sigillen har bildat ett enda som kan bryta förseglingarna vid Trollbanes grav. Han skickar dig till Stromgarde för att hämta Trol'kalar från graven.",h="När du följer Sigil of Trollbane upptäcker Zengu att de fyra sigillen har bildat ett enda som kan bryta...",kw={"krypta","the sanctum","sigil of ignaeus","stromgarde","trol'kalar","trollbane","zengu"},sec={{t="Ett sigill av fyra",b="Zengu upptäcker att de fyra sigillen har förenats och bildat ett enda, Sigil of Ignaeus. Han tvivlar inte på att det kan bryta förseglingarna vid Trollbanes grav. Trollbane ligger begravd i Stromgarde, i The Sanctum bakom kapellet, och Zengu skickar dig dit för att hämta Trol'kalar. En inhägnad stig till höger om kapellets ingång leder ner till kryptan."},{t="Graven öppnas",b="Ristningarna på gravens framsida matchar sigillets egna lysande linjer. Rikta in det ena med det andra, så slukar en ljusblixt sigillet och frigör det legendariska svärdet Trol'kalar från stenhänderna som höll fast det."}},faq={{q="Vem skickar dig för att hämta Trol'kalar?",a="Zengu, efter att de fyra sigillen förenats till Sigil of Ignaeus.",al={"vem ger uppdraget","uppdragsgivare","zengu"}},{q="Var ligger Trollbanes grav?",a="Hans kvarlevor ligger i The Sanctum bakom kapellet i Stromgarde. En inhägnad stig till höger om kapellets ingång leder ner till kryptan.",al={"var ligger graven","gravens plats","kryptans plats"}},{q="Vad händer med de fyra sigillen?",a="De förenas och bildar ett enda sigill, Sigil of Ignaeus, som Zengu tror kan bryta förseglingarna vid Trollbanes grav.",al={"vad hände med sigillen","sigil of ignaeus"}},{q="Vilket är det föregående steget i den här kedjan?",a="Sigil of Trollbane, det sista av de fyra sigillen, kommer före detta.",al={"föregående uppdrag","tidigare uppdrag","sigil of trollbane"}}},fp="10,89,19.309.0,14.196.1,37.91.0,34.139.0,32.108.0,40.67.0"}
P.entries["quest:646"] = {n="Trol'kalar",s="Den långa Trol'kalar-kedjan når sitt sista steg. Ljuset bleknar långsamt, och Trol'kalar, innesluten i en stenhylsa, frigörs. Bär den till Zengu i Hammerfall.",h="Den långa Trol'kalar-kedjan når sitt sista steg.",kw={"arathi","hammerfall","nimboya","trol'kalar","trollbane","zengu","zul'gurub"},sec={{t="Ett svärd befrias",b="Vid Trollbane's Tomb bleknar ljuset långsamt, och Trol'kalar, förvarad i en stenhylsa, frigörs. Du tar det hylsade svärdet till Zengu i Hammerfall, i Arathi Highlands."},{t="Vad Zengu säger",b="Zengu berättar att Stroms och Arathors styrkor jagade trollen i generation efter generation, och att deras främsta vapen nu finns i hans folks händer. Den långsamma framryckningen in i Zul'Gurubs fuktiga skogar kommer inte längre att vara en kamp. Han säger att Darkspear-trollen står i skuld till dig och att han ska se till att svärdet levereras till Nimboya i Grom'gol."}},faq={{q="Vart ska Trol'kalar föras?",a="Till Zengu i Hammerfall, i Arathi Highlands. Svärdet når dig fortfarande i sin stenhylsa.",al={"vart ska jag ta trolkalar","överlämning av trol'kalar","lämna in trolkalar"}},{q="Var hittar jag svärdet?",a="Vid Trollbane's Tomb, där det bleknande ljuset har frigjort det från dess stenhylsa.",al={"var finns trol'kalar","trolkalar-plats"}},{q="Vad hände före det här steget?",a="Det här är det sista steget i den långa Trol'kalar-kedjan och följer på det tidigare Trol'kalar-steget.",al={"tidigare trol'kalar","trolkalar-kedja"}}},fp="10,126,16.144.0,15.298.1,33.92.0,26.94.0,27.80.0"}
P.entries["quest:6461"] = {n="Blood Feeders",s="Blood Feeders är ett jaktuppdrag för Horden som Xen'Zilla ger i Darkspear-bosättningen Malaka'jin. De lokala trollen har hittat gott om villebråd längs Stonetalon Mountains sluttningar, men lukten av deras slaktade kött har lockat svärmar av rovlystna Deepmoss-spindlar ner till lägren.",h="Blood Feeders är ett jaktuppdrag för Horden som Xen'Zilla ger i Darkspear-bosättningen Malaka'jin.",kw={"blood feeders","deepmoss creeper","deepmoss venomspitter","malaka'jin","sishir canyon","spindlar","stonetalon","xen'zilla"},ang={["class:Hunter"]="Att spåra farliga rovdjur som jagar bättre än och trakasserar vänligt sinnade bosättningar är ett naturligt uppdrag för skickliga spårare som rör sig genom klippterrängen.",["faction:Horde"]="Malaka'jin säkrar Hordens tillfartsväg från norra The Barrens in i Stonetalon Mountains. Att skydda byn säkrar hela det södra passet.",["race:Troll"]="Jägarna i Malaka'jin är släkt och kämpar för att skapa ett självförsörjande område i Kalimdors karga högland utan att gå under i vildmarken."},sec={{t="Oönskade middagsgäster",b="Trollen som grundade utposten Malaka'jin i sydöstra Stonetalon Mountains kom dit för att hitta god jakt. De klippiga sluttningarna visade sig vara rika på villebråd, men köttet och bytet de förde tillbaka väckte snart nattliga rovdjurs uppmärksamhet. Deepmoss-spindlar, aggressiva spindeldjur som hör hemma bland klipporna och ravinerna i norr, började smyga in i lägret i skydd av mörkret för att stjäla deras förråd eller göra jägarna till byte."},{t="Rensa klipporna",b="För att hålla lägret tryggt och skydda förråden ber Xen'Zilla äventyrare att spåra rovdjuren norrut in i bergspassen. Deepmoss Creepers och Venomspitters är som flest runt de klippiga ravinerna och spindelvävarna i Sishir Canyon. När deras antal minskar trängs ynglet tillbaka från Malaka'jins gränser, så att byn kan vila utan att frukta bakhåll ur skuggorna."}},faq={{q="Vem ger uppdraget Blood Feeders?",a="Xen'Zilla, ett Darkspear-troll som bor i byn Malaka'jin i sydöstra Stonetalon Mountains, ger uppdraget till resande hjältar från Horden.",al={"vem ger blood feeders","blood feeders uppdragsgivare","xen'zilla uppdrag"}},{q="Varför anfaller spindlarna Malaka'jin?",a="Trollen i Malaka'jin jagar det lokala villebrådet i stor omfattning. Lukten av färskt byte och torkande kött lockar Deepmoss-spindlarna ner från bergspassen om natten för att stjäla förråd och jaga byborna.",al={"varför anfaller spindlar","spindlar anfaller malaka'jin","varför invaderar spindlar"}},{q="Var finns Deepmoss-spindlarna?",a="Deepmoss Creepers och Venomspitters strövar genom de centrala passen och klipporna norr om Malaka'jin. Särskilt många håller till i den spindelvävstäckta ravinen Sishir Canyon.",al={"var finns deepmoss-spindlar","deepmoss creepers plats","deepmoss venomspitter plats"}},{q="Vad är Malaka'jin?",a="Malaka'jin är ett Darkspear-trolläger vid den södra ingången till Stonetalon Mountains, nära gränsen mot The Barrens. Det fungerar som jaktbas vid gränsen och som utpost för Horden.",al={"vad är malaka'jin","malaka'jin bakgrund","trollby i stonetalon"}},{q="Finns det ett större hot kopplat till de här spindlarna?",a="Långt inne i Sishir Canyon, bland spindelvävarna, lever en enorm och dödlig spindelmatriark. En varningsskylt utanför ravinen varnar resande för faran och uppmanar grupper att fälla henne.",al={"stor spindel i stonetalon","sishir canyon elitspindel","spindelmatriark i stonetalon"}},{q="Vad händer när spindlarna har gallrats ut?",a="När Creepers och Venomspitters gallras ut får Malaka'jin andrum. Trolljägarna kan säkra sina köttförråd och röra sig genom lägren om natten utan att ständigt riskera bakhåll.",al={"efter blood feeders","blir malaka'jin säkert"}}},fx={["5b921468"]={q="Vad gör Deepmoss-spindlarna i Stonetalon Mountains?",a="Deepmoss creepers och venomspitters är inhemska spindeldjur som stryker omkring bland klipporna och ravinerna i Stonetalon Mountains. De har alltid levt bland klipporna, men lukten av färskt byte som trolljägare fört till Malaka'jin har lockat dem närmare civilisationen. Nu har de blivit djärvare. Dessa aggressiva rovdjur smyger aktivt ner från de klippiga höjderna för att plundra byns läger i skydd av mörkret.",al={"deepmoss-spindlar i stonetalon","deepmoss creepers och venomspitters","varför är spindlarna här"}}},fp="13,179,22.391.0,18.377.0,35.138.0,41.210.0,39.164.0,19.173.0,48.179.0,42.169.0"}
P.entries["quest:6462"] = {n="Troll Charm",s="Troll Charm är ett Horde-uppdrag som ges av Darkspear-trollet Mitsuwa vid Zoram'gar Outpost i Ashenvale. Efter att en resande grupp troll överfölls och slaktades av Thistlefur-furbolgerna ber Mitsuwa äventyrare att ta sig in i deras håla och återta heliga talismaner som stulits från de döda.",h="Troll Charm är ett Horde-uppdrag som ges av Darkspear-trollet Mitsuwa vid Zoram'gar Outpost i Ashenvale.",kw={"ashenvale","darkspear","furbolg","mitsuwa","thistlefur hold","thistlefur village","troll charm","zoram'gar outpost"},ang={["faction:Horde"]="Genom att tränga in på Thistlefurs område slår man tillbaka mot hot i skogen som överfaller Hordes försörjningslinjer och resande genom Ashenvale.",["race:Troll"]="Att återta amuletterna är en andlig plikt för Darkspear-trollen och räddar heliga förfädersföremål från de vilda furbolgernas klor."},sec={{t="En överfallen karavan",b="Zoram'gar Outpost är en avlägsen tillflyktsort för Horde på Ashenvales västkust, vilket gör färder längs skogsstigarna farliga. En grupp Darkspear-troll som var på väg mot utposten kom aldrig fram, utan föll offer för ett våldsamt överfall från den revirhävdande Thistlefur-stammen av furbolger. Mitsuwa accepterar att hans fränder har dött och en dag återförenas med honom i livet efter detta, men skändningen och stölden av deras heliga amuletter är en outhärdlig förolämpning."},{t="Heliga prydnader",b="I trollkulturen är amuletter och talismaner starkt knutna till identitet, andligt beskydd och kontakten med Loa. Mitsuwa anser att ett troll utan sin amulett är lika tomt och värdelöst som en orch utan stridsärr. Thistlefur-furbolgerna släpade de stulna föremålen tillbaka till Thistlefur Hold, djupt inne i grottsystemen bortom Thistlefur Village, och gömde dem i kistor långt från deras rättmätiga ägare."}},faq={{q="Vem ger uppdraget och var finns personen?",a="Uppdraget ges av Mitsuwa, ett Darkspear-troll som är stationerat vid Zoram'gar Outpost längs The Zoram Strand på Ashenvales nordvästra kust.",al={"uppdragsgivare","var finns mitsuwa","vem startar troll charm"}},{q="Varför är trollamuletterna så viktiga för Mitsuwa?",a="För troll har heliga amuletter en djup andlig och kulturell betydelse. Mitsuwa jämför ett troll utan sin amulett med en orch utan stridsärr och ser de fientliga furbolgernas innehav av relikerna som en skandalös skändning av sina dödade fränder.",al={"amuletternas betydelse","varför trollamuletter är viktiga","amuletternas innebörd"}},{q="Var finns trollamuletterna?",a="Amuletterna förvaras i kistor inne i Thistlefur Hold, ett djupt grottkomplex vid norra kanten av Thistlefur Village, norr om Night Elf-bosättningen Astranaar.",al={"amuletternas plats","var finns kistorna","hitta amuletterna"}},{q="Vem stal amuletterna?",a="Thistlefur-furbolgerna överföll och dödade Mitsuwas fränder när de färdades mot Zoram'gar Outpost, plundrade deras tillhörigheter och släpade med sig de heliga amuletterna in i sina grottor.",al={"vem tog amuletterna","vilka låg bakom överfallet"}},{q="Vad hände med trollen som ursprungligen bar amuletterna?",a="De dödades av Thistlefur-furbolgerna längs stigen. Mitsuwa sörjer deras förlust men tror att han en dag återförenas med dem i livet efter detta, och prioriterar att återta deras heliga reliker.",al={"karavanens öde","dödade troll","mitsuwas fränder"}},{q="Är uppdraget tillgängligt för Alliance?",a="Nej. Uppdraget börjar vid Zoram'gar Outpost och är endast tillgängligt för Horde-spelare som hjälper Darkspear-stammen.",al={"alliance troll charm","kan alliance göra det"}}},fx={["3db0517e"]={q="Vad är Troll Charm?",a="Dessa amuletter är djupt heliga reliker som bärs av Darkspear-trollen. I deras kultur står en amulett för heder, identitet och andlig tillhörighet. Som Mitsuwa uttrycker det är ett troll utan sin amulett lika ihåligt och värdelöst som en orch utan stridsärr. Även om deras fallna ägare återförenas med sina fränder i livet efter detta, är det en outhärdlig skymf mot deras minne att låta dessa vördnadsvärda föremål förbli nedsölade i vilda bestars händer.",al={"troll charm-lore","vad gör troll charm","vad är troll charms"}}},fp="11,155,19.358.0,15.388.0,48.112.0,49.198.0,35.134.0,21.159.0,62.173.0,40.58.0"}
P.entries["quest:647"] = {n="MacKreel's Moonshine",s="MacKreel's Moonshine är ett fartfyllt ärende åt Foggy MacKreel, en dvärg som strandat på den trasiga delen av Thandol Span. Efter att ha druckit för mycket av sitt eget starka brygd och sovit sig igenom vakten ber Foggy en resenär från Alliansen att skynda en ny sats till Hillsbrad och reglera en gammal skuld till Brewmeister Bilger i Southshore.",h="MacKreel's Moonshine är ett fartfyllt ärende åt Foggy MacKreel, en dvärg som strandat på den trasiga delen av...",kw={"bilger","foggy","longbraid","mackreel","menethil","månsken","southshore"},ang={["faction:Alliance"]="Den här snabba färden landvägen visar den viktiga förbindelsen mellan Thandol Span och det allianskontrollerade Southshore i Hillsbrad.",["race:Dwarf"]="Dvärgar förstår genast den dubbla olyckan med en plågsam baksmälla och en obetald bryggskuld till en frände."},sec={{t="Baksmälla på vakten",b="Vaktlivet på den sönderslagna Thandol Span är blött, kallt och ökänt långtråkigt. Foggy MacKreel står ut med fukten och kylan genom att dricka sin egen hembrända månsken, ett brygd så starkt att han liknar efterdyningarna vid en hel brigad belägringsmaskiner som rullar över hans skalle. Tyvärr för Foggy fick en drink för mycket honom att svimma under sitt pass. Med Longbraid the Grim som befälhavare över dvärgarna som försvarar Span har Foggy inte råd med fler disciplinbrott."},{t="En kamp mot klockan",b="Foggy har dessutom en gammal skuld till Brewmeister Bilger i Southshore. Foggy lovade Bilger en sats av sitt eget brygd för att jämna ut räkenskaperna, men mellan baksmällan och vakttjänsten har han bara några minuter kvar innan tidsfristen går ut. Med hjälp av gripar och snabba fötter måste resenärer skynda över Arathi Highlands till Southshore och leverera kannan innan Bilger återigen bestämmer sig för att Foggy har smitit från notan."}},faq={{q="Vem är Foggy MacKreel?",a="Foggy MacKreel är en dvärg på den trasiga delen av Thandol Span, dit man kommer från sidan vid Arathi Highlands. Han är känd för att brygga extremt starkt hembränt månsken och brukar provsmaka sin egen produkt lite väl frikostigt under tjänstgöringen.",al={"foggy mackreel","vem är foggy","uppdragsgivare mackreel"}},{q="Varför är leveransen så brådskande?",a="Foggy hamnade rejält efter i tidtabellen när han söp sig medvetslös under vakten. Han har en sträng tidsfrist för att leverera månskenet till Brewmeister Bilger och reglera en förfallen nota, så det finns knappt en kvart på sig att ta sig från Thandol Span till Southshore.",al={"varför finns det en timer","varför 15 minuter","mackreels månsken timer"}},{q="Vem är Brewmeister Bilger?",a="Brewmeister Bilger är en mästerlig dvärgbryggare som verkar i kustbosättningen Southshore i Hillsbrad Foothills. Han uppskattar stark alkohol och har en utestående affärsöverenskommelse med Foggy MacKreel.",al={"brewmeister bilger","vem är bilger","bilger southshore"}},{q="Hur hinner man leverera månskenet till Southshore?",a="Det går ingen båt från Span till Southshore. Den snabbaste vägen är att ta sig till Arathi Highlands och flyga med grip från Refuge Pointe till Southshore, om du kan flygrutten, och sedan hitta Brewmeister Bilger i staden innan tiden går ut.",al={"hur levererar man månsken","snabbaste vägen till southshore mackreel","leveransväg för månsken"}},{q="Vem är Longbraid?",a="Longbraid the Grim är dvärgbefälhavaren som är stationerad utanför Dun Modr i Wetlands och leder försvararna av Thandol Span. Foggy fasar fullständigt för att Longbraid ska upptäcka att han drack sig medvetslös när han skulle hålla vakt.",al={"kapten longbraid","longbraid menethil"}}},fx={d39890fd={q="Varför kan inte Foggy MacKreel leverera hembrännvinet själv?",a="Foggy MacKreel drack alldeles för mycket av sitt eget hembrännvin kvällen innan och tuppade av under sitt vaktpass. Han har bultande huvudvärk, måste stå till svars inför Longbraid the Grim för sin officiella vaktpost och har ont om tid att betala sina skulder till Brewmeister Bilger. Han är inte i skick att ge sig av till Southshore på egen hand.",al={"varför jag mackreel","varför leverera hembrännvin","foggy hembrännvin varför jag"}}},fp="20,211,18.422.0,24.368.0,22.183.0,31.217.0,26.206.0,53.196.0,17.208.0"}
P.entries["quest:648"] = {n="Rescue OOX-17/TN!",s="Den skadade målsökande roboten OOX-17/TN talar med Oglethorpes röst. Den behöver en öppen, säker plats för en lång startprocedur, och du ombeds eskortera den säkert till Steamwheedle Port och sedan hitta Oglethorpe Obnoticus i Booty Bay.",h="Den skadade målsökande roboten OOX-17/TN talar med Oglethorpes röst.",kw={"booty bay","målsökande robot","mekanisk kyckling","oglethorpe obnoticus","oox-17/tn","steamwheedle port","tanaris"},sec={{t="Eskort till hamnen",b="Oglethorpes röst knastrar åter från roboten. Robotens inbyggda kamouflage behöver repareras, men Oglethorpe behöver tid för att få det att fungera igen. Därför måste roboten nå en öppen, säker plats där den långa startproceduren kan börja. Oglethorpe har tänkt sig Steamwheedle Port, och resan ger den tid som behövs för att få allt att fungera. Din uppgift är att eskortera roboten dit säkert."},{t="Rapportera i Booty Bay",b="När roboten är säkert framme vid hamnen ombeds du leta efter Oglethorpe Obnoticus, en mästerlig uppfinnare, i Booty Bay."},{t="En tacksam uppfinnare",b="Oglethorpe hälsar dig som den som räddade OOX-17/TN. Serien av målsökande robotar behöver fortfarande vidareutvecklas, men att få tillbaka den här har sparat otaliga timmar av återuppbyggnad och en hel del guldmynt i kostnader för att binda om den. Oglethorpe säger att både robotarna och uppfinnaren står i skuld till dig."}},faq={{q="Vart måste roboten eskorteras?",a="Till Steamwheedle Port, där den säkert kan påbörja starten.",al={"vart ska oox-17","oox-17:s eskortväg","robotens destination"}},{q="Vem talar genom roboten?",a="Oglethorpe Obnoticus, en gnom och mästerlig uppfinnare, som äger den här målsökande roboten. Du hittar uppfinnaren i Booty Bay.",al={"vem byggde oox-17","oox-17:s skapare","vem talar genom roboten"}},{q="Varför måste roboten flyttas?",a="Den behöver en öppen, säker plats för att påbörja en lång startprocedur. Dess inbyggda kamouflage behöver också tid för att fungera igen.",al={"varför flytta oox-17","varför till steamwheedle port"}},{q="Var rapporterar du efter eskorten?",a="Oglethorpe Obnoticus väntar i Booty Bay.",al={"var finns oglethorpe obnoticus","vem lämnar jag uppdraget till","var lämnar jag in oox-17"}}},fp="17,190,21.343.0,19.106.0,19.271.1,41.86.0,34.114.0,36.119.0,37.44.0"}
P.entries["quest:6481"] = {n="Earthen Arise",s="Djupt inne i Boulderslide Ravine upptäcker schamanen Mor'rogal en slumrande Earthen, Goggeroc, förseglad i en Resonite-tunna. Av rädsla för den råa förstörelsekraft som en uråldrig varelse av sten skulle kunna släppa lös över Kalimdor skickar han en mästare för att krossa tunnan och fälla Goggeroc innan varelsen återfår hela sin styrka.",h="Djupt inne i Boulderslide Ravine upptäcker schamanen Mor'rogal en slumrande Earthen, Goggeroc, förseglad i en...",kw={"boulderslide ravine","earthen","earthen arise","goggeroc","mor'rogal","resonite-tunna","schaman","stonetalon mountains"},ang={["class:Shaman"]="Mor'rogal kanaliserar schamansk kraft för att manipulera Resonite Crystal och rubba den elementära balansen som håller Earthen fången i sin tunna.",["faction:Horde"]="Genom att döda Goggeroc säkrar Hordens mästare sin närvaro i Stonetalon omstridda bergskammar och vinner samtidigt Thunder Bluffs lednings bestående respekt.",["race:Tauren"]="Stonetalon är helig, förfäders jaktmark för Thunder Bluffs stammar, och att oskadliggöra en uråldrig, förödande varelse djupt bland dess toppar skyddar landet från undergång."},sec={{t="En slummer i sten",b="Under undersökningen av skadedjursinvasionen i Boulderslide Ravine upptäckte spejare en märklig relik bland kobolderna: en Resonite-tunna som utstrålade en övernaturlig kraft. Mor'rogal, en tauren-schaman stationerad i Stonetalon Mountains, insåg vad behållaren verkligen var – ett fängelse och en fristad som hyste Goggeroc, en vilande Earthen. Dessa uråldriga stenskapelser besitter en styrka som överträffar dödliga krigare, vilket gör risken att Goggeroc strövar fritt till ett existentiellt hot mot regionen."},{t="Resonite Crystal",b="Om en Earthen vaknar med full kraft väntar katastrof för Stonetalon. För att jämna ut oddsen ändrade Mor'rogal blandningen av Resonite Crystal som förts till honom och genomsyrade dem med schamanmagi. Den förtrollade kristallen är utformad för att krossa Resonite-tunnan med sådan kraft att Goggeroc väcks i ett kraftigt försvagat tillstånd. Det är Hordens krigare som måste slå sönder behållaren och fälla den desorienterade titanformade varelsen innan den skakar av sig århundraden av dvala."}},faq={{q="Vem är Mor'rogal?",a="Mor'rogal är en tauren-schaman stationerad i Stonetalon Mountains. Han studerar oroligheterna i regionen och använder sin elementarmagi för att bedöma de märkliga uråldriga artefakter och hot som grävts fram av traktens skadedjur.",al={"mor rogal","vem är uppdragsgivaren","orkschamanen morrogal"}},{q="Vad är en Earthen?",a="Earthen är uråldriga varelser smidda av levande sten, skapelser som titanerna lämnade efter sig vid världens gryning. De har ett djupt band till jorden och en häpnadsväckande fysisk styrka, och har sovit begravda över hela Kalimdor och Eastern Kingdoms i årtusenden.",al={"vad är earthen","earthen-lore","vilka är earthen"}},{q="Varför vill Mor'rogal döda Goggeroc?",a="Mor'rogal fruktar att en aktiv Earthen med sin oöverträffade styrka skulle innebära katastrof för Stonetalon och hela Kalimdor. Eftersom sådana uråldriga varelser är oförutsägbara och oerhört mäktiga tror han att det enda sättet att skydda landet är att förgöra Goggeroc medan den är försvagad efter sin slummer.",al={"varför döda goggeroc","är goggeroc ond","varför fälla earthen"}},{q="Var finns Goggeroc?",a="Goggeroc ligger begravd i en Resonite-tunna djupt inne i grottorna i Boulderslide Ravine, i sydöstra Stonetalon Mountains. Runt omkring finns Boulderslide-kobolderna, som gräver sig genom grottorna.",al={"var finns tunnan","goggerocs plats","hitta resonite-tunnan"}},{q="Hur väcker du Goggeroc?",a="Använd Enchanted Resonite Crystal som Mor'rogal gett dig direkt på Resonite-tunnan i grottan. Den magiskt förändrade kristallen spräcker behållaren och tvingar den slumrande Earthen upp till ytan.",al={"hur åkallar man goggeroc","använd enchanted resonite crystal","öppna tunnan"}},{q="Vad händer när Goggeroc har dödats?",a="När du återvänder till Mor'rogal med beskedet om Goggerocs död lättar schamanens djupa fruktan. Han hyllar dig som en hjälte vars handling har avvärjt en enorm katastrof, och du vinner stor ära och aktning bland Thunder Bluffs tauren.",al={"berättelse om uppdragsbelöning","morrogals reaktion","lämna in earthen arise"}}},fx={["7cc06600"]={q="Vem är Goggeroc och varför är han i Stonetalon?",a="Goggeroc är en uråldrig Earthen, en varelse av levande sten som titanerna skapade för länge sedan. Han förseglades i en Resonite-tunna djupt inne i grottan i Boulderslide Ravine och har sedan dess sovit under Stonetalon Mountains. Mor'rogal varnar för att om en Earthen vaknar med full kraft blir hans oöverträffade styrka ett katastrofalt hot mot Stonetalon och hela Kalimdor. Om du slår sönder tunnan fångar du honom medan han ännu är omtöcknad och försvagad efter den långa sömnen, vilket ger dig din enda chans att besegra honom.",al={"vem är goggeroc","goggeroc-lore","vad är goggeroc"}},["9f2ce835"]={q="Varför behöver Mor'rogal att du besegrar Goggeroc i stället för att själv möta honom?",a="Mor'rogal använder sina shamanska krafter vid Sun Rock Retreat för att förändra Resonite-kristallerna du samlade in. Han skickar tillbaka dig till grottan med den förtrollade kristallen, så att du kan öppna Goggerocs tunna och slå till medan Earthen är försvagad efter sin långa sömn.",al={"varför slåss inte mor'rogal mot goggeroc","varför jag","varför skicka mig mot goggeroc"}}},fp="13,240,18.369.0,20.369.1,17.197.0,19.223.0,38.193.0,26.172.0,27.179.0,37.204.1"}
P.entries["quest:6482"] = {n="Freedom to Ruul",s="Djupt inne i Thistlefur Hold i norra Ashenvale väntar en fångad björn vid namn Ruul på att räddas från de korrumperade Thistlefur-furbolgerna. Hordens äventyrare kan hjälpa fången att kämpa sig ut ur furbolgernas håla till säkerheten.",h="Djupt inne i Thistlefur Hold i norra Ashenvale väntar en fångad björn vid namn Ruul på att räddas från de...",kw={"ashenvale","druideskort","furbolg","ruul snowhoof","splintertree post","thistlefur hold","yama snowhoof"},ang={["class:Druid"]="Ruuls tillfångatagande påminner ödmjukande om riskerna med att färdas genom vilda områden i djurgestalt, där korrumperade invånare inte kan skilja vän från byte.",["faction:Horde"]="Varje själ som räddas ur de korrumperade hålorna i norra Ashenvale stärker Hordens utsatta utpost vid Splintertree Post.",["race:Tauren"]="Att rädda en strandsatt broder ur Cenarion Circle och stilla oron hos hans närmaste vid Splintertree Post hedrar banden till Jordmodern och Horden."},sec={{t="En druid i bojor",b="När druiden Ruul Snowhoof färdades genom de korrumperade skogarna i norra Ashenvale kom han för nära Thistlefur Hold i sin björnform. De korrumperade furbolgerna, som saknade sina förfäders visdom och drevs av vild paranoia, tog den skepnadsskiftande taurenen för ett vanligt djur. I stället för att visa honom vördnad satte de honom i bur och lät honom svälta. Det tömde hans magiska krafter och gjorde honom oförmögen att ta sig loss på egen hand."},{t="Flykt från hålan",b="Försvagad av hunger och fångenskap kan Ruul varken skifta form eller kämpa sig genom furbolgernas vidsträckta bosättning utan hjälp. När en allierad till Horden befriar honom förlitar han sig på sin räddare för att röja en väg förbi våg efter våg av fientliga Thistlefur-furbolger. När han når utkanten av Splintertree Post i säkerhet visar han kort sin sanna taurenform och tackar räddaren innerligt. Sedan återvänder han till vildmarken för att sova bort utmattningen."}},faq={{q="Varför låste furbolgerna in Ruul Snowhoof?",a="Ruul utforskade skogarna i björnform. De korrumperade Thistlefur-furbolgerna kände inte igen honom som druid, utan tog honom för ett vilt djur. De låste in honom i en bur och lät honom svälta tills han saknade kraft att fly.",al={"varför är ruul fångad","hur blev ruul tillfångatagen","varför sattes han i bur"}},{q="Vem är Yama Snowhoof?",a="Yama Snowhoof är Ruuls syster och är stationerad vid Splintertree Post i Ashenvale. Hon hade blivit mycket orolig när Ruul försvann in i skogen flera dagar tidigare och inte återvände.",al={"ruuls syster","yama splintertree","vem är yama"}},{q="Varför kunde Ruul inte bara skifta form och fly?",a="Den långvariga fångenskapen och den avsiktliga svälten som Thistlefur-furbolgerna utsatte Ruul för gjorde honom mycket svag. Utan mat och kraft var hans förråd av naturlig energi helt tömda, och han var hjälplös tills någon räddade honom.",al={"varför skiftade ruul inte form","druid björnfälla"}},{q="Vad händer när Ruul når säkerheten?",a="När han eskorterats ut ur den fientliga hålan till gränsen vid Splintertree Post skiftar Ruul kort till sin naturliga taurenform för att uttrycka sin tacksamhet. Sedan återgår han till björnform och söker upp en lugn plats där han kan sova och återhämta sig.",al={"vart tar ruul vägen","ruuls slut"}},{q="Är alla furbolger i Ashenvale fientliga som Thistlefur-furbolgerna?",a="Nej. Många furbolgstammar har ett ädelt arv och starka band till naturen, men Thistlefur-furbolgerna i norra Ashenvale har fallit offer för mörka, korrumperande krafter som gjort dem aggressiva och oberäkneliga.",al={"är furbolger onda","thistlefur-korruption"}},{q="Var äger räddningen rum?",a="Ruul hålls fången inne i Thistlefur Hold, en furbolghåla i kullarna nordväst om Splintertree Post och norr om Astranaar i Ashenvale.",al={"var är ruul","ruul snowhoofs plats"}}},fx={cd4f3bf3={q="Varför behöver Ruul Snowhoof att du eskorterar honom i stället för att fly på egen hand?",a="Ruul har suttit fångad i en Thistlefur-bur i flera dagar och fått utstå svält och fångenskap hos de korrumperade furbolgerna. Hans fysiska styrka är nästan helt förbrukad. Försvagad och undernärd, djupt inne i fientliga Thistlefur Hold, kan han inte ensam kämpa sig förbi stammen som omringar honom. Han behöver din hjälp för att bana väg till friheten.",al={"varför behöver ruul hjälp","varför kan ruul inte fly ensam","varför jag ruul snowhoof"}}},fp="15,223,17.433.0,19.421.1,48.238.1,21.176.0,56.235.1,39.229.1,59.215.0,33.145.0"}
P.entries["quest:65"] = {n="The Defias Brotherhood",s="I Westfall hotar Defias Brotherhoods tjuvar gårdarna och vägarna. Gryan Stoutmantle skickar dig från Sentinel Hill österut till Redridge för att söka upp en kontakt som kanske vet var de håller till.",h="I Westfall hotar Defias Brotherhoods tjuvar gårdarna och vägarna.",kw={"defias","gryan stoutmantle","lakeshire","redridge","sentinel hill","westfall","wiley the black"},ang={["class:Rogue"]="Som skurk vet du att det inte går att avslöja ett kriminellt syndikat med bara soldatkunskaper. Stoutmantle vänder sig till någon som förstår skuggor och gentjänster på gatan: Wiley the Black.",["faction:Alliance"]="Som resenär i Alliance färdas du från Westfall till Redridge, där gränstrakterna är beroende av varandra medan Stormwind försummar dem."},sec={{t="Hotet i dammet",b="Skördarna i Westfall är borta, och banditer med röda bandanas strövar omkring i trakten. Gryan Stoutmantle och People's Militia håller Sentinel Hill under nästan ständiga angrepp, men de vet inte vem som styr deras fiender. Stoutmantle vet att det inte räcker att bekämpa kringströvande plundrare för att rädda regionen. Han måste hitta kartellens innersta krets och ta reda på vem som leder den."},{t="En kontakt från trakten",b="Gryan Stoutmantle lägger militära kanaler och Stormwinds frånvarande adelsmän åt sidan och kontaktar någon han känner. Han skickar betrodda äventyrare österut, genom Elwynn och in i Redridge Mountains. I Lakeshire väntar Wiley the Black på övervåningen i det lokala värdshuset, i en stillsam by vid sjön. Skurken känner den undre världen bättre än någon miliskapten och kan ge den första ledtråden till var Brotherhood håller till."}},faq={{q="Vem är Gryan Stoutmantle?",a="Gryan Stoutmantle leder People's Militia, en brokig försvarsstyrka med bas i Sentinel Hill i Westfall. Medan Stormwind försummar gränstrakterna samordnar han försvaret av de få bönder och flyktingar som fortfarande finns där.",al={"gryan stoutmantle","vem ger uppdraget","uppdragsgivare i westfall"}},{q="Varför skickar Stoutmantle dig till Lakeshire?",a="People's Militia saknar informatörer i Westfalls undre värld. Gryan Stoutmantle åberopar en gammal gentjänst från Wiley the Black, en skurk på Lakeshire Inn, och hoppas att hans kriminella kontakter ska avslöja vem som leder tjuvarna.",al={"varför lakeshire","varför resa till redridge","varför wiley"}},{q="Vem är Wiley the Black?",a="Wiley the Black är en skurk som bor på andra våningen i Lakeshire Inn i Redridge Mountains. Han står i skuld till Gryan Stoutmantle och kan dela med sig av rykten från den undre världen och kriminella kontakter.",al={"vem är wiley","wiley i lakeshire","wiley the black"}},{q="Vad är Defias Brotherhood?",a="I Westfall bär Defias Brotherhoods tjuvar röda bandanas och har tagit över gårdar, vägar och övergivna gruvor. De driver bort nybyggare och utmanar Stormwinds auktoritet.",al={"defias brotherhood","vad är defias","banditer med röda bandanas"}},{q="Var hittar jag Wiley i Lakeshire?",a="Wiley the Black är på övervåningen, på andra våningen i Lakeshire Inn, nära bron i staden Lakeshire i Redridge Mountains.",al={"var finns wiley","hitta wiley","wileys plats"}},{q="Innebär det här uppdraget strid?",a="Nej. Du reser från Sentinel Hill i Westfall genom Elwynn Forest till värdshuset i Lakeshire för att träffa Wiley.",al={"är uppdraget svårt","strid i uppdraget defias brotherhood","fiender"}}},fx={e3561313={q="Varför behöver Gryan Stoutmantle en äventyrare i stället för sin egen People's Militia?",a="Gryan Stoutmantles People's Militia har fullt upp med att försvara Sentinel Hill och skydda de få bönder som finns kvar i Westfall. Stormwind vägrar skicka kungliga förstärkningar, så det lokala försvaret har desperat ont om folk. Dessutom behöver Stoutmantle särskilt en utomstående som kan infiltrera fienden i hemlighet. Lokala milissoldater skulle kännas igen och upptäckas av Defias-väktare direkt.",al={"varför skicka mig","varför inte skicka milisen","varför behöver stoutmantle en äventyrare"}}},fp="22,127,22.168.0,22.188.0,25.219.0,43.215.0,23.194.0,31.179.0,36.130.0,35.102.0"}
P.entries["quest:6503"] = {n="Ashenvale Outrunners",s="Ashenvale Outrunners är ett uppdrag där Horde ska genskjuta patruller, utdelat av Kuray'bin i Ashenvale. Night Elf-spejare har spritt ut sig från Silverwing Outpost för att samla information om Hordes närliggande läger. Därför inleder Horde ett förebyggande anfall för att hålla utpostens försvar hemligt. Genom att jaga rätt på dessa smygande spejare förblindar Horde de lokala Alliance-styrkorna och avskräcker från framtida intrång.",h="Ashenvale Outrunners är ett uppdrag där Horde ska genskjuta patruller, utdelat av Kuray'bin i Ashenvale.",kw={"alliance","ashenvale","ashenvale outrunners","horde","kuray'bin","night elf-spejare","silverwing outpost"},ang={["class:Hunter"]="Att spåra upp dolda spejare i djupa skogsområden kräver skarpa instinkter, vässade spårningssinnen och säker träffsäkerhet.",["class:Rogue"]="När fiendens spejare slås ut vänds Night Elfs smygförmåga mot dem, så att Hordes infiltratörer härskar i skogens skuggor.",["faction:Horde"]="Varje Night Elf-spejare som fälls i Ashenvale skyddar de lokala lägren och avverkningsplatserna från samordnade motanfall från Alliance."},sec={{t="Ögon i trädkronorna",b="Ashenvales skogar är fortfarande en omstridd gränstrakt där varje stig och höjd bevakas noga. Underrättelser är lika dödliga som en yxa, och rapporter till Kuray'bin bekräftar att Night Elf-spejare som kallas Ashenvale Outrunners har smugit sig ut från Alliance-fästet Silverwing Outpost. Spejarna rör sig i den täta vildmarken öster om sin bas och söder om Hordes närliggande områden. De bevakar skogsstigarna för att kartlägga befästningar och följa truppförflyttningar."},{t="Förblinda Alliance",b="För att förhindra ett samordnat anfall måste Horde slå ut fiendens spanare innan de kan återvända hem. Genom att jaga rätt på spejarna hindrar Hordes mästare befälhavarna vid Silverwing Outpost från att få viktig information om truppstyrka och utpostens försvarsverk. Utan ögon långt fram blir Night Elf desorienterade och mycket mindre villiga att riskera aggressiva manövrer genom de omstridda skogarna."}},faq={{q="Vem ger uppdraget Ashenvale Outrunners?",a="Uppdraget ges av Kuray'bin, en samordnare för Hordes spejare i Ashenvale, som arbetar med att följa och motverka Night Elf-rörelser i skogen.",al={"uppdragsgivare","vem ger uppdraget","kuray'bin-uppdrag"}},{q="Var finns Ashenvale Outrunners?",a="Spejarna stryker omkring i skogarna öster om Silverwing Outpost och söder om Kuray'bins läger. De patrullerar i snåren för att samla information.",al={"spejarnas plats","var finns spejarna","var hittar man spejarna"}},{q="Varför utgör spejarna ett hot mot Horde?",a="Spejarna är avancerade spanare som utgår från Silverwing Outpost. Om de lyckas kartlägga Hordes läger och truppantal kan Alliance samordna precisa räder mot utsatta positioner.",al={"varför döda spejarna","spejarnas hot","spejarnas syfte"}},{q="Vad är Silverwing Outpost?",a="Silverwing Outpost är en framstående militär anläggning för Night Elf i Ashenvale. Den fungerar som en bas vid fronten för Alliance-styrkor som försvarar skogen och motverkar Hordes expansion.",al={"silverwing outposts historia","vad är silverwing outpost","silverwing och alliance"}},{q="Ingår uppdraget i en längre berättelse?",a="Uppdraget är främst en fristående taktisk uppgift som ska minska Alliance-spaningen i området. Det belönar kämpar som hjälper Kuray'bin att säkra försvarslinjen.",al={"uppdragskedja","uppföljningsuppdrag","spejarnas uppdragskedja"}},{q="Kan spelare i Alliance slutföra uppdraget?",a="Nej, uppdraget är exklusivt för Horde. Kuray'bin verkar enbart för Hordes frontlinjer i Ashenvale.",al={"är uppdraget bara för horde","alliance-version","kan alliance göra detta"}}},fx={["2873db73"]={q="Varför vill Kuray'bin att Ashenvale Outrunners ska dödas?",a="Kuray'bin vill blända Alliansen och hindra dem från att genomföra ett samordnat anfall mot hordens territorium. Outrunners smet nyligen ut från Silverwing Outpost för att spana nära hordens linjer. Om de kartlägger lägrets försvar och truppernas rörelser följer nästan säkert ett anfall från Alliansen. Om du röjer dem ur vägen går fienden miste om viktig information om slagfältet.",al={"kuraybin motiv","varför döda outrunners","kuray'bin anledning"}},["884af179"]={q="Vilka är Ashenvale Outrunners?",a="De är nattalvsspejare som skickats ut från Alliansens närbelägna fäste Silverwing Outpost. Under skogens täta lövverk smyger dessa rörliga förtrupper nära hordens gränser för att bevaka befästningar och patrullvägar samt förbereda marken för framtida intrång från Alliansen.",al={"vad är ashenvale outrunners","vilka är outrunners","ashenvale outrunners mål"}}},fp="20,189,20.332.0,21.325.0,41.141.0,43.140.0,45.183.0,27.172.0,41.144.0,41.66.0"}
P.entries["quest:6504"] = {n="The Lost Pages",s="När orken Gurda Ragescar transporterade en nyinköpt goblinsåg från Ratchet till Warsong Lumber Camp blåste en plötslig vindpust bort maskinens instruktionsbok. Hon sitter fast nära Splintertree Post och kan inte köra det komplicerade ingenjörsmästerverket utan att hitta de utspridda sidorna.",h="När orken Gurda Ragescar transporterade en nyinköpt goblinsåg från Ratchet till Warsong Lumber Camp blåste en...",kw={"ashenvale","gurda ragescar","ratchet","såg","sågens instruktionsbok","splintertree post","de förlorade sidorna","warsong lumber camp"},ang={["faction:Horde"]="Varje såg som når Warsong Lumber Camp påskyndar insamlingen av det dyrbara timmer som behövs för att bygga murar, hyddor och krigsskepp i Durotar.",["profession:Engineering"]="Mekare förstår nog Gurdas dilemma alltför väl: att köra en goblinbyggd såg utan tillverkarens anvisningar är ett enkelt sätt att orsaka ett katastrofalt pannhaveri.",["race:Orc"]="Kroppsarbete och krigartraditioner lämnar föga tålamod för goblinernas detaljerade pappersarbete, så många kan nog känna igen sig i Gurdas frustration över borttappade tekniska blad."},sec={{t="En otursam vindpust",b="Warsong-klanen förlitar sig i hög grad på ångdrivna sågar som köps från goblinerna i hamnen Ratchet för att röja skog i Ashenvale. Det är långt ifrån självklart för en vanlig orcisk krigare hur dessa ömtåliga, högljudda vidunder ska användas. När Gurda Ragescar färdades norrut med en nyinköpt såg slet en plötslig vindstöt instruktionshäftet ur hennes händer och spred tolv sköra pergamentblad över skogsmarken."},{t="Sidor i vildmarken",b="De vilda vindarna svepte manualen över trädkronorna, och enskilda sidor har hamnat hos kringvandrande varelser, kultister och skogens invånare i hela området. Utan alla tre samlade kapitlen förblir den komplicerade maskinen en livlös klump av stål och surrande sågblad. Gurda är strandsatt längs vägen till Splintertree Post och kan inte inställa sig för skogsarbetet."}},faq={{q="Vem är Gurda Ragescar?",a="Gurda Ragescar är en arbetare i Horde som fått i uppdrag att frakta en goblinsåg från handelsstaden Ratchet till Ashenvale, där den ska hjälpa till med avverkningen vid Warsong Lumber Camp.",al={"gurda","ragescar","vem ger uppdraget"}},{q="Varför behöver Gurda en instruktionsbok för att köra sågen?",a="Goblinernas ingenjörskonst är ökänt nyckfull och svårbegriplig, med flyktiga ångpannor, intrikata tryckventiler och komplicerade spakar. Inte ens en ivrig orc kan köra vidundret säkert utan att läsa tillverkarens manual.",al={"varför manual","varför kan hon inte köra den","sågens instruktionsbok"}},{q="Hur hamnade manualens sidor utspridda över hela Ashenvale?",a="När Gurda färdades norrut längs skogsvägen slet en våldsam vindpust boken ur hennes grepp. De lösa sidorna fladdrade ut över skogen, och hon stod kvar med bara det tomma omslaget.",al={"hur kom sidorna bort","vinden blåste bort sidorna"}},{q="Vart ska sågen?",a="Maskinen är avsedd för Warsong Lumber Camp, där Horde bedriver en aggressiv kalavverkning för att förse Orgrimmar och Durotar med timmer.",al={"vart ska sågen","warsong-sågens destination"}},{q="Var går det att hitta de saknade sidorna?",a="Vindarna svepte sidorna vida omkring, och olika humanoider och fientliga skogsvarelser som strövar omkring i Ashenvale har plockat upp dem.",al={"var hittar man sidorna","vem släpper sidorna"}},{q="Varför köper Horde maskiner från Ratchet?",a="Ratchet är den närmaste neutrala hamnen med aktiva handelsnätverk knutna till goblinkarteller. Horde köper regelbundet specialiserad ingenjörsutrustning, sprängverktyg och ångdrivna fordon för att stärka sin militära logistik.",al={"hordes goblinmaskiner","ratchets handel med horde"}}},fx={["63589195"]={q="Varför behöver Gurda Ragescar att du hittar sidorna ur handboken?",a="Gurda sitter fast på vägen nära Splintertree Post med en goblinhuggare som står stilla och som hon inte kan köra. Hon fick i uppdrag att ta den dyrbara maskinen från Ratchet till Warsong Lumber Camp för att inställa sig i tjänst. Utan handboken vet hon inte hur den fungerar. Om hon lämnar fordonet oskyddat i vildmarken för att söka igenom skogen till fots riskerar horden att förlora värdefull utrustning.",al={"varför behöver gurda hjälp","varför kan gurda inte hitta sidorna","varför jag förlorade sidor"}}},fp="14,213,18.331.0,23.258.0,22.130.0,64.132.0,61.182.0,42.111.0,37.118.0,51.189.0"}
P.entries["quest:651"] = {n="Stones of Binding",s="Efter The Princess Trapped berättar en röst från de skimrande skärvorna om fyra Stones of Binding utspridda över Arathi, som håller den fången under marken. Den starkaste, Stone of Inner Binding, kan bara låsas upp med nycklar från de tre andra.",h="Efter The Princess Trapped berättar en röst från de skimrande skärvorna om fyra Stones of Binding utspridda...",kw={"arathi highlands","burning key","cresting key","skimrande skärvor","myzrael","stone of inner binding","stones of binding","thundering key"},sec={{t="Fyra stenar",b="Rösten berättar om fyra Stones of Binding utspridda över Arathi, som håller den fången under marken. För att lossa bojorna måste den starkaste låsas upp först: Stone of Inner Binding, som kräver nycklar från de tre andra, Stones of West, East och Outer Binding. Nycklarna är Burning Key, Cresting Key och Thundering Key. Väktare vakar över stenarna, men någon listig eller lyckosam kan kanske hitta ett sätt att fördriva dem. När nycklarna har samlats förs de till Stone of Inner Binding."},{t="Vid den inre stenen",b="Stenen bär Myzraels röst: Stones of Binding är öppna, bojorna lossnar och friheten kommer allt närmare. Myzrael hälsar dig som en ädel befriare."}},faq={{q="Var kommer det här steget ifrån?",a="Det kommer från de skimrande skärvorna, efter The Princess Trapped.",al={"uppdragsgivare till stones of binding","vem ger stones of binding","var börjar stones of binding"}},{q="Vilka är de fyra Stones of Binding?",a="Stone of West Binding, Stone of East Binding, Stone of Outer Binding och Stone of Inner Binding, den starkaste.",al={"vilka stones of binding","arathis bindningsstenar","fyra stenar"}},{q="Vilka nycklar behövs för att låsa upp den inre stenen?",a="Burning Key, Cresting Key och Thundering Key, som samlas från Stones of West, East och Outer Binding.",al={"bindningsnycklar","vilka nycklar behövs","nycklar till stone of inner binding"}},{q="Vem vaktar bindningsstenarna?",a="Väktare vakar över stenarna, men en listig eller lyckosam äventyrare kan kanske hitta ett sätt att fördriva dem.",al={"stensväktare","vem vaktar stenarna","bindningsstenarnas väktare"}},{q="Vart måste nycklarna lämnas?",a="Till Stone of Inner Binding, den mäktigaste av dem, som måste låsas upp innan de andra öppnas.",al={"vart lämnar jag nycklarna","lämna in stones of binding","stone of inner binding plats"}}},fp="17,159,11.387.0,18.163.1,31.83.0,36.140.0,48.118.0,30.99.0,33.115.0"}
P.entries["quest:652"] = {n="Breaking the Keystone",s="När Stones of Binding öppnades lättade mycket av röstens fångenskap, men ett lås håller den fortfarande kvar. Låset är Keystone, bland en ring av stenar, och stenväktaren Fozruk, en av röstens fångvaktare, har nyckeln, som väktarna kallar Rod of Order.",h="När Stones of Binding öppnades lättade mycket av röstens fångenskap, men ett lås håller den fortfarande kvar.",kw={"arathi highlands","fozruk","keystone","rod of order","stone of inner binding","stenväktare"},sec={{t="Det sista låset",b="När Stones of Binding öppnades lättade mycket av röstens fångenskap, men ett lås återstår: Keystone, bland stenarna i cirkeln omkring dig. Nyckeln hålls av en fångvaktare, stenväktaren Fozruk, och väktarna kallar den Rod of Order. Låset öppnas om du tar staven från Fozruk och bär den till Keystone. Rösten lovar att dess tacksamhet, om du lyckas, ska skaka jorden ända ner till rötterna. Keystone är laddad med enorm geomantisk energi."},{t="Vid Keystone",b="När staven sätts in i Keystone går en skälvning genom marken under dig."}},faq={{q="Vad hände före detta steg?",a="Stones of Binding kom först, och när stenarna öppnades lättade mycket av röstens fångenskap.",al={"förutsättning","föregående uppdrag","förutsättning för stones of binding"}},{q="Vem är Fozruk?",a="Fozruk är en stenväktare och en av röstens fångvaktare. Han har nyckeln till Keystone.",al={"vem är fozruk","fozruks historia","stenväktaren fozruk"}},{q="Vad är Rod of Order?",a="Namnet som stenväktarna använder för nyckeln till Keystone, som Fozruk har.",al={"rod of order","vad är rod of order","keystones nyckel"}},{q="Var finns Keystone?",a="Keystone står bland en stencirkel i Arathi Highlands.",al={"var finns breaking the keystone","keystones plats","stone circle arathi"}}},fp="21,170,13.399.0,15.66.1,28.85.0,14.91.0,25.82.0,22.67.0"}
P.entries["quest:6523"] = {n="Protect Kaya",s="Protect Kaya är ett eskortuppdrag för Horde i Stonetalon Mountains. Efter att ha upptäckt att Kaya Flathoof hålls fången av fientliga Grimtotem-tauren eskorterar äventyrare henne genom farliga bergsstigar till Camp Aparaje. När hennes orolige far, Makaba Flathoof, får veta att hon överlevt känner han en enorm lättnad.",h="Protect Kaya är ett eskortuppdrag för Horde i Stonetalon Mountains.",kw={"camp aparaje","eskort","grimtotem","kaya flathoof","makaba flathoof","protect kaya","stonetalon","tauren"},ang={["faction:Horde"]="När resande familjer skyddas stärks Hordes svårvunna fästen och försörjningsvägar i Stonetalon.",["race:Tauren"]="Att rädda Kaya hjälper direkt fränder som slitits isär av Grimtotem-klanens aggressiva aggression."},sec={{t="En fånge bland klipporna",b="I Stonetalon Mountains råder bittra rivaliteter mellan taurerna, och ingen konflikt är skarpare än den kring den förrädiska klanen Grimtotem. Djupt inne på fientligt territorium tillfångatogs Kaya Flathoof och hölls fången. Att fly till fots kräver att man tar sig fram längs vindlande stigar kantade av opportunistiska rovdjur och vaksamma fiender. En beväpnad eskort är hennes enda realistiska hopp om att nå vänligt territorium."},{t="Flykt till Camp Aparaje",b="Camp Aparaje ligger i östra Stonetalon Mountains, och Kaya hittar därifrån hem. Hon siktar på lägret och är säker på att hon kan hitta resten av vägen själv när hon väl kommit fram. Genom att leda henne längs stigarna där bakhåll är vanliga ser du till att hon inte blir tillfångatagen igen innan hennes fångvaktare upptäcker att hon rymt."},{t="En fars lättnad",b="Makaba Flathoof väntar på nyheter nära Stonetalon sydöstra gräns och fruktar det allra värsta för sin försvunna dotter. När budbärare kommer med beskedet att Kaya tryggt nått Camp Aparaje förbyts Makabas förtvivlan i överväldigande tacksamhet mot hjältarna som stod mellan hans barn och hennes fångvaktare."}},faq={{q="Vem är Kaya Flathoof?",a="Kaya Flathoof är en ung tauren som tillfångatogs av fientliga Grimtotem-styrkor i Stonetalon Mountains. Hon är beroende av att Horde-äventyrare på genomresa hjälper henne att fly och eskorterar henne till en säker plats.",al={"vem är kaya","kaya flathoof bakgrund","kaya"}},{q="Vart ska Kaya eskorteras?",a="Kaya måste eskorteras säkert längs stigarna till Camp Aparaje i östra Stonetalon. Därifrån hittar hon hem på egen hand.",al={"vart kaya ska eskorteras","vart ska kaya föras","vart tar kaya vägen"}},{q="Vem är Makaba Flathoof?",a="Makaba Flathoof är Kayas far och väntar oroligt nära den sydöstra ingången till Stonetalon Mountains. Han förtvivlar över sitt försvunna barn tills äventyrare kommer med besked om att hon räddats.",al={"vem är makaba","makaba flathoof bakgrund","kayas far"}},{q="Vem tillfångatog Kaya?",a="Kaya tillfångatogs av fientliga Grimtotem-taurer som har läger och ordnar bakhåll bland klipporna i Stonetalon.",al={"vem tog kaya","vem kidnappade kaya","kayas kidnappare"}},{q="Vad händer när Kaya når Camp Aparaje?",a="När Kaya når Camp Aparaje kan hon hitta hem på egen hand. Spelaren får i uppdrag att återvända till Makaba Flathoof och berätta den glädjande nyheten att hon överlevt.",al={"efter protect kaya","vad händer efter eskortuppdraget","fortsättning på protect kaya"}},{q="Kan Alliance-spelare ta uppdraget?",a="Nej. Familjen Flathoof tillhör de fredliga taurerna som står på Hordes sida, så räddningsuppdraget är exklusivt för Horde-äventyrare.",al={"kan alliance göra protect kaya","är kaya endast för horde"}}},fx={ee59f589={q="Varför behöver Kaya Flathoof ditt skydd?",a="Kaya har just tagit sig loss från sina fångvaktare, men är fortfarande fast bakom fiendens linjer i bergen. Om fångvaktarna upptäcker flykten innan hon når säker mark blir hon tillfångatagen igen eller dödad. Camp Aparaje är hennes enda chans att komma i säkerhet och skicka bud till sin far Makaba, som fruktar det värsta för hennes liv.",al={"varför skydda kaya","kaya flathoof motiv","varför behöver kaya eskort"}},["87bb92ff"]={q="Varför kan Kaya Flathoof inte fly på egen hand?",a="Kaya är försvagad, obeväpnad och helt omringad av fiendeland. Utan en skicklig kämpe som skyddar henne från kringströvande patruller kan hon inte tryggt ta vägen mot Camp Aparaje innan någon upptäcker att hon är borta.",al={"varför behöver kaya mig","varför kan kaya inte ge sig av ensam","varför behövs eskort"}}},fp="12,224,22.345.0,22.228.0,17.265.1,21.180.0,36.129.0,23.198.0,18.100.0,45.137.0,44.120.0"}
P.entries["quest:653"] = {n="Myzrael's Allies",s="Myzrael ropar att hon är fri och ska samla kraft i hemlighet för sina fångvaktare. Hon kallar dig en ädel bundsförvant och skickar dig till Gerrig Bonegrip, som har en butik i Ironforges Forlorn Cavern och vet hur hon kan åkallas.",h="Myzrael ropar att hon är fri och ska samla kraft i hemlighet för sina fångvaktare.",kw={"arathi highlands","forlorn cavern","gerrig bonegrip","jättar","ironforge","slutsten","myzrael"},sec={{t="Fri att samla kraft",b="Myzrael är fri och tänker samla kraft i hemlighet för sina fångvaktare. Om de mötte henne nu skulle de säkert övermanna henne och låsa in henne igen. Med tiden tänker hon möta jättarna, och hon svär att de kommer att ångra att de höll henne fången. Hon kallar dig en ädel bundsförvant och säger att hon kommer att behöva din hjälp igen, för att åkalla henne till ytan när hon är redo."},{t="Ett meddelande till Gerrig Bonegrip",b="Myzrael ber dig tala med Gerrig Bonegrip, vars butik ligger i Forlorn Cavern i Ironforge. Han vet hur hon kan åkallas."}},faq={{q="Var hittar man Gerrig Bonegrip?",a="Gerrig Bonegrip har en butik i Forlorn Cavern i Ironforge.",al={"gerrig bonegrips plats","var finns gerrig bonegrip","hitta gerrig bonegrip"}},{q="Varför håller sig Myzrael gömd?",a="Hon måste samla kraft först. Om hennes fångvaktare mötte henne nu skulle de säkert övermanna henne och fängsla henne igen.",al={"varför gömmer sig myzrael","vart ska myzrael"}},{q="Vilka är fångvaktarna som Myzrael talar om?",a="Jättarna, som hade henne i sitt förvar. Hon säger att hon med tiden kommer att konfrontera dem och att de kommer att ångra det.",al={"myzraels fångvaktare","vem fängslade myzrael","myzrael och jättarna"}},{q="Varför skickar Myzrael dig till Ironforge?",a="Gerrig Bonegrip vet hur hon kan åkallas, och hon säger att hon kommer att behöva din hjälp med att åkalla henne till ytan när hon är redo.",al={"varför åka till ironforge","syftet med att besöka gerrig"}}},fp="16,213,23.331.0,24.110.0,35.59.0,35.114.0,38.124.0,39.150.0"}
P.entries["quest:654"] = {n="Tanaris Field Sampling",s="När du slår på strömkällan börjar fälttestningsutrustningen glöda och vibrera. Du har nu två timmar på dig att samla in det Tanaris öken kan erbjuda, annars går informationen förlorad.",h="När du slår på strömkällan börjar fälttestningsutrustningen glöda och vibrera.",kw={"basilisk","bilgewhizzle","fälttestningsutrustning","gadgetzan","hyena","strömkälla","scorpion","tanaris","vattenbolag"},sec={{t="En tickande strömkälla",b="När strömkällan är igång glöder och vibrerar utrustningen, så den verkar fungera som planerat. Chief Engineer Bilgewhizzle har sagt att du har två timmar på dig att samla in dina prover i Tanaris öken: godtagbara prover från åtta basilisks, åtta hyenor och åtta skorpioner. Om tiden tar slut går allt förlorat, och du måste köpa en ny strömkälla från Bilgewhizzle. Utrustningen ska lämnas tillbaka till Bilgewhizzle i Gadgetzan innan strömmen tar slut."},{t="Företagets vinst",b="Bilgewhizzle känner ingen sympati för den vars utrustning slocknar. Det enda som spelar någon roll är att Gadgetzan Water Company går med vinst. Bilgewhizzle är villig att fortsätta sälja strömkällor tills företaget har råd att importera vatten från Dun Moroghs iskalla källor."}},faq={{q="Vilka varelser ska provtas med testutrustningen?",a="Godtagbara prover från åtta basilisks, åtta hyenor och åtta skorpioner i Tanaris öken.",al={"vilka djur ska testas","provtagningsmål","vad ska jag döda"}},{q="Hur lång tid finns det för att slutföra provtagningen?",a="Två timmar från det att strömkällan slås på.",al={"tidsgräns","hur lång tid har jag","tidtagare"}},{q="Vad händer om strömkällan tar slut?",a="Allt i utrustningen förstörs, och du måste köpa en ny strömkälla av Chief Engineer Bilgewhizzle i Gadgetzan för att börja om.",al={"om tiden tar slut","misslyckat uppdrag","strömmen tog slut"}},{q="Vart ska testutrustningen lämnas när den är full?",a="Till Chief Engineer Bilgewhizzle i Gadgetzan, innan strömmen tar slut.",al={"vem ska jag lämna in det till","inlämningsplats","var finns bilgewhizzle"}},{q="Varför fortsätter Bilgewhizzle att sälja strömkällor?",a="Bilgewhizzle vill att Gadgetzan Water Company ska gå med vinst, även om det innebär att sälja strömkällor tills företaget har råd att importera vatten från Dun Moroghs iskalla källor.",al={"bilgewhizzles mål","gadgetzan water companys mål","varför ta prover"}}},fp="22,120,22.403.0,20.237.0,54.89.0,52.67.0,42.120.0,40.99.0,49.164.0"}
P.entries["quest:6541"] = {n="Report to Kadrak",s="Vid The Crossroads skickar Thork beprövade Horde-krigare norrut för att rapportera till Kadrak. Orchen håller till i ett vakttorn nära gränsen till Ashenvale och förbereder rekryter inför striderna som väntar.",h="Vid The Crossroads skickar Thork beprövade Horde-krigare norrut för att rapportera till Kadrak.",kw={"ashenvale","the barrens","the crossroads","kadrak","splintertree","thork","vakttorn","the zoram strand"},ang={["faction:Horde"]="Som medlem av Horde går du från att försvara bosatta områden i The Barrens till att säkra livsviktiga resurser i de omstridda skogarna i norr.",["race:Orc"]="Som orc går du in på en avgörande prövoplats. Timret från Ashenvale kan hjälpa till att befästa Orgrimmar och skapa ett varaktigt hem på Kalimdor."},sec={{t="Vägen norrut",b="The Crossroads står inför quilboar, centaurer och lokala banditer, medan Horde blickar norrut mot Ashenvales täta skogar. Thork skickar krigare som har bevisat sig i centrala The Barrens till gränstornet i norr, där Kadrak är stationerad."},{t="Strategi vid gränsen",b="Kadrak övervakar den södra vägen in i Ashenvale och organiserar förstärkningar till Hordes fäste på andra sidan gränsen. Splintertree Post och en utpost längs The Zoram Strand hjälper Horde att stärka sin närvaro i de timmerrika skogarna, där de infödda nattalverna gör hårt motstånd."}},faq={{q="Vem är Thork?",a="Thork är en orcisk officer vid The Crossroads i The Barrens. Han hjälper till att organisera det lokala försvaret och styr lovande krigare mot fälttåg som framryckningen in i Ashenvale.",al={"thork the crossroads","vem ger rapport till kadrak","thork the barrens"}},{q="Var finns Kadrak?",a="Kadrak finns i det norra vakttornet i The Barrens, intill huvudvägen in i Ashenvale.",al={"kadraks plats","var finns kadrak","kadraks vakttorn"}},{q="Varför rycker horden in i Ashenvale?",a="Horde tränger in i Ashenvale efter timmer och resurser som behövs för att bygga dess nya städer i Durotar och The Barrens. Timret är livsviktigt, men jakten på det för Horde i direkt konflikt med nattalverna.",al={"varför ashenvale","horden i ashenvale","hordens invasion av ashenvale"}},{q="Vilka utposter har horden etablerat i Ashenvale?",a="Horde har upprättat Splintertree Post längs Ashenvales huvudväg och ytterligare en utpost längre västerut vid The Zoram Strand.",al={"hordens baser i ashenvale","bas vid zoram strand","splintertree"}},{q="Vad händer efter att du rapporterat till Kadrak?",a="När du har rapporterat till Kadrak ger han dig en genomgång av den lokala militära situationen och skickar dig för att hämta rapporter från Warsong-utposterna runtom i Ashenvale.",al={"efter kadrak","nästa uppdrag efter kadrak","vad ger kadrak"}},{q="Kan du få det här uppdraget någon annanstans än i The Barrens?",a="Ja. Horde-krigare som utgår från Malaka'jin i Stonetalon Mountains får en nästan identisk kallelse att rapportera till Kadrak.",al={"alternativt kadrakuppdrag","kadrakuppdrag i stonetalon"}}},fx={d049fa98={q="Varför vill Thork att jag rapporterar till Kadrak?",a="Horden säkrar aktivt sitt grepp om Ashenvale och har nyligen byggt utposter som den vid The Zoram Strand. Thork ansvarar för försvaret av Crossroads, men frontlinjerna i norr behöver ständigt nya rekryter för att skydda de nyligen erövrade områdena. Han skickar dugliga krigare till Kadrak, som samordnar fälttåget från det norra vakttornet och avgör var förstärkningar behövs mest.",al={"varför rapportera till kadrak","thorks motiv att rapportera till kadrak","varför skickar thork mig till kadrak"}}},fp="16,159,14.255.0,17.286.0,13.174.0,24.90.0,40.190.0,53.128.0,37.154.0,69.129.0"}
P.entries["quest:6542"] = {n="Report to Kadrak",s="Den här militära ordern skickar Hordens krigare från Malaka'jin i Stonetalon Mountains till Kadraks utpost vid norra gränsen till The Barrens. Den markerar övergången från att försvara bergskammen till att förstärka Hordens omstridda militära fälttåg i Ashenvale. När du rapporterar till Kadrak samlas soldater för att stödja framskjutna läger som Splintertree Post och The Zoram Strand.",h="Den här militära ordern skickar Hordens krigare från Malaka'jin i Stonetalon Mountains till Kadraks utpost...",kw={"ashenvale","the barrens","darn talongrip","kadrak","splintertree","stonetalon mountains","warsong reports","the zoram strand"},ang={["faction:Horde"]="Den här ordern gör dig till en del av krigshövdingens större krigsinsats och skickar erfarna gränskrigare till den pågående kampen om Ashenvales resurser.",["race:Orc"]="Fälttåget i Ashenvale är avgörande för Warsong-klanen och Durotars överlevnad, vilket gör Kadraks postering till en prövning för unga orc-krigare.",["race:Tauren"]="Hordens spanare, som orchen Darn Talongrip, visar resande säkra vägar över bergsgränserna och håller kommunikationslinjerna öppna mellan bloodhoof-folkens länder och krigshövdingens nordfront."},sec={{t="En kallelse till nordfronten",b="I Malaka'jins klippiga bergspass håller orchen Darn Talongrip uppsikt över Hordens södra gräns och bergsgränser. Det största militära trycket kommer dock norrifrån, i Ashenvales uråldriga skogar, där nattalvernas väktare ständigt drabbar samman med Warsong-klanens timmerhuggare. Darn ser stridsvana krigare passera genom Stonetalon och skickar därför dugliga rekryter till vakttornet i norra The Barrens för att hjälpa till med de pågående fälttågen."},{t="Kadraks vaktpost",b="Orchen Kadrak är stationerad vid den norra gränsen, där den torra savannen möter Ashenvales grönskande trädkronor, och övervakar Hordens truppförflyttningar in i omstritt område. Horden säkrar aggressivt sitt fotfäste och håller utposter vid både The Zoram Strand i väster och Splintertree Post i norr. Kadrak är den viktiga knutpunkten för samordning av förnödenheter, trupper och brådskande rapporter längs dessa krigshärjade skogsgränser."}},faq={{q="Vem skickar dig till Kadrak från Stonetalon?",a="Darn Talongrip, en ork vid Hordens utpost Malaka'jin i Stonetalon Mountains, ger den här ordern till dugliga äventyrare på väg mot skogsgränsen.",al={"uppdragsgivare rapportera till kadrak","vem startar rapportera till kadrak stonetalon","darn talongrip uppdrag"}},{q="Var ligger Kadrak?",a="Kadrak är stationerad vid vakttornet i norra The Barrens och bevakar huvudvägen norrut in i Ashenvale.",al={"kadraks plats","var finns kadrak","hitta kadrak"}},{q="Varför rekryterar Horden krigare till Ashenvale?",a="Horden behöver timmer för att försörja Orgrimmar och har upprättat befästa ställningar som The Zoram Strand och Splintertree Post. Eftersom de möter hårt motstånd från de inhemska nattalverna behöver befälhavarna ständigt förstärkningar för att säkra området.",al={"varför bege sig till ashenvale","hordens fälttåg i ashenvale","varför strida i ashenvale"}},{q="Vad händer när du har rapporterat till Kadrak?",a="Kadrak informerar dig om det strategiska läget i Ashenvale och ger dig i uppdrag att leverera och samla in militära rapporter vid skogens omstridda utposter genom The Warsong Reports.",al={"vad händer efter kadrak","the warsong reports","uppföljningsuppdrag kadrak"}},{q="Skiljer sig det här uppdraget från versionen i The Barrens?",a="Båda är vägvisaruppdrag som leder till Kadrak vid gränsen till Ashenvale. Det ena erbjuds i The Barrens, vid Crossroads, och det här i Stonetalon Mountains. Båda leder dig vidare in i Ashenvales berättelse.",al={"the barrens eller stonetalon kadrak","två uppdrag rapportera till kadrak","dubbelt vägvisaruppdrag kadrak"}},{q="Vad är The Zoram Strand, som nämns i rapporten?",a="The Zoram Strand är ett kustområde i nordvästra Ashenvale vid Veiled Sea. Horden har upprättat en befäst strandutpost där för att stödja taktiska förflyttningar och säkra tillgången till havet.",al={"vad är zoram strand","zoram strand utpost","ashenv ale strandbas"}}},fx={f0da3cc6={q="Varför vill Darn Talongrip att du rapporterar till Kadrak?",a="Horden har nyligen upprättat en utpost vid The Zoram Strand i Ashenvale och behöver rekryter för att försvara de nya frontlinjerna. Darn Talongrip, som är stationerad vid Malaka'jin, skickar dugliga äventyrare till Kadrak vid det norra vakttornet i The Barrens för att få vidare order.",al={"varför skickar darn mig till kadrak","darn talongrips motiv","varför rapportera till kadrak"}}},fp="16,210,28.358.0,14.304.0,40.135.0,24.98.0,51.199.0,39.129.0,49.188.0,51.187.0"}
P.entries["quest:6543"] = {n="The Warsong Reports",s="Kadrak skickar kurirer från The Barrens norra delar för att samla in rapporter från hela Ashenvale. Warsong Reports förmedlar order och fältiakttagelser från utposter nära Azshara, Splintertree Post och The Zoram Strand.",h="Kadrak skickar kurirer från The Barrens norra delar för att samla in rapporter från hela Ashenvale.",kw={"ashenvale","the barrens","kadrak","splintertree post","warsong outrider","warsong reports","warsong runner","warsong scout","the zoram strand","zoram'gar outpost"},ang={["class:Hunter"]="Som jägare prövar du din förmåga att hitta rätt och överleva på Ashenvales farliga vägar, där vilda rovdjur och dolda alvskyttar utgör hot.",["faction:Horde"]="När du levererar rapporterna får en ung krigare i Horden en tidig roll i kampen mot nattalverna i norra Kalimdor.",["race:Orc"]="För orcher är det en ära att hjälpa Warsong-klanen, och det bidrar till att förse dem med virket som behövs för att bygga Orgrimmar."},sec={{t="Försörjning vid gränsen",b="Kadrak bevakar bergspasset mellan The Barrens norra delar och Ashenvale från ett befäst torn. Horden behöver passet eftersom The Barrens inte kan leverera virket som Orgrimmar behöver. Warsong-klanen har trängt in i den uråldriga alvskogen för att nå virket. Kurirer förmedlar order mellan utspridda patruller och hjälper dem att hålla samspelet, medan nattalvernas bakhåll hotar stigarna i vildmarken."},{t="Ögon över Ashenvale",b="Warsong-spejare håller uppsikt över tre delar av Ashenvale. På västkusten bevakar en löpare vid Zoram'gar Outpost nagaernas aktiviteter och andra hot längs kusten vid The Zoram Strand. Vid Splintertree Post samordnar en spejare försvaret mot Sentinels räder. Längre österut bevakar en utpostare vägen mot Azsharas krossade ruiner. Deras rapporter ger Kadrak en bild av nattalvernas rörelser och svagheter längs gränsen."}},faq={{q="Var börjar uppdraget?",a="Rapporterna börjar hos Kadrak, en orcofficer i vakttornet av trä som bevakar bergspasset mellan The Barrens norra delar och Ashenvales södra delar.",al={"uppdragsgivare","var finns kadrak","vem ger uppdraget warsong reports","var börjar uppdraget"}},{q="Varför spionerar Horde på Ashenvale?",a="Horden söker sig till Ashenvales täta skogar efter virke för att bygga och förstärka bosättningar som Orgrimmar. Nattalverna försvarar sina heliga lundar med kraft, och ständig spaning hjälper Horden att hålla sina utposter och försörjningslinjer i konflikten.",al={"varför ashenvale","warsong-timmer","konflikten i ashenvale"}},{q="Var finns de tre Warsong-spejarna?",a="Warsong Runner finns vid Zoram'gar Outpost, längst ut på den nordvästra delen av The Zoram Strand. Warsong Scout finns vid Splintertree Post längs huvudvägen. Warsong Outrider patrullerar den östra vägen mot Azsharas gräns.",al={"var finns spejarna","var är spejarna","var finns warsong outrider, runner och scout"}},{q="Vilka är Warsong Outriders?",a="Warsong Outriders är spejare och plundrare i Warsong, en orcisk klan. Deras kavalleri och skärmytslingar hjälper Horden att utöka sitt område, avverka timmer och försvara territorium i Ashenvales skogar.",al={"warsong-klanen","vilka är warsong outriders","warsong-klanen i ashenvale"}},{q="Vad händer när rapporterna lämnats in?",a="När Kadrak tar emot rapporterna använder han dem för att planera truppförflyttningar, förstärka utsatta utposter som Zoram'gar och Splintertree och stärka Hordens närvaro djupare inne i skogen.",al={"lämna in rapporterna","nästa drag","vad gör kadrak"}},{q="Är vägen genom Ashenvale säker för kurirer på låg nivå?",a="Nej. Nattalvernas Sentinels överfaller ofta resande på Ashenvales huvudväg. Rovdjur, björnar och Alliansens patruller från bosättningar som Astranaar hotar också kurirerna.",al={"faror i ashenvale","är vägen säker","nattalvsöverfall"}}},fx={["197774e3"]={q="Varför vill Kadrak att rapporterna samlas in?",a="Kadrak vaktar gränsen mellan The Barrens och Ashenvales omstridda skogar. Horden försöker aktivt utöka sin närvaro under lövverket, men att marschera rakt in i nattalvernas område utan vägledning leder till katastrof. Kadrak skickade spejare djupt in i regionen för att bevaka fiendens aktivitet och terrängen. Han behöver få rapporterna levererade och återförda omgående, så att hordens ledning kan bedöma sitt taktiska läge och samordna nästa steg i det pågående fälttåget.",al={"kadraks motiv","varför vill kadrak ha rapporter","varför samla in warsong-rapporter"}},["649e115c"]={q="Vad är Warsong Outrider Update?",a="Warsong Outrider Update är ett taktiskt underrättelsedokument som sammanställts av hordens beridna spejare, som patrullerar Ashenvales östra delar mot gränsen till Azshara. Det innehåller iakttagelser om Alliansens rörelser, nattalvspatruller och den lokala geografin längs den viktiga färdvägen. Det ger Kadrak den östra gränsöversikt han behöver för att planera truppernas förflyttningar.",al={"warsong outrider update","vad är outrider update","outrider-rapport"}},f6b4d8ea={q="Vad är Warsong Runner Update?",a="Warsong Runner Update innehåller spaningsuppgifter från skogens västra utkanter, där styrkorna är stationerade vid Zoram'gar Outpost längs The Zoram Strand. Rapporten beskriver hot längs kusten, fientliga styrkor i området och möjliga angrepp från havet. Den ger Kadrak information om hur säkra hordens positioner är långt väster om huvudvägen.",al={"warsong runner update","vad är runner update","runner-rapport"}},["92e54885"]={q="Vad är Warsong Scout Update?",a="Warsong Scout Update är en strategisk rapport från Splintertree Post, hordens främsta fäste i centrala Ashenvale. Den har sammanställts av spejaren som är stationerad där och följer nattalvernas intrång, tillgången på förnödenheter och utpostens beredskap att stödja hordens fortsatta expansion i den omgivande vildmarken.",al={"warsong scout update","vad är scout update","scout-rapport"}}},fp="19,205,18.410.0,21.421.0,30.150.0,37.236.0,44.214.0,30.179.0,41.195.0,58.169.0"}
P.entries["quest:6544"] = {n="Torek's Assault",s="Torek's Assault är en direkt räd från Horden, som utgår från Ashenvales vildmark och riktas mot den närbelägna Night Elf-garnisonen vid Silverwing Outpost. Orc-raideren Torek leder anfallet på order från Splintertree Post. Målet är att krossa de lokala Sentinel-styrkornas motstånd och döda deras befälhavare, Duriel Moonfire. Det är en av de djärvaste och blodigaste sammandrabbningarna i det pågående kriget om Ashenvales gränser.",h="Torek's Assault är en direkt räd från Horden, som utgår från Ashenvales vildmark och riktas mot den...",kw={"ashenvale","duriel moonfire","ertog ragetusk","raider","sentinels","silverwing outpost","splintertree post","torek"},ang={["class:Warrior"]="En brutal, frontal närstrid där rå fysisk uthållighet ställs mot härdade Sentinel-bågskyttar och svärdsmästare.",["faction:Alliance"]="När Duriel Moonfire faller blottas Silverwing Outpost, och Night Elfs förfäders skogsmarker hotas.",["faction:Horde"]="För Horden är framryckningen förbi Silverwing Outpost ett avgörande styrkeprov som försvagar Night Elf-blockaden runt Splintertree Post.",["race:NightElf"]="Räden slår mot Sentinels främsta ledning, och alvblod spills under Ashenvales trädkronor."},sec={{t="Ett anfall ur skuggorna",b="Ashenvale har fastnat i ett tilltagande gränskrig mellan Hordens timmerläger och de infödda Night Elf. För att bryta Alliansens försvarslinje samlar Torek ihop en grupp raider från Splintertree Post strax utanför Silverwing Outpost. I stället för att invänta en motattack samordnar Torek en frontal stormning, för att krossa utpostens försvar innan Night Elf kan inleda ett förstärkt fälttåg mot Splintertree Post."},{t="Silverwing intas",b="Silverwing Outpost är ett befäst fäste i skogen, bemannat av vaksamma Silverwing Sentinels och stridslystna alvkrigare. Toreks främsta mål är deras ledare, Duriel Moonfire. Om Duriel faller huggs den lokala Night Elf-militärhierarkin av vid roten, så att raiderna kan rapportera en blodig seger till befälhavaren Ertog Ragetusk vid Splintertree Post."}},faq={{q="Vem är Torek?",a="Torek är en aggressiv orc-raider som utgår från Splintertree Post i Ashenvale. Han är stridslysten och hungrig på strid, och leder en grupp raider med uppdrag att ta striden direkt till Night Elf-styrkorna som befäst sig i skogen.",al={"torek npc","vem är torek","torek orc"}},{q="Vad är Silverwing Outpost?",a="Silverwing Outpost är en befäst Night Elf-bosättning i Ashenvale. Den bevakas av elitsoldater från Sentinels och krigare, och fungerar som ett militärt bålverk som håller uppsikt över Hordens truppförflyttningar längs skogsstigarna.",al={"silverwing outpost","vad är silverwing"}},{q="Vem är Duriel Moonfire?",a="Duriel Moonfire är befälhavaren bland Night Elf som försvarar Silverwing Outpost. Som garnisonens ledare för hon de lokala Sentinels mot Hordens intrång, tills Toreks raidgrupp bryter sig in i lägret för att slå ner henne.",al={"duriel moonfire","duriel"}},{q="Vem är Ertog Ragetusk?",a="Ertog Ragetusk är en Horde-officer stationerad vid Splintertree Post. Han är Toreks överordnade och övervakar regionens militära operationer. Han tar emot rapporter om segrar mot Alliansen.",al={"ertog ragetusk","ertog"}},{q="Varför anfaller Horden Silverwing Outpost?",a="Horden och Night Elf ligger i öppet krig om territorium i hela Ashenvale. Ett anfall mot Silverwing Outpost lättar trycket på Hordens försörjningslinjer och försvagar direkt Sentinels försvarsnät som bevakar den djupare skogen.",al={"varför anfalla silverwing","konflikten i ashenvale silverwing"}},{q="Var äger anfallet rum?",a="Anfallet börjar strax utanför Silverwing Outpost, som ligger på östra sidan av Falfarren River, i Hordens händer i Ashenvale. Det kulminerar inne i Night Elf-lägret.",al={"platsen för toreks anfall","var är torek"}}},fx={["6e6dcd55"]={q="Varför behöver Torek min hjälp med anfallet?",a="Torek för redan befäl över en grupp plundrare från Splintertree, men hans spejare rapporterar att Silverwing Outpost är väl befäst och bevakad av erfarna nattalvsväktare och krigare. Han vet att försvararna inte ger sig lätt och välkomnar därför en stridsduglig mästare som kan förstärka frontlinjen och säkra en avgörande seger för horden i anfallet mot Duriel Moonfire.",al={"varför behöver torek mig","varför rekryterar torek spelaren","varför hjälpa torek"}}},fp="15,215,25.343.0,17.299.0,13.152.0,27.159.0,23.179.1,22.179.0,45.210.0,34.159.0"}
P.entries["quest:6545"] = {n="Warsong Runner Update",s="Warsong Runner Update är ett kommunikationsuppdrag för Horde som förbinder Ashenvales främre försvar med befälhavare längs gränsen. Budskapet anförtros åt kurirer och nya rekryter och beskriver det ökande militära trycket mot Warsong-spejare, särskilt de allt aggressivare naga.",h="Warsong Runner Update är ett kommunikationsuppdrag för Horde som förbinder Ashenvales främre försvar med...",kw={"ashenvale","kadrak","mor'shan","naga","rampart","rapport","löpare","spejare","warsong"},ang={["faction:Horde"]="Varje soldat räknas längs skogsgränsen, där kommunikationslinjerna mellan Barrens och de främre utposterna måste hållas öppna för att överleva.",["race:Orc"]="Warsong Clan är beroende av sina löpares uthållighet och vaksamhet för att hålla mark som tagits i anspråk under krigshövding Thralls befäl."},sec={{t="Rapporter från fronten",b="Warsong Clan håller en rad spejare och löpare utplacerade i Ashenvale för att bevaka fientligheter i området och hålla försörjningslinjerna öppna. Mellan territoriella skärmytslingar med Night Elf-väktare och den hårda miljön är snabba underrättelser avgörande. Kurirer med rapporter från fronten är oumbärliga för att hålla avlägsna garnisoner samordnade med befälhavare som Kadrak, som är stationerad vid Mor'shan Rampart."},{t="Hotet från naga",b="Horde väntar sig hårt motstånd från Night Elf bland träden, men vakter vid utposterna rapporterar allt djärvare angrepp från naga. Dessa ormformade inkräktare slår till från vattendrag och forntida ruiner, sätter utpostens barrikader på prov och tvingar försvararna att rikta uppmärksamheten bort från skogsbruk och gränspatruller. Uppdateringen som förs tillbaka till Mor'shan Rampart varnar för dessa samordnade amfibieangrepp."}},faq={{q="Vem skickas rapporten till?",a="Rapporten förs direkt tillbaka till Kadrak, en tillsynsman som är stationerad vid Mor'shan Rampart längs gränsen mellan Ashenvale och norra Barrens.",al={"vem får uppdateringen","rapport till kadrak","vart skickas rapporten"}},{q="Vilka hot nämns i uppdateringen?",a="Spejaren rapporterar att den lokala utposten har stått emot upprepade angrepp och lyfter fram det växande hotet från fientliga naga i närliggande vatten.",al={"vad står i rapporten","innehåll i löparens uppdatering","nagaangrepp"}},{q="Varför förlitar sig Horde på löpare till fots här?",a="Tät växtlighet, aktiva Night Elf-skyttar och isolerade utposter gör flygtransporter svåra eller utsatta i delar av Ashenvale. Budbärare till fots kan snabbt och diskret kommunicera längs bevakade stigar.",al={"varför löpare","warsong-löparnas bakgrund","varför inte wyverner"}},{q="Vilka är Warsong-löparna?",a="De är spejare, kurirer och förtruppskrigare i Warsong Clan, med uppdrag att säkra försörjningslinjer och hålla uppsikt över fiendens rörelser kring skogens omstridda gränser.",al={"warsong clan i ashenvale","vilka är warsong-löparna"}},{q="Var angriper naga i Ashenvale?",a="Naga har etablerat fästen i ruiner längs Ashenvales stränder och sjöar, där de ofta överfaller resenärer och plundrar närliggande läger.",al={"var finns naga","naga i ashenvale"}},{q="Vad har utposten för uppgift i området?",a="Utposten fungerar som en station för tidiga varningar och ett defensivt fäste. Den ser till att fientliga styrkor inte kan skära av kommunikationen mellan skogsbruket djupt inne i skogen och Barrens.",al={"varför finns utposten här","hordelägrets syfte"}}},fx={["3fdffadb"]={q="Varför behöver Warsong Runner få den här rapporten levererad?",a="Utposten utsätts för allt hårdare tryck efter de senaste nagaangreppen, och befälet behöver en korrekt bild av frontlinjerna. Löparen har hållit vakt och slagit tillbaka flera anfallsvågor, men Kadrak vid The Mor'shan Rampart måste förstå hur farligt läget har blivit, så att horden kan samordna sitt försvar i Ashenvale.",al={"varför skicka rapport","löparens motiv","varför leverera warsong-rapport"}},ae645a70={q="Vad är Warsong Report till för?",a="Warsong Report innehåller viktig fältinformation om nagaernas allt tätare angrepp mot utposten. När du för tillbaka den får Kadrak veta hur försvaret vid fronten ser ut och vilka trupper som behövs, så att Hordens ledning känner till de senaste hoten i området.",al={"vad warsong report är till för","vad warsong report är","vad rapporten säger"}},["0f7ad725"]={q="Varför ber budbäraren dig att lämna rapporten i stället för att göra det själv?",a="Utpostens garnison är hårt pressad när den aktivt slår tillbaka nagaernas angrepp. Eftersom du är en stridsduglig kurir som redan färdas mellan frontens utposter kan försvararna stanna på sina poster i stället för att lämna försvarsvallen och bära dokument till gränsen mot The Barrens.",al={"varför jag som warsong runner","varför han inte lämnar den själv","varför budbäraren behöver mig"}}},fp="21,178,20.299.0,15.325.0,32.115.0,41.113.0,45.185.0,28.168.0,42.118.0,43.139.0"}
P.entries["quest:6546"] = {n="Warsong Outrider Update",s="Warsong Outrider Update är ett leveransuppdrag för Horden som börjar längs de farliga stigarna i östra Ashenvale. En ensam Warsong Scout anförtror en äventyrare livsviktig information om hot från den närliggande Alliansen, satyrer som slagit sig ner där och naga som rycker fram i Azshara intill.",h="Warsong Outrider Update är ett leveransuppdrag för Horden som börjar längs de farliga stigarna i östra...",kw={"ashenvale","azshara","kadrak","the mor'shan rampart","naga","satyr","warsong outrider","warsong report"},ang={["faction:Horde"]="Varje rapport som förs längs Mor'shan-linjen stärker Hordens bräckliga fotfäste i Ashenvales lummiga skogar.",["race:Orc"]="Warsongklanen är stolt över att hålla förtruppen, men dess spejare vet att mod inte ensamt kan stoppa fiender som omringar dem från alla håll."},sec={{t="Ögon längs skogsbrynet",b="Östra Ashenvale är en omstridd gränszon där Hordens försörjningslinjer ständigt utsätts för angrepp. Warsong Outriders håller noggrann uppsikt över skogarna och spanar efter fiender långt innan anfallsstyrkor kan slå till mot utposter som The Mor'shan Rampart eller Splintertree Post. Om du stöter på en ryttare på patrull befinner du dig mitt i ett aktivt spaningsområde. Informationen kan avgöra om en befästning hålls eller går förlorad i ett bakhåll."},{t="Hot vid varje horisont",b="Rapporten från ryttaren ger en dyster taktisk bild av Hordens läge i Kalimdors centrala skogar. Utöver de ständiga striderna mot Night Elves och den större Alliansen kryllar östra Ashenvale av listiga, demoniska satyrer. Faran ökar ytterligare: spejare har upptäckt en stor naga-närvaro som breder ut sig över de förstörda kustområdena i Azshara intill. Befälhavarna varnas för att Horden är omringad av fientliga makter från nästan alla håll."}},faq={{q="Vad är Warsong Report?",a="Det är en underrättelserapport skriven av en Warsong Outrider som sammanfattar fiendens truppositioner och faror i området. Den lyfter fram hot från närliggande styrkor i Alliansen, aktiva satyrklaner i östra Ashenvale och nyupptäckta naga-rörelser genom Azshara.",al={"uppdragsföremål warsong report","vad står det i rapporten","spejarrapport"}},{q="Vem är Kadrak?",a="Kadrak är en befälhavare i Horden som är stationerad vid The Mor'shan Rampart, försvarsbarriären som vaktar den norra gränsen mellan The Barrens och Ashenvale. Han tar emot spejare och samordnar operationer in i skogen.",al={"vem är kadrak","var finns kadrak","lämna in till kadrak"}},{q="Varför nämns naga i Azshara?",a="Azshara gränsar direkt till östra Ashenvale. Ryttarna bevakar främmande rörelser i angränsande områden för att se till att Hordens flanker inte överraskas av stora anfall medan de strider mot Night Elves.",al={"koppling mellan naga och azshara","varför nämns azshara","naga-hotet i azshara"}},{q="Varför är östra Ashenvale så farligt för Horden?",a="Området ligger mellan aktiva avdelningar från Alliansen, forntida satyrruiner genomsyrade av demonisk korruption och vilda skogsdjur. Hordens kurirer och patruller riskerar därför bakhåll från alla håll.",al={"varför är östra ashenvale farligt","hot i ashenvale","saty hot"}},{q="Vilka är Warsong Outriders?",a="De utgör Warsongklanens främsta förtrupp och spaningsryttare i Ashenvale. De ansvarar för att följa Night Elves rörelser, hålla uppsikt över timmerlägren och säkra handelsvägarna.",al={"vad är outriders","warsong-spejare","outriders bakgrund"}},{q="Varför kan ryttaren inte själv leverera rapporten?",a="Ryttaren har fått i uppdrag att hålla vakt längs leden och följa fiendens rörelser i realtid. Om han lämnar sin utsiktspunkt blir frontlinjen blind för oväntade framryckningar från Alliansen eller satyrer.",al={"varför ska jag leverera rapporten","varför levererar han den inte själv"}}},fx={["43097ba7"]={q="Varför behöver Warsong Outrider få rapporten levererad?",a="Horden står inför hot från alla håll i östra Ashenvale. Med Alliansen i närheten, satyrer som fördärvar skogarna och nagaer som tar mark på andra sidan gränsen i Azshara behöver Kadrak omedelbar information om fiendens rörelser. När du levererar rapporten får utpostens befälhavare veta vilka faror som finns i området och kan förstärka utsatta positioner innan fienden slår till.",al={"varför skicka rapporten","warsong outriders motiv","varför lämna rapporten"}}},fp="23,211,26.359.0,24.362.0,27.246.0,14.226.0,38.207.0,56.206.0,30.182.0,50.176.0"}
P.entries["quest:6547"] = {n="Warsong Scout Update",s="Warsong Scout Update är ett kommunikationsuppdrag för Horde som förbinder utposternas befälhavare längs Ashenvales gränser med framskjutna spejare som håller uppsikt över den omstridda skogen. Kurirer förmedlar strategiska order från Kadrak och ser till att Warsong Clan håller nattalverna under noggrann uppsikt. Uppdraget visar hur skört och fientligt Horde försöker hålla fast vid sitt nyvunna territorium.",h="Warsong Scout Update är ett kommunikationsuppdrag för Horde som förbinder utposternas befälhavare längs...",kw={"ashenvale","the barrens","kadrak","nattalver","rapport","spejare","väktare","warsong"},ang={["faction:Horde"]="Varje kurir som bär order mellan Kadrak och spejarna i utkanterna hjälper Horde att hålla sitt fotfäste i Ashenvale säkert mot nattalvernas obevekliga bakhåll.",["race:NightElf"]="Warsong-spejare som smyger längs gränserna innebär att Elunes heliga skogar fortsätter att skändas. Väktarna strävar efter att rensa bort dem.",["race:Orc"]="Warsong Clans arv präglas av deras uthållighet i Ashenvale, där de tar livsviktigt timmer trots landets fientlighet och dess uråldriga försvarare."},sec={{t="Ögon i skuggorna",b="Gränslandet i Ashenvale är fortfarande en krutdurk där ingen av sidorna ger efter en tum. Hordes styrkor under Kadrak förlitar sig i hög grad på utspridda Warsong-spejare vid utposter med hög risk för att följa nattalvernas rörelser och säkra omstridda försörjningsleder. Skogen ger Alliansens smygande väktare naturligt skydd, så regelbundna rapporter och skriftliga uppdateringar är avgörande för att hindra att isolerade spejare blir avskurna och övermannade."},{t="Hålla marken",b="För Warsong Clan har varje röjd eller ockuperad skogsremsa kostat blod. Spejarna håller ständig utkik efter nattalvernas räder, som syftar till att återta skogarna. När Kadraks order levereras får förtruppen veta att förstärkningar och samordning fortfarande är i gång, så spejarna kan rapportera att deras försvarsåtgärder lyckas trots alvernas oavbrutna motstånd."}},faq={{q="Vem är Kadrak?",a="Kadrak är en befälhavare inom Horde, stationerad längs gränsen mellan The Barrens och Ashenvale. Han samordnar spaningsuppdrag, gränsförsvar och logistiskt stöd för Warsong-operationer som tränger in i den uråldriga skogen.",al={"kadrak","vem är kadrak","kadraks roll"}},{q="Varför är Warsong-spejarna så rädda för nattalver?",a="Nattalver smälter naturligt in i skuggorna i sina förfäders skogar och överfaller plötsligt Hordes patruller. Eftersom Warsong Clan aktivt röjer timmer och bosätter sig på mark som alverna anser helig, hotas spejarna ständigt av dödliga överraskningsattacker.",al={"varför frukta nattalver","nattalver i skuggorna","warsong-spejare och alvernas hot"}},{q="Varför strider man om Ashenvale?",a="Horde behöver timmer och resurser från Ashenvale för att bygga Orgrimmar och försörja sina bosättningar i det torra The Barrens och Durotar. Nattalverna som bor där betraktar skogen som helig mark och strider hårt för att driva bort orcherna som avverkar skogen och bemannar garnisonerna.",al={"varför strida om ashenvale","kriget i ashenvale","hordes konflikt i ashenvale"}},{q="Vilken roll har Warsong Clan här?",a="Warsong Clan leder Hordes expansion och resursutvinning i Ashenvale. Grom Hellscream ledde dem först in i skogen under det tredje kriget. Deras närvaro är fortfarande djupt rotad, med timmerläger och pågående strider mot väktarna.",al={"warsong clan i ashenvale","warsongs roll"}},{q="Vart tar rapporten vägen efter att spejaren fått den?",a="När spejaren har tagit emot Kadraks uppdaterade instruktioner skickar hen tillbaka besked om framgångarna mot alvernas motattacker i området. På så vis hålls Hordes ledning fullt informerad om hur stabil frontlinjen är.",al={"vem får rapporten","kadraks rapport","resultat av spejarens uppdatering"}},{q="Lyckas Hordes planer i Ashenvale vid den här tidpunkten?",a="Spejarna vid frontlinjen anser att deras försvar lyckas. De håller sina befästa positioner och slår tillbaka alvernas angrepp, men området är fortfarande ett hårt omstritt slagfält där ingen sida har fullständig kontroll.",al={"vinner horde i ashenvale","warsongs framsteg"}}},fx={aadbe711={q="Varför vill Warsong Scout att det här blir gjort?",a="Warsong-spejare patrullerar djupt inne i fientliga delar av Ashenvale, omgivna av Night Elf som lurar i skuggorna. Spejaren behöver färska order från Kadrak för att samordna försvaret vid fronten, behålla sitt hårt vunna fäste i skogen och få veta om deras försök att driva tillbaka alverna håller stånd.",al={"warsong scouts motiv","varför leverera rapporten","varför spejaren behöver order"}},ae4f0954={q="Vad är Warsong Report till för?",a="Warsong Report innehåller strategiska direktiv och truppositioner som Kadrak skickat från Mor'shan Rampart. För spejare som håller isolerade utposter i Ashenvale ser rapporten till att de känner till Hordens taktiska manövrer medan de försvarar klanens anspråk mot Night Elf-styrkor som lurar i närheten.",al={"vad warsong report är till för","vad warsong report gör","warsong report bakgrund"}},f7519c0a={q="Varför behöver Kadrak en äventyrare för att leverera rapporten?",a="Gränsen mellan The Barrens och Ashenvale är full av bakhåll. Grunts och vaktposter som är stationerade vid Mor'shan Rampart kan inte lämna sina försvarsvärn utan att äventyra utpostens försvar. Därför är en självständig resenär en idealisk kurir som kan smyga genom skogen och leverera känsliga militära direktiv till isolerade spejare.",al={"varför skicka mig med warsong report","varför vakterna inte kan leverera den","varför jag som warsong scout"}}},fp="20,173,19.283.0,18.292.0,14.174.0,57.200.0,35.224.0,37.208.0,51.165.0,60.196.0"}
P.entries["quest:6548"] = {n="Avenge My Village",s="Makaba Flathoof överlevde knappt en brutal attack när plundrare från Grimtotem-klanen anföll hans by i sydöstra Stonetalon Mountains. Avskuren från sitt folk och omgiven av de döda ber han Horde-resenärer slå tillbaka mot lägret med Grimtotem-banditer och lejda svärdskämpar för att hämnas sitt fallna folk.",h="Makaba Flathoof överlevde knappt en brutal attack när plundrare från Grimtotem-klanen anföll hans by i...",kw={"avenge my village","grimtotem","grimtotem-legosoldat","grimtotem-bandit","grundig darkcloud","makaba flathoof","stonetalon mountains"},ang={["faction:Horde"]="Horde är beroende av öppna, säkra pass mellan The Barrens och Stonetalon. Ett fredlöst Grimtotem-band som mördar resenärer och allierade bybor hotar krigshövdingens försörjningslinjer genom bergen.",["race:Tauren"]="Grimtotem-klanens förräderi drabbar tauren-resenärer hårdast. Att se andra shu'halo slaktas av sitt eget folk förstärker den bistra verkligheten av splittringen mellan klanerna och faran Grimtotem utgör för Cairnes enade folk."},sec={{t="Blod bland klipporna",b="Nära gränsen mellan The Barrens och Stonetalon Mountains röda stenpass står Makaba Flathoof som ensam överlevare efter en brutal massaker. Plundrare med Grimtotem-klanens mörka banér anföll utan förvarning och slaktade nästan alla i hans bosättning. Makaba kämpade tappert emot och fällde flera angripare, men tvingades till slut gömma sig med knappt livet och sin vrede i behåll."},{t="Grimtotem-hotet",b="Grimtotem har länge varit en oregerlig och aggressiv nagel i ögat på tauren-stammarna som enats under Cairne Bloodhoof, högöverhövding. Till skillnad från de fredliga nomaderna som vandrar genom Mulgore använder Grimtotem-krigsband ofta hänsynslösa banditer och opportunistiska legosoldater för att erövra mark och angripa isolerade bosättningar. För Makaba betyder diplomati och släktskap mellan stammar inget längre; bara blod för blod kan lindra hans sorg."}},faq={{q="Vem gav uppdraget?",a="Makaba Flathoof är en överlevande tauren som slagit läger nära det sydöstra passet in i Stonetalon Mountains. Han överlevde Grimtotem-klanens våldsamma plundring av den närbelägna byn och söker hämnd på plundrarna.",al={"uppdragsgivare","makaba flathoof","vem är makaba"}},{q="Varför anfaller Grimtotem andra tauren?",a="Grimtotem-klanen har aldrig helt omfamnat Hordes enighet eller Cairne Bloodhoofs vision om fred. De är starkt revirhävdande, främlingsfientliga och aggressiva. De plundrar öppet rivaliserande bosättningar, dödar främlingar och använder beväpnade busar och lejda legosoldater för att ta kontroll över områden som Stonetalon.",al={"varför är grimtotem fientliga","tauren anfaller tauren","grimtotem-klanens bakgrund"}},{q="Var finns Grimtotem-angriparna?",a="Grimtotem-banditerna och legosoldaterna håller till i ett läger strax väster om Makaba Flathoofs plats i sydöstra Stonetalon, bland de klippiga kullarna med utsikt över passet.",al={"var finns fienderna","grimtotem-lägrets plats","var hittar man banditer"}},{q="Vilka är Grimtotem-legosoldaterna?",a="Grimtotem-klanen förstärker ofta sina egna krigare genom att leja hänsynslösa kämpar och svärdskämpar till sina krigsband. På så vis ser de till att ha tillräckligt med folk för att terrorisera och övermanna isolerade bosättningar.",al={"legosoldater","grimtotem-svärdskämpar","vilka är legoknektarna"}},{q="Vad händer efter uppdraget?",a="När du har fällt banditerna och legosoldaterna vid fronten ber Makaba dig angripa ledaren bakom massakern, Grundig Darkcloud, i uppföljningsuppdraget 'Kill Grundig Darkcloud'.",al={"nästa uppdrag","vad följer efter avenge my village","kill grundig darkcloud"}},{q="Var låg Makabas by?",a="Makabas bosättning var ett isolerat tauren-läger nära gränspassen i sydöstra Stonetalon. Grimtotem-plundringen utplånade det helt och lämnade Makaba som en av få kända överlevande.",al={"flathoof-byn","var låg byn","vilken by förstördes"}}},fx={ee147ee3={q="Varför vill Makaba Flathoof att Grimtotem ska dödas?",a="Makaba Flathoof vill hämnas efter att Grimtotem-klanen genomfört en brutal räd mot hans by och slaktat nästan alla som bodde där. Han har förlorat sitt hem och sitt folk, och nu drivs han bara av viljan att hämnas på klanen som massakrerade hans familj och grannar.",al={"makaba flathoofs motiv","varför hämnas på byns vägnar","varför makaba vill hämnas"}},["2ec07636"]={q="Vem riktar Grimtotem in sig på här?",a="Du skickas mot Grimtotem Ruffians och Mercenaries som slagit läger västerut. Grimtotem är en aggressiv, isolerad taurenklan som är känd för sin fientlighet mot andra stammar och Horden. De plundrar lokala bosättningar för att utöka sitt fäste i Stonetalon Mountains.",al={"grimtotem ruffians och mercenaries","vem du skickas för att döda","vem som anföll makabas by"}},bd5303e7={q="Varför behöver Makaba Flathoof din hjälp?",a="Makaba kämpade desperat under räden och dödade så många Grimtotem han kunde, men undkom själv med knapp nöd. Han är sårad och ensam, utan allierade eller byvakter att samla. Han kan inte möta de återstående rövarna på egen hand.",al={"varför makaba inte kan slåss","varför be mig","varför makaba behöver hjälp"}}},fp="17,241,18.334.0,20.358.0,20.193.0,45.262.0,42.140.0,34.132.0,30.138.1,35.187.0"}
P.entries["quest:655"] = {n="Hammerfall",s="Hammerfall berättar om hövding Orgrim Doomhammers tragiska fall när en interneringsläger för Alliansen befriades i Arathi Highlands. Genom Gor'muls sorgtyngda minnen får resenärer veta hur lägret befriades och varför fästet bär sitt högtidliga namn.",h="Hammerfall berättar om hövding Orgrim Doomhammers tragiska fall när en interneringsläger för Alliansen...",kw={"arathi highlands","doomhammer","gor'mul","hammerfall","interneringsläger","orgrim doomhammer","thrall","tor'gan"},ang={["class:Warrior"]="Orgrim Doomhammer förblir en legendarisk och ikonisk krigare. Att gå på marken där han föll i strid har stor militär betydelse.",["faction:Horde"]="Hammerfall står som ett högtidligt minnesmärke över befrielsen av orchernas interneringsläger och hövding Orgrim Doomhammers offer.",["race:Orc"]="För orcherna är Doomhammers fall i Arathi ett av historiens mest smärtsamma ögonblick. Det markerar slutet på en era och framväxten av Thralls nya hord."},sec={{t="Blod och brustna kedjor",b="Hammerfall var en gång ett dystert interneringsläger för Alliansen, där tillfångatagna orcher hölls bakom trä och stål efter det andra kriget. Det förändrades när den unge Thrall och hövding Orgrim Doomhammer anföll för att krossa fångenskapen och befria sitt folk. Räden befriade många fångar och slog ut lägrets försvar, men slutade i tragedi när Doomhammer träffades i ryggen av en lans från en ryttare och dog på samma mark där hordens bosättning nu står."},{t="Defeatens kvardröjande skugga",b="Alla fångar blev inte fria den ödesdigra dagen. I stridens kaos och jordens skakningar såg en orch vid namn Gor'mul den legendariske hövdingen falla och förlorade all vilja att kämpa. När hans bröder flydde lämnades Gor'mul kvar, och i åratal vandrade han planlöst genom höglandet i sorg. Även nu när horden har återtagit platsen som en befäst bas fortsätter minnet av det fega angreppet att hemsöka dem som överlevde."}},faq={{q="Vem är Gor'mul?",a="Gor'mul var en orchfånge i interneringslägret som en gång låg där Hammerfall nu står. Thrall och Doomhammer ledde ett anfall för att befria lägret, men Gor'mul lämnades kvar under den kaotiska flykten och vandrade ensam i förtvivlan i åratal.",al={"vem är gormul","gormuls bakgrund","vad hände med gormul"}},{q="Hur dog Orgrim Doomhammer?",a="Orgrim Doomhammer dödades under striden för att befria interneringslägret i Arathi Highlands. När han ledde anfallet i svart plåtrustning träffades han i ryggen av en alliansriddare som stormade fram till häst och genomborrade honom med en lans.",al={"hur dog doomhammer","vem dödade doomhammer","berättelsen om doomhammers död"}},{q="Varför heter utposten Hammerfall?",a="Utposten fick namnet Hammerfall till ära för hövding Orgrim Doomhammer, som föll just här när han befriade sitt folk från människornas fångenskap. Senare återvände horden till det förstörda lägret för att bygga en permanent bas.",al={"varför heter det hammerfall","ursprunget till namnet hammerfall","hammerfalls historia"}},{q="Vem är Tor'gan?",a="Tor'gan är en representant för horden som är stationerad i Hammerfall. Han hjälper till att hålla uppsikt över lägret och förstår det kvardröjande trauma som tidigare fångar som Gor'mul lider av.",al={"vem är tor'gan","tor'gan hammerfall","tor'gan uppdrag"}},{q="Deltog Thrall i striden här?",a="Ja. Thrall kämpade sida vid sida med hövding Orgrim Doomhammer i anfallet mot interneringslägret i Arathi Highlands. Tillsammans krossade de lägrets försvar för att befria de tillfångatagna orcherna, men segern kostade Doomhammer livet.",al={"thrall och doomhammer i arathi","befrielsen av hammerfall","kämpade thrall vid hammerfall"}},{q="Varför är Gor'mul så nedstämd?",a="Gor'mul såg Doomhammer falla framför sina ögon, och det krossade hans mod. När de andra fångarna flydde ut i vildmarken lämnades han kvar och vandrade planlöst utan hopp, tills horden återvände för att bygga Hammerfall.",al={"varför är gormul så ledsen","gormuls depression","varför tappade gormul hoppet"}}},fp="10,169,23.321.0,30.367.0,15.224.0,30.141.0,36.186.0,15.161.0,40.181.0,29.212.0"}
P.entries["quest:65593"] = {n="Hearts of the Lovers",s="Carendin Halgar söker Avelina Lillys och Isaac Pearsons hjärtan för att locka till sig en incubus. Deras längtan efter varandra gör dem till ett särskilt kraftfullt lockbete.",h="Carendin Halgar söker Avelina Lillys och Isaac Pearsons hjärtan för att locka till sig en incubus.",kw={"ambermill","avelina lilly","carendin halgar","hearts of the lovers","incubus","isaac pearson","älskande","ratchet"},sec={{t="Spådomens val",b="Carendin Halgar söker två hjärtan för sitt arbete i Temple of the Damned. Hans spådomar pekar mot Avelina Lilly i Ambermill och Isaac Pearson i Ratchet. Avelina bistår de fallna trollkarlarna med sitt skrädderi, medan Isaac hoppas kunna göra sig ett namn i kuststaden. Trots att de sliter långt ifrån varandra längtar de efter varandra. Carendin ber dig att hämta deras hjärtan åt honom som lockbete för en incubus."},{t="Hjärtana",b="Carendin tar emot Avelina Lillys och Isaac Pearsons hjärtan. Han håller ett i varje hand och för dem varsamt samman, och kallar sedan de älskande för idioter."}},faq={{q="Vilka är Avelina Lilly och Isaac Pearson?",a="Avelina Lilly erbjuder skräddartjänster åt de fallna trollkarlarna i Ambermill, och Isaac Pearson hoppas kunna göra sig ett namn i Ratchet. Deras hjärtan längtar efter varandra.",al={"avelina och isaac","vilka är de älskande"}},{q="Varför vill Carendin ha deras hjärtan?",a="Carendin säger att en incubus dras till älskandes hjärtan och att den djupaste längtan ger det starkaste lockbetet.",al={"incubus hjärtan","varför hjärtan"}},{q="Var finns de två älskande?",a="Avelina Lilly finns i Ambermill i Silverpine Forest, medan Isaac Pearson finns i Ratchet i Barrens.",al={"var finns avelina","var finns isaac"}},{q="Vem är Carendin Halgar?",a="Carendin Halgar finns i Temple of the Damned, där han ber dig att hämta Avelinas och Isaacs hjärtan åt honom.",al={"carendin","temple of the damned"}}},fp="20,155,18.387.0,10.153.1,40.165.0,36.107.0,25.101.0,23.106.0"}
P.entries["quest:65597"] = {n="The Binding",s="Carendin Halgar i Magic Quarter i Undercity ber dig att använda Lovers’ Hearts för att frammana och betvinga en inkub. Han behöver få tillbaka hjärtana efteråt.",h="Carendin Halgar i Magic Quarter i Undercity ber dig att använda Lovers’ Hearts för att frammana och betvinga...",kw={"carendin halgar","inkub","lovers' hearts","magic quarter","frambesvärjelse","the binding","undercity"},sec={{t="En frambesvärjelse i Undercity",b="Carendin Halgar ber om din hjälp i Magic Quarter i Undercity. Lovers’ Hearts ska användas för att frammana och betvinga en inkub och sedan lämnas tillbaka till honom. Hjärtana förblir i Carendins förvar när du återvänder."}},faq={{q="Vem ber om hjälp?",a="Carendin Halgar i Magic Quarter i Undercity ber om din hjälp.",al={"vem vill ha detta","vem gav det","carendin halgar"}},{q="Vad används Lovers’ Hearts till?",a="Du använder Lovers’ Hearts för att frammana och betvinga en inkub.",al={"användning av lovers hearts","vad gör hjärtana","hjärtan för inkub"}},{q="Vad händer efter frambesvärjelsen?",a="Du lämnar tillbaka Lovers’ Hearts till Carendin Halgar i Magic Quarter.",al={"var lämna tillbaka hjärtan","lämna tillbaka lovers hearts","vad händer sedan"}}},fp="11,160,28.226.0,23.72.0,34.61.0,33.72.0"}
P.entries["quest:656"] = {n="Summoning the Princess",s="Theldurin the Lost säger att Myzrael måste besegras medan hon fortfarande växer, innan hon blir stark nog att utmana dem som håller henne fången. Vid Shards of Myzrael kallar du fram henne, besegrar henne och binder hennes Eldritch Shackles vid Shards.",h="Theldurin the Lost säger att Myzrael måste besegras medan hon fortfarande växer, innan hon blir stark nog att...",kw={"arathi highlands","eldritch shackles","myzrael","scroll of myzrael","shards of myzrael","theldurin the lost"},sec={{t="Varför hon måste stoppas",b="Theldurin vill stoppa Myzrael innan hennes kraft växer sig så stark att hon kan vända sig mot sina fångvaktare. Vissa hävdar att hon kan kontrolleras, men Theldurin undrar varför jättarna då bemödade sig med att kedja fast henne."},{t="Vid Shards",b="Du tar Scroll of Myzrael till Shards, platsen där du först talade med henne, och kallar fram henne. När du har besegrat henne kan du binda hennes Eldritch Shackles vid Shards, och hon blir fångad igen."},{t="När bojorna sätts på plats",b="När bojorna sluter sig kring Shards hörs ett klagorop långt där nere, följt av ett vrål. Värmen och trygghetskänslan som Shards en gång gav är borta. Nu pulserar de av öppet hot, som om varelsen under dem hyser illvilja mot ytan."}},faq={{q="Vem skickar dig för att strida mot Myzrael?",a="Theldurin the Lost, som varnar för att Myzrael måste besegras innan hon blir stark nog att utmana sina fångvaktare.",al={"uppdragsgivare","vem ger uppdraget summoning the princess","theldurins uppdrag"}},{q="Var äger frammaningen rum?",a="Vid Shards of Myzrael, platsen där du först talade med henne.",al={"var frammanar man myzrael","shards of myzrael plats","frammankallningsplats"}},{q="Varför vill Theldurin att Myzrael besegras?",a="Theldurin fruktar att hon ska bli stark nog att utmana sina fångvaktare. Theldurin påpekar också att om hon verkligen kunde kontrolleras, skulle jättarna inte ha kedjat fast henne.",al={"varför döda myzrael","theldurins motiv","varför framkalla henne"}},{q="Hur frammanas Myzrael?",a="Med Scroll of Myzrael, som används vid Shards of Myzrael.",al={"hur framkallar man henne","användning av scroll of myzrael","frammanningsprocess"}},{q="Vad gör du med Eldritch Shackles?",a="Besegra Myzrael, ta hennes bojor och fäst dem vid Shards. Då blir hon fångad igen.",al={"vilket föremål behöver jag","eldritch shackles","myzraels bojor"}}},fp="22,199,23.184.0,13.188.0,28.226.1,31.105.0,36.76.0,41.142.0,24.71.0,42.89.0"}
P.entries["quest:65601"] = {n="Love Hurts",s="Gan'rul skickar dig längs Orgrimmars huvudstråk för att hitta Magar. Hans längtan efter Krilge kan avslöja vilket föremål Gan'rul behöver för att locka en inkub till världen.",h="Gan'rul skickar dig längs Orgrimmars huvudstråk för att hitta Magar.",kw={"cleft of shadow","gan'rul","incubus","krilge","love hurts","magar","orgrimmar","sayaad"},sec={{t="Magars sökande",b="Öster om Cleft of Shadow längtar Magar efter att Krilge ska återvända. Han ber dig att leta efter något dyrbart. Ta med föremålet till Gan'rul, som behöver ett tecken på kärlek och hängivenhet för att frammana en inkub."}},faq={{q="Vem är Magar?",a="Magar bor längs Orgrimmars huvudstråk och längtar efter att Krilge ska återvända.",al={"vem är magar"}},{q="Vem är Krilge?",a="Krilge är Magars partner, och Magar längtar efter att Krilge ska återvända.",al={"vem är krilge","magars partner"}},{q="Vad är en incubus?",a="En incubus är en manlig sayaad, djupt ond och helt inriktad på sitt mål.",al={"incubus betydelse","manlig sayaad"}},{q="Vad behöver Gan'rul?",a="Gan'rul behöver ett föremål som står för stor kärlek och hängivenhet för att locka en incubus till världen.",al={"vad behöver gan'rul","incubus föremål"}},{q="Var kan jag hitta Magar?",a="Magar bor öster om Cleft of Shadow längs Orgrimmars huvudstråk.",al={"magars plats","var finns magar"}}},fp="10,154,14.199.0,13.71.0,14.60.0,19.63.0,23.98.0,23.68.0"}
P.entries["quest:65602"] = {n="What Is Love?",s="Gakin the Darkbinder söker en träfigur vars ålder och historia gör den lämplig för en ritual med en incubus. Hängivenheten den bär på kan locka varelsen närmare.",h="Gakin the Darkbinder söker en träfigur vars ålder och historia gör den lämplig för en ritual med en incubus.",kw={"ashenvale","gakin the darkbinder","incubus","maestra's post","ritual","stormwind","vad är kärlek","träfigur"},sec={{t="Ett gammalt minne",b="Gakin the Darkbinder har lokaliserat en figur med sin spådomskonst. Han säger att den tillhörde ett ungt par för tusentals år sedan och att ägarna är borta. Du ombeds hämta minnesföremålet från ett hus bortom Maestra's Post i Ashenvale och föra det till Gakin i Mage Quarter i Stormwind."},{t="Figurens kraft",b="När du återvänder med träfiguren känner Gakin att dess känslomässiga kraft fortfarande är stark trots tidens gång. Han säger att den kommer att locka till sig en incubus och därför är det reagens han behöver för ritualen."}},faq={{q="Vad vill Gakin att jag ska hitta?",a="Gakin ber dig hämta en träfigur som han tror kommer att locka en incubus till hans ritual.",al={"vilken figur","träfigur","gakins föremål"}},{q="Var finns figuren?",a="Gakin säger att den finns i ett hus bortom Maestra's Post i Ashenvale.",al={"figurens plats","var finns den","hus i ashenvale"}},{q="Vem ägde figuren?",a="Figuren tillhörde ett ungt par för tusentals år sedan.",al={"tidigare ägare","parets figur","vem hade den"}},{q="Varför vill Gakin ha figuren?",a="Gakin känner känslomässig energi i figuren och säger att den kommer att locka till sig en incubus för hans ritual.",al={"varför figuren","reagens för incubus","vad används den till"}}},fp="13,143,15.275.0,20.201.1,32.97.0,22.63.0,23.63.0,33.97.0"}
P.entries["quest:65603"] = {n="The Binding",s="Gakin the Darkbinder ber dig använda en träfigur i kryptorna och möta en incubus. Din framgång avgör om han kan lära dig att åkalla demonen.",h="Gakin the Darkbinder ber dig använda en träfigur i kryptorna och möta en incubus.",kw={"kryptor","gakin the darkbinder","incubus","besvärjelse","sayaad","åkallningscirkel","bindningen","träfigur"},ang={["class:Warlock"]="Som häxmästare ställs du inför Gakins prov: att binda en sayaad och lära dig en besvärjelse för att åkalla incubusen."},sec={{t="Ett prov i kryptorna",b="Gakin the Darkbinder har förberett en åkallningscirkel i kryptorna under Slaughtered Lamb. Du placerar en träfigur i mitten för att öppna en väg för en incubus, en sayaad-demon. Den kan försöka förleda dig, men Gakin varnar för att allt den erbjuder är falskt. Din själ står på spel om du misslyckas."},{t="Bindningslektionen",b="När du besegrat incubusen berömmer Gakin din orubbliga vilja. Han säger att många häxmästare som försöker binda en sayaad blir dess nästa måltid. Sedan lär han dig besvärjelsen för att åkalla den incubus du har bundit."}},faq={{q="Vad vill Gakin att jag ska göra?",a="Gakin ber dig använda en träfigur vid åkallningscirkeln i kryptorna, kuva incubusen och återlämna figuren till honom.",al={"vad ska jag göra","uppdrag med träfigur","åkalla incubus"}},{q="Var finns åkallningscirkeln?",a="Gakin säger att åkallningscirkeln finns i kryptorna under Slaughtered Lamb.",al={"var ska jag åkalla den","cirkel i kryptorna","under slaughtered lamb"}},{q="Vad är en sayaad?",a="En sayaad är en demon, och Gakin varnar för att man inte ska underskatta den.",al={"sayaad-demon","vilken sorts demon","typ av incubus"}},{q="Varför ska jag misstro incubusen?",a="Gakin varnar för att incubusen kan försöka förleda och bedra dig, och att allt den erbjuder är falskt.",al={"kan jag lita på den","incubusens bedrägeri","vad kommer den erbjuda"}},{q="Vad lär Gakin ut efter provet?",a="När du besegrat incubusen lär Gakin dig besvärjelsen för att åkalla demonen du har bundit.",al={"vad händer sedan","bindningslektion","incubusbesvärjelse"}}},fp="11,159,21.294.0,18.210.1,30.130.0,30.76.0,17.75.0,34.101.0,38.99.0"}
P.entries["quest:65604"] = {n="The Binding",s="Gan'rul Bloodeye skickar dig för att frammana en incubus med Withered Scarf och kuva den. Bindningen prövar din förmåga att bemästra en demons förförelsekonster och kraft.",h="Gan'rul Bloodeye skickar dig för att frammana en incubus med Withered Scarf och kuva den.",kw={"gan'rul bloodeye","incubus","magar","neerus tält","sayaad","åkallelsecirkel","the binding","withered scarf"},ang={["class:Warlock"]="Som häxmästare prövas du i att frammana och kuva en incubus. Gan'rul varnar för att demoner kan vända sina förförelsekonster mot dig."},sec={{t="Vid cirkeln",b="Gan'rul Bloodeye läser kärlek i trådarna i Withered Scarf och tror att den kommer att locka till sig en incubus. I Neerus tält i Orgrimmar ska du använda den vid åkallelsecirkeln och visa ditt herravälde över demonen. Gan'rul varnar för att en incubus inte ger sig utan motstånd och ber dig att lämna tillbaka halsduken när demonen har kuvats."},{t="Halsduken återlämnad",b="Gan'rul tar emot halsduken när demonen har kuvats. Han säger att han ska lära dig att frammana demonen och lämna tillbaka halsduken till Magar. Tyget påminner honom om att häxmästare må bruka demoniskt mörker, men att demoner aldrig får styra dem."}},faq={{q="Vem ger dig The Binding?",a="Gan'rul Bloodeye ger dig Withered Scarf och ber dig att frammana och kuva en incubus.",al={"vem är gan'rul","gan'rul bindning","vem ger halsduken"}},{q="Vad gör Withered Scarf?",a="Gan'rul känner kärlek invävd i halsdukens trådar och tror att den kommer att locka till sig en incubus.",al={"halsdukens syfte","withered scarf","varför halsduk"}},{q="Var finns åkallelsecirkeln?",a="Åkallelsecirkeln finns i Neerus tält i Orgrimmar.",al={"incubus cirkel","var frammana","neerus tält"}},{q="Vad är en incubus?",a="En incubus är en sayaad. Gan'rul varnar för att sayaad behärskar sinnen och plågar själar, och att en incubus kan förhäxa sitt byte.",al={"incubus betydelse","sayaad","vilken demon"}},{q="Vad ber Gan'rul dig att göra?",a="Gan'rul ber dig att frammana en incubus med Withered Scarf, kuva den och lämna tillbaka halsduken till honom.",al={"bindningens uppgift","vad ska göras","incubus bindning"}}},fp="11,148,13.325.0,18.231.1,26.91.0,32.88.0,30.53.0,19.123.0,32.102.0"}
P.entries["quest:6561"] = {n="Blackfathom Villainy",s="Blackfathom Villainy är en brådskande vädjan från en döende korsfarare från Argent Dawn, fångad i Blackfathom Deeps. Hordens äventyrare får i uppdrag att göra slut på Twilight Lord Kelris, kultledaren som ligger bakom fruktansvärda blodsoffer till ett uråldrigt vidunder i ruinerna nedanför.",h="Blackfathom Villainy är en brådskande vädjan från en döende korsfarare från Argent Dawn, fångad i Blackfathom...",kw={"aku'mai","argent dawn","bashana runetotem","blackfathom deeps","blackfathom villainy","kelris","moon well","thaelrid","twilight lord kelris","twilight's hammer"},ang={["class:Druid"]="Att kultister som dyrkar tomrummet och naga vanhelgar en uråldrig Moon Well tillhörande nattalverna är ett plågsamt sår i Kalimdors naturliga och andliga fristad.",["class:Shaman"]="Oroligheterna som Kelris och Aku'mai har väckt kränker elementens balans och förvandlar rent grundvatten till en ruttnande härd av skugga och offer.",["faction:Horde"]="För Horden innebär pakten med en spejare från Argent Dawn ett ovanligt ögonblick av gemensamma intressen mot en kosmisk plåga, vilket vinner dem Argent Dawns tidiga välvilja.",["race:Tauren"]="Bashana Runetotem ser Kelris nederlag som ett avgörande försvar av Earthmother, där en styggelse som ville kasta världens naturliga ordning i uråldrigt kaos har renats bort."},sec={{t="En desperat sista strid",b="Argent Dawn-spejaren Thaelrid lockades till det underjordiska templet vid Ashenvales kust och upptäckte fasor långt värre än enkla naga-infall. Nattalven är sårad och har förlorat all sin styrka i grottorna, och inser att han inte kan slutföra sitt uppdrag ensam. Han vägrar låta spaningsuppdraget dö med honom och vänder sig därför till alla förbipasserande hjältar från Horden som är villiga att slå till mot det mörka ledarskapet i de sjunkna salarna."},{t="Offer till djupet",b="Målet för uppdraget är Twilight Lord Kelris, ledaren för Twilight's Hammer-kultisterna som har befäst sig i det förstörda Temple of the Moon. Kelris samarbetar med de lokala naga och utför mörka ritualer över den vanhelgade Moon Well. Han matar levande fångar till Aku'mai, en glupsk hydra och ett vidunder tillhörande Old Gods, i sin galna jakt på kosmisk kraft och uråldrigt kaos."},{t="Bud till Thunder Bluff",b="Argent Dawn trodde en gång att Kelris var död eller försvunnen, så det är avgörande att bekräfta hans död. Thaelrid tvingar inte hjältarna att återvända till människornas områden, utan ber dem i stället lämna bevis på kultledarens död till Bashana Runetotem på Elder Rise i Thunder Bluff. Bashana, som är djupt förbunden med Earthmothers naturliga balans, hedrar segern för att den har släckt en vidrig fördärvelse som ville dra Kalimdor ner i uråldrigt förfall."}},faq={{q="Vem är Twilight Lord Kelris?",a="Kelris leder Twilight's Hammer-kultisterna som ockuperar Blackfathom Deeps. Argent Dawn tror att han är död eller försvunnen, men i hemlighet har han samlat kraft genom att offra levande varelser till den uråldriga hydran Aku'mai i den korrumperade Moon Well.",al={"kelris","vem är kelris","twilight lord kelris"}},{q="Varför befinner sig en medlem av Argent Dawn i Blackfathom Deeps?",a="Argent Guard Thaelrid kom för att undersöka det växande hotet i det förstörda nattalvstemplet. Han övermannades och försvagades dödligt av varelserna där inne, och är fortfarande fångad. Han måste förlita sig på förbipasserande äventyrare för att slutföra sitt uppdrag och göra sig av med Kelris.",al={"argent guard thaelrid","varför är thaelrid här","argent dawn i bfd"}},{q="Vad är Aku'mai?",a="Aku'mai är en monstruös, uråldrig hydra med flera huvuden som anses vara en urtida tjänare till Old Gods. Den slumrade under de sjunkna ruinerna, men vaknade när en djup underjordisk fördärvelse förorenade templets heliga vatten. Nu slukar den fångar som Twilight's Hammer levererar.",al={"akumai","vem är akumai","aku'mais bakgrund"}},{q="Varför lämna in uppdraget till Bashana Runetotem?",a="Thaelrid ber Hordens hjältar bege sig till Bashana Runetotem på Elder Rise i Thunder Bluff. Bashana vakar över Earthmothers balans och håller kontakten med dem som försvarar sig mot uråldrig ondska. Hon betraktar Kelris dyrkan av Old Gods som en avskyvärd plåga för Kalimdor.",al={"bashana runetotem","varför thunder bluff","var lämnar man in blackfathom villainy"}},{q="Vad hände med ruinerna i Blackfathom Deeps?",a="För länge sedan var det underjordiska komplexet ett heligt tempel tillägnat mångudinnan Elune. Katastrofala omvälvningar och uråldrig mörk påverkan från jordens inre förorenade den storslagna Moon Well, vilket lät naga och domedagskultister ta de sjunkna helgedomarna i besittning åt sin mörke herre Aku'mai.",al={"blackfathom deeps historia","elunes tempelruiner","varför är bfd korrumperat"}},{q="Vad vill Twilight's Hammer-kulten uppnå här?",a="Twilight's Hammer vill återföra världen till en tid av uråldrigt kaos genom att dyrka Old Gods. Kelris söker personlig makt genom mörk gemenskap och offrar oskyldiga i djupet för att vinna uråldriga varelsers gunst.",al={"twilight's hammers motiv","varför finns kulten i bfd","kelris mål"}}},fx={["8c6f2eb7"]={q="Varför vill Argent Guard Thaelrid att Twilight Lord Kelris ska dödas?",a="Twilight Lord Kelris och hans kultister från Twilight's Hammer offrar aktivt oskyldiga fångar till Aku'mai, en vidrig tjänare åt Old Gods, i utbyte mot mörk kraft. Argent Dawn skickade Thaelrid för att sätta stopp för dessa fasor, och han kan inte låta kultens fördärv och kaotiska dyrkan fortsätta obehindrat.",al={"thaelrids motiv","varför thaelrid vill att kelris ska dö","varför döda kelris"}},f2efcdf9={q="Varför behöver Thaelrid din hjälp i stället för att själv stoppa Kelris?",a="Thaelrid har blivit svårt sårad djupt inne i det sjunkna templet. Försvagad, utmattad och helt utan krafter kan han inte möta kultledaren ensam. Du är den enda som kan slutföra hans uppdrag.",al={"varför thaelrid behöver hjälp","varför thaelrid inte kan slåss mot kelris","thaelrid varför jag"}},["6dbae1c3"]={q="Vad är Head of Kelris till för?",a="Huvudet är ett obestridligt bevis på att kultledaren är död. Kelris har länge undkommit Argent Dawn, och många trodde därför att han redan var död eller försvunnen. När du visar hans huvud för Bashana Runetotem i Thunder Bluff bekräftar du att hans skräckvälde och människooffer verkligen har upphört.",al={"head of kelris syfte","vad man gör med head of kelris","varför ta kelris huvud"}}},fp="20,210,22.316.0,22.295.0,21.314.1,28.228.0,54.228.0,16.230.0,43.250.0,48.253.0,52.211.0"}
P.entries["quest:65610"] = {n="Wish You Were Here",s="En tillverkare av mooncloth i Ashenvale ber dig hitta Krilge, som försvann medan han skyddade civila. Hans kamrater kallar honom desertör, men tillverkaren tror att han stod kvar på sin post.",h="En tillverkare av mooncloth i Ashenvale ber dig hitta Krilge, som försvann medan han skyddade civila.",kw={"ashenvale","träskbestar","desertör","fallen sky lake","gan'rul bloodeye","krilge","saknad","mooncloth"},sec={{t="En saknad vän",b="En tillverkare av mooncloth träffade Krilge under arbetet med mooncloth i Ashenvale. Krilge var stationerad där för att skydda civila, men försvann sedan. De träffades ofta vid Fallen Sky Lake, tills aggressiva träskbestar tog över platsen. Tillverkaren hoppas fortfarande få veta vad som hände med honom."},{t="Vid sjön",b="Du ombeds söka igenom Fallen Sky Lake och rapportera dina fynd till Gan'rul Bloodeye i Orgrimmar. Krilges kamrater har slutat leta efter honom. Kanske finns det fortfarande ett spår i sjön som visar vad som hände honom."}},faq={{q="Vem är Krilge?",a="Krilge var stationerad i Ashenvale för att skydda civila innan han försvann. Han och tillverkaren av mooncloth träffades ofta vid Fallen Sky Lake.",al={"krilge","mooncloth-tillverkarens saknade vän"}},{q="Varför kallas Krilge desertör?",a="Krilge försvann från sin post. De som tjänstgjorde med honom slutade leta och kallar honom desertör.",al={"krilge desertör","varför de slutade leta"}},{q="Vem ber dig leta efter Krilge?",a="En tillverkare av mooncloth som träffade Krilge i Ashenvale ber dig att leta efter spår av honom.",al={"vem skickade mig","tillverkare av mooncloth"}},{q="Var träffades Krilge och tillverkaren?",a="Krilge och tillverkaren träffades ofta vid Fallen Sky Lake i Ashenvale, innan aggressiva träskbestar tog över området.",al={"krilges mötesplats","var ligger fallen lake"}},{q="Var ska du rapportera vad du hittar?",a="Du ombeds rapportera dina fynd till Gan'rul Bloodeye i Orgrimmar.",al={"rapportera till gan'rul","var rapporterar jag"}}},fp="18,169,16.258.0,11.205.0,14.134.0,38.99.0,32.83.0,36.110.0,38.71.0"}
P.entries["quest:6562"] = {n="Trouble in the Deeps",s="Trouble in the Deeps är en vädjan om hjälp från Stonetalon Mountains till Ashenvales avlägsna stränder. Tsunaman skickar Horde-äventyrare till trollforskaren Je'neu Sancrea vid Zoram'gar Outpost och varnar för farliga krafter längs kusten.",h="Trouble in the Deeps är en vädjan om hjälp från Stonetalon Mountains till Ashenvales avlägsna stränder.",kw={"ashenvale","blackfathom deeps","je'neu sancrea","stonetalon mountains","tsunaman","windshear crag","the zoram strand","zoram'gar outpost"},ang={["class:Shaman"]="Störningen under vågorna vid The Zoram Strand hotar balansen bland de lokala vattenandarna, och kräver andlig insikt för att rena förruttnelsen.",["faction:Horde"]="Det är avgörande att hålla ställningarna vid Zoram'gar Outpost för att säkra Kalimdors västra flank mot både Night Elf-styrkor och fasor från kusten.",["race:Troll"]="Genom att svara på Je'neu Sancreas kallelse får Darkspear-fränder en viktig möjlighet att hjälpa en av sina främsta lärda att avslöja Kalimdors uråldriga hemligheter."},sec={{t="En kallelse till kusten",b="I Stonetalon Mountains torra klipplandskap inser Tsunaman att mörka dån i norr kräver uppmärksamhet. Han ger Horde-resenärer med rätt förmåga i uppdrag att ta sig in i Ashenvale, Night Elf-folkets urgamla skog, och kontakta Je'neu Sancrea. Je'neu är stationerad vid Zoram'gar Outpost längs den avlägsna västra kusten, som kallas The Zoram Strand, och har hamnat inför en växande fara som kräver hjälp utifrån."},{t="Vägen till The Zoram Strand",b="Det är ingen enkel resa för Horde-resenärer att nå Ashenvales västra kust. Oavsett om de tar sig genom Windshear Crags pass, störda av gobliner, eller färdas norrut från The Barrens måste de ta sig in i en fientlig skog som vaktas hårt av Night Elf-väktare. Långt bortom de täta trädkronorna klamrar sig den ensliga utposten fast vid tillvaron på The Zoram Strands stormpinade kust, med blicken riktad mot det skuggiga vattnet intill."},{t="Viskningar under vågorna",b="När du kommer fram till stranden avslöjar Je'neu Sancrea att oron har sina rötter i det underjordiska templet Blackfathom Deeps. Uråldriga fördärv, vidriga vattenelementarer och kultister från Twilight's Hammer har samlats under tidvattnet och lockar urgamla ondskor tillbaka till världen. Je'neu förlitar sig på att de anländande hjältarna beger sig under ytan och möter den urtida fasa som väckts i de sjunkna salarna."}},faq={{q="Vem ger uppdraget Trouble in the Deeps?",a="Tsunaman, som finns i Stonetalon Mountains, erbjuder uppdraget. Han inser att allierade längs Ashenvales kust behöver förstärkning och visar Horde-äventyrare vägen mot havet.",al={"uppdragsgivare","vem startar trouble in the deeps","tsunaman"}},{q="Var finns Je'neu Sancrea?",a="Je'neu Sancrea är stationerad vid Zoram'gar Outpost på The Zoram Strand, vid Ashenvales avlägsna västkust.",al={"var finns je'neu","je'neu sancreas plats","zoram'gar outpost"}},{q="Hur tar du dig från Stonetalon till Zoram'gar Outpost?",a="Resenärer kan färdas nordost genom Windshear Crag och in i Ashenvale, eller ta en omväg österut genom The Barrens och gå in i skogen söderifrån. Från centrala Ashenvale ska du bege dig rakt västerut tills du når The Zoram Strands öppna vatten.",al={"vägen till ashenvale","hur tar man sig till zoram strand","väg från stonetalon till ashenvale"}},{q="Vilka problem undersöker Je'neu?",a="Je'neu Sancrea bevakar ruinerna av Blackfathom Deeps i närheten, där kultister och fördärvade vattenvarelser rör upp uråldriga fasor under ytan.",al={"vad händer vid zoram strand","varför behöver je'neu hjälp"}},{q="Vilket uppdrag följer efter Trouble in the Deeps?",a="Om du talar med Je'neu Sancrea får du uppdraget The Essence of Aku'Mai, som skickar äventyrare in i Blackfathom Deeps för att samla in Aku'mais elementladdade safirer från gångarna.",al={"nästa uppdrag","fortsättning på trouble in the deeps"}},{q="Varför är resan genom Ashenvale farlig?",a="Ashenvale är Night Elf-folkets suveräna domän, och de gör hårt motstånd mot alla Horde-intrång. Resenärer som färdas genom skogen riskerar att stöta på fientliga väktare och svårupptäckta bakhållsmän.",al={"faran i ashenvale","hotet från night elf"}}},fx={dde1b6c4={q="Varför skickar Tsunaman dig till Je'neu Sancrea?",a="Tsunaman vet att Je'neu Sancrea är isolerad vid den avlägsna Zoram'gar Outpost och desperat behöver pålitliga allierade. Je'neu är stationerad vid Ashenvales avlägsna västkust och möter allt större faror kring Blackfathom Deeps mystiska djup utan tillräckligt stöd. Tsunaman skickar dig för att förstärka hans styrkor innan fientliga krafter övermannar Hordens fäste.",al={"varför tsunaman vill ha det gjort","varför skicka mig till ashenvale","tsunamans motiv"}}},fp="20,192,22.271.0,24.383.0,24.318.1,41.99.0,32.99.0,51.196.0,37.144.0,40.120.0,57.133.0"}
P.entries["quest:6563"] = {n="The Essence of Aku'Mai",s="Je'neu Sancrea vid Zoram'gar Outpost har märkt att naga från Blackfathom Deeps bryter loss kraftfulla safirkluster ur grottorna. Shamanen oroar sig för deras magiska egenskaper och elementära vattenenergier och ger Hordens äventyrare i uppdrag att hämta ädelstenarna innan de missbrukas.",h="Je'neu Sancrea vid Zoram'gar Outpost har märkt att naga från Blackfathom Deeps bryter loss kraftfulla...",kw={"ashenvale","blackfathom deeps","je'neu sancrea","naga","sapphire of aku'mai","trouble in the deeps","vattenandar","the zoram strand"},ang={["class:Shaman"]="När Je'neu Sancrea läser av kristallerna märker han de oroliga vattenandar som är bundna i dem. Det är en diskret varning om att elementarkrafterna fördärvas under templet.",["faction:Horde"]="Hordens fäste vid Zoram'gar Outpost är utsatt. Om du hindrar naga i närheten från att få tag på rå magisk kraft skyddar du lägerplatsen vid kusten.",["race:Troll"]="Je'neu Sancrea är en uppmärksam Darkspear-mystiker som förlitar sig på kontakt med andarna och förfädernas visdom för att hantera Kalimdors märkliga hot."},sec={{t="Ett hot i djupet",b="På Zoram Strandens dimhöljda stränder håller Darkspear-shamanen Je'neu Sancrea vakt över forntida Kaldorei-ruiner som nu har tagits över av mörka krafter. Djupt inne i Blackfathom Deeps nedsänkta kamrar har naga börjat bryta fram lysande safirformationer som växer längs de fuktiga grottväggarna. Sancrea känner att de ormliknande inkräktarna vill tämja denna oberäkneliga kraft och försöker stoppa skörden innan deras planer kan bli verklighet."},{t="Vattenandar och arkan kraft",b="Aku'mais safirer är mycket mer än vanliga ädelstenar. De vibrerar av elementär resonans och hyser vattenandar som klamrat sig fast vid dem. I händerna på skickliga trollkarlar kan sådana kraftkällor driva farliga arkanritualer eller förstärka inflytandet från den skuggmörka hydran Aku'mai, vars mörka närvaro genomsyrar det underjordiska templet. När du hämtar klustren berövas naga en ovärderlig ingrediens, och kusten skyddas från okontrollerad elementarmagi."}},faq={{q="Vem ger det här uppdraget?",a="Uppdraget ges av Je'neu Sancrea, en Darkspear-trollshaman som är stationerad vid Zoram'gar Outpost på Zoram Strand i nordvästra Ashenvale.",al={"uppdragsgivare","vem startar essence of akumai","jeneu sancreas plats"}},{q="Varför vill naga ha Aku'mais safirer?",a="Deras exakta plan är fortfarande höljd i dunkel, men safirerna rymmer kraftfull elementär vattenenergi och rå magisk kraft, vilket gör dem till synnerligen farliga ingredienser i nagas besvärjelser.",al={"varför vill naga ha safirer","vad ska kristallerna användas till","safirernas syfte"}},{q="Var finns safirklustren?",a="De täcker grottväggar och golv i de yttre gångarna och översvämmade passagerna i Blackfathom Deeps, strax innanför den förstörda underjordiska ingången längs Zoram Strand.",al={"var hittar man safirer","sapphire of akumai plats","kristallernas växtplatser"}},{q="Vad är Aku'mai?",a="Aku'mai är en monstruös trehövdad hydra som lever djupt inne i de översvämmade tempelruinerna. Twilight's Hammer-kultisterna vördar honom och fruktar honom som en tjänare åt de gamla gudarna.",al={"vem är akumai","vad är akumai","aku'mai"}},{q="Måste jag döda några grottbossar för det här uppdraget?",a="Nej. Safirklustren växer längs grottväggarna i de tidiga, översvämmade gångarna, innan du möter Blackfathom Deeps huvudbossar.",al={"behöver jag en hel grupp","kan jag hämta safirerna ensam","krävs en boss"}},{q="Har det här uppdraget samband med någon annan berättelse?",a="Ja. Det följer efter 'Trouble in the Deeps' och ingår i Je'neu Sancreas undersökning av det växande mörkret och kultisternas verksamhet i Blackfathom Deeps.",al={"uppdragskedja","förkunskapskrav","trouble in the deeps"}}},fx={["7dd39a86"]={q="Varför vill Je'neu Sancrea ha Sapphires of Aku'Mai?",a="Je'neu Sancrea har lagt märke till hur nagaerna systematiskt skördar dessa kristallformationer från grottväggarna i Blackfathom Deeps. Även om deras plan fortfarande är oklar känner han en enorm elementarkraft i stenarna. Han vill samla in dem innan nagaerna kan använda dem som kraftfulla magiska komponenter.",al={"je'neu sancreas motiv","varför samla safirer","varför samla sapphires of akumai"}},["644dacf9"]={q="Vad är Sapphire of Aku'Mai?",a="Dessa safirer är kristallformationer som täcker de översvämmade gångarna i Blackfathom Deeps. De vibrerar av rå elementarkraft och drar till sig vattenandar som klamrar sig fast vid dem. Tack vare denna naturliga koncentration av energi är de kraftfulla magiska reagenser om kraften leds på rätt sätt.",al={"vad safirerna är","sapphire of akumai bakgrund","sapphires of akumai kraft"}}},fp="22,160,22.319.0,30.364.0,21.129.0,46.137.0,38.185.0,16.158.0,52.117.0,47.151.0"}
P.entries["quest:6564"] = {n="Allegiance to the Old Gods",s="Allegiance to the Old Gods är ett Horde-uppdrag som börjar när du hittar ett vattenskadat meddelande från nagas i Blackfathom Deeps. När du lämnar lappen till Je'neu Sancrea vid Zoram'gar Outpost avslöjas en ondskefull ritual som pågår djupt inne i Blackfathom Deeps översvämmade ruiner.",h="Allegiance to the Old Gods är ett Horde-uppdrag som börjar när du hittar ett vattenskadat meddelande från...",kw={"aku'mai","trohet","ashenvale","blackfathom deeps","damp note","je'neu sancrea","lorgus jett","gamla gudar","wrathscale","zoram'gar outpost"},ang={["class:Shaman"]="Nagas underkuvande av vattenelementarernas andar i rituella kristaller är en allvarlig förvrängning av den naturliga balansen och måste rättas till snabbt.",["faction:Horde"]="När du avslöjar Lorgus Jetts lapp bidrar du till att skydda Zoram'gar Outpost mot Twilight's Hammer och deras naga-allierade, som hotar Hordens fotfäste på Ashenvales västkust.",["race:Troll"]="När du hjälper din Darkspear-frände Je'neu Sancrea avslöjar du uråldriga kosmiska väsen vars återkomst skulle hota varje stam på Azeroth."},sec={{t="En nedklottrad förklaring",b="Under striderna mot nagas i Blackfathom Deeps hittar Hordens spejare en fuktig, skrynklig lapp med en desperat handstil. På pergamentet står instruktioner till naga-prästinnorna om att samla elementära vattenkristaller. Kristallerna samlas inte in för att plundra urskillningslöst, utan ska driva naga-akvamantiernas besvärjelser och samla elementarkrafter till ett betydligt mörkare syfte."},{t="Viskningar från djupet",b="De återfunna orderna avslöjar att nagas tänker använda kristallernas elementarkraft för att blidka och till fullo frammana Aku'mai, en monstruös hydra i de gamla gudarnas tjänst. I lappen står djärvt att detta ska förebåda återkomsten av världens ”största era” – de gamla gudarnas förhistoriska välde. När lappen tas emot vid Zoram'gar Outpost identifierar Darkspear-mystikern Je'neu Sancrea upphovsmannen bakom sammansvärjningen: Twilight's Hammer-kultisten Lorgus Jett."}},faq={{q="Vad är Damp Note?",a="Damp Note är en samling återfunna order, skrivna av Twilight's Hammer-kultisten Lorgus Jett. De instruerar naga-prästinnor att samla elementarladdade kristaller för att stärka sina akvamantier och frammana den monstruösa tjänaren Aku'mai.",al={"damp note","vad står det i lappen","lappens historia"}},{q="Vem är Je'neu Sancrea?",a="Je'neu Sancrea är en Darkspear-trollsiaregubbe och lärd som är stationerad vid Zoram'gar Outpost i Ashenvale. Som representant för The Earthen Ring undersöker han elementära obalanser och uråldriga hot som väcks i ruinerna av Blackfathom Deeps i närheten.",al={"jeneu sancrea","vem är jeneu","uppdragsgivare vid zoram outpost"}},{q="Vem är Lorgus Jett?",a="Lorgus Jett är en mänsklig shaman från Twilight's Hammer-kulten som verkar inne i Blackfathom Deeps, där kultisterna samarbetar med nagas. Han övervakar insamlingen av elementarkristaller för att stärka nagas ritualer och väcka mörka, uråldriga fasor till liv.",al={"lorgus jett","vem skrev lappen","nagal ledare zoram"}},{q="Vad är Aku'mai?",a="Aku'mai är en kolossal, trehövdad hydra som lever i de översvämmade djupen av Blackfathom Deeps. Varelsen är nära knuten till de gamla gudarnas ursprungliga mörker och vördas av både Twilight's Hammer-kulten och nagas i Blackfathom Deeps.",al={"akumai","vem är akumai","aku'mais historia"}},{q="Varför samlar nagas vattenkristaller?",a="Vattenelementarernas andar som är fångade i kristallerna ger rå kraft åt nagas akvamantier. Genom att suga åt sig denna elementarmagi hoppas de kunna blidka Aku'mai och samla tillräcklig kraft för att bana väg för de gamla gudarnas återkomst.",al={"varför samlar nagas kristaller","elementarkristaller naga","akvamantiernas kristaller"}},{q="Vart leder den här uppdragskedjan?",a="När du lämnar lappen till Je'neu Sancrea får du direkt ett uppföljande uppdrag att spåra upp och döda Lorgus Jett för att sätta stopp för kultens ritualplaner i Blackfathom Deeps.",al={"vad kommer efter allegiance to the old gods","allegiance to the old gods del 2","nästa uppdrag"}}},fp="26,141,23.300.0,20.366.1,22.211.0,22.207.0,19.213.0,16.198.0,43.195.0,33.152.1"}
P.entries["quest:6565"] = {n="Allegiance to the Old Gods",s="Allegiance to the Old Gods är ett uppdrag åt Horden där äventyrare ska eliminera Lorgus Jett i djupen av Blackfathom Deeps. Darkspear-siaren Je'neu Sancrea vid Zoram'gar Outpost leder uppdraget, som ska störa Twilight's Hammer-kultisterna som försöker väcka uråldriga förstörelsekrafter. Genom att fälla Lorgus utdelas ett direkt slag mot kultens omstörtande verksamhet under Ashenvales kust.",h="Allegiance to the Old Gods är ett uppdrag åt Horden där äventyrare ska eliminera Lorgus Jett i djupen av...",kw={"allegiance to the old gods","ashenvale","blackfathom deeps","je'neu sancrea","lorgus jett","gamla gudar","twilight's hammer","zoram'gar"},ang={["class:Shaman"]="Twilight's Hammer försöker släppa lös elementens vrede i de kaotiska gamla gudarnas tjänst. Därför måste de utrotas av dem som tillsammans med Earthen Ring svurit att bevara elementens balans.",["faction:Horde"]="När Lorgus Jett fälls säkras utkanterna kring Zoram'gar Outpost, och Hordens isolerade kustläger i Ashenvale skyddas mot kultisternas lömska planer.",["race:Troll"]="Genom att hjälpa Je'neu Sancrea hedrar du visdomen hos en respekterad Darkspear-siare som långt från Echo Isles skyddar Azeroths ursprungliga andar."},sec={{t="Hotet under Zoram'gar",b="Hordens utpost vid Zoram'gar ligger på Ashenvales strand och håller orolig uppsikt över Blackfathom Deeps. Det översvämmade tempelkomplexet har blivit en grogrund för mörk magi och svämmar över av naga, fördärvade bestar och Twilight's Hammers beslöjade fanatiker. Je'neu Sancrea, en siande medlem av Earthen Ring som är stationerad vid kusten, inser att kultisterna varken vördar naturens balans eller landets andar. I stället svär de trohet till de gamla gudarna, monstruösa kaosvarelser som besegrades i forntiden men vars onda beröring fortfarande dröjer kvar på Azeroths bortglömda platser."},{t="Lorgus Jetts fall",b="Je'neu skickar Hordens mästare in i de underjordiska ruinerna för att jaga Lorgus Jett, en av kultisternas viktigaste ledare. Lorgus rör sig djupt inne i stenkorridorerna mellan kamrarna där jättesköldpaddan Ghamoo-ra och vattenelementaren Baron Aquanis finns. Je'neu är själv för bräcklig för att tåga in i det fuktiga mörkret, så det är avgörande att döda Lorgus för att sätta stopp för de mörka ritualer kultisten försöker iscensätta under Ashenvales vågor."},{t="Hålla kaoset stången",b="När Lorgus Jett dör är det omedelbara rituella hotet mot kusten under kontroll, men Je'neu medger att Twilight's Hammer är långt ifrån utrotat. Kultens tysta infiltration av forntida heliga platser vittnar om ett större, växande hot som inte nöjer sig med mindre än att de gamla gudarna återvänder i full styrka. För Horden vid Zoram'gar ger Lorgus fall värdefull tid mot en fiende som gömmer sig i världens skuggor."}},faq={{q="Vem är Lorgus Jett?",a="Lorgus Jett är en framstående ledare bland Twilight's Hammers kultister i Blackfathom Deeps. Han leder kultens ritualer, som ska bana väg för de gamla gudarnas återkomst och välde.",al={"lorgus jett","vem är lorgus","lorgus jett bakgrund"}},{q="Var finns Lorgus Jett i Blackfathom Deeps?",a="Lorgus Jett patrullerar Blackfathom Deeps översvämmade korridorer, särskilt gångarna mellan Ghamoo-ras kammare och Baron Aquanis altare.",al={"lorgus jett plats","var finns lorgus","hitta lorgus jett"}},{q="Vem är Je'neu Sancrea?",a="Je'neu Sancrea är en siande Darkspear-troll knuten till Earthen Ring. Han är stationerad vid Zoram'gar Outpost på The Zoram Strand i Ashenvale, där han håller uppsikt över elementära störningar och fördärvet i Blackfathom Deeps.",al={"je'neu sancrea","vem ger sin trohet till de gamla gudarna","jeneu"}},{q="Varför bryr sig Je'neu om Twilight's Hammer?",a="Som siare hängiven åt att förstå naturen och elementens balans ser Je'neu Twilight's Hammer som ett existentiellt hot. Kulten tjänar de gamla gudarna, kaotiska uråldriga väsen vars återkomst skulle kullkasta världens harmoni.",al={"varför bekämpa twilight's hammer","earthen ring gamla gudar"}},{q="Vad är de gamla gudarna?",a="De gamla gudarna är ursprungliga väsen av kaos och förstörelse som härskade över Azeroth i urminnes tider innan de besegrades och begravdes. Twilight's Hammers kult dyrkar dem aktivt och smider planer på att bryta deras sigill och återupprätta deras förödande välde.",al={"gamla gudarnas bakgrund","vilka är de gamla gudarna","kaosvarelser"}},{q="Varför kan inte Je'neu Sancrea döda Lorgus Jett själv?",a="Je'neu erkänner att han är för bräcklig och svag för att på egen hand trotsa farorna i Blackfathom Deeps. Han förlitar sig på Hordens dugliga mästare för striden medan han följer de andliga och elementära störningarna från utposten.",al={"varför följer jeneu inte med","är jeneu svag"}}},fp="26,239,28.446.0,18.398.0,17.332.1,19.168.0,52.141.0,22.201.0,49.212.0,22.243.0,50.156.0"}
P.entries["quest:6568"] = {n="The Testament of Rexxar",s="Rexxar säger att en illusion krävs för att smita förbi Black Flights försvar. Han känner en mästerillusionist, Myranda the Hag, som bor i Western Plaguelands, och skickar dig till henne med ett meddelande.",h="Rexxar säger att en illusion krävs för att smita förbi Black Flights försvar.",kw={"black dragonflight","desolace","illusion","mästare i bedrägeri","myranda the hag","rexxar","sorrow hill","testamentet om rexxar","western plaguelands"},sec={{t="Illusionskonsten",b="Rexxar frågar vad du vet om illusioner, eftersom en illusion är sättet du kommer förbi Black Flights försvar. Han nämner någon som kan hjälpa dig med bedrägeriet: Myranda the Hag, en mästerillusionist som drevs bort av Lordaeronalliansen och bor i Western Plaguelands. Rexxar säger att hon har hjälpt hans folk tidigare, närhelst hon funnit en sak värd att kämpa för. Du för hans meddelande till henne."},{t="En besökare i Lordaeron",b="Myranda påpekar att en medlem av Horde är en ovanlig syn i de här delarna av Lordaeron, och frågar vad du har med dig åt henne."},{t="Myrandas svar",b="Myranda håller i lappen, gör en paus och ler. Hon frågar hur Rexxar har det och förklarar sedan att sidan var tom med flit: den innehöll skribentens tankar och avsikter, och hon förstår varför han inte skrev dem med bläck, eftersom det hade varit farligt om du blivit tillfångatagen eller dödad. Hon går med på att hjälpa dig, eftersom hon är skyldig Warchiefen en tjänst eller två."}},faq={{q="Vem är Myranda the Hag?",a="Myranda the Hag är en mästerillusionist som en gång tillhörde Lordaeron och förvisades av dess allians. Hon finns i Western Plaguelands, vid Sorrow Hill.",al={"vem är myranda","myranda the hag bakgrund","var finns myranda"}},{q="Varför måste du söka upp en illusionist?",a="Rexxar säger att en illusion är sättet du kommer förbi Black Flights försvar, och han känner en mästare som kan hjälpa dig.",al={"varför förklädnad","varför söka en illusionist","lura black dragonflight"}},{q="Vart skickar Rexxar dig?",a="Han skickar dig till Western Plaguelands för att hitta Myranda the Hag vid Sorrow Hill.",al={"vart ska jag gå","var finns sorrow hill","mästare i bedrägeri destination"}},{q="Har Myranda hjälpt Horde tidigare?",a="Rexxar säger att hon har hjälpt hans folk tidigare, närhelst hon funnit saken värd att kämpa för.",al={"gillar myranda horde","myranda alliance eller horde","myranda tjänst warchief"}}},fp="23,150,19.293.0,22.121.0,16.334.1,23.136.0,37.105.0,27.83.0,36.82.0"}
P.entries["quest:657"] = {n="Hints of a New Plague?",s="Quae har gått igenom mappen och fått veta att Apothecary Jorell utför dödliga experiment på Go'Shek Farm. Quae är illa däran efter en sammandrabbning med orcher och kan inte hjälpa Kinelory, som behöver ditt skydd när hon beger sig till gården för att stjäla den forskning av Jorells som ännu inte skickats till Tarren Mill.",h="Quae har gått igenom mappen och fått veta att Apothecary Jorell utför dödliga experiment på Go'Shek Farm.",kw={"apothecary jorell","forsaken","go'shek farm","kinelory","phin","pest","quae","tarren mill"},sec={{t="Jorells experiment",b="Quae läser igenom mappen och upptäcker att Apothecary Jorell utför dödliga experiment på Go'Shek Farm. Quae förstår inte hur detta berör Hillsbrad, men Phin skulle inte vilja att det fortsatte. En del av Jorells forskning har redan skickats till Tarren Mill."},{t="Kinelorys beskyddare",b="Medan du var borta drabbade Quae samman med några orcher och är inte i skick att hjälpa Kinelory. Kinelory tänker bege sig till gården och stjäla den forskning som Jorell ännu inte har skickat till Tarren Mill, och hon behöver skydd. Du ska tala med Kinelory."},{t="Kinelorys beslutsamhet",b="Kinelory säger att hon personligen ska förgöra varenda en av Forsaken om det ger Phin ro. Phin har gjort så mycket för Kinelory och de andra sedan pesten, och de trodde aldrig att de skulle hitta vänner eller familj igen. Kinelory ber dig säga till när du är redo, så sätter ni igång genast."}},faq={{q="Varför kan inte Quae följa med Kinelory?",a="Quae drabbade samman med några orcher medan du var borta och är inte i skick att hjälpa Kinelory.",al={"varför stannar quae","varför hjälper quae inte","varför eskortera kinelory ensam"}},{q="Vad upptäcktes i mappen?",a="Att Apothecary Jorell har utfört dödliga experiment på Go'Shek Farm.",al={"vad fanns i mappen","jorells experiment","vad gör jorell"}},{q="Varför undersöker Quae och Kinelory detta?",a="De är Phins följeslagare. Phin leder en grupp äventyrare som undersöker märkliga händelser. Phin skulle inte vilja att Jorells experiment fick fortsätta.",al={"vem är phin","varför bryr de sig om pesten","varför hjälpa phin"}},{q="Vart skickas forskningen?",a="En del har redan skickats till Tarren Mill. Kinelory tänker stjäla det som Jorell ännu inte har skickat.",al={"vart skickas anteckningarna","forskning i tarren mill"}}},fp="22,186,20.228.0,20.209.0,18.318.1,34.78.0,34.74.0,45.159.0,33.107.0"}
P.entries["quest:6571"] = {n="Warsong Supplies",s="Warsong Supplies är ett omfattande logistikuppdrag för Horde, som Locke Okarr ger vid Splintertree Post. För att hålla Warsong Lumber Camp igång måste livsviktig avverkningsutrustning återtas från fientliga furbolg- och satyrmarker, samtidigt som varor anländer från avlägsna goblinhamnar.",h="Warsong Supplies är ett omfattande logistikuppdrag för Horde, som Locke Okarr ger vid Splintertree Post.",kw={"ashenvale","booty bay","locke okarr","logging rope","pixel","sågblad","splintertree post","warsong lumber camp","warsong oil","warsong supplies"},ang={["faction:Horde"]="Hordes expansion i Durotar är helt beroende av timmer som Warsong Clan säkrar. När verktygen återtas stärks grunden för Orgrimmar direkt.",["profession:Engineering"]="Goblin-delarna i den här leveransen visar hur viktig den mekaniska försörjningskedjan är, från Pixels sågblad till ångmaskinssmörjmedel, för att fälla uråldriga skogar.",["race:Orc"]="Att hedra Warsong Clans arv i Ashenvale innebär att hålla yxorna vassa och lägren välförsedda, trots ständiga trakasserier från skogens invånare."},sec={{t="Sågarna måste snurra",b="Warsong Clans kampanj för att skörda Ashenvales uråldriga timmer kräver en ständig ström av tunga verktyg. Från utposten vid Splintertree Post måste Hordes kvartermästare ständigt hantera störningar i leveranserna. Locke Okarr ansvarar för att hålla sågverket fullt utrustat, men lokala transporter har slagits i spillror av räder från den inhemska faunan och demoniska kultister, vilket lämnat verksamheten utan livsviktig utrustning."},{t="En splittrad logistikkedja",b="Att säkra den utrustning som behövs är en prövning som sträcker sig över stora delar av Kalimdor och till och med över havet. Cirkelsågblad väntar på att hämtas från goblinkuriren Pixel här vid Splintertree Post, medan en låda tunga yxor kräver att du hämtar en leverans från Wharfmaster Lozgil nere i Booty Bay. De återstående nödvändiga varorna måste ryckas direkt ur fiendens händer: stadiga avverkningsrep som fientliga Foulweald- och Thistlefur-furbolg har lagt beslag på, och tunnor med Warsong Oil som satyrerna i Night Run, Satyrnaar och Xavian har stulit för att driva sina vanheliga ritualer."}},faq={{q="Vilka Warsong Supplies behövs?",a="Locke Okarr behöver fyra viktiga föremål: en leverans Warsong Saw Blades som goblinen Pixel har, en låda Warsong Axes som skickats till Booty Bay, tunga Logging Rope som lokala furbolg har plundrat och tunnor Warsong Oil som Ashenvales satyrer har stulit.",al={"warsong supplies lista","vilka föremål behövs","förnödenheter som behövs"}},{q="Vem är Locke Okarr?",a="Locke Okarr är en ork vid Splintertree Post som ansvarar för att samordna materialleveranser till Warsong Lumber Camp. Under hård press att undvika driftstopp tar han hjälp av kringvandrande Horde-äventyrare för att återta sina utspridda leveranser.",al={"locke okarr berättelse","vem ger warsong supplies","uppdragsgivare vid splintertree"}},{q="Varför skickar Horde utrustning från Booty Bay?",a="Horde förlitar sig på neutrala handelsnätverk som Steamwheedle Cartel för att importera specialtillverkade varor som Durotar och The Barrens inte enkelt kan smida i stora mängder. Tunga avverkningsyxor som beställs genom goblinkanaler går via sjöfartens knutpunkter, som Booty Bay, innan de når Ashenvale.",al={"varför booty bay","yxleverans till booty bay","steamwheedle-verktyg"}},{q="Varför vill satyrerna ha Warsong Oil?",a="Satyrerna som håller till i ruiner som Satyrnaar, Night Run och Xavian använder inte oljan till maskiner. I stället leder de den stulna industrioljan till mörka, fördärvade riter tillägnade Burning Legion och den spridande smittan från Felwood.",al={"satyrernas olja berättelse","varför har satyrer olja","warsong oil ritualer"}},{q="Vilka furbolg stal avverkningsrepet?",a="Foulweald- och Thistlefur-furbolgstammarna överföll och tog Logging Rope. Båda stammarna hyser en häftig territoriell fientlighet mot Hordes kalhuggning i Ashenvale.",al={"vem stal repet","furbolgernas rep berättelse","foulweald thistlefur rep"}},{q="Varför är Warsong Lumber Camp så viktigt för Horde?",a="Durotars torra marker erbjuder nästan inget användbart byggnadstimmer. Warsong Clan skickades till Ashenvales lummiga gränsmarker just för att skörda de väldiga träd som behövs för att bygga Orgrimmar och driva Hordes växande militära infrastruktur.",al={"varför skörda i ashenvale","warsong lumber betydelse","orcher som fäller träd"}}},fx={b7ffa730={q="Varför behöver Locke Okarr att de här förråden samlas in?",a="Locke Okarr ansvarar för att förse Warsong Lumber Camp, där viktiga verktyg börjar sina farligt mycket. Leveranser har försenats, stulits eller stoppats runtom i Ashenvale och bortom dess gränser. Om han inte levererar det nödvändiga timmerutrustningen i tid får han allvarliga problem med sina överordnade i Warsong-klanen.",al={"varför locke okarr behöver förråd","varför samla förråd åt locke okarr","locke okarrs motiv"}},["54c7a3c1"]={q="Vad används Warsong Saw Blades till?",a="Sågbladen är viktiga industrikomponenter i de mekaniska flismaskiner och sågverk som används vid Warsong Lumber Camp. Utan nya blad kan inte Hordens tunga skogsmaskiner effektivt fälla Ashenvales väldiga uråldriga träd och förse Orgrimmor och lokala läger med byggvirke.",al={"vad sågblad används till","hur warsong saw blades används","sågblad vid timmerlägret"}},["9c63ad01"]={q="Vad används Warsong Axe Shipment till?",a="Den här lådan med kraftiga yxor har skickats hela vägen från goblinernas gjuterier i Booty Bay. Den förser Warsong Outriders och arbetare som röjer tät snårskog och fäller Ashenvales täta skog för hand. I en fientlig skog full av Night Elf och vilddjur fungerar de tåliga verktygen också som pålitliga krigsvapen.",al={"vad yxleveransen är till för","hur warsong axe shipment används","yxleverans från booty bay"}},["74cafbab"]={q="Vad används Warsong Oil till?",a="Warsong Oil är ett trögflytande smörjmedel som behövs för att hålla lägrets ångmaskiner, flismaskiner och komplicerade skogsmaskiner i gott skick under hård belastning. Utan den kärvar det tunga järnverket och timmerarbetet stannar helt.",al={"vad warsong oil är till för","warsong oil syfte","varför olja till timmerlägret"}},["76a0db14"]={q="Vad används Logging Rope till?",a="Lägrets arbetare använder det här slitstarka, kraftiga repet för att dra, säkra och hissa upp väldiga trädstammar efter att de fällts. Det är nästan omöjligt att hantera Ashenvales höga träd utan ordentlig riggning, och då riskerar arbetare att krossas eller värdefull utrustning att skadas.",al={"vad logging rope är till för","logging rope syfte","rep vid warsong-lägret"}},["4e02126d"]={q="Varför ber Locke Okarr en äventyrare om hjälp i stället för utpostens vakter?",a="Splintertree Posts garnison är hårt ansträngd av försvaret mot ständiga angrepp från Silverwing Sentinels och fientliga skogsbor. Locke kan inte ta bort viktiga vakter från försvaret av utpostens gräns, och han kan inte heller själv lämna sin post för att genomsöka avlägsna delar av Ashenvale och resa ända till Booty Bay.",al={"varför jag locke okarr","varför kan inte vakterna hämta förråd","varför skickar man inte vakter"}}},fp="16,175,25.277.0,27.361.0,39.194.0,19.186.0,51.263.0,35.173.0,38.139.0,53.281.0"}
P.entries["quest:658"] = {n="Hints of a New Plague?",s="Quae och Kin har bevakat Go'Shek Farm i flera dagar. Kin såg en kurir komma ut ur ett litet hus i söder, och de misstänker att kuriren bär på anteckningar som ska till Tarren Mill. Quae vill ha dokumenten och frågar om du är en skicklig spårare.",h="Quae och Kin har bevakat Go'Shek Farm i flera dagar.",kw={"apotekare","arathi highlands","forsaken courier","go'shek farm","kin","phin odelic","quae","sealed folder","tarren mill"},sec={{t="Bevakning av gården",b="Quae är inte förvånad över att Phin Odelic skickade dig för att se till dem, eftersom Phin oroar sig för mycket. Quae och Kin har bevakat gården i flera dagar. För inte så länge sedan såg Kin en kurir komma ut ur ett litet hus i söder. Kin pratar mycket, men Quae kan alltid lita på Kins sinnen i farliga områden."},{t="Kurirens mapp",b="Quae frågar om du är en skicklig spårare. Kuriren kan bära på anteckningar som ska till Tarren Mill, och om du får tag på dokumenten kan det kasta ljus över vad som händer i Hillsbrad. Du ska hitta Forsaken Courier och ta med hennes Sealed Folder tillbaka till Quae nära Go'Shek Farm. Medan du letar får Kin syn på en apotekare som lämnar samma hus. Quae är säker på att apotekaren har onda avsikter, men behöver bevis innan någon gör något förhastat."}},faq={{q="Vem skickade dig för att hitta Quae och Kin?",a="Phin Odelic skickade dig för att se till dem, men Quae är inte förvånad eftersom Phin oroar sig för mycket.",al={"vem skickade mig till quae","vem startade spår av en ny pest","phin odelic uppdrag"}},{q="Varifrån kom kuriren?",a="Kin såg kuriren komma ut ur ett litet hus i söder.",al={"varifrån kommer kuriren","kurirens plats","hus söder om gården"}},{q="Vart är kuriren på väg?",a="Quae och Kin misstänker att kuriren bär på anteckningar som ska till Tarren Mill.",al={"kurirens destination","vart är kuriren på väg"}},{q="Vilket föremål ska du hämta?",a="Forsaken Couriers Sealed Folder, som ska lämnas tillbaka till Quae nära Go'Shek Farm.",al={"vilket föremål har kuriren","sealed folder"}},{q="Vem mer sågs vid huset?",a="Kin såg en apotekare lämna samma hus i söder medan du var borta.",al={"apotekare vid gården","vem kom ut ur huset"}},{q="Varför vill Quae ha dokumenten?",a="De kan kasta ljus över vad som händer i Hillsbrad, och Quae behöver bevis innan någon gör något förhastat.",al={"varför hämta dokumenten","vad är anteckningarna till för"}}},fp="22,215,17.252.0,20.399.0,34.93.0,32.53.0,29.69.0,35.69.0,34.83.0,33.109.0"}
P.entries["quest:6581"] = {n="Warsong Saw Blades",s="Warsong Saw Blades är ett uppdrag åt Horde vid Splintertree Post, kopplat till Warsong Clans skogsavverkning. För att få tag på tunga sågblad från Ratchet måste äventyrare göra upp i hemlighet med kuriren Pixel, som kräver personligt skydd innan hon lämnar över lasten. När bytet är genomfört får Horde viktig utrustning som håller sågverken i Ashenvale i gång.",h="Warsong Saw Blades är ett uppdrag åt Horde vid Splintertree Post, kopplat till Warsong Clans skogsavverkning.",kw={"ashenvale","deadly blunderbuss","pixel","ratchet","splintertree post","warsong outriders","warsong saw blades","warsong supplies"},ang={["faction:Horde"]="Skogslägren i Ashenvale utgör den viktiga strukturella ryggraden i Orgrimmars expansion, så varje leverans av maskiner är avgörande för Hordes överlevnad på Kalimdor.",["profession:Engineering"]="Deadly Blunderbuss, som Pixel kräver, är en standardprodukt bland skickliga mekaniker och visar hur gobliners och dödligas ingenjörskonst driver logistiken i frontlinjens krig.",["race:Orc"]="Warsong Clan satte sin stolthet på att avverka Ashenvale under Grommash Hellscream. När deras industriella sågblad fortsätter att snurra hedras klanens fortsatta fotfäste i skogen."},sec={{t="En kurirs listiga byteshandel",b="Warsong Clans skogsarbetare i Ashenvale förlitar sig helt på importerade tunga maskiner för att såga genom den uråldriga skogen. Pixel har lyckats frakta en last specialsågblad direkt från goblinhamnen Ratchet till Splintertree Post, men tänker inte bara lämna över dem gratis. I Ashenvales farliga vildmarker räcker mynt bara en bit; personlig säkerhet är mycket mer värd. I stället för att kräva guld vill Pixel byta sågbladen mot en pålitlig Deadly Blunderbuss som kan skydda henne under de farliga resorna genom fientligt område."},{t="Att förse krigsinsatsen",b="Horde värdesätter Ashenvales täta trädkronor, eftersom Durotars torra slätter och The Barrens lider av allvarlig virkesbrist. Men avverkning i uråldriga skogsdungar nöter snabbt ner vanliga yxor, så industriella blad smidda av gobliner är nödvändiga. När Pixels last säkras får Warsongs skogsläger direkt stöd, så att Horde kan fortsätta bygga utposter och krigsmaskiner trots nattalvernas hårda motstånd."}},faq={{q="Vem är Pixel och varför har hon sågbladen?",a="Pixel är en kurir som för närvarande befinner sig vid Splintertree Post. Hon har transporterat en last industriella sågblad direkt från goblinhamnen Ratchet. Hon behåller lasten tills hon har säkrat ett pålitligt vapen för att skydda sig själv.",al={"vem är pixel","pixel splintertree","sågbladskurir"}},{q="Varför vill Pixel ha en Deadly Blunderbuss i stället för guld?",a="Det är mycket farligt att resa genom The Barrens och djupt in på nattalvernas territorium i Ashenvale. Pixel känner till farorna längs vägen och prioriterar personligt försvar framför mynt. Därför kräver hon ett ingenjörstillverkat skjutvapen för att skydda sig under resorna.",al={"varför deadly blunderbuss","pixels vapenbyte","varför vill hon ha ett vapen"}},{q="Varför är sågbladen så viktiga för Horde?",a="Horde behöver enorma mängder virke för att bygga befästningar och krigsmaskiner runt Kalimdor. Vanliga skärverktyg slits snabbt mot Ashenvales uråldriga järnträd, vilket gör importerade mekaniska sågblad livsviktiga för Warsong Clans skogsmaskiner.",al={"varför behövs sågblad","warsongs virke betydelse","varför warsong supplies"}},{q="Varifrån kommer sågbladen ursprungligen?",a="Sågbladen tillverkades och skeppades från Ratchet, den neutrala goblinhamnen på The Barrens östra kust, innan de fraktades landvägen till Splintertree Post.",al={"sågbladens ursprung","sågblad från ratchet","var kom sågbladen ifrån"}},{q="Hur passar uppdraget in i Warsongs skogsavverkning?",a="Uppgiften ingår i det större arbetet med att samla in Warsong Supplies till skogslägren i Ashenvale. När sågbladen hämtas från Pixel uppfylls ett av de viktigaste logistikbehoven för att hålla Hordes skogsavverkning i gång.",al={"warsong supplies kedja","förkunskapskrav för warsong saw blades"}},{q="Kan vem som helst tillverka vapnet Pixel vill ha?",a="En Deadly Blunderbuss tillverkas av skickliga ingenjörer med kopparrör, kopparbultar, en träkolv och läder. Kurirer och krigare byter dock ofta till sig sådana på lokala marknader eller från andra äventyrare.",al={"hur får man tag på deadly blunderbuss","källa till blunderbuss","ingenjörstillverkat vapen"}}},fx={["496db877"]={q="Vad ska Deadly Blunderbuss användas till?",a="Pixel behöver skydd när hon är ute i vildmarken. Som kurir som transporterar gods genom otämjda gränstrakter som Ashenvale och The Barrens är det farligt att resa ensam. I stället för mynt, som inte kan värja henne mot bestar eller nattalver, kräver hon ett pålitligt tekniskt skjutvapen så att hon kan ta hand om sig själv längs vägen.",al={"varför blunderbuss","deadly blunderbuss pixel","vad ska pixel använda blunderbuss till"}}},fp="18,235,25.287.0,24.331.0,50.149.0,57.158.0,51.178.0,46.79.0,58.99.0,39.200.0"}
P.entries["quest:659"] = {n="Hints of a New Plague?",s="Phin Odelic leder en grupp äventyrare som undersöker märkliga händelser i området och tror att de odöda ligger bakom. Två följeslagare, Quae och Kinelory, begav sig till Go'Shek Farm i Arathi Highlands. Ingen har hört av dem på flera dagar.",h="Phin Odelic leder en grupp äventyrare som undersöker märkliga händelser i området och tror att de odöda...",kw={"arathi highlands","go'shek farm","hillsbrad foothills","kinelory","phin odelic","quae","stanley"},sec={{t="Märkliga händelser",b="För inte länge sedan var Phins kusin i Hillsbrad tvungen att avliva sin hund, Stanley. Djuret hade på mystiskt vis svällt upp till enorm storlek och gick våldsamt till angrepp på alla som kom nära. Phin tror att de odöda ligger bakom de märkliga händelserna, och gruppen letar efter tecken som kan bevisa det."},{t="De saknade följeslagarna",b="Quae och Kinelory, två av Phins följeslagare, begav sig till Go'Shek Farm i Arathi Highlands och har inte hört av sig på flera dagar. Phin blir alltmer orolig och vill att du letar efter dem nära gården."}},faq={{q="Vem är Phin Odelic?",a="Phin leder en grupp äventyrare som undersöker märkliga händelser i området.",al={"phin odelic","vem ger ledtrådar om en ny farsot","uppdragsgivare"}},{q="Vad hände med Stanley?",a="Stanley var hunden som tillhörde Phins kusin i Hillsbrad. Djuret svällde på mystiskt vis upp till enorm storlek och gick våldsamt till angrepp på alla som kom nära, så kusinen avlivade det.",al={"hunden stanley","vad hände med hunden","stanley hillsbrad"}},{q="Var ska Quae och Kinelory vara?",a="Nära Go'Shek Farm i Arathi Highlands, dit de begav sig. Phin har inte hört av dem på flera dagar.",al={"var är quae","var är kinelory","quaes plats","hitta quae"}},{q="Varför undersöker Phin saken?",a="Phin tror att de odöda ligger bakom de märkliga händelserna i området, och gruppen letar efter tecken som kan bevisa det.",al={"varför go'shek farm","go'shek farm odöda","undersök go'shek"}}},fp="22,165,14.244.0,22.167.0,19.70.0,25.139.0,43.110.0,26.100.0"}
P.entries["quest:66"] = {n="The Legend of Stalvan",s="Legenden om Stalvan börjar i Darkshire med en olycksbådande vision från stadens siare, Madame Eva. Oroad av ett omen som förebådar döden för hennes barnbarn Alyssa, söker Eva i sina kort och transvisioner efter svar och får fram ett enda namn som dröjer sig kvar: Stalvan. För att nysta upp denna tråd av fasa skickar hon resande till Darkshire Town Hall för att rådfråga stadens arkiv.",h="Legenden om Stalvan börjar i Darkshire med en olycksbådande vision från stadens siare, Madame Eva.",kw={"alyssa","clerk daltry","darkshire","dödskortet","duskwood","madame eva","stalvan","stadshuset"},ang={["class:Priest"]="Präster som vandrar längs Darkshires mörka vägar tar ofta andliga varningar på allvar. Madame Evas isande dödsomen blir därför en angelägen fråga om själavård.",["faction:Alliance"]="När Duskwood kämpar utan regelbundet stöd från Stormwinds armé rycker Alliansens äventyrare ofta in för att hjälpa stadens äldste och skydda utsatta familjer som Madame Evas."},sec={{t="En dödsvision",b="I Duskwoods eviga dunkel verkar Madame Eva som Darkshires siare och tolkar förebud och lägger kort för oroliga stadsbor. Efter att ha ryckts ur sömnen av en fruktansvärd störning rådfrågade Eva sin spåkortlek, men drog bara dödskortet i samband med sitt unga barnbarn Alyssa. Hon sjönk in i en djup, skuggig trans för att tränga igenom mörkret och fick bara fram en enda ledtråd: namnet Stalvan. Skräckslagen över vad detta omen betyder för hennes familj och staden vänder hon sig till dugliga äventyrare som får följa tråden innan tragedin slår till."},{t="Efterforskningar i stadshuset",b="Eva vet att sanningen om Stalvan måste sökas i Darkshires skriftliga historia. Hon skickar äventyrarna över torget till Darkshire Town Hall för att tala med Clerk Daltry, stadens förvaltare av räkenskaper och offentliga arkiv. Daltry ansvarar för stadens dammiga dokument och är därför den enda som kan avgöra om Stalvan var en tidigare invånare, en genomresande eller något långt mer illavarslande begravt i Duskwoods förflutna."}},faq={{q="Vem är Madame Eva?",a="Madame Eva är en spåkvinna och siare som bor i Darkshire. Med kort och transritualer skymtar hon framtidens förebud och känner av magiska störningar som sprider sig genom Duskwood.",al={"madame eva","vem är eva","spåkvinna i darkshire"}},{q="Varför behöver Madame Eva hjälp?",a="Madame Eva hade en skräckinjagande vision som visade att hennes barnbarn Alyssa svävar i livsfara. Hennes kort visade dödskortet, och ur transen fick hon bara fram namnet ”Stalvan”, vilket fick henne att söka hjälp utifrån för att undersöka hotet.",al={"varför börja med stalvan","evas vision","varför hjälpa eva"}},{q="Vem är Clerk Daltry?",a="Clerk Daltry är stadens arkivarie och arbetar inne i Darkshire Town Hall. Han sköter stadens räkenskaper, register och historiska dokument, så honom är det bäst att fråga om okända namn.",al={"clerk daltry","daltry","vem är stadens skrivare"}},{q="Vad är Darkshire Town Hall?",a="Darkshire Town Hall är stadens administrativa centrum. Där finns den lokala förvaltningen, historiska arkiv och Night Watchs ledning.",al={"darkshire town hall","stadshuset i duskwood"}},{q="Vem är Alyssa?",a="Alyssa är Madame Evas unga barnbarn och bor i Darkshire. Evas spådom visade att Alyssa hotas av ett dödligt omen med koppling till någon som heter Stalvan.",al={"alyssa","madame evas barnbarn"}},{q="Vart leder utredningen härnäst?",a="Ett samtal med Clerk Daltry ger tillgång till stadens arkiv och tidigare efterforskningar. Därmed börjar en omfattande utredning i Duskwood och granntrakterna för att avslöja Stalvans historia och öde.",al={"nästa steg för stalvan","vad säger daltry"}}},fx={aeb2106e={q="Vem är Stalvan?",a="I det här skedet är Stalvan knappt mer än ett dunkelt namn som viskas fram under Madame Evas spådomar. Eva blev oroad av en föraning om livsfara kring sitt barnbarn Alyssa, lade korten och föll i djup trans för att få svar. Hon såg döden och bara ett enda namn: Stalvan. Du får i uppdrag att ta reda på vem han var genom att söka i Darkshires gamla handlingar.",al={"vem är stalvan","vem stalvan","vad är stalvan"}},["9e863436"]={q="Varför ber Madame Eva dig i stället för Night Watch?",a="Madame Eva förlitar sig på omen och spådomar snarare än vanliga brottsutredningar, så ett obskyrt namn från en kortläsning är svårt att anmäla formellt till Night Watch. Darkshire är redan belägrat av vargar, spindlar och odöda, och den lokala garnisonen är hårt ansträngd av försvaret av stadens gräns. Hon behöver en självständig äventyrare som diskret kan gräva i gamla kommunala handlingar åt henne.",al={"varför be mig","varför inte stadsvakten","varför inte night watch"}}},fp="21,160,17.366.0,22.301.0,18.166.0,30.180.0,20.166.0,28.109.0,14.145.0,40.185.0"}
P.entries["quest:660"] = {n="Hints of a New Plague?",s="Kinelory är redo att bege sig ner till gården och vill ha dig vid sin sida. Hon oroar sig för att de odöda kan hinna skada folk i Hillsbrad medan de väntar, och du får i uppdrag att eskortera henne tryggt tillbaka till Quae.",h="Kinelory är redo att bege sig ner till gården och vill ha dig vid sin sida.",kw={"eskort","hillsbrad foothills","tecken på en ny farsot","kinelory","farsot","quae"},sec={{t="Håll Kinelory trygg",b="Efter de tidigare stegen i utredningen är Kinelory redo att agera. Hon ber dig följa med henne ner till gården. Du ska eskortera henne tryggt tillbaka till Quae, och alla som bryr sig om Hillsbrads folk uppmanas att skydda henne."},{t="Tryggt tillbaka",b="När du återvänder till Quae tackar hon dig för din insats. Quae medger att hon hoppades att Kinelory inte skulle vara alltför besvärlig: hon är mycket vänlig, men lika dödlig när du är hennes fiende."}},faq={{q="Vem skickar dig på den här eskortuppgiften?",a="Kinelory ber dig följa med när hon är redo att ge sig av.",al={"uppdragsgivare","vem ger uppdraget","vem startar hints of a new plague 4"}},{q="Vart behöver Kinelory ta sig?",a="Hon beger sig ner till en gård och tar sig sedan tillbaka till Quae.",al={"eskortväg","vart beger sig kinelory","kinelorys destination"}},{q="Vem rapporterar du till när du är klar?",a="Quae, när Kinelory har kommit tillbaka till henne.",al={"lämna in","vem slutför uppdraget","var lämnar man in"}},{q="Vad kom precis före den här delen av utredningen?",a="Den tredje delen av Hints of a New Plague?, som leder direkt in i den här delen.",al={"föregående uppdrag","förutsättning","vad kommer före"}},{q="Vad händer efter den trygga återkomsten?",a="Utredningen fortsätter med den femte delen av Hints of a New Plague?.",al={"nästa uppdrag","what comes next","fortsättning"}},{q="Varför måste Kinelory skyddas?",a="Alla som bryr sig om Hillsbrads folk uppmanas att se till att hon kommer fram tryggt.",al={"varför skydda kinelory","varför bry sig om kinelory"}}},fp="22,168,24.188.0,13.154.1,29.62.0,31.51.0,35.53.0,54.83.0,36.48.0,31.101.0"}
P.entries["quest:6608"] = {n="You Too Good.",s="Lumak skickar dig från Orgrimmar för att hitta sin vän Nat Pagle. Din skicklighet har vuxit ur vanliga lektioner, och Nat slår läger på en avlägsen liten ö söder om Theramore Isle.",h="Lumak skickar dig från Orgrimmar för att hitta sin vän Nat Pagle.",kw={"hantverksfiske","dustwallow marsh","lumak","nat pagle","orgrimmar","theramore","you too good"},ang={["faction:Horde"]="Även under fraktionskriget kan människor knyta band över dess gränser genom ett gemensamt hantverk eller fritidsintresse.",["race:Orc"]="Som orch kan du se Lumaks tålamod, goda humör och respekt för naturen i vänskapen han har knutit över fiendens gränser."},sec={{t="Lumaks gräns",b="Lumak tränar fiskare i Orgrimmars Valley of Honor. Han ser att du har lärt dig allt han kan lära dig om spö och rulle och erkänner att du är för skicklig för vanliga lektioner. För att lära dig hantverksfiske måste du söka kunskap bortom staden och Horden."},{t="En oväntad vänskap",b="Lumak skickar dig för att hitta sin mänskliga vän Nat Pagle. Han varnar dig för att inte skada eller äta Nat, trots motsättningarna mellan Horden och Alliansen över hela Kalimdor. Nat slår läger på en liten ö söder om Theramore Isle i Dustwallow Marsh. Han håller sig borta från politiken och bryr sig bara om fisken nappar."}},faq={{q="Vem skickar mig på det här uppdraget?",a="Lumak, fisketränaren i Orgrimmars Valley of Honor, skickar dig när din skicklighet har vuxit bortom expertnivån.",al={"vem startar you too good","lumak uppdragsgivare","var får man you too good"}},{q="Var finns Nat Pagle?",a="Nat Pagle slår läger på en liten ö utanför kusten vid Dustwallow Marsh, söder om Theramore Isle.",al={"var finns nat pagle","nat pagles plats","hitta nat pagle"}},{q="Varför har en orch en mänsklig vän?",a="Lumak och Nat Pagle blev vänner genom fisket och delar en passion som överbryggar den bittra rivaliteten mellan orcher och människor.",al={"lumak och nat pagles vänskap","varför är nat pagle vän med en orch"}},{q="Vad händer när jag talar med Nat Pagle?",a="Nat Pagle ger dig ett krävande prov: res genom Azeroth och fånga sällsynta fiskar innan han lär dig mer.",al={"vad lär nat pagle ut","uppdrag för hantverksfiske"}},{q="Är det säkert för Horde att passera genom Theramore?",a="Nej. Theramore är en fästningsstad som vaktas av Alliansen. För att nå Nats ö får du följa kusten eller ta en omväg runt staden för att undvika vakterna.",al={"kan horde passera genom theramore","ta sig till nat pagle som horde"}},{q="Varför kan Lumak inte träna mig mer?",a="Lumak har lärt dig allt han kan. Nat Pagle kan lära dig hantverksfiske, och fiskare över hela den kända världen ser honom som en legend.",al={"varför lumak slutar träna","från expert till hantverksfiske för horde"}}},fp="13,160,14.234.0,22.281.0,27.109.0,27.87.0,36.124.0,39.115.0,44.139.0,41.134.0"}
P.entries["quest:661"] = {n="Hints of a New Plague?",s="Kinelory är tillbaka från gården, oskadd, och Quae har fått föremålen hon hämtade. Quae och Kinelory tänker stanna i Arathi lite längre, så du får ta med ett meddelande till Phin Odelic i Southshore.",h="Kinelory är tillbaka från gården, oskadd, och Quae har fått föremålen hon hämtade.",kw={"arathi highlands","forsaken","hillsbrad","kinelory","phin odelic","pest","quae","southshore"},sec={{t="Meddelande till Southshore",b="Quae är nöjd med hur väl du tog hand om Kinelory, som kommit tillbaka i bättre skick än efter en natt på värdshuset. Föremålen från gården bör ge Phin Odelic en uppfattning om vad som pågår ute i Arathi. Eftersom gården blev attackerad tänker Quae och Kinelory stanna lite längre, ifall någon hämnas, och ber dig återvända till Southshore och tala med Phin."},{t="Phins svar",b="Phin är glad att höra att Kinelory och Quae är vid liv och mår bra. De är oersättliga vänner och reskamrater, säger Phin. Phin tackar dig med en gåva för hela gruppens räkning och hoppas att de med lite tur får reda på vad Forsaken planerar och kan sätta stopp för det."}},faq={{q="Vem skickar dig för att tala med Phin Odelic?",a="Quae ber dig bege dig till Southshore när Kinelory tryggt har återvänt från gården.",al={"vem ger ledtrådar om en ny pest 5","vem startar ledtrådar om en ny pest","quae uppdrag"}},{q="Varför återvänder inte Quae och Kinelory själva till Southshore?",a="Quae vill att de stannar lite längre i Arathi, för säkerhets skull, ifall någon hämnas på attacken mot gården.",al={"varför stannar quae i arathi","varför stanna kvar","quae stannar"}},{q="Var hittar du Phin Odelic?",a="I Southshore.",al={"phin odelics plats","var är phin","phin odelic southshore"}},{q="Varför ska du ta med nyheter till Phin Odelic?",a="Föremålen Kinelory hämtade från gården bör hjälpa Phin Odelic att förstå vad som pågår ute i Arathi.",al={"varför besöka phin","phin odelics syfte","vad vill phin"}}},fp="22,144,19.375.0,13.283.1,40.77.0,64.110.0,31.29.0,52.104.0"}
P.entries["quest:6610"] = {n="Clamlette Surprise",s="Dirge Quikcleave behöver ingredienser till sin clamlette, en ny kulinarisk skapelse. I utbyte erbjuder han sig att lära dig exotisk matlagning och laga ett par åt dig.",h="Dirge Quikcleave behöver ingredienser till sin clamlette, en ny kulinarisk skapelse.",kw={"alterac swiss","clamlette","clamlette surprise","dirge quikcleave","exotisk matlagning","jätteägg","smakrikt musselkött"},ang={["profession:Cooking"]="Som kock kan du lära dig exotisk matlagnings finare detaljer av Dirge Quikcleave."},sec={{t="Ett nytt recept",b="Dirge Quikcleave är redo att visa dig hur han lagar sin clamlette surprise. Innan han kan börja behöver han jätteägg, smakrikt musselkött och Alterac Swiss. Samla ingredienserna han ber om, så lär Dirge dig om exotisk matlagning medan han lagar rätten."}},faq={{q="Vad är en clamlette?",a="En clamlette är Dirge Quikcleaves senaste kulinariska skapelse, gjord på jätteägg, smakrikt musselkött och Alterac Swiss.",al={"clamlette surprise","vad är en clamlette"}},{q="Vem ber om ingredienserna?",a="Dirge Quikcleave vill ha ingredienserna till sin clamlette surprise.",al={"vem vill ha ingredienserna","dirges uppdrag"}},{q="Vilka ingredienser behöver Dirge?",a="Dirge behöver jätteägg, smakrikt musselkött och Alterac Swiss.",al={"clamletteingredienser","vad ska jag samla in"}},{q="Var hittar jag jätteäggen?",a="Jätteäggen kan komma från rocs som strövar omkring i Tanaris eller från andra stora fåglar.",al={"var finns jätteägg","var finns äggen"}},{q="Varifrån kommer det smakrika musselköttet?",a="Smakrikt musselkött finns i musslor.",al={"källa till musselkött","smakrikt musselkött"}},{q="Var kan jag få tag på Alterac Swiss?",a="Dirge säger att du ska hämta Alterac Swiss från ett ysteri.",al={"källa till alterac swiss","ost till dirge"}},{q="Vad erbjuder Dirge i utbyte?",a="Dirge erbjuder sig att lära dig finare detaljer inom exotisk matlagning och laga ett par clamelettes åt dig.",al={"vad får jag","dirge lär ut"}}},fp="18,154,12.259.0,20.117.0,34.66.0,33.59.0,32.73.0,41.38.0,30.48.0,32.105.0"}
P.entries["quest:6611"] = {n="To Gadgetzan You Go!",s="I Orgrimmar skickar Zamja hordekockar söderut för att lära sig av en excentrisk goblinköttmästare.",h="I Orgrimmar skickar Zamja hordekockar söderut för att lära sig av en excentrisk goblinköttmästare.",kw={"mästarmatlagning","matlagning","dirge quikcleave","gadgetzan","orgrimmar","tanaris","valley of strength","zamja"},ang={["faction:Horde"]="Orgrimmar förlitar sig på specialister utifrån, däribland neutrala goblinkockar, för att hjälpa stadens hantverkare att gå bortom vanliga stambaserade råvaror.",["profession:Cooking"]="Som kock når du en punkt där undervisningen i huvudstaden tar slut, och du måste ge dig ut i den farliga vildmarken för att studera hos en mästerkock."},sec={{t="En kock växer ur Orgrimmar",b="Zamja utbildar kockar i Drag, där hon förser krigare och resenärer på väg genom Durotar med mat. När en kock har lärt sig alla recept och tekniker hon kan lära ut, medger Zamja att hon har förmedlat allt sitt kulinariska kunnande. Hon skickar sin erfarna elev till Tanaris och säger att bara en mästare på märkliga och exotiska köttsorter kan hjälpa en begåvad kock att utvecklas vidare."},{t="Slaktaren i öknen",b="I Tanaris är Gadgetzan en ångdriven handelsplats som drivs av Steamwheedle Cartel. Dirge Quikcleave arbetar inne på stadens värdshus. Den excentriske goblinköttmästaren har en okonventionell smak och är inte det minsta kräsmagad. Över hela Kalimdor är han känd för att förvandla monstruösa ökenvarelser och ibland läderrester till rejäla måltider för härdade äventyrare."}},faq={{q="Vem skickar dig till Gadgetzan?",a="Zamja, trollernas matlagningsinstruktör nära kokeldarna i Drag i Orgrimmar, skickar iväg kockar som har bemästrat allt hon kan.",al={"uppdragsgivare","vem startar det här","zamjas uppdrag"}},{q="Varför skickar Zamja iväg dig?",a="Zamja har lärt ut alla recept och tekniker hon kan. Hon skickar lovande kockar till Dirge Quikcleave i Tanaris, en excentrisk expert som är känd för att laga mat av de kärvaste ökeningredienserna.",al={"varför gadgetzan","varför dirge quikcleave","matlagningsmästare"}},{q="Vem är Dirge Quikcleave?",a="Dirge Quikcleave är en goblinköttmästare och hantverksinstruktör i matlagning på värdshuset i Gadgetzan. Han har ett kärvt temperament, märkliga idéer om näring, som att hitta protein i gamla läderstövlar, och är mästare på avancerad matlagning med exotiska vildmarksingredienser.",al={"vem är dirge","dirge gadgetzan"}},{q="Måste man göra uppdraget för att lära sig mästarmatlagning?",a="Nej. Det här är en hänvisning som visar hordekockar vägen till Tanaris. En kock med tillräcklig skicklighet kan resa direkt till Gadgetzan och tala med Dirge Quikcleave utan Zamjas rekommendation.",al={"måste jag göra uppdraget","vägvisare för matlagning","är det obligatoriskt"}},{q="Var ligger Gadgetzan?",a="Gadgetzan är en muromgärdad handelsplats i öknen som drivs av Steamwheedle Cartel i norra Tanaris, långt söderut på Kalimdor och söder om Thousand Needles.",al={"gadgetzans plats","var finns dirge"}},{q="Lär sig Zamja verkligen något när du återvänder?",a="Zamja kräver skämtsamt att du kommer tillbaka och lär henne när du blivit den främsta kocken i trakten. Hon fortsätter som expertinstruktör i Orgrimmar och sköter sina kokeldar för nästa generation resenärer.",al={"lär sig zamja matlagning","lära zamja"}}},fp="20,95,25.295.0,25.364.0,27.117.0,29.181.0,24.239.0,48.146.0,27.138.0,51.194.0"}
P.entries["quest:662"] = {n="Deep Sea Salvage",s="Efter Land Ho! ber First Mate Nilzlix dig att hämta tillbaka sjökorten och loggböckerna från två sjunkna skepp innan någon lämnar viken.",h="Efter Land Ho!",kw={"arathi highlands","booty bay","deep sea salvage","harbinger","maiden's folly","nilzlix","o'breen","seahorn","spirit of silverpine"},sec={{t="Två skepp förliste vid revet",b="O'Breen ledde tre skepp in i viken, övertygad om att skatten låg här. Harbinger lade till säkert. Sedan, när Maiden's Folly och Spirit of Silverpine kom in, började tidvattnet sjunka. Båda skeppen gick på grund på en tempelliknande struktur i revet och sjönk snabbt."},{t="Vad Nilzlix vill ha tillbaka",b="Nilzlix vill att loggböckerna och sjökorten från båda vraken bärgas, eftersom informationen inte får lämnas kvar åt nyfikna ögon. Om den hamnade i fiendens händer skulle Fleet Master Seahorn, säger han, tvinga besättningen att gå plankan."}},faq={{q="Varför sjönk Maiden's Folly och Spirit of Silverpine?",a="När de två skeppen kom in började tidvattnet sjunka. Båda gick på grund på något som liknade ett tempel i revet och sjönk snabbt.",al={"varför förliste skeppen","hur sjönk skeppen","orsak till skeppsbrottet vid arathi cove"}},{q="Vem är First Mate Nilzlix?",a="Han är styrmannen som berättar om de tre skeppen O'Breen ledde in i viken, och han vill att loggböckerna och sjökorten från de två sjunkna skeppen bärgas.",al={"nilzlix","vem ger deep sea salvage"}},{q="Varför är sjökorten och loggböckerna så viktiga?",a="Nilzlix vill inte lämna informationen åt nyfikna ögon. Om fiender fick tag på den skulle Fleet Master Seahorn, säger han, tvinga besättningen att gå plankan.",al={"varför bärga loggböcker","varför sjökort och loggböcker"}},{q="Vilket skepp klarade sig?",a="Bara Harbinger. Det lade till säkert i viken, medan de andra två skeppen sjönk.",al={"vilket skepp överlevde","skeppet harbinger"}},{q="Vem är Fleet Master Seahorn?",a="Nilzlix säger att Seahorn skulle tvinga besättningen att gå plankan om deras dokument hamnade i fiendens händer.",al={"fleet master seahorns roll","vem är seahorn"}},{q="Vad kom före det här uppdraget?",a="Det följer efter Land Ho!",al={"förkunskapskrav för deep sea salvage","föregående uppdrag"}}},fp="16,121,26.247.0,23.206.0,57.158.0,26.142.0,41.157.0,28.71.0,28.117.0,27.26.0"}
P.entries["quest:6621"] = {n="King of the Foulweald",s="King of the Foulweald är ett militärt anfall från Horde, beordrat av Karang Amakkar vid Zoram'gar Outpost. För att kuva de korrumperade Foulweald-furbolgerna sydost om Astranaar planterar Hordes hjältar en krigsfana direkt på stammens heliga totemhög, provocerar fram dess hövding Chief Murgut och dödar honom.",h="King of the Foulweald är ett militärt anfall från Horde, beordrat av Karang Amakkar vid Zoram'gar Outpost.",kw={"ashenvale","foulweald","furbolg","greenpaw village","karang amakkar","murgut","totemhög","zoram'gar"},ang={["class:Shaman"]="Foulwealds förvrängda totem och aggression speglar den pågående andliga obalans som plågade Ashenvales ursprungsstammar efter Burning Legions invasion.",["faction:Horde"]="Karang Amakkar använder öppna uppvisningar av militär överlägsenhet för att kuva fientliga stammar i Ashenvale och säkra fri passage längs de centrala stigarna för Hordes försörjningskaravaner.",["race:Orc"]="Att plantera en fana för att provocera en fiendehövding till envig är klassisk orchisk krigföring, där styrka och avgörande konfrontation prioriteras framför långvariga skärmytslingar."},sec={{t="En styrkedemonstration",b="Medan nattalverna kämpar för att hålla Ashenvales korrumperade ursprungsstammar i schack närmar sig Horde hotet med beräknad aggression. Karang Amakkar vid Zoram'gar Outpost inser att Foulweald-stammen kanske inte kan mäta sig med den talrika nordliga Thistlefur-stammen, men att dess tygellösa våldsamhet utgör en lurande fara längs den södra vägen. I stället för att invänta bakhåll mot Hordes patruller beordrar Karang en förebyggande uppvisning av militär överlägsenhet för att kuva stammen."},{t="Skändning och utmaning",b="Anfallet riktas mot Greenpaw Village, som ligger nordost om Mystral Lake. Karang skapar en krigsfana avsedd att planteras mitt i Foulwealds totemhög – en oförlåtlig förolämpning mot stammens förfäders andar och stolthet. Furbolgförsvararna rusar desperat mot högen för att riva ner den kränkande fanan, vilket tvingar Chief Murgut att träda fram och försvara sin ära i öppen strid. När Horden tar Murguts personliga totem krossas deras ledarskap och Hordes överhöghet i området befästs."}},faq={{q="Vem beordrar att Chief Murgut ska dödas?",a="Karang Amakkar, en orch stationerad vid Zoram'gar Outpost på Ashenvales västkust, ger uppdraget efter att ha undersökt de närliggande Thistlefur-furbolgerna.",al={"uppdragsgivare king of the foulweald","vem ger king of the foulweald","karang amakkar uppdrag"}},{q="Var ligger Greenpaw Village?",a="Greenpaw Village ligger sydost om nattalvbosättningen Astranaar, nordost om Mystral Lake och strax söder om Ashenvales stora östra landsväg.",al={"var ligger greenpaw village","foulwealds plats","var plantera karangs fana"}},{q="Varför planterar Horde en fana på totemhögen?",a="Att plantera Karang's Banner direkt i stammens heliga totemhög är en avsiktlig provokation. Genom att skända deras heliga mark tvingas Foulweald att anfalla i raseri och Chief Murgut att strida öppet för att försvara sin ställning.",al={"varför plantera fana","syftet med fana på totemhög","varför utmana murgut"}},{q="Vilka är Foulweald-furbolgerna?",a="Foulweald är en av flera furbolgstammar i Ashenvale som har fallit i vansinne och korrumperats efter det tredje kriget. De är färre än Thistlefur, men förblir våldsamma och fientliga mot främlingar.",al={"vad är foulweald","foulweald-stammens historia","vem är chief murgut"}},{q="Vad uppnår man genom att hämta Murgut's Totem?",a="Att föra Chief Murguts totem tillbaka till Zoram'gar Outpost bevisar att hövdingen har besegrats. Utan sin ledare och med sin heliga hög skändad skräms de överlevande i Foulweald till att undvika ytterligare konflikt med Horde.",al={"syftet med murguts totem","vad händer efter murguts död"}},{q="Hur hänger det här uppdraget ihop med de tidigare undersökningarna av furbolgerna?",a="Uppdraget följer direkt efter 'Between a Rock and a Thistlefur.' Efter att ha tagit itu med den nordliga Thistlefur-stammen vänder Karang söderut för att krossa Foulweald i förebyggande syfte, innan de kan inleda samordnade räder.",al={"sambandet med between a rock and a thistlefur","förkunskapskrav för king of the foulweald"}}},fx={b1528232={q="Varför vill Karang Amakkar få Chief Murgut besegrad?",a="Karang Amakkar ser Foulweald-stammen som ett växande hot mot Hordens fäste i Ashenvale. De är färre än den närliggande Thistlefur-stammen, men deras blotta vildsinthet gör dem till ett oberäkneligt hot. Genom att utmana deras hövding direkt och döda honom vill Karang knäcka deras vilja och tydligt visa att Horde inte tolererar några hot i skogen.",al={"karang motiv","varför döda murgut","varför besegra foulweald"}},["9b8cfe09"]={q="Vem är Chief Murgut?",a="Chief Murgut är den vildsinte ledaren för Foulwealds furbolger och bor i Greenpaw Village, sydost om Astranaar. Han härskar över stammen från dess heliga totempåle och leder genom rå styrka och territoriell aggression. Karang skickar dig för att locka fram honom i öppen strid genom att vanhelga stammens marker med en Horde-krigsfana.",al={"vem är murgut","chief murgut foulweald","vem är foulwealds kung"}}},fp="21,189,15.274.0,25.382.0,37.162.0,34.126.0,53.171.0,31.190.0,47.216.0,64.182.0"}
P.entries["quest:6623"] = {n="Horde Trauma",s="I Hammerfall i Arathi Highlands kallar Horde Trauma skickliga fältskärer till frontlinjen. Doctor Gregory Victor, chefsläkare för Hordens traumavård, söker hjälp från dem som kan rädda liv under extrem press.",h="I Hammerfall i Arathi Highlands kallar Horde Trauma skickliga fältskärer till frontlinjen.",kw={"arathi highlands","doctor gregory victor","första hjälpen","hammerfall","horde trauma","arnok","triage"},ang={["class:Priest"]="Som präst kan du sluta sår med gudomlig magi, men sekulär akutsortering lär dig att avgöra vem som kan räddas när ditt mana tar slut.",["faction:Horde"]="Som medlem av Horden är du beroende av tåliga fältskirurger som håller fotsoldaterna stridsdugliga i brutala gränskonflikter som de i Arathi Highlands."},sec={{t="En kallelse från Hammerfall",b="I Valley of Spirits i Orgrimmar berättar förstahjälpstränaren Arnok för skickliga helare att de har fångat Doctor Gregory Victors uppmärksamhet. Victor leder Horde Trauma från Hammerfall, undangömt i de omstridda kullarna i Arathi Highlands. Arnok ser kallelsen som höjdpunkten i en fältskirurgs yrkeskarriär."},{t="Fälttriage i krigets hetta",b="I Hammerfall lämnar ständiga skärmytslingar med Stromgardes styrkor och lokala fientliga fraktioner Victor överhopad av sårade fotsoldater, plundrare och spejare. Chefsläkaren slösar ingen tid på artighetsfraser när han välkomnar rekryter. I stället beordrar han nykomlingarna att ta på sig operationskläderna och bevisa sitt värde i brutal, snabb akutsortering."}},faq={{q="Vad är Horde Trauma?",a="Horde Trauma är Hordens särskilda medicinska och kirurgiska avdelning vid frontlinjen. Doctor Gregory Victor leder den från Hammerfall, där medlemmarna är specialiserade på slagfältsmedicin, akutsortering och svåra stridsskador under kaotiska förhållanden.",al={"hordens traumavård","vad är horde trauma","vilka ingår i horde trauma"}},{q="Vem skickar mig på det här uppdraget?",a="Arnok, orkernas förstahjälpstränare i Valley of Spirits i Orgrimmar, utfärdar kallelsen. Han ser tjänstgöring under Doctor Gregory Victor som höjdpunkten i en fältmedics yrkeskarriär.",al={"uppdragsgivare horde trauma","vem startar horde trauma","krenk choplimb","arnok"}},{q="Var finns Doctor Gregory Victor?",a="Doctor Gregory Victor är stationerad i sjukstugan i Hammerfall i nordöstra Arathi Highlands.",al={"doctor gregory victor plats","var finns victor","läkare i hammerfall"}},{q="Vad händer när jag anmäler mig i Hammerfall?",a="När du anländer säger Doctor Victor genast åt dig att ta på dig operationskläderna inför uppföljningsuppdraget, Triage. Du sätts på prov under hård press när du prioriterar och behandlar sårade soldater vars tillstånd snabbt försämras, innan de dukar under för sina skador.",al={"vad händer efter horde trauma","nästa uppdrag efter horde trauma","uppdraget triage"}},{q="Varför är Hammerfall så desperat efter fältläkare?",a="Hammerfall är omgivet av fientligheter i Arathi och möter ändlösa strider med människostyrkor, syndikatets agenter och lokala bestar. Skadade strömmar ständigt in i lägret och pressar den lilla sjukvårdspersonalen till bristningsgränsen.",al={"varför behöver hammerfall läkare","sjukvårdsläget i hammerfall"}},{q="Kan Alliansens spelare ta det här uppdraget?",a="Nej. Horde Trauma är till för Hordens medlemmar. Alliansen har en motsvarande medicinsk bedömning som leds av Doctor Gustaf VanHowzen på Theramore Isle.",al={"kan alliansen göra horde trauma","alliansens version av horde trauma"}}},fx={ac636cdf={q="Varför skickar Arnok mig till Doctor Gregory Victor?",a="Doctor Gregory Victor, chefsläkaren för Horde Trauma vid Hammerfall, har personligen bett om dig. Arnok håller Doctor Victor i högsta aktning och ser en chans att lära av honom som en möjlighet man bara får en gång i livet — en möjlighet han säger sig själv vara beredd att göra vad som helst för. Av djup yrkesmässig respekt och entusiasm för din förmåga vill Arnok se till att du inte slösar bort en så sällsynt kallelse.",al={"varför vill krenk ha det här","krenk choplimbs motiv","varför skicka till victor","varför vill arnok det här","arnoks motiv"}},b6720468={q="Varför ber Doctor Victor särskilt om mig?",a="Doctor Gregory Victor söker efter Hordens skickligaste fältsjukvårdare för att ansluta sig till Horde Trauma i Arathi Highlands. Dina bevisade kunskaper i första hjälpen har fångat hans uppmärksamhet i Hammerfall, så han kallar dig personligen till utbildning i stället för att ta in oprövade rekryter eller vanliga soldater.",al={"varför jag horde trauma","varför behöver victor mig","varför vill doctor victor ha mig"}}},fp="12,171,25.318.0,37.292.0,21.204.0,32.190.0,39.111.0,43.233.0,48.221.0,42.145.0"}
P.entries["quest:6625"] = {n="Alliance Trauma",s="Alliance Trauma är en kallelse till erfarna fältmediciner att inställa sig på Theramore Isle i Dustwallow Marsh. Första hjälpen-instruktörer i alliansens huvudstäder skickar ut den till skickliga utövare, som får studera under Doctor Gustaf VanHowzen, överläkare för alliansens elitkår inom sjukvård.",h="Alliance Trauma är en kallelse till erfarna fältmediciner att inställa sig på Theramore Isle i Dustwallow...",kw={"alliance trauma","dustwallow marsh","första hjälpen","ironforge","nissa firestone","theramore","triage","vanhowzen"},ang={["faction:Alliance"]="Alliance Trauma ser till att frontkämpar i Kalimdor och Eastern Kingdoms har tillgång till skickliga fältmediciner som kan stabilisera kritiska skador under beskjutning.",["race:Dwarf"]="Instruktörer som Nissa Firestone i Ironforge spanar ivrigt efter lovande utövare från Great Forge, som kan representera alliansens främsta sjukvårdstalanger i Theramore."},sec={{t="En kallelse till fältet",b="När en fältmedicinare väl behärskar grundteknikerna som lärs ut i alliansens stora städer har de lokala instruktörerna inte mycket mer att lära ut. De som visar enastående fallenhet för nål, tyg och triage rekommenderas direkt till Doctor Gustaf VanHowzen. VanHowzen verkar från gränsfästet Theramore Isle och leder Alliance Trauma, organisationen som har i uppdrag att rädda liv i Kalimdors och omgivningens brutalaste krigszoner."},{t="Vägen till Theramore",b="Instruktörer som Nissa Firestone i Ironforge betraktar en personlig kallelse från VanHowzen som ett enastående privilegium. Theramore Isle utsätts ständigt för regionala hot, skärmytslingar och hårda förhållanden i vildmarken, vilket leder till en jämn ström av svårt sårade soldater. För att nå VanHowzens klinik krävs en lång resa över havet till Dustwallow Marsh, där endast de mest samlade fältkirurgerna kan hoppas klara hans stränga triagekrav."}},faq={{q="Vad är Alliance Trauma?",a="Alliance Trauma är den medicinska elitgren som ansvarar för avancerad slagfältsmedicin och akut triage i hela alliansen. Kåren leds av överläkaren Gustaf VanHowzen och tar hand om kritiska sår som vanliga fältförband inte kan behandla.",al={"alliance trauma i berättelsen","vilka ingår i alliance trauma"}},{q="Vem skickar dig på det här uppdraget?",a="Alliansens instruktörer i första hjälpen, som Nissa Firestone i Great Forge i Ironforge, skickar lovande utövare vidare när de nått toppen av den vanliga utbildningen i städerna.",al={"vem ger alliance trauma","uppdragsgivare för första hjälpen i ironforge"}},{q="Vart måste du resa?",a="Du måste resa till den mänskliga hamnfästningen Theramore Isle, som ligger vid Dustwallow Marshs östkust på kontinenten Kalimdor.",al={"var finns vanhowzen","alliance traumas destination"}},{q="Vem är Doctor Gustaf VanHowzen?",a="Doctor Gustaf VanHowzen är överläkare för Alliance Trauma. Han är stationerad vid militärkliniken i Theramore och räknas som en av alliansens främsta auktoriteter inom akutmedicin och kirurgisk triage.",al={"gustaf vanhowzen","överläkare vanhowzen"}},{q="Vad händer när du inställer dig hos Doctor VanHowzen?",a="När du inställer dig i Theramore låter VanHowzen kandidaterna genomgå en intensiv praktisk triageprövning. Han testar deras förmåga att rädda vågor av döende soldater innan han antar dem till de högre leden inom fältmedicinen.",al={"vad händer efter alliance trauma","nästa triageuppdrag"}},{q="Varför ligger kliniken i Theramore i stället för i Stormwind eller Ironforge?",a="Theramore är en aktiv gränsgarnison omgiven av fientliga träskmarker, farliga bestar och territoriella skärmytslingar. Den ständiga strömmen av kritiskt sårade soldater gör platsen idealisk för intensiv traumautbildning.",al={"varför ligger kliniken i theramore","varför dustwallow för traumavård"}}},fx={a452e047={q="Varför skickar Nissa Firestone dig till Theramore?",a="Doctor Gustaf VanHowzen, chefsläkaren för Alliance Trauma, har personligen bett att du ska ansluta dig till hans styrkor i Theramore. Nissa Firestone håller den berömda kirurgen i högsta aktning och ser arbete under honom som en enastående ära. Hon framför kallelsen eftersom hon vill se till att du inte slösar bort en så sällsynt medicinsk möjlighet.",al={"varför vill nissa få det här gjort","nissa firestones motiv","varför skicka till theramore"}},a6ba6381={q="Varför ber Doctor VanHowzen särskilt om dig?",a="Doctor Gustaf VanHowzen behöver skickliga och erfarna fältsjukvårdare som kan hantera svårt skadade under press. Du har visat prov på enastående kunskaper i första hjälpen och fångat uppmärksamheten hos Alliansens främsta kirurgkår. Därför kallar VanHowzen dig personligen till Theramore för att pröva dina färdigheter under stridsförhållanden.",al={"varför jag alliance trauma","varför vill vanhowzen ha mig","varför skicka spelaren till theramore"}}},fp="15,183,19.199.0,21.353.0,24.216.0,28.169.0,28.100.0,31.206.0,49.183.0,71.231.0"}
P.entries["quest:6626"] = {n="A Host of Evil",s="Myriam Moonsinger ber dig att konfrontera Razorfen Downs försvarare och kultister. Deras närvaro är problemet hon skickar dig för att ta itu med.",h="Myriam Moonsinger ber dig att konfrontera Razorfen Downs försvarare och kultister.",kw={"a host of evil","death's head cultists","myriam moonsinger","razorfen battleguard","razorfen downs","razorfen thornweavers"},sec={{t="Myriams begäran",b="Nära ingången till Razorfen Downs ber Myriam Moonsinger dig att möta Razorfen Battleguard, Razorfen Thornweavers och Death's Head Cultists där inne. Hon förväntar sig att du återvänder till henne när du har tagit hand om dem."}},faq={{q="Vem ber om hjälp vid Razorfen Downs?",a="Myriam Moonsinger, nära ingången till Razorfen Downs, ber dig att konfrontera dess försvarare och kultister.",al={"vem är myriam","myriam moonsinger"}},{q="Vilka fiender nämner Myriam?",a="Myriam nämner Razorfen Battleguard, Razorfen Thornweavers och Death's Head Cultists.",al={"vilka ska bekämpas","fiender i razorfen"}},{q="Var återvänder jag till Myriam?",a="Återvänd till Myriam Moonsinger nära ingången till Razorfen Downs.",al={"var är myriam","myriams plats"}}},fp="14,136,18.212.0,36.104.0,31.84.0,28.64.0"}
P.entries["quest:6627"] = {n="Test of Lore",s="Test of Lore är ett intellektuellt prov i historisk kunskap, instiftat av eremiten Braug Dimspirit i Stonetalon Mountains. Efter att ha hämtat den uråldriga boken Legacy of the Aspects måste resenärer visa att de förstår forntidens historia genom att besvara Braugs fråga. Den som inte tar texten på allvar förvisas plötsligt till en annan plats i Kalimdor.",h="Test of Lore är ett intellektuellt prov i historisk kunskap, instiftat av eremiten Braug Dimspirit i...",kw={"aspekter","braug dimspirit","jordväktaren","neltharion","stonetalon","taurajo","test of faith","the weathered nook"},ang={["class:Mage"]="Magiker kommer att tycka att Braugs teleporteringsskydd är imponerande och straffande. Det visar hur eremiterna i Stonetalon använder uråldrig magi för att tukta vårdslösa lärda.",["faction:Horde"]="Hordens prövningar i Kalimdor kräver mer än råstyrka. Både krigare och shamaner förväntas förstå de uråldriga sår och drakmakter som formade kontinenten.",["race:Tauren"]="Prövningen speglar taurenfolkets respekt för förfädernas visdom och forntidens historia. Den ser till att unga hjältar inte ger sig av utan att förstå världens balans."},sec={{t="Ett visdomsprov",b="Test of Lore ingår i en större serie prövningar som började med Dorn Plainstalker vid Weathered Nook. Provet flyttar fokus från strid och blind tillit till förståelse för världens forntid. Braug Dimspirit bor bland klipporna i Stonetalon Mountains och kräver att de prövade hämtar uråldriga texter och verkligen tar till sig kunskapen på sidorna."},{t="Legacy of the Aspects",b="Lärdomen handlar om drakernas aspekters tillkomst och uppdelning, särskilt den ödesdigra pakt som slöts långt före den Stora Klyvningen. Braug prövar om den prövade minns Jordväktaren Neltharion, vars fall i galenskap och förräderi förändrade Azeroths yta. Den som inte respekterar historien får inte fortsätta på visdomens väg."},{t="Priset för gissningar",b="Braug tolererar inga lösa gissningar. Den som svarar fel förvisas genast med magi och hamnar flera mil bort, vid Camp Taurajo i södra Barrens. För att återfå sin ställning måste man vandra hela vägen tillbaka upp i Stonetalon och möta eremitens granskning en andra gång."}},faq={{q="Vad är svaret på Braug Dimspirits fråga?",a="Braug frågar vem Jordväktaren är i boken Legacy of the Aspects. Det rätta svaret är Neltharion, den svarta aspekten som senare skulle vända sig mot sina drakfränder.",al={"svar på braugs fråga","svar på test of lore","fråga om legacy of the aspects"}},{q="Vad händer om du svarar fel?",a="Om du ger Braug fel namn förvisas du genast med magi och teleporteras direkt till Camp Taurajo i The Barrens. Du måste resa hela vägen tillbaka till hans utsiktsplats i Stonetalon Mountains för att försöka klara provet igen.",al={"fel svar på test of lore","misslyckades med test of lore","teleporterad till taurajo"}},{q="Vem är Braug Dimspirit?",a="Braug Dimspirit är en ålderstigen eremit i Stonetalon Mountains som prövar Hordens kunskaper om historia och sägner. Han fortsätter serien av andliga prövningar som inleddes i Thousand Needles.",al={"braug dimspirit","vem håller i test of lore"}},{q="Hur hänger detta ihop med prövningarna i Thousand Needles?",a="Prövningen började med Test of Faith, som Dorn Plainstalker höll vid Weathered Nook i Thousand Needles. Dorn prövar fysisk och andlig tillit och skickar sedan värdiga deltagare genom Kalimdor för att få sitt intellekt, sin beslutsamhet och sin styrka prövade av andra visa äldste.",al={"koppling till dorn plainstalker","test of faith-uppdragskedjan"}},{q="Vilken bok frågar Braug ut dig om?",a="Förhöret prövar hur väl du förstått Legacy of the Aspects, en uråldrig skrift om titanernas välsignelse av de fem stora drakaspekterna, som skulle beskydda Azeroth.",al={"vilken bok braug frågar om","legacy of the aspects"}},{q="Vart leder den här uppdragskedjan sedan?",a="Klarar du Braugs förhör om drakaspekterna väntar fler prövningar där du får undersöka forntidens historia. Du måste söka igenom avlägsna trakter efter fler förlorade skrifter och förfäders kunskap.",al={"vad händer efter test of lore","nästa uppdrag i test of lore"}}},fx={a70a9b29={q="Varför prövar Braug Dimspirit dig?",a="Braug Dimspirit är examinator i de prövningar som började i Thousand Needles. Medan andra prövningar sätter din kampförmåga eller tro på prov, ska Test of Lore se till att du inte enbart förlitar dig på råstyrka. Genom att låta dig hämta gamla skrifter och förstå deras innehåll vill Braug främja visdom och historisk förståelse hos dem som vill företräda Horde.",al={"varför prövar braug dig","braug dimspirits syfte","varför test of lore"}}},fp="12,217,17.284.0,21.322.0,22.247.1,49.147.0,39.164.0,23.185.0,56.247.0,38.150.0,38.176.0"}
P.entries["quest:6628"] = {n="Test of Lore",s="Det här provet är en intellektuell prövning i en större serie andliga test med ursprung i Thousand Needles. Efter att ha letat igenom världen efter historiska texter infinner sig initiater hos Parqual Fintallas i Undercity för att bevisa att de förstår Azeroths mörkare historia.",h="Det här provet är en intellektuell prövning i en större serie andliga test med ursprung i Thousand Needles.",kw={"dorn plainstalker","lich king","mark of shame","nerzhul","parqual fintallas","test of lore","thousand needles","undercity","the weathered nook"},ang={["faction:Horde"]="Prövningen stärker banden mellan Kalimdors stammar och kungariket under Lordaeron och påminner hjältar om att visdom är lika viktig för Hordes överlevnad som rå styrka.",["race:Tauren"]="Det här provet, som bygger på äldre traditioner, får taurenresenärer att lära sig den dystra historien om sina Forsaken-allierade i norr och världen bortom Kalimdor.",["race:Undead"]="Ämnet går rakt in i kärnan av Forsakens identitet: tragedin kring Ner'zhuls skapelse och ursprunget till förbannelsen som band dem innan Sylvanas bröt Lich Kings grepp."},sec={{t="Ett kunskapsprov",b="Medan många prövningar inom Horde testar stridsförmåga eller rå uthållighet kräver Test of Lore akademiskt engagemang. Resan har sitt ursprung i Dorn Plainstalkers andliga disciplin vid The Weathered Nook och för kandidater långt från Thousand Needles vindskulpterade raviner till Undercitys skuggiga salar. Parqual Fintallas är examinator och ställer höga krav på historiska kunskaper."},{t="Scourges ursprung",b="För att tillfredsställa Parqual måste en initiat studera \"Beginnings of the Undead Threat\", en text som beskriver Scourges förbannade ursprung i Lordaeron. Kärnan i hans förhör gäller ursprunget till varelsen som härskar på Frozen Throne: den tidigare äldre schamanen Ner'zhul, vars essens smiddes av Burning Legion till Lich King. Kunskap om denna dystra härkomst anses nödvändig för att förstå Forsakens existens och farorna som hotar både Kalimdor och Eastern Kingdoms."}},faq={{q="Vad är svaret på Parquals fråga?",a="Parqual Fintallas frågar efter Lich Kings ursprungliga namn. Det rätta svaret är Ner'zhul, den forntida orkschaman vars ande bands till Frozen Throne.",al={"lich king svar","parquals fråga","test of lore svar"}},{q="Vad händer om du svarar fel på frågan?",a="Om du svarar fel drabbas du av debuffen Mark of Shame och måste vänta ut straffet innan Parqual låter dig göra ett nytt försök på provet.",al={"mark of shame","fel svar test of lore"}},{q="Var börjar den här uppdragskedjan?",a="Den övergripande prövningen börjar hos Dorn Plainstalker vid The Weathered Nook, som ligger bland de höga spirorna i Thousand Needles.",al={"var börjar test of lore","dorn plainstalker uppdragskedja"}},{q="Var finns Parqual Fintallas?",a="Parqual Fintallas håller till i Undercity, bland Forsakens underjordiska bibliotek och korridorer, där han förhör blivande elever.",al={"hitta parqual","parqual fintallas plats"}},{q="Vilken text bygger prövningen på?",a="Provet bygger på boken \"Beginnings of the Undead Threat\", som beskriver Plague of Undeaths ursprung och skapandet av Lich King.",al={"vilken bok till test of lore","beginnings-boken"}},{q="Varför skickar ett uppdrag i Thousand Needles folk till Undercity?",a="Prövningarna som tauren upprättat är utformade för att utmana varje sida av en äventyrare. För att testa sina kunskaper skickas kandidater över havet för att söka efter lärda skrifter som bevarats i Ruins of Lordaeron.",al={"varför till undercity","thousand needles undercity"}}},fx={b37475e3={q="Varför vill Parqual Fintallas att det här ska göras?",a="Parqual Fintallas sätter ditt engagemang för kunskapssökandet på sitt yttersta prov. Han anser att kunskap är avgörande för att överleva i den här farliga världen — ju mer du lär dig och iakttar, desto mer av sanningen kommer du att se. Han har gett dig i uppdrag att skaffa en bok om hotet från de odöda och kräver bevis på att du verkligen har studerat och tagit till dig dess dystra historia, i stället för att bara springa ett ärende.",al={"parquals motiv","varför prövar parqual mig","varför test of lore"}}},fp="12,200,20.332.0,21.381.1,41.135.0,46.131.0,34.131.0,35.136.0,33.135.0,60.163.0"}
P.entries["quest:6629"] = {n="Kill Grundig Darkcloud",s="Kill Grundig Darkcloud är ett Horde-uppdrag som Makaba Flathoof ger längs den sydöstra stigen i Stonetalon Mountains. När du har rensat ut Grimtotem-bråkmakarna och legosoldaterna skickar Makaba dig för att fälla ledaren som plundrade hans hem: Grundig Darkcloud. Genom att döda Grundig och hans följe av råskinn skipar du rättvisa åt den ödelagda bosättningen.",h="Kill Grundig Darkcloud är ett Horde-uppdrag som Makaba Flathoof ger längs den sydöstra stigen i Stonetalon...",kw={"råskinn","darkcloud","flathoof","grimtotem","grundig","makaba","post","stonetalon"},ang={["faction:Horde"]="Stonetalon är viktig mark för Hordes expansion in i Kalimdor, och aggressiva Grimtotem-krigsherrar som Grundig hotar försörjningsvägarna mellan The Barrens och Sun Rock Retreat.",["race:Tauren"]="Grimtotem-klanen fortsätter att så splittring bland taurenfolket. Genom Grundigs massaker visar de att deras skoningslösa extremism alltid kommer att stå emot enighet under Horde."},sec={{t="Stigens slaktare",b="Makaba Flathoof överlevde den plötsliga, våldsamma attacken mot bosättningen längs Stonetalon-stigen, men sorgen är fortfarande färsk. Efter att ha prövat din förmåga mot Grimtotems fotsoldater pekar han ut hjärnan bakom blodbadet: Grundig Darkcloud. Grundig är ingen simpel plundrare. Han leder ett troget följe av råskinn och stod i spetsen för massakern som jämnade byn med marken."},{t="Slå till mot Grimtotem Post",b="Grundig har sitt läger vid Grimtotem Post, längre uppför bergsvägen åt väster. För att hämnas Makabas släkt och skydda passet mot mer våld måste resande ta sig upp till fästet, kämpa sig igenom Darkclouds närmaste krets av råskinn och döda Grundig innan hans rövarskara kan ge sig på andra utsatta läger."}},faq={{q="Vem är Grundig Darkcloud?",a="Grundig Darkcloud är en våldsam Grimtotem-befälhavare med bas vid Grimtotem Post i sydöstra Stonetalon Mountains. Han planerade och ledde personligen den brutala attack som förstörde Makaba Flathoofs by.",al={"grundig darkcloud","vem är grundig","grimtotem-ledare"}},{q="Var hittar man Grundig Darkcloud?",a="Grundig Darkcloud finns vid Grimtotem Post, högt uppe längs bergsstigen väster om Makaba Flathoofs läger, nära gränsen till The Barrens.",al={"grundigs plats","var finns grundig","grimtotem post plats"}},{q="Varför ger Makaba Flathoof dig uppdraget?",a="Makaba såg Grimtotem slakta hans familj och klanfränder. Efter att redan ha fått sin första hämnd på deras bråkmakare och legosoldater ber han dig ta ledarens huvud, Grundig Darkclouds, så att han kan få verklig upprättelse och vedergällning.",al={"varför döda grundig","makabas berättelse","makabas hämnd"}},{q="Varför angriper Grimtotem fredliga bosättningar här?",a="Grimtotem-klanen hyser starkt förakt för de andra tauren-stammarna, särskilt dem som har allierat sig med Horde eller valt en fredligare väg. De använder regelbundet bakhåll, räder och rent våld för att driva bort konkurrerande klaner från markerna de vill härska över.",al={"varför grimtotem angriper","grimtotems fientlighet"}},{q="Vad händer efter att Grundig Darkcloud dödats?",a="Att döda Grundig Darkcloud och hans råskinn avslutar Makaba Flathoofs korta hämndkedja. När slaktaren är död kan Makaba äntligen sörja sin by i vetskap om att rättvisa har skipats.",al={"vad händer efter grundig","fortsättning på flathoof-kedjan"}},{q="Vilket uppdrag måste göras först?",a="Du måste först slutföra ”Avenge My Village”, där Makaba Flathoof prövar din beslutsamhet genom att låta dig döda Grimtotem-bråkmakarna och legosoldaterna som slagit läger strax västerut.",al={"förkrav för kill grundig","uppdrag före grundig"}}},fx={ce2e4f2e={q="Varför behöver Makaba Flathoof din hjälp i stället för att själv slåss mot Grundig?",a="Makaba Flathoof är en ensam överlevare som blivit strandsatt på bergsvägen och är förkrossad över slakten i sin by. Grundig Darkcloud befaller Grimtotem Post, omgiven av ett livgarde av vilda råskinn. Försvaret är alldeles för starkt för en ensam, sårad tauren att angripa. Makaba har sett dig fälla de vanliga plundrarna och sätter allt sitt hopp om hämnd till din stridsförmåga.",al={"varför jag makaba","varför slåss inte makaba flathoof mot grundig","varför skicka mig att döda grundig darkcloud"}}},fp="22,189,23.315.0,24.279.0,25.156.0,37.117.0,47.190.0,58.198.0,43.147.0,45.159.0"}
P.entries["quest:663"] = {n="Land Ho!",s="Vid Faldir's Cove hälsar utkiken Lolo dig välkommen med beskedet att Captain O'Breens uppehåll här blir mycket längre än planerat. Två skepp i flottan, Spirit of Silverpine och Maiden's Folly, har gått förlorade, och Lolo föreslår att du talar med kaptenen.",h="Vid Faldir's Cove hälsar utkiken Lolo dig välkommen med beskedet att Captain O'Breens uppehåll här blir...",kw={"booty bay","faldir's cove","harbinger","utkiken lolo","maiden's folly","seahorn","shakes o'breen","spirit of silverpine"},sec={{t="Lolos välkomnande",b="Lolo, alltid på utkik, får syn på dig när du anländer till Faldir's Cove. Captain O'Breen hade lovat besättningen bara några timmar här, tillräckligt med tid för att samla skatten och återvända till Booty Bay. Lolo tvivlar på att det går så snabbt. Två skepp i flottan, Spirit of Silverpine och Maiden's Folly, ligger nu på havets botten. Den som tänker stanna får veta att den ska tala med kaptenen."},{t="Kaptenens berättelse",b="Captain O'Breen kallar hela affären en fruktansvärd röra och fruktar att Seahorn tar skeppet om ryktet sprids. En av Professor's uppfinningar pekade ut den förlorade skatten nära viken, så Harbinger lade till och de två andra skeppen fick signalen att följa efter. Sedan mullrade havet, vattnet drog sig tillbaka och båda skeppen kraschade in i revet. Det är inte bara ett rev, säger kaptenen, och något finns där nere. Den som hjälper besättningen utlovas en rejäl betalning."}},faq={{q="Vad hände med de andra skeppen?",a="Två skepp i flottan, Spirit of Silverpine och Maiden's Folly, gick förlorade och ligger på havets botten.",al={"var är de andra skeppen","sjunkna skepp faldir","vad sänkte skeppen"}},{q="Varför kom besättningen till Faldir's Cove?",a="Captain O'Breen kom för att samla skatter vid viken och räknade med att stanna bara några timmar innan han återvände till Booty Bay.",al={"varför är de här","expeditionens syfte","vad förde dem till arathi"}},{q="Vem ska du tala med vid Faldir's Cove?",a="Utkiken Lolo föreslår att du talar med Captain O'Breen vid Faldir's Cove om du tänker stanna kvar.",al={"vem är captain o'breen","var är shakes o'breen"}}},fp="8,195,14.382.0,21.442.1,33.87.0,39.142.0,40.94.0"}
P.entries["quest:664"] = {n="Drowned Sorrows",s="Captain Steelgut sitter sörjande vid Faldir's Cove efter att ha förlorat älskade Maiden's Folly. Steelgut ber dig ge dig efter Daggerspine-nagorna som slaktade de överlevande från vraket.",h="Captain Steelgut sitter sörjande vid Faldir's Cove efter att ha förlorat älskade Maiden's Folly.",kw={"arathi","daggerspine","faldir's cove","maidens folly","nagor","o'breen","rövare","trollkvinna","steelgut"},sec={{t="En kapten vid elden",b="Captain Steelgut sitter vid elden vid Faldir's Cove och önskar sig i stället en vattengrav. Besättningen kämpade hårt för att rädda vackra Maiden's Folly, men havet sänkte henne när vattnet plötsligt forsade in. O'Breen nådde stranden i säkerhet, men nagorna dödade de överlevande. Steelgut vill se Daggerspine-rövare och trollkvinnor döda."}},faq={{q="Vem är Captain Steelgut?",a="Kaptenen på Maiden's Folly, som nu sitter vid en eld vid Faldir's Cove efter att skeppet gått förlorat.",al={"captain steelgut","steelgut","vem är uppdragsgivaren"}},{q="Vad hände med Maiden's Folly?",a="Steelgut säger att havet sänkte skeppet: ena sekunden flöt det, och nästa forsade vattnet in, trots att besättningen kämpade hårt för att rädda det.",al={"maidens folly","vad hände med skeppet","varför förliste steelgut"}},{q="Varför vill Captain Steelgut att nagorna dödas?",a="Nagorna dödade de överlevande från vraket. Steelgut kallar dem avskum och vill se dem döda.",al={"varför döda nagor","steelguts hämnd","daggerspines anledning"}},{q="Vilka nagor vill Steelgut se döda?",a="Tio Daggerspine-rövare och tre Daggerspine-trollkvinnor.",al={"vilka nagor ska dödas","målnagor","daggerspine-mål"}}},fp="15,134,21.341.0,24.106.0,36.142.0,47.68.0,35.76.0"}
P.entries["quest:6641"] = {n="Vorsha the Lasher",s="Vorsha the Lasher är en våldsam hydra som terroriserar Horde:s fäste vid Zoram'gar Outpost längs Ashenvales kust. De lokala naga vördar varelsens grymhet och håller en offereld brinnande på en ö utanför kusten för att hedra henne. När Horde-mästarna släcker den heliga lågan lockar de fram Vorsha ur havet och sätter stopp för hennes rovattacker.",h="Vorsha the Lasher är en våldsam hydra som terroriserar Horde:s fäste vid Zoram'gar Outpost längs Ashenvales...",kw={"ashenvale","offereld","hydra","muglash","naga","vorsha","the zoram strand","zoram'gar"},ang={["faction:Horde"]="Försvaret av Zoram'gar Outpost är avgörande för att hålla en nordlig försörjningsbas i Ashenvale, där försörjningslinjerna ständigt utsätts för angrepp.",["race:Orc"]="Orcher som Muglash vägrar att huka bakom provisoriska palissader. De rusar i stället ut i bränningarna för att jaga rovdjur ansikte mot ansikte."},sec={{t="Ett hot från djupet",b="Zoram'gar Outpost ligger på en utsatt kustremsa i nordvästra Ashenvale och belägras ständigt av fientliga vilddjur, night elves och ormlika inkräktare. Ett av de mest förödande hoten som stryker längs The Zoram Strand är Vorsha the Lasher, en väldig hydra som är känd för sina brutala, oprovocerade angrepp mot utposten. Besten stiger upp ur bränningarna, krossar försvarsverken och slaktar krigare innan den försvinner tillbaka ner i djupet."},{t="Nagas offereld",b="De närliggande naga tolererar inte bara den glupska hydran, utan vördar aktivt hennes rovgiriga ondska. På ett klipputsprång utanför stranden håller de ormlika varelserna en offereld brinnande oavbrutet till Vorshas ära. Muglash, en orc som vill få slut på de ständiga angreppen mot utposten, insåg att en skändning av ritualens låga skulle få besten att rasa upp till ytan. Då kunde försvararna locka henne i ett bakhåll i stället för att invänta ännu en överraskande massaker."}},faq={{q="Vem är Vorsha the Lasher?",a="Vorsha the Lasher är en våldsam, enorm hydra som hemsöker vattnen utanför The Zoram Strand. Hon gör ofta oprovocerade räder mot Zoram'gar Outpost, där hon förstör lägrets försvar och slaktar Horde:s trupper.",al={"vorsha","vad är vorsha","vorsha hydra"}},{q="Varför hedrar naga Vorsha?",a="Naga vid The Zoram Strand respekterar Vorsha för hennes obevekliga grymhet och destruktiva aptit. De håller en eld brinnande på en ö utanför kusten till hennes ära och betraktar besten som en sinnebild för kustens vilda raseri.",al={"varför gillar naga hydror","vorshas offereld hos naga","varför dyrka vorsha"}},{q="Hur lockas Vorsha fram för strid?",a="Muglash leder ett anfall mot ön där naga sköter Vorshas offereld. När den heliga lågan släcks blir både nagaväktarna och hydran rasande, och Vorsha tvingas upp ur havet för att hämnas.",al={"hur tillkallar man vorsha","hur lockar man fram vorsha","vorshas ö med offerelden"}},{q="Vem är Muglash?",a="Muglash är en orc stationerad vid Zoram'gar Outpost. Trött på att leva i skräck för Vorshas oprovocerade härjningar längs kusten lägger han upp en plan för att släcka nagas offereld och kämpa mot besten tillsammans med pålitliga allierade.",al={"vem är muglash","muglash orc","zoram'gar muglash"}},{q="Varför är Zoram'gar Outpost utsatt för kustens bestar?",a="Zoram'gar Outpost är ett isolerat och oskyddat gränsläger direkt på Ashenvales stränder. Naga dominerar ruinerna ute i havet och vilda hydror patrullerar bränningarna, så närheten till vattnet gör lägret sårbart för attacker från havet åt alla håll.",al={"varför attackeras zoram'gar","faran vid the zoram strand"}},{q="Vad händer när Vorsha har dräpts?",a="När hydran har dräpts rapporteras segern till Warsong Runners, som håller linjerna vid Zoram'gar Outpost. Det lättar den ständiga bördan för gränsvakterna och säkrar den närmaste kusten mot plötsliga angrepp.",al={"lämna in vorsha-uppdrag","till vem rapportera om vorsha"}}},fx={["4cca3bd5"]={q="Varför vill Muglash att Vorsha ska dödas?",a="Vorsha är en ständig skräck för Zoram'gar Outpost. Den våldsamma hydran väller gång på gång upp ur havet utan provokation och ödelägger Hordens styrkor och allt annat som kommer i hennes väg längs kusten. Muglash vill sätta stopp för de förödande räderna en gång för alla genom att möta besten vid dess heliga åkallningsplats.",al={"muglashs motiv","varför döda vorsha","varför slåss mot vorsha"}},["23eb1be6"]={q="Varför behöver Muglash din hjälp mot Vorsha?",a="För att döda Vorsha måste du resa till en ö som hålls av kustens naga och släcka den heliga fyrfat de håller brinnande till hennes ära. Muglash tänker slåss vid din sida, men vet att ritualen kommer att locka dit både den väldiga hydran och vågor av ursinniga naga-försvarare. En enda krigare kan inte stå emot så många ensam.",al={"varför behöver muglash hjälp","varför inte hordens vakter mot vorsha","varför jag muglash"}}},fp="17,243,22.435.0,23.448.0,25.200.0,29.163.0,33.193.0,15.192.0,54.209.0,35.213.1"}
P.entries["quest:665"] = {n="Sunken Treasure",s="Nu när de är fullvärdiga Blackwater Raiders ska Professor Phizzlethorpe och Doctor Draxlegauge hjälpa Mr. O'Breen att hitta den försvunna alvskatten. För att söka efter ädelstenarna i det mörka havet behöver professorn ditt beskydd medan han laddar ett par glasögon vid en förtrollad sten i en grotta.",h="Nu när de är fullvärdiga Blackwater Raiders ska Professor Phizzlethorpe och Doctor Draxlegauge hjälpa Mr.",kw={"arathi highlands","blackwater raiders","draxlegauge","förtrollad sten","glasögon","o'breen","phizzlethorpe","sjunkna skatter"},sec={{t="Ladda glasögonen",b="Ädelstenarna är nästan omöjliga att hitta i det mörka havet utan hjälp, så Doctor Draxlegauge har byggt glasögon för sökandet. De måste laddas med kraft från den förtrollade stenen i en grotta en bit uppför sluttningen. Men grottan är förbannad: de som närmar sig blir överfallna. Professor Phizzlethorpe ber dig försvara honom medan han leder stenens energi in i glasögonen."}},faq={{q="Vem ber om hjälp?",a="Professor Phizzlethorpe ber dig försvara honom när han tar sig till grottan och tillbaka och laddar doktorns glasögon vid den förtrollade stenen.",al={"vem ger uppdraget","phizzlethorpe","uppdragsgivare"}},{q="Varför måste glasögonen laddas?",a="Doctor Draxlegauge byggde dem för att hjälpa till att hitta de försvunna ädelstenarna i det mörka havet. För att fungera måste de först laddas med stenens kraft.",al={"varför ladda glasögon","glasögonens syfte","vad är glasögonen till för"}},{q="Varför behöver professorn eskort?",a="Grottan är förbannad, och de blir överfallna när de närmar sig. Han behöver att du försvarar honom medan han leder stenens energi.",al={"varför skydda phizzlethorpe","vad finns i grottan"}},{q="Vem arbetar professorn och doktorn för?",a="Professorn säger att de nu är fullvärdiga Blackwater Raiders, så det är deras uppgift att hjälpa Mr. O'Breen hitta den försvunna alvskatten.",al={"vem hjälper de","mr obreen","blackwater raiders"}}},fp="15,226,20.358.0,23.149.0,38.127.0,38.140.0,49.161.0"}
P.entries["quest:666"] = {n="Sunken Treasure",s="Efter den första delen av Sunken Treasure lånar Doctor Draxlegauge ut sina Goggles of Gem Hunting till dig och ber dig samla in tio alviska ädelstenar från havsbotten åt Captain O'Breen och sedan lämna tillbaka glasögonen.",h="Efter den första delen av Sunken Treasure lånar Doctor Draxlegauge ut sina Goggles of Gem Hunting till dig...",kw={"arathi highlands","captain o'breen","doctor draxlegauge","alvisk ädelsten","faldir's cove","fleet master seahorn","goggles of gem hunting","sunken treasure"},sec={{t="Ädelstenar som blivit sten",b="På havsbotten har ädelstenarna legat så länge att de har hårdnat till massiv sten. Kraften i glasögonen gör att du ändå kan hitta dem, och Doctor Draxlegauge är stolt över det gnomiska snillet bakom dem. Han lånar ut glasögonen så att du kan samla in de förlorade ädelstenarna åt Captain O'Breen."},{t="Torr mark åt doktorn",b="Han skulle själv dyka ner, säger han, men vetenskapligt arbete väntar på honom på trygg, torr mark. Han vill ha tillbaka glasögonen efteråt och är säker på att Captain O'Breen kommer att få stor användning av dem."}},faq={{q="Vem skickar dig för att samla in ädelstenarna?",a="Doctor Draxlegauge, som väntar i Faldir's Cove. Han vill att tio alviska ädelstenar samlas in åt Captain O'Breen.",al={"vem ger sunken treasure 2","uppdragsgivare sunken treasure"}},{q="Varför behövs särskilda glasögon för sökandet?",a="Efter så lång tid på havsbotten har ädelstenarna förvandlats till massiv sten. Kraften i Goggles of Gem Hunting gör att du lätt kan hitta dem.",al={"varför goggles of gem hunting","vad gör glasögonen"}},{q="Varför dyker inte Doctor Draxlegauge själv efter ädelstenarna?",a="Han säger att viktiga vetenskapliga angelägenheter håller honom kvar på trygg, torr mark.",al={"varför simmar inte draxlegauge","varför stannar draxlegauge på land"}},{q="Får du behålla Goggles of Gem Hunting?",a="Nej. Doktorn lånar ut dem och vill ha tillbaka dem när du är klar, eftersom han räknar med att Captain O'Breen kommer att använda dem ofta.",al={"behålla glasögon för ädelstensjakt","ska jag lämna tillbaka glasögonen"}},{q="Var i kedjan Sunken Treasure hör det här hemma?",a="Det följer efter den första delen av Sunken Treasure, då Professor Phizzlethorpe laddade glasögonen. En tredje del kommer efter det.",al={"vad kommer före det här","vad är nästa steg"}}},fp="15,140,20.298.0,23.211.0,33.101.0,48.130.0,57.78.0,40.120.0,50.119.0"}
P.entries["quest:6661"] = {n="Deeprun Rat Roundup",s="Deeprun Rat Roundup är ett uppdrag för Alliansen i Deeprun Tram, där spelare hjälper Monty att bekämpa skadedjur. Med en förtrollande flöjt samlar de ihop levande Deeprun-råttor, så att Montys bror får färskt kött till råttspett.",h="Deeprun Rat Roundup är ett uppdrag för Alliansen i Deeprun Tram, där spelare hjälper Monty att bekämpa...",kw={"deeprun-råtta","deeprun rat roundup","deeprun tram","monty","rat catchers flute","råttspett","ohyra"},ang={["profession:Cooking"]="Montys bror använder nyfångad ohyra från Deeprun för att laga råttspett. Råttorna måste hållas vid liv tills de ska tillagas, annars blir köttet dåligt."},sec={{t="Skadedjur under rälsen",b="Långt nere i Deeprun Trams underjordiska tunnel kämpar en färgstark person vid namn Monty för att hålla transportlinjen fri från skadedjur. Monty talar som en sjöbuse och behandlar spåret som ett fartygsdäck, och ber resenärer som passerar om hjälp att samla ihop ohyran som springer runt på stationen."},{t="En tveksam delikatess",b="I stället för att utrota gnagarna ger Monty sina hjälpare en Rat Catcher's Flute, vars förtrollande melodi lockar Deeprun-råttorna att följa efter. Djuren måste återföras levande och sprattlande, eftersom Montys bror behöver färska råttor till matlagningen. Han ska nämligen göra råttspett av dem innan köttet blir skämt."}},faq={{q="Vem ger uppdraget Deeprun Rat Roundup?",a="Monty, en sjörövarpratande figur som håller till nere i Deeprun Tram, delar ut uppgiften. Han behöver fler händer som hjälper till att hantera ett skadedjursproblem längs den underjordiska transportlinjen.",al={"vem ger deeprun rat roundup","monty deeprun tram","råttuppdragskillen"}},{q="Varför måste Monty fånga råttorna levande?",a="Monty behöver Deeprun-råttorna levande så att köttet inte hinner bli skämt innan hans bror kan laga råttspett av dem. Om ohyran dör i förtid blir köttet dåligt.",al={"varför fånga råttor levande","vad gör monty med råttorna","råttspett i berättelsen"}},{q="Hur lockar du till dig och samlar ihop råttorna?",a="Monty ger dig en förtrollad Rat Catcher's Flute. Spela melodin nära ohyran, så förtrollas råttorna och följer efter dig tillbaka till Montys station.",al={"hur fångar man deeprun-råttor","vad används flöjten till","rat catchers flute deeprun"}},{q="Var utspelar sig uppgiften?",a="Uppdraget utspelar sig inne i Deeprun Tram, ett underjordiskt ingenjörsmästerverk som förbinder Alliansens städer Stormwind och Ironforge. Monty håller till längs spårplattformarna.",al={"var finns deeprun rat roundup","var finns monty","råttor i deeprun tram"}},{q="Vem är Montys bror?",a="Monty nämner att han har en bror som lagar råttspett, men han säger inte vad brodern heter. Brodern behöver en stadig tillgång på färska, levande råttor för att inte servera härsket kött.",al={"vem är montys bror","montys bror lagar mat","bror som lagar råttspett"}},{q="Varför pratar Monty som en sjörövare?",a="Monty talar med kraftig sjörövarjargong och behandlar spåret som ett fartygsdäck, men han har tagit på sig att bekämpa skadedjur i den underjordiska järnvägen.",al={"varför finns en sjörövare i spårvagnen","monty sjörövare deeprun"}}},fp="19,138,24.241.0,23.220.1,40.128.0,44.129.0,39.133.0,32.106.0,23.152.0,34.142.0"}
P.entries["quest:6662"] = {n="Me Brother, Nipsy",s="Me Brother, Nipsy är ett leveransuppdrag för Alliansen som tar resenärer mellan Ironforge och Stormwind med Deeprun Tram. En gnom vid namn Monty ber passagerare transportera en låda med levande råttor till hans bror Nipsy, som driver ett stånd med råttkebab vid den andra ändstationen. Under det egendomliga ärendet döljer sig en gripande inblick i Montys splittrade sinne efter tragedin i Gnomeregan.",h="Me Brother, Nipsy är ett leveransuppdrag för Alliansen som tar resenärer mellan Ironforge och Stormwind med...",kw={"deeprun tram","gnomeregan","stationen i ironforge","me brother, nipsy","monty","mystery meat","nipsy","råttkebab","stationen i stormwind"},ang={["faction:Alliance"]="Deeprun Tram är ett viktigt tekniskt underverk som snabbt förbinder Stormwind och Ironforge. Vid båda stationerna finns dessutom egenartade försäljare som betjänar resenärer.",["profession:Cooking"]="Nipsys matverksamhet går ut på att trä färska Deeprun-råttor på spett och sälja dem som ätbar kebab till resenärer mellan Ironforge och Stormwind.",["race:Gnome"]="Montys excentriska vanföreställningar och piratmanér beror direkt på traumat från händelsen i Gnomeregan och visar hur djupt stadens fall drabbade de överlevande gnomerna."},sec={{t="En underjordisk leverans",b="Me Brother, Nipsy är ett kort budärende som låter resenärer upptäcka Deeprun Tram och dess faror. Vid spårvägens station i Ironforge ber en besynnerlig gnom vid namn Monty resenärer att frakta en kartong med färska småkryp genom den underjordiska transportkorridoren till sin bror Nipsy vid Stormwindstationen. Leveransen visar den märkliga vardagshandel som pågår under bergen mellan dvärgarnas och människornas huvudstäder."},{t="Handeln med råttkebab",b="Trots etiketten Carton of Mystery Meat är paketet faktiskt fullt av levande, slingrande Deeprun-råttor. Nipsy driver en verksamhet med råttkebab vid Stormwindstationen och behöver få sina varor levererade innan de blir dåliga. När lådan anländer hel och fortfarande sprattlande kan Nipsy fortsätta hålla sitt matställe välförsett för hungriga resenärer på genomresa."},{t="Ärr från Gnomeregan",b="Under den humoristiska leveransen döljer sig en allvarlig glimt av de fördrivna gnomerna i Ironforge. Monty talar med överdriven piratjargong och varnar resenärer för att hålla armar och ben ombord, så att de inte blir enbenta. När Nipsy tar emot råttorna beklagar han sig över att Monty aldrig har sett ett hav i hela sitt liv. Hans excentriska piratpersona är bara ett sätt att hantera det kvarvarande traumat efter Gnomeregans radioaktiva fall."}},faq={{q="Vem ger uppdraget Me Brother, Nipsy?",a="Monty är en excentrisk gnom som finns vid Deeprun Trams station i Ironforge. Katastrofen i Gnomeregan har påverkat honom djupt, och han har tagit efter en pirats tal och manér trots att han aldrig har sett ett hav. Han fångar levande råttor för att skicka dem längs spårvägen.",al={"vem ger me brother nipsy","vem är monty","monty spårvagn"}},{q="Vem är Nipsy?",a="Nipsy är Montys bror och driver ett matstånd vid Deeprun Tram-stationen i Stormwind. Han förlitar sig på att Monty skickar över levande råttor genom spårtunneln så att han får färska råvaror till sin råttkebab.",al={"vem är nipsy","var finns nipsy","nipsys plats"}},{q="Vad finns i Carton of Mystery Meat?",a="Trots den skämtsamma etiketten Mystery Meat är lådan full av levande, sprattlande Deeprun-råttor som Monty har fångat. Nipsy kräver att de anländer levande och sprattlande så att köttet inte hinner bli dåligt innan det träs på spett till kebab.",al={"vad är carton of mystery meat","lådan med mystery meat","vad finns i lådan"}},{q="Varför talar Monty som en pirat?",a="Monty talar som en pirat eftersom traumat från katastrofen i Gnomeregan krossade hans sinne. Som hans bror Nipsy beklagar sig har Monty aldrig ens sett ett hav, men han håller fast vid sina piratmanér och varnar resenärer för att förlora lemmar över spåren.",al={"varför talar monty som en pirat","är monty en pirat","montys piratbakgrund"}},{q="Vad gör Nipsy med råttorna?",a="Nipsy tillagar och säljer råttkebab till passagerare som passerar genom stationen i Stormwind. En stadig tillgång på färska, sprattlande småkryp från spårvägen håller hans ovanliga underjordiska matställe igång.",al={"vad gör nipsy med råttorna","råttkebabverksamhet","nipsys mat"}},{q="Vart levererar du försändelsen?",a="Du tar försändelsen med Deeprun Tram från stationen i Ironforge till ändstationen i Stormwind. När du kliver ombord på en av de snabba spårvagnarna färdas du genom undervattenstunneln raka vägen till Nipsys station på Stormwindsidan.",al={"hur tar jag mig till nipsy","vart ska jag ta köttet","spårvagnsresa till nipsy"}}},fp="17,183,23.243.0,19.287.0,19.248.1,38.246.0,13.171.0,42.157.0,35.216.0,33.130.0,34.180.0"}
P.entries["quest:667"] = {n="Death From Below",s="I Arathi Highlands väntar sig Shakes O'Breen att Daggerspine-nagorna ska anfalla från havet, och besättningen kan inte segla hem till Booty Bay utan O'Breens kunskap om vattnen. Du stannar ombord hos O'Breen, bemannar kanonen och driver tillbaka nagorna.",h="I Arathi Highlands väntar sig Shakes O'Breen att Daggerspine-nagorna ska anfalla från havet, och besättningen...",kw={"arathi highlands","booty bay","daggerspine","nagor","shakes o'breen","skeppskanon"},sec={{t="Håll däcket",b="Efter Sunken Treasure ser Shakes O'Breen hur Daggerspine-nagorna samlas för att anfalla. Nagorna är kända för sin hänsynslöshet och fortsätter tills O'Breen är död. O'Breen värderar inte sitt eget liv högre än besättningens, men ber dig försvara dem, eftersom besättningen inte kan ta sig till Booty Bay utan O'Breens kunskap om haven. Du väntar ombord med O'Breen på att nagorna ska komma från vattnet."},{t="Efteråt",b="När anfallet är över säger O'Breen att skeppet ger sig av så snart tidvattnet stiger. O'Breen skulle ha erbjudit dig en plats i besättningen, men ser att du har större fiskar att steka."}},faq={{q="Vem anfaller Shakes O'Breen?",a="Daggerspine-nagorna samlas för att anfalla och fortsätter tills Shakes O'Breen är död. De kommer från havet.",al={"vem anfaller shakes","vilka är angriparna","daggerspine anfaller"}},{q="Varför är det så viktigt för besättningen att skydda Shakes O'Breen?",a="Shakes O'Breen värderar inte sitt eget liv högre än besättningens, men utan O'Breens kunskap om haven kan besättningen inte segla tillbaka till Booty Bay.",al={"varför skydda shakes obreen","varför är shakes viktig","shakes obreen navigation"}},{q="Hur slår du tillbaka nagornas anfall?",a="Du stannar ombord med Shakes O'Breen och bemannar kanonen för att driva tillbaka nagorna när de kommer från havet.",al={"hur klara death from below","hur försvara shakes","kanonförsvar"}},{q="Var äger försvaret rum?",a="På Shakes O'Breens skepp i Arathi Highlands, medan nagorna kommer från havet.",al={"var finns death from below","death from below plats"}}},fp="16,174,16.372.0,9.176.1,32.120.0,54.138.0,34.108.0,35.87.0"}
P.entries["quest:668"] = {n="Sunken Treasure",s="Doctor Draxlegauge ger dig de alviska ädelstenarna och skickar dig för att överlämna dem till Captain O'Breen. Efter några veckor bland piraterna vet han och professorn att det är ohälsosamt att behålla skatten.",h="Doctor Draxlegauge ger dig de alviska ädelstenarna och skickar dig för att överlämna dem till Captain O'Breen.",kw={"arathi highlands","captain o'breen","doctor draxlegauge","alviska ädelstenar","pirater","shakes o'breen","sunken treasure"},sec={{t="Skatt åt kaptenen",b="Doctor Draxlegauge vill inte låta Captain O'Breen vänta, eftersom kaptenen själv vill se de alviska ädelstenarna. Efter veckor bland dessa pirater har doktorn och professorn lärt sig att det är dåligt för hälsan att bli ertappad med piratskatt. Han ger dig ädelstenarna så att du kan ta dem till O'Breen, som väntar vid bron."}},faq={{q="Vem skickar dig till Captain O'Breen?",a="Doctor Draxlegauge ger dig de alviska ädelstenarna och ber dig ta dem till Captain O'Breen.",al={"vem ger sunken treasure 3","draxlegauges uppdrag"}},{q="Varför är Doctor Draxlegauge så angelägen om att lämna ifrån sig ädelstenarna?",a="Efter några veckor bland dessa pirater har han och professorn bestämt sig för att det vore dåligt för hälsan att bli ertappad med piraternas skatt.",al={"varför lämna över alviska ädelstenar","varför ge ädelstenar till pirat"}},{q="Var i kedjan kommer det här?",a="Det följer på den andra delen av Sunken Treasure, och en fjärde del kommer efter det.",al={"sunken treasures plats i kedjan","vad kommer före sunken treasure 3"}}},fp="15,215,24.319.0,33.72.0,55.136.0,34.82.0"}
P.entries["quest:669"] = {n="Sunken Treasure",s="Efter föregående steg i Sunken Treasure-kedjan sitter Shakes O'Breen fast där han är och behöver få ett meddelande till Fleet Master Seahorn i Booty Bay. Han ber dig ta med en provädelsten som bevis på fyndet.",h="Efter föregående steg i Sunken Treasure-kedjan sitter Shakes O'Breen fast där han är och behöver få ett...",kw={"arathi highlands","blackwater raiders","booty bay","fleet master seahorn","provädelsten från alverna","shakes o'breen","sunken treasure"},sec={{t="Meddelande till Booty Bay",b="Shakes O'Breen vill att Fleet Master Seahorn genast får höra om fyndet, men han kan inte lätt ta sig därifrån. Tidvattnet är för lågt, och varelserna de störde håller ögonen på varje rörelse. Han ber dig hjälpa Blackwater Raiders genom att berätta för Seahorn i Booty Bay att skatten har hittats och att mer håller på att bärgas. Du får med dig en provädelsten från alverna som bevis."}},faq={{q="Varför kan inte Shakes O'Breen själv lämna över ädelstenen?",a="Tidvattnet är för lågt för att de ska kunna ta sig därifrån, och varelserna de störde håller noga uppsikt över deras rörelser.",al={"varför kan shakes inte ge sig av","varför sitter shakes fast","varför behöver shakes ett bud"}},{q="Vem är Fleet Master Seahorn?",a="Han är Fleet Master i Booty Bay, och O'Breen vill att han genast får höra om fyndet.",al={"vem är seahorn","var finns fleet master seahorn"}},{q="Vilket bevis förs till Booty Bay?",a="En provädelsten från alverna, som visar att skatten har hittats och att mer håller på att bärgas.",al={"vad är beviset","vilken ädelsten levereras"}}},fp="15,117,18.301.0,49.117.0,28.88.0,41.90.0"}
P.entries["quest:67"] = {n="The Legend of Stalvan",s="Det här ärendet inleder spåren efter Stalvan Mistmantles öde, på uppdrag av Clerk Daltry i Darkshires stadshus.",h="Det här ärendet inleder spåren efter Stalvan Mistmantles öde, på uppdrag av Clerk Daltry i Darkshires...",kw={"daltry","duskwood","kista","forlorn spirit","mistmantle","moonbrook","skola","stalvan","westfall"},ang={["class:Mage"]="Forlorn Spirit som vaktar kistan använder förvandling och försvagande förbannelser. Den bjuder på ett kusligt möte med sorgbunden magi i en annars vardaglig skolmiljö.",["faction:Alliance"]="Den här delen av utredningen visar hur djupt kungarikets landsbygdsstäder har splittrats. Hjältar måste ta sig genom ett Westfall som ockuperats av Defias bara för att reda ut en fråga i Darkshires stadsregister."},sec={{t="Stadsskrivarens begäran",b="Efter de första efterforskningarna i Darkshire tar Clerk Daltry fram stadens register för att hitta Stalvan Mistmantle. Till sin förvåning upptäcker han att liggaren inte har uppdaterats på flera år och anger Stalvans senast kända bostad långt västerut, vid skolan i Moonbrook. Daltry känner inte till utredningens olycksbådande natur och ser det som vanligt pappersarbete. Han ber resenärer undersöka adressen och samla in handlingar som kan föra Darkshires dammiga arkiv à jour."},{t="Moonbrooks ruiner",b="För att följa spåren måste du ta dig genom Duskwoods mörker och in i Westfalls laglösa ödemark. Moonbrook, som en gång var en blomstrande jordbruksbygd, kryllar nu av laglösa från Defias Brotherhood. Nära den övergivna stadens mitt står den gamla skolan, tyst mitt bland banditerna. Inuti rymmer en gammal kista de första konkreta ledtrådarna om Stalvans forna liv som lärare, liksom en kvardröjande, orolig sorg som är bunden till kistan."},{t="En tragisk hemsökelse",b="När du rör vid den gamla kistan får du mer än bortglömda sidor. Du väcker en Forlorn Spirit som angriper alla som gräver i Stalvans förflutna. Vålnadens sorgsna magi förbannar inkräktare och antyder en olöst tragedi kring skolmästarens avfärd från Westfall. En enkel historisk efterforskning blir därmed en aktiv hemsökelse."}},faq={{q="Vem är Clerk Daltry?",a="Clerk Daltry sköter stadens arkiv i Darkshire Town Hall i Duskwood. Han söker i det lokala registret efter uppgifter om Stalvan Mistmantle, men hittar bara gamla, inaktuella noteringar.",al={"daltry","skrivare i darkshire","vem startar legend of stalvan 2"}},{q="Var ligger Moonbrook Schoolhouse?",a="Skolan ligger i Moonbrook i sydvästra Westfall. Arkitekturen påminner om stadshuset i Darkshire. Byggnaden står mitt i staden, omgiven av fientliga banditer från Defias.",al={"moonbrook schoolhouse plats","var ligger skolan","var finns stalvans kista"}},{q="Vad finns i den gamla kistan?",a="Kistan innehåller gamla handlingar och personliga tillhörigheter från Stalvan Mistmantles tid som lärare i Moonbrook. Där finns nästa ledtråd i sökandet efter honom.",al={"stalvans kista","vad finns i kistan"}},{q="Varför anfaller ett spöke när man öppnar kistan?",a="När du öppnar kistan frammanas en Forlorn Spirit som anfaller med förvandling och förbannelser. Den rastlösa vålnaden är bunden till den mörka tragedin kring Stalvans förflutna och hans avfärd från Moonbrook.",al={"forlorn spirit","varför dyker ett spöke upp","stalvans spökes förbannelse"}},{q="Varför lämnade Stalvan Westfall?",a="Stalvan arbetade som skolmästare i Moonbrook innan han drog vidare för att söka arbete som privatlärare någon annanstans i kungariket. Han lämnade sina tillhörigheter i den gamla skolan, inlåsta i den övergivna staden.",al={"varför lämnade stalvan moonbrook","stalvans historia i moonbrook"}},{q="Är Moonbrook säkert att gå in i?",a="Nej. Moonbrook kontrolleras helt av Defias Brotherhood. Den som söker sig till skolan måste slå sig igenom beväpnade tjuvar och laglösa.",al={"är moonbrook farligt","fiender i moonbrook"}}},fx={["803ebeb2"]={q="Varför vill Clerk Daltry att det här ska göras?",a="Clerk Daltry är mycket stolt över sitt yrke och sköter Darkshires stadsregister. När han kontrollerar handlingarna för Stalvan Mistmantle upptäcker han att mannens senast kända adress står som Moonbrook Schoolhouse i Westfall. Han vet hur inaktuell uppgiften är och vill att du besöker skolan och tar reda på om det finns någon ny information, så att hans register förblir prydliga och korrekta.",al={"varför vill daltry ha stalvans handlingar","clerk daltrys motiv","varför hitta stalvan"}}},fp="21,175,24.393.0,22.351.0,17.289.1,20.167.0,35.166.0,34.182.0,52.182.1,31.165.0,27.114.0"}
P.entries["quest:670"] = {n="Sunken Treasure",s="Fleet Master Seahorn, vars skepp inte kan lämna Booty Bay förrän de har fyllt på förråden, ber dig att ta med ett hemligt brev till Shakes O'Breen, som är upptagen utanför Arathi Highlands kust.",h="Fleet Master Seahorn, vars skepp inte kan lämna Booty Bay förrän de har fyllt på förråden, ber dig att ta med...",kw={"arathi highlands","blackwater raiders","booty bay","fleet master seahorn","seahorns förseglade brev","shakes o'breen","sunken treasure"},sec={{t="Ett brev till O'Breen",b="Fleet Master Seahorn bedömer dig som en äventyrslysten typ. Hans skepp kan inte lämna Booty Bay förrän de har fyllt på förråden, och han säger att allvarliga saker är på gång både här och utomlands. Han behöver att du tar med topphemlig korrespondens till Shakes O'Breen utanför Arathi Highlands kust, och frågar om han kan lita på att du levererar meddelandet säkert och diskret."}},faq={{q="Vem skickar dig för att leverera brevet?",a="Fleet Master Seahorn i Booty Bay ger dig ett förseglat brev till Shakes O'Breen.",al={"vem ger sunken treasure 5","vem startar uppdraget","seahorns uppdragsgivare för brevet"}},{q="Varför levererar Fleet Master Seahorn inte brevet själv?",a="Hans skepp kan inte lämna Booty Bay förrän de har fyllt på förråden.",al={"varför kan seahorn inte lämna booty bay","varför har fleet master seahorn fastnat"}},{q="Var befinner sig Shakes O'Breen?",a="Utanför Arathi Highlands kust, där Seahorn säger att han är upptagen.",al={"var hittar man shakes obreen","shakes obreens plats","var är shakes"}},{q="Vad föregick den här leveransen?",a="Den följer på den fjärde delen av Sunken Treasure.",al={"sunken treasure-uppdragskedjan","vilket uppdrag kommer före sunken treasure 5"}}},fp="15,136,20.286.0,37.79.0,60.56.0,32.61.0,31.57.0"}
P.entries["quest:671"] = {n="Foul Magics",s="Foul Magics är ett Horde-uppdrag som börjar i Hammerfall i Arathi Highlands. Tor'gan känner en oroande demonisk närvaro i väster och upptäcker spår av mörka kallelseritualer vid Northfold Manor. Han ber äventyrare ta sig in i godset och hämta blodstensamuletter som används vid dessa kallelser, så att han kan studera deras mörka magi.",h="Foul Magics är ett Horde-uppdrag som börjar i Hammerfall i Arathi Highlands.",kw={"arathi highlands","blodsten","blodstensamulett","demonisk kallelse","foul magics","hammerfall","northfold manor","tor'gan"},ang={["class:Warlock"]="Kriglockare är väl förtrogna med ritualerna och bindningsreagenserna som krävs för att kalla fram demoner. Därför är blodstensamuletterna vid Northfold Manor särskilt intressanta för dem.",["faction:Horde"]="Eftersom Hammerfall är Hordens enda utpost i Arathi Highlands utgör mörka kallelseutövare så nära västerut ett direkt säkerhetshot mot bosättningen.",["race:Orc"]="Orcher har en lång och smärtsam historia av demonisk korruption, och kvarvarande felmagi kan få blodet att koka och väcka onaturlig vrede. Tor'gans instinktiva reaktion nära Northfold Manor visar hur känsliga orcher fortfarande är för demoniska kallelser."},sec={{t="En pyrande vrede",b="Tor'gan, en orch stationerad vid Hordens utpost Hammerfall, började märka en oroande störning som drog genom Arathi Highlands. För en orch är demoniska energier inte bara ett abstrakt hot; de väcker en instinktiv, biologisk reaktion med rötter i blodförbannelsens historia. När Tor'gan följde sin oro västerut mot Northfold Manor fick den omgivande korruptionen hans blod att koka och väckte en ofrivillig vrede inom honom. Han kände igen de tydliga spåren efter en demonisk kallelse och drog sig tillbaka innan det mörka inflytandet överväldigade hans sinnen. I stället sökte han hjälp utifrån, hellre än att återvända själv."},{t="Blodstensamuletterna",b="Vid Northfold Manor upptäckte Tor'gan konkreta bevis på mörka ritualer: en amulett av blodsten som låg på marken. Dessa magiska amuletter används aktivt för att underlätta och stabilisera demoniska kallelseritualer. Amuletten Tor'gan lyckades hitta hade redan tömts på sin magiska kraft, vilket gjorde en grundlig magisk undersökning omöjlig. För att undersöka kallelsernas fulla omfattning och avgöra vilka väsen som kallades fram skickar han Horde-resenärer till Northfold Manor för att hämta tio intakta blodstensamuletter från utövarna som håller till där."}},faq={{q="Vem ger uppdraget Foul Magics?",a="Uppdraget erbjuds av Tor'gan, en orch i Hammerfall, Hordens fäste i Arathi Highlands. Tor'gan känner en oroande demonisk närvaro i närheten och ber äventyrare undersöka Northfold Manor för att ta reda på vilka mörka krafter som verkar där.",al={"vem ger uppdraget foul magics","vem startar foul magics","tor'gan uppdrag arathi"}},{q="Var ligger Northfold Manor?",a="Northfold Manor ligger väster om Hammerfall, bland de norra kullarna i Arathi Highlands. Godset var en gång ett mänskligt hem, men har blivit en plats för hemliga demoniska kallelser med blodstensamuletter.",al={"northfold manor plats","var ligger northfold manor","hitta northfold manor arathi"}},{q="Vad används blodstensamuletter till?",a="Blodstensamuletter är magiska fokuspunkter som används för att bistå vid demoniska kallelseritualer. Tor'gan upptäckte att utövarna vid Northfold Manor använder stenarna för att kanalisera mörk magi, men enskilda amuletter töms på kraft under en kallelse.",al={"vad är en blodstensamulett","blodstensamulettens syfte","varför blodstensamuletter"}},{q="Varför känner Tor'gan vrede nära Northfold Manor?",a="Tor'gan får en våldsam fysisk reaktion nära Northfold Manor på grund av kvarvarande energier från demoniska kallelser. För orcher väcker exponering för felmagi resterna av blodförbannelsen, så att blodet kokar och en okontrollerbar vrede blossar upp.",al={"varför kokar tor'gans blod","tor'gans vrede northfold","varför blir tor'gan arg"}},{q="Varför vägrar Tor'gan att återvända till Northfold Manor?",a="Tor'gan vägrar återvända till Northfold Manor eftersom den kvarvarande demoniska kraften väcker en farlig vrede inom honom. Han är rädd att förlora kontrollen eller falla offer för det fördärvande inflytandet, så han anlitar äventyrare utifrån för att hämta amuletterna åt honom.",al={"varför går tor'gan inte till northfold","varför återvänder tor'gan inte","varför kan tor'gan inte hämta amuletterna"}},{q="Hur många blodstensamuletter behövs?",a="Tor'gan ber om tio blodstensamuletter från Northfold Manor. Eftersom den enda amulett han hittade på marken var helt tömd på kraft behöver han flera laddade exemplar för att kunna undersöka och förstå ritualerna där ordentligt.",al={"hur många blodstensamuletter","antal blodstensamuletter","antal mål i foul magics"}},{q="Vem kallar fram demoner vid Northfold Manor?",a="Mörka utövare har tagit över Northfold Manor för att genomföra olovliga demoniska kallelser. Deras mörka ritualer och de felrester som blir kvar väckte Tor'gans uppmärksamhet från Hammerfall och fick Horden att undersöka godset.",al={"vem finns vid northfold manor","vem kallar fram demoner vid northfold","kultister vid northfold manor"}}},fp="11,160,16.391.0,22.436.0,32.173.0,33.184.0,37.149.0,48.193.0,53.182.0,39.174.0,43.178.0"}
P.entries["quest:672"] = {n="Raising Spirits",s="Raising Spirits är ett Horde-uppdrag i Arathi Highlands där Tor'gan försöker muntra upp den nedslagne orchen Gor'mul. När berättelser om Orgrimmar och hövding Thrall inte hjälper vänder sig Tor'gan till återupptäckta shamantraditioner och skapar en stärkande amulett av ögonen från höglandsraptorer.",h="Raising Spirits är ett Horde-uppdrag i Arathi Highlands där Tor'gan försöker muntra upp den nedslagne orchen...",kw={"arathi highlands","gor'mul","hammerfall","ögon från höglandsraptorer","orgrimmar","raising spirits","shamanism","thrall","tor'gan"},ang={["class:Shaman"]="Det här försöket visar hur Hordens återupplivade shamantraditioner används för att läka känslomässiga sår och håglöshet, genom att låta djurandar väcka en broders livsvilja på nytt.",["faction:Horde"]="Uppdraget visar den omtänksamma sidan av Thralls Horde, där kamrater vid avlägsna utposter som Hammerfall tar hand om nedslagna vapenbröder i stället för att överge dem.",["race:Orc"]="Många veteraner som Gor'mul bär fortfarande på håglösheten och förtvivlan efter interneringslägren och förlusten av sina gamla levnadssätt. De har svårt att ta till sig Thralls nya Horde."},sec={{t="Ett tungt hjärta i Hammerfall",b="I den avlägsna utposten Hammerfall i Arathi Highlands står orcherna inför yttre fiender och tysta inre strider. En av dem, Gor'mul, har sjunkit ner i en djup och obeveklig melankoli. Hans kamrater försökte muntra upp honom med stolta berättelser om Kalimdor, den mäktiga fästningsstaden Orgrimmar och den visionäre unge hövdingen Thralls ledarskap. Men inga av dessa storslagna segrar eller avlägsna under kunde tränga igenom Gor'muls mörker eller ge honom hopp."},{t="Vildmarkens andar",b="Tor'gan inser att ord inte räcker mot Gor'muls modlöshet och vänder sig till Hordens återupplivade andliga arv. Genom att samla ögonen från de vildsinta höglandsraptorer som strövar omkring i Arathi skapar Tor'gan en amulett välsignad av rovdjurens andar. Ritualen förlitar sig varken på råstyrka eller felmagi, utan åkallar den läkande kraften i nyanammade shamantraditioner och hoppas att bestens livsflamma ska väcka en broders slumrande livsvilja."}},faq={{q="Vem är Tor'gan?",a="Tor'gan är en orch stationerad vid Hordens utpost Hammerfall i Arathi Highlands. För att hjälpa sin nedslagne kamrat Gor'mul vänder han sig till Hordens nyupptäckta shamanmagi och skapar en amulett som kan återställa kamratens inre eld.",al={"vem är tor'gan","tor'gan hammerfall","uppdragsgivare raising spirits"}},{q="Vem är Gor'mul och varför behöver han muntras upp?",a="Gor'mul är en orch som bor i Hammerfall och lider av djup nedstämdhet och håglöshet. Hans orkiska kamrater har försökt muntra upp honom med berättelser om Orgrimmar och Thralls ledarskap, men ingenting har lyckats beröra honom eller väcka hans livsandar.",al={"vem är gor'mul","varför är gor'mul ledsen","deprimerad orch i hammerfall"}},{q="Varför behöver Tor'gan ögon från höglandsraptorer?",a="Tor'gan använder ögonen från Highland Striders och Highland Thrashers för att skapa en shamanamulett. Genom att kanalisera dessa vildsinta rovdjurs andar hoppas Tor'gan ge Gor'mul raptorernas medfödda styrka och uthållighet och åter tända hans stridsvilja.",al={"varför raptorögon","raptorögonamulett","syftet med raptorögon"}},{q="Var utspelar sig uppdraget?",a="Hammerfall är Hordens främsta utpost i Arathi Highlands och har fått sitt namn för att hedra den tidigare hövdingen Orgrim Doomhammer. Den fungerar som en befäst fristad för orcher som stannat kvar i Eastern Kingdoms.",al={"var ligger hammerfall","hammerfalls läge","orcher i arathi"}},{q="Vad är den nyfunna shamanmagin som Tor'gan nämner?",a="Under tiden med demonisk fördärvelse och den efterföljande interneringen förlorade orcherna sin andliga kontakt med elementen och förfädernas andar. Under hövding Thralls ledarskap har Horden återupptagit denna forntida shamanväg och vägleder sitt folk genom andlig harmoni i stället för felmagi.",al={"shamanmagi hos orcher","orchernas shamanism i nya horden","varför ny shamanmagi"}},{q="Vilka berättelser lyckades inte muntra upp Gor'mul?",a="Hans kamrater försökte inge Gor'mul hopp med storslagna berättelser om den nya huvudstaden Orgrimmar, på andra sidan havet i Kalimdor, och om hövding Thralls tapperhet när han bar Orgrim Doomhammers rustning och legendariska stridshammare.",al={"berättelser om thrall","vilka berättelser berättade de för gor'mul","berättelser om orgrimmar och gor'mul"}}},fp="15,220,27.248.0,19.268.0,15.171.0,48.134.0,43.190.0,33.175.0,63.236.0,40.170.0"}
P.entries["quest:673"] = {n="Foul Magics",s="Tor'gan i Hammerfall är säker på att en mäktig häxmästare bor innanför Stromgardes murar och använder en magisk relik för att kalla fram demoner i stora mängder. Efter den första delen av Foul Magics skickar han dig för att döda häxmästaren och hämta reliken.",h="Tor'gan i Hammerfall är säker på att en mäktig häxmästare bor innanför Stromgardes murar och använder en...",kw={"arathi highlands","blodsten","hammerfall","marez cowl","stromgarde","tor'gan","häxmästare"},sec={{t="En häxmästare i Stromgarde",b="Tor'gan är säker på att en häxmästare bor innanför Stromgardes murar. Då och då använder häxmästaren en magisk relik för att kalla fram fruktansvärda demoner i stora mängder. Branden i Tor'gans blod växer för varje dag. Han vill att häxmästaren hittas och dödas, och att det magiska föremål som finns på kroppen förs till honom, så att han kan förstöra det och hindra dess kraft från att fördärva landet. Häxmästaren är Marez Cowl, och föremålet är en Befouled Bloodstone Orb."},{t="Vad klotet påminner om",b="När klotet är förstört räknar Tor'gan med att hans oroliga nätter ska övergå i fridfull sömn. För honom påminner det om det fruktansvärda grepp demonerna en gång hade om orcherna, innan Hellscream befriade dem från sin förbannelse."}},faq={{q="Vem skickar dig för att jaga häxmästaren?",a="Tor'gan i Hammerfall skickar dig till Stromgarde för att hitta häxmästaren och ta det magiska föremål som hon bär.",al={"vem ger foul magics","uppdragsgivare för foul magics","tor'gan uppdrag"}},{q="Var finns häxmästaren?",a="Marez Cowl befinner sig innanför Stromgardes murar, utanför själva Keep och västerut, gömd bakom en byggnad. Du kan höra henne kanalisera en besvärjelse.",al={"var finns marez cowl","häxmästaren i stromgarde","var hittar man marez cowl"}},{q="Vilken relik ska du hämta?",a="Marez Cowls Befouled Bloodstone Orb, det magiska föremål som Tor'gan vill att du tar till honom så att han kan förstöra det.",al={"vilket föremål vill tor'gan ha","befouled bloodstone orb","föremål i foul magics"}},{q="Varför vill Tor'gan stoppa häxmästaren?",a="Häxmästaren har kallat fram fruktansvärda demoner i stora mängder. Tor'gan vill undanröja källan till den kraften och förstöra klotet, så att det inte längre kan fördärva landet.",al={"varför förstöra klotet","tor'gans motiv","varför stoppa häxmästaren"}}},fp="11,165,23.399.0,20.219.1,34.123.0,29.129.0,36.111.0,42.176.0"}
P.entries["quest:674"] = {n="Raising Spirits",s="Raising Spirits är ett uppdrag för Horde som ska väcka stridsviljan hos Gor'mul, en bruten krigare uppslukad av förtvivlan. Ett sändebud överlämnar en Raptor Talon Amulet i hopp om att väcka den vilda anda han en gång bar inom sig. Men Gor'mul förblir bitter och undrar om någon enkel prydnad någonsin kan läka hans sorg eller återge Horde dess ära.",h="Raising Spirits är ett uppdrag för Horde som ska väcka stridsviljan hos Gor'mul, en bruten krigare uppslukad...",kw={"gor'mul","horde","raising spirits","raptoramulett","raptor talon amulet","krigare"},ang={["class:Warrior"]="Uppgiften handlar om att åter tända krigarandan hos en orch som lamslagits av förtvivlan och sorg efter ett fegt angrepp.",["faction:Horde"]="Gor'mul sörjer Hordes förlorade styrka och undrar om en enkel prydnad någonsin kan återge fraktionen dess förlorade ära."},sec={{t="En gnista i falnad låga",b="I Raising Spirits ska en Raptor Talon Amulet överlämnas till en orch vid namn Gor'mul. Hans allierade hoppas att raptorernas vilda styrka och ursinne, förmedlade genom amuletten, ska väcka krigarens låga som en gång brann starkt i hans ådror."},{t="Bitterhet och förtvivlan",b="När Gor'mul tar emot amuletten visar han bara bitter sorg. Han plågas av minnet av hur de mäktigaste mästarna föll för fega händer och avvisar gåvan som blott polerat ben. Han undrar hur någon prydnad skulle kunna återge Horde dess forna ära."}},faq={{q="Vad är Raising Spirits?",a="Raising Spirits är ett uppdrag där en Raptor Talon Amulet ska överlämnas till den nedslagne krigaren Gor'mul i hopp om att åter väcka hans stridsvilja.",al={"vad är raising spirits","uppdraget raising spirits"}},{q="Vem är Gor'mul?",a="Gor'mul är en krigare vars anda brutits av förtvivlan efter att ha sett de mäktigaste mästarna falla för en feg hand. Han avfärdar gåvor och ifrågasätter Hordes framtid.",al={"vem är gor'mul","gor'mul"}},{q="Varför får Gor'mul amuletten?",a="Raptor Talon Amulet är tillverkad av polerat ben och raptorernas klor. Den ges i hopp om att raptorernas naturliga styrka och ursinne ska väcka Gor'muls inre låga.",al={"varför ge amuletten","vad gör raptor talon amulet"}},{q="Varför är Gor'mul nedslagen?",a="Gor'mul har förlorat allt hopp efter att ha sett de mäktigaste krigarna dödas av feghet. Tragedin har övertygat honom om att ära och styrka lätt kan släckas och brutit hans stridsvilja.",al={"varför är gor'mul ledsen","varför är gor'mul deprimerad"}},{q="Hur reagerar Gor'mul på amuletten?",a="Gor'mul avvisar gåvan och avfärdar bittert amuletten som blott polerat ben, som om den skulle kunna återupprätta Horde eller göra den tragedi han sörjer ogjord.",al={"gillar gor'mul amuletten","gor'muls reaktion"}},{q="Vad säger Gor'mul om Horde?",a="Gor'mul tvivlar öppet på att Horde någonsin kan återta sin forna ära. Han ser föga hopp när förrädiska dåd kan fälla även de största hjältarna.",al={"kan horde återupprättas","gor'mul och hordes ära"}}},fp="15,225,26.231.0,22.218.1,24.120.0,15.164.0,50.191.0,26.182.0,37.119.0,38.130.0"}
P.entries["quest:675"] = {n="Raising Spirits",s="Raising Spirits är ett Horde-uppdrag om de kvarvarande känslomässiga såren hos en gammal orc-veteran. Med Tor'gans vägledning försöker en shaman nå den bittra Gor'mul med förfädernas magi, för att återställa hans förlorade stolthet och livsvilja.",h="Raising Spirits är ett Horde-uppdrag om de kvarvarande känslomässiga såren hos en gammal orc-veteran.",kw={"amulett","gor'mul","nåd","orc","raising spirits","shaman","tor'gan","veteran","warchief"},ang={["class:Shaman"]="Uppdraget visar den återupprättande och andliga betydelsen av dagens orc-shamanism, där laddade reliker används för att hjälpa brustna veteraner att läka kvarvarande trauman.",["faction:Horde"]="Under Thralls ledning försöker Horden aktivt återintegrera och lyfta bittra veteraner i stället för att överge dem åt förtvivlan.",["race:Orc"]="Gor'mul personifierar den djupa andliga sjukdom och vanära som gamla veteraner känner när de nekas det de ser som en hedervärd död vid sidan av sin forna Warchief."},sec={{t="En bruten själ",b="Efter tidigare krig kämpar många orc-veteraner med överlevnadens börda och känslan av vanära. Gor'mul är en sådan krigare, fast i bitter förtvivlan eftersom han nekades det han ser som en hedervärd död vid sidan av sin fallne Warchief. Tor'gan, en medkännande shaman, försöker lindra Gor'muls lidande genom att påminna honom om sitt folks andliga styrka. Tor'gan tror att förfädernas krafter kan läka känslomässiga sår och förbereder en förtrollad amulett som ska väcka den gamle krigarens stolthet till liv igen."},{t="Amulettens gränser",b="När amuletten överlämnas till Gor'mul får den inte önskad effekt. I ett utbrott av bitterhet kastar Gor'mul amuletten i smutsen och frågar varför någon skulle visa honom nåd när ödet nekade honom ett hedervärt slut. Tor'gan tar motgången med jämnmod och inser att en enda amulett inte hade kraft nog att övervinna åratal av djup sorg. Ändå håller shamanen fast vid sitt uppdrag och är övertygad om att den framväxande shamanismen till slut ska leda Gor'mul tillbaka till hans forna heder."}},faq={{q="Vem är Gor'mul?",a="Gor'mul är en bitter orc-veteran som förtärs av sorg och skuldkänslor över att ha överlevt. Han överlevde den äldre Horde-konflikten då hans Warchief föll, och ser sin fortsatta överlevnad som ödets grymma nyck. Han avvisar vanlig medkänsla.",al={"vem är gor'mul","gor'muls bakgrund","vad är det med gor'mul"}},{q="Vem är Tor'gan och varför hjälper han Gor'mul?",a="Tor'gan är en shaman som försöker lyfta Gor'mul ur hans bittra förtvivlan. Han tror att återknytningen till förfädernas seder kan hela brustna själar. Därför skapar Tor'gan laddade amuletter som ska påminna forna krigare om sitt folks andliga pånyttfödelse.",al={"vem är tor'gan","vad vill tor'gan","tor'gans syfte"}},{q="Vad var amulettens syfte?",a="Amuletten var en förtrollad talisman som Tor'gan hade förberett för att väcka Gor'muls krigaranda med shamanistisk kraft. När Gor'mul fick den avvisade han den och kastade den på marken, eftersom han tyckte att magin inte räckte för att skingra hans djupa bitterhet.",al={"vad är amuletten","varför kastade gor'mul amuletten","fungerade amuletten"}},{q="Vilken Warchief sörjer Gor'mul?",a="Gor'mul förbannar ödet för att det nekade honom döden vid sidan av hans Warchief i strid, men han nämner honom inte direkt. Hans ord speglar den tragiska synen hos den besegrade gamla Hordes kvarlevor, som längtade efter en hedervärd död på slagfältet.",al={"vilken warchief dog","vem var gor'muls warchief","vem tjänade gor'mul"}},{q="Vad tänker Tor'gan göra när amuletten misslyckas?",a="Tor'gan visar tålamod trots det första misslyckandet. Han medger att amuletten inte var tillräckligt kraftfull på egen hand, men tror fortfarande att shamanismens verkliga kraft till slut ska väcka Gor'muls förlorade stolthet till liv igen.",al={"ger tor'gan upp","vad händer efter raising spirits","kommer gor'mul att återhämta sig"}},{q="Varför använder Tor'gan shamanism för att hjälpa Gor'mul?",a="Det här visar vilken viktig roll shamaner har i den nya Horden som andliga läkare. De kanaliserar inte bara elementen i krig, utan tar också hand om sitt folks sårade sinnen och stolthet.",al={"vad visar detta om shamaner","varför använda shamanmagi här"}}},fp="15,133,15.376.0,24.363.1,15.207.0,45.240.0,35.198.0,34.118.0,52.153.0,47.132.0"}
P.entries["quest:676"] = {n="The Hammer May Fall",s="På uppdrag av Tallow från Tarren Mill skickas Hordens hjältar över bergen till Arathi Highlands för att undsätta Hammerfall, som är under belägring. Innan de rapporterar till Drum Fel måste äventyrarna visa att de är redo för strid mot de brutala Boulderfist-ogrerna nära Stromgardes ruiner.",h="På uppdrag av Tallow från Tarren Mill skickas Hordens hjältar över bergen till Arathi Highlands för att...",kw={"arathi highlands","boulderfist-väktare","boulderfist-ogre","drum fel","hammerfall","hillsbrad foothills","stromgarde","tallow","tarren mill","the hammer may fall"},ang={["class:Warrior"]="Att möta väldiga Boulderfist-väktare är en klassisk prövning för frontkämpar som vill vinna respekten hos erfarna orkbefälhavare som Drum Fel.",["faction:Horde"]="Det här uppdraget markerar den främsta övergången från de lokala konflikterna i Hillsbrad till det större försvaret av Arathi Highlands och stärker Hammerfalls viktiga fäste i regionen.",["race:Orc"]="Hammerfall har stor känslomässig och historisk betydelse för orkerna, eftersom det grundades där Warchief Orgrim Doomhammer gav sitt liv under befrielsekampanjerna."},sec={{t="En barsk kallelse",b="I Tarren Mill har Tallow föga tålamod med oprövade äventyrare som strövar omkring i Hillsbrad Foothills. När han ser odisciplinerade rekryter stå sysslolösa medan avlägsna allierade blöder, skickar han dugliga kämpar österut genom Thoradin's Wall till Arathi Highlands. Hordens utpost Hammerfall är belägrad från flera håll, men Tallow vägrar skicka dit folk utan att de först har visat sitt värde mot en övermäktig fiende."},{t="Prövning mot Boulderfist",b="I stället för att låta rekryterna vandra rakt in i Hammerfall kräver Tallow ett prov på stridsduglighet vid ogreberget nordost om Stromgarde. Boulderfist-stammen har en stark närvaro i Arathi, och deras väldiga ogres och väktare utgör ett omedelbart hot mot alla som färdas längs höglandets stigar. Att dräpa dessa bestar minskar både de fientliga styrkorna som hotar vägen och säkerställer att bara dugliga krigare når utposten."},{t="Rapportera till Hammerfall",b="När Boulderfist-lägret har rensats går vägen nordost till Hammerfall, en utpost uppkallad till minne av Warchief Orgrim Doomhammer. Där tar befälhavaren Drum Fel emot nyanlända med trött skepsis. Oavsett om Tallow tänkte förstärka garnisonen eller bara skicka dårar i döden, slösar Drum Fel ingen tid på att sätta beprövade kämpar i arbete mot de ändlösa skärmytslingar som hotar utpostens överlevnad."}},faq={{q="Var börjar och slutar det här uppdraget?",a="Uppdraget ges av Tallow i Tarren Mill, som ligger i Hillsbrad Foothills. När du har dödat de efterfrågade fienderna i Arathi Highlands lämnar du in det till Drum Fel i Hordens utpost Hammerfall.",al={"var börjar the hammer may fall","plats för inlämning av uppdraget","vem ger the hammer may fall"}},{q="Var finns Boulderfist-ogrerna?",a="Boulderfist-ogrerna håller till vid en stor jordhög och ett läger intill, nordost om ruinerna av Stromgarde i Arathi Highlands.",al={"boulderfist-ogreplats","var finns ogres i arathi","boulderfist-kullen"}},{q="Vad är utposten Hammerfall?",a="Hammerfall är en befäst bosättning för Horden i nordöstra Arathi Highlands. Den är uppkallad efter den tidigare Warchief Orgrim Doomhammer, som föll i strid i närheten under befrielsen av orkernas interneringsläger.",al={"vad är hammerfall","hammerfalls historia","vem grundade hammerfall"}},{q="Varför låter Tallow dig slåss mot ogres innan du rapporterar till Hammerfall?",a="Hammerfall är under ständig attack och behöver desperat dugliga kämpar. Tallow skickar rekryter mot Boulderfist-ogrerna som en hård prövning, för att försäkra sig om att alla som kommer för att förstärka Drum Fel kan slåss i stället för att bli en extra börda.",al={"varför döda ogres först","tallows motiv","varför prövar han mig"}},{q="Vem är Drum Fel?",a="Drum Fel är en veteran bland orkkrigare och befälhavare vid Hammerfall i Arathi Highlands. Han ansvarar för att organisera försvaret mot fientligt djurliv, ogres, troll och rester av Alliansen.",al={"drum fels identitet","hammerfalls befälhavare","vem är drum fel"}},{q="Vad följer efter det här uppdraget?",a="När du rapporterar till Drum Fel går du direkt vidare till kampanjen Call to Arms, en serie militära operationer som ska röja undan hot i området, däribland Witherbark-trollstammarna som hotar höglandet.",al={"nästa uppdrag","uppföljning till hammer may fall","vad kommer efter"}}},fx={b3b0715a={q="Vilka är Boulderfist-ogrerna som du skickas mot?",a="Boulderfist-stammen är en brutal ogreklan som gör anspråk på områden över hela Arathi Highlands, med sin kulle nordost om ruinerna av Stromgarde som centrum. De är våldsamma, envisa och fysiskt imponerande, och dominerar höglandets klippiga kullar medan de kämpar om den omgivande marken. Tallow skickar dig till deras kulle för att se om du kan överleva deras främsta kämpar och därmed visa att du har styrkan som krävs innan du kastar dig in i slakthuset i Arathis krigszon.",al={"boulderfist-ogrer","vilka är boulderfist","ogrer i arathi"}}},fp="19,217,15.379.0,20.319.0,23.345.1,36.190.0,40.123.0,34.188.0,68.189.0,16.172.0,29.183.0"}
P.entries["quest:677"] = {n="Call to Arms",s="Call to Arms är ett militärt initiativ från Horden, lett av Drum Fel från utposten Hammerfall i Arathi Highlands. En allians mellan de lokala Witherbark-skogstrollen och Boulderfist-ogrerna hotar Horden, som inleder ett förebyggande fälttåg mot Witherbark för att säkra sitt fotfäste i området.",h="Call to Arms är ett militärt initiativ från Horden, lett av Drum Fel från utposten Hammerfall i Arathi...",kw={"arathi highlands","yxkastare","boulderfist","call to arms","drum fel","hammerfall","huvudjägare","häxdoktor","witherbark"},ang={["faction:Horde"]="Hammerfall står isolerat i Arathi Highlands, omgivet av fientliga styrkor. Att försvara utposten mot aggressiva urinvånare är avgörande för att säkra Hordens permanenta fotfäste i människodominerade områden.",["race:Orc"]="Hammerfall byggdes på platsen för ett interneringsläger från det andra kriget. För orcher är det en symbol för frigörelse, vilket gör försvaret av deras nya bosättning mot fientliga grannar personligt.",["race:Troll"]="För Darkspear-troll som tjänar Thralls Horde visar kampen mot de fientliga Witherbark-skogstrollen den djupa splittringen mellan deras folk och stammarna som avvisade den nya Horden."},sec={{t="Försvaret av Hammerfall",b="Från den befästa tillflyktsorten Hammerfall organiserar Drum Fel en förebyggande militär attack mot Arathi Highlands fientliga urinvånare. Hordens bosättning ligger omgiven av gamla mänskliga ruiner och aggressiva lokala grupper och står inför ett överhängande hot från en pakt mellan Witherbark-skogstrollen och de brutala Boulderfist-ogrerna. I stället för att låta fienderna bestämma villkoren för deras överlevnad uppmanar Drum Fel mästare att gå till anfall."},{t="Hotet från Witherbark",b="Det första anfallet riktas mot området söder om Hammerfall, där Witherbarks kärnområde ligger. Witherbark har vänt diplomatin ryggen och valt att i stället konspirera med Boulderfist-ogrerna för att driva bort Horden från höglandet. Genom att slå ut deras specialiserade yxkastare, huvudjägare och häxdoktorer vill Hammerfall krossa deras militära ledning och visa att Horden tänker stanna."}},faq={{q="Vem ger uppdraget Call to Arms?",a="Call to Arms ges av Drum Fel, en orch som är stationerad vid Hordens utpost Hammerfall i nordöstra Arathi Highlands. Han samordnar försvars- och anfallsstyrkor för att trygga lägrets överlevnad mot hot från grannarna.",al={"vem ger call to arms","var finns drum fel","uppdragsgivare call to arms"}},{q="Varför angriper Hammerfall Witherbark-trollen?",a="Witherbark-stammen av skogstroll har allierat sig med Boulderfist-ogrerna för att driva bort Horden från Arathi Highlands. De har avvisat fredlig samexistens och vänt Horden ryggen. Deras aggressiva hållning lämnar Hammerfall utan annat val än att slå till först.",al={"varför döda witherbark","varför angripa troll i arathi","vad gjorde witherbark"}},{q="Var finns Witherbark-trollen?",a="Witherbark-trollen bor i flera bosättningar och läger söder om Hammerfall i Arathi Highlands, bland annat långt inne i Witherbark Village nära bergen.",al={"var finns witherbark-trollen","witherbark-lägrets plats","var hittar man yxkastare i arathi"}},{q="Vilken roll spelar Boulderfist-ogrerna i konflikten?",a="Boulderfist-ogrerna är en brutal klan som bor i Arathi Highlands. Enligt Drum Fel har de ingått en bekvämlighetsallians med Witherbark-trollen för att utrota Hordens närvaro på höglandet.",al={"vilka är boulderfist","ogrer i arathi","boulderfist-trollens allians"}},{q="Vad är Hammerfall och varför måste det försvaras?",a="Hammerfall är Hordens främsta utpost i Arathi Highlands, uppkallad till minne av krigshövding Orgrim Doomhammer. Den ligger på platsen för ett gammalt interneringsläger som tillhörde Alliansen och är en svårvunnen tillflyktsort och militär bastion för Horden i Eastern Kingdoms.",al={"vad är hammerfall","hammerfalls historia","varför finns horden i arathi"}},{q="Tillhör Witherbark-trollen Horden?",a="Nej. Darkspear-stammens djungeltroll tillhör Horden, men Witherbark är skogstroll som hör hemma i Eastern Kingdoms. De hyser ett djupt hat mot främlingar och har våldsamt avvisat alla inviter från Horden.",al={"tillhör witherbark horden","är skogstroll vänliga mot horden","darkspear mot witherbark"}}},fp="12,173,20.364.0,21.332.0,34.181.0,50.170.0,40.129.0,57.165.0,50.229.0,44.202.0"}
P.entries["quest:678"] = {n="Call to Arms",s="Call to Arms är ett krigiskt prov för Horden, utdelat av Drum Fel vid utposten Hammerfall i Arathi Highlands. Efter att ha visat att de är redo för strid beordras äventyrarna sydväst, mot dvärgarnas bro, för att ta sig an de farliga Boulderfist-ogrerna. Att slå ut både frontlinjens bestar och magikerkunniga magi prövar krigarens beslutsamhet och skyddar samtidigt Hordens utsatta fäste i Arathi.",h="Call to Arms är ett krigiskt prov för Horden, utdelat av Drum Fel vid utposten Hammerfall i Arathi Highlands.",kw={"arathi highlands","boulderfist","boulderfist brute","boulderfist magi","call to arms","drum fel","hammerfall","ogrer","thandol span"},ang={["class:Mage"]="Att möta Boulderfist Magi låter magiker sätta stopp för råstyrkans besvärjare, som böjer mystiska energier till primitiva, destruktiva syften.",["class:Warrior"]="Drum Fels krav på uthållighet inför råstyrka och magisk kraft ger krigare ett direkt prov på stridsuthållighet och krigarära.",["faction:Horde"]="Det är livsviktigt för Horden att säkra Hammerfall och sitt fäste i Eastern Kingdoms. Att rensa bort de aggressiva Boulderfist-ogrerna hindrar utposten från att bli övermannad.",["race:Orc"]="Hammerfall är uppkallat efter krigshövdingen Orgrim Doomhammer, vilket ger orcherna ett djupt personligt skäl att driva bort alla rivaliserande bestar som hotar denna minnesfästning."},sec={{t="Ett prov på tapperhet",b="I Hordens isolerade skans Hammerfall kräver överlevnad orubblig kampstyrka. Drum Fel ser hur resenärerna som hjälper utposten blir allt skickligare, men låter ingen slå sig till ro efter enkla segrar. I stället för att möta mindre skärmytslare måste krigarna bevisa sin tapperhet mot vad Fel ser som ett verkligt hot: de väldiga Boulderfist-ogrerna. Dessa bestar har gång på gång trakasserat Hordens expedition och prövat Hammerfalls försvarares beslutsamhet. Fel ställer enkla krav på uppdraget: krigarna förväntas återvända framgångsrika, i kropp eller med hedern i behåll, och han lovar beröm för ren och skär uthållighet i strid."},{t="Hotet från Boulderfist",b="Boulderfist-klanen har befäst ett näste sydväst om Hammerfall och utvidgar sitt territorium mot den väldiga dvärgbron som förbinder Arathi med Wetlands. Ogrerna är inte odisciplinerade bestar. De behärskar både förkrossande fysisk styrka och dödlig mystisk konst, och ställer upp tåliga bestar sida vid sida med listiga magi. Deras aggressiva närvaro utmanar direkt Hordens försörjningslinjer och regionala dominans. Genom att beordra att tio Boulderfist-brutaler och fyra magi ska dödas vill Drum Fel hejda deras styrka och se till att Boulderfist förstår att Hammerfalls krigare varken tänker ge upp mark eller tåla rivaler i Arathi."}},faq={{q="Vem ger uppdraget Call to Arms?",a="Uppdraget erbjuds av Drum Fel, en officer stationerad i Hordens befästa utpost Hammerfall i nordöstra Arathi Highlands. För att skydda fästets utsatta position ger Fel beprövade kämpar i uppdrag att slå till mot farliga fiender i regionen och visa sin kampdisciplin och råstyrka.",al={"vem ger uppdraget call to arms","drum fel uppdrag","uppdragsgivare för call to arms"}},{q="Var ligger Boulderfists näste?",a="Boulderfist-ogrilägret ligger sydväst om Hammerfall, längs vägen mot Thandol Span, den stora dvärgbron till Wetlands. Ogrerna håller till i jordhålor och jordhögar i höglandet, där både deras närstridskämpar och magiker samlas i stort antal.",al={"boulderfists plats","var finns ogrerna","boulderfists näste i arathi"}},{q="Vilka fiender måste besegras för uppdraget?",a="Drum Fel säger åt krigarna att döda tio Boulderfist Brutes och fyra Boulderfist Magi innan de återvänder till Hammerfall. Brutalerna förlitar sig på tunga närstridsangrepp, medan magi understödjer dem på avstånd med magiska besvärjelser. Därför är de betydligt farligare än vanliga vägskärmytslare i Arathi.",al={"antal fiender i call to arms","vilka ogre ska dödas","mål för call to arms"}},{q="Varför är Boulderfist-ogrerna ett hot mot Hammerfall?",a="Boulderfist har befäst ett fäste i Arathi och har gång på gång utmanat Hordens garnison i Hammerfall. Närheten till viktiga färdvägar mot den södra dvärgbron hotar Hordens spaning och försörjningslinjer. Drum Fel ser dem som en verklig rivaliserande styrka som måste hållas tillbaka med regelbundna anfall.",al={"varför strida mot boulderfist","är boulderfist fientliga mot horden","ogrehot i arathi"}},{q="Vad menar Drum Fel med att återvända i kropp eller ande?",a="Drum Fels bisterhet speglar Hordens kompromisslösa krigarideal i Arathi. Han förväntar sig att hans kämpar ska lyckas och återvända levande, men respekterar den som stupar medan han tappert strider mot mäktiga fiender. I hans ögon ger uthållighet och oräddhet inför ogrernas överväldigande styrka ära, oavsett om man överlever den blodiga drabbningen.",al={"drum fels citat","betydelsen av att återvända i anden","återvända i kropp eller ande"}},{q="Kan alliansspelare utföra det här uppdraget?",a="Nej, Call to Arms är ett uppdrag enbart för Horden, utdelat av Drum Fel i Hammerfall. Alliansens styrkor utgår från Refuge Pointe i väster och ser både Hammerfalls försvarare och Boulderfist-ogrerna som fientliga fiender som tävlar om herraväldet över Arathi Highlands.",al={"är call to arms bara för horden","alliansens call to arms i arathi","kan alliansen göra uppdraget"}},{q="Varför riktar Drum Fel in sig på både brutalare och magi?",a="Genom att angripa båda sorters ogre neutraliseras Boulderfists taktiska fördel med kombinerade styrkor. Brutalerna utgör den muskulösa frontlinjen som tar emot slagen, medan magi använder förödande magi från bakre ledet. Om båda typerna besegras kan klanen inte organisera en motoffensiv mot Hammerfall.",al={"varför döda magi","boulderfist magis betydelse","boulderfist brute och magus"}}},fp="12,131,16.330.0,22.452.0,33.184.0,38.185.0,48.185.0,64.242.0,58.230.0,42.231.0,46.249.0"}
P.entries["quest:679"] = {n="Call to Arms",s="Efter den föregående Call to Arms förklarar Drum Fel vid Hammerfall att det är dags att hugga huvudet av besten. Han skickar dig efter Boulderfist-hövdingarna och schamanerna som håller till i ruinerna av Stromgarde.",h="Efter den föregående Call to Arms förklarar Drum Fel vid Hammerfall att det är dags att hugga huvudet av...",kw={"arathi highlands","boulderfist","boulderfist-hövdingar","boulderfist-schamaner","drum fel","hammerfall","stromgarde"},sec={{t="Bestens huvud",b="Drum Fel säger att du har visat dig tillräckligt duglig för att hjälpa till att utdela ett sista stort slag. De som leder attackerna har slagit läger i ruinerna av Stromgarde, som han kallar en symbol för människornas svaghet. Jaga rätt på Boulderfist-hövdingarna och schamanerna som tjänar dem, för de tänker försöka driva bort Horde från dessa marker."}},faq={{q="Vem skickar dig för att strida mot Boulderfist-ledarna?",a="Drum Fel vid Hordens utpost Hammerfall i Arathi Highlands.",al={"vem ger call to arms","drum fel-uppdrag","vem startar call to arms 3"}},{q="Var finns Boulderfist-hövdingarna och schamanerna?",a="Drum Fel säger att de som leder attackerna håller till i ruinerna av Stromgarde.",al={"var finns boulderfist-hövdingarna","boulderfist-schamanernas plats","var hittar man ogreledare"}},{q="Var passar det här steget in i kedjan?",a="Det följer efter den föregående Call to Arms och är det sista steget i kedjan som börjar med Tallow i Tarren Mill.",al={"vad kom före call to arms 3","call to arms-kedjan","ogrekedjan i hammerfall"}},{q="Vad vill Drum Fel att du gör med Boulderfist-ledarna?",a="Han vill att hövdingarna och schamanerna som leder attackerna dödas i ett sista stort slag, eftersom de skulle driva bort Horde från dessa marker.",al={"varför döda boulderfist-hövdingarna","varför anfalla ogres i stromgarde"}}},fp="12,157,21.304.0,47.78.0,51.105.0,40.112.0,56.138.0"}
P.entries["quest:68"] = {n="The Legend of Stalvan",s="Den här undersökningen blottlägger ett bortglömt kapitel i Stalvan Mistmantles mörka historia. Ett dammigt, oskickat brev från en försummad kista i Moonbrook visar var han bodde innan spåren efter honom kallnade och ledde tillbaka till Darkshires arkiv.",h="Den här undersökningen blottlägger ett bortglömt kapitel i Stalvan Mistmantles mörka historia.",kw={"clerk daltry","curse of stalvan","darkshire","duskwood","a dusty unsent letter","kista","forlorn spirit","mistmantle","moonbrook","stalvan"},ang={["class:Mage"]="Skuggan som vaktar kistan använder förrädiska magiska knep som förvandlingar och en förlamande förbannelse. Det antyder att onaturliga krafter lämnat sina spår efter Stalvan.",["class:Priest"]="Att en Forlorn Spirit hemsöker en enkel kista med minnessaker vittnar om en plågsam sorg som inte fick ro ens efter döden.",["faction:Alliance"]="När du nystar upp mysteriet kring Stalvan Mistmantle hjälper du den hårt prövade staden Darkshire att kartlägga de skuggfigurer som tagit sig över traktens gränser."},sec={{t="Ett bortglömt spår i Moonbrook",b="När du söker efter Stalvan Mistmantles historia ger en gammal kista i Moonbrook en viktig pusselbit: ett dammigt, oskickat brev. Moonbrook var en gång en blomstrande jordbruksbygd, men föll i ruiner och vimlar nu av laglösa och rastlösa vålnader. Stalvans vistelse här var kort nog för att falla ur det allmänna minnet, men det försummade brevet bekräftar att han var i byn."},{t="En hemsökelse vid kistan",b="Det går inte obemärkt förbi när du undersöker Stalvans tillhörigheter. När du rör vid kistan väcks en Forlorn Spirit ur skuggorna, fast besluten att vakta hemligheterna som lämnats kvar. Vålnaden går till angrepp med förhäxande magi och den försvagande Curse of Stalvan, vilket antyder att sorg och mörk förtrollning tynger mannens kvarlämnade ägodelar, vad som än hände honom."},{t="Uppdatera stadsregistret",b="När du för brevet över gränsen tillbaka till Darkshire får Clerk Daltry de saknade handlingarna han behöver. Daltry tycker att det är märkligt att brevet aldrig skickades, men bevisen är obestridliga. Nu när kopplingen till Moonbrook är bekräftad kan den byråkratiska papperskedjan äntligen leda undersökningen vidare till platsen dit Stalvan flydde."}},faq={{q="Vad finns i den gamla kistan i Moonbrook?",a="I kistan ligger ett A Dusty Unsent Letter, skrivet under Stalvan Mistmantles vistelse i Moonbrook. Det är ett konkret bevis på att han bodde i byn innan han försvann.",al={"vad hittade jag","innehåll i kistan","stalvans brev"}},{q="Varför anfaller en ande när kistan öppnas?",a="En Forlorn Spirit dröjer sig kvar vid Stalvans bortglömda ägodelar och går till angrepp mot alla som rör vid kistan. Den använder oroväckande magi, bland annat skräckbesvärjelser, förvandlingar och den kvardröjande Curse of Stalvan.",al={"forlorn spirit","varför blir jag anfallen","spöke vid kistan"}},{q="Varför ska brevet lämnas till Clerk Daltry?",a="Clerk Daltry ansvarar för Darkshires stadsarkiv och register i stadshuset. Han behöver konkreta handlingar som bekräftar var Stalvan tidigare befunnit sig innan han kan hjälpa dig att spåra honom vidare.",al={"vem är clerk daltry","varför daltry","darkshire town hall"}},{q="Varför är det betydelsefullt att brevet aldrig skickades?",a="Att brevet låg undangömt och övergivet i en bortglömd kista kan tyda på en hastig flykt eller växande paranoia och förstärker den kusliga hemlighetsfullheten kring Stalvans rörelser.",al={"mysteriet med det oskickade brevet","varför skickades det inte"}},{q="Vad gör Curse of Stalvan?",a="Curse of Stalvan är en försvagande förbannelse som sänker offrets alla primära attribut i tio minuter. Den läggs av Forlorn Spirit, som vaktar kistan.",al={"förbannelsen curse of stalvan","ande förbannelse"}},{q="Vart leder spåret efter att brevet lämnats till Daltry?",a="När Clerk Daltry uppdaterar stadsregistret med beviset från Moonbrook kan han visa dig vart Stalvan sedan tros ha tagit vägen.",al={"vad händer sedan","vart efter daltry","nästa ledtråd"}}},fp="21,187,30.276.0,28.225.1,26.268.0,47.139.0,50.185.0,36.143.0,53.154.0,34.127.0,60.111.0"}
P.entries["quest:680"] = {n="The Real Threat",s="Efter Call to Arms berättar Korin Fel att hennes make inte vet varför Hammerfall attackeras, och ber dig döda ogret Or'Kalar och ta med hans huvud till henne.",h="Efter Call to Arms berättar Korin Fel att hennes make inte vet varför Hammerfall attackeras, och ber dig döda...",kw={"arathi highlands","hammerfall","korin fel","mug'thol","or'kalar","stromgarde","the tower of arathor"},sec={{t="En oförrätt mot hennes make",b="Korin Fel säger att du tjänar hennes make väl, men att han inte har någon aning om varför Hammerfall attackeras. Orsaken är Or'Kalar, Mug'thols bricka i Stromgarde, som hatar hennes make för att han besegrade honom för flera år sedan och vill se honom död. Hennes spådomar säger att ogret har gillrat en fälla åt honom."},{t="Vad Korin döljer",b="Korin har dolt tecknen på ogrets närvaro för sin make, eftersom hon tror att han skulle rusa iväg oförsiktigt om han visste var Or'Kalar finns. I stället ber hon om din hjälp. Du hittar Or'Kalar nära The Tower of Arathor, och hon väntar sig att hans död ska få attackerna mot Hammerfall att upphöra."}},faq={{q="Vem försöker Korin Fel skydda?",a="Sin make. Hennes spådomar säger att Or'Kalar har gillrat en fälla åt honom, och ogret vill se honom död för att han besegrade det för flera år sedan.",al={"korins make","varför behöver korin hjälp"}},{q="Varför attackerar Or'Kalar Hammerfall?",a="Korin Fel kallar Or'Kalar för Mug'thols bricka i Stromgarde, fylld av hat mot hennes make, som besegrade honom för flera år sedan. Hon säger att hans död skulle få attackerna att upphöra.",al={"varför hatar or'kalar korins make","vem är or'kalar","or'kalars motiv"}},{q="Var finns Or'Kalar?",a="Korin Fel säger att han finns nära The Tower of Arathor.",al={"or'kalars plats","var hittar man or'kalar","hitta or'kalar"}},{q="Varför håller Korin hotet hemligt för sin make?",a="Hon är rädd att han skulle rusa iväg oförsiktigt om han fick veta var ogret finns, så hon har hindrat honom från att se några spår av Or'Kalar.",al={"varför hålla det hemligt","varför dölja or'kalar","korins hemlighet"}}},fp="15,98,28.274.0,16.266.0,35.158.0,37.171.0,26.30.0,57.135.0"}
P.entries["quest:681"] = {n="Northfold Manor",s="Captain Nials vid Refuge Pointe ber om hjälp mot Syndicate, som håller Northfold Manor. Deras kontroll över landet mellan Stromgardes försvarare och Southshore gör det svårt för förnödenheter att nå fram.",h="Captain Nials vid Refuge Pointe ber om hjälp mot Syndicate, som håller Northfold Manor.",kw={"captain nials","landsvägsrövare","legosoldat","northfold manor","refuge pointe","southshore","stromgarde","syndicate"},sec={{t="Ett hårt pressat försvar",b="Stromgarde har delats upp mellan ogres, Syndicate och Alliance, och varje fraktion strider mot de andra till ett blodigt dödläge. Alliances styrkor minskar medan fienderna växer sig starkare. Försvararna behöver hjälp från Southshore, men förnödenheterna kommer fram långsamt."},{t="Syndicate vid herrgården",b="Syndicate håller marken mellan försvararna och Southshore. Captain Nials vill att du beger dig till deras bas vid Northfold Manor och dödar deras landsvägsrövare och legosoldater, i hopp om att trycket på försörjningstransporterna ska lätta så att fler kommer fram."}},faq={{q="Varför vill Captain Nials att Syndicate angrips vid Northfold Manor?",a="Hjälpen måste komma från Southshore, men Syndicate håller marken mellan orten och försvararna. Nials hoppas att det ska lätta på trycket mot försörjningstransporterna om du dödar dem vid deras bas.",al={"varför angripa northfold manor","nials mål","syftet med uppdraget vid northfold manor"}},{q="Hur ser läget ut i Stromgarde?",a="Ogres, Syndicate och Alliance har delat upp den en gång så mäktiga staden mellan sig, och varje fraktion strider mot de andra till ett blodigt dödläge. Alliances styrkor minskar medan fienderna växer sig starkare.",al={"stromgardes krigsläge","vem kontrollerar stromgarde","läget i stromgarde"}},{q="Varifrån kommer Alliances förnödenheter?",a="Försvararna hoppas få hjälp från staden Southshore, men Syndicates kontroll över marken däremellan gör det svårt att få fram förnödenheterna.",al={"vem förser refuge pointe med förnödenheter","förnödenheter från southshore","varifrån kommer leveranserna"}},{q="Vilka fiender måste elimineras vid herrgården?",a="Tio Syndicate Highwaymen och sex Syndicate Mercenaries, som finns vid Northfold Manor.",al={"vem ska dödas vid northfold","måltavlor vid northfold","lista över syndicates fiender"}}},fp="15,162,20.224.0,26.254.0,70.163.0,44.162.0,44.124.0,49.74.0"}
P.entries["quest:682"] = {n="Stromgarde Badges",s="I Stromgarde slåss Syndicate mot en grupp milismän, och dess ledare betalar guld för varje bricka som tas från en fallen milisman. I Refuge Pointe vill Captain Nials ha tillbaka brickorna.",h="I Stromgarde slåss Syndicate mot en grupp milismän, och dess ledare betalar guld för varje bricka som tas...",kw={"arathi","brickor","captain nials","milis","refuge pointe","stromgarde","syndicate"},sec={{t="En belöning för soldater",b="I Stromgarde ligger Syndicate i krig med en grupp milismän. För att få sina anhängare att slåss mot de bättre tränade soldaterna betalar Syndicates ledare guld för varje bricka som tas från en dödad milisman. Captain Nials kallar dem mördare och tänker inte låta dem behålla troféer från de modiga fallna, så du skickas till den del av Stromgarde som kontrolleras av Syndicate för att leta efter brickorna och föra dem tillbaka till Refuge Pointe. Nials vill att Syndicate ska lära sig att de inte kan tjäna på de döda."},{t="Efter jakten",b="Nials lovar att de fallnas anhöriga ska få veta att de dog i strid. Det är tungt att lämna sådana besked, men Nials tycker att det är bättre än att låta en familj undra vad som hänt med en försvunnen anhörig."}},faq={{q="Varför vill Syndicate ha Stromgarde-brickor?",a="Deras ledare har utlyst en belöning på milismännen: guld för varje bricka som tas från en fallen milisman. Syftet är att få Syndicates anhängare att slåss mot de bättre tränade trupperna.",al={"varför syndicate-brickor","syndicates belöning stromgarde","varför samla brickor"}},{q="Var hittar man brickorna?",a="Captain Nials skickar dig till den del av Stromgarde som Syndicate kontrollerar för att leta efter brickorna.",al={"var hittar man brickor","stromgarde-brickornas plats","var brickor släpps"}},{q="Vem beordrar att brickorna ska hämtas?",a="Captain Nials i Refuge Pointe vill inte att Syndicate ska behålla troféer från den fallna milisen.",al={"vem ger stromgarde-brickor","captain nials brickuppdrag","uppdragsgivare stromgarde-brickor"}}},fp="17,132,20.450.0,14.215.1,46.161.0,27.74.0,39.128.0"}
P.entries["quest:683"] = {n="Sara Balloo's Plea",s="Sara Balloo's Plea är ett sorgset ärende för en sörjande dvärgänka i Ironforge. Sara kan inte möta sin monark i sin sorg och ber därför King Magni Bronzebeard personligen om hjälp för sin fallne make, Sully Balloo.",h="Sara Balloo's Plea är ett sorgset ärende för en sörjande dvärgänka i Ironforge.",kw={"a king's tribute","dun morogh","ironforge","magni bronzebeard","sara balloo","sully balloo","thandol span"},ang={["faction:Alliance"]="Att förmedla budskap mellan sörjande invånare och Alliance-ledningen visar vilket personligt pris vanligt folk får betala i konflikterna som skyddar riket.",["race:Dwarf"]="Att överlämna en sörjande änkas vädjan direkt till din kung berör den djupa kulturella betydelse dvärgarna fäster vid stenarbete, släktled och att hedra förfädernas offer."},sec={{t="En änkas vädjan",b="Efter att ha fått det tragiska sista brevet, som bärgats ur Thandol Spans vattenfyllda djup, blir Sara Balloo lamslagen av sorg. Hon vill inte låta sin makes offer falla i glömska och skriver därför en vädjan direkt till Ironforges tron. Förkrossad av sorg kan hon inte själv infinna sig inför hovet, så hon överlämnar det förseglade pergamentet till en betrodd Alliance-mästare som ska tala med King Magni Bronzebeard för hennes räkning."},{t="Audiens hos kungen",b="Att bära en privat vädjan till High Seat i Ironforge är inget rutinärende, men Magni Bronzebeard lägger personligen märke till Khaz Modans modiga försvarare. När kungen får budskapet lägger han statsärendena åt sidan för att läsa en soldats änkas ödmjuka vädjan. Det visar hans band till de vanliga dvärgarna som byggde och försvarar hans bergsrike."}},faq={{q="Vem är Sara Balloo?",a="Sara Balloo är en dvärg från Ironforge vars make, soldaten Sully Balloo, dog i tragedin vid Thandol Span. Hon bor i staden och håller hans minne kärt.",al={"sara balloo","vem är sara"}},{q="Varför vill Sara att jag ska träffa kungen i stället för att gå själv?",a="Sara är överväldigad av sorg efter att äntligen ha fått veta vad som hände hennes make. Hon känner att hon inte kan behålla fattningen som förväntas när man vädjar till King Magni Bronzebeard vid High Seat.",al={"varför kan sara inte gå","saras sorg"}},{q="Vem var Sully Balloo?",a="Sully Balloo var en dvärgsoldat som försvarade Thandol Span. Han stupade i striderna vid bron och lämnade efter sig ett vattenskadat brev till sin hustru.",al={"sully balloo","saras make"}},{q="Var lämnar jag Sara Balloo's Plea?",a="Du lämnar vädjan direkt till King Magni Bronzebeard vid High Seat, mitt i Ironforge.",al={"var är magni","kung magnies plats","var lämnar jag in uppdraget"}},{q="Vad händer efter att King Magni läst vädjan?",a="Saras vädjan berör King Magni och får honom att hedra den fallne soldaten ordentligt. Det leder direkt vidare till uppdraget 'A King's Tribute', där ett bestående monument ska resas.",al={"fortsättning på uppdraget","nästa uppdrag"}},{q="Vilken fraktion kan utföra uppdraget?",a="Det här ärendet är endast tillgängligt för medlemmar i Alliance, eftersom det rör dvärgarnas egna angelägenheter och en audiens med King Magni Bronzebeard.",al={"kan horden göra det här","fraktionskrav"}}},fx={ca82ce02={q="Varför vill Sara Balloo att hennes vädjan ska överlämnas till King Magni?",a="Sara Balloo sörjer sin make Sully Balloo, som stupade när han försvarade Thandol Span. Nu när hon äntligen har fått hans sista brev, som hittades under bron, vill hon att King Magni Bronzebeard formellt erkänner Sullys offer och hedrar hans minne. Genom att överlämna vädjan ser hon till att hennes avlidne makes hängivenhet till Alliansen blir ihågkommen i Ironforge.",al={"varför vill sara balloo få det här gjort","sara balloos motiv","varför skicka vädjan till magni"}}},fp="18,101,17.321.0,22.261.1,19.150.0,63.170.0,21.141.0,38.96.0,45.126.1,37.129.0"}
P.entries["quest:684"] = {n="Wanted! Marez Cowl",s="WANTED: Marez Cowl är ett alliansiskt prisjägaruppdrag mot en högt uppsatt Syndicate-agent som håller till bland ruinerna av Stromgarde. Som både inflytelserik rådgivare och mörk häxmästare som handlar med demoner utgör Cowl ett allvarligt hot mot alliansstyrkorna som försöker säkra Arathi Highlands.",h="WANTED: Marez Cowl är ett alliansiskt prisjägaruppdrag mot en högt uppsatt Syndicate-agent som håller till...",kw={"arathi highlands","belöning","captain nials","marez cowl","refuge pointe","stromgarde","syndicate","häxmästare"},ang={["class:Paladin"]="Som någon som öppet handlar med demoniska väsen bland ruinerna av ett forntida människorike är Cowl en skymf mot det heliga ljuset och Stromgardes försvar.",["class:Warlock"]="Marez Cowl representerar Syndicates mörkare ockulta falang och visar hur politiska renegater gärna tar till demonisk besvärjelsekonst för att utöka sitt inflytande.",["faction:Alliance"]="Alliansgarnisonen i Refuge Pointe, under Captain Nials befäl, kämpar desperat för att återta Stromgarde. Därför är högt uppsatta mål inom Syndicate, som Marez Cowl, strategiska prioriteringar."},sec={{t="Ett pris på Syndicates ledarskap",b="WANTED: Marez Cowl är en alliansisk prisförklaring med målet att röja en av Syndicates viktigaste ledargestalter ur vägen i Arathi Highlands. Marez Cowl är högt uppsatt rådgivare och fältagent inom organisationen och styr deras verksamhet i Stromgardes ruinstad. Genom att sätta ett pris på hennes huvud hoppas alliansens befälhavare i Refuge Pointe slå ut Syndicates lokala ledningsstruktur."},{t="Häxmästaren i Stromgarde",b="Till skillnad från Syndicates vanliga banditer och egendomslösa adelsmän ägnar sig Marez Cowl åt mörk magi. Hon är känd som en listig häxmästare som öppet handlar med demoniska krafter för att genomdriva sin vilja och försvara Syndicates område. Den som närmar sig hennes håla i Stromgarde måste konfrontera både mördare och konspiratörer, och de fasansfulla väsen hon befaller."}},faq={{q="Vem är Marez Cowl?",a="Marez Cowl är en högt uppsatt agent och rådgivare inom Syndicate. Hon är långt ifrån en enkel fotsoldat och har stort inflytande i den kriminella organisationen. Hon är känd som en listig och farlig häxmästare som handlar med demoniska krafter.",al={"vem är marez cowl","marez cowls bakgrund","vem är hon"}},{q="Var finns Marez Cowl?",a="Marez Cowl håller till i den del av den förstörda staden Stromgarde som kontrolleras av Syndicate, i Arathi Highlands. Den som jagar henne måste ta sig genom djupt rotade kriminella styrkor för att hitta hennes helgedom.",al={"var hittar man marez cowl","marez cowls plats","var är marez"}},{q="Vem satte ett pris på Marez Cowl?",a="Belöningen erbjuds på uppdrag av alliansens militära styrkor i Arathi Highlands. Den övervakas av Captain Nials, som för befälet över alliansens fäste i Refuge Pointe.",al={"vem satte ett pris på marez cowl","vem vill se marez cowl död","vem betalar belöningen"}},{q="Varför är det ett pris på hennes huvud?",a="Hon är efterlyst på grund av sin centrala ledarroll i Syndicate och sitt aktiva bruk av demonisk besvärjelsekonst i Stromgarde. Hennes närvaro utgör ett omedelbart hot mot alliansgarnisonen, som kämpar för att återta det förstörda kungariket.",al={"varför är marez cowl efterlyst","varför finns det en belöning för marez cowl","varför döda marez cowl"}},{q="Vilken sorts magi använder Marez Cowl?",a="Marez är inte bara en politisk konspiratör; hon är en skicklig häxmästare som aktivt tillkallar demoner och ingår avtal med dem. Jägare varnas uttryckligen för att vara ytterst försiktiga när de möter henne och hennes demoniska hantlangare.",al={"vad gör marez cowl farlig","marez cowls krafter","är marez cowl stark"}},{q="Var lämnar du in belöningen för Marez Cowl?",a="När Marez Cowl har dödats måste hennes huvud lämnas direkt till Captain Nials i Refuge Pointe, den främsta alliansiska utposten i Arathi Highlands.",al={"var lämnar man in belöningen för marez cowl","var finns captain nials","lämna in marez cowls huvud"}}},fp="18,142,31.242.0,25.262.0,18.155.0,28.184.0,36.147.0,34.171.0,39.132.0,47.124.0"}
P.entries["quest:685"] = {n="Wanted! Otto and Falconcrest",s="En efterlysning från Stromgarde Militia sätter en belöning på Lord Falconcrest, ledaren för de lokala Syndicate-styrkorna, och hans dödliga livvakt Otto. Att röja dem ur vägen blir ett hårt slag mot den kriminella organisationens fäste i Arathi Highlands. Bevis på att de är döda ska lämnas till Captain Nials i Refuge Pointe.",h="En efterlysning från Stromgarde Militia sätter en belöning på Lord Falconcrest, ledaren för de lokala...",kw={"arathi highlands","belöning","captain nials","falconcrest","otto","refuge pointe","stromgarde militia","syndicate"},ang={["faction:Alliance"]="Lord Falconcrest och hans Syndicate-agenter hotar resterna av Stromgarde. Den här belöningen är därför avgörande för att säkra Refuge Pointe och återta höglandet.",["race:Human"]="För Stromgardes försvarare är kampen mot de förrädiska människoadelsmännen i Syndicate personlig. De vill hämnas sitt fallna kungarike."},sec={{t="En desperat belöning",b="Stromgarde Militia har utfärdat en officiell efterlysning av två nyckelpersoner i Arathi Highlands: Lord Falconcrest och hans våldsamma livvakt Otto. Stromgardes hårt ansatta försvarare, som är stationerade i Refuge Pointe, försöker bryta Syndicates grepp om sina förfäders land. Jägare måste ta med båda måltavlornas huvuden till Captain Nials för att få belöningen."},{t="Befälhavare och bödel",b="Lord Falconcrest är hjärnan bakom Syndicates samordnade framryckning in i Arathi Highlands. Hans död skulle innebära en viktig strategisk seger för Alliansen och kraftigt störa den kriminella nätverkets verksamhet i regionen. Vid hans sida står Otto, en brutalt effektiv livvakt vars klingor redan har fällt dussintals av Stromgardes kvarvarande milissoldater."}},faq={{q="Vem är Lord Falconcrest?",a="Lord Falconcrest är en adelsman och befälhavare som leder Syndicates verksamhet i Arathi Highlands. Hans närvaro samordnar deras hänsynslösa försök att ta det sönderslagna kungariket Stromgarde, vilket gör honom till ett huvudmål för den lokala människomilisen.",al={"vem är lord falconcrest","falconcrests bakgrund","vem är falconcrest"}},{q="Vem är Otto?",a="Otto är Lord Falconcrests dödliga personliga livvakt. Han är ingen strateg som sin herre, men en våldsam kämpe som har dödat dussintals av Stromgardes försvarare i höglandet.",al={"vem är otto","falconcrests livvakt","otto och syndicate"}},{q="Varför har Stromgarde Militia satt en belöning på dem?",a="Stromgarde Militia satte en belöning på dem för att slå ut Syndicates ledning i Arathi Highlands. Om Falconcrest röjs ur vägen slås deras regionala befälsstruktur sönder, medan Otto utgör ett dödligt hot som har slaktat många av Alliansens kämpar.",al={"varför belöning på falconcrest","varför döda otto och falconcrest","stromgardes belöning"}},{q="Vem betalar ut belöningen för Otto och Falconcrest?",a="Belöningarna för både Lord Falconcrest och Otto hämtas hos Captain Nials, en officer i Stromgarde Militia som är stationerad i Refuge Pointe i Arathi Highlands.",al={"var lämnar man in otto och falconcrest","vem är captain nials","var lämnar man in falconcrests belöning"}},{q="Vad gör Syndicate i Arathi Highlands?",a="Syndicate består av fallna adelsmän från Alterac och laglösa som vill lägga beslag på mark och rikedomar medan norra Lordaeron faller samman. I Arathi Highlands har de tagit sig in i Stromgardes ruiner för att rycka kontrollen från kungarikets överlevande försvarare.",al={"vad är syndicate i arathi","syndicates roll i arathi"}},{q="Vilka bevis krävs för att få belöningen?",a="För att få belöningen måste jägare ta med de avhuggna huvudena från både Lord Falconcrest och Otto direkt till Captain Nials i Refuge Pointe som obestridliga bevis på att de är döda.",al={"vart tar man ottos huvud","bevis för belöningen"}}},fp="28,291,18.246.0,22.253.0,24.212.0,12.163.0,55.236.0,47.146.0,52.243.0,43.121.0"}
P.entries["quest:686"] = {n="A King's Tribute",s="A King's Tribute är ett Alliance-uppdrag som King Magni Bronzebeard erbjuder i High Seat i Ironforge. Djupt rörd av Sara Balloos sorg över att hennes make Sully stupade när han försvarade Thandol Span, beslutar kungen att hedra den fallne soldaten med ett bestående monument. Han skickar The Adventurer för att överlämna sitt kungliga uppdrag till Grand Mason Marblesten.",h="A King's Tribute är ett Alliance-uppdrag som King Magni Bronzebeard erbjuder i High Seat i Ironforge.",kw={"ironforge","magni bronzebeard","marblesten","minnesmärke","sara balloo","sully balloo","thandol span"},ang={["faction:Alliance"]="De fallna vid Thandol Span gav sina liv när de försvarade viktiga försörjningsleder mellan Khaz Modan och de norra kungarikena åt Alliance.",["race:Dwarf"]="Uppdraget visar King Magnis hängivenhet till sitt folk och att tronen minns även den allra enklaste dvärgfotsoldaten."},sec={{t="En härskares börda",b="När King Magni Bronzebeard får höra Sara Balloos vädjan avfärdar han inte den sörjande änkan. Han förstår att vanligt folk kan ha svårt att begripa krigets brutala nödvändighet, men förlusten av varje soldat som kämpar under Alliances fana tynger hans samvete. Magni kan inte ändra frontlinjens obevekliga slut, döden, men han ser till att Sully Balloos offer aldrig glöms."},{t="Stenhuggarens mejsel",b="I stället för att komma med tomma trösteord beslutar kungen att resa ett fysiskt minnesmärke till Sullys ära. Han utser The Adventurer till förvaltare av sin kungliga vilja och skickar denne genom Ironforge för att tala med Grand Mason Marblesten. Stenhuggarmästaren får kungens personliga uppdrag och förbereder sig på att hugga in minnet av en fallen försvarare i sten."}},faq={{q="Vem var Sully Balloo?",a="Sully Balloo var en dvärgsoldat som miste livet när han stred för Alliance under försvaret av Thandol Span. Hans änka, Sara Balloo, vädjade till King Magni Bronzebeard när hon fick veta att han hade dött.",al={"vem är sully","sully balloo bakgrund","vem stupade"}},{q="Varför beställer King Magni ett minnesmärke?",a="King Magni bär tyngden av varje dvärgliv som gått förlorat i Alliances pågående strider. Han kan inte återföra Sully till hans änka, men vill hedra soldatens mod med ett bestående kungligt monument.",al={"varför bygga minnesmärke","magnis motiv","syftet med kungens hyllning"}},{q="Vem är Grand Mason Marblesten?",a="Grand Mason Marblesten är Ironforges främste stenhuggare och ansvarar för stadens stora offentliga och kungliga byggprojekt. King Magni förlitar sig på honom för att hugga Sully Balloos minnesmärke.",al={"vem är marblesten","stormurarens roll"}},{q="Var utspelar sig uppdraget?",a="Uppdraget utspelar sig helt och hållet i Ironforge. Det börjar i High Seat hos King Magni Bronzebeard och leder vidare till Grand Mason Marblesten på en annan plats i huvudstaden.",al={"var utspelar sig uppdraget","uppdragets plats"}},{q="Vad händer före det här uppdraget?",a="Innan The Adventurer kan ta emot uppdraget måste hen slutföra 'Sara Balloo's Plea' och överlämna änkans innerliga brev direkt till King Magni Bronzebeard.",al={"förkunskapskrav","föregående uppdrag"}},{q="Är minnesmärket bara tillägnat Sully Balloo?",a="Minnesmärket beställs uttryckligen till Sully Balloos ära för att trösta hans änka Sara, men hyllningen symboliserar kungens vördnad för alla dvärgkrigare som stupar i Alliances tjänst.",al={"vem hedras","är det bara för sully"}}},fx={["66401eff"]={q="Varför väljer King Magni dig som förvaltare av tributgåvan?",a="Du var den som bar Sara Balloos innerliga vädjan direkt till High Seat och förde hennes personliga tragedi inför tronen. Eftersom du valde att lyssna till en sörjande änkas sorg och överlämna hennes ord till kungen, anförtror Magni dig uppdraget att se till att den kungliga hedersbevisningen genomförs. Han utser dig till sin uppdragsförvaltare i stället för att delegera det till palatsets tjänstemän.",al={"varför jag kungens tributgåva","varför skickar magni dig","varför välja mig"}}},fp="16,177,20.284.0,18.284.0,21.176.0,42.190.0,30.203.0,33.149.0,29.91.0,39.146.0"}
P.entries["quest:687"] = {n="Theldurin the Lost",s="En medlem av Twilight's Hammer ber dig hitta Theldurin the Lost, som en gång tillhörde deras orden, förlorade förståndet och flydde med Scroll of Myzrael. Rykten säger att han finns i Badlands.",h="En medlem av Twilight's Hammer ber dig hitta Theldurin the Lost, som en gång tillhörde deras orden, förlorade...",kw={"badlands","gerrig bonegrip","myzrael","scroll of myzrael","theldurin","theldurin the lost","twilight's hammer","zaruk"},sec={{t="Mannen som stal skriftrullen",b="Theldurin tillhörde en gång Twilight's Hammer, tills han förlorade förståndet och vände ryggen åt ordens lära. När han flydde tog han med sig Scroll of Myzrael. De han lämnade efter sig kunde inte fånga honom."},{t="Rykten från Badlands",b="Orden har hört att Theldurin gömmer sig i Badlands, galen och osammanhängande. Skriftrullen behövs för att Lady ska återvända, och för att få tag på den måste du först hitta mannen som tog den."}},faq={{q="Vem är Theldurin the Lost?",a="En före detta medlem av Twilight's Hammer som förlorade förståndet, förkastade ordens lära och flydde med Scroll of Myzrael.",al={"theldurins bakgrund","vem är theldurin","theldurins berättelse"}},{q="Varför letar Twilight's Hammer efter honom?",a="Han rymde med Scroll of Myzrael, som orden säger måste hittas för att Lady ska kunna återvända.",al={"varför hitta theldurin","varför vill kultister ha theldurin"}},{q="Vart flydde Theldurin efter att ha lämnat orden?",a="Orden har bara rykten att gå på, och de säger att han finns i Badlands.",al={"var finns theldurin","theldurins plats i berättelsen"}},{q="Vad kommer direkt före den här efterforskningen?",a="Den följer på Myzrael's Allies.",al={"föregående uppdrag för theldurin","förkunskapskrav för theldurin the lost"}}},fp="18,115,28.174.0,22.184.0,26.142.0,45.140.0,49.96.0,39.36.0"}
P.entries["quest:688"] = {n="Myzrael's Allies",s="Myzrael talar genom slutstenen, förklarar att hon är fri men gömmer sig för sina fångvaktare och ber dig tala med Zaruk i Hammerfall, som vet hur hon kan tillkallas.",h="Myzrael talar genom slutstenen, förklarar att hon är fri men gömmer sig för sina fångvaktare och ber dig tala...",kw={"arathi highlands","jättar","hammerfall","slutsten","myzrael","zaruk"},sec={{t="Fri men gömd",b="Myzrael ropar att hon är fri. Just nu måste hon samla kraft utom synhåll för sina fångvaktare, för om de mötte henne i dag skulle de övermanna och fängsla henne igen. Med tiden svär hon att hon ska konfrontera jättarna som höll henne fången, och de kommer att ångra att de höll henne kvar."},{t="Zaruk i Hammerfall",b="Myzrael kallar dig en ädel allierad och säger att hon kommer att behöva din hjälp igen med tiden. När hon är redo ska hon låta dig tillkalla henne till ytan. Just nu skickar hon dig till Zaruk i Hammerfall, som vet hur det går till."}},faq={{q="Vem skickar dig till Zaruk?",a="Myzrael själv talar genom slutstenen och säger åt dig att söka upp Zaruk i Hammerfall.",al={"vem ger myzraels allierade","uppdragsgivare myzraels allierade","vem talar genom slutstenen"}},{q="Varför gömmer sig Myzrael?",a="Hon säger att hennes fångvaktare skulle övermanna och fängsla henne igen om de mötte henne nu, så hon gömmer sig medan hon samlar kraft.",al={"varför slåss inte myzrael","varför är myzrael svag","varför gömmer sig myzrael"}},{q="Var kan Zaruk hittas?",a="I Hammerfall.",al={"zaruks plats","var finns zaruk","hitta zaruk"}},{q="Vilken roll spelar Zaruk för Myzrael?",a="Myzrael säger att han vet hur hon kan tillkallas.",al={"varför tala med zaruk","vad vet zaruk","zaruks uppgift"}}},fp="16,157,15.260.0,19.211.0,23.85.0,22.122.0,25.33.0,38.49.0"}
P.entries["quest:689"] = {n="A King's Tribute",s="King Magni Bronzebeard har beställt ett monument över Sully Balloo, en dvärgisk soldat som omkom när han försvarade Thandol Span. För att hedra den stupade krigaren med bestående värdighet skickar Grand Mason Marblesten resenärer till Hillsbrad för att hämta felfri Alterac Granite.",h="King Magni Bronzebeard har beställt ett monument över Sully Balloo, en dvärgisk soldat som omkom när han...",kw={"alterac granite","darrow hill","ironforge","magni bronzebeard","marblesten","stenhuggare","sully balloo","thandol span"},ang={["faction:Alliance"]="Att säkra material från Hillsbrad stärker Alliansens närvaro i det splittrade norr och hedrar samtidigt en vanlig soldat som gav sitt liv för den gemensamma saken.",["profession:Mining"]="Gruvarbetare förstår varför Marblesten är så kräsen. De hårda, oböjliga ådrorna av Alterac Granite kräver vana händer för att kunna brytas ut utan att spricka.",["race:Dwarf"]="Att hedra Sully Balloo berör kärnan i dvärgisk kultur, där stenarbete, militär uppoffring och orubblig lojalitet mot King Bronzebeard är tätt sammanflätade."},sec={{t="Ett kungligt uppdrag",b="När King Magni Bronzebeard beslöt att den stupade soldaten Sully Balloo förtjänade ett bestående minnesmärke föll uppdraget direkt på Ironforges främsta hantverkare, Grand Mason Marblesten. Balloo miste livet under katastrofen vid Thandol Span, en viktig förbindelse mellan dvärgarnas länder och de nordliga kungadömena som utsatts för brutala angrepp av Dark Iron-sabotörer. För Marblesten innebär kungens påbud att skapa en skulptur som står emot både tid och krig, så att dvärgarnas uppoffringar varken förbises eller glöms bort i Great Forge."},{t="Nordens sten",b="En mästerlig dvärgisk stenhuggare nöjer sig inte med vanlig sten från ett stenbrott till ett kungligt projekt. Marblesten insisterar på att Sully Balloos avbild bara kan skapas i Alterac Granite, en tät och tålig sten som uppskattas för sin hållbarhet och fina struktur. Utmaningen är att få tag på den: de bästa fyndigheterna finns kring Darrow Hill i Hillsbrads omstridda förberg. Det är farligt att bege sig djupt in i det oroliga norr, men dvärgiskt stenarbete kräver material som motsvarar hjältedåden det ska föreviga."}},faq={{q="Vem är Sully Balloo?",a="Sully Balloo var en soldat i Alliansen som dog när han försvarade Thandol Span under det katastrofala sabotaget. Berörd av ett sörjande brev från hans änka, Sara Balloo, beordrade King Magni Bronzebeard att en permanent staty skulle resas till hans ära.",al={"sully balloo","vem var sully balloo","sully balloos historia"}},{q="Vem är Grand Mason Marblesten?",a="Grand Mason Marblesten är Ironforges främsta skulptör och stenarbetare. Han arbetar från stadens Commons, sköter kungliga uppdrag och är mycket stolt över att endast använda de finaste regionala stenarna.",al={"grand mason marblesten","marblesten ironforge","vem är marblesten"}},{q="Varför behövs Alterac Granite?",a="Alterac Granite är känd i hela Eastern Kingdoms för sin exceptionella täthet, fina kornighet och motståndskraft mot erosion. Marblesten insisterar på att endast sten av den här kvaliteten duger till en kunglig hyllning som ska bestå genom tiderna.",al={"varför alterac granite","alterac granites syfte","vad är alterac granite"}},{q="Var ligger Darrow Hill?",a="Darrow Hill är ett kuperat område i norra Hillsbrad Foothills, strax nedanför Headland och nära gränsen till Alterac. Alterac Granite finns i grottorna där.",al={"var ligger darrow hill","darrow hills läge","hitta darrow hill"}},{q="Vad hände vid Thandol Span?",a="Thandol Span, den väldiga bron över ravinen mellan Wetlands och Arathi Highlands, utsattes för ett angrepp av Dark Iron-sabotörer. De placerade ut sprängämnen för att skära av Alliansens försörjningsleder, och många försvarare miste livet.",al={"thandol spans tragedi","thandol spans katastrof","vad hände med thandol span"}},{q="Vad händer när graniten har lämnats till Marblesten?",a="När Marblesten har fått Alterac Granite färdigställer han minnesmärket och ber dig meddela King Magni att det är klart.",al={"efter att graniten lämnats in","marblestens statybygge"}}},fx={["1680ec58"]={q="Varför vill Grand Mason Marblesten att det här ska göras?",a="King Magni Bronzebeard har personligen beställt ett minnesmärke för att hedra den stupade soldaten Sully Balloo. För Grand Mason Marblesten har kungliga uppdrag högsta prioritet och kräver hans allra bästa arbete. Han sörjer det ständiga blodspillan över Azeroth, men insisterar på att bara använda den finaste stenen till ett verkligt storslaget och bestående minnesmärke som gör kungens beställning rättvisa.",al={"varför bryr sig marblesten","marblestens motiv","varför bygga ett minnesmärke över sully balloo"}}},fp="16,192,18.364.0,18.333.0,20.224.0,30.184.0,30.206.0,21.139.0,34.192.0,54.125.0"}
P.entries["quest:69"] = {n="The Legend of Stalvan",s="Det här ärendet markerar en avgörande vändning i sökandet efter den svårfunne Stalvan Mistmantle och leder utredarna från Duskwoods dunkel tillbaka mot kungarikets hjärta. En hastigt nedklottrad och överstruken anteckning i Darkshires stadsregister pekar över floden mot Goldshire. Nästa steg för att ta reda på vart den mystiske läraren tog vägen är att följa pappersspåren till det livliga Lion's Pride Inn.",h="Det här ärendet markerar en avgörande vändning i sökandet efter den svårfunne Stalvan Mistmantle och leder...",kw={"clerk daltry","darkshire","duskwood","elwynn forest","goldshire","innkeeper farley","lion's pride inn","stalvan"},ang={["faction:Alliance"]="Att nysta upp lokal historia och följa kalla spår genom Alliansens södra områden kräver att du tar dig mellan gränsposter som Darkshire och centrala byar som Goldshire.",["race:Human"]="När du följer Stalvans fotspår färdas du genom Stormwindrikets hjärtland och länkar samman Duskwoods hemsökta gränstrakter med Elwynn Forests välbekanta trygghet."},sec={{t="En ledtråd i registret",b="När Clerk Daltry går igenom Darkshires handlingar upptäcker han en miss i stadsregistret. Under en tidigare anteckning om Stalvan Mistmantle finns en andra destination, hastigt nedskriven och delvis överstruken, som om någon ångrat sig eller velat dölja sina förehavanden. Anteckningen visar att Stalvan tänkte resa nordväst mot Elwynn Forest, närmare bestämt till Lion's Pride Inn."},{t="In i Elwynn",b="Att lämna Duskwoods skuggiga dungar och ge sig ut på Goldshires soliga vägar är en skarp kontrast, men skuggan från Stalvans förflutna når även hit. Lion's Pride Inn är Elwynn Forests livliga knutpunkt och välkomnar både resenärer, köpmän och soldater. Innkeeper Farley styr över den välbesökta gäststugan och är den perfekta personen att fråga om en bildad vandrare som söker logi."}},faq={{q="Varför leder spåret till Goldshire?",a="Clerk Daltry upptäckte en andra, delvis överstruken adress i Darkshires register, under Stalvans första anteckning. Där stod tydligt att han var på väg till Lion's Pride Inn i Goldshire.",al={"varför goldshire","varför åka till goldshire","stalvan i goldshire"}},{q="Vem är Clerk Daltry?",a="Clerk Daltry är skrivaren i Darkshires rådhus. Han sköter de lokala registren och hjälper till att gräva fram historiska handlingar om tidigare invånare.",al={"daltry","vem är daltry"}},{q="Vem ska jag prata med på Lion's Pride Inn?",a="Du ska prata direkt med Innkeeper Farley, som sköter Lion's Pride Inn och håller reda på resenärer och gäster som passerar Goldshire.",al={"vem ska jag prata med","kontakt på lion's pride","värdshusvärd i goldshire"}},{q="Varför överströks anteckningen i registret?",a="Anteckningen i liggaren raderades bara delvis, vilket tyder på ett hastigt eller avsiktligt försök att dölja Stalvans väg mot Elwynn Forest när han lämnade Duskwood.",al={"överstruken anteckning","varför överstruken"}},{q="Innebär det här uppdraget någon strid?",a="Nej. Det här steget i utredningen handlar bara om att resa och ställa frågor. Du tar dig tryggt från Darkshires rådhus till gäststugan i Goldshire.",al={"är det strider","måste jag slåss mot något"}},{q="Vad är Lion's Pride Inn?",a="Lion's Pride Inn är Goldshires centrala mötesplats i Elwynn Forest. Det är ett välkänt viloställe för resenärer mellan Stormwind City, Westfall och Duskwood.",al={"lion's pride inn","värdshuset i goldshire"}}},fx={f40d5969={q="Varför vill Clerk Daltry att Stalvan spåras upp?",a="Som stadsskrivare i Darkshire sköter Daltry stadens handlingar och register. När Madame Eva först satte dig på spåret efter den mystiske Stalvan Mistmantle hjälpte Daltry till genom att gå igenom sina liggare. Han upptäckte en förbisedd, delvis överstruken anteckning under den första adressen och ber dig följa den nya ledtråden för att pussla ihop den gåtfulle mannens historia.",al={"varför bryr sig daltry","daltrys motiv med stalvan","varför spåra stalvan"}},["136b3a3d"]={q="Varför skickar Clerk Daltry dig till Goldshire i stället för att gå dit själv?",a="Clerk Daltry är en tjänsteman knuten till stadshuset i Darkshire. Han ansvarar för att föra register och hjälpa lokalbefolkningen i en bosättning som plågas av fasor. Att resa hela vägen över floden till Elwynn Forest för att förhöra värdshusvärdar ingår inte i hans uppgifter. En äventyrslysten person som du passar bättre för att följa upp avlägsna ledtrådar.",al={"varför skicka mig","varför går inte daltry själv","varför behöver daltry en äventyrare"}}},fp="21,405,20.410.0,20.404.0,37.199.0,20.172.0,42.150.0,48.160.0,35.150.0,29.176.0"}
P.entries["quest:690"] = {n="Malin's Request",s="I Stormwind ber Malin om hjälp att återfinna reliker från det fallna Stromgarde. Archmage Malin skickar erfarna äventyrare från Alliance norrut till Refuge Pointe i Arathi Highlands, där en expedition söker de magiska reliker som lämnades kvar när Stromgarde föll.",h="I Stormwind ber Malin om hjälp att återfinna reliker från det fallna Stromgarde.",kw={"arathi highlands","malin","refuge pointe","skuerto","stormwind","stromgarde","the tower of arathor","trelane","wizard's sanctum"},ang={["class:Mage"]="Som magiker på besök i Wizard's Sanctum kan du hjälpa Malin att bevara värdefull arkanisk forskning och reliker med anknytning till Arathors magiker.",["faction:Alliance"]="Som medlem i Alliance kan du hjälpa till att stärka Refuge Pointe, Alliances bräckliga kvarvarande fäste i Arathi.",["race:Human"]="Som människa kan du hjälpa till att återfinna Stromgardes skatter, den mänskliga civilisationens vagga, och bevara Arathors arv."},sec={{t="En mästares förlorade ägodelar",b="Archmage Malin tjänstgör i Stormwinds Wizard's Sanctum och företräder sin tidigare mentor, Archmage Trelane. När Stromgarde föll i kaos gjorde Trelane ett desperat motstånd vid The Tower of Arathor. När fiendestyrkor intog staden tvingades han överge sin post och lämna kvar mäktiga förtrollade ägodelar. Malin fruktar att relikerna kan hamna i fiendehänder. Han skickar dugliga legosoldater norrut för att förstärka sina agenter på plats och återta Trelanes förlorade ägodelar."},{t="Den hårt ansatta utposten vid Refuge Pointe",b="Refuge Pointe ligger längs vägen till Trelanes reliker, mitt i Arathi Highlands. Utposten är en hårt ansatt tillflykt för Stromgardes trogna, och Malins främsta kontakt där är dvärgen Skuerto. Syndicate-banditer, Witherbark-troll och Boulderfist-ogrer pressar utposten från alla håll. När du anländer är Skuerto och garnisonen så överbelastade att de inte kan välkomna dig varmt utan omedelbar hjälp."}},faq={{q="Vem är Archmage Malin?",a="Archmage Malin är en mänsklig magiker i Stormwinds Wizard's Sanctum. Han var en gång lärling hos Archmage Trelane från Stromgarde och leder nu arbetet från Stormwind med att återfinna sin mentors magiska forskning.",al={"archmage malin","vem är malin","malin stormwind"}},{q="Varför behöver Malin hjälp i Arathi?",a="Stromgarde föll under belägring, vilket tvingade Archmage Trelane att fly från The Tower of Arathor. Malins agenter försöker återfinna Trelanes övergivna reliker, men de är övermannade och behöver förstärkning.",al={"varför bege sig till arathi","malins uppdrag syfte","varför arathi highlands"}},{q="Var finns Skuerto?",a="Skuerto är en dvärgspanare stationerad vid Refuge Pointe, ett läger för Alliance vid den stora handelsvägen genom centrala Arathi Highlands.",al={"hitta skuerto","skuertos plats","var ligger refuge pointe"}},{q="Vad hände med The Tower of Arathor?",a="The Tower of Arathor var ett arkaniskt fäste i Stromgarde. När kungariket föll försökte Archmage Trelane försvara det mot Syndicate-rövare och Boulderfist-ogrer, men försvaret bröt samman och han tvingades fly.",al={"the tower of arathors fall","vad hände med stromgarde","trelane torn"}},{q="Vad händer efter att man rapporterat till Skuerto?",a="Skuerto är överbelastad och avvisande när du anländer. Han skickar dig till sina följeslagare vid Refuge Pointe för att börja återfinna Trelanes utspridda ägodelar.",al={"uppföljning på malins begäran","nästa uppdrag efter malin","skuertos nästa uppdrag"}},{q="Vem är Archmage Trelane?",a="Archmage Trelane är en framstående magiker från Stromgarde och Archmage Malins mentor. Han var en av de främsta försvararna av Arathis huvudstad innan kungariket föll.",al={"archmage trelane","vem är trelane","trelane stromgarde"}}},fx={["5671e9ba"]={q="Varför behöver Archmage Malin en äventyrare för det här uppdraget?",a="Archmage Malin är bunden till sin tjänst i Wizard's Sanctum i Stormwind, långt söderut. Han har redan agenter stationerade vid Refuge Pointe i Arathi Highlands, men de rapporterar att läget kring den fallna staden Stromgarde är desperat och kräver förstärkning. En kringresande äventyrare kan snabbt ta sig norrut och har stridsvana nog att ge sig in i fientliga, omstridda ruiner som officiella sändebud har svårt att nå.",al={"varför skicka en äventyrare","varför jag åt malin","varför går malin inte själv"}}},fp="15,250,26.467.0,37.407.0,22.199.0,35.198.0,25.136.0,38.207.0,40.154.0,24.154.0"}
P.entries["quest:691"] = {n="Worth Its Weight in Gold",s="Vid Refuge Pointe söker Apprentice Kryten efter Witherbark-betar, medicinpåsar och en skuggjägares kniv, allt ingredienser åt Archmage Malin, som skickade honom och Skuerto för att samla in dem. Han ber dig leta efter dem bland Witherbark-trollen i sydöstra Arathi.",h="Vid Refuge Pointe söker Apprentice Kryten efter Witherbark-betar, medicinpåsar och en skuggjägares kniv, allt...",kw={"apprentice kryten","arathi highlands","archmage malin","medicinpåse","refuge pointe","skuggjägarkniv","skuerto","witherbark","witherbark-bete"},sec={{t="Malins ingredienser",b="Archmage Malin skickade Kryten och Skuerto till Arathi för att samla ingredienser, och Kryten visste inte hur han skulle hitta dem förrän du kom. Han behöver tio Witherbark-betar, fyra medicinpåsar och en skuggjägarkniv. Witherbark-trollen bor i sydöstra Arathi."},{t="Vad Witherbark bär på",b="Enligt Krytens efterforskningar bör alla Witherbark-troll ha betar, och häxdoktorerna bär på medicinpåsarna. Kniven tillhör de mäktigaste skuggjägarna och ges till dem när de har fullbordat sina övergångsriter. Bara strid kan visa vem av dem som har en."}},faq={{q="Vem arbetar Apprentice Kryten åt?",a="Archmage Malin skickade Kryten och Skuerto till Arathi för att samla ingredienser åt honom.",al={"vem skickade kryten","krytens mästare","varför är kryten i arathi"}},{q="Var finns Witherbark-trollen?",a="I sydöstra Arathi, där Witherbark-trollen bor.",al={"witherbark-plats","var hittar man witherbark","witherbark village-plats"}},{q="Vilka troll bär på medicinpåsarna?",a="Enligt Krytens efterforskningar är det Witherbark-häxdoktorerna som bär medicinpåsar, medan alla Witherbark-troll bör ha betar.",al={"källa till medicinpåse","vem har medicinpåsar","witherbark-medicinpåse"}},{q="Hur hittar du skuggjägarkniven?",a="De mäktigaste Witherbark-skuggjägarna bör ha den, ett vapen som ges till dem efter deras övergångsriter. Striden får visa vem av dem som bär på en.",al={"skuggjägarknivens plats","vem släpper skuggjägarkniven","övergångsritskniv"}}},fp="24,195,16.251.0,25.257.0,37.76.0,40.65.0,40.115.0,40.142.0"}
P.entries["quest:692"] = {n="The Lost Fragments",s="Theldurin the Lost grips av panik inför Scroll of Myzrael. Dess magi kan dra upp Myzrael till ytan, men om hon redan är fri kan skriftrullen vara det enda sättet att binda henne igen. Rasande elementaler har slitit sönder den och slåss om spillrorna, och du skickas för att samla ihop dem.",h="Theldurin the Lost grips av panik inför Scroll of Myzrael.",kw={"badlands","skrynkligt skriftrullefragment","elementaler","myzrael","scroll of myzrael","svedd skriftrullefragment","theldurin the lost","sönderrivet skriftrullefragment"},sec={{t="En farlig skriftrulle",b="Theldurin the Lost blir orolig när Scroll of Myzrael nämns, för han fruktar att dess magi kan dra Myzrael upp till ytan. Sedan ändrar han sig: om hon redan har slitit sig fri, eller samlar kraft för att slå till, är skriftrullen precis vad du behöver för att fånga henne igen."},{t="Sliten av elementen",b="Skriftrullen är inte längre hel. Rasande elementaler tog den, slet den i bitar och slåss nu om spillrorna. Du ska leta efter tre delar: en sönderriven, en skrynklad och en svedd. Theldurin tänker försöka laga dem. Tjuvarna strövar omkring i kullarna bakom Theldurin."}},faq={{q="Vem skickar dig för att samla in skriftrullens fragment?",a="Theldurin the Lost ber dig att hämta delarna av den förstörda skriftrullen.",al={"uppdragsgivare","vem ger uppdraget the lost fragments","uppdrag från theldurin"}},{q="Vad ska Scroll of Myzrael göra?",a="Theldurin säger att dess magi kan dra Myzrael upp till ytan. Theldurin tror också att den är vad du behöver för att fånga henne igen, om hon redan är fri.",al={"vad gör skriftrullen","scroll of myzrael i historien","varför hitta skriftrullens fragment"}},{q="Var finns skriftrullens fragment?",a="Rasande elementaler bar bort skriftrullen, slet sönder den och slåss om bitarna. De finns i kullarna bakom Theldurin.",al={"vem har fragmenten","var hittar man skriftrullens bitar","plats för skriftrullens fragment"}},{q="Vilket uppdrag kommer före det här?",a="Det följer på dina tidigare förehavanden med Theldurin the Lost.",al={"tidigare uppdrag","förutsättning för the lost fragments"}}},fp="18,147,21.234.0,20.209.0,46.73.0,45.150.0,31.110.0,29.57.0"}
P.entries["quest:6921"] = {n="Amongst the Ruins",s="På uppdrag av Je'neu Sancrea vid Zoram'gar Outpost söker Horde-äventyrare igenom det översvämmade templet Blackfathom Deeps efter en fathom core. The Earthen Ring söker reliken för att avslöja den invaderande kulten Twilight's Hammers mörka planer för elementen.",h="På uppdrag av Je'neu Sancrea vid Zoram'gar Outpost söker Horde-äventyrare igenom det översvämmade templet...",kw={"amongst the ruins","ashenvale","blackfathom deeps","earthen ring","fathom core","fathom-sten","je'neu sancrea","moonshrine ruins","twilight's hammer","zoram'gar outpost"},ang={["class:Shaman"]="När du hämtar fathom core hjälper du direkt The Earthen Ring att skydda vattnets och jordens andar från att kuvas av Twilight's Hammer.",["faction:Horde"]="När du röjer undan hoten i Blackfathom Deeps skyddar du Zoram'gar Outpost och säkrar Hordes omstridda fäste vid Ashenvales kust.",["race:Troll"]="När du hjälper Je'neu Sancrea bistår du en Darkspear-frände som överbryggar klyftan mellan Horde och The Earthen Rings elementvårdare."},sec={{t="Ett hot i djupet",b="Nattalvernas uråldriga tempel Blackfathom Deeps, en gång helgat åt Elune, har fallit under mörka krafters herravälde. Djupt inne i de översvämmade gångarna har kultisterna i Twilight's Hammer upprättat ett fäste. Darkspear-schamanen Je'neu Sancrea är stationerad vid den vindpinade kusten nära Zoram'gar Outpost i Ashenvale. Han ser hur fördärvet sprider sig och blir alltmer oroad. Han förstår att kulten tänker kuva de lokala elementen och vända dem mot landet och dess försvarare."},{t="Fathom-stenen",b="För att sätta stopp för kultens planer ger Je'neu Horde-hjältar i uppdrag att hämta en fathom core från fathom-stenen under vattnet i Moonshrine Ruins. Skickliga schamaner kan tyda kärnan och läsa en utförlig krönika över elementens strömmar och störningar. Med artefakten hoppas The Earthen Ring kunna genomskåda Twilight's Hammers verksamhet och skydda regionen från en elementär katastrof."}},faq={{q="Vem ger uppdraget Amongst the Ruins?",a="Uppdraget ges av Je'neu Sancrea, en troll som företräder The Earthen Ring och är stationerad vid Zoram'gar Outpost längs Zoram Strand i västra Ashenvale.",al={"uppdragsgivare","var får man uppdraget","vem startar amongst the ruins"}},{q="Vad är en fathom core?",a="En fathom core är en särskild artefakt som förvaras i en fathom-sten under vattnet i ruinerna. När schamaner läser den får de en utförlig historik över elementens aktivitet och kan se hur de lokala elementen tvingas till lydnad och manipuleras.",al={"vad är fathom core","fathom-stenens syfte","vad gör kärnan"}},{q="Varför oroar sig The Earthen Ring för Blackfathom Deeps?",a="The Earthen Ring söker balans mellan naturens element. Twilight's Hammers kultister har tagit över de översvämmade ruinerna och fördärvar och kuvar aktivt elementen för sina mörka syften. Det hotar stabiliteten i hela regionen.",al={"the earthen rings motiv","varför bryr sig the earthen ring","kultister i blackfathom deeps"}},{q="Var finns fathom-stenen?",a="Fathom-stenen ligger under vattnet i Moonshrine Ruins, inne i Blackfathom Deeps. Utforskare måste dyka under ytan för att hämta kärnan.",al={"var finns stenen","fathom cores plats","fathom core i moonshrine ruins"}},{q="Kan alliansspelare ta det här uppdraget?",a="Nej. Uppdraget är bara tillgängligt för Horde, eftersom Je'neu Sancrea verkar från Horde-utposten Zoram'gar och stöder Hordes strategiska närvaro i Ashenvale vid sidan av sina uppgifter för The Earthen Ring.",al={"bara för horde","alliansversion","kan alliansen göra amongst the ruins"}},{q="Vilken grupp håller till i Blackfathom Deeps?",a="Det väldiga grottemplet har tagits över av Twilight's Hammer, en apokalyptisk kult som tjänar mörka Old God-väsen och förvrider elementen för att orsaka katastrofer.",al={"vilka finns i blackfathom","fiender i bfd","twilight's hammer i blackfathom"}}},fx={["139b4a2b"]={q="Varför vill Je'neu Sancrea att Fathom Core hämtas?",a="Je'neu Sancrea fruktar att Twilight's Hammer-kultisterna som ockuperar Blackfathom Deeps ska tvinga de lokala elementen att vända sig mot området och Horden. Utan Fathom Core kan Earthen Ring inte se vilka ritualer kultisterna utför eller vilka elementära störningar de orsakar djupt under ruinerna.",al={"je'neu sancreas motiv","varför hämta fathom core","varför bland ruinerna"}}},fp="17,199,20.341.0,16.355.0,38.137.0,22.197.0,58.188.0,34.152.0,37.186.0,42.139.0"}
P.entries["quest:6922"] = {n="Baron Aquanis",s="När äventyrarna besegrar vattenelementaren Baron Aquanis i Blackfathom Deeps hittar de en Strange Water Globe med förorenad, stinkande vätska. Artefakten ger Je'neu Sancrea från Earthen Ring avgörande bevis för den elementära korruption som sprider sig under Ashenvale. Je'neu tror att den kan visa vad som korrumperade baronen, och han skulle inte bli förvånad om det var kultisterna i Twilight's Hammer som lurar i de översvämmade ruinerna.",h="När äventyrarna besegrar vattenelementaren Baron Aquanis i Blackfathom Deeps hittar de en Strange Water Globe...",kw={"ashenvale","baron aquanis","blackfathom deeps","earthen ring","elementär korruption","je'neu sancrea","strange water globe","twilight's hammer","the zoram strand"},ang={["class:Shaman"]="Earthen Ring ser korrumperingen av elementandar som en allvarlig kränkning av den naturliga ordningen. Undersökningen av Baron Aquanis förorenade tillstånd är central för att återställa elementens balans.",["faction:Horde"]="Je'neu Sancrea samordnar sig med hordens spejare vid Zoram'gar Outpost och söker modiga hjältar som kan rena de korrumperade vatten som döljer sig under Ashenvales kust."},sec={{t="Ett korrumperat hjärta",b="Baron Aquanis var ingen vanlig vattenande, utan en mäktig elemental som korrumperats av mörk magi i Blackfathom Deeps översvämmade grottor. När elementalen besegras lämnar den efter sig en Strange Water Globe, en oförstörbar klotformad behållare med en skvalpande, stinkande vätska som tycks ha upprätthållit och förvridit varelsens naturliga väsen. Föremålet står emot fysisk skada och rymmer energier som väcker djupt obehag hos dem som är lyhörda för elementens balans."},{t="Earthen Rings undersökningar",b="Je'neu Sancrea, en shaman från Earthen Ring som är stationerad vid The Zoram Strand, känner genast igen artefakten som bevis på onaturlig inblandning. Han och hans orden har länge misstänkt att Baron Aquanis fallit offer för mörka krafter och pekar direkt ut kultisterna i Twilight's Hammer, som håller till i det sjunkna templet. Genom att studera klotet hoppas Je'neu inte bara kunna bekräfta kultens skuld, utan också upptäcka exakt vilka mörka metoder de använder för att kuva och förvrida Azeroths elementandar."}},faq={{q="Vad är Baron Aquanis?",a="Baron Aquanis är en mäktig vattenelemental som lever i Blackfathom Deeps underjordiska vatten. Aquanis strövar inte fritt, utan har korrumperats och bundits av de mörka magiutövare som håller till i tempelruinerna.",al={"vem är aquanis","aquanis boss","baron aquanis historia"}},{q="Vad är Strange Water Globe?",a="Strange Water Globe är en oförstörbar sfär som blir kvar efter att Baron Aquanis besegrats. Inuti skvalpar en stinkande, rutten vätska som är källan till den förorenade energi som drev elementalen i dess korrumperade tillstånd.",al={"vattenklot","strange water globe","aquanis uppdragsföremål"}},{q="Varför vill Je'neu Sancrea ha klotet?",a="Som medlem av Earthen Ring håller Je'neu Sancrea uppsikt över elementära störningar i Ashenvale. Han studerar klotet för att bekräfta om Twilight's Hammer ligger bakom korruptionen och avslöja ritualerna som används för att förvrida andarna.",al={"varför lämna till jeneu","jeneu sancreas syfte"}},{q="Vem ligger bakom Baron Aquanis korruption?",a="De främsta misstänkta är kultisterna i Twilight's Hammer, som håller till djupt inne i Blackfathom Deeps. Deras närvaro i templet stämmer överens med ett försök att vanhelga platsen och ingå mörka förbund med onaturliga varelser.",al={"vem korrumperade aquanis","aquanis twilight hammer","kultister blackfathom"}},{q="Var finns Je'neu Sancrea?",a="Je'neu Sancrea är en shaman från Earthen Ring som slagit läger längs The Zoram Strand på Ashenvales nordvästra kust, nära ingången till grottsystemet Blackfathom Deeps.",al={"var finns jeneu","lämna in aquanisuppdraget","var lämnar man in vattenklotet"}},{q="Vad händer när uppdraget lämnas in?",a="När du lämnar över klotet inleds fler undersökningar av regionens elementära lidande, och äventyrarna får anledning att fortsätta hjälpa Earthen Ring mot den växande plågan.",al={"nästa uppdrag","elementärt lidande"}}},fp="13,242,17.349.0,27.391.1,22.172.0,32.194.0,39.240.0,46.219.0,32.157.0,39.157.0"}
P.entries["quest:693"] = {n="Wand over Fist",s="Skuerto vid Refuge Pointe har kommit på vart den första av Trelane's föremål hamnade. Kor'gresh har Trelane's Wand of Invocation i Boulderfist Hall, och Skuerto vill att du hämtar tillbaka den.",h="Skuerto vid Refuge Pointe har kommit på vart den första av Trelane's föremål hamnade.",kw={"arathi highlands","boulderfist hall","korgresh","refuge pointe","skuerto","stromgarde","thandol span","trelane","wand of invocation","wand over fist"},sec={{t="Ogren och trollstaven",b="Efter ditt arbete åt Apprentice Kryten har Skuerto tagit reda på vart Trelane's första föremål tog vägen. Kor'gresh har det i Boulderfist Hall och har kastat isblixtar mot sina egna för att hålla dem i schack. Skuerto tror att ogren snart måste lista ut trollstavens alla krafter. Boulderfist Hall ligger söder om Refuge Pointe och sedan öster om Thandol Span."},{t="Skuerto's lista",b="När du kommer tillbaka räknar Skuerto trollstaven som ett föremål avklarat, med tre kvar enligt sin lista. De andra tre finns alla i Stromgarde."}},faq={{q="Vem ger uppdraget Wand over Fist?",a="Skuerto, vid Refuge Pointe i Arathi Highlands.",al={"uppdragsgivare för wand over fist","vem startar wand over fist","var får man wand over fist"}},{q="Var finns Kor'gresh?",a="Kor'gresh finns i Boulderfist Hall, som ligger söder om Refuge Pointe och sedan öster om Thandol Span.",al={"var finns korgresh","korgreshs plats","hitta korgresh"}},{q="Vilket föremål måste hämtas tillbaka?",a="Trelane's Wand of Invocation, det första av Trelane's föremål. Kor'gresh har kastat isblixtar mot sina fränder med den.",al={"vilket föremål har kor'gresh","vilken trollstav","trelanes trollstav"}},{q="Vilka förkunskaper krävs för uppdraget?",a="Det följer efter Worth Its Weight in Gold, arbetet du utförde åt Apprentice Kryten.",al={"förkunskaper för wand over fist","krav för wand over fist","föregående uppdrag till wand over fist"}}},fp="14,161,21.321.0,14.123.1,35.79.0,27.87.0,32.134.0,45.91.0"}
P.entries["quest:694"] = {n="Trelane's Defenses",s="Med trollstaven i hand vänder sig Skuerto mot ogres som omringar Tower of Arathor. För att aktivera tornets försvar behöver han en azurblå agat från Boulderfist-shamanen, som ska tas till Apprentice Kryten vid Refuge Pointe.",h="Med trollstaven i hand vänder sig Skuerto mot ogres som omringar Tower of Arathor.",kw={"apprentice kryten","azurblå agat","boulderfist-shaman","refuge pointe","skuerto","stromgarde","the tower of arathor","trelanes försvar"},sec={{t="Tornets försvar",b="Ogres omringar Tower of Arathor i Stromgarde. Skuerto säger att tornets försvar måste aktiveras om du ska ha en chans mot dem och ändå nå föremålen levande."},{t="En ädelsten som nyckel",b="Vissa ädelstenar från tornet har fallit Boulderfist-shamanen i smaken, och de tog dem med sig, men Skuerto säger att de inte får behålla dem länge. Ta med en azurblå agat till Apprentice Kryten vid Refuge Pointe, som kan besvärjelsen som förtrollar den så att den fungerar som en nyckel."}},faq={{q="Varför behövs en azurblå agat?",a="Skuerto vill aktivera tornets försvar så att du kan möta ogres som omringar Tower of Arathor och ändå nå föremålen levande. Förtrollad fungerar ädelstenen som en nyckel.",al={"varför azurblå agat","syftet med trelanes försvar","varför hämta ädelstenen"}},{q="Varifrån kom de azurblå agaterna?",a="Boulderfist-shamanen tog dem från Tower of Arathor och har fattat tycke för dem.",al={"vem tog agaterna","varifrån kommer ädelstenarna","agatens ursprung"}},{q="Vem kan förtrolla ädelstenen?",a="Apprentice Kryten vid Refuge Pointe kan besvärjelsen som förtrollar ädelstenen så att den fungerar som en nyckel.",al={"vem förtrollar agaten","krytens roll","vem gör om den till en nyckel"}}},fp="18,190,20.166.0,15.257.0,29.161.0,37.99.0,24.91.0"}
P.entries["quest:695"] = {n="An Apprentice's Enchantment",s="Apprentice Kryten har förtrollat agaten du hämtade från Boulderfist-schamanen. Rör du vid en piedestal vid tornets fot väcks tornets försvar. Innan du ger dig av skickar han dig till Skuerto för resten.",h="Apprentice Kryten har förtrollat agaten du hämtade från Boulderfist-schamanen.",kw={"apprentice kryten","arathi highlands","förtrollad agat","skuerto","torn","trelane"},sec={{t="En nyckel till tornet",b="Kryten räcker dig den förtrollade ädelstenen. Han förklarar att om du rör vid en piedestal vid tornets fot väcks tornets försvar, och att du bör använda den när du är redo att gå in och hämta resten av Trelane's föremål. Han väntar på dig när du återvänder till lägret. Tala först med Skuerto, som berättar allt annat du behöver veta."}},faq={{q="Vad är den förtrollade agatens syfte?",a="Rör du vid en piedestal vid tornets fot väcks tornets försvar. Du använder den när du är redo att gå in och hämta resten av Trelane's föremål.",al={"varför behöver jag agaten","använda förtrollad agat","vad gör ädelstenen"}},{q="Vem behöver du prata med innan du lämnar lägret?",a="Skuerto. Kryten säger åt dig att prata med honom innan du ger dig av, eftersom han berättar allt annat du behöver veta.",al={"vem ska jag prata med","vart går jag härnäst","vem är skuerto"}},{q="Var kommer Kryten att vara?",a="Han väntar på att du ska återvända till lägret.",al={"var är kryten","kryten väntar"}}},fp="27,174,19.335.0,43.174.0,47.95.0,21.45.0"}
P.entries["quest:696"] = {n="Attack on the Tower",s="När tornets försvar har vaknat skickar Skuerto vid Refuge Pointe in dig i det ogrehållna tornet för att hämta Trelane's phylactery, orb och ember agate. De bör ligga i kistor där inne, och Skuerto säger att Malin blir mer än nöjd om du tar dem tillbaka.",h="När tornets försvar har vaknat skickar Skuerto vid Refuge Pointe in dig i det ogrehållna tornet för att hämta...",kw={"arathi highlands","attack on the tower","malin","ogres","refuge pointe","skuerto","trelane","trelanes ember agate","trelanes orb","trelanes phylactery"},sec={{t="In i tornet",b="Efter Kryten's förtrollning berättar Skuerto vad du ska leta efter: Trelane's phylactery, orb och ember agate. De tre bör ligga i kistor inne i tornet, och du bör kunna öppna dem utan problem, men se upp för ogres. Tornets försvar tar inte hand om dem på egen hand, och om ogres upptäcker att du stjäl från dem kommer de att göra livet surt för dig."},{t="Skuerto's dom",b="När du lämnar tillbaka de tre föremålen säger Skuerto att Malin inte kunde ha bett om en mer värdig person att hjälpa dem här. Malin blir överlycklig när de får veta hur väl deras företag har lyckats."}},faq={{q="Vem ger dig uppdraget?",a="Skuerto, vid Refuge Pointe i Arathi Highlands, efter att Kryten har förtrollat ädelstenen.",al={"vem ger attack on the tower","uppdragsgivare attack on the tower","var får man attack on the tower"}},{q="Vilka föremål ska du hämta?",a="Trelane's phylactery, orb och ember agate. Var och en bör finnas i en kista inne i tornet.",al={"föremål i attack on the tower","vilka reliker ska hämtas","trelanes föremål"}},{q="Vad kommer ogres att göra?",a="Tornets försvar tar inte hand om dem åt dig. Om ogres upptäcker att du stjäl från dem kommer de att göra livet surt för dig.",al={"är ogres farliga","tornets ogres"}},{q="Vad kommer före det här?",a="Det följer efter An Apprentice's Enchantment, där Kryten förtrollar ädelstenen och skickar dig till Skuerto.",al={"förkunskapskrav för attack on the tower","vilket uppdrag kommer först"}}},fp="19,228,14.307.0,17.194.1,22.91.0,36.111.0,23.98.0,23.95.0"}
P.entries["quest:6962"] = {n="Treats for Great-father Winter",s="Vid Smokywood Pastures feststånd i Orgrimmar är skådespelaren som spelar Greatfather Winter utmattad av att höra högtidsönskningar. Han ber dig om pepparkakor och mjölk.",h="Vid Smokywood Pastures feststånd i Orgrimmar är skådespelaren som spelar Greatfather Winter utmattad av att...",kw={"gingerbread cookie","greatfather winter","holiday spices","ice cold milk","orgrimmar","smokywood pastures","treats for great-father winter","winter veil"},ang={["faction:Horde"]="I Orgrimmar för goblinernas handelsmän från Smokywood Pastures med sig festen och en stunds hemtrevnad till krigarstaden.",["profession:Cooking"]="Som kocklärling kan du öva på enkel bakning genom att förvandla vilda ägg och säsongskryddor till festliga pepparkakor."},sec={{t="En trött vinterbesökare",b="Greatfather Winter, som hälsar besökare välkomna i Valley of Strength, arbetar för Smokywood Pastures. Långa timmar av att lyssna på invånare som talar om festliga godsaker gör honom hungrig. Han vänder sig till förbipasserande resenärer och ber om nybakat och en kall dryck."},{t="Högtidlig matglädje",b="Du kan baka kakorna med Holiday Spices som säljs av Smokywood Pastures krämare och Small Eggs som du samlar från vilda fåglar. Ta med dem tillsammans med Ice Cold Milk från en lokal krog, så bjuder festens arrangörer på högtidsstämning och en liten tacksamhetsgåva."}},faq={{q="Vem är Greatfather Winter i Orgrimmar?",a="I Orgrimmar är Greatfather Winter en skådespelare som Smokywood Pastures anlitat för att gestalta den legendariska figuren under Feast of Winter Veil. Han sitter nära högtidens handelsstånd i Valley of Strength, hälsar Horde-invånare välkomna och lyssnar på deras önskemål inför högtiden.",al={"vem är greatfather winter","greatfather winter i orgrimmar","är han den riktige greatfather winter"}},{q="Vilka godsaker ber Greatfather Winter om?",a="Han ber dig om fem Gingerbread Cookies och en portion Ice Cold Milk som hjälp under en lång dag då han hälsar högtidens besökare välkomna.",al={"vad vill han ha","önskade godsaker","vilka kakor behöver han"}},{q="Hur bakar du Gingerbread Cookies?",a="Smokywood Pastures försäljare runt högtidsståndet säljer receptet och Holiday Spices. Blanda kryddorna med Small Eggs som du samlat från vilda fåglar och grädda sedan kakorna över en matlagningseld.",al={"hur får man gingerbread cookies","recept på gingerbread cookies","ingredienser till kakor"}},{q="Var hittar du Ice Cold Milk?",a="Du kan köpa Ice Cold Milk av mat- och dryckesförsäljare, värdshusvärdar eller krögare runt om i Orgrimmar och andra större bosättningar.",al={"var får man tag på ice cold milk","köpa mjölk","mjölkförsäljare"}},{q="Varför ber Greatfather Winter själv om mat?",a="Att lyssna hela dagen på barn och invånare som pratar om mat, gåvor och festligheter gör skådespelaren som spelar Greatfather Winter hungrig. Eftersom han inte enkelt kan lämna sin post i Valley of Strength ber han förbipasserande resenärer om ett snabbt mellanmål.",al={"varför vill han ha godsaker","är greatfather winter hungrig"}},{q="Finns det en motsvarande quest för Alliansen?",a="Ja. I Ironforge framför Greatfather Winter samma önskemål till Alliance-mästare om pepparkakor och kall mjölk under festivalen.",al={"version för alliansen","godsaker i ironforge"}}},fx={["87543d9b"]={q="Vad ska pepparkakorna och Ice Cold Milk användas till?",a="Great-father Winter från Smokywood Pastures sitter ute och hälsar på festivalbesökare hela dagen, och julstämning är ett hungrigt arbete. De färska pepparkakorna och den svalkande kannan med Ice Cold Milk är ett enkelt, tröstande mellanmål som håller humöret uppe medan han lyssnar på besökarnas önskningar under högtiden i Orgrimmar.",al={"varför mjölk och kakor","vad pepparkakor används till","ice cold milk under winter veil"}},["1b7dc40f"]={q="Varför ber Great-father Winter dig i stället för att hämta godsakerna själv?",a="Great-father Winter sitter fast på sin festliga plats i Valley of Strength, där han tar emot gäster och sprider julglädje under Feast of Winter Veil. Om han lämnade sin post för att handla eller baka skulle besökarna bli besvikna och festligheterna störas. Därför ber han förbipasserande äventyrare att uträtta ärendet.",al={"varför behöver greatfather winter mig","varför kan great-father winter inte hämta mjölk","varför be en äventyrare hämta godsaker"}}},fp="30,159,24.234.0,23.236.0,39.254.0,44.137.0,36.196.0,33.117.0,50.238.0,45.141.0"}
P.entries["quest:697"] = {n="Malin's Request",s="Skuerto ger dig ett förseglat brev till Archmage Malin, som finns i Mage Quarter i Stormwind. I brevet står det att Kryten och Skuerto snart är hemma, och Skuerto är säker på att Malin kommer att belöna dig väl för hjälpen i Arathi.",h="Skuerto ger dig ett förseglat brev till Archmage Malin, som finns i Mage Quarter i Stormwind.",kw={"arathi highlands","archmage malin","kryten","mage quarter","malins begäran","förseglat brev","skuerto","stormwind"},sec={{t="Ett brev till ärkemagikern",b="Efter arbetet i Arathi ger Skuerto dig ett brev att ta med tillbaka till Stormwind. Hälsningen till Archmage Malin i Mage Quarter är att Kryten och Skuerto snart är hemma. Skuerto tvivlar inte på att Malin kommer att belöna dig väl för hjälpen, och skickar iväg dig med en önskan om en trygg resa."},{t="Malin läser brevet",b="När Malin öppnar brevet spärrar han upp ögonen. Han blir överlycklig och säger att Trelane kommer att bli så glad. Han antar att Kryten och Skuerto delar hans upphetsning nu när de är på väg hem till Stormwind."}},faq={{q="Vem skickar dig med brevet?",a="Det gör Skuerto. I brevet står det till Malin att han och Kryten snart är hemma.",al={"vem ger brevet","vem inleder malins begäran","startare för malins begäran"}},{q="Var finns Archmage Malin?",a="Archmage Malin finns i Mage Quarter i Stormwind.",al={"var finns archmage malin","archmage malins plats","var lämnar jag in det här"}},{q="Vem är Kryten?",a="Kryten är Skuertos följeslagare i Arathi Highlands. Skuerto säger att de snart är hemma.",al={"vem är kryten","kryten arathi"}},{q="Vad kommer före det här steget?",a="Det följer på Attack on the Tower, arbetet som Skuerto bad dig utföra vid tornet i Arathi.",al={"föregående uppdrag","förutsättning","vad leder hit"}}},fp="15,160,25.243.0,22.193.1,30.88.0,32.46.0,14.91.0,28.90.0"}
P.entries["quest:698"] = {n="Lack of Surplus",s="Dar samlar förnödenheter till utposten vid stranden i öster, där Tok'Kar har ont om tid mellan vaktpassen och matlagningen åt soldaterna. Dar ber dig ta med en leverans sågtandskött till Tok'Kar.",h="Dar samlar förnödenheter till utposten vid stranden i öster, där Tok'Kar har ont om tid mellan vaktpassen och...",kw={"dar","flank","kött","utpost","sågtand","swamp of sorrows","tok'kar"},sec={{t="Förnödenheter till stranden",b="Dar samlar förnödenheter till utposten vid stranden i öster. Tok'Kar gör vad han kan där, men vaktpassen och matlagningen åt soldaterna lämnar lite tid över på dagen. Soldaterna tycker om att laga sågtandskött när de får tag på det, och Dar har inte haft tid att skicka dem en ny leverans."},{t="Välj köttet",b="Dar varnar dig för att låta de unga sågtänderna vara, eftersom de äldre smakar bättre. De unga behöver ett eller två år för att nå full storlek. Åtta obehandlade sågtandsflankar ska levereras till Tok'Kar i Swamp of Sorrows."}},faq={{q="Vem ber om sågtandsköttet?",a="Dar, som samlar förnödenheter till utposten vid stranden i öster.",al={"vem ger lack of surplus","vem börjar lack of surplus","dar swamp of sorrows"}},{q="Var är Tok'Kar stationerad?",a="Vid utposten vid stranden i öster som Dar nämner. Köttet ska levereras till Tok'Kar där, i Swamp of Sorrows.",al={"var är tok'kar","tok'kar plats","tok'kar utpost"}},{q="Varför behöver Tok'Kar andra som tar med kött?",a="Mellan vaktpassen och matlagningen åt soldaterna har Tok'Kar lite tid över på dagen.",al={"varför behöver tok'kar kött","varför skickar dar mat"}},{q="Vilka sågtänder ska jagas?",a="De äldre. De unga är mindre välsmakande och behöver ett eller två år för att nå full storlek.",al={"vilka sågtänder","vilka sågtänder ger kött","källa till sågtandsflank"}},{q="Hur många flankar behövs?",a="Åtta obehandlade sågtandsflankar, levererade till Tok'Kar.",al={"hur många flankar","antal obehandlade sågtandsflankar"}},{q="Vad kommer härnäst i kedjan?",a="Ett andra steg med samma namn följer.",al={"nästa uppdrag lack of surplus","uppföljning lack of surplus"}}},fp="15,165,22.253.0,17.189.0,36.68.0,27.104.0,43.79.0,33.94.0,27.47.0,29.42.0"}
P.entries["quest:6981"] = {n="The Glowing Shard",s="Glowing Shard är en mystisk smaragdgrön ädelsten från Wailing Caverns mörka djup. Rökig essens virvlar under dess polerade yta, och den oroande reliken driver äventyrare att söka svar i Ratchet och bortom.",h="Glowing Shard är en mystisk smaragdgrön ädelsten från Wailing Caverns mörka djup.",kw={"barrens","druids of the fang","emerald nightmare","falla sagewind","glowing shard","ratchet","sputtervalve","wailing caverns"},ang={["class:Druid"]="För druider är kristallens smaragdglans och rökiga kärna ett dystert bevis på att Emerald Nightmare sipprar in i den vakna världen genom deras fallna bröder i Wailing Caverns.",["faction:Alliance"]="Även långt hemifrån i Kalimdor inser Alliance-utforskare den globala fara som den mörka kraft utgör, den som fördärvar naturen under Barrens.",["faction:Horde"]="Genom att nysta upp kristallens mysterium hjälper du till att skydda Barrens viktiga knutpunkter och handelsvägar från onaturliga hot som frodas i de underjordiska källorna.",["race:Tauren"]="Balansen i Barrens är dyrbar för Shu'halo, och när du för den onaturliga reliken till Falla Sagewind bidrar du till förståelsen av det fördärv som förgiftar deras förfäders land."},sec={{t="Ett oroande fynd",b="Glowing Shard hämtades från Wailing Caverns djup och gör genast den som håller den orolig. Den är lysande grön och verkar solid, men under sin kristallklara yta rymmer den virvlande, dimlika skuggor. Kristallen utövar en subtil dragningskraft och kräver uppmärksamhet, samtidigt som den utstrålar en djupt oroande aura. Den antyder att de sovande druidernas natur är fördärvad och att deras fristad är hemsökt av mardrömmar."},{t="På jakt efter svar i Ratchet",b="Osäkra på stenens ursprung och natur tar äventyrare artefakten till goblinernas hamn Ratchet. Där undersöker den lokale ingenjören Sputtervalve märkligheten och inser att dess ursprung ligger bortom goblinernas maskiner och vanlig geologi. I stället hänvisar han sökarna till de klippiga höjderna ovanför grottorna, där taurenmystikern Falla Sagewind vakar över Barrens plågade andar."}},faq={{q="Vad är Glowing Shard?",a="Det är en fördärvad, självlysande grön kristall som hittats djupt inne i Wailing Caverns. Inuti det glasliknande skalet virvlar svag rök som oroar alla som studerar den noga.",al={"föremålet glowing shard","vad är den gröna ädelstenen","kristall från wailing caverns"}},{q="Vem kan undersöka kristallen i Ratchet?",a="Sputtervalve, en ingenjör som håller till nära flygmästaren i Ratchet, undersöker kristallen. Han är ingenjör, inte druid, men känner igen dess märkliga energi och hänvisar dig till någon med andlig sakkunskap.",al={"vem i ratchet undersöker kristallen","npc i ratchet för kristallen","sputtervalve och kristallen"}},{q="Var finns Falla Sagewind?",a="Falla Sagewind har sitt läger på bergstopparna rakt ovanför ingången till Wailing Caverns, i centrala Barrens.",al={"falla sagewinds plats","var finns falla","berget ovanför wailing caverns"}},{q="Har Sputtervalve en uppdragsmarkör över huvudet?",a="Nej. Sputtervalve visar ingen aktiv uppdragsikon. Du måste tala direkt med honom och välja dialogalternativet om den märkligt lysande kristallen för att gå vidare.",al={"sputtervalve saknar frågetecken","kan inte lämna in till sputtervalve","sputtervalve buggad"}},{q="Varför ser kristallen ut att innehålla rök?",a="Röken som virvlar inuti kristallen speglar det utbredda fördärv som förvrider Wailing Caverns. Det hänger direkt samman med att Emerald Nightmare tränger in i de sovande Druids of the Fangs tankar.",al={"varför ryker kristallen","grön rök i ädelstenen","fördärv i kristallen"}},{q="Vem kan fortsätta uppdragskedjan efter Falla Sagewind?",a="Äventyrare från både Horde och Alliance kan följa den här berättelsen. Falla Sagewinds upptäckter leder direkt vidare till uppdraget 'In Nightmares', där hjältarna söker vägledning hos sina respektive ledare och äldste.",al={"är uppdraget bara för horde","glowing shard för alliance","vem får uppdraget in nightmares"}}},fx={["8f9c92be"]={q="Varför behöver du undersöka Glowing Shard?",a="Den lysande skärvan är djupt oroande. Den är fast men rymmer virvlande, rökgröna djup och utstrålar en onaturlig närvaro som kräver en förklaring. Du hämtade den från hjärtat av de oroliga Wailing Caverns och behöver förstå vilken korruption den bär på och vilket hot den kan utgöra mot The Barrens.",al={"varför undersöka glowing shard","glowing shards motiv","varför ta skärvan till ratchet"}}},fp="17,128,22.271.0,26.297.1,26.145.0,37.156.0,32.119.0,52.135.0,47.174.0,54.168.1"}
P.entries["quest:6984"] = {n="A Smokywood Pastures' Thank You!",s="Great-father Winter väntar i Orgrimmar för att tacka dem som återfann Smokywood Pastures stulna julgodis. Kaymard Copperpinch skickar dig för att ta emot ett tecken på uppskattning för att du återförde varorna.",h="Great-father Winter väntar i Orgrimmar för att tacka dem som återfann Smokywood Pastures stulna julgodis.",kw={"feast of winter veil","great-father winter","greench","kaymard copperpinch","orgrimmar","smokywood pastures","valley of strength","winter veil"},ang={["faction:Horde"]="I Orgrimmar förenar Hordens Winter Veil-firande schamanistisk vördnad för årstidernas växlingar med goblinernas handel.",["profession:Cooking"]="Som kock kan du lita på att Smokywood Pastures har säsongsvaror, exotiska recept och festliga ingredienser som många ser fram emot varje år."},sec={{t="En företagshögtid",b="I Orgrimmar säljer Smokywood Pastures godsaker, recept och säsongens glädje inför Feast of Winter Veil. Deras leverans stals i de snöiga kullarna i Alterac Mountains, och verksamheten stannade av. Nu när godsakerna har återfunnits och Abominable Greench tagits om hand skickar Kaymard Copperpinch dig för att ta emot företagets tack."},{t="Möte med Great-father Winter",b="Great-father Winter väntar vid högtidsträdet i Valley of Strength. Goblinerna har ordnat så att han hedrar dem som räddade högtidsvarorna med en säsongsbetonad välsignelse och en Smokywood Pastures Special Gift."}},faq={{q="Vem skickar mig till Great-father Winter?",a="Kaymard Copperpinch, Smokywood Pastures representant i Valley of Strength i Orgrimmar, skickar dig till Great-father Winter när du har återfunnit företagets stulna julgodis.",al={"vem startar uppdraget","uppdragsgivare","kaymards roll"}},{q="Vad gjorde jag för att förtjäna Smokywood Pastures tacksamhet?",a="Du spårade upp Abominable Greench i Alterac Mountains och återfann det stulna julgodiset, vilket räddade Smokywood Pastures varor inför Feast of Winter Veil.",al={"varför tackar de mig","vilka godsaker stals","greenchs bakgrund"}},{q="Var i Orgrimmar finns Great-father Winter?",a="Great-father Winter väntar under det pyntade Winter Veil-trädet i Valley of Strength, bredvid Smokywood Pastures försäljningsstånd.",al={"var finns great-father winter","var finns jultomten i org","winter veil-trädet i org"}},{q="Vem är Great-father Winter?",a="Great-father Winter är en elementär eller mytisk budbärare för årstidernas växlingar, som sägs täcka landet med vintersnö. Under Feast of Winter Veil bär dödliga hans röda kåpa för att sprida välvilja och ge godsaker till barn och äventyrare.",al={"vem är great-father winter","finns great-father winter på riktigt","winter veil-sägner"}},{q="Vad är Smokywood Pastures?",a="Smokywood Pastures är ett goblinlett företag inom mat och jordbruk. Det förser Horden och Alliansen med festmat, säsongsvaror och dekorationer under Feast of Winter Veil.",al={"smokywood pastures-sägner","vilka är smokywood pastures","goblinernas högtidsförsäljare"}},{q="Får jag något mer efter att ha pratat med honom?",a="Ja. Great-father Winter ger dig en Smokywood Pastures Special Gift på företagets vägnar, och dina insatser ger dig anseende hos Steamwheedle Cartel.",al={"uppdragsbelöning","förklädnadskit","present via posten"}}},fx={["553cdbb2"]={q="Varför skickar Kaymard Copperpinch dig till Great-father Winter?",a="Kaymard Copperpinch och Smokywood Pastures vill belöna dig för att du hämtade deras stulna godsaker. Genom att skicka dig till Great-father Winter för att personligen få en särskild gåva under Feast of Winter Veil visar goblinerna sin tacksamhet och håller fast vid säsongens festliga handelsanda.",al={"varför tackar kaymard mig","kaymard copperpinchs motiv","varför skicka mig till great-father winter"}}},fp="32,194,19.327.0,33.232.0,47.166.0,52.175.0,50.136.0,27.240.0,27.200.0,51.155.0"}
P.entries["quest:699"] = {n="Lack of Surplus",s="Tok'Kar och soldaterna vid kusten är stationerade där för att skydda Stonard mot murlocer eller varna när fienden är för många. Tok'Kar vill ha sex klor från sawtooth snapper och erbjuder som tack ett av utpostens vapen.",h="Tok'Kar och soldaterna vid kusten är stationerade där för att skydda Stonard mot murlocer eller varna när...",kw={"klor","murlocer","sawtooth snapper","stonard","swamp of sorrows","tok'kar"},sec={{t="Vapen till kusten",b="Eftersom murlocer hotar längs kusten är Tok'Kar och soldaterna stationerade här för att skydda Stonard eller varna staden om fienden är för många. Det lämnar lite tid för vila, och Tok'Kar skulle behöva mer hjälp. Klor från sawtooth snapper blir fina vapen när de förbereds på rätt sätt. Tok'Kar ber om sex stycken och erbjuder ett av utpostens vapen i utbyte, tacksam för köttet och sällskapet."}},faq={{q="Vem ber om klorna?",a="Tok'Kar, som är stationerad längs kusten för att skydda Stonard.",al={"vem ger lack of surplus","uppdragsgivare","tokkar"}},{q="Varför behöver Tok'Kar klor från sawtooth snapper?",a="Klorna blir fina vapen när de förbereds på rätt sätt, och Tok'Kar vill ha sex stycken.",al={"varför klor","sawtooth snapper användning","vapenklor"}},{q="Vilket hot håller kustposteringen utkik efter?",a="Murlocer längs kusten. Soldaterna är där för att skydda Stonard eller varna staden om fienden är för många.",al={"faror vid kusten","murlocattack mot stonard","vad håller tokkar utkik efter"}},{q="Vad följer härnäst?",a="Threat From the Sea följer.",al={"what comes next","nästa uppdrag","efter lack of surplus"}}},fp="15,194,21.347.0,23.78.0,45.82.0,45.112.0,26.28.0"}
P.entries["quest:7"] = {n="Kobold Camp Cleanup",s="I Northshire ställer Kobold Camp Cleanup de nya rekryterna inför deras första prov: att försvara Stormwinds gränser. Marshal McBride skickar frivilliga efter kobolder i de norra skogarna, där deras växande antal hotar abbeyns marker.",h="I Northshire ställer Kobold Camp Cleanup de nya rekryterna inför deras första prov: att försvara Stormwinds...",kw={"echo ridge","elwynn forest","kobold","marshal mcbride","northshire","northshire abbey","skadedjur"},ang={["faction:Alliance"]="Som medlem av Alliansen ser du hur hårt Stormwinds hemtrakter är ansträngda, när även angrepp från asätare kräver skyndsam hjälp från frivilligmilisen.",["race:Human"]="Som människa från Northshire är det en plikt mot samhället att driva tillbaka koboldskadedjuren och skydda abbeyn och jordbruksmarken från att bli översvämmade."},sec={{t="En pressad dal",b="Northshire Valley erbjöd en gång lugn för bön, jordbruk och träning av noviser. På senare år har Stormwinds styrkor blivit fåtaliga. Med kungen försvunnen och de kungliga garnisonerna utspridda tränger vilda varelser och lycksökare på vid civilisationens utkant. Marshal McBride leder dalens försvar från Northshire Abbey. Han förlitar sig på nya frivilliga för att hindra hot från att störa abbeyn eller äventyra de omgivande vingårdarna."},{t="Skadedjuren i skogen",b="Kobolder är skygga grottinvånare med starka band till ljus. De brukar leta i underjordiska ådror, långt från direkt solljus. Nu har en hel klan nått Northshires norra skogsgräns. Om de lämnas åt sig själva kan deras antal förvandla asätande till öppna räder. McBride skickar rekryterna för att minska deras förtrupp och pröva deras beslutsamhet att försvara riket."}},faq={{q="Vem beordrar att koboldlägret ska rensas ut?",a="Marshal McBride ger ordern. Från Northshire Abbey övervakar han rekryternas mottagande och säkerheten i dalen för Stormwind.",al={"vem ger uppdraget","uppdragsgivare","marshal mcbrides roll"}},{q="Varför finns kobolderna i de norra skogarna i stället för i en gruva?",a="Kobolder lever vanligtvis i hålor och gruvor, men Northshires växande befolkning har spridit sig ut i den öppna skogen. De har slagit upp primitiva läger bland de norra träden, nära civilisationens gräns.",al={"varför är kobolder utomhus","kobolder ovan jord","varför skogen"}},{q="Varför anses dessa kobolder vara ett hot mot Stormwind?",a="Enskilda koboldskadedjur är skygga och svaga. I flock kan de överfalla resande, plundra förråd och övermanna obevakade utposter, ett hot som Stormwind knappast har råd med när dess styrkor redan är hårt ansträngda.",al={"är kobolder farliga","varför döda skadedjur"}},{q="Vart leder uppdraget härnäst?",a="När kobolderna på ytan har blivit färre skickas rekryterna för att undersöka djupare delar av Echo Ridge Mine, där angreppet har sitt centrum.",al={"vilket uppdrag kommer härnäst","nästa steg","efter att lägret rensats"}},{q="Får Northshire regelbundet förstärkning från den kungliga armén?",a="Nej. Politiska spänningar och brist på trupper efter kung Varian försvinnande gör att befälhavare som McBride får förlita sig på frivilliga civila, äventyrare och rekryter under utbildning för gränssäkerheten.",al={"var är stormwinds vakter","varför frivilliga"}},{q="Varför är kobolder så fästa vid sina ljus?",a="Kobolder vördar ljus som sitt främsta skydd mot det kvävande mörkret i underjordiska tunnlar. Lågorna ger dem trygghet, sikt och en känsla av äganderätt.",al={"varför ljus","besatthet av ljus"}}},fx={afae4267={q="Varför vill Marshal McBride att koboldlägret röjs?",a="En koboldklan har börjat sprida sig i skogen norr om klostret, och Marshal McBride vill minska deras antal innan de tar över dalen. Stormwind är redan hårt pressat av hot på andra håll, så Northshire måste försvara sig självt. Kobolderna är fega var för sig, men blir djärva i flock. Om de röjs undan nu hålls bosättningen säker och arbetet med att driva bort dem från Northshire kan börja.",al={"varför rensa ut kobolder","mcbrides koboldmotiv","varför röja koboldlägret"}},["35967b57"]={q="Vilka är de koboldskadedjur som du skickas ut för att jaga?",a="Koboldskadedjuren är spejare och asätare från en klan som smugit sig in i den norra skogen. De är naturligt underjordiska, råttliknande humanoider och fega tjuvar på egen hand, men har samlats i oroväckande antal i skogen utanför Northshire. Om de lämnas i fred hotar deras läger resande, fruktodlingar och själva klostret.",al={"vilka är koboldskadedjuren","vad är koboldskadedjur","mål för koboldskadedjur"}},["921e514b"]={q="Varför skickar Marshal McBride dig i stället för Stormwinds vakter?",a="Stormwinds kungliga armé har spridit ut sina styrkor tunt för att hantera kriser i hela kungariket. Därför är bara en handfull vakter stationerade i Northshire Valley. McBride måste hålla sina soldater vid klostret och huvudvägarna för att upprätthålla försvarslinjerna. Han har inga extra soldater att skicka ut i vildmarken och förlitar sig därför på dugliga rekryter och förbipasserande frivilliga för att slå ner nya hot.",al={"varför inte skicka vakter","varför behöver mcbride mig","varför rekrytera äventyrare mot kobolder"}}},fp="19,169,23.267.0,23.319.0,42.126.0,56.203.0,55.199.0,34.145.1,50.184.0,48.164.0"}
P.entries["quest:70"] = {n="The Legend of Stalvan",s="Det här steget i utredningen leder till ett övergivet brev på värdshuset i Goldshire. Spåren efter Stalvan Mistmantle går från Elwynn Forest till Stormwinds kanaldistrikt.",h="Det här steget i utredningen leder till ett övergivet brev på värdshuset i Goldshire.",kw={"kanaler","caretaker folsom","goldshire","innkeeper farley","lion's pride inn","mistmantle","stalvan","stormwind","olevererat brev"},ang={["faction:Alliance"]="För att lösa mysteriet kring Stalvan måste du färdas genom Alliansens hjärtland och följa ett gammalt spår från den sömniga byn Goldshire till huvudstadens ståtliga kanaler.",["race:Human"]="Utredningen blottlägger Stormwinds kungarikes mörka strömningar och visar att ondskan som hemsöker Duskwood har rötter ända fram till huvudstadens tröskel."},sec={{t="En midnattsskräck",b="När Innkeeper Farley på Lion's Pride Inn får frågor om Stalvan Mistmantle minns han en stormig natt för många år sedan. En kurir på resa sökte skydd från störtregnet, men rusade ner för trappan kring midnatt i ren panik. Klädd enbart i nattkläder sprang kuriren rakt ut i den mörka stormen och sågs aldrig mer."},{t="Det kvarglömda paketet",b="I sin panikartade flykt lämnade kuriren sin väska och personliga kista i rummet däruppe. Bland den bortglömda lasten låg ett obeställt brev med namnet Stalvan, adresserat till någon i Canal District i Stormwind City. Kistan stod orörd vid fotänden av sängen tills Farley tillät att den öppnades."},{t="Ett kyligt välkomnande",b="När du tar med det sedan länge försenade brevet till Stormwind hittar du Caretaker Folsom, som vakar över egendom längs kanalerna nära Park. I stället för tacksamhet för att du slutfört en försummad leverans väcker omnämnandet av Stalvans namn och åsynen av hans handstil omedelbart avsky och fientlighet. Det antyder djupa skandaler kopplade till avsändaren."}},faq={{q="Var förvaras det olevererade brevet?",a="Brevet ligger i en förvaringskista på övervåningen av Lion's Pride Inn i Goldshire. Gå uppför trappan, sväng höger och gå in i sovrummet med sängen. Kistan står vid fotänden av sängramen.",al={"hitta brevet","stalvans kista plats","var finns kistan"}},{q="Varför blev brevet aldrig levererat från början?",a="Kuriren sökte skydd från ett skyfall på Lion's Pride Inn för många år sedan. Nära midnatt blev han så skräckslagen av något att han flydde ut i stormen i bara nattkläder och lämnade kistan och försändelserna bakom sig.",al={"varför övergivet brev","vad skrämde kuriren","varför flydde budbäraren"}},{q="Var hittar jag Caretaker Folsom i Stormwind?",a="Caretaker Folsom står vid kanalerna i Stormwind City, nära gränsen till Park-distriktet.",al={"folsoms plats","var finns caretaker folsom","lämna in vid kanaldistriktet"}},{q="Varför blir Caretaker Folsom arg när han får brevet?",a="Folsom känner genast igen Stalvans handstil och namn och reagerar upprört. Stalvan Mistmantle lämnade efter sig bittra minnen och vrede hos människorna som hade anknytning till hans förflutna i Stormwind.",al={"varför är folsom arg","folsoms reaktion","du har mage"}},{q="Hur hänger detta ihop med problemen i Duskwood?",a="Stadsrådet i Darkshire utreder en kvardröjande ondska med koppling till namnet Stalvan Mistmantle. För att ta reda på vem Stalvan var i livet måste du följa hans tidigare resor och kontakter genom Elwynn Forest och Stormwind.",al={"varför uppdrag i duskwood börjar i goldshire","hur hänger detta ihop med duskwood"}},{q="Vad händer efter att jag gett brevet till Caretaker Folsom?",a="Caretaker Folsoms skarpa reaktion öppnar nästa del av utredningen i Stormwind och får dig att söka efter Stalvans tidigare arbete och de fasansfulla händelserna med den adelsfamilj han tjänade.",al={"nästa steg","vad händer efter uppdraget"}}},fx={["1a6ccbd1"]={q="Varför vill Innkeeper Farley att Stalvans brev lämnas över?",a="Innkeeper Farley har inget personligt intresse i Stalvans angelägenheter eller det gamla brevet. Han hjälper dig bara att pussla ihop mysteriet du undersöker. När du frågar om Stalvan Mistmantle minns Farley en skräckslagen kurir som flydde från Lion's Pride Inn under ett oväder för många år sedan och lämnade sin postkista på övervåningen. Farley minns att ett olevererat brev från Stalvan låg kvar, adresserat till Stormwinds Canal District, och ger dig det så att du kan följa upp ditt svårfångade spår.",al={"varför hjälper farley","innkeeper farleys motiv","varför lämna över brevet"}},b7fa74bd={q="Vad är An Undelivered Letter?",a="Brevet är gammal korrespondens som Stalvan Mistmantle skrev för många år sedan, avsedd för en adress i Stormwinds Canal District. Det blev kvar på Lion's Pride Inn när en budbärare flydde ut i natten i skräck och lämnade sina tillhörigheter inlåsta i en kista på övervåningen. I din undersökning är brevet en viktig fysisk ledtråd. Det leder dig till Caretaker Folsom i Stormwind, där du kan ta reda på vem Stalvan kontaktade och vad som hände med honom.",al={"vad är ett olevererat brev","stalvans olevererade brev","vad står i brevet"}}},fp="21,134,17.266.0,19.289.0,16.261.1,37.203.0,46.205.0,46.91.0,57.183.0,49.198.0,57.186.1"}
P.entries["quest:700"] = {n="A King's Tribute",s="A King's Tribute markerar det sista steget i att hedra den fallne dvärgsoldaten Sully Balloos offer. Efter att fin granit hämtats från Ruins of Lordaeron hugger Grand Mason Marblesten ut ett högtidligt minnesmärke i Ironforge på order av King Magni Bronzebeard.",h="A King's Tribute markerar det sista steget i att hedra den fallne dvärgsoldaten Sully Balloos offer.",kw={"a king's tribute","granit","ironforge","lordaeron","magni bronzebeard","marblesten","minnesmärke","sully balloo"},ang={["class:Warrior"]="Magnis ord hedrar direkt frontsoldaternas osjälviska tapperhet, som hos Sully Balloo, som offrade allt i strid.",["faction:Alliance"]="Monumentet påminner på ett gripande sätt om de stora förlusterna i Khaz Modan och de norra kungarikena under senare konflikter.",["race:Dwarf"]="För dvärgar är det en av deras heligaste kulturtraditioner att hedra fallna förfäder i beständig sten."},sec={{t="Ett monument hugget i sorg",b="King Magni Bronzebeard beställde ett bestående monument för att hedra Sully Balloo, en modig dvärg som miste livet i tjänst för sitt folk. Grand Mason Marblesten tillverkade det av högklassig granit som transporterats från de krigshärjade markerna i Lordaeron. Minnesmärket står färdigt i Ironforge som ett bestående vittnesbörd om fallna soldater vars offer bevarar dvärgarnas kungarike."},{t="En monarks eftertanke",b="När Magni får veta att monumentet är färdigt tänker han dystert på stenens och dödlighetens gränser. Han inser att uthuggen sten aldrig kan mäta sig med en modig dvärgs liv, men hoppas att minnesmärket ska bestå så att framtida generationer som vandrar i Azeroth aldrig glömmer hjältarna som blödde för att trygga deras morgondag."}},faq={{q="Vem hedras med minnesmärket?",a="Monumentet byggdes till minne av Sully Balloo, en modig dvärgsoldat som gav sitt liv när han tappert stred för sitt folk och Alliansen.",al={"vem är minnesmärket tillägnat","sully balloo monument","vem dog"}},{q="Varför hämtades stenen från Lordaeron?",a="Grand Mason Marblesten behövde den finaste graniten för ett bestående kungligt minnesmärke. Lordaeron ger utmärkt sten från sina stenbrott, trots att regionen har fallit i ruiner efter de Ursjällas framfart.",al={"varför sten från lordaeron","lordaerongranit","marblestens sten"}},{q="Var utspelar sig uppdraget?",a="Uppdraget börjar hos Grand Mason Marblesten och avslutas hos King Magni Bronzebeard i High Seat i Ironforge.",al={"var lämnar man in","vem avslutar uppdraget"}},{q="Varför beställer King Magni minnesmärket personligen?",a="Magni anser att härskare måste hedra fotsoldaterna som försvarar deras riken. Han ser minnesstenar som viktiga påminnelser för framtida generationer om det höga pris vanliga soldater betalar för deras trygghet.",al={"varför bryr sig magni","magni bronzebeard sully balloo"}},{q="Vad händer när minnesmärket är färdigt?",a="När du rapporterar till King Magni avslutas kedjan av minnesmärkesuppdrag. Den färdiga statyn står kvar i Ironforge som ett högtidligt, bestående landmärke till Sully Balloos minne.",al={"what comes next","fortsättning på a king's tribute"}},{q="Vilken betydelse har statyn för stenhuggeriet?",a="Grand Mason Marblesten är en av de skickligaste dvärghantverkarna i Ironforge. Han bearbetade den importerade graniten från Lordaeron och formade råstenen till ett passande nationellt konstverk på monarkens vägnar.",al={"marblestens roll","grand masons hantverk"}}},fx={["964451bf"]={q="Varför skickar Grand Mason Marblesten dig till kungen?",a="Det var du som trotsade den farliga resan till Ruins of Lordaeron för att hämta den fina graniten till skulpturen. När stenen väl var säkrad och hyllningen möjlig, anförtror Grand Mason Marblesten dig uppgiften att personligen meddela King Magni Bronzebeard att minnesmärket över Sully Balloo är färdigt.",al={"varför skicka mig till magni","varför berätta för king magni","varför skickar marblesten spelaren"}}},fp="16,131,26.297.0,24.259.0,38.117.0,42.172.0,33.100.0,55.178.0,44.132.0,47.169.0"}
P.entries["quest:7003"] = {n="Zapped Giants",s="Vid The Forgotten Coast i Feralas, nära bryggorna, säger Zorbin Fandazzle att jättarna är dåliga för affärerna. Zorbin har byggt en förminskningsstråle efter en gnomisk ritning, förbättrad med goblinernas kunnande, och ger dig Ultra-Shrinker att prova på jättarna i Feralas.",h="Vid The Forgotten Coast i Feralas, nära bryggorna, säger Zorbin Fandazzle att jättarna är dåliga för...",kw={"cliff giant","feralas","the forgotten coast","land walker","miniaturiseringsrester","ultra-shrinker","zapped giants","zorbin fandazzle"},sec={{t="En förminskningsstråle åt jättarna",b="Zorbin Fandazzle måste göra något åt jättarna i Feralas, som sannerligen inte är bra för affärerna om Zorbin ska kunna stanna här ute. Lösningen är en variant av en gnomisk förminskningsstråle, byggd med vad Zorbin stolt kallar överlägsna goblinframsteg. För att slippa besvär som döden vill Zorbin hellre att du testar den. Du ska använda Ultra-Shrinker på jättar som Cliff Giants, Deep Striders, Wave Striders, Shore Striders eller Land Walkers och samla upp miniaturiseringsresterna som blir kvar på dem när de krymper, för att ta med dem tillbaka till bryggorna."},{t="Varför Zorbin vill ha resterna",b="Zorbin kallar miniaturiseringsresterna en värdefull råvara inom ingenjörskonsten, eftersom de hjälper till att säkerställa att zapparen inte gör något så nedslående som att explodera på användaren. Zorbin tillägger sedan att det bara gäller andra zappers, inte den du har i händerna."},{t="Tillbaka vid bryggorna",b="När du kommer tillbaka blir Zorbin förtjust över att se resterna och att du fortfarande har alla dina viktigaste kroppsdelar. Zorbin hävdar sedan att Ultra-Shrinker aldrig var riskabel och kallar dig en vän till gobliner överallt."}},faq={{q="Vem ligger bakom Ultra-Shrinker?",a="Zorbin Fandazzle, som finns vid bryggorna på The Forgotten Coast i Feralas.",al={"vem ger uppdraget zapped giants","zorbin fandazzle uppdragsgivare","var startar zapped giants"}},{q="Varför vill Zorbin krympa jättarna?",a="Zorbin säger att jättarna sannerligen inte är bra för affärerna om Zorbin stannar här ute, och att en krympt jätte är mycket mer lätthanterlig.",al={"varför zappa jättar","varför krympa jättar i feralas","zorbin fandazzles motiv"}},{q="Vilka jättar kan krympas?",a="Vilken sorts jätte som helst i Feralas duger. Längs The Forgotten Coast finns bland annat Cliff Giants, Deep Striders, Wave Striders, Shore Striders och Land Walkers.",al={"vilka jättar kan jag zappa","vilka jättar räknas","mål för zapped giants"}},{q="Vad är miniaturiseringsrester?",a="De finns på en jätte efter att den har krympts. Zorbin kallar dem en värdefull råvara inom ingenjörskonsten och säger att de hjälper till att säkerställa att zapparen inte exploderar på användaren.",al={"varför miniaturiseringsrester","vad gör resterna","syftet med zorbins rester"}}},fp="13,232,30.457.0,28.193.0,17.182.1,33.84.0,39.108.0,27.154.0,32.159.0"}
P.entries["quest:701"] = {n="Guile of the Raptor",s="Guile of the Raptor är ett uppdrag där Tor'gan försöker väcka Gor'muls slumrande krigaranda. Genom att samla hjärtan från Highland Fleshstalkers planerar Tor'gan att skapa ett förtrollat föremål genomsyrat av rovfågelns list och rovdjurskraft.",h="Guile of the Raptor är ett uppdrag där Tor'gan försöker väcka Gor'muls slumrande krigaranda.",kw={"slumrande krigare","gor'mul","guile of the raptor","highland fleshstalkers","rovfågelhjärtan","tor'gan","krigare"},ang={["class:Warrior"]="Tor'gan vill tända Gor'muls slumrande krigaranda på nytt och använda rovfåglarnas list och ursinne för att påminna honom om sin kampstyrka.",["faction:Horde"]="Ritualen speglar Hordens traditioner att hämta kraft från uråldriga bestar och naturandar för att ge en håglös eller plågad kamrat ett nytt syfte."},sec={{t="Den slumrande krigaren vaknar",b="Tor'gan försöker återställa sin håglösa kamrat Gor'mul, vars krigaranda har slumrat in. I stället för att nöja sig med enkla övertalningsförsök tar Tor'gan till uråldrig magi för att få Gor'mul att reagera. Genom att skapa en amulett genomsyrad av vilda rovdjurs essens hoppas han åter väcka Gor'muls stridsvilja och visa styrkan i deras nya kraft."},{t="Rovdjurets hjärta",b="För att kanalisera vildmarkens rovdjursinstinkter behöver Tor'gan hjärtan från Highland Fleshstalkers. I schamanistiska och ursprungliga traditioner bär en listig jägares hjärta på dess ursinne och list. Av dessa troféer skapar Tor'gan både en fysisk talisman och en besvärjelse. Han vill ingjuta rovdjurets list direkt i Gor'mul, så att han kan återupptäcka sitt verkliga kall."}},faq={{q="Vem är Tor'gan?",a="Tor'gan är en schamanistisk eller andlig gestalt som vill hjälpa Gor'mul. Han tror att Gor'mul har tappat kontakten med sin inre styrka och samlar därför ingredienser till ett föremål genomsyrat av bestmagi för att väcka honom till liv igen.",al={"vem är tor'gan","tor'gan","uppdragsgivare"}},{q="Vem är Gor'mul?",a="Gor'mul är en person som har tappat sin stridsvilja och låtit krigaren inom sig slumra in. Tor'gan tänker ingjuta honom med ett ursprungligt rovdjurs väsen, så att han får bevittna en ny kraft och resa sig för att strida igen.",al={"vem är gor'mul","varför hjälpa gor'mul","slumrande krigare"}},{q="Varför behöver Tor'gan rovfågelhjärtan?",a="Tor'gan behöver tolv rovfågelhjärtan för att skapa både en fysisk talisman och den förtrollning som krävs för att ingjuta kraft i Gor'mul. Urtida magi använder ofta rovdjurens hjärtan för att kanalisera deras naturliga instinkter, list och rovdjurskraft.",al={"varför rovfågelhjärtan","vad används hjärtana till","rovfågelmagi"}},{q="Var kommer rovfågelhjärtana ifrån?",a="Hjärtana tas från Highland Fleshstalkers, rovlystna rovfåglar som är kända för sin ihärdiga jaktförmåga och list. Tor'gan anser att deras hjärtan är kraftfulla nog att driva väckelsebesvärjelsen.",al={"var hittar man hjärtan","vilka rovfåglar","highland fleshstalkers"}},{q="Vad står rovfågelns list för?",a="Rovfågelns list står för rovdjurets slughet, snabba reflexer och dödliga instinkt. Tor'gan tror att om han kanaliserar just dessa egenskaper kan han bryta igenom Gor'muls håglöshet och väcka hans stridsinstinkter till liv.",al={"vad är rovfågelns list","vilken kraft","vad betyder rovfågelns list"}},{q="Vad är ritualens slutmål?",a="Tor'gan skapar föremålet och väver besvärjelsen med de insamlade hjärtana. Han vill visa Gor'mul en ny kraft och väcka hans slumrande krigaridentitet, så att han kan återta sin väg.",al={"är gor'mul botad","vad händer efter ritualen","fungerar det"}}},fp="19,196,29.335.0,25.336.0,15.190.0,15.194.0,36.199.0,37.179.0,42.187.0,40.176.0"}
P.entries["quest:702"] = {n="Guile of the Raptor",s="Efter den tidigare Guile of the Raptor ger Tor'gan dig en klot och skickar dig till Gor'mul i Hammerfall. Dess kraft bär på rovfågelns väsen, tänkt att väcka Gor'muls själ och ge honom ett nytt mål.",h="Efter den tidigare Guile of the Raptor ger Tor'gan dig en klot och skickar dig till Gor'mul i Hammerfall.",kw={"arathi highlands","gor'mul","hammerfall","rovfågelns väsen","tor'gan","tor'gan's orb"},sec={{t="Tor'gan's Orb",b="Tor'gan ger dig ett klot vars kraft är tänkt att fylla Gor'mul med rovfågelns väsen. Han hoppas att det ska väcka krigarens själ och ge honom en ny riktning i livet. När Gor'mul har blivit sig själv igen tänker Tor'gan förklara hordens nuvarande läge för honom och vinna en stor krigares hjälp i de ständiga striderna."},{t="Gor'muls bitterhet",b="Gor'mul tar emot dig med bitterhet och säger att han inte vill ha något annat än mer av Tor'gan's medlidande. Han hånar dig med prat om färgglatt snöre."},{t="En märklig kraft",b="Ändå är klotet mer intressant än Gor'mul väntat sig, och han kommenterar den märkliga kraft det utstrålar."},{t="Rovfågeln inom honom",b="När Gor'mul tar klotet börjar blodet sjuda och rovfågelns list strömmar genom honom. Han undrar högt om detta är shamanismen Tor'gan talade om och förklarar sedan att han är pånyttfödd och att styrkan återvänder."}},faq={{q="Vem är Gor'mul?",a="Gor'mul är en modfälld krigare i Hammerfall. Tor'gan vill muntra upp honom och ge honom en ny riktning, så att horden kan få hjälp av en stor krigare.",al={"vem är gor'mul","gor'muls historia","vad är det med gor'mul"}},{q="Vad är syftet med Tor'gan's Orb?",a="Dess kraft är tänkt att fylla Gor'mul med rovfågelns väsen, väcka hans själ och ge honom ett nytt mål.",al={"vad gör klotet","syftet med tor'gan's orb","guile of the raptor-klotet"}},{q="Vad kom före det här steget?",a="En tidigare Guile of the Raptor kommer först, och det här steget bygger vidare på den.",al={"föregående uppdrag","förutsättning"}}},fp="19,160,13.310.0,20.144.0,15.79.1,17.206.1,15.160.0,37.127.0,27.84.0"}
P.entries["quest:7025"] = {n="Treats for Greatfather Winter",s="Under Feast of Winter Veil blir den som spelar Greatfather Winter i Ironforge trött och ber förbipasserande om en säsongens godsak. Ta med nybakade pepparkakor och kall mjölk så får du en festlig belöning och hans varma tack.",h="Under Feast of Winter Veil blir den som spelar Greatfather Winter i Ironforge trött och ber förbipasserande...",kw={"feast of winter veil","pepparkaka","greatfather winter","ice cold milk","ironforge","smokywood pastures","treats for greatfather winter"},ang={["faction:Alliance"]="Ironforge är Alliance främsta samlingsplats för Winter Veil-firandet. Resenärer från hela Eastern Kingdoms kommer till högtidsträdet i Commons.",["profession:Cooking"]="Uppdraget kräver enkla matlagningskunskaper för att blanda små ägg och Holiday Spices till festliga pepparkakor.",["race:Dwarf"]="För dvärgarna står Greatfather Winter för en uråldrig legend med band till titanerna och vinterns överflöd, men när han sitter och mumsar på kakor i Commons känns myten plötsligt jordnära."},sec={{t="En lång dag i stolen",b="Winter Veil har rötter i uråldrig titanlore och dvärgmyter om en odödlig gestalt höljd i vinterns kyla, men dagens firande bygger till stor del på kommersiellt stöd från Smokywood Pastures. En vanlig dvärg står vid högtidsträdet i Ironforge Commons, klädd som Greatfather Winter under långa, slitsamma timmar medan han tar emot högtidsönskningar från både invånare och ivriga barn."},{t="Julbakad glädje",b="Efter att ha lyssnat på önskemål om gåvor hela dagen blir Greatfather Winter förstås rejält hungrig själv. I stället för att be om något påkostat önskar han sig något enkelt och tröstande: fem nybakade pepparkakor med Holiday Spices och lite Ice Cold Milk att skölja ner dem med. Bytet ger en utmattad högtidsarbetare en stunds vila och sprider glädje i den snöiga huvudstaden."}},faq={{q="Var hittar jag Greatfather Winter i Ironforge?",a="Greatfather Winter sitter intill det stora högtidsträdet och Smokywood Pastures utställning i Ironforge Commons, omgiven av festliga dekorationer.",al={"var finns greatfather winter","greatfather winter plats ironforge","var finns tomten i ironforge"}},{q="Hur bakar man pepparkakor?",a="Receptet säljs av Smokywood Pastures-försäljare nära Greatfather Winter. Du behöver Cooking och Holiday Spices, som du köper av högtidshandlaren, samt små ägg från vilda fåglar.",al={"var får man tag på pepparkakor","pepparkaksrecept","hur bakar man kakor"}},{q="Var får jag tag på Ice Cold Milk?",a="Ice Cold Milk kan köpas av nästan alla värdshusvärdar, matförsäljare och dryckesförsäljare i större Alliance-städer, bland annat på värdshusen i Ironforge.",al={"ice cold milk försäljare","var kan man köpa mjölk","mjölk ironforge"}},{q="Är den här Greatfather Winter den riktiga mytiska gestalten?",a="Nej, han är en dvärg som Smokywood Pastures har anlitat för att föreställa den legendariska gestalt som förknippas med titanerna under Winter Veil-firandet.",al={"är greatfather winter verklig","vem är mannen i ironforge","är han verkligen greatfather winter"}},{q="Vad skickar Greatfather Winter till dig när du har slutfört uppdraget?",a="När Greatfather Winter får kakorna och mjölken ger han dig ett Smokywood Pastures Gift Pack som en liten belöning för besväret.",al={"belöning för treats for greatfather winter","brev från greatfather winter","smokywood pastures provpaket"}},{q="Kan spelare i Horde slutföra just det här uppdraget?",a="Det här uppdraget erbjuds Alliance-spelare i Ironforge. Horde-medlemmar har ett motsvarande uppdrag där de besöker Greatfather Winter i Orgrimmar.",al={"kan horde göra det här uppdraget","hordes treats for greatfather winter"}}},fx={["4b1f8d0d"]={q="Varför vill Greatfather Winter att det här blir gjort?",a="Greatfather Winter har suttit i Ironforge hela dagen utan avbrott och lyssnat på högtidsönskningar och hälsat besökare välkomna. Feast of Winter Veil sprider glädje till alla andra, men allt prat om festmat har gjort honom utmattad och hungrig. Därför ber han dig hämta ett välbehövligt mellanmål.",al={"greatfather winters motiv för kakor","varför vill greatfather winter ha kakor","varför godsaker till greatfather winter"}},a70b2277={q="Vad ska Ice Cold Milk användas till?",a="Ice Cold Milk är helt enkelt en svalkande dryck att skölja ner de varma pepparkakorna med. Att hälsa på resande och ropa festliga lyckönskningar hela dagen gör en törstig, och inget passar bättre till söta festkakor än en iskall dryck.",al={"varför ice cold milk","mjölk till greatfather winter","vad ice cold milk är till för"}},cc125737={q="Vad ska pepparkakorna användas till?",a="Pepparkakorna är en personlig högtidsgåva till Greatfather Winter själv. Efter att ha delat ut godsaker och lyssnat på önskemål från den ena invånaren efter den andra längtar han efter en traditionell Winter Veil-godsak kryddad med Holiday Spices för att få ny energi.",al={"pepparkakor till greatfather","varför pepparkakor","kakor till greatfather winter"}},["6bf2696f"]={q="Varför behöver Greatfather Winter dig i stället för att hämta godsakerna själv?",a="Greatfather Winter kan inte lämna sin plats mitt under festligheterna. Han står vid trädet i Ironforge för att hälsa på folkmassorna och sprida glädje för Smokywood Pastures. Därför måste han stanna där och förlita sig på hjälpsamma förbipasserande som du för att hämta mat åt honom.",al={"varför behöver greatfather winter mig","varför kan greatfather winter inte hämta egna kakor","varför ber greatfather winter en äventyrare"}}},fp="29,183,22.305.0,20.261.0,48.143.0,36.195.0,29.137.0,50.116.0,64.104.1,47.144.0"}
P.entries["quest:703"] = {n="Barbecued Buzzard Wings",s="Rigglefuzz svär vid grillade gamvingar, med fyllig sås på syrligt kött. Allt till en sats finns till hands utom själva vingarna. Hämta tillräckligt många, så kanske Rigglefuzz delar med sig av receptet.",h="Rigglefuzz svär vid grillade gamvingar, med fyllig sås på syrligt kött.",kw={"badlands","grillning","gam","matlagning","recept","rigglefuzz","vingar"},ang={["profession:Cooking"]="Kockar, hör upp: receptet på rätten erbjuds."},sec={{t="En lokal favorit",b="Rigglefuzz är stolt över sina grillade gamvingar. Såsen är fyllig, köttet syrligt och doften når hungrigt folk långt bort. Alla ingredienser till en sats finns redan till hands, utom vingarna. Ta med fyra gamvingar, så kanske Rigglefuzz delar med sig av receptet."}},faq={{q="Vem ber om gamvingarna?",a="Rigglefuzz vill ha gamvingar för att laga en sats grillade gamvingar.",al={"vem ger grillade gamvingar","vem är rigglefuzz","uppdragsgivare"}},{q="Vad erbjuder Rigglefuzz i utbyte mot vingarna?",a="Rigglefuzz antyder att receptet kan delas om du tar med tillräckligt många vingar.",al={"vad är belöningen","vad får jag","receptbelöning"}},{q="Varför behöver Rigglefuzz gamvingar?",a="Rigglefuzz har allt annat som behövs för en sats grillade gamvingar. Det är bara vingarna som saknas.",al={"varför gamar","rigglefuzz motiv","varför vill rigglefuzz ha vingar"}},{q="Hur många vingar vill Rigglefuzz ha?",a="Fyra gamvingar.",al={"hur många gamvingar","antal gamvingar"}}},fp="23,92,16.251.0,31.66.0,51.59.0,39.62.0,36.36.0"}
P.entries["quest:705"] = {n="Pearl Diving",s="Rigglefuzz, en goblin, finner att Badlands kryllar av våldsamma rovdjur och djärva asätare och överlever genom list: blixtrökbomber skrämmer bort vilddjuren. Förrådet av krossat blått pärlpulver börjar sina, så du skickas till The Vile Reef i Stranglethorn för att hämta mer.",h="Rigglefuzz, en goblin, finner att Badlands kryllar av våldsamma rovdjur och djärva asätare och överlever...",kw={"badlands","blå pärla","blixtrökbomb","pärlfiske","rigglefuzz","stranglethorn vale","the vile reef"},ang={["profession:Engineering"]="Ingenjörer har goda skäl att intressera sig för Rigglefuzz blixtrökbomber."},sec={{t="En listig liten goblin",b="Badlands är en hård plats, och Rigglefuzz erkänner att han är rädd som en kort liten goblin bland rovdjur och asätare. Rigglefuzz kan receptet på blixtrökbomber och använder dem för att skrämma bort vilda djur. En ingrediens börjar ta slut: krossat blått pärlpulver."},{t="Pärlor från revet",b="Blå pärlor kommer från musslorna vid The Vile Reef i Stranglethorn. Rigglefuzz skämtar om att du nog bör ha rejäla stövlar, och väntar sedan i Badlands på nio stycken. Han lovar att göra din möda värd besväret."}},faq={{q="Varför behöver Rigglefuzz blå pärlor?",a="Rigglefuzz använder krossat blått pärlpulver för att tillverka blixtrökbomber, och förrådet börjar sina.",al={"rigglefuzz pärlor","varför pärlfiske","varför blå pärlor"}},{q="Var hittar man de blå pärlorna?",a="De finns i musslor vid The Vile Reef i Stranglethorn.",al={"var finns blå pärlor","blå pärlors plats","pärlor vid vile reef"}},{q="Varför använder Rigglefuzz blixtrökbomber?",a="Badlands kryllar av våldsamma rovdjur och djärva asätare, och blixtrökbomber skrämmer bort vilddjuren.",al={"varför blixtrökbomber","rigglefuzz försvar"}},{q="Hur många blå pärlor vill Rigglefuzz ha?",a="Nio blå pärlor, som du tar tillbaka till Rigglefuzz i Badlands.",al={"antal blå pärlor","hur många pärlor"}}},fp="12,136,22.241.0,20.199.0,37.93.0,32.65.0,36.118.0,42.67.0"}
P.entries["quest:706"] = {n="Fiery Blaze Enchantments",s="Sigrun Ironhew väntar i Badlands på besked från Ironforge och kan en teknik för att ge vapen eldegenskaper. Den kräver blod från hjärtat på en sällsynt svart drakunge som fortfarande slår. Sådana ungar finns i Lethlor Ravine.",h="Sigrun Ironhew väntar i Badlands på besked från Ironforge och kan en teknik för att ge vapen eldegenskaper.",kw={"badlands","svart drakhjärta","feranor steeltoe","fiery blaze","ironforge","lethlor ravine","scalding whelp","scorched guardian","sigrun ironhew"},ang={["faction:Alliance"]="Sigrun Ironhew väntar på besked från Ironforge, och det här arbetet är avsett för Alliansen."},sec={{t="En lärlings hantverk",b="Som lärling hos Feranor Steeltoe lärde sig Sigrun Ironhew ett särskilt sätt att ge vapen eldiga förtrollningar. Senast hörde man att Feranor fanns bland smederna i ett jaktsällskap i Lordaeron. Sigrun väntar på besked från Ironforge och har inte mycket annat att göra."},{t="Ungarna i Lethlor Ravine",b="Sigrun berättar få detaljer om processen. Det enda som sägs är att den kräver blod från hjärtat på en sällsynt svart drakunge som fortfarande slår. Ta med ett hjärta från ungarna i ravinen till Sigrun, så får du lära dig tekniken. Scalding Whelps och Scorched Guardians där är källan till hjärtana."}},faq={{q="Vem lärde Sigrun Ironhew den här förtrollningstekniken?",a="Sigrun lärde sig tekniken som lärling hos Feranor Steeltoe, som senast hördes av i Lordaeron, där han arbetade i ett jaktsällskaps smedja.",al={"sigruns lärare","vem tränade sigrun","feranor steeltoe"}},{q="Vilken ingrediens behövs för att lägga eld på en klinga?",a="Blod från hjärtat på en sällsynt svart drakunge, medan det fortfarande slår.",al={"vad behöver sigrun","krav på svart drakhjärta","material till fiery blaze"}},{q="Var hittar man de svarta drakungarna?",a="I Lethlor Ravine, i östra Badlands.",al={"var hittar man svarta drakar","ungar i lethlor ravine","plats för svart drakhjärta"}},{q="Varför dröjer Sigrun Ironhew kvar i Badlands?",a="Sigrun väntar på besked från Ironforge och har inget annat som håller henne sysselsatt under tiden.",al={"varför är sigrun i badlands","sigrun ironhews syfte"}},{q="Vilka varelser ger det nödvändiga hjärtat?",a="Scalding Whelps och Scorched Guardians i Lethlor Ravine.",al={"vad släpper svart drakhjärta","vilka drakungar har hjärtan"}}},fp="24,208,21.244.0,28.266.0,53.142.0,52.89.0,39.72.0,48.84.0,39.84.0"}
P.entries["quest:7070"] = {n="Shadowshard Fragments",s="Ärkemagikern Tervosh i Theramore ber dig samla Shadowshard Fragments från Maraudon. Han behöver att du återför tio stycken till honom.",h="Ärkemagikern Tervosh i Theramore ber dig samla Shadowshard Fragments från Maraudon.",kw={"ärk magikern tervosh","dustwallow marsh","maraudon","shadowshard fragments","tervosh","theramore"},sec={{t="Tervoshs begäran",b="Ärkemagikern Tervosh väntar i Theramore vid kusten i Dustwallow Marsh. Han ber dig ta med tio Shadowshard Fragments från Maraudon, och fragmenten står i centrum för hans begäran."}},faq={{q="Vem ber om Shadowshard Fragments?",a="Ärkemagikern Tervosh i Theramore ber dig samla Shadowshard Fragments.",al={"vem vill ha fragment","tervoshs fragment"}},{q="Var kommer fragmenten ifrån?",a="Shadowshard Fragments kommer från Maraudon.",al={"varifrån kommer fragment","maraudonskärvor"}},{q="Hur många fragment vill Tervosh ha?",a="Ärkemagikern Tervosh ber om tio Shadowshard Fragments.",al={"hur många skärvor","tio fragment"}},{q="Vart ska jag ta dem?",a="Ta fragmenten till ärkemagikern Tervosh i Theramore vid kusten i Dustwallow Marsh.",al={"vart återlämna fragment","tervoshs plats"}}},fp="21,119,19.182.0,39.76.0,33.45.0,37.52.0,22.87.0"}
P.entries["quest:708"] = {n="The Black Box",s="En svart metallåda har hittats i magen på en jättelik kondor i Badlands. Ytan är kraftigt gropig, som om den legat i syra. På undersidan, under en symbol, står det Engine #19 - Ironforge Siege Brigade.",h="En svart metallåda har hittats i magen på en jättelik kondor i Badlands.",kw={"badlands","svart låda","korroderad svart låda","jättelik kondor","hall of arms","ironforge siege brigade","pilot longbeard"},ang={["faction:Alliance"]="Lådan bär Ironforges märkning, och spåret slutar i Ironforge."},sec={{t="Upphittad i en kondor",b="Gropigheten tyder på att lådan legat i kondoren i evigheter medan syran frätte på metallen. Vänd på den så ser du en symbol stämplad på botten, med Engine #19 - Ironforge Siege Brigade skrivet under. Du ska ta den till Hall of Arms i Ironforge, till Pilot Longbeard."}},faq={{q="Varifrån kom den korroderade svarta lådan?",a="Den låg i magen på en jättelik kondor i Badlands och verkar ha legat där mycket länge.",al={"varifrån kom lådan","hur kom lådan hit","svarta lådans ursprung"}},{q="Vilka märkningar är stämplade på lådan?",a="En symbol är stämplad på botten, och under den står det Engine #19 - Ironforge Siege Brigade.",al={"vad står det på lådan","märkningar på den svarta lådan","inskription på lådan"}},{q="Vem ska ta emot lådan?",a="Pilot Longbeard, i Hall of Arms i Ironforge.",al={"vem får lådan","vart ska den svarta lådan","vem ska jag lämna lådan till"}}},fp="13,74,20.211.0,43.100.0,37.90.0,35.50.0"}
P.entries["quest:71"] = {n="Report to Thomas",s="Guard Thomas väntar vid den östra bron på nyheter om sina försvunna män. Med få vakter till hands håller han övergången mellan Goldshire och Eastvale Logging Camp och behöver veta vad som hänt längs floden.",h="Guard Thomas väntar vid den östra bron på nyheter om sina försvunna män.",kw={"bro","elwynn forest","goldshire","guard thomas","malakai","medaljonger","murlocs","rolf"},ang={["faction:Alliance"]="Rolf och Malakais död visar hur utsatta Elwynn Forests gränser är. Även vanliga flodpatruller kan bli övermannade när vakterna är få.",["race:Human"]="Som människa ger återfinnandet av de fallna vakternas medaljonger Stormwind-soldaterna, som dog när de försvarade kungarikets inre vägar, en viss heder och ett avslut."},sec={{t="En dyster bekräftelse",b="Guard Thomas håller övergången mellan Goldshire och Eastvale Logging Camp med få män till hands. När Malakai och Rolf försvann i flodlandet hoppades han att de bara hade blivit avskurna eller försenade. Deras återfunna tjänstemedaljonger lämnar inget utrymme för sådant hopp. Båda vakterna dödades nära vattendragen."},{t="Hotet längs vattnet",b="I flera månader har Stormwinds ledare betraktat murlocs som ett besvär bland floderna och i stället fokuserat på banditer och kungarikets vidare gränser. Nu har två beväpnade vakter från Stormwind slaktats längs vattendragen i inlandet. Medaljongerna visar Thomas att Elwynn Forests östra gräns utsätts för ett aktivt angrepp, och han efterlyser en insats innan avverkningsvägarna och bosättningarna blir överväldigade."}},faq={{q="Var befinner sig Guard Thomas?",a="Guard Thomas är stationerad vid stenbron över floden i östra Elwynn Forest, på vägen mellan Goldshire och Eastvale Logging Camp.",al={"thomas plats","guard thomas vid bron","var är guard thomas"}},{q="Vilka var Rolf och Malakai?",a="Rolf och Malakai var vakter från Stormwind som skickades för att patrullera östra Elwynn Forest. Murlocs längs flodbankarna och Stonecairn Lake övermannade och dödade dem.",al={"försvunna vakter i elwynn","vem var rolf","vem var malakai"}},{q="Varför behövdes deras medaljonger?",a="Medaljongerna identifierar vakter från Stormwind City. När de återlämnas får Guard Thomas bevis för att hans försvunna män dog i tjänsten.",al={"varför medaljonger","vakternas medaljonger syfte"}},{q="Varför är murlocernas angrepp så allvarligt?",a="Murlocs avfärdas ofta som primitiva, fega skadedjur. Att två beväpnade vakter dödats visar att flodstammar kan utföra samordnade bakhåll och hota tränade soldater.",al={"varför är murlocs ett hot","är murlocs farliga i elwynn"}},{q="Vad händer efter att du rapporterat tillbaka till Thomas?",a="Thomas ber dig ta med en rapport om vakternas död och det växande hotet från murlocs till Marshal Dughan i Goldshire. Dughan varnar för att områdets försvar redan är hårt ansträngt.",al={"nästa uppdrag efter report to thomas","vad gör thomas härnäst"}},{q="Varför är Guard Thomas ensam stationerad vid bron?",a="Stormwinds militär är hårt ansträngd i hela riket, kung Varian Wrynn är försvunnen och resurserna är knappa. Den östra bron och andra avlägsna poster har få vakter som kan skydda viktiga vägar.",al={"varför är thomas ensam","stormwind-vakt ensam vid bron"}}},fx={d4d51b05={q="Varför ska medaljongerna lämnas till Guard Thomas?",a="Guard Thomas skickade ut patruller mot floden, men de försvann utan ett ord. Att hitta Rolf och Malakai döda bland vassen ger ett dystert besked om deras öde. När du lämnar tillbaka deras medaljonger till Thomas får han ett obestridligt bevis på vad som hände med hans män och en varning om de dödliga murlockerna längs det östra vattnet.",al={"varför rapportera till thomas","varför ta medaljongerna till thomas","syftet med rapporten till thomas"}},["3744e02c"]={q="Varför är det du som återlämnar medaljongerna till Thomas?",a="Rolf och Malakai är döda, mördade av murlockerna djupt inne i den fientliga byn vid flodstranden. Guard Thomas är ensam stationerad vid den östra bron och kan inte lämna sin post obevakad. Eftersom du hittade de fallna vakterna och trotsade murlockerna för att hämta deras insignier faller uppgiften på dig att föra tillbaka det dystra beskedet.",al={"varför jag ska rapportera till thomas","varför tar jag med medaljongerna"}}},fp="16,179,19.300.0,26.390.0,30.144.0,26.154.1,36.133.1,41.180.1,44.185.1,47.196.0"}
P.entries["quest:710"] = {n="Study of the Elements: Rock",s="Lotwil Veriatus har stannat i Badlands för att arbeta med bojor för att binda elementaler. För att testa några offensiva besvärjelser och ett par hopmonterade manicker behöver Lotwil små stenfragment från de mindre stenelementalerna i närheten.",h="Lotwil Veriatus har stannat i Badlands för att arbeta med bojor för att binda elementaler.",kw={"badlands","mindre stenelementaler","lotwil veriatus","bojor för att binda elementaler","små stenfragment","studier av elementen: sten"},ang={["class:Mage"]="Bojorna som Lotwil tillverkar är avsedda för magiker."},sec={{t="Elementarbojor",b="Här i Badlands arbetar Lotwil Veriatus med ett projekt: bojor för att binda elementaler. När de är färdiga ska de låta magiker frammana ännu starkare elementaler för ännu större nytta. För att komma igång vill Lotwil ha tio små stenfragment, som lätt kan tas från de mindre stenelementalerna i kullarna precis västerut."}},faq={{q="Vem ber om stenfragmenten?",a="Lotwil Veriatus, som har stannat i Badlands för att arbeta med ett projekt.",al={"vem ger uppdraget","uppdragsgivare","lotwil veriatus"}},{q="Vad arbetar Lotwil Veriatus med?",a="Bojor för att binda elementaler, avsedda att låta magiker frammana ännu mäktigare elementaler.",al={"lotwils projekt","bojor för att binda elementaler","vad bygger lotwil"}},{q="Varför behöver Lotwil små stenfragment?",a="De ska användas för att testa några av Lotwils senaste offensiva besvärjelser och ett par hopmonterade manicker.",al={"varför stenfragment","fragmentens syfte","vad används fragmenten till"}},{q="Var finns stenfragmenten?",a="Hos de mindre stenelementalerna i kullarna precis väster om Lotwil.",al={"var hittar man fragment","mindre stenelementalers plats","stenfragmentens källa"}}},fp="27,147,18.305.0,35.71.0,35.104.0,40.82.0,33.84.0"}
P.entries["quest:711"] = {n="Study of the Elements: Rock",s="Lotwil Veriatus berömmer dig för att vara skickligare än alla Lotwils lärlingar tillsammans och vill gå vidare med proven. Den här gången behöver du tre stora stenplattor, som bäst hittas på st_elementaler.",h="Lotwil Veriatus berömmer dig för att vara skickligare än alla Lotwils lärlingar tillsammans och vill gå...",kw={"badlands","stora stenplattor","lotwil veriatus","stenlementaler","stenplattor","study of the elements: rock"},sec={{t="Större delar",b="Nästa delar av Lotwil Veriatus arbete kräver mer kraft. Stenlementaler har större och tåligare kroppar, så de bär troligare på delar som är stora nog för proven. Lotwil visar dig längre västerut, eller sydost längs bergens kanter, och ber dig samla tre stora stenplattor. Lotwil behöver en stund för att testa de mindre delarna du tog med tidigare."},{t="Lotwils förhoppningar",b="Lotwils besvärjelser påverkade de mindre delarna precis som förutspått. Om nästa experiment går lika bra som väntat kommer elementalerna under Lotwils kontroll att överträffa allt som tidigare har frammanats."}},faq={{q="Vem skickar dig efter de stora plattorna?",a="Lotwil Veriatus, som arbetar i Badlands.",al={"vem ger uppdraget","lotwil uppdrag","studie av elementen uppdragsgivare"}},{q="Vad hände före den här begäran?",a="Det tidigare Study of the Elements: Rock, där du tog med små stenflisor till Lotwil.",al={"tidigare uppdrag","föregående steg","vad gjorde jag tidigare"}},{q="Var säger Lotwil att du hittar stenlementalerna?",a="Längre västerut från Lotwil, eller sydost längs bergens kanter.",al={"var finns elementalerna","elementalernas platser","var hittar man plattor"}},{q="Varför behöver Lotwil större stenplattor?",a="Lotwil behöver större delar till nästa prov. Stenlementaler har större och starkare kroppar, så deras delar är tillräckligt stora.",al={"varför stora plattor","plattornas syfte","lotwils forskningsmål"}}},fp="27,148,13.306.0,14.177.0,36.78.0,30.106.0,50.77.0,40.140.0"}
P.entries["quest:712"] = {n="Study of the Elements: Rock",s="Lotwil Veriatus behöver en sista del från elementarvarelserna i Badlands: bojor av bergbindning, tagna från större bergselementarer. Enligt Lotwils beräkningar räcker de för att mäta styrkan hos Lotwils egna bojor.",h="Lotwil Veriatus behöver en sista del från elementarvarelserna i Badlands: bojor av bergbindning, tagna från...",kw={"badlands","bojor av bergbindning","större bergselementarer","kharanos","lotwil veriatus","lucien","ogres","servo"},sec={{t="Mät bojorna",b="Efter stenplattorna ber Lotwil Veriatus om en sista del från Badlands elementarvarelser. Bojor av bergbindning, tagna från större bergselementarer, bör låta Lotwil bedöma styrkan hos bojorna som håller på att tillverkas. Lotwils skådande visade en grupp elementarvarelser i sydväst, nära några ogres, om Lotwil minns rätt. Fem bojor behövs, så att det finns några extra, eftersom Servo är ökänd för att tappa bort Lotwils reagenser och forskning."}},faq={{q="Varför behöver Lotwil bojorna?",a="Enligt Lotwils beräkningar räcker bojor av bergbindning för att mäta styrkan hos Lotwils egna bojor.",al={"varför bojor av bergbindning","vad används bojor till","lotwil bojor av bergbindning"}},{q="Varför ber Lotwil om fem bojor?",a="För att ha några extra, eftersom Servo är ökänd för att tappa bort Lotwils reagenser och forskning.",al={"varför fem bojor","hur många bojor","varför extra bojor"}},{q="Var finns de större bergselementarerna?",a="En grupp av dem finns sydväst om Lotwil, nära några ogres, enligt Lotwils skådande. Kullarna kring Camp Cagg är deras hem.",al={"var finns bergselementarerna","större bergselementarers plats","var hittar man bojor"}},{q="Vad händer med stenplattorna som samlades in tidigare?",a="Lucien tar med sig de extra plattorna tillbaka till Kharanos när arbetet här är klart, eftersom de kan komma till nytta igen.",al={"vad hände med stenplattorna","lucien stenplattor","kharanos stenplattor"}}},fp="27,98,20.369.0,33.79.0,37.100.0,46.126.0,50.115.0"}
P.entries["quest:713"] = {n="Coolant Heads Prevail",s="Lotwil Veriatus vill ha en flaska Frost Oil för att förstärka bojorna som ska hålla en tillkallad vän i schack. Bro'kin, en goblinvän till Lotwil i Alterac, kan lära dig att tillverka det.",h="Lotwil Veriatus vill ha en flaska Frost Oil för att förstärka bojorna som ska hålla en tillkallad vän i...",kw={"badlands","bro'kin","coolant heads prevail","frost oil","lotwil veriatus","ruins of alterac","bojor"},sec={{t="En livsviktig kylvätska",b="Lotwil Veriatus svär att inget hindrar en motor eller kugghjul från att överhettas lika bra som Frost Oil, och att ingen annan smörjolja kan mäta sig med den. Den hjälper också magiska föremål att behålla sina förtrollningar. En flaska skulle öka den magiska kapaciteten i Lotwils bojor och göra dem starka nog att hindra den tillkallade vännen från att döda alla."},{t="Bro'kin i Alterac",b="Bro'kin, en goblinvän till Lotwil, kan lära dig att tillverka oljan. Bro'kin finns i Ruins of Alterac och säljer från en plats uppe på den gamla stadens mur."},{t="När oljan kommer",b="När oljan kommer kallar Lotwil den den perfekta kylvätskan för de nya armskenorna. Lotwil svär att om förtrollningarna inte håller i ett århundrade ska alla Lotwils ägodelar gå till Servo. Lotwil förväntar sig också att magikerna i Assembly ska häpna när arbetet är klart."}},faq={{q="Varför behöver Lotwil Veriatus Frost Oil?",a="En flaska skulle öka den magiska kapaciteten i Lotwils bojor, så att de blir starka nog att hindra den tillkallade vännen från att döda alla.",al={"varför frost oil","vad används frost oil till","lotwils olja"}},{q="Vem kan konsten att brygga Frost Oil?",a="Bro'kin, en goblinvän till Lotwil, kan lära dig att tillverka det. Han finns i Ruins of Alterac, uppe på en mur i den gamla staden.",al={"vem lär ut frost oil","var lär man sig frost oil","bro'kins recept"}},{q="Vad är speciellt med Frost Oil?",a="Lotwil säger att inget hindrar en motor eller kugghjul från att överhettas lika bra som den, att ingen annan smörjolja kan mäta sig med den och att den hjälper magiska föremål att behålla sina förtrollningar.",al={"frost oils egenskaper","varför är frost oil bra"}}},fp="21,147,15.262.0,18.134.0,20.254.1,40.111.0,32.143.0,32.165.0"}
P.entries["quest:714"] = {n="Gyro... What?",s="När du har hämtat Frost Oil från Coolant Heads Prevail och lämnat det till Lotwil Veriatus, finner du honom fortfarande helt uppslukad av en apparat i Badlands. En liten men avgörande del saknas: en gyrochronatom.",h="När du har hämtat Frost Oil från Coolant Heads Prevail och lämnat det till Lotwil Veriatus, finner du honom...",kw={"badlands","apparat","coolant heads prevail","gyrochronatom","kharanos","lotwil veriatus"},ang={["profession:Engineering"]="Ingenjörer kan själva tillverka en gyrochronatom."},sec={{t="En avgörande del",b="Lotwil Veriatus, distraherad av arbetet, säger att du har gjort ett arbete som överträffar alla krav och ber dig komma och söka jobb om ni någonsin möts i Kharanos. Sedan följer ett jäktat försök att fånga något, och den egentliga begäran: en gyrochronatom. Lotwil medger att det är en liten del, men en avgörande sådan. Ta med en, så bör projektet vara redo att slutföras."},{t="Överlämningen",b="När du räcker över gyrochronatomen griper Lotwil tag i den med ett rop och säger att arbetet nästan är klart, verkligen, och att projektet har högsta prioritet just nu. Löftet om att snart bli klar vacklar mellan några minuter och kanske mycket längre."}},faq={{q="Vem ber om gyrochronatomen?",a="Lotwil Veriatus, som arbetar på en apparat i Badlands.",al={"vem ger gyro vad","uppdragsgivare gyro vad","lotwil veriatus badlands"}},{q="Vad behöver Lotwil Veriatus gyrochronatomen till?",a="Det är en liten men mycket viktig del, och med den bör Lotwil kunna slutföra projektet.",al={"varför gyrochronatom","vad bygger lotwil"}},{q="Vad är erbjudandet om Kharanos?",a="Distraherad av arbetet säger Lotwil att du gärna får komma och söka jobb om ni någonsin möts i Kharanos.",al={"lotwil kharanos","jobberbjudande kharanos"}},{q="Var kan man hitta en gyrochronatom?",a="Ingenjörer tillverkar dem, och de kan också köpas från ingenjörsleverantörer.",al={"hur får man gyrochronatom","gyrochronatom källa","var köpa gyrochronatom"}}},fp="13,180,14.358.0,15.227.1,36.93.0,53.125.0,33.72.0,35.67.0"}
P.entries["quest:716"] = {n="Stone Is Better than Cloth",s="Lucien Tosselwrench vet hur snål Lotwil kan vara och erbjuder sig att göra något för allt besvär: förtrollade armbågsskydd av de extra stenar du samlat. Det Lucien saknar är mönstrade bronsarmbågsskydd från en smed.",h="Lucien Tosselwrench vet hur snål Lotwil kan vara och erbjuder sig att göra något för allt besvär: förtrollade...",kw={"badlands","elementär sten","förtrollade armbågsskydd","lotwil veriatus","lucien tosselwrench","mönstrade bronsarmbågsskydd"},ang={["profession:Blacksmithing"]="Bronsarmbågsskydden Lucien vill ha kommer från en smed."},sec={{t="Ett tack för allt besvär",b="Efter Study of the Elements: Rock-prövningarna erkänner Lucien Tosselwrench hur snål Lotwil kan vara och vill gottgöra dig. Lucien har arbetat med de extra stenar du samlat och kan göra fina förtrollade armbågsskydd. De kan till och med skydda dig mot det Lucien kallar Lotwils senaste uppfinnings kommande vidrighet."},{t="Vad Lucien behöver",b="För att färdigställa armbågsskydden behöver Lucien mönstrade bronsarmbågsskydd av den sort en smed gör. Lucien varnar för att det är klokt att inte vänta länge, eftersom ingen vet vad som händer härnäst."}},faq={{q="Vem erbjuder sig att tillverka armbågsskydden?",a="Lucien Tosselwrench i Badlands erbjuder sig att göra förtrollade armbågsskydd av de extra stenar du samlat.",al={"vem ger stone is better than cloth","uppdragsgivare","lucien tosselwrench"}},{q="Varför tillverkar Lucien den här rustningen åt dig?",a="Lucien vet hur snål Lotwil kan vara och vill göra något för allt besvär. Den kan också hjälpa till att skydda dig mot Lotwils senaste uppfinning.",al={"varför tillverka armbågsskydd","luciens motiv","lotwil snål"}},{q="Vad behöver Lucien för att färdigställa armbågsskydden?",a="Mönstrade bronsarmbågsskydd av den sort en smed gör.",al={"vilket föremål behövs","föremål som krävs","mönstrade bronsarmbågsskydd behövs"}},{q="Vilket uppdrag kommer före det här?",a="Det följer på Lotwils tredje Study of the Elements: Rock-begäran.",al={"föregående uppdrag","förutsättning för stone is better than cloth"}}},fp="26,175,28.310.0,17.155.0,32.92.0,40.147.0,53.100.0,29.75.0"}
P.entries["quest:7162"] = {n="Proving Grounds",s="Proving Grounds är en invigningsrit som Lieutenant Haggerdin ger rekryter från Alliansen som tar värvning i Stormpike Guard i Alterac. För att förtjäna ett officiellt Stormpike Insignia måste aspiranterna ta sig in i de harpybebodda Icewing Caverns och hämta en utplacerad stridsfana. Den som bevisar sitt mod i grottorna tar första steget mot högre grader i expeditionens militär.",h="Proving Grounds är en invigningsrit som Lieutenant Haggerdin ger rekryter från Alliansen som tar värvning i...",kw={"dun baldar","haggerdin","harpyor","icewing caverns","insignia","proving grounds","stormpike","stormpike banner"},ang={["faction:Alliance"]="Stormpike-expeditionen är Alliansens främsta militära satsning i Alterac och förenar dvärgarnas arkeologiska ambitioner med territoriellt försvar mot Horden.",["race:Dwarf"]="Stormpike Guard leds till största delen av dvärgar från Ironforge som söker förfädersreliker och titanernas hemligheter. Provet är därför en väg in i en av ditt folks stoltaste militära enheter."},sec={{t="Ett prov på mod",b="Stormpike Guard bedriver ett skoningslöst fälttåg i Alterac Valley mot Frostwolf Clan. Lieutenant Haggerdin samordnar styrkorna från Alliansens läger i Alterac Mountains och vägrar skicka oerfarna rekryter ut på slagfältet utan att först pröva dem. Innan han ger en soldat en officiell plats i gardet kräver Haggerdin bevis på skicklighet och mod, och skickar dem till de förrädiska Icewing Caverns sydväst om Dun Baldar."},{t="Icewing Caverns",b="Rättegången är enkel i teorin men dödlig i praktiken: en Stormpike-fana står planterad djupt inne i de underjordiska istunnlarna. Grottorna är inte tomma; våldsamma frostharpyor häckar i de frostbitna skrymslena och sliter gärna sönder oförsiktiga inkräktare. Att återvända med fanan oskadd visar att en rekryt kan ta sig fram i farlig terräng, stå emot brutala rovdjur och behålla disciplinen under press."},{t="Stormpike Insignia",b="Den som överlever grottorna och återlämnar fanan får en Stormpike-insignia för noviser, som välkomnar soldaten officiellt till expeditionsstyrkan. Som Haggerdin lovar är insignian mer än en prydnad – den visar soldatens grad och kan förbättras när soldaten vinner större ära på slagfältet, med sikte på legendariska utmärkelser som Eye of Command."}},faq={{q="Vem är Lieutenant Haggerdin?",a="Lieutenant Haggerdin är en officer i Alliansen som är stationerad i Alterac Mountains och ansvarar för rekrytering och fältutmärkelser åt Stormpike Guard. Han prövar blivande kämpar och belönar deras tjänst med militära insignier.",al={"lieutenant haggerdin","haggerdin","vem delar ut proving grounds"}},{q="Var ligger Icewing Caverns?",a="Icewing Caverns ligger sydväst om Alliansens fäste Dun Baldar, i de frusna delarna av Alterac Valley. De är vindlande underjordiska tunnlar uthuggna ur is och sten.",al={"icewing caverns plats","var ligger icewing caverns","fanans plats"}},{q="Vilka hot finns i Icewing Caverns?",a="Grottorna bebos av våldsamma isharpyor. Lieutenant Haggerdin varnar rekryterna för att dessa vildsinta varelser inte tvekar att överfalla inkräktare och slita ut deras strupar.",al={"harpyor","vad finns i icewing caverns","icewing-harpyor"}},{q="Varför kräver Stormpike Guard det här provet?",a="Kampen mot Frostwolf-orkerna är brutal och skoningslös. Haggerdin insisterar på att sålla bort oprövade rekryter innan de ansluter sig till huvudstyrkan, så att varje soldat som bär deras fana kan strida under hårda förhållanden.",al={"varför proving grounds","varför göra fanprovet","stormpike-invigning"}},{q="Vad får man för att klara prövningen?",a="Den som klarar prövningen belönas med en Stormpike-insignia för noviser. Haggerdin uppgraderar insignian till kraftfullare varianter när soldaten samlar ära i Alterac Valley.",al={"stormpike insignia","eye of command","belöning för proving grounds"}},{q="Vilka är Frostwolves som Haggerdin nämner?",a="Frostwolf Clan är en orkklan som har levt i Alterac Valley sedan de landsförvisades för årtionden sedan. Stormpike Guard betraktar dem som fientliga vildar som står i vägen för Alliansens intressen och utgrävningar i dalen.",al={"frostwolf-vildar","vilka är frostwolves","frostwolf clan"}}},fx={b9e84d22={q="Vad är syftet med Stormpike Banner i grottorna?",a="Djupt inne i de farliga Icewing Caverns fungerar Stormpike Banner som en prövningsmarkör för rekryter som vill ta värvning i expeditionsstyrkan. För att göra anspråk på den måste du trotsa de våldsamma harpyorna som hemsöker grottorna och visa det mod, den påhittighet och den beslutsamhet som krävs av en sann Stormpike-soldat, innan du ens sätter foten på det öppna slagfältet.",al={"vad är stormpike banner","varför banner i icewing caverns","stormpike banner syfte"}}},fp="15,256,20.271.0,19.276.0,22.254.0,28.213.0,30.136.0,46.119.0,47.191.0,53.135.0,47.209.0"}
P.entries["quest:717"] = {n="Tremors of the Earth",s="Garek har kommit fram till att Blacklash och Hematus inte går att lita på när det gäller att stanna i sitt fängelse i Lethlor. Svarta drakar har flyttat in där och ogres stal Sign of the Earth, så Garek skickar dig för att befria drakarna och döda dem.",h="Garek har kommit fram till att Blacklash och Hematus inte går att lita på när det gäller att stanna i sitt...",kw={"blacklash","garek","hematus","kirin tor","krasus","lethlor ravine","runstenar","seal of the earth","sign of the earth","tremors of the earth"},ang={["faction:Alliance"]="Gareks begäran gäller Alliansen."},sec={{t="Ett fängelse som sviktar",b="Garek kan inte längre vara säker på att Blacklash och Hematus stannar fängslade. Svarta drakar bor nu i Lethlor, och ogres har kommit över Sign of the Earth. Garek anser att hårdare tag krävs och att drakarna måste dö."},{t="Bryta sigillet",b="Tre runstenar håller drakarna fångna, och bara Sign of the Earth kan hämta dem. Du använder Sign of the Earth på ametistens, opalens och diamantens pelare och placerar sedan runstenarna i Seal of the Earth. Det befriar de två drakarna, och du dödar dem. Garek vill ha tillbaka Blacklash's Bindings, Chains of Hematus och Sign of the Earth."},{t="Efter dådet",b="När drakarna är döda förklarar Garek att Kirin Tor kan sluta oroa sig för fångarna i Lethlor. Garek tänker rapportera framgången till sin mästare, Krasus, som säkert blir nöjd."}},faq={{q="Vilka är Blacklash och Hematus?",a="Drakar som hålls fångna bakom ett sigill i Lethlor.",al={"blacklash och hematus","vilka är drakarna","vad hålls fånget i lethlor"}},{q="Varför måste drakarna dödas i stället för att hållas inlåsta?",a="Garek kan inte längre vara säker på att de stannar fängslade. Svarta drakar bor nu i Lethlor, och ogres stal Sign of the Earth.",al={"varför döda blacklash","varför bryta fängelset","varför döda hematus"}},{q="Hur öppnas fängelset?",a="Tre runstenar hämtas från pelarna med Sign of the Earth och placeras sedan i Seal of the Earth.",al={"hur öppnar man seal of the earth","hur tillkallar man blacklash","hur befriar man drakarna"}},{q="Vad måste föras tillbaka till Garek?",a="Tre saker ska tillbaka till Garek: Blacklash's Bindings, Chains of Hematus och Sign of the Earth.",al={"vad ska återlämnas till garek","blacklash's bindings","chains of hematus"}},{q="Vad kommer före det här uppdraget?",a="Det följer på det tidigare Tremors of the Earth.",al={"föregående uppdrag","förutsättning för tremors of the earth"}}},fp="20,175,16.194.0,17.353.0,14.179.1,30.63.0,58.140.0,27.129.0,35.82.0,29.43.0"}
P.entries["quest:718"] = {n="Mirages",s="På flykten från utgrävningsplatsen i Uldaman lämnade Sigrun Ironhews sällskap vagnar och lådor efter sig. Ogrer från Camp Kosh tog kärran med alla deras vapen, och sedan dess har sällskapet inte haft någon mat.",h="På flykten från utgrävningsplatsen i Uldaman lämnade Sigrun Ironhews sällskap vagnar och lådor efter sig.",kw={"badlands","camp kosh","utgrävning","hägringar","ogrer","sigrun ironhew","supply crate","uldaman"},ang={["faction:Alliance"]="Sigrun Ironhew söker hjälp från Alliansen."},sec={{t="Hungriga i Badlands",b="I sin brådska att lämna utgrävningsplatsen i Uldaman lämnade Sigrun Ironhew och sällskapet många vagnar och förrådslådor efter sig. Ogrer från Camp Kosh har plockat bland resterna som gamar. De tog kärran med sällskapets alla vapen, och sedan dess har sällskapet inte haft någon mat. Sigrun medger att det är pinsamt och ber dig hämta förrådslådan."},{t="När du kommer tillbaka",b="När du kommer tillbaka erkänner Sigrun att hen svalde en munfull sand medan du var borta. Sigrun går snabbt vidare och säger att sällskapet ska ge sig ut och leta efter mat i kväll och äta som kungar."}},faq={{q="Vem är Sigrun Ironhew?",a="Sigrun Ironhew tillhör ett sällskap som lämnade utgrävningsplatsen i Uldaman i all hast och nu saknar mat i Badlands.",al={"sigrun ironhew","vem ger hägringar","vem är sigrun"}},{q="Varför svälter Sigruns sällskap?",a="Ogrer tog kärran med alla deras vapen och annat, och sedan dess har de inte kunnat få tag på någon mat.",al={"varför är de hungriga","varför finns ingen mat","sigruns matproblem"}},{q="Vem tog de övergivna förråden?",a="De lokala ogrerna från Camp Kosh, som har rotat bland utrustningen som lämnades kvar.",al={"vem stal lådan","ogrerna i camp kosh","vem tog vapnen"}},{q="Vad hoppas Sigrun få tillbaka?",a="Förrådslådan som lämnades kvar i brådskan att lämna utgrävningsplatsen.",al={"supply crate","vad ska hämtas åt sigrun"}}},fp="7,88,22.360.0,14.186.1,22.116.0,31.97.0,32.73.0,34.94.0"}
P.entries["quest:719"] = {n="A Dwarf and His Tools",s="Prospector Ryedol varnar för att Dark Iron-dvärgar som verkar tillhöra Shadowforge-klanen finns överallt. De attackerade nyss utgrävningsplatsen där Ryedol arbetade, och Ryedol vill ha tillbaka sin tursamma hacka.",h="Prospector Ryedol varnar för att Dark Iron-dvärgar som verkar tillhöra Shadowforge-klanen finns överallt.",kw={"badlands","dark iron","utgrävning","hammertoe","tursam hacka","ryedol","shadowforge"},sec={{t="Rövare vid utgrävningen",b="Enligt Prospector Ryedol attackerade Dark Iron-dvärgar från Shadowforge-klanen utgrävningsplatsen där Ryedol arbetade. De dödade nästan alla, däribland Ryedols chef Hammertoe, och Ryedol undkom nätt och jämnt med livet i behåll. Platsen ligger norr om Ryedols position."},{t="En tursam hacka",b="Ryedol funderar på hur han ska få tillbaka en del av de förlorade förråden, framför allt sin tursamma hacka. En av Dark Iron-dvärgarna måste bära på den, men det kan vara vem som helst av dem. Ryedol hoppas att du vill hjälpa till och väntar söder om Hammertoe's Dig Site."}},faq={{q="Vem är Prospector Ryedol?",a="Ryedol arbetade vid en utgrävningsplats som attackerades av Dark Iron-dvärgar. Han undkom nätt och jämnt och väntar nu söder om Hammertoe's Dig Site.",al={"vem är ryedol","prospector ryedol","vem ger uppdraget a dwarf and his tools"}},{q="Vem attackerade utgrävningslägret?",a="Dark Iron-dvärgar som verkade tillhöra Shadowforge-klanen.",al={"vem attackerade utgrävningen","vem attackerade hammertoe","vad attackerade lägret"}},{q="Vad hände med Hammertoe?",a="Hammertoe var Ryedols chef och en av dem som dödades i attacken.",al={"vem är hammertoe","lever hammertoe","vad hände med chefen hammertoe"}},{q="Var finns den tursamma hackan?",a="Ryedol tror att en av Dark Iron-dvärgarna har den, men det kan vara vem som helst av dem.",al={"var är ryedols tursamma hacka","hur hittar man hackan","vem har ryedols hacka"}}},fp="21,147,18.228.0,12.234.0,25.140.0,33.79.0,27.69.0,32.99.0"}
P.entries["quest:72"] = {n="The Legend of Stalvan",s="Det här utredningssteget leder sökarna till Stormwind Citys kanaler, där Caretaker Folsom vakar över det som återstår av den ruinerade familjen Flintridge. Äventyrare som söker svar om den gåtfulle Stalvan Mistmantle måste gå igenom packlårar med egendom samtidigt som de möter rastlösa andar med koppling till en massaker i det förflutna.",h="Det här utredningssteget leder sökarna till Stormwind Citys kanaler, där Caretaker Folsom vakar över det som...",kw={"kanaler","caretaker folsom","duskwood","flintridge","forlorn spirit","legend of stalvan","massaker","sealed crate","stormwind","tilloa"},ang={["class:Priest"]="När du konfronterar den gråtande Forlorn Spirit vid stadens kanaler blottas den kvarvarande plågan hos oskyldiga själar som mördades i förtid och nu ber Ljuset om frid.",["faction:Alliance"]="Flintridge-familjens stillsamma tragedi utspelar sig mitt i kungarikets huvudstad och visar hur även Stormwinds mest skyddade adelsätter kan slås sönder med våld."},sec={{t="Ekon från en massaker",b="Spåren efter Stalvan leder från Duskwoods skuggiga dungar till Stormwinds hjärta. Intill stadens kanaler tar Caretaker Folsom hand om det lilla som finns kvar av hushållet Flintridge. Enligt Folsom tjänade hans far godset före honom och fick det hemska uppdraget att skura bort blod efter en fasansfull massaker i hushållet – en tragedi som på något sätt har koppling till namnet Stalvan."},{t="Auktionen av ett ruinerat hus",b="Flintridge-familjens förtroendefonder är helt uttömda och kungliga skatteindrivare cirklar runt. Därför ska familjens kvarvarande arvegods och packade tillhörigheter säljas på auktion. Minnessaker och dokument som överlevde blodbadet ligger staplade i fraktlådor längs kanalbanken. För att hitta spår efter Stalvan måste du bryta upp de förseglade lådorna innan godsets sista ägodelar skingras bland samlare i hela kungariket."},{t="En rastlös skugga",b="Det går inte obemärkt förbi att du rör vid de dödas lådor. Morden har lämnat sina spår på de räddade ägodelarna och visar sig som en hämndlysten Forlorn Spirit som angriper alla som undersöker familjens tillhörigheter. Den gråtande vålnaden tros vara den unga Tilloa Flintridge och är fortfarande starkt bunden till de fysiska lämningarna av hennes liv, som rycktes ifrån henne så abrupt."}},faq={{q="Var hittar jag Caretaker Folsom?",a="Caretaker Folsom håller till vid kanalerna i Stormwind City. Han står nära en hög med övergivna fraktlådor och husgeråd intill vattenvägen.",al={"caretaker folsom plats","var finns folsom","var finns caretaker folsom i stormwind"}},{q="Vad hände med familjen Flintridge?",a="Flintridge-familjen var ett välbärgat hushåll som slets sönder av en plötslig och brutal massaker. Enligt berättelsen om godsets förvaltare var blodbadet så omfattande att Folsoms far måste skura rent godset. Det är ännu oklart vem som låg bakom dådet.",al={"flintridge-massakern","vad var massakern","vem dödade familjen flintridge"}},{q="Varför ligger familjens ägodelar packade i lådor längs kanalen?",a="Flintridge-familjens förtroendefond sinade helt efter tragedin. På grund av påtryckningar från kungarikets skatteindrivare packades godsets kvarvarande ägodelar i lådor och ställdes upp vid kanalerna för att säljas på auktion.",al={"varför auktionera ut flintridge-föremål","varför finns det lådor i kanalerna","flintridge-fond"}},{q="Varför anfaller en ande när lådan öppnas?",a="Massakerns våldsamma trauma band offrens själar till deras forna ägodelar. Forlorn Spirit, som visar sig för att försvara lådorna, tros allmänt vara skuggan av Tilloa Flintridge, ett av de mördade barnen.",al={"forlorn spirit stormwind","vem är forlorn spirit","varför finns det ett spöke i stormwinds kanaler"}},{q="Hur hänger det här ihop med Duskwood?",a="Utredningen började i Darkshire som en efterforskning om den försvunne Stalvan Mistmantle. När hans förflutna följdes upp ledde spåren tillbaka till tiden då han var lärare åt familjen Flintridge i Elwynn och Stormwind.",al={"stalvans koppling till duskwood","varför är vi i stormwind på ett duskwood-uppdrag","legend of stalvan koppling till staden"}},{q="Vad hittar man i den förseglade lådan?",a="När du letar igenom de packade möblerna och personliga föremålen hittar du dammiga arvegods och, nära botten, en trasig sida ur Stalvans dagbok som ger nästa ledtråd.",al={"vad finns i lådan","ledtråd i sealed crate","innehållet i flintridge-lådan"}}},fx={d6eccd2d={q="Varför låter Caretaker Folsom dig söka igenom lådorna?",a="Caretaker Folsom har personligen föga kvar att ta hand om. Familjen Flintridges förvaltningsfond har sinat helt, vilket har lämnat deras återstående egendom i ruiner och deras sista ägodelar på väg till auktionshuset för att betala skatteindrivarna. Hans familj tjänade godset i generationer, och hans far städade upp efter den fruktansvärda massakern. Folsom själv har ingen anledning att dölja den dystra sanningen och låter dig helt enkelt stilla din nyfikenhet bland det som återstår.",al={"caretaker folsoms motiv","varför hjälper folsom","varför låta mig söka i lådorna"}}},fp="21,200,20.302.0,29.320.0,16.262.1,34.133.0,39.167.0,66.167.0,50.210.0,39.167.0,41.155.0"}
P.entries["quest:720"] = {n="A Sign of Hope",s="En skrynklig karta bär några ord skrivna med krita: en vädjan från Hammertoe till Ryedol. Hammertoe säger att de för honom till Uldaman och ber om hjälp. Prospector Ryedol bör få veta att Hammertoe Grez lever.",h="En skrynklig karta bär några ord skrivna med krita: en vädjan från Hammertoe till Ryedol.",kw={"ett tecken på hopp","badlands","kritanteckning","skrynklig karta","hammertoe grez","prospector ryedol","uldaman"},sec={{t="Ord skrivna med krita",b="På den skrynkliga kartan finns en kort anteckning, hastigt skriven med krita och undertecknad av Hammertoe. Den är adresserad till Ryedol och säger bara att de för Hammertoe till Uldaman och att hjälp behövs. Budskapet till Prospector Ryedol är att Hammertoe Grez lever."}},faq={{q="Vad står det på den skrynkliga kartan?",a="En anteckning med krita, adresserad till Ryedol och undertecknad Hammertoe. Där står att de för Hammertoe till Uldaman och ber om hjälp.",al={"vad står det i anteckningen","kritmeddelande på kartan","text på skrynklig karta"}},{q="Vem är Prospector Ryedol?",a="Han är den som anteckningen är avsedd för. Du ska söka upp Prospector Ryedol och berätta att Hammertoe Grez lever.",al={"vem är ryedol","vart ska den skrynkliga kartan lämnas"}},{q="Vart säger meddelandet att Hammertoe Grez förs?",a="Till Uldaman.",al={"vart förs hammertoe","vart förs grez"}}},fp="14,141,14.188.0,36.110.0,25.97.0,57.58.0"}
P.entries["quest:723"] = {n="Prospect of Faith",s="Hammertoe Grez, sårad och medtagna krafter, skickar dig med amuletten till Prospector Ryedol i Badlands. Ryedol vet vad Hammertoe sökte efter och vad Shadowforge-klanen inte får tillåtas hitta.",h="Hammertoe Grez, sårad och medtagna krafter, skickar dig med amuletten till Prospector Ryedol i Badlands.",kw={"a sign of hope","badlands","hammertoe grez","hammertoes amulett","ursprung","prospector ryedol","shadowforge"},sec={{t="En amulett till Ryedol",b="Hammertoe Grez håller sig om såren och stannar upp för att hämta andan. Sedan ber han dig hitta Ryedol och lämna över amuletten. Hammertoe är säker på att Ryedol kommer att lista ut vad han ska göra. Ryedol vet att Hammertoe sökte efter sitt folks ursprung och att Hammertoe också ville sätta stopp för Shadowforge-klanen, som inte får tillåtas komma över skriftrullarna."},{t="I Ryedols händer",b="När Ryedol får Hammertoes amulett säger han att modet var större när Hammertoe troddes vara död, eftersom vissheten bara gör smärtan värre. Ryedol kallar amuletten Hammertoes livsverk och lovar att dödsfallet inte ska ha varit förgäves."}},faq={{q="Vem är Prospector Ryedol?",a="Prospector Ryedol är den du ska ta Hammertoes amulett till i Badlands. Ryedol vet vad Hammertoe sökte efter.",al={"prospector ryedol","vem är ryedol","var finns ryedol"}},{q="Vad försöker Hammertoe Grez stoppa?",a="Hammertoe ville sätta stopp för Shadowforge-klanen, som inte får tillåtas komma över skriftrullarna.",al={"hammertoes syfte","shadowforge-skriftrullar","varför stoppa shadowforge"}},{q="Vad sökte Hammertoe Grez efter?",a="Sitt folks ursprung, enligt Hammertoe.",al={"hammertoes ursprung","vad letade hammertoe efter"}},{q="Vilken uppdragskedja ingår det här steget i?",a="Det här ingår i kedjan som började med A Sign of Hope.",al={"prospect of faith-kedjan","a sign of hope-kedjan"}}},fp="17,194,20.238.0,17.232.1,25.121.0,38.87.0,32.50.0,33.62.0"}
P.entries["quest:724"] = {n="Prospect of Faith",s="Prospector Ryedol skickar dig till Ironforge med Hammertoe's Amulet. Historian Karnik och Hammertoe samarbetade för att hitta Uldamans förlorade artefakter, och Ryedol gissar att Shadowforge upptäckte att de båda visste mer än de lät förstå.",h="Prospector Ryedol skickar dig till Ironforge med Hammertoe's Amulet.",kw={"badlands","hammertoe","hammertoes amulet","historian karnik","ironforge","prospect of faith","prospector ryedol","shadowforge","uldaman"},sec={{t="Ett meddelande till Ironforge",b="Ryedol funderar på vem som kan veta vad nästa steg är och bestämmer sig för Historian Karnik, som befinner sig i Ironforge. Du ska berätta för Karnik vad som hänt Hammertoe och lämna amuletten i historikerns händer. Karnik säger vad som behöver göras sedan."},{t="Karniks välkomnande",b="Karnik hälsar dig som ännu en resenär som ber om tid, och har ingen att avvara, förrän du visar amuletten. Då tar Karnik saken på allvar, skjuter upp sorgen över Hammertoe och visar varför amuletten är så värdefull genom att kalla fram Hammertoes ande."}},faq={{q="Vem ger uppdraget?",a="Prospector Ryedol i Badlands skickar dig vidare till Ironforge med Hammertoe's Amulet.",al={"vem ger prospect of faith","prospect of faith uppdragsgivare","var börjar prospect of faith"}},{q="Var befinner sig Historian Karnik?",a="Historian Karnik befinner sig i Ironforge.",al={"var finns karnik","historian karniks plats","karnik ironforge"}},{q="Varför valdes Historian Karnik?",a="Karnik och Hammertoe samarbetade för att hitta Uldamans förlorade artefakter, så Ryedol litar på att Karnik vet vad som ska göras.",al={"varför skicka amuletten till karnik","karniks koppling"}},{q="Vad händer efter det här uppdraget?",a="Karniks del av berättelsen fortsätter med Passing Word of a Threat.",al={"nästa uppdrag efter prospect of faith","vad följer efter prospect of faith"}}},fp="17,228,23.171.0,16.190.1,22.81.0,34.33.0,32.111.0,28.55.0"}
P.entries["quest:725"] = {n="Passing Word of a Threat",s="Historian Karnik ger dig en förseglad lapp till Advisor Belgrum. Berätta för Belgrum vad du har bevittnat och fråga hur Belgrum vill gå vidare, medan Karnik vänder sig till Hammertoe's ande om Shadowforge i Badlands.",h="Historian Karnik ger dig en förseglad lapp till Advisor Belgrum.",kw={"advisor belgrum","badlands","hammertoe","historian karnik","ironforge","passing word of a threat","shadowforge"},sec={{t="Meddelande till Advisor Belgrum",b="Karnik vill att du snabbt hittar Advisor Belgrum, berättar vad du har sett och frågar hur Belgrum vill gå vidare. Lappen berättar mer. Under tiden ska Karnik tala med Hammertoe's ande i hopp om att Hammertoe vet något som kan sätta stopp för Shadowforges verksamhet i Badlands. Karnik kan bara hoppas att så är fallet."}},faq={{q="Vem skickar dig till Advisor Belgrum?",a="Historian Karnik räcker dig en förseglad lapp och ber dig hitta Advisor Belgrum så fort du kan.",al={"vem startar passing word of a threat","vem ger passing word of a threat","karnik uppdrag"}},{q="Vad vill Karnik att du ska säga till Advisor Belgrum?",a="Karnik vill att du berättar för Belgrum vad du har bevittnat och frågar hur Belgrum vill gå vidare. Lappen berättar mer.",al={"varför besöka belgrum","syftet med belgrums lapp","varför skicka lappen"}},{q="Vad gör Historian Karnik medan du levererar lappen?",a="Karnik tar sig tid att tala med Hammertoe's ande i hopp om att få veta något som kan hjälpa till att stoppa Shadowforge i Badlands.",al={"vad gör karnik","karniks plan","historian karnik badlands"}},{q="Vilket uppdrag kommer före Passing Word of a Threat?",a="Det följer efter Prospect of Faith, uppdraget där du tar Hammertoe's amulet till Karnik i Ironforge.",al={"förutsättning för passing word","föregående uppdrag till passing word of a threat","tidigare uppdrag"}}},fp="24,162,24.336.0,33.100.0,43.108.0,58.124.0,49.109.0"}
P.entries["quest:726"] = {n="Passing Word of a Threat",s="Advisor Belgrum har läst Historian Karniks meddelande och skickar dig tillbaka till Karnik med ett bud på kungens vägnar: agera snabbt och beslutsamt utifrån det som är känt, och stoppa Shadowforges verksamhet i Badlands.",h="Advisor Belgrum har läst Historian Karniks meddelande och skickar dig tillbaka till Karnik med ett bud på...",kw={"angor fortress","badlands","belgrum","karnik","shadowforge","uldaman"},sec={{t="Belgrums svar",b="Belgrum läser meddelandet till slut med allt större ögon och kallar nyheten ond. Du ska återvända till Karnik och framföra att informationen måste omsättas i handling snabbt och beslutsamt, på kungens vägnar. Shadowforges verksamhet i Badlands måste stoppas."},{t="Karniks svar",b="Karnik tar brådskan på största allvar och har en plan redo: Shadowforge i Uldaman kan hejdas genom ett slag mot Angor Fortress, därifrån de sköter sina operationer."}},faq={{q="Vem skickar dig tillbaka till Karnik?",a="Advisor Belgrum, efter att ha läst Karniks meddelande. Du bär med dig ett bud på kungens vägnar om att agera snabbt och beslutsamt.",al={"vem ger ordern","belgrum ger order","kunglig order badlands"}},{q="Vad vill Belgrum att man gör åt Shadowforge?",a="Belgrum vill att Karnik agerar snabbt och bestämt och sätter stopp för det Shadowforge gör i Badlands.",al={"vad vill belgrum","shadowforge order badlands"}},{q="Vad hände före detta?",a="Du tog med Karniks förseglade meddelande till Advisor Belgrum i det tidigare uppdraget Passing Word of a Threat, som följde på stegen i Prospect of Faith.",al={"föregående steg","uppdraget före passing word of a threat","uppladdning inför badlands"}}},fp="24,113,16.229.0,14.154.1,29.119.0,50.99.0,22.127.0"}
P.entries["quest:727"] = {n="To Ironforge for Yagyin's Digest",s="Theldurin the Lost skickar dig till Ironforge med ett sigill. I en butik i Forlorn Cavern ska Gerrig Bonegrip ta dig för en av dem som Theldurin flydde från, och du ska be Gerrig om Yagyin's Digest.",h="Theldurin the Lost skickar dig till Ironforge med ett sigill.",kw={"badlands","forlorn cavern","gerrig bonegrip","ironforge","sigil of the hammer","theldurin the lost","yagyin's digest"},sec={{t="En bok skriven för länge sedan",b="The Tablet berättar mycket för Theldurin, men långt ifrån tillräckligt. Yagyin skrev en sammanfattning för länge sedan, och de som Theldurin flydde från har kopior på många platser, där deras lärdaste studerar den. Theldurin tror att den rymmer stor kunskap som kan ge skydd och vill att du tar med den tillbaka."},{t="Butiken i Forlorn Cavern",b="Gerrig Bonegrip har en butik i Forlorn Cavern i Ironforge. Theldurin ger dig Sigil of the Hammer att visa Gerrig, så att Gerrig ska tro att du är en av dem, och du ska be om Yagyin's Digest."},{t="Gerrigs hälsning",b="Gerrig varnar dig för att vara försiktig med vad du rör vid i butiken, för kunskap kan vara dödlig. När sigillet visas hälsar Gerrig dig som broder eller syster och prisar dem som bor därunder."}},faq={{q="Varför vill Theldurin ha Yagyin's Digest?",a="The Tablet berättar mycket för Theldurin, men inte tillräckligt. Sammanfattningen, som Yagyin skrev för länge sedan, rymmer stor kunskap som kan ge skydd, och Theldurin vill att du tar med den tillbaka.",al={"varför behövs yagyins digest","vad är yagyins digest","yagyins digest syfte"}},{q="Var finns Gerrig Bonegrip?",a="Gerrig Bonegrip finns i en butik i Ironforges Forlorn Cavern.",al={"var finns gerrig bonegrip","gerrig bonegrips plats","vem är gerrig"}},{q="Vad används Sigil of the Hammer till?",a="Theldurin ger dig det att visa Gerrig Bonegrip, så att Gerrig ska tro att du är en av dem som Theldurin flydde från.",al={"vad gör sigillet","sigil of the hammer användning","varför använda sigillet"}},{q="Var passar det här in i kedjan?",a="Det kommer efter Solution to Doom, med Theldurin the Lost, och kedjan fortsätter i nästa steg.",al={"vad kommer före to ironforge for yagyins digest","yagyin kedjeordning"}}},fp="32,203,23.272.0,30.214.0,17.185.1,40.186.0,25.53.0,41.134.0,33.92.0"}
P.entries["quest:728"] = {n="To the Undercity for Yagyin's Digest",s="Theldurin the Lost skickar dig till Undercity i Lordaeron med en sigill. Keeper Bel'dugur ska tro att du är en av dem Theldurin flydde från, och du ska be Keeper om Yagyin's Digest.",h="Theldurin the Lost skickar dig till Undercity i Lordaeron med en sigill.",kw={"badlands","bel'dugur","sammanfattning","hammare","sigill","theldurin","undercity","yagyin"},sec={{t="En bok skriven för länge sedan",b="Stentavlan berättar mycket för Theldurin, men långt ifrån tillräckligt. Yagyin skrev en sammanfattning för länge sedan, och folket som Theldurin flydde från har kopior på många platser, där de lärdaste studerar den. Theldurin tror att den rymmer stor kunskap som kan skydda dem, och vill att den hämtas tillbaka."},{t="Keeper i Undercity",b="Keeper Bel'dugur finns i Undercity i Lordaeron. Theldurin ger dig Sigil of the Hammer att visa Keeper, så att du ska tas för en av dem, och du ska be om sammanfattningen."},{t="En varning",b="Bel'dugur hälsar dig som en ivrig sökare efter samlingen och varnar för att kunskap ger de starka makt men driver de svaga till vansinne. När sigillen har visats uppmanar Bel'dugur dig att vara diskret med sådana tecken. Vissa tror inte på att deras löfte är rättfärdigt, och andra skulle vilja se dem misslyckas om de fick veta om dem. De som delar löftet måste alltid vara försiktiga, vaksamma och tålmodiga."}},faq={{q="Vem skickar dig till Undercity?",a="Theldurin the Lost skickar dig med Sigil of the Hammer för att hitta Keeper Bel'dugur.",al={"vem startar det här uppdraget","vem ger uppdraget till undercity for yagyin's digest","uppdragsgivare"}},{q="Vad är Sigil of the Hammer till för?",a="Theldurin ger dig den att visa Keeper Bel'dugur, så att Keeper ska tro att du är en av dem Theldurin flydde från.",al={"vad sigil of the hammer används till","varför behöver jag sigillen","vad gör sigillen"}},{q="Vad är Yagyin's Digest?",a="Det är en bok som Yagyin skrev för länge sedan. Theldurin säger att den rymmer stor kunskap och studeras av de lärdaste bland folket som Theldurin flydde från.",al={"vad är yagyin's digest","vem är yagyin","yagyins bok"}},{q="Var finns Keeper Bel'dugur?",a="Keeper Bel'dugur håller till i Undercity i Lordaeron, där du hittar Keeper.",al={"keeper bel'dugurs plats","var hittar man keeper bel'dugur","bel'dugur i undercity"}},{q="Vad kom före det här?",a="Den följer efter Solution to Doom.",al={"föregående uppdrag","vad kommer före det här","kopplingen till solution to doom"}}},fp="36,197,23.281.0,27.197.0,17.375.1,31.101.0,36.135.0,24.142.0,26.50.0,22.34.0"}
P.entries["quest:729"] = {n="The Absent Minded Prospector",s="Archaeologist Hollee flydde till Auberdine efter att fientliga stengolemer intagit en utgrävningsplats i södra Darkshore. Förskräckt för sin äldre kollega ber hon resenärer skynda söderut och rädda Prospector Remtravel, en ansedd dvärgforskare som är ökänd för att inte märka dödsfara när han är uppslukad av sin forskning.",h="Archaeologist Hollee flydde till Auberdine efter att fientliga stengolemer intagit en utgrävningsplats i...",kw={"auberdine","darkshore","explorers' league","fossil","golemer","greywhisker","hollee","remtravel"},ang={["faction:Alliance"]="Uppdraget visar hur forskare från Ironforge samarbetar för att studera de okända, forntida länderna i Kalimdor, där deras nattalviska allierade bor.",["race:Dwarf"]="För dvärgar förkroppsligar Remtravel Explorers' Leagues tvångsmässiga nyfikenhet och tunnelseende: han riskerar gärna liv och lem för ett fossil som inte katalogiserats."},sec={{t="En farlig utgrävning",b="Archaeologist Hollee skickades över havet av Explorers' League på order av Master Greywhisker och var överlycklig över att få gå i lära hos Prospector Remtravel. Remtravel var känd i Ironforges akademiska kretsar för sina banbrytande upptäckter och skickades för att undersöka forntida ruiner längs Darkshores otämjda kust. Men under en utgrävning av det som verkade vara lämningarna efter en forntida, storslagen civilisation bröt våldsamma stengolemer fram ur jorden och intog snabbt utgrävningsplatsen."},{t="Ovetande om undergången",b="Medan Hollee flydde i panik till den nattalviska hamnen Auberdine för att söka hjälp, reagerade Remtravel knappt. Helt uppslukad av relikerna han grävt fram stod den åldrige prospektören kvar till knäna i rasmassor, fullständigt oberörd av de klumpiga konstruktionerna runt lägret. Den som når honom söder om Auberdine finner honom inte hukande av rädsla, utan muttrande om saknade stenborstar och förlagda fossiler."}},faq={{q="Vem är Prospector Remtravel?",a="Prospector Remtravel är en hyllad dvärgforskare i Ironforges Explorers' League. Han är berömd i dvärgarnas akademier för sina monumentala upptäckter och lika ökänd för sin extrema brist på situationsmedvetenhet när värdefulla reliker finns i närheten.",al={"remtravel","prospector remtravel berättelse","vem är prospektören"}},{q="Varför är Archaeologist Hollee i Auberdine?",a="Hollee tilldelades som assistent åt Remtravel av Master Greywhisker. När farliga golemer kom upp ur marken vid deras utgrävningsplats flydde hon norrut till Auberdine för att hämta förstärkning inför en räddningsinsats.",al={"archaeologist hollee","hollee auberdine","varför flydde hollee"}},{q="Vad grävde dvärgarna ut i Darkshore?",a="Expeditionen hade funnit tecken på ett forntida, avancerat samhälle begravt under Darkshore. Remtravel upptäckte ett mystiskt fossil och diverse stenföremål innan underjordiska konstruktioner tog över platsen.",al={"vad grävde remtravel efter","utgrävningsplatsen i darkshore","remtravel fossil"}},{q="Var finns Prospector Remtravel?",a="Remtravel finns i södra Darkshore, bland forntida ruiner söder om Auberdine. Han är omringad av farliga golemer och letar maniskt efter sin stenborste och sitt fossil.",al={"var finns remtravel","remtravels plats","hitta prospector remtravel"}},{q="Vem skickade expeditionen till Darkshore?",a="Expeditionen organiserades av Explorers' League i Ironforge och fick sitt uppdrag direkt av Master Greywhisker, som gav Hollee i uppgift att hjälpa Remtravel att katalogisera regionens forntida underverk.",al={"vem skickade hollee","master greywhisker","explorers' league darkshore"}},{q="Är Remtravel verkligen i fara?",a="Ja. Fientliga golemer strövar omkring bland ruinerna alldeles intill honom. Remtravel är omedveten om det omedelbara hotet och fokuserar helt på att katalogisera sina fynd och undrar vart hans verktyg och assistent har tagit vägen.",al={"är remtravel död","remtravel lever","hjälp remtravel"}}},fx={["90475777"]={q="Varför vill Archaeologist Hollee att det här blir gjort?",a="Hollee var överlycklig över att få studera under Prospector Remtravel, en berömd forskare från Ironforge Explorers' League. Men när fientliga golems vällde fram från utgrävningsplatsen var Remtravel så djupt försjunken i sitt arbete att han inte märkte faran. Hollee flydde till Auberdine för att hämta förstärkningar, skräckslagen över att hennes mentor kommer att dödas om någon inte får ut honom ur ruinerna.",al={"varför behöver hollee hjälp","hollees motiv","varför leta efter remtravel"}},["1b9bcac6"]={q="Varför ber Hollee dig att se till Remtravel i stället för att gå själv?",a="Hollee undkom nätt och jämnt utgrävningsplatsen med livet i behåll när stengolemerna vaknade. Hon är skräckslagen och saknar stridsförmågan att ensam kämpa sig igenom de fientliga konstrukterna. Därför måste hon stanna i trygghet i Auberdine och förlita sig på kapabla äventyrare på genomresa som vågar sig tillbaka in i striden för att se till hennes mentor.",al={"varför jag, hollee","varför går inte hollee tillbaka","varför hjälper inte auberdine"}}},fp="28,221,14.427.0,17.354.0,28.215.0,41.166.0,46.205.0,40.191.0,38.186.0,30.178.0"}
P.entries["quest:730"] = {n="Trouble In Darkshore?",s="Trouble in Darkshore? är ett introduktionsuppdrag för Alliansen från Chief Archaeologist Greywhisker i Darnassus. Efter veckor utan ett livstecken från ett utgrävningsteam han skickat över havet ber han resenärer ta sig till Auberdine och undersöka varför de försvunnit. Uppdraget knyter ihop dvärgarnas lärda expedition med Darkshores vilda, skuggiga kust.",h="Trouble in Darkshore?",kw={"arkeolog","auberdine","darkshore","darnassus","explorers league","greywhisker","hollee","trouble in darkshore"},ang={["faction:Alliance"]="Uppdraget visar hur samarbetet mellan Ironforge och Darnassus växer och förbinder resenärer mellan Teldrassil och Kalimdors fastland.",["race:Dwarf"]="För dvärgar anknyter uppdraget till Explorer's League-traditionen att utforska titanernas historia och forntiden på nya kontinenter.",["race:NightElf"]="Nattalver kan betrakta de hackförsedda dvärgiska utgrävarnas ankomst till deras förfäders kustruiner med försiktig munterhet eller stilla oro."},sec={{t="En tyst expedition",b="I nattalvernas storslagna huvudstad Darnassus utforskar dvärgiska forskare från Ironforge Kalimdors uråldriga mysterier. Chief Archaeologist Greywhisker skickade en utgrävningsgrupp över vattnet till Darkshore för att gräva fram forntida föremål. När veckor går utan ett enda brev eller en lägesrapport blir Greywhisker orolig. Han fruktar att fältgruppen råkat ut för faror de inte var rustade att överleva på egen hand."},{t="Hot under jorden",b="Greywhisker beklagar att många i Alliansen avfärdar dvärgisk arkeologi som en excentrisk hobby. Fynd i Khaz Modan har dock övertygat hans kollegor om att en uråldrig och skrämmande kraft hotar Azeroth, från Lordaeron till Kalimdor. Att gräva i Darkshores ruiner är inte bara ett akademiskt arbete. Det handlar om att förstå historiska katastrofer och djupt rotade hot begravda under forntida jord."},{t="Kontakt i Auberdine",b="När resenärerna seglar över sundet från Teldrassil till kuststaden Auberdine väntar Archaeologist Hollee i staden. Lättad över att Chief Archaeologist skickat hjälp avslöjar Hollee att expeditionen verkligen befinner sig i knipa. De råkade ut för problem längre ner längs kusten när de letade efter forntida reliker."}},faq={{q="Vem startar uppdraget Trouble in Darkshore?",a="Chief Archaeologist Greywhisker erbjuder uppdraget i nattalvernas huvudstad Darnassus. Han söker modiga äventyrare som kan undersöka vad som hänt hans försvunna besättning.",al={"vem ger trouble in darkshore","uppdragsgivare för trouble in darkshore","var får man trouble in darkshore"}},{q="Vart behöver jag gå för att slutföra uppdraget?",a="Du behöver resa från Darnassus över havet till hamnstaden Auberdine i Darkshore, där du hittar Archaeologist Hollee.",al={"vart ska jag gå","plats för inlämning","vem lämnar jag in uppdraget till"}},{q="Varför befinner sig dvärgiska arkeologer i Darnassus och Darkshore?",a="Efter nya upptäckter i Khaz Modan började dvärgiska forskare undersöka forntida platser i Kalimdor för att hitta ledtrådar om uråldriga krafter som hotar Azeroth.",al={"varför är dvärgar i darnassus","dvärgar i darkshore","dvärgisk arkeologi i kalimdor"}},{q="Vad händer när jag hittar Archaeologist Hollee?",a="Om du talar med Archaeologist Hollee i Auberdine får du direkt uppdraget 'The Absent Minded Prospector', där du ska ge dig ut i Darkshores vildmark för att hitta Prospector Remtravel.",al={"what comes next","uppföljningsuppdrag","nästa uppdrag"}},{q="Varför har utgrävningsgruppen inte hört av sig?",a="Gruppen råkade ut för oväntade faror och motgångar ute i Darkshores vildmark. Medlemmarna skildes åt och kunde inte längre kommunicera med Darnassus.",al={"vad hände med utgrävningen","varför försvann de","saknad besättning"}},{q="Vilket hotande hot syftar Greywhisker på?",a="Greywhisker syftar på fynd i Khaz Modan som tyder på en uråldrig, utbredd fara som slumrar djupt bland Azeroths historiska ruiner.",al={"vilket uråldrigt hot","greywhiskers varning","hotet i khaz modan"}}},fx={["0c1ca2fe"]={q="Varför vill Chief Archaeologist Greywhisker att det här blir gjort?",a="Chief Archaeologist Greywhisker har inte hört av sin utgrävningsgrupp i Darkshore på flera veckor. Efter illavarslande upptäckter i Khaz Modan som avslöjar ett mäktigt och uråldrigt hot mot hela Azeroth har han inte råd att tappa kontakten med sina forskare, särskilt eftersom deras arbete är avgörande för att avslöja farorna som närmar sig.",al={"greywhiskers motiv","varför skicka till darkshore","varför hitta utgrävningsgruppen"}}},fp="21,205,19.359.0,16.403.0,20.286.1,42.110.0,45.102.0,58.154.0,48.175.0,45.147.0,48.134.0"}
P.entries["quest:731"] = {n="The Absent Minded Prospector",s="Långt inne bland Darkshores södra ruiner vägrar Prospector Remtravel att överge sin utgrävningsplats utan ett fynd att visa upp för Explorers' League. Trots att han är mycket glömsk och att platsen kryllar av fientliga trogger insisterar han på att hitta ett mystiskt fossil innan han drar sig tillbaka. Om du ser till att den dvärglika forskaren överlever sitt irrande sökande kan besked om att han är oskadd nå hans assistent i Auberdine.",h="Långt inne bland Darkshores södra ruiner vägrar Prospector Remtravel att överge sin utgrävningsplats utan ett...",kw={"auberdine","darkshore","eskort","utgrävning","explorers' league","fossil","hollee","remtravel","trogger"},ang={["faction:Alliance"]="Att rädda Remtravel och hans fynd upprätthåller ett viktigt diplomatiskt och vetenskapligt samarbete mellan dvärgarnas Explorers' League och nattalverna i Teldrassil.",["race:Dwarf"]="För dvärgar förkroppsligar Remtravel både Explorers' Leagues obevekliga passion och dess farliga envishet. Han visar hur hängivenhet åt titanernas forntida lärdomar kan få en forskare att blunda för omedelbar fara.",["race:NightElf"]="Kaldorei ser i allmänhet med misstänksamhet på dvärgiska utgrävningar i Darkshore. När Remtravel gräver upp en här av våldsamma trogger bekräftas deras farhågor om att gräva för djupt i helig mark."},sec={{t="En farlig utgrävning",b="Remtravels utgrävning ligger långt söderut i Darkshore, bland forntida ruiner som skulle rymma bortglömda hemligheter. I stället grävde de dvärgiska utgrävarna fram boningar med vilda trogger, som drev bort arbetarna och belägrade lägret. De flesta skulle genast fly till Auberdine, men Prospector Remtravel blev besatt av att rädda sina fynd. Han vägrar att ge sig av tomhänt och vandrar rakt in i faran för att hitta ett svårfångat fossil och rättfärdiga expeditionens kostnader inför Explorers' League."},{t="Förvirrade minnen och troggöverfall",b="Att skydda Remtravel är lika frustrerande som farligt. Hans tankspriddhet får honom att gå i cirklar över utgrävningsplatsen, missta borstar för fossil och snubbla förbi byggnadsställningar och övergivna tält. Varje stopp drar till sig uppmärksamheten från aggressiva trogger som lurar i stenbrottets skuggiga skrymslen. Först när du eskorterat honom genom våg efter våg av underjordiska bestar minns forskaren till slut var fyndet finns: han gav redan fossilet till Hollee, och går glatt tillbaka till arbetet."}},faq={{q="Vem är Prospector Remtravel?",a="Prospector Remtravel är en erfaren fältforskare i dvärgarnas Explorers' League. Han är stationerad i Darkshore och har fått i uppdrag att gräva ut forntida ruiner längs kusten, men hans extrema tankspriddhet försätter honom ofta i livsfarliga situationer.",al={"remtravel","vem är prospector","den glömske prospector"}},{q="Varför är Remtravel kvar vid utgrävningen?",a="Trots att trogger har tagit över utgrävningen vägrar Remtravel att återvända till Darnassus utan konkreta bevis på sitt arbete. Han insisterar på att hitta ett mystiskt fossil att visa Explorers' League innan han överväger att överge lägret.",al={"varför stanna vid utgrävningen","varför är remtravel där","varför har han inte flytt"}},{q="Varifrån kom troggerna?",a="Precis som vid många dvärgiska utgrävningar grävde Remtravels grupp djupt ner i marken och råkade bryta igenom till underjordiska hålor där trogger levde. De primitiva varelserna vällde upp i stora mängder och tog med våld över maskiner, tält och arbetare.",al={"varför finns det trogger i darkshore","trogger i darkshore","trogger vid utgrävningen"}},{q="Vem är Archaeologist Hollee?",a="Archaeologist Hollee är Remtravels kollega och assistent, baserad i kuststaden Auberdine. Hon är förtvivlad över att hennes mentor varit borta så länge och känner väl till hans glömska. Därför anlitar hon resenärer för att leta reda på honom och se till att han kommer tillbaka oskadd.",al={"hollee","archaeologist hollee","remtravels assistent"}},{q="Vad händer när man hittar fossilet?",a="När du har hjälpt Remtravel att leta vid utgrävningen ska du rapportera att han är oskadd till Archaeologist Hollee i Auberdine.",al={"fortsättning på uppdraget","vad händer sedan","efter eskorteringen av remtravel"}}},fx={["6ea255c4"]={q="Varför vill Prospector Remtravel hitta fossilet?",a="Remtravel är pressad av Explorers' League-avdelningen i Darnassus att bevisa att han faktiskt har gjort framsteg vid utgrävningsplatsen. Trots att han är väldigt förvirrad och glömsk vet han att han måste visa konkreta resultat, närmare bestämt det mystiska fossilet och sina skriftliga fynd, för att rättfärdiga expeditionen och tillfredsställa sina överordnade.",al={"remtravels motiv","varför söka efter fossilet","varför hitta fossilet åt remtravel"}},["4634f683"]={q="Varför behöver Remtravel din hjälp med att söka igenom utgrävningen?",a="Utgrävningsplatsen har tagits över av fientliga troggar, och Remtravel är en tankspridd forskare, ingen härdad krigare. Han är helt fixerad vid att återfå sina förlorade föremål och anteckningar och är därför helt skyddslös mot bakhåll när han vandrar genom utgrävningsplatsen utan någon beväpnad som vaktar hans rygg.",al={"varför behöver remtravel en eskort","varför behöver remtravel skydd","varför söker inte remtravel ensam"}}},fp="28,251,21.333.0,35.415.1,28.223.0,39.180.0,31.175.0,28.213.0,38.98.1"}
P.entries["quest:732"] = {n="Tremors of the Earth",s="Garek har hört av Sigrun hur mycket du har hjälpt till och ber dig nu om hjälp. Gareks mästare, Krasus från Kirin Tor, skickade honom för att stoppa det som är på gång i Lethlor Ravine, och först måste en stulen Sign of the Earth hittas.",h="Garek har hört av Sigrun hur mycket du har hjälpt till och ber dig nu om hjälp.",kw={"angor fortress","camp boff","dark iron","deathwing","garek","kirin tor","krasus","lethlor ravine","sign of the earth"},sec={{t="En hemlighet väl bevarad",b="Krasus från Kirin Tor, Gareks mästare, skickade Garek till Badlands för att stoppa problemen som är på gång i Lethlor Ravine. Det exakta uppdraget kan inte avslöjas, bara att det är av stor betydelse. En grupp strövande ogres, som då och då har setts kring Camp Boff, tog Sign of the Earth, och Garek behöver få tillbaka den. Återlämna den, så får du veta mer."},{t="De strövande ogres",b="Ogres flyttar mellan läger runt om i Badlands, och stigande hetta och virvlande vindar gör dem svåra att spåra. Garek har hört att de ibland passerar genom Camp Boff, som är ett bra ställe att leta på om du tappar bort dem."},{t="Garek förklarar",b="När du återvänder med Sign berättar Garek att Dark Iron-dvärgarna i Angor Fortress skapade den för att binda Deathwings två löjtnanter, de skoningslösa Blacklash och Hematus."}},faq={{q="Vem arbetar Garek för?",a="Gareks mästare är Krasus från Kirin Tor, som skickade Garek till Badlands för att stoppa problemen som är på gång i Lethlor Ravine.",al={"vem skickade garek","gareks mästare","krasus badlands"}},{q="Vad är Sign of the Earth?",a="Strövande ogres stal den, och Garek behöver få tillbaka den. Garek berättar mer när du har hämtat den.",al={"sign of the earth","vad är sign of the earth","sign of the earths historia"}},{q="Var finns de strövande ogres?",a="De strövar mellan sina läger runt om i Badlands, och Garek har hört att de ibland passerar genom Camp Boff.",al={"var finns ogres","ogrelägret camp boff","var finns sign of the earth"}},{q="Varför håller Garek uppdraget hemligt?",a="Garek vill inte säga vad uppdraget går ut på eller vilket arbete det kräver, bara att det är livsviktigt.",al={"varför hemligt","gareks hemliga uppdrag"}}},fp="20,219,19.300.0,19.211.0,14.168.1,25.115.0,30.98.0,39.104.0,42.100.0"}
P.entries["quest:7321"] = {n="Soothing Turtle Bisque",s="Soothing Turtle Bisque är ett matlagningsuppdrag som Christoph Jeffcoat erbjuder i Tarren Mill. Den Forsaken-kocken vill motbevisa föreställningen att de odöda saknar matlagningskonst genom att laga en mustig buljong på lokalt snapjaw-kött. Du måste jaga sötvattenssköldpaddor längs vattendragen i Hillsbrad Foothills och stränderna vid Lordamere Lake för att bemästra hans uppskattade recept.",h="Soothing Turtle Bisque är ett matlagningsuppdrag som Christoph Jeffcoat erbjuder i Tarren Mill.",kw={"christoph jeffcoat","matlagning","hillsbrad foothills","lordamere lake","snapjaw","soothing turtle bisque","tarren mill","sköldpaddskött"},ang={["faction:Horde"]="Att stödja garnisonen i Tarren Mill handlar om mer än att försvara dess gränser. Goda förråd och hög moral hjälper Horde att hålla ställningarna i det omstridda Hillsbrad.",["profession:Cooking"]="Det här uppdraget låter kockar bemästra Soothing Turtle Bisque och förvandla de aggressiva kräldjuren i Lordamere Lake och Hillsbrads floder till en stärkande måltid.",["race:Undead"]="Christoph Jeffcoat visar en lättsammare sida av de Forsaken, präglad av hantverk, och hävdar att döden inte har dämpat hans passion för matlagning."},sec={{t="De Forsakens matkonst",b="Det är allmänt vedertaget att de Forsaken helt har övergett livets bekvämligheter, däribland konsten att äta gott. Christoph Jeffcoat, som är stationerad i Tarren Mill, avvisar bestämt den föreställningen. Jeffcoat skryter om att hans mustiga, lena sköldpaddsbisque är så god att den kan locka själar tillbaka från andra sidan graven. Han vill bevisa att odöda händer kan skapa något utsökt och värmande även i ett land märkt av pest och krig."},{t="Jakten på snapjaw-sköldpaddor",b="Vanligtvis hämtade Jeffcoat själv sina ingredienser från vattendragen i Hillsbrad Foothills och Lordamere Lakes östra stränder i grannlandet Alterac. Men hans uppgifter i Tarren Mill och Alliance-styrkornas framryckning håller honom på plats. Han förlitar sig på Horde-kockar på genomresa, som jagar snapjaw-sköldpaddorna, tar till vara på köttet och för tillbaka det så att mattraditionen kan leva vidare."}},faq={{q="Varför bryr sig en Forsaken-kock om att laga varm bisque?",a="De Forsaken behöver inte föda på samma sätt som levande dödliga, men individer som Christoph Jeffcoat är mycket stolta över sitt yrke. Jeffcoat vill motbevisa fördomen att odöda saknar förfinad skicklighet och skämtar om att hans signaturbuljong är så god att den kan väcka de döda till liv.",al={"odödas matlagning","varför laga bisque","äter odöda mat"}},{q="Var hittar man sköldpaddskött till receptet?",a="Sköldpaddsköttet kommer från de aggressiva snapjaw-sköldpaddor som lever längs floderna genom Hillsbrad Foothills och Alterac, samt längs stränderna vid Lordamere Lake.",al={"var finns sköldpaddor","sköldpaddornas platser","snapjaw-sköldpaddornas platser"}},{q="Varför kan inte Christoph Jeffcoat samla sina egna ingredienser?",a="Jeffcoat säger att han är upptagen med ansvar i Tarren Mill. Han är också irriterad över Alliance-styrkorna som rycker närmare, eftersom de gör jaktturer på egen hand mycket farligare.",al={"varför går inte christoph själv","jeffcoat fast i staden"}},{q="Måste man kunna laga mat för att ta det här uppdraget?",a="Ja. Christoph Jeffcoat delar bara med sig av sin kunskap och sitt recept till andra som utövar matlagningsyrket, men det krävs ingen avancerad skicklighet för att börja.",al={"behöver jag kunna laga mat","krav på matlagningsyrket"}},{q="Hur viktig är Tarren Mill för Horde i Hillsbrad?",a="Tarren Mill är Hordes främsta fäste i Hillsbrad Foothills. Byn var tidigare mänsklig, men fungerar nu som en befäst bas för de Forsaken och deras allierade, som ofta drabbar samman med Southshore och Alliance-styrkorna i området.",al={"vad är tarren mill","tarren mills bakgrund"}},{q="Är sköldpaddsbisque unik för Horde?",a="Alliance-kockar kan få receptet av lokala mänskliga kockar i Southshore, som också använder områdets sköldpaddor. Men Christoph Jeffcoats personliga uppdrag och perspektiv är förbehållna Horde.",al={"alliance-versionen","kan alliance få sköldpaddsbisque"}}},fx={["7509a6d7"]={q="Vad ska Turtle Meat användas till?",a="Christoph Jeffcoat behöver sköldpaddsköttet för att laga sin berömda, mildrande sköldpadssoppa. De odöda kanske inte känner kyla eller hunger som de levande, men Jeffcoat är oerhört stolt över sitt kulinariska hantverk. Han påstår att hans hemliga recept är så gott att folk skulle återvända från de döda bara för att få smaka en varm skål.",al={"användning av turtle meat","varför turtle meat","vad används turtle meat till"}},["5469f6c5"]={q="Vad är snapjaws för varelser som du jagar till soppan?",a="Snapjaws är våldsamma sötvattenssköldpaddor med hårda skal, hemmahörande i Lordaerons vattendrag och särskilt talrika längs stränderna vid Lake Lordamere och de lokala flodbankarna. De är vilda och farliga för oförsiktiga resenärer, men deras sega kött ger Christoph det mustiga kött han behöver till sin soppa.",al={"snapjaws hillsbrad","snapjaws i lake lordamere","vem ska jag jaga"}}},fp="22,190,19.346.0,20.316.0,54.207.0,47.127.0,56.123.0,49.100.0,59.215.0,37.178.0"}
P.entries["quest:733"] = {n="Scrounging",s="Sigrun Ironhew behöver material för att bygga försvar och annat nödvändigt till lägret, och har märkt att ogres i närheten bär på gott om metallskrot. Sigrun vill ha sju bitar.",h="Sigrun Ironhew behöver material för att bygga försvar och annat nödvändigt till lägret, och har märkt att...",kw={"badlands","dustbelch grotto","explorers' league","ironforge","ogres","metallskrot","scrounging","sigrun ironhew"},sec={{t="Ett läger med materialbrist",b="Sigrun har svårt att klara sig utan material till försvar och annat nödvändigt, och Prospector har oroat sig för det lilla lägrets tillstånd. Sigrun vill snart sätta igång och behöver metallskrot för att kunna göra det."},{t="Ogrernas skrot",b="Ogres i området verkar ha gott om metallskrot, vilket får Sigrun att tro att det kanske låg något i pratet om belägringsmaskiner i Badlands. Deras huvudläger är Dustbelch Grotto, en lång färd väster om Sigruns läger."}},faq={{q="Vem ber om metallskrotet?",a="Sigrun Ironhew, som vill använda det till att bygga försvar och annat nödvändigt för lägret.",al={"uppdragsgivare","vem ger scrounging","sigrun"}},{q="Varför behöver lägret metallskrot?",a="Sigrun saknar material för att bygga försvar och annat nödvändigt, och Prospector har oroat sig för lägrets tillstånd.",al={"varför behövs metallskrot","syftet med metallskrot","försvar"}},{q="Var kan man hitta metallskrotet?",a="Ogres i området bär på det. Deras huvudläger är Dustbelch Grotto, en lång färd väster om Sigruns läger.",al={"plats för metallskrot","var får man metallskrot","ogrernas läger"}},{q="Vad kommer före det här?",a="Det följer efter Mirages.",al={"föregående uppdrag","förutsättning för scrounging"}}},fp="10,123,25.189.0,16.162.0,34.71.0,35.98.0,35.106.0,23.19.0"}
P.entries["quest:734"] = {n="This Is Going to Be Hard",s="Lotwil Veriatus, upptagen med ett par bojor, skickar dig till Badlands för att tala med Lucien Tosselwrench. Lotwil behöver ett kugghjul nr 5 och vill att du tar med det tillbaka.",h="Lotwil Veriatus, upptagen med ett par bojor, skickar dig till Badlands för att tala med Lucien Tosselwrench.",kw={"badlands","kugghjul nr 5","lotwil veriatus","lucien tosselwrench","bojor"},sec={{t="Kugghjul nummer fem",b="Lotwil kastar en hastig blick upp på dig och böjer sig sedan åter över bojorna. Du ska gå och tala med Lucien Tosselwrench, eftersom Lotwil behöver ett kugghjul nr 5 och ber dig ta med det."},{t="Lucien dömer",b="När kugghjul nr 5 kommer på tal är Lucien Tosselwrench inte hoppfull om hur det kommer att gå."}},faq={{q="Vem ger det här uppdraget?",a="Lotwil Veriatus, som arbetar med ett par bojor i Badlands.",al={"vem startar det här uppdraget","lotwil veriatus uppdrag","uppdragsgivare"}},{q="Vad behöver Lotwil?",a="Ett kugghjul nr 5, som Lotwil ber dig ta med tillbaka efter att du talat med Lucien Tosselwrench.",al={"vad vill lotwil ha","vilket kugghjul","kugghjul 5"}},{q="Vem ska jag tala med om kugghjulet?",a="Lotwil skickar dig till Lucien Tosselwrench i Badlands.",al={"var hittar man kugghjul 5","vem är lucien","lucien tosselwrench"}}},fp="24,111,15.147.0,16.86.1,21.76.0,22.92.0,32.56.0"}
P.entries["quest:735"] = {n="The Star, the Hand and the Heart",s="Gerrig Bonegrip i Ironforge har ett extra exemplar av Yagyin's Digest och lämnar ifrån sig det i utbyte mot tre kraftfulla föremål. Gerrig säger inte deras namn högt, utan skriver dem i en lapp.",h="Gerrig Bonegrip i Ironforge har ett extra exemplar av Yagyin's Digest och lämnar ifrån sig det i utbyte mot...",kw={"bonegrips lapp","gerrig bonegrip","hand of dagun","ironforge","legacy heart","star of xil'yeh","yagyin's digest"},sec={{t="Ett byte med slutna läppar",b="Gerrig hör dig fråga efter Yagyin's Digest och undrar om du tänker inleda ett nytt kapitel för orden någonstans, men beslutar att det inte är Gerrigs sak att fråga. Gerrig har ett extra exemplar och anser att ordens medlemmar måste hjälpa varandra. I utbyte måste du hämta tre kraftfulla föremål. Deras namn förblir osagda, eftersom någon kanske lyssnar, och Gerrig skriver ner dem."},{t="De tre föremålen",b="På lappen står Star of Xil'yeh, Hand of Dagun och Legacy Heart. Det är vad Gerrig vill ha innan digesten lämnas över."},{t="Gerrigs dom",b="När relikerna väl är i din ägo kallar Gerrig dig påhittig och tror att du kommer att leda orden väl, om det verkligen är ditt uppdrag att grunda ett nytt kapitel."}},faq={{q="Vem ber om de tre föremålen?",a="Gerrig Bonegrip i Ironforge, som har ett extra exemplar av Yagyin's Digest att lämna i utbyte.",al={"uppdragsgivare","vem börjar stjärnan handen och hjärtat","gerrig bonegrips uppdrag"}},{q="Vilka tre föremål vill Gerrig Bonegrip ha?",a="Gerrig Bonegrips lapp ber om tre saker: Star of Xil'yeh, Hand of Dagun och Legacy Heart.",al={"föremål som krävs","vilka reliker behöver han","föremålen på bonegrips lapp"}},{q="Varför skriver Gerrig ner föremålen i stället för att säga namnen?",a="Gerrig säger inte deras namn, eftersom någon kanske lyssnar.",al={"varför skriva ner dem","varför den hemliga lappen","bonegrip viskar"}},{q="Vad hände tidigare i kedjan?",a="Det följer på To Ironforge for Yagyin's Digest, där Theldurin the Lost skickade dig till Gerrig.",al={"förutsättningsuppdrag","föregående uppdrag"}}},fp="32,154,30.392.0,15.140.0,16.158.1,29.104.0,43.89.0,60.62.0,35.89.0"}
P.entries["quest:736"] = {n="The Star, the Hand and the Heart",s="The Star, the Hand and the Heart är ett uppdrag i Undercity där Keeper Bel'dugur prövar en blivande ledare som vill grunda en ny gren av sin orden. För att få tag på det oumbärliga Yagyin's Digest måste den sökande hitta tre kraftföremål vars namn Bel'dugur inte vågar uttala högt.",h="The Star, the Hand and the Heart är ett uppdrag i Undercity där Keeper Bel'dugur prövar en blivande ledare...",kw={"bel'dugurs lapp","keeper bel'dugur","orden","the star the hand and the heart","tre kraftföremål","undercity","yagyin's digest"},ang={["class:Warlock"]="Att skaffa Yagyin's Digest för att grunda en ny skara är ett avgörande steg för att utöka din mörka ordens räckvidd och ockulta kunskap.",["race:Undead"]="Keeper Bel'dugur verkar från Undercity och vägleder Forsaken-utövare som vill fördjupa sig i förbjudna riter under stadens skuggiga spiror."},sec={{t="Ett brödraskapsprov",b="I Undercitys skuggiga korridorer vänder sig ambitiösa utövare som vill leda sin egen krets till Keeper Bel'dugur. För att grunda en ny skara och öppna en gren av sin orden behöver en blivande ledare Yagyin's Digest, en auktoritativ skrift om ritualkunskap som väktaren skyddar. Bel'dugur står redo att hjälpa sin broder, men kräver bevis på dennes värdighet innan han lämnar ifrån sig en sådan auktoritet."},{t="De outsagda relikerna",b="Keeper Bel'dugur lämnar inte gärna ifrån sig Yagyin's Digest. Han kräver tre särskilda kraftföremål som sin del av bytet. Relikerna har så farlig eller helig betydelse att deras namn inte ens kan uttalas högt; Bel'dugur skriver i stället ner dem på en privat lapp. Endast en utövare som kan spåra upp och hämta alla tre outsagda föremål visar sig värdig att grunda en egen gren."}},faq={{q="Vem är Keeper Bel'dugur?",a="Keeper Bel'dugur är en ockult gestalt som bor i Undercity och hjälper medlemmar av sitt mörka brödraskap. Han vaktar mäktig kunskap och kräver att kandidater visar sin förmåga innan han anförtro dem heliga skrifter.",al={"vem är keeper bel'dugur","bel'dugurs roll","bel'dugur undercity"}},{q="Vad är Yagyin's Digest?",a="Yagyin's Digest är en särskild instruktionsskrift som behövs för att grunda och leda en ny gren eller samla en ny skara inom en hemlighetsfull ockult orden.",al={"vad är yagyin's digest","yagyin's digest syfte","boken yagyin's digest"}},{q="Vilka föremål ber Keeper Bel'dugur om?",a="Bel'dugur kräver tre särskilda kraftföremål. Eftersom deras namn är för förbjudna eller farliga för att uttalas högt skriver han ner dem i tysthet på en lapp som den sökande får hämta.",al={"vilka föremål behöver bel'dugur","föremålen på bel'dugurs lapp","tre kraftföremål"}},{q="Varför uttalas inte namnen på föremålen högt?",a="Keeper Bel'dugur påpekar uttryckligen att han inte kan uttala namnen på de tre relikerna högt. Det antyder att de har en mörk, helig eller instabil kraft som kräver diskretion.",al={"varför kan bel'dugur inte säga föremålens namn","kan inte uttala namnen","de outsagda föremålsnamnen"}},{q="Vad innebär det att samla en ny skara?",a="Att samla en skara innebär att rekrytera följare och grunda en fungerande, självständig gren av brödraskapet. På så sätt visar man sig redo att vägleda andra utövare av hantverket.",al={"vad innebär det att samla en skara","grunda en gren","vår ordens gren"}},{q="Var utspelar sig uppdraget?",a="Uppdraget kretsar kring Keeper Bel'dugur, som håller till i Forsakens underjordiska huvudstad Undercity.",al={"var utspelar sig uppdraget","bel'dugurs plats","platsen där uppdraget lämnas in"}}},fp="32,178,21.311.0,19.280.0,24.186.0,24.123.0,41.118.0,58.118.0,42.136.0,29.90.0"}
P.entries["quest:737"] = {n="Forbidden Knowledge",s="Yagyin's Digest överlämnas med en varning om att skydda den väl från illasinnade händer. Theldurin the Lost ska bära den vidare.",h="Yagyin's Digest överlämnas med en varning om att skydda den väl från illasinnade händer.",kw={"badlands","forbidden knowledge","the star the hand and the heart","theldurin the lost","yagyin's digest"},sec={{t="En bok som bränner",b="Gerrig Bonegrip i Ironforge eller Keeper Bel'dugur i Undercity ger dig digesten. Du uppmanas att skydda den väl och hålla den borta från illasinnade händer, för den rymmer många sanningar, och sanningen har en tendens att bränna. Bär den till Theldurin the Lost."},{t="Theldurins hopp",b="Theldurin ropar att hoppet glimtar och säger att dina ansträngningar kanske ännu kan rädda dem alla, med ett monument, en helgedom och ditt namn prisat i generationer framöver. Allt detta gäller bara så länge DE inte släpps fria att ta sig upp till ytan. I så fall blir alla maskföda, säger Theldurin."}},faq={{q="Vilket föremål ska levereras?",a="Yagyin's Digest, en bok som rymmer många sanningar. Den måste skyddas noga och hållas borta från illasinnade händer.",al={"vad är det här för bok","vad är yagyin's digest","vad ska jag ta med"}},{q="Vem tar emot digesten?",a="Digesten är avsedd för Theldurin the Lost.",al={"vem får boken","vem ska jag lämna det till","vart ska digesten"}},{q="Vad hände före detta?",a="Det följer efter steget där tre föremål hämtades i utbyte mot digesten.",al={"föregående uppdrag","vad leder fram till detta","vilket uppdrag kommer före forbidden knowledge"}}},fp="19,93,17.215.0,16.268.1,32.99.0,24.49.0,22.82.0"}
P.entries["quest:738"] = {n="Find Agmond",s="Prospector Ironband har inte hört från Prospector Agmond på flera veckor. Agmond ansvarade för utgrävningsplatserna i Badlands, och Ironband vill att Agmond hittas så att rapporten kan hämtas.",h="Prospector Ironband har inte hört från Prospector Agmond på flera veckor.",kw={"agmond","angor fortress","badlands","ironforge","prospector ironband"},sec={{t="En tyst prospektör",b="Agmond ledde utgrävningarna i Badlands, åt sydväst. Ironband säger ”ledde” med flit, för det har inte hörts något från Agmond på flera veckor. Ironband vill att Agmond hittas, och att rapporten följer med. Senast hörde man av Agmond vid den sydligaste utgrävningen i Badlands, ett litet arbetslag bortom Angor Fortress, och det är där sökandet bör börja."},{t="Där spåren slutar",b="När sökandet är över hittar du ett skelett, som måste vara det som finns kvar av Agmond. Kroppen är trasig och illa tilltygad, och benen har rensats rena."}},faq={{q="Vem är Prospector Agmond?",a="Agmond ledde utgrävningarna i Badlands, sydväst om Prospector Ironband.",al={"vem är agmond","vem agmond","agmonds historia"}},{q="Varför letar Prospector Ironband efter Agmond?",a="Ironband har inte hört från Agmond på flera veckor och vill få tag på Agmonds rapport.",al={"varför hitta agmond","ironband letar efter agmond"}},{q="Var befann sig Prospector Agmond senast?",a="Vid den sydligaste utgrävningen i Badlands, ett litet arbetslag bortom Angor Fortress.",al={"agmonds plats","var ligger agmonds utgrävningsplats","var var agmond"}},{q="Vad kommer före detta i kedjan?",a="Det följer på Ironband Wants You!",al={"föregående uppdrag","förutsättning för find agmond"}}},fp="11,151,19.307.0,20.154.1,25.92.0,46.80.0,45.98.0,36.30.0"}
P.entries["quest:739"] = {n="Murdaloc",s="Agmonds sargade kvarlevor ligger i Badlands, och bredvid den döda handen står namnet ristat i sandstenen: Murdaloc. Agmonds mördare ska dödas, och beskedet ska föras tillbaka till Prospector Ironband i Loch Modan.",h="Agmonds sargade kvarlevor ligger i Badlands, och bredvid den döda handen står namnet ristat i sandstenen...",kw={"agmond","badlands","loch modan","murdaloc","prospector ironband","stonevault bonesnapper","trogg"},sec={{t="Ett namn i sandstenen",b="Agmonds spår kommer från väster, och blodet över sten och sand visar hur långt dvärgen kröp innan han dog här. Bredvid den livlösa handen står ett enda ord inristat i Badlands sandsten: Murdaloc. Agmonds mördare ska dödas, liksom ett antal Stonevault Bonesnappers, och nyheten ska föras till Prospector Ironband i Loch Modan."},{t="Ironbands svar",b="Ironband tar emot nyheten med allvar och minns Agmond som stark i armen, våldsam med en hammare och tjockskallig. Ironband säger att Agmond dödades av förbannade troggs och är säker på att Agmond slog ner ett stort antal av dem på vägen."}},faq={{q="Vem var Agmond?",a="Agmond var en dvärg som ansvarade för utgrävningsplatserna i Badlands åt Prospector Ironband. Ditt sökande efter Agmond slutade vid ett skelett.",al={"vem är agmond","agmonds historia"}},{q="Vem är Murdaloc?",a="Murdaloc är namnet som står ristat i sandstenen bredvid Agmonds döda hand. Du ska döda Agmonds mördare, Murdaloc.",al={"vad är murdaloc","murdalocs historia"}},{q="Vart ska rapporten skickas?",a="Till Prospector Ironband i Loch Modan.",al={"vem berättar jag om murdaloc för","var finns ironband"}}},fp="8,162,23.321.0,16.245.1,15.133.0,16.108.0,33.54.0"}
P.entries["quest:74"] = {n="The Legend of Stalvan",s="Det här steget i utredningen leder djupt ner i en gammal kista med Flintridge-familjens arvegods, lämnad vid Stormwind Citys kanaler. Bland de dammiga relikerna hittar du en trasig journalsida med en avgörande handskriven ledtråd om Stalvan Mistmantles tidigare liv, som leder till Marshal Haggard i Elwynn Forest.",h="Det här steget i utredningen leder djupt ner i en gammal kista med Flintridge-familjens arvegods, lämnad vid...",kw={"duskwood","elwynn forest","forlorn spirit","marshal haggard","mistmantle","sealed crate","stalvan","trasig journalsida"},ang={["faction:Alliance"]="När du utreder gamla olösta fall i hjärtat av Elwynn upptäcker du hur djupt personliga fasor kan slinka förbi Stormwinds marshaler.",["race:Human"]="Marshal Haggard står för den åldrande generationen av Stormwinds veteraner och bär på viktiga minnen av kungariket från tiden innan Första och Andra kriget splittrade familjer."},sec={{t="Att gräva fram det förflutna",b="När utredarna söker igenom en förseglad kista fylld med unkna arvegods, gamla jakttroféer och familjeporträtt hittar de en ensam trasig journalsida gömd under en keramikvas. Den är skriven med Stalvan Mistmantles egen handstil och ger en intim inblick i en tillbakadragen forskares tankar innan tragedin slog till."},{t="En marshals sviktande syn",b="Marshal Haggard, som nu är gammal och plågas av försämrad syn, kämpar med att läsa texten på det slitna pergamentet. Ändå väcker den särpräglade handstilen ett obehagligt minne av dokument och händelser från åren innan mörkret tog hans syn."}},faq={{q="Var finns den förseglade kistan?",a="Den förseglade kistan står vid Stormwind Citys kanaler, precis bakom Caretaker Folsom bland Flintridge-familjens hoppackade tillhörigheter. Sidan du hittar där tas sedan till Marshal Haggard i sydöstra Elwynn Forest.",al={"kistans plats","var finns kistan","haggards kista"}},{q="Vad finns i den förseglade kistan?",a="Kistan innehåller dammiga arvegods, ett familjeporträtt, gamla böcker, jakttroféer och en keramikvas. Under vasen ligger en trasig sida ur Stalvans journal.",al={"kistans innehåll","vad finns i kistan","trasig sida i kistan"}},{q="Vem är Marshal Haggard?",a="Marshal Haggard är en äldre, pensionerad officer från Stormwind som bor ensam i södra Elwynn Forest. Trots sin sviktande syn och bräckliga hälsa gör hans minnen av gamla handlingar och resenärer honom till ett viktigt vittne till tidigare händelser.",al={"vem är haggard","marshal haggards bakgrund","gammal marshal i elwynn"}},{q="Varför är den här journalsidan viktig?",a="Den trasiga journalsidan är ett direkt bevis skrivet av Stalvan Mistmantle själv. Hans särpräglade handstil och kvardröjande tankar hjälper till att knyta samman skilda berättelser från Duskwood och Elwynn med hans personliga fall.",al={"varför den trasiga sidan är viktig","ledtråd på journalsidan","stalvans journal"}},{q="Vad händer när kistan öppnas?",a="När du rör vid resterna av Stalvans förflutna väcks The Restless Dead, och en hämndlysten Forlorn Spirit visar sig och går till angrepp mot dem som försöker nysta upp tragedin.",al={"när visar sig forlorn spirit","spöke efter kistan","varför attackerade ett spöke mig"}},{q="Vart leder utredningen härnäst?",a="När du visar den trasiga sidan för Marshal Haggard leder hans minne av handstilen utredningen vidare i sökandet efter fler bevarade fragment av Stalvans historia.",al={"nästa steg","efter den trasiga sidan","vart går jag härnäst"}}},fp="21,171,19.265.0,24.200.1,34.215.0,32.158.0,23.226.0,35.183.0,38.152.0,39.152.0"}
P.entries["quest:741"] = {n="The Absent Minded Prospector",s="Det här ärendet för ett märkligt förstenat fynd från Darkshores vilda stränder till Explorers' League-utposten i Darnassus. Archaeologist Hollee vägrar lämna sin tankspridda kollega ensam ute i fält och låter i stället en äventyrare på genomresa transportera fyndet. När fossilet anländer till nattalvernas huvudstad väcker det genast Chief Archaeologist Greywhiskers stora intresse.",h="Det här ärendet för ett märkligt förstenat fynd från Darkshores vilda stränder till Explorers'...",kw={"arkeolog","darkshore","darnassus","explorers' league","fossil","greywhisker","hollee","remtravel"},ang={["faction:Alliance"]="Den här uppgiften visar hur alliansens medlemmar är beroende av varandra logistiskt, eftersom dvärgarnas forskare förlitar sig på resande äventyrare för att säkert överbrygga avståndet mellan Darkshores avlägsna stränder och Darnassus höjder.",["race:Dwarf"]="Genom att bära Remtravels fossil fullgör du Explorers' Leagues främsta uppdrag: att gräva fram världens djupaste förflutna och visa dvärgarnas uthållighet utan gränser.",["race:NightElf"]="Det kan kännas omskakande att se dvärgiska utgrävare hämta forntida lämningar ur Darkshores heliga jord, men samarbetet med skrået bevarar alliansens band."},sec={{t="En kurir till huvudstaden",b="Prospector Remtravels utgrävningar längs Darkshores dimhöljda kust har grävt fram ett märkligt fossil, men för honom är fortsatt grävande viktigare än reglerna. Archaeologist Hollee vill inte lämna prospektören ensam bland kustens farliga bestar och fientliga sekterister, så hon stannar kvar för att hålla ett öga på honom. För att fyndet ska bli dokumenterat behöver hon en alliansresenär som kan föra det till Darnassus, där dvärgarnas skrå har en vetenskaplig delegation."},{t="Dvärgarnas intressen i Kalimdor",b="Dvärgar från Ironforge har i stort antal korsat det Stora havet under Explorers' Leagues fana, ivriga att gräva fram forntida reliker och bortglömd historia ur Kalimdors jord. När Chief Archaeologist Greywhisker tar emot artefakten i alvernas huvudstad slösar han ingen tid på att förundras över Remtravels förmåga att hitta forntida skatter. Nattalverna ser sina skogar som levande fristäder, medan skrået ser de gamla länderna som en väldig arkeologisk utgrävning som väntar på att bli uttolkad."}},faq={{q="Vad är det mystiska fossilet?",a="Det är ett oidentifierat förstenat fynd som Prospector Remtravel grävt fram längs Darkshores kust. Dess ålder och märkliga natur gör det till ett värdefullt fynd för Explorers' Leagues lärda i Darnassus.",al={"mysterious fossil","vad är det här för fossil","remtravels fossil"}},{q="Varför stannar Hollee kvar i Darkshore?",a="Archaeologist Hollee känner sig skyldig att hålla ett öga på Prospector Remtravel. Han har för vana att vandra iväg och strunta i faror när han gräver, så hon vägrar lämna honom ensam i vildmarken medan hon för hans fynd till Darnassus.",al={"varför följer hollee inte med","hollee stannar kvar","varför hollee stannar"}},{q="Vem är Chief Archaeologist Greywhisker?",a="Greywhisker är en högt uppsatt företrädare för Ironforges Explorers' League och övervakar arkeologiska expeditioner i norra Kalimdor. Han utgår från Darnassus och studerar reliker som dvärggrävarna fört tillbaka från fältet.",al={"greywhisker","vem är greywhisker","chief greywhisker"}},{q="Varför verkar Explorers' League i Darnassus?",a="King Magni Bronzebeard grundade Explorers' League för att gräva fram dvärgarnas ursprung och utforska Azeroths forntida historia. De vänskapliga diplomatiska banden med nattalverna gör att dvärgarnas lärda kan utgå från Darnassus när de undersöker Kalimdors bortglömda länder.",al={"dvärgar i darnassus","explorers' league darnassus","varför är dvärgar här"}},{q="Vart tar fossilet vägen efter Darnassus?",a="Chief Archaeologist Greywhisker undersöker fyndet i Darnassus, men upptäckter av den här storleken är avsedda att katalogiseras eller skickas vidare genom skråets kanaler, mot det stora museet i Ironforge.",al={"vart tar fossilet vägen","fossilets nästa steg"}},{q="Var hittade Remtravel fyndet?",a="Remtravel grävde fram fyndet längs Darkshores vilda kust, ett område fullt av skeppsvrak, forntida ruiner och förstenat marint liv från tiden före den stora omvälvningen.",al={"var hittades fossilet","remtravels utgrävningsplats"}}},fx={c70c2c67={q="Varför vill Archaeologist Hollee att fossilet levereras till Darnassus?",a="Prospector Remtravel vill att hans fynd undersöks genast, men någon måste ta det till deras överordnade. Hollee är fast besluten att inte överge Darkshore medan Remtravel är kvar i vildmarken. Därför förlitar hon sig på att du för deras räkning för det ovärderliga fyndet direkt till Chief Archaeologist Greywhisker i Darnassus.",al={"varför skicka fossilet till darnassus","hollees motiv","varför leverera fossilet"}}},fp="28,180,24.315.0,29.381.0,30.181.0,41.202.0,39.222.0,52.261.0,46.181.0,38.151.0"}
P.entries["quest:742"] = {n="The Ashenvale Hunt",s="Ashenvale Hunt är en kallelse till unga Hordehjältar på besök i Thunder Bluff, som uppmanar dem att bege sig norrut till Ashenvales täta skog. Stadens härolder framför kallelsen och hänvisar resenärerna till Senani Thunderheart vid Splintertree Post för att delta i en prövande jakt.",h="Ashenvale Hunt är en kallelse till unga Hordehjältar på besök i Thunder Bluff, som uppmanar dem att bege sig...",kw={"ashenvale","jakt","senani","splintertree","thunder bluff","thunderheart","windstrider","the zoram strand"},ang={["class:Hunter"]="Ashenvales otämjda rovdjur ger jägare en chans att bemästra spårning i tät skog, långt från söderns torra, öppna savanner.",["faction:Horde"]="Splintertree Post och The Zoram Strand är viktiga uppmarschområden för Hordens norra försörjningslinjer. De förlitar sig på nya rekryter för att hålla vilddjuren och fientliga invånare på avstånd.",["race:Tauren"]="För tauren som har genomgått sina prövningar på Mulgore öppna slätter är Ashenvales täta, skuggiga skog en främmande och helig utmaning under vaksamma blickar från fränder som Senani."},sec={{t="En kallelse från High Rise",b="På Thunder Bluffs fridfulla höjder håller löpare den växande Horden underrättad om möjligheter bortom Mulgore. Bluff Runner Windstrider förmedlar en öppen inbjudan till beprövade äventyrare som söker större utmaningar. Horden etablerar fotfästen djupt inne i den uråldriga skogen norr om The Barrens, och unga krigare kallas in för att stärka utposterna och pröva sin överlevnadsförmåga i en mycket hårdare miljö."},{t="Den norra gränsmarken",b="Ashenvale erbjuder både rika tillgångar och allvarliga faror för Horden. Två framstående läger befäster fraktionens närvaro i området: Splintertree Post längs huvudvägen och en avlägsen utpost på västkusten vid The Zoram Strand. När du kommer till Splintertree Post tar Senani Thunderheart, en erfaren vildmarkskvinna, hand om dig. Hon organiserar en omfattande jakt för att tämja vildmarken och vinna ära åt Horden."}},faq={{q="Vem erbjuder det här uppdraget i Thunder Bluff?",a="Bluff Runner Windstrider erbjuder det här uppdraget till äventyrare på genomresa i Thunder Bluff. Hans uppgift är att uppmärksamma dugliga kämpar på Hordens expansionsinsatser och visa dem vägen till avlägsna utposter som behöver hjälp.",al={"vem startar ashenvale hunt","uppdragsgivare för ashenvale hunt","bluff runner windstrider"}},{q="Var ligger Splintertree Post?",a="Splintertree Post är en befäst Horde-bosättning i östra Ashenvale. För att ta dig dit reser du rakt norrut över gränsen från The Barrens till Ashenvale. Följ sedan skogsstigen österut när den leder djupare in bland träden.",al={"splintertree post plats","hur tar man sig till splintertree post","var ligger splintertree"}},{q="Vem är Senani Thunderheart?",a="Senani Thunderheart är en erfaren tauren-spårare stationerad vid Splintertree Post. Hon samordnar jakten i Ashenvale och prövar Hordens rekryters styrka och tålamod mot traktens rovdjur.",al={"senani thunderheart","vem är senani","thunderheart npc"}},{q="Varför jagar Horden i Ashenvale?",a="Horden fortsätter att expandera i Ashenvale för att samla timmer och säkra strategiskt viktig mark. Jakten ska gallra bland de farliga vilddjur som hotar lägren, samtidigt som unga äventyrare får bevisa sitt mod i främmande terräng.",al={"varför jaga i ashenvale","syftet med ashenvale hunt","hordens mål i ashenvale"}},{q="Vad är Zoram Strand, som nämns i orienteringen?",a="The Zoram Strand är Hordens kustläger vid Ashenvales avlägsna västra kust, vänt mot havet. Det fungerar som ett sekundärt marint fotfäste och ett bålverk mot naga och fientliga skogsinvånare.",al={"vad är the zoram strand","utposten the zoram strand","utposten zoram"}},{q="Vad händer när du har rapporterat till Senani?",a="När du rapporterar till Senani Thunderheart välkomnar hon dig till utposten och sätter dig genast i arbete med de större jaktuppgifterna. Hon skickar dig att spåra upp och besegra Ashenvales farligaste bestar.",al={"vad följer efter ashenvale hunt","nästa uppdrag efter senani","jaktens fortsättning"}}},fx={af70e220={q="Varför vill Bluff Runner Windstrider att du beger dig till Ashenvale?",a="Bluff Runner Windstrider tjänar som härold åt Horden och vägleder dugliga unga hjältar till platser där de behövs som mest. Horden säkrar sina utposter vid gränsen i skogarna norr om The Barrens med kraft, och jägare som Senani Thunderheart behöver nya rekryter som kan förstärka deras närvaro och vinna ära i vildmarken.",al={"varför bege sig till ashenvale","bluff runner windstriders motiv","varför vill windstrider detta"}}},fp="18,197,28.293.0,21.333.0,39.191.0,35.171.0,27.166.0,38.189.0,51.173.0,39.171.0"}
P.entries["quest:743"] = {n="Dangers of the Windfury",s="Dangers of the Windfury är ett prov på stridsberedskap som Ruul Eagletalon erbjuder i Bloodhoof Village. Unga tauren och äventyrare från Horde får i uppdrag att bekämpa de vilda Windfury-harpiorna som häckar i de sydöstra klipporna i Mulgore. Jakten på dessa förvildade rovdjur är ett viktigt prov på skicklighet och överlevnadsförmåga innan man färdas bortom stammens hemland.",h="Dangers of the Windfury är ett prov på stridsberedskap som Ruul Eagletalon erbjuder i Bloodhoof Village.",kw={"bloodhoof village","dangers of the windfury","harpior","mulgore","ruul eagletalon","taurenprov","windfury","windfury-klor"},ang={["class:Warrior"]="Ruul Eagletalons utmaning betyder särskilt mycket för blivande krigare, som måste lära sig att parera snabba dykattacker och övermanna grymma luftburna bakhållsangripare med stadig disciplin.",["faction:Horde"]="Taurenernas allierade som genomgår Ruuls prov visar sitt engagemang för att skydda Hordes kärnland och vinner samtidigt Bloodhoof Villages bestående respekt.",["race:Tauren"]="För unga tauren är det både en handling för att försvara slätterna och en helig övergång till erkänd vuxenhet inför byäldstarnas vakande ögon att rensa Windfury-bon."},sec={{t="En lärares bedömning",b="I Bloodhoof Village håller den erfarne krigaren Ruul Eagletalon uppsikt över alla resenärer som passerar genom hjärtat av Mulgore. För dem som blir vuxna eller vill bevisa att de är redo för större äventyr kräver Ruul konkreta bevis på deras stridsinstinkter. För att överleva utanför Mulgors skyddade dalar krävs lugn inför aggressiva och listiga fiender, och Ruul använder landets farligaste inhemska rovdjur för att pröva de ungas tapperhet."},{t="Hotet från Windfury",b="Windfury-harpiorna har sina bon längs Mulgors bergiga sydöstra rand, långt från de upptrampade stigarna men ett ständigt hot mot kringströvande djur och ensliga resenärer. Dessa fågelliknande fasor är grymma och ständigt hungriga efter färskt kött, och förlitar sig på snabba störtdykningar och rakbladsvassa klor. Att besegra dem och ta deras klor visar inte bara att du kan slå ut ett befäst hot, utan också att du har snabbheten som krävs för att möta luftburna plundrare."}},faq={{q="Vem är Ruul Eagletalon?",a="Ruul Eagletalon är en erfaren taurenkrigare och lärare som bor i Bloodhoof Village. Han handleder unga äventyrare och erbjuder prov för att säkerställa att de har styrkan, reflexerna och uthålligheten som krävs innan de ger sig av till Kalimdors vidare och farligare hörn.",al={"ruul eagletalon","vem ger uppdraget dangers of the windfury","ruul"}},{q="Var finns Windfury-harpiorna i Mulgore?",a="Windfury-harpiorna har sina bon i Mulgors sydöstra berg. De bygger sina enkla bon högt uppe bland klipporna och på bergssluttningarnas nedre delar, avskilda från huvudvägen genom dalen.",al={"windfury-harpiornas plats","var finns windfury-harpior","windfury-bonas plats"}},{q="Varför räknas Windfury-harpiorna som taurenernas naturliga fiender?",a="Harpior är ökända för att vara aggressiva, revirhävdande asätare som anfaller alla som inkräktar nära deras bon. I Mulgore är Windfury-flocken känd för sin omättliga aptit på färskt kött och sin obevekliga aggressivitet mot både resenärer och betande djur, vilket gör dem till ett ständigt hot mot slätterna.",al={"varför slåss tauren mot harpior","harpiornas hot i mulgore","windfurys historia"}},{q="Vilka bevis kräver Ruul Eagletalon från jakten?",a="Ruul ber äventyrarna hämta åtta Windfury Talons direkt från de dödade harpiorna. Att skära loss och återlämna klorna visar att du behärskar har피ornas främsta naturliga vapen.",al={"bevis för dangers of the windfury","vad ska hämtas åt ruul","windfury-uppdragets mål"}},{q="Varför måste äventyrare genomgå det här provet innan de lämnar Mulgore?",a="Ruul ser de vilda Windfury-harpiorna som ett idealiskt mått på stridsberedskap. Om en äventyrare inte kan hantera en harpis snabbhet, grymhet och klor har hen liten chans mot de dödligare faror som växer sig starkare bortom Mulgors försvarsbranter.",al={"provets syfte","varför göra dangers of the windfury","ruuls prov"}},{q="Var ligger Bloodhoof Village?",a="Bloodhoof Village ligger centralt i Mulgore, nära Stonebull Lake, söder om Great Gate och Thunder Bluff. Det är den främsta samlingsplatsen för kultur, handel och träning för taurenresenärer som färdas över slätterna.",al={"bloodhoof villages plats","var ligger bloodhoof","ruuls plats"}}},fx={d8522cbd={q="Varför vill Ruul Eagletalon att Windfury-harpyorna jagas?",a="Ruul Eagletalon är en krigare och mentor med uppdraget att förbereda unga äventyrare innan de ger sig bortom Mulgore trygga gränser. Han ser de vildsinta Windfury-harpyorna som en naturlig prövning, ett verkligt mått på din stridsförmåga och beredskap att möta de hårdare hoten i den stora världen.",al={"varför jaga harpyor","ruuls motiv","ruul eagletalons skäl"}},["1789ad72"]={q="Vilka är Windfury-harpyorna?",a="Windfury-harpyorna är vilda, fågelliknande asätare som har bon på bergshyllorna sydöst om Bloodhoof Village. De är våldsamma och listiga och har länge jagat resenärer och vilda djur i Mulgore. De drivs av en omättlig hunger efter färskt kött och en naturlig fiendskap mot taurerna.",al={"windfury-harpyor","vilka är windfury","windfury-harpyor i mulgore"}},["29c303b8"]={q="Varför jagar inte Ruul Eagletalon harpyorna själv?",a="Ruul är en lärare vars plikt i Bloodhoof Village är att fostra nästa generation försvarare, inte att utkämpa deras strider åt dem. Uppgiften är uttryckligen ett övergångsprov: du måste bevisa din egen styrka mot Mulgore rovdjur innan du anses redo att resa bortom slätterna.",al={"varför jag","varför skicka mig","varför gör inte ruul det"}}},fp="23,183,22.325.0,19.354.0,23.162.0,48.176.0,70.210.0,53.112.0,63.172.0,35.163.0"}
P.entries["quest:744"] = {n="Preparation for Ceremony",s="Förberedelser inför ceremonin är en tauren-tradition där man tillverkar en ceremoniell huvudbonad åt någon som ska möta hövding Cairne Bloodhoof. För att fullända dräkten måste färgstarka fjädrar samlas in från farliga harpyor som häckar bortom Thunder Bluff, medan läderremmarna förbereds.",h="Förberedelser inför ceremonin är en tauren-tradition där man tillverkar en ceremoniell huvudbonad åt någon...",kw={"cairne bloodhoof","ceremoni","fjädrar","harpy","huvudbonad","mulgore","förberedelser inför ceremonin","tauren","thunder bluff"},ang={["faction:Horde"]="Att hjälpa en annan medlem av Horde med hans traditionella ceremonier hedrar sederna hos taurenfolkets allierade på Thunder Bluffs platåer.",["race:Tauren"]="Huvudbonader av naturmaterial är djupt förknippade med taurenfolkets heder och övergångsriter inför överhövdingen. Att hjälpa till att tillverka en sådan dräkt visar stammarnas gemenskap och stolthet i Mulgore."},sec={{t="Hedra hövdingen",b="I taurenkulturen är det ett tillfälle fyllt av stolthet och vördnad att stå inför hövding Cairne Bloodhoof. Sådana milstolpar kräver lämplig ceremoniell dräkt, i synnerhet en traditionell huvudbonad som omsorgsfullt tillverkats av behandlat läder och symboliska fjädrar. Familjemedlemmar ser det som en ära att tillverka denna dräkt och ser noga till att varje del uttrycker värdighet och respekt inför ledaren för de förenade stammarna."},{t="Fjädrar från klipporna",b="Att tillverka en ceremoniell huvudbonad kräver både skicklighet och särskilda material. Medan smidiga läderremmar garvas till ett band som bildar basen, måste långa och felfria fjädrar hämtas för att pryda kronan. De fågellika harpyor som häckar bland de klippiga kullarna norr och nordväst om Thunder Bluff har fjädrar med precis den storlek och färg som behövs. Därför måste resande ta sig in i fientliga bon för att hämta dem."}},faq={{q="Inför vilken ceremoni förbereder man sig?",a="Ceremonin markerar att en tauren ska träda fram inför hövding Cairne Bloodhoof. För att hedra tillfället tillverkar hans syskon en särskild ceremoniell huvudbonad av garvat läder och färgstarka fjädrar.",al={"vilken ceremoni är det här","vad är ceremonin","vem står inför bloodhoof"}},{q="Vem är hövding Bloodhoof?",a="Hövding Cairne Bloodhoof är den vördnadsvärde överhövdingen och ledaren för de förenade taurenstammarna. Han härskar från Thunder Bluffs höga platåer. Det är en stor ära för varje tauren att stå inför honom.",al={"vem är hövding bloodhoof","cairne bloodhoof","vem är bloodhoof"}},{q="Varför behövs harpyfjädrar till huvudbonaden?",a="Den ceremoniella huvudbonaden behöver fjädrar av en viss storlek och med slående färger, särskilt azurblått och brons, för att fullända den traditionella utformningen medan läderremmarna garvas.",al={"varför behövs harpyfjädrar","varför harpyfjädrar","varför fjädrar"}},{q="Var finns harpyorna?",a="Harpyorna med dessa fjädrar lever i det karga landet långt norr och nordväst om Thunder Bluff i Mulgore.",al={"var bor harpyor","var hittar man harpyor","var finns azurblå och bronsfärgade fjädrar"}},{q="Vilken roll spelar harpyor i Mulgore?",a="Harpyor är våldsamma fågelmänniskor som häckar bland de klippiga branterna i Mulgore. Förutom att hota resande och stammarna är de en viktig källa till ceremoniella prydnader tack vare sin stora, färgstarka fjäderdräkt.",al={"varför jagar man harpyor","vad är harpyor"}},{q="Vem tillverkar den ceremoniella huvudbonaden?",a="Eyahn Eagletalon garvar läderremmarna och tillverkar huvudbonaden för att hedra sin bror när han förbereder sig på att träda fram inför hövdingen.",al={"vem gör huvudbonaden","vem tillverkar huvudbonaden"}}},fp="24,212,22.307.0,21.314.0,36.161.0,23.121.0,48.143.0,30.82.0,37.203.0,41.130.0"}
P.entries["quest:745"] = {n="Sharing the Land",s="Baine Bloodhoof ger dig uppdraget i Bloodhoof Village. Du ska stoppa de lokala Palemane-gnollernas hänsynslösa tjuvjakt.",h="Baine Bloodhoof ger dig uppdraget i Bloodhoof Village.",kw={"baine bloodhoof","bloodhoof village","gnoller","mulgore","palemane","tjuvjägare","sharing the land","flåare","garvare"},ang={["class:Druid"]="Druider vet att okontrollerad tjuvjakt rubbar slätternas ande och kräver ett omedelbart ingripande för att återställa harmonin i landet.",["class:Hunter"]="Palemanes flåare och tjuvjägare är motsatsen till sanna jägare. De slaktar vilda djur grymt och slösaktigt i stället för att visa respekt.",["faction:Horde"]="Genom att hjälpa Baine Bloodhoof stärker du banden mellan Horde-äventyrare och ledarna för den unga tauren-nationen.",["race:Tauren"]="För unga taurener är det ett viktigt steg att svara på Baines uppmaning. De lär sig då sin heliga plikt att försvara Mulgore och värna Jordmoderns balans."},sec={{t="Ett land ur balans",b="Taurenerna vördar naturen djupt. De tar bara det de behöver för att överleva och hedrar i allt Jordmodern. Palemane-gnollerna har slagit sig ner söder om Bloodhoof Village och i en grotta västerut, men visar ingen sådan respekt. I stället för att jaga med måtta slaktar de vilt på slätterna och lämnar flådda kadaver och rubbade ekosystem efter sig. För ett folk som försöker bygga ett fredligt hemland i Mulgore kan denna vårdslösa slakt inte tolereras."},{t="När ord inte räcker",b="Baine Bloodhoof hoppades först kunna lösa saken fredligt och försökte inleda en dialog med gnollerna som trängde in på taurenfolkets marker. Palemanes avvisade varje försök och svarade diplomati med fientlighet och fortsatt förödelse. När förhandlingar visar sig vara lönlösa tar Baine till våld. Unga krigare skickas direkt till deras jaktläger för att sätta stopp för tjuvjägarna, garvarna och flåarna innan gräsmarkerna skadas för alltid."},{t="Livets och dödens kretslopp",b="Uppdraget är en övergångsrit och en moralisk läxa för unga hjältar. När de återvänder efter att ha rensat ut fienderna påminner Baine The Adventurer om att man aldrig får ta liv av illvilja, utan bara när det krävs för att bevara harmonin. Liv och död ingår i en sammanhängande krets där det ena inte kan frodas utan det andra, en grundläggande sanning som varje väktare av Mulgore måste bära med sig."}},faq={{q="Vem ger uppdraget?",a="Baine Bloodhoof, son till högklanledaren Cairne Bloodhoof, ger uppdraget i Bloodhoof Village i centrala Mulgore.",al={"uppdragsgivare","vem startar sharing the land","baines uppdrag"}},{q="Varför ger sig taurenerna på Palemane-gnollerna?",a="Palemane-gnollerna jagar hänsynslöst på viltet i Mulgore och utarmar hjordarna utan att respektera naturens balans. De avvisade också alla försök från taurenerna att tala fredligt med dem.",al={"varför döda gnoller","palemane-problemet","vad gjorde gnollerna"}},{q="Var finns gnollerna?",a="Palemanes har läger söder om Bloodhoof Village och håller till i grottsystemet Palemane Rock västerut.",al={"gnollernas platser","palemane-läger","var hittar man palemanes"}},{q="Försökte taurenerna sluta fred först?",a="Ja. Baine berättar att taurenerna försökte kommunicera och dela marken flera gånger, men gnollerna visade ingen respekt och avvisade varje fredlig gest.",al={"talade taurenerna med gnollerna","palemane-diplomati"}},{q="Vilken läxa vill Baine lära ut?",a="Baine vill att unga försvarare ska förstå att liv och död ingår i ett oskiljaktigt kretslopp. Ibland måste man ta liv för att försvara balansen, men det måste alltid ske med djup respekt för Jordmodern.",al={"baines läxa","innebörden av sharing the land"}},{q="Vilka är Palemane-gnollerna?",a="De är en primitiv stam från Mulgore som liknar hyenor. De är kända för sin ljusa päls, sin territoriella aggressivitet och sin totala brist på respekt för slätternas harmoni.",al={"vilka är palemanes","palemane-stammen"}}},fx={["901e0c5d"]={q="Vilka ska du ge dig på i Sharing the Land?",a="Baine skickar dig mot Palemane-gnollerna, som har trängt in på slätterna söder om Bloodhoof Village och tagit skydd i en grotta i väster. Dessa tjuvjägare, flåare och garvare har hänsynslöst slaktat Mulgore vilda djur utan respekt för balansen eller Jordmodern. Eftersom de våldsamt avvisat varje fredlig vädjan från taurerna återstår bara våld för att stoppa deras tjuvjakt.",al={"mål i sharing the land","vem ska jag döda i sharing the land","palemane-gnoller i sharing the land"}}},fp="16,178,21.364.0,15.287.0,28.197.0,21.117.0,49.139.0,31.100.0,39.141.0,42.194.0,28.170.0"}
P.entries["quest:746"] = {n="Dwarven Digging",s="Dwarven Digging är ett uppdrag i Mulgore som Baine Bloodhoof ger i Bloodhoof Village. Baine oroar sig för att dvärgarnas utgrävningar ska reta upp de inhemska bestarna och vanhelga den heliga jorden. Därför ber han unga hordförsvarare sabotera arbetet genom att beslagta och slå sönder deras hackor.",h="Dwarven Digging är ett uppdrag i Mulgore som Baine Bloodhoof ger i Bloodhoof Village.",kw={"baine bloodhoof","bloodhoof village","dvärg","smedja","kodo","mulgore","hackor","prospektör"},ang={["class:Shaman"]="Schamaner förstår att vårdslösa utgrävningar stör berggrunden och rubbar den elementära balansen, vilket väcker oro bland landets andar och varelser.",["faction:Horde"]="Dvärgar som står på Alliansens sida tränger in i hordens hjärtland och undergräver den sköra freden som upprättades efter det tredje kriget. De visar tydlig brist på respekt för stammarnas gränser.",["profession:Mining"]="Gruvarbetare vördar rikedomarna som döljs i stenen, men dvärgarnas metoder i Mulgore saknar respekt och harmoni och leder i stället till hänsynslös förstörelse.",["race:Tauren"]="Jordemoderns kropp är helig. Att se främmande inkräktare borra sig in i Mulgore böljande stäpper är en kränkning som kräver ett omedelbart och bestämt svar."},sec={{t="Inkräktare i kullarna",b="Nordväst om Bloodhoof Village har dvärgiska prospektörer börjat märka ut en utgrävningsplats bland Mulgore böljande kullar. Explorer's League och dess utgrävningslag söker titanreliker och jordens hemligheter över hela Kalimdor, men deras verksamhet visar sällan respekt för ursprungsfolkens marker eller seder. För tauren är jorden en levande moder som ska vördas, inte skalas av och gröpas ur efter sten och metall."},{t="Att försvara den heliga jorden",b="Baine Bloodhoof inser att dvärgarnas maskiner och skoningslösa sprängningar hotar slätternas sköra harmoni. Förutom den fysiska förstörelsen oroar oljudet traktens djurliv och driver slättens kodos till ursinne. Genom att slå sönder prospektörernas verktyg vid deras egna smedjor hoppas tauren sända ett tydligt budskap och hejda intrånget innan bestående skada sker."}},faq={{q="Varför gräver dvärgar i Mulgore?",a="Dvärgiska prospektörer tror att jordens djup i centrala Kalimdor döljer hemligheter och forntida föremål. Men deras brist på respekt för stammarnas territorium och våldsamma gruvmetoder har lett till direkt konflikt med tauren.",al={"dvärgar i mulgore","varför är prospektörerna här","dvärgutgrävning i mulgore"}},{q="Vem ger uppdraget Dwarven Digging?",a="Uppdraget ges av Baine Bloodhoof, den unge sonen till Cairne Bloodhoof, den store hövdingen. Han finns i Bloodhoof Village i centrala Mulgore.",al={"uppdragsgivare för dwarven digging","vem startar dwarven digging"}},{q="Varför vill Baine att verktygen ska slås sönder i stället för att bara stjälas?",a="Baine vill göra utrustningen helt obrukbar för att genast stoppa utgrävningen. När verktygen förstörs i smedjorna blir budskapet både symboliskt och praktiskt: landet lämnar inte ifrån sig sina hemligheter genom våld och vanhelgande.",al={"varför slå sönder hackorna","förstöra dvärgarnas verktyg"}},{q="Hur påverkar grävandet djurlivet i Mulgore?",a="Det högljudda grävandet och de djupa såren i marken oroar de inhemska varelserna kraftigt, särskilt de väldiga kodos som strövar i kullarna. Fredliga hjordar blir lättretliga och aggressiva.",al={"arga kodos","varför är bestarna arga"}},{q="Var kan hackorna slås sönder?",a="Hackorna kan hamras till skrot vid vilken fungerande smedja som helst. Du kan använda smedjan mitt i dvärgarnas utgrävningsläger eller ta dem till smederna i Thunder Bluff.",al={"var finns smedjan","slå sönder prospektörernas hackor i smedjan"}},{q="Har det här uppdraget koppling till Explorer's League större närvaro i Kalimdor?",a="Ja. Dvärgexpeditioner från Ironforge har upprättat utposter över hela Kalimdor, bland annat i Mulgore, The Barrens och södra Kalimdor. De utlöser ofta skärmytslingar med hordens folk om territoriell självbestämmanderätt och heliga platser.",al={"explorer's league i mulgore","ironforge i kalimdor"}}},fx={["755e231a"]={q="Vad ska Broken Tools användas till?",a="Broken Tools är ett konkret bevis på att du har satt stopp för dvärgarnas verksamhet. I stället för att bara driva bort prospektörerna eller ta deras utrustning vill Baine Bloodhoof att deras hackor slås sönder vid en smedja och återlämnas till honom. Då säkerställs att arbetet upphör och att ett tydligt budskap sänds mot vanhelgandet av den heliga jorden.",al={"broken tools","varför broken tools","syftet med broken tools"}},["95107d94"]={q="Vilka är dvärgarna som gräver i Mulgore?",a="De är dvärgiska prospektörer som har slagit upp ett utgrävningsläger i de nordvästra kullarna i Mulgore. De drivs av rykten om att uråldriga hemligheter ligger begravda under slätterna och söker historiska reliker och kunskap om titanerna, utan tanke på den andliga skada som deras stenbrott orsakar landet och dess vilda djur.",al={"dvärgar i mulgore","vilka är dvärggrävarna","prospektörer i mulgore"}}},fp="15,187,24.365.0,26.324.0,35.185.0,36.130.0,63.159.0,52.156.0,31.131.0,75.217.0"}
P.entries["quest:747"] = {n="The Hunt Begins",s="The Hunt Begins är en grundläggande övergångsrit för unga äventyrare i Camp Narache på Red Cloud Mesa. På uppdrag av Grull Hawkwind ger sig de nyinvigda ut för att jaga lokala plainstriders och skaffa kött och fjädrar åt byn. När uppdraget är slutfört har de tagit första steget mot att vinna Chief Hawkwinds respekt och så småningom få tillträde till Thunder Bluff.",h="The Hunt Begins är en grundläggande övergångsrit för unga äventyrare i Camp Narache på Red Cloud Mesa.",kw={"camp narache","chief hawkwind","fjädrar","grull hawkwind","the hunt begins","mulgore","plainstrider","red cloud mesa"},ang={["class:Hunter"]="Att smyga sig på de snabba plainstriders på Red Cloud Mesa är den första praktiska övningen i skytte, spårning och att hedra djuren som försörjer dig.",["race:Tauren"]="För unga shu'halo är det en viktig övergångsrit att fälla sina första plainstriders på platån. Det bekräftar bandet till landet och plikten att försörja Camp Narache."},sec={{t="En stams försörjning",b="På höjderna av Red Cloud Mesa flätas överlevnad och tradition samman. Tauren jagar av nödvändighet för att ge sitt folk mat och kläder, men ser också smygandet och jakten som ett viktigt prov på disciplin och en sport. När förråden i Camp Narache börjar sina vänder sig samhället till sina unga för att samla färskt plainstriderkött till matlagningen och tåliga fjädrar till stammens kläder."},{t="Att vinna erkännande",b="Ingen blivande hjälte lämnar Red Cloud Mesa för Mulgores vidsträckta trakter utan att först visa sitt värde. Grull Hawkwind bedömer de nyanländas karaktär och kräver att de visar vad de går för innan de får träffa hans far, Chief Hawkwind. En lyckad jakt visar inte bara självständighet, utan också hängivenhet till stammen."}},faq={{q="Vem ger det här uppdraget?",a="Grull Hawkwind ger det här uppdraget i Camp Narache. Han är son till byns ledare, Chief Hawkwind, och fungerar som en tidig mentor för unga jägare och äventyrare på Red Cloud Mesa.",al={"uppdragsgivare","vem startar the hunt begins","grull hawkwind"}},{q="Varför jagar man plainstriders i stället för andra djur?",a="Plainstriders är talrika över hela platån och ger både näringsrikt kött som fyller på de sinande matförråden och slitstarka fjädrar till traditionella taurenkläder och prydnader.",al={"varför plainstriders","plainstriderkött och fjädrar","jaga plainstriders"}},{q="Varför måste jag bevisa mitt värde innan jag får träffa Chief Hawkwind?",a="Taurens samhälle värdesätter praktiska insatser och jaktförmåga högt. Grull Hawkwind kräver att de nyinvigda visar grundläggande överlevnadskunskaper och lojalitet mot byn innan hövdingen tar emot dem och ger dem större ansvar.",al={"varför bevisa sig för chief hawkwind","chief hawkwinds godkännande","varför jaga först"}},{q="Vad är det större målet med prövningarna på Red Cloud Mesa?",a="Platån fungerar som en prövningsmark. När en ung tauren har visat Chief Hawkwind och de äldste i Camp Narache vad hen går för anses hen redo att bege sig ner till Mulgore slätter och ta sig in i huvudstaden Thunder Bluff.",al={"syftet med prövningarna på platån","varför är jag på red cloud mesa","lämna red cloud mesa"}},{q="Vad händer efter den här jakten?",a="Om du kommer tillbaka med köttet och fjädrarna får du Grulls godkännande och går direkt vidare till ”The Hunt Continues”, där de nyinvigda spårar större och mer svårfångat villebråd över platån.",al={"nästa uppdrag","fortsättning","vad händer efter the hunt begins"}},{q="Jagar tauren bara för att överleva?",a="Mat och resurser som läder, ben och fjädrar är viktiga, men tauren jagar också för sport och andlig samhörighet. Jakten vässar deras instinkter och hjälper stammarna att hålla sig alerta och starka.",al={"taurens syn på jakt","jaga för sport","varför jagar tauren"}}},fx={["395288c5"]={q="Varför vill Grull Hawkwind att det här blir gjort?",a="Grull Hawkwind ser något lovande i dig och vill att du bevisar ditt värde för stammen och hans far, Chief Hawkwind. Matförråden i Camp Narache börjar sina, och lägret behöver färska fjädrar. Genom att skicka dig för att samla in dem prövar han din jaktinstinkt samtidigt som byns nödvändiga förråd fylls på.",al={"varför vill grull att plainstriders jagas","grull hawkwinds motiv","varför jaga plainstriders åt grull"}},f26a5c4f={q="Vad ska Plainstrider Meat användas till?",a="Köttet samlas in för att fylla på Camp Naraches sinande matförråd. För att överleva på Red Cloud Mesa krävs en pålitlig tillgång på mat, och jakt på plainstriders ger det färska kött som behövs för att föda de unga jägarna och de äldre som bor i lägret.",al={"vad används plainstrider meat till","varför samla plainstrider meat","användning av plainstrider meat"}},fb1052a7={q="Vad ska Plainstrider Feather användas till?",a="Taurerna i Camp Narache använder plainstriderfjädrar till kläder och prydnader. Stammen tar vara på varje del av djuren de jagar och förvandlar den tåliga fjäderdräkten till praktiska kläder och utsmyckningar som passar livet på platån.",al={"vad används plainstrider feathers till","varför samla plainstriderfjädrar","användning av plainstrider feather"}}},fp="15,195,20.251.0,19.245.0,21.116.0,53.151.0,59.149.0,59.122.0,27.139.0,33.193.0"}
P.entries["quest:748"] = {n="Poison Water",s="Poison Water inleder taurenfolkets arbete med att rena de heliga brunnarna i Mulgore från föroreningar. På uppdrag av Mull Thunderhorn i Bloodhoof Village samlar unga Horde-försvarare naturmaterial från slätterna för att skapa en återställande ritualtotem.",h="Poison Water inleder taurenfolkets arbete med att rena de heliga brunnarna i Mulgore från föroreningar.",kw={"bloodhoof village","reningstotem","mulgore","mull thunderhorn","plainstrider","poison water","prärievarg","winterhoof water well"},ang={["class:Druid"]="När gobliner förgiftar färskvattenkällor angriper de naturens balans direkt. Det kräver ett omedelbart svar för att bevara Mulgore sköra växt- och djurliv.",["class:Shaman"]="Att återställa förorenat vatten med totemer stärkta av djur visar grunderna i taurenfolkets schamanism: att samarbeta med traktens djurliv för att hela störningar i elementen.",["race:Tauren"]="Skändningen av färskvatten angriper kärnan i Jordmoderns gåvor och gör reningsritualen till en grundläggande plikt för varje tauren som blir vuxen i Mulgore."},sec={{t="Ett skändat land",b="Mulgore grässlätter är helig mark för taurenfolket, men lömska krafter har börjat hota deras livsnödvändiga vatten. Mull Thunderhorn, en äldste i Bloodhoof Village, upptäcker att goblinintränglingar och deras hantlangare har förorenat de dyrbara brunnar som försörjer stammarna och traktens djurliv. Föroreningen angriper direkt det andliga hjärtat hos det nomadfolk som nyligen bosatt sig här."},{t="Naturens kraft samlas",b="För att motverka industriella föroreningar förlitar sig Mull på traditionell tauren-schamanism i stället för grova botemedel. För att rena Winterhoof Water Well måste man skapa en kraftfull ritualtotem fylld med livskraften från Mulgore ursprungliga rovdjur. Han skickar jägare över de sydvästra slätterna för att spåra prärievargar efter deras tassar och vuxna plainstriders efter deras klor, så att landet kan använda sin egen kraft för att läka sina sår."}},faq={{q="Vem förgiftade brunnarna i Mulgore?",a="Goblinernas intrång och deras lejda hantlangare ligger bakom föroreningen av de heliga vattenhålen i Mulgore. Deras destruktiva industriella verksamhet och brist på respekt för naturens balans hotar både taurenstammarna och det lokala djurlivet.",al={"vem förorenade brunnarna","vem förgiftade mulgore","vem förorenade vattnet"}},{q="Varför behöver Mull Thunderhorn vargtassar och plainstriderklor?",a="Mull skapar traditionella reningstotemer av delar från Mulgore inhemska djur. Genom att ta vara på slätternas rovdjurs inneboende andar och styrka skapar han ett fokus som är kraftfullt nog att leda en vattenreningsritual.",al={"varför vargtassar","varför plainstriderklor","material till totem"}},{q="Vilken brunn ska det här uppdraget förbereda för rening?",a="Materialen samlas specifikt för att skapa reningstotemen till Winterhoof Water Well, den första i en rad förorenade brunnar som måste renas genom ritualer.",al={"vilken brunn är detta till","vilken vattenbrunn"}},{q="Var finns Mull Thunderhorn?",a="Mull Thunderhorn bor i Bloodhoof Village, den främsta taurenbosättningen mitt i Mulgore, kring Stonebull Lakes vatten.",al={"var finns mull thunderhorn","var finns mull","var lämnar man in poison water"}},{q="Var hittar man vargarna och plainstriders som behövs?",a="Prärievargar och vuxna plainstriders strövar omkring på slätterna sydväst om Bloodhoof Village.",al={"var hittar man prärievargar","var finns plainstriders","jaktmarker"}},{q="Vad händer när Mull får tassarna och klorna?",a="Mull binder samman de insamlade delarna till en Winterhoof Cleansing Totem och ber dig bära den direkt till Winterhoof Water Well för att utföra reningsriten.",al={"nästa uppdrag efter poison water","vad gör jag härnäst"}}},fx={["50414ce1"]={q="Varför vill Mull Thunderhorn att det här blir gjort?",a="Gobliner och deras hantlangare har förorenat de heliga vattenkällorna i Mulgore och angripit själva livsnerven i taurenfolkets hemland. För Mull Thunderhorn och invånarna i Bloodhoof Village innebär förorenade källor sjukdom och en kränkning av jordens heliga balans. Att rena dem är en brådskande andlig och praktisk plikt.",al={"mull thunderhorns motiv","varför rena vattenkällorna","varför uppdraget poison water"}}},fp="12,192,17.320.0,26.311.0,40.142.0,65.130.0,46.77.0,34.109.0,58.86.0,53.143.0"}
P.entries["quest:749"] = {n="The Ravaged Caravan",s="Morin Cloudstalker ber resenärer undersöka vraket efter en överfallen Venture Company-karavan nära Stonebull Lakes norra strand. Taurenerna satte karavanen i brand som hämnd för förlorade kamrater, men goblinskrotletare återvände för att bärga oskadat gods. En undersökning av de överlevande Supply Crate-lådorna avslöjar den verkliga industriella omfattningen av Venture Companys verksamhet i Mulgore.",h="Morin Cloudstalker ber resenärer undersöka vraket efter en överfallen Venture Company-karavan nära Stonebull...",kw={"morin cloudstalker","mulgore","ravaged caravan","stonebull lake","supply crate","venture company"},ang={["faction:Horde"]="Okontrollerad företagsutvidgning i Mulgore hotar Thunder Bluffs stabilitet. Hordens spejare måste därför störa Venture Companys logistik.",["profession:Mining"]="De robusta lådorna och logistikanteckningarna visar att Venture Company bedriver aggressiv mineralprospektering och utvinning över hela Mulgore.",["race:Tauren"]="Venture Companys maskiner ödelägger slätterna, och deras skogsröjning hotar ditt förfädersland. Därför är det avgörande för Mulgorets försvar att återta och förstöra deras förråd."},sec={{t="Hämnd vid sjön",b="De förkolnade resterna längs Stonebull Lakes norra strand vittnar om en snabb attack från taurenerna. Sörjande över två följeslagare som dödats i en tidigare skärmytsling överföll Morin Cloudstalker och hans krigare en beväpnad försörjningskaravan från Venture Company. Taurenerna ville utplåna inkräktarnas verksamhet och satte vagnarna i brand innan de lämnade det rykande vraket. De trodde att elden skulle förtära allt som goblinerna försökte frakta."},{t="Oavslutade affärer",b="Taurenerna upptäckte snart att Venture Companys bärgare letade bland de förkolnade resterna. Det tydde på att elden inte hade förstört det viktigaste godset. Morin skickar ut spejare för att undersöka vraket i stället för att riskera fler liv i blindo. Bland de sotiga resterna finns oskadade lådor märkta med Venture Company Mining Divisions insignier. De är packade för transport till centrala bearbetningsanläggningar."}},faq={{q="Varför förstördes karavanen?",a="Morin Cloudstalker och hans taurenkrigare överföll och brände karavanen som hämnd efter att två av deras spejare dödats i en tidigare sammanstötning med Venture Company.",al={"vem förstörde karavanen","varför brinner karavanen","karavanattack"}},{q="Var ligger Ravaged Caravan?",a="De brända vagnarna står längs Stonebull Lakes norra strand, öster om Bloodhoof Village i Mulgore.",al={"karavanens plats","var ligger karavanen","ravaged caravan plats"}},{q="Varför återvänder goblinerna till vraket?",a="Venture Company skickade dit bärgare eftersom elden inte förstörde allt deras gods. De försöker hämta hållbara försörjningslådor märkta för leverans till företagets centrala bearbetningsanläggningar.",al={"varför är bärgarna här","venture companys bärgare","vad vill goblinerna ha"}},{q="Vad finns i försörjningslådorna?",a="Lådorna bär Venture Company Mining Divisions insignier och innehåller mineralresurser märkta för raffinering och bearbetning vid företagets främsta industrianläggningar.",al={"lådornas innehåll","vad finns i lådan","förseglad försörjningslåda"}},{q="Vem är Morin Cloudstalker?",a="Morin Cloudstalker är en tauren-spejare och spårare som är stationerad öster om Bloodhoof Village. Han har i uppgift att bevaka fientliga intrång i centrala Mulgore, särskilt från Venture Company.",al={"vem är morin","morin cloudstalkers roll"}},{q="Vad avslöjar karavanen om Venture Company?",a="Den visar att Venture Companys närvaro i Mulgore inte bara består av ett utforskningsteam, utan av en organiserad industriell utvinningsverksamhet med beväpnade försörjningsleder och centraliserade raffineringsnätverk.",al={"venture companys närvaro i mulgore","varför är gobliner i mulgore"}}},fx={["89fc7cfd"]={q="Varför vill Morin Cloudstalker att karavanens lådor undersöks?",a="Morin och hans krigare överföll Venture Companys karavan vid Stonebull Lake för att hämnas fallna kamrater. De brände vagnarna och trodde att elden skulle förinta allt av värde. När han såg goblinernas asätare leta igenom vraket förstod han att något värdefullt eller farligt hade överlevt lågorna. Han behöver att du undersöker lådorna för att ta reda på vad Venture Company transporterade genom Mulgore och varför de är så ivriga att återfå det.",al={"varför undersöka karavanen","morin cloudstalkers motiv","varför söka igenom försörjningslådorna"}}},fp="19,223,23.315.0,19.356.0,30.176.0,37.100.0,46.185.0,33.171.0,26.185.0,56.206.0"}
P.entries["quest:7493"] = {n="The Journey Has Just Begun",s="Efter Onyxias fall lär sig skickliga läderarbetare i Orgrimmar hur hennes fjäll kan skydda mot den svarta drakflygeln. Overlord Runthak erkänner deras hantverk och lär dem en sällsynt teknik för att tillverka skyddande mantlar, som behövs mot lågorna i Blackrock Spire.",h="Efter Onyxias fall lär sig skickliga läderarbetare i Orgrimmar hur hennes fjäll kan skydda mot den svarta...",kw={"blackrock","yngelmamma","kappa","läderarbete","runthak","nefarian","onyxia","fjäll"},ang={["faction:Horde"]="För Horde är skyddsutrustning smidd av fallna fiender avgörande för att värna styrkorna mot ytterligare drakförödelse."},sec={{t="En yngelmammas arv",b="Onyxias fall är en triumf för Horde, men den svarta drakflygeln är fortfarande ett hot. Yngelmammans fjällklädda skinn står emot drakeld. Hordes ledare söker hantverkare som kan förvandla drakens kvarlevor till skyddande rustning i stället för att låta dem gå till spillo."},{t="Skydd mot skuggflamma",b="Overlord Runthak lär begåvade läderarbetare att sy Onyxia Scale Cloak. Kunskapen är ingen tom uppvisning eller prestigemarkör. Djupt inne i Blackrock Mountain andas Onyxias bror Nefarian ut förödande eld. Utan yngelmammans fjälls förtrollade skydd skulle varje förtrupp som möter Lord of Blackrock förvandlas till aska."}},faq={{q="Vem erbjuder uppdraget och var finns personen?",a="Overlord Runthak erbjuder detta i Orgrimmar. Han erkänner Hordes mästare med mästerlig skicklighet i läderarbete som hjälpte till att besegra Onyxia.",al={"uppdragsgivare runthak","var finns overlord runthak","uppdragsstart"}},{q="Vilket krav måste uppfyllas för att få uppdraget?",a="Endast skickliga läderarbetare som har slutfört efterspelet efter Onyxias nederlag kan få detta, till exempel de som slutfört ”Victory for the Horde” eller ”A Most Puzzling Circumstance”.",al={"krav på läderarbete","hur får man uppdraget","förkunskapskrav"}},{q="Vad lär Overlord Runthak ut?",a="Overlord Runthak lär läderarbetare tekniken för att tillverka Onyxia Scale Cloak av fjäll från den fallna yngelmodern.",al={"recept som uppdragsbelöning","onyxia cloak-mönster","vad lär jag mig"}},{q="Varför är Onyxia Scale Cloak viktig?",a="Manteln skyddar bäraren mot Nefarians dödliga, brännande andedräkt. Utan dess unika skydd skulle det vara livsfarligt att möta ynglets herre.",al={"varför tillverka en kappa","kappans syfte","nefarian-kappa"}},{q="Vem är Lord of Blackrock?",a="Nefarian är Lord of Blackrock, en mäktig svart drake och Onyxias bror. Han smider planer från höjderna i Blackrock Mountain för att härska över de dödliga raserna.",al={"vem är lord of blackrock","nefarian identitet","blackrocks herre"}},{q="Varför säger uppdraget att resan just har börjat?",a="Onyxia har dräpts, men det större kriget mot den svarta drakflygeln och Nefarians planer i Blackrock Mountain har bara trappats upp.",al={"titelns betydelse","varför resan just har börjat"}}},fx={cb1b5404={q="Varför vill Overlord Runthak att det här blir gjort?",a="Overlord Runthak vill utrota Black Dragonflight fullständigt. Onyxias nederlag var en stor triumf, men hennes avkomma hemsöker fortfarande riket under hennes bror Nefarians befäl. Genom att lära ut den uråldriga tekniken att smida skyddskappor av yngelmammans fjäll ser Runthak till att Hordens mästare får det avgörande skydd de behöver för att stå emot Nefarians dödliga Shadow Flame och avsluta kriget.",al={"varför ger runthak det här uppdraget","overlord runthaks motiv","runthaks mål"}}},fp="26,199,22.250.0,27.344.1,49.139.0,49.183.0,33.118.0,40.147.0,29.158.0,57.142.0"}
P.entries["quest:7497"] = {n="The Journey Has Just Begun",s="I Stormwind känner Major Mattingly igen hantverkaren som besegrade Onyxia. Han lär ut hantverket som krävs för att göra en mantel av hennes fjäll.",h="I Stormwind känner Major Mattingly igen hantverkaren som besegrade Onyxia.",kw={"svarta drakflykten","blackrock","läderbearbetning","major mattingly","nefarian","onyxia","onyxia scale cloak","stormwind"},ang={["faction:Alliance"]="Som allianshjälte för du vidare Stormwinds seger över Onyxia i den kommande offensiven mot hennes bror Nefarian vid Blackrock Mountain."},sec={{t="En sällsynt skicklighet",b="Få av dem som hjälpte till att besegra Onyxia kan också bearbeta hennes skinn. När en hantverkare med mästerlig läderbearbetning rapporterar till Major Mattingly i Stormwind inser officeren hur viktiga dessa färdigheter är inför striderna som väntar."},{t="Skydd mot den svarta drakflykten",b="Onyxias död innebär inte att den svarta drakflykten har slutat vara ett hot. Major Mattingly lär hantverkaren att behandla och sy ihop hennes fjäll till en Onyxia Scale Cloak. Plagget skyddar bäraren mot den eldiga andedräkten från hennes bror Nefarian, Lord of Blackrock."}},faq={{q="Vem erbjuder uppdraget The Journey Has Just Begun?",a="Major Mattingly i Stormwind City erbjuder det till allianshjältar som kämpade i fälttåget mot Onyxia och har mästerlig läderbearbetning.",al={"vem ger uppdraget the journey has just begun","var hittar jag the journey has just begun","uppdragsgivare för the journey has just begun"}},{q="Vad lär man sig i det här uppdraget?",a="Major Mattingly lär mästerliga läderarbetare att göra en Onyxia Scale Cloak av Onyxias fjäll.",al={"vilket recept får jag","onyxia cloak recept","belöning för the journey has just begun"}},{q="Varför behövs Onyxia Scale Cloak?",a="Manteln har behandlats för att skydda bäraren mot Nefarians, Lord of Blackrocks, eldiga andedräkt.",al={"varför behöver jag onyxia cloak","vad används onyxia scale cloak till","skydd mot skuggflamma"}},{q="Vem är Lord of Blackrock som Major Mattingly nämner?",a="Lord of Blackrock är Nefarian, en mäktig svart drake och Onyxias bror. Han härskar över Blackrock Spire och fortsätter den svarta drakflyktens planer.",al={"vem är lord of blackrock","vem är nefarian","mattinglys drakvarning"}},{q="Varför måste hjälten vara läderarbetare för att få den här kunskapen?",a="Att bearbeta drakfjäll utan att förstöra deras magiska skydd kräver en mästerlig läderarbetares avancerade skicklighet.",al={"varför krävs läderbearbetning","kan vem som helst få uppdraget","krav på läderbearbetning"}},{q="Löser Onyxias död hotet från den svarta drakflykten i Stormwind?",a="Nej. Onyxia är död, men hennes bror Nefarian befaller fortfarande över Blackrock Mountain och smider planer mot alliansen och de dödliga folken.",al={"är stormwind säkert nu","onyxia är död, vad händer nu","svarta drakflykten efter onyxia"}}},fx={b42a6800={q="Varför delar Major Mattingly med sig av den här kunskapen?",a="Major Mattingly vet att dråpet på Onyxia bara var det första angreppet. Yngelmamman är död, men hennes släkte hotar fortfarande Azeroth från Blackrock Mountains höjder. För att utplåna den återstående svarta drakflocken måste mästarna överleva Nefarians brännande lågor. Mattingly delar med sig av den här särskilda tekniken så att Alliansens hjältar kan tillverka skyddskappor av Onyxias fjäll och avsluta kriget.",al={"varför lär mattingly dig","major mattinglys motiv","mattinglys skäl"}}},fp="26,129,14.184.0,41.232.1,48.150.0,27.97.0,40.99.0,58.153.0,63.116.0,65.131.1"}
P.entries["quest:75"] = {n="The Legend of Stalvan",s="Utredningen om Stalvan Mistmantle leder från Duskwood till ett ensligt hem i sydöstra Elwynn Forest. Marshal Haggard, en åldrad veteran med försämrad syn, visar dig en kista på övervåningen med en gammal bunt papper som lämnades kvar när han flyttade in.",h="Utredningen om Stalvan Mistmantle leder från Duskwood till ett ensligt hem i sydöstra Elwynn Forest.",kw={"duskwood","elwynn forest","bleknad journal page","forlorn spirit","marshal haggard","stalvan"},ang={["faction:Alliance"]="När Stalvans arv nystas upp blottas mörka kapitel som ligger gömda inom Elwynns annars fridfulla landsbygdsgränser.",["race:Human"]="Stalvans väg slingrar sig genom vanliga mänskliga bosättningar och blir en varnande berättelse om isolering och ondska som döljer sig mitt framför ögonen på alla."},sec={{t="En veterans vind",b="Marshal Haggard bor långt från staden, i utkanten av sydöstra Elwynn Forest, nära gränsen till Duskwood och Redridge. När han flyttade in i sitt avskilda hem hittade han en kista på övervåningen, full av gamla pergament. Hans sviktande syn blev allt grumligare, så han gav upp försöken att läsa dem och lät dokumenten ligga orörda tills en utredare frågar om Stalvan."},{t="Kvarhängande skuggor",b="Papperen i kistan på övervåningen är inga vanliga rester från ett hushåll. När någon rör vid Stalvans tillhörigheter väcks ofta rastlös magi, som lockar fram en Forlorn Spirit bunden till Mistmantles förflutna. Den gömda journal page ger en direkt inblick i Stalvans privata anteckningar och konkreta bevis för att den tillbakadragne lärde lämnade spår i Elwynn innan han försvann."}},faq={{q="Vem är Marshal Haggard?",a="Marshal Haggard är en åldrad veteran med nästan ingen syn, som lever stillsamt i en avskild stuga i sydöstra Elwynn Forest. Han har kvar papper som sedan länge glömts bort och som tillhörde Stalvan Mistmantle, och som han hittade i sitt hus.",al={"marshal haggard","haggard elwynn","vem är haggard"}},{q="Varför ledde spåret tillbaka till Elwynn Forest?",a="Ledtrådar från Darkshire och Moonbrook följer Stalvans vandringar genom södra Stormwind. På Haggards gård fanns gamla papper som Stalvan hade lämnat efter sig.",al={"varför elwynn forest","stalvan elwynn","varför bege sig till haggard"}},{q="Vad finns i kistan på övervåningen?",a="Kistan innehåller en bleknad journal page skriven av Stalvan Mistmantle, bevarad bland en bunt pergament som Haggard aldrig lyckades undersöka ordentligt.",al={"kista på övervåningen","bleknad journal page","vad finns i kistan"}},{q="Varför anfaller en ande när kistan öppnas?",a="En Forlorn Spirit hemsöker relikerna från Stalvans forna liv och visar sig våldsamt när en främling stör hans personliga anteckningar och minnen.",al={"forlorn spirit","varför anfaller anden","ande i haggards hus"}},{q="Hur för utredningen om Stalvan framåt?",a="Den bleknade sidan ger förstahandsbevis med Stalvans egen handstil och hjälper dig att pussla ihop berättelsen om hans förflutna.",al={"stalvans mysterium","vad avslöjar sidan","steg i stalvans uppdragskedja"}},{q="Varför kunde Marshal Haggard inte läsa papperen själv?",a="Med åren har Haggards syn blivit grumlig och svag, så han kan inte tyda liten eller bleknad handstil på de gamla dokumenten.",al={"haggard blind","varför haggard behöver hjälp"}}},fx={["7284e072"]={q="Varför vill Marshal Haggard att det här blir gjort?",a="Marshal Haggard är en gammal soldat som lever ett stillsamt pensionärsliv, men han har fortfarande kvar en riksofficers instinkter. När du söker sanningen om Stalvan Mistmantle minns han de bortkastade pergamenten som låg kvar i kistan när han tog över huset. Han har ingen egen del i den mörka gåtan, men vill hjälpa dig med undersökningen så gott han kan, även om hans sviktande syn hindrar honom från att själv granska pappren.",al={"varför hjälpa haggard","marshal haggards motiv","varför vill haggard ha dagboken"}}},fp="21,157,17.291.0,17.283.1,23.159.0,45.144.0,34.136.0,50.115.0,48.100.1,53.117.0"}
P.entries["quest:750"] = {n="The Hunt Continues",s="The Hunt Continues är en tidig övergångsrit som Grull Hawkwind ger i Camp Narache. Uppdraget går ut på att samla pälsar från mountain cougars i de södra kullarna, så att stammens barn får kläder och deras tält kan lagas.",h="The Hunt Continues är en tidig övergångsrit som Grull Hawkwind ger i Camp Narache.",kw={"camp narache","chief hawkwind","grull hawkwind","mountain cougar-pälsar","red cloud mesa","taurenjakt","the hunt continues"},ang={["class:Hunter"]="Uppgiften stärker jaktens grundläggande filosofi på slätterna: att spåra djur med ett syfte, bara ta det som behövs och aldrig se djur som ren underhållning eller troféer.",["race:Tauren"]="För unga tauren som blir vuxna på Red Cloud Mesa är det en viktig övergångsrit att lära sig att varje del av ett djur ska tjäna stammen, från mat till kläder och skydd."},sec={{t="Jaktens syfte",b="I Camp Narache får unga jägare lära sig att jakt aldrig är ett nöje eller ett sökande efter troféer. Grull Hawkwind skickar ut unga äventyrare till de södra kullarna på Red Cloud Mesa för att spåra mountain cougars. Uppgiften handlar inte bara om att visa sin skicklighet i strid, utan betonar ansvaret för samhället och visar att riktiga jägare måste skaffa viktiga förnödenheter åt sitt folk."},{t="Skydd åt stammen",b="Livet på platån kräver tåliga material som står emot väder och vind. Grull förklarar att cougarhudarna behövs akut för att sy kläder åt stammens barn och laga de slitna hudtälten i Camp Narache. Den som visar sig kunna skaffa dessa värdefulla pälsar vinner de äldstes tacksamhet, och Grull lovar att själv berätta för sin far, Chief Hawkwind, om jägarens osjälviska insats."}},faq={{q="Varför behöver stammen pälsar från mountain cougars?",a="Pälsarna från mountain cougars är viktiga och användbara resurser för Camp Narache. Grull Hawkwind förklarar att hudarna behövs för att tillverka varma kläder åt stammens barn och för att laga och förstärka byns tält.",al={"varför jaga cougars","vad används cougarpälsar till","användning av mountain cougar-pälsar"}},{q="Vem ger uppdraget?",a="Jakten ges av Grull Hawkwind, en framstående jägare i Camp Narache och son till Chief Hawkwind. Han vägleder nybörjare i de viktiga uppgifter som krävs för att stötta bosättningen.",al={"vem ger the hunt continues","uppdragsgivare i camp narache"}},{q="Var finns mountain cougars?",a="Mountain cougars strövar omkring på de klippiga åsarna och böljande kullarna strax söder om Camp Narache på Red Cloud Mesa.",al={"var finns cougars","mountain cougars plats","var hittar man mountain cougar"}},{q="Hur är Grull Hawkwind släkt med Chief Hawkwind?",a="Grull Hawkwind är son till Chief Hawkwind, stammens ledare i Camp Narache. Om du skaffar de pälsar som behövs lovar Grull att tala med sin far för din räkning och berätta om dina generösa dåd.",al={"hur imponerar man på chief hawkwind","chief hawkwinds son"}},{q="Vad lär jakten ut om tauren-traditionen?",a="Bland tauren betraktas jakt aldrig som sport eller troféjakt. Varje djur som fälls ska försörja samhället. Genom att använda hud, kött och ben för att trygga stammens överlevnad visar man respekt för slätterna.",al={"taurens jaktfilosofi","varför jaga i mulgore"}},{q="Varför är pälsar från mountain cougars så värdefulla?",a="Cougarpälsar är tjocka och tåliga, och lämpar sig väl för att stå emot vädret på de vindpinade slätterna. De ger värme åt små barn och är tillräckligt starka för att laga bostäder, så byns äldste värdesätter dem högt.",al={"är cougarpälsar värdefulla","varför värderas cougarpälsar högt"}}},fp="18,171,23.211.0,21.244.0,46.168.0,22.161.0,37.72.0,54.165.0,49.173.0,55.171.0"}
P.entries["quest:751"] = {n="The Ravaged Caravan",s="En undersökning av en förstörd transport i Mulgore avslöjar att goblinernas industrimän har skaffat sig ett olagligt fäste i taurenfolkets territorium. När spejare återfinner dokument ur en förseglad låda bekräftar de att Venture Company systematiskt utvinner landets mineralrikedomar. Upptäckten får Bloodhoof Outrunners att organisera ett aktivt försvar av sina förfäders slätter.",h="En undersökning av en förstörd transport i Mulgore avslöjar att goblinernas industrimän har skaffat sig ett...",kw={"bloodhoof village","morin cloudstalker","mulgore","outrunners","ravaged caravan","supply crate","venture company","dokument från venture company"},ang={["class:Druid"]="Druider håller landets balans helig, och Venture Companys destruktiva, rökfyllda dagbrottsbrytning är en skändning som måste renas bort.",["faction:Horde"]="Horden förlitar sig på Mulgore lojalitet och stabilitet. Om utländska handelskarteller tillåts skövla kullarna hotas tryggheten i själva Thunder Bluff.",["profession:Mining"]="Den högvärdiga malmen i lådan bevisar att Mulgore östra kullar döljer rika underjordiska ådror som utomstående skyndar sig att exploatera.",["race:Tauren"]="För taurenfolket är det en förolämpning mot Jordmodern och en krigshandling mot deras nyvunna fred att se grova industrimaskiner riva upp Mulgore slätter där deras förfäder levde."},sec={{t="Bevis på exploatering",b="Vraket av en härjad karavan öster om Bloodhoof Village berättar en oroande historia. I en förseglad Supply Crate ligger en stor mängd bruten malm och mineraler, tillsammans med en bunt dokument från Venture Company. Dokumenten ger obestridliga bevis för att det giriga Venture Company har inlett en otillåten gruvdrift djupt inne i Mulgore fridfulla dalar."},{t="Outrunners håller vakt",b="Morin Cloudstalker och hans fellow Outrunners har hållit noggrann uppsikt över Mulgore gränser, medvetna om att utomstående fraktioner vill utnyttja deras fridfulla hemland. När dokumenten överlämnas bekräftas Morins värsta farhågor: rök över de östra kullarna signalerar en växande kommersiell invasion. Taurenfolket har inget annat val än att driva tillbaka fördärvarna innan kullarna blir helt utarmade."}},faq={{q="Vad finns i den förseglade Supply Crate?",a="När lådan bänds upp syns en fullpackad blandning av bruten malm, råa mineraler och en bunt dokument från Venture Company som beskriver deras verksamhet.",al={"byte i supply crate","vad finns i lådan","lådans innehåll"}},{q="Vem är Morin Cloudstalker?",a="Morin Cloudstalker är en tauren Outrunner som är stationerad vid vägen öster om Bloodhoof Village, mot gränsen till The Barrens. Hans uppgift är att patrullera Mulgore och hålla uppsikt över utländska hot.",al={"vem är morin","morins roll","outrunner morin"}},{q="Varför är Venture Company i Mulgore?",a="Venture Company vill hänsynslöst utnyttja Mulgore rika naturresurser och malmådror och gräver sig in i kullarna utan hänsyn till jorden eller dess ursprungsfolk.",al={"varför är gobliner här","venture companys mål i mulgore","vad vill gobliner ha"}},{q="Varifrån kom karavanen?",a="Karavanen tillhörde Venture Company och transporterade bruten malm och verksamhetsdokument från deras verksamhet vid kullarna innan den förstördes längs vägen.",al={"vems karavan var det","karavanens ursprung","vem angrep karavanen"}},{q="Vart leder den här undersökningen härnäst?",a="Med dokumenten i hand skickar Morin Cloudstalker krigare för att konfrontera Venture Companys ledning direkt och slå sönder deras gruvdrift i de östra kullarna.",al={"what comes next","uppdrag efter ravaged caravan","uppföljning av karavanen"}},{q="Varför hotar detta taurenfolket?",a="Taurenfolket ser landet som heligt och vördar Jordmodern. Venture Companys hänsynslösa dagbrottsbrytning och industriella föroreningar skändar aktivt Mulgore orörda landskap.",al={"varför bryr sig taurenfolket","hotet från venture company","hot mot mulgore"}}},fp="19,239,24.279.0,21.389.0,39.132.0,26.162.0,38.150.0,32.175.0,40.169.1,34.170.0"}
P.entries["quest:752"] = {n="A Humble Task",s="A Humble Task är en tidig pliktceremoni som Chief Hawkwind ger i Camp Narache. Medan hövdingen tar hand om viktiga angelägenheter för stammen på Red Cloud Mesa ber han en ung äventyrare bege sig sydost och se till sin åldriga mor vid den lokala vattenkällan. Uppdraget betonar gemensamt ansvar, vördnad för äldre och den dagliga harmoni som är grundläggande för taurenfolkets levnadssätt.",h="A Humble Task är en tidig pliktceremoni som Chief Hawkwind ger i Camp Narache.",kw={"a humble task","camp narache","chief hawkwind","greatmother hawkwind","mulgore","red cloud mesa","vattenkälla"},ang={["faction:Horde"]="Den stillsamma, lantliga prägeln på Naraches uppgifter visar hur taurenfolkets fridfulla gemenskapsfilosofi står i kontrast till den hårdare, överlevnadsinriktade uthållighet som präglar resten av den gryende Horden.",["race:Tauren"]="För unga taurenkrigare visar svaret på hövdingens uppmaning att de följer grundsatserna i Earth Mothers lära: respekt för äldre och orubbligt engagemang för stammens gemensamma välmående."},sec={{t="Gemenskap och plikt",b="I skuggan av Camp Narache förväntas varje medlem av stammen dra sitt strå till stacken och bidra till livets harmoni. För unga tauren som blir vuxna mäts stammens plikter inte bara i stridsförmåga mot quilboars eller rovdjur; de börjar med grundläggande socialt ansvar. Chief Hawkwind visar detta ideal i praktiken: eftersom hans ledarskap inom administration och försvar binder honom vid hans post, litar han på att oerfarna äventyrare ser till samhällets utsatta äldre."},{t="Källan sydost om Narache",b="Mulgore är beroende av viktiga naturliga vattenkällor utspridda utanför lägrets gränser vid Red Cloud Mesa. Tidigt på morgonen lämnade Greatmother Hawkwind byn obevakad för att hämta färskt vatten från källan i sydost. I ett land där territoriella vilddjur och Bristleback quilboars tränger sig på väcker det stilla oro när en äldre person är borta i flera timmar, så Hawkwind skickar hjälp för att försäkra sig om att hon är oskadd."}},faq={{q="Vem ger uppdraget och var hittar jag personen?",a="Chief Hawkwind, ledaren för Camp Narache på Red Cloud Mesa i Mulgore, ger uppdraget. Han står i lägrets centrala paviljong och överblickar de lokala angelägenheterna.",al={"vem ger a humble task","var hämtar jag uppdraget","chief hawkwinds plats"}},{q="Var finns Greatmother Hawkwind?",a="Greatmother Hawkwind finns strax sydost om Camp Narache, där hon sköter vattenkällan på mesans lägre nivå.",al={"greatmother hawkwinds plats","var finns modern","vattenkällans plats"}},{q="Varför tittar inte Chief Hawkwind till sin mor själv?",a="Chief Hawkwind måste stanna i Camp Narache för att sköta viktiga angelägenheter för stammen och vägleda unga krigare. Som hövding förlitar han sig på stammens gemensamma ansvar och litar på att framväxande äventyrare tar hand om byns angelägenheter i hans ställe.",al={"varför kan hövdingen inte gå","varför tittar inte hawkwind till henne","chief hawkwind upptagen"}},{q="Är Greatmother Hawkwind i fara vid källan?",a="Även om slätterna omkring henne hyser aggressiva bergspumor och striders hittas Greatmother Hawkwind välbehållen vid källan, glatt överraskad över att någon gjorde sig besväret att se till en äldre person.",al={"är hon i säkerhet","blir greatmother attackerad","fara vid vattenkällan"}},{q="Vilken kulturell betydelse har uppdraget för tauren?",a="Taurenkulturen värdesätter familjen, gemenskapens sammanhållning och vördnad för äldre högt. Uppdraget lär unga hjältar att sann styrka grundar sig i ödmjuk tjänst och att skydda sina närmaste, inte i att jaga personlig ära.",al={"taurenkultur och a humble task","varför är det här en ödmjuk uppgift","taurenfolkets äldre"}},{q="Vad händer när jag har hittat Greatmother Hawkwind?",a="När du talar med Greatmother Hawkwind slutför hon uppgiften och ber dig om ytterligare hjälp med att bära den fyllda Water Pitcher tillbaka till lägret.",al={"nästa uppdrag","fortsättning på a humble task","vad gör jag när jag hittat modern"}}},fx={b1d313d3={q="Varför vill Chief Hawkwind att du ser till hans mor?",a="Hans gamla mor lämnade Camp Narache tidigt på morgonen för att hämta vatten från brunnen åt sydost, och hon har varit borta länge. Taurenlivet bygger på gemensamt ansvar och omsorg, så även om Hawkwind oroar sig för hennes välbefinnande håller hans plikter som hövding honom kvar i lägret.",al={"varför vill hawkwind få det här gjort","chief hawkwinds motiv","varför se till greatmother hawkwind"}}},fp="13,221,25.328.0,29.371.0,47.153.0,38.101.0,55.229.0,46.204.0,64.185.0,48.116.0"}
P.entries["quest:753"] = {n="A Humble Task",s="A Humble Task är en inledande tjänsterit i Red Cloud Mesa, där en äldre prövar en spirande äventyrares ödmjukhet och flit. Genom att bära färskt brunnsvatten över slätterna till ledaren i Camp Narache lär sig unga tauren att tjänsten för folket börjar med de enklaste sysslorna.",h="A Humble Task är en inledande tjänsterit i Red Cloud Mesa, där en äldre prövar en spirande äventyrares...",kw={"camp narache","chief hawkwind","greatmother hawkwind","humble task","mulgore","red cloud mesa","earthmothers riter","water pitcher"},ang={["faction:Horde"]="Familjen Hawkwinds lärdomar visar hur tauren håller samman och överlever i Mulgore och utgör en fredlig men orubblig hörnsten i Thralls Horde.",["race:Tauren"]="Att hämta vatten åt de äldre förkroppsligar taureners grundläggande dygd att ta hand om gemenskapen och visar att du är redo att följa Earthmothers väg."},sec={{t="Ungdomens kraft",b="Greatmother Hawkwind har vandrat längs många stigar under sitt långa liv, och även om hennes själ fortfarande är stadig bär benen henne inte längre över slätterna med samma fart som i ungdomen. Hon håller till nära brunnen vid Red Cloud Mesas södra utkant och sköter sina plikter med tålmodig beslutsamhet. När blivande stamförsvarare korsar hennes väg leder hon deras ungdomliga energi mot praktiska behov i samhället och ger dem chansen att visa sitt värde genom tjänst snarare än våld."},{t="Tjänst för stammen",b="Uppgiften går ut på att bära en fylld vattenkanna tillbaka nordväst till Camp Narache och överlämna den direkt till bosättningens ledare, Chief Hawkwind, som råkar vara Greatmothers son. I taurenernas samhälle kräver överlevnad på Mulgore torra slätter gemensamt arbete och tillförlitlig tillgång till färskt vatten. Att visa respekt för samhällets äldre genom att ta på sig deras bördor ses som grundstenen i att bli en sann beskyddare av stammen."},{t="En väg mot Thunder Bluff",b="Chief Hawkwind ser mer än en avklarad syssla när en ung vandrare kommer med vatten från hans mor. Enligt taureners sed börjar en individs beredskap att försvara sitt folk i vidare länder med ödmjukhet och en spontan vilja att hjälpa till. Genom att visa denna stillsamma disciplin fångar den unga äventyraren hövdingens uppmärksamhet och får en rekommendation till Earthmothers urgamla riter, de verkliga andliga prövningar som öppnar vägen till Thunder Bluff."}},faq={{q="Vem är Greatmother Hawkwind?",a="Greatmother Hawkwind är en äldre medlem av familjen Hawkwind som håller till vid brunnen i Red Cloud Mesa. Hon är mor till Chief Hawkwind, ledaren i Camp Narache, och vägleder unga tauren i att lära sig ödmjukhet och stammens värderingar.",al={"greatmother hawkwind","vem ger en ödmjuk uppgift","hawkwind-äldste"}},{q="Var ligger brunnen?",a="Brunnen ligger sydost om Camp Narache på Red Cloud Mesas gräsbevuxna slätter. Kannor med färskt brunnsvatten står bredvid den, redo för resenärer och lägerförvaltare att bära tillbaka.",al={"brunnens plats","var finns brunnen","hitta vattenkanna"}},{q="Vem är Chief Hawkwind?",a="Chief Hawkwind är hövdingen som styr Camp Narache i Red Cloud Mesa. Han leder unga taureners träning och andliga riter och förbereder dem för att ge sig ut och tjäna den större stammen i Mulgore.",al={"chief hawkwind","vem är hövdingen","ledaren i camp narache"}},{q="Varför ses den här sysslan som en viktig prövning?",a="Taureners kultur värdesätter ödmjukhet, stöd till samhället och respekt för de äldre högt. Att utföra vardagliga och oglamorösa plikter visar att en äventyrare bryr sig om att hålla sitt folk vid liv, inte bara om personlig ära i strid.",al={"varför bära vatten","varför en ödmjuk uppgift","är uppdraget viktigt"}},{q="Vad händer när A Humble Task är slutförd?",a="När du slutför uppgiften bevisar du din disciplin för Chief Hawkwind, som sedan ber dig genomgå Earthmothers riter, en rad traditionella prövningar som alla tauren måste klara när de blir vuxna.",al={"what comes next","nästa uppdrag","efter humble task"}},{q="Vart leder den här vägen till slut?",a="När du vinner de äldres respekt i Camp Narache är du redo att lämna den avskilda platån bakom dig och färdas ut på Mulgore vida slätter, och till sist mot huvudstadens höga platåer i Thunder Bluff.",al={"framtida resmål","vart är vi på väg","målet thunder bluff"}}},fx={["57bce500"]={q="Varför vill Greatmother Hawkwind att det här blir gjort?",a="Greatmother Hawkwind medger att hennes åldrande ben inte längre har sin forna kraft, vilket gör enkla vardagssysslor runt Red Cloud Mesa långsamma och tröttande. Än viktigare är att hon ser det här rutinärendet som en viktig moralisk läxa för dig. Att leverera livsnödvändigt dricksvatten till hennes son, Chief Hawkwind, blir ett tidigt prov på om du har den ödmjukhet, det tålamod och den gemenskapsanda som förväntas av en sann tjänare åt stammen.",al={"greatmother hawkwinds motiv","varför hämta vatten åt chief hawkwind","varför uppdraget a humble task"}},b511fd77={q="Vad ska Water Pitcher användas till?",a="Water Pitcher är ett enkelt lerkärl med nyhämtat vatten från brunnen på Red Cloud Mesa, avsett att ge Camp Narache rent vatten. Att bära det prövar din hängivenhet till gemensamma sysslor och ser till att även nybörjare bland äventyrarna lär sig värdet av att försörja sina närmaste innan de söker större ära i strid.",al={"water pitchers syfte","varför water pitcher","vad är vattenkannan"}},["19ad5d96"]={q="Varför ber Greatmother Hawkwind dig i stället för att göra det själv?",a="Greatmother Hawkwind är gammal och medger att hennes ben inte längre har sin forna styrka. Därför tar det mycket längre tid än förr att bära tunga vattenkärl. När en arbetsför nybörjare som du dyker upp tar hon chansen att både lätta sin egen börda och pröva om du är villig att utföra oglamoröst vardagsarbete för lägret.",al={"varför gör inte greatmother det själv","varför be mig hämta vatten","varför kan inte hawkwind hämta vatten"}}},fp="13,149,21.336.0,20.330.0,27.367.0,28.184.0,32.172.0,22.165.0,47.158.0,42.134.0,37.130.0"}
P.entries["quest:754"] = {n="Winterhoof Cleansing",s="Winterhoof Cleansing är en rit som Mull Thunderhorn i Bloodhoof Village anförtrott åt Hordens äventyrare. Efter att goblinernas verksamhet förorenat de lokala källorna måste en välsignad totem bäras in på Venture Companys område för att rena Winterhoof Water Well. Att återställa källan är ett viktigt första steg för att läka de förgiftade vattnen i centrala Mulgore.",h="Winterhoof Cleansing är en rit som Mull Thunderhorn i Bloodhoof Village anförtrott åt Hordens äventyrare.",kw={"bloodhoof village","rening","mulgore","mull thunderhorn","gift","totem","venture company","vattenbrunn","winterhoof"},ang={["class:Druid"]="När törstigt djurliv genast återvänder till den renade källan blir det tydligt hur viktigt det är att läka naturen där civilisationen hotar att skövla den.",["class:Shaman"]="Att kanalisera andar genom totemer för att motverka onaturlig industriell förorening är själva kärnan i en shamans band till elementens vatten.",["faction:Horde"]="Att trygga Mulgore färskvatten stabiliserar taurenfolkets nyligen bosatta kärnland och stärker den unga Hordens södra pelare.",["race:Tauren"]="Brunnarna i Mulgore är heliga livskällor som Jordmodern skänkt. Att försvara dem mot goblinernas girighet är både en samhällsplikt och en helig förpliktelse för varje tauren."},sec={{t="Ett skövlat land",b="Mulgore slätter täcks av gräs och är beroende av ett känsligt nätverk av förfädernas vattenbrunnar för att försörja både vilt och de utspridda taurenstammarna. Nyligen flyttade Venture Companys hänsynslösa industriella legosoldater in bland de böljande kullarna sydost om Bloodhoof Village. Deras verksamhet har förorenat de lokala grundvattenmagasinen och gjort Winterhoof Water Well stinkande och giftig. Vilda djur undviker det förorenade vattnet, och de närliggande lägren står inför en överhängande kris om förgiftningen sprider sig längre genom jorden."},{t="Ritualen för renande vatten",b="För att motverka industrins smuts täljer och förtrollar Mull Thunderhorn en rituell reningstotem, fylld med Jordmoderns välsignelser. Men för att leverera botemedlet måste man trotsa beväpnade busar från Venture Company, som har lagt beslag på källan. När äventyraren placerar totemen direkt vid brunnens mynning skingras det förorenade avrinningvattnet, så att rent, livgivande vatten åter kan stiga upp ur jordens djup."}},faq={{q="Var ligger Winterhoof Water Well?",a="Winterhoof Water Well ligger i kullarna sydost om Bloodhoof Village i Mulgore. Den patrulleras flitigt av goblinarbetare och legosoldater som arbetar för Venture Company.",al={"winterhoof-brunnens läge","var ligger winterhoof-brunnen","hur hittar man winterhoof-brunnen"}},{q="Varför förgiftades brunnen?",a="Venture Company upprättade gruvdrift och utgrävningar i närheten, vilket gjorde att giftigt industriellt avfall och skräp kunde sippra direkt ner i grundvattenmagasinet. Därmed blev den naturliga källan odrickbar för det lokala djurlivet och taurenfolket.",al={"vem förgiftade vattnet","varför är brunnen smutsig","venture company-brunnen"}},{q="Vem är Mull Thunderhorn?",a="Mull Thunderhorn är en andlig äldste som håller till i Bloodhoof Village. Han är djupt lyhörd för jordens hälsa och tillverkar ceremoniella totemer för att råda bot på den miljöförstörelse som utomstående inkräktare orsakat.",al={"vem är mull","mull thunderhorns roll"}},{q="Vad händer efter att brunnen har renats?",a="När Winterhoof Water Well åter rinner klart och djurlivet börjar dricka säkert ur den leder Mull Thunderhorn din uppmärksamhet mot andra skadade brunnar i Mulgore, med början vid Thunderhorn Totem.",al={"what comes next","efter winterhoof cleansing","vad gör mull härnäst"}},{q="Vilka vaktar brunnen?",a="Brunnen är ockuperad av arbetare och lejda män som anställts av Venture Company, ett samvetslöst syndikat lett av gobliner som utarmar landområden på naturresurser utan hänsyn till det lokala ekosystemet.",al={"vem vaktar winterhoof-brunnen","vilka fiender finns vid brunnen"}},{q="Hur fungerar reningstotemen?",a="Totemen är snidad enligt taurenfolkets heliga riter och skyddsritualer. Den åkallar naturandar och Jordmoderns välsignelser för att rena källflödet från onaturliga kemiska föroreningar.",al={"reningstotemens historia","hur fungerar mulls totem"}}},fx={["16ee77f0"]={q="Varför vill Mull Thunderhorn att Winterhoof Water Well renas?",a="Winterhoof Water Well är avgörande för Mulgore och dess överlevnad. Vattnet har förorenats och hotar både det lokala djurlivet och stammarna som är beroende av det. Mull Thunderhorn har förberett en vigd reningstotem, men dess kraft måste föras direkt till platsen för att läka vattnet och återställa harmonin i landet.",al={"varför rena winterhoof well","mull thunderhorns motiv","varför rena vattnet i winterhoof"}}},fp="20,271,16.402.0,30.304.0,43.149.0,32.169.0,24.179.0,40.174.1,31.180.0,34.179.0"}
P.entries["quest:7541"] = {n="Service to the Horde",s="Det juvelprydda hänget finns nu hos Zor Lonetree i Orgrimmar. Du lämnade det efter Report to Zor, och Zor har mer att säga dig.",h="Det juvelprydda hänget finns nu hos Zor Lonetree i Orgrimmar.",kw={"dustwallow marsh","hänge","report to zor","tjänst åt horden","zor lonetree"},sec={{t="Zor Lonetree i Orgrimmar",b="Du bar det juvelprydda hänget till Zor Lonetree i Orgrimmar, och nu finns hänget hos Zor. Återvänd till Zor Lonetree för att få höra mer om vad du har gjort för Horden."},{t="Zors sista ord",b="Zor säger att lärda behöver tid för att studera hänget. Som tack för din tjänst åt Horden erbjuder Zor en liten gåva och säger att det du har gjort hedrar både dig och Horden."}},faq={{q="Vem har hänget nu?",a="Zor Lonetree i Orgrimmar, efter att du bar det dit från Nazeer Bloodpike i Brackenwall Village.",al={"vem tar hänget","vem ger det här uppdraget","zor lonetrees roll"}},{q="Vilket uppdrag kommer före det här?",a="Det följer på Report to Zor, där du tog det juvelprydda hänget till Zor Lonetree.",al={"vilket uppdrag kom före","förutsättning för tjänst åt horden","föregående uppdrag"}}},fp="20,117,25.121.0,15.174.1,24.109.0,29.75.0"}
P.entries["quest:755"] = {n="Rites of the Earthmother",s="Rites of the Earthmother inleder en initiands andliga resa på Red Cloud Mesa. Under Chief Hawkwinds ledning söker resenärer upp Seer Graytongue i de södra kullarna vid Camp Narache. Att genomgå dessa vördnadsvärda ceremonier ses som ett avgörande mandomsprov för tauren som nått vuxen ålder.",h="Rites of the Earthmother inleder en initiands andliga resa på Red Cloud Mesa.",kw={"camp narache","chief hawkwind","jordmodern","red cloud mesa","rites of the earthmother","seer graytongue","tauren"},ang={["class:Druid"]="Druidkandidater inleder sin väg mot harmoni med naturen genom att respektera stammens äldstes och siarnas heliga vägledning.",["class:Shaman"]="För blivande schamaner är riter välsignade av stammens siare ett viktigt första steg mot gemenskap med elementen och andarna i Mulgore.",["faction:Horde"]="En förståelse för dessa heliga prövningar ger inblick i den andliga kärnan hos taurenfolkets allierade, som nyligen anslutit sig till Horde.",["race:Tauren"]="Rites of the Earthmother utgör den grundläggande andliga resan för unga tauren och prövar om de är redo att tjäna sin stam och vörda Jordmodern."},sec={{t="Prövningarnas tröskel",b="På Red Cloud Mesa vägleder Chief Hawkwind unga tauren som vill bevisa sig inför Seer Graytongue. Graytongue bor i de stilla kullarna strax söder om Camp Narache och vakar över ungdomarnas andliga början. Den enkla färden markerar den formella tröskeln mellan lägerlivets vardag och de allvarliga åtaganden som stamtraditionen kräver."},{t="Att omfamna Jordmodern",b="Jordmodern står i centrum för taurenfolkets skapelseberättelse och vardagsliv. Hennes riter är heliga prövningar av mognad, uthållighet och andligt djup. Som Seer Graytongue varnar alla som kommer till hans helgedom är det ingen lätt uppgift att inleda Rites of the Earthmother; det kräver fullständig hängivenhet åt mesans traditioner."}},faq={{q="Vem ger uppdraget Rites of the Earthmother?",a="Uppdraget inleds av Chief Hawkwind i Camp Narache, som skickar unga äventyrare till Seer Graytongue i de omgivande kullarna.",al={"vem inleder rites of the earthmother","uppdragsgivare"}},{q="Var hittar jag Seer Graytongue?",a="Seer Graytongue bor i kullarna strax söder om Camp Narache på Red Cloud Mesa i Mulgore.",al={"var finns seer graytongue","graytongues plats","hitta graytongue"}},{q="Vad är Rites of the Earthmother?",a="Rites of the Earthmother är traditionella, heliga övergångsriter som unga tauren genomgår för att visa sin vishet, styrka och hängivenhet till sitt folk och dess tro.",al={"vad är rites of the earthmother","berättelsen om jordmoderns prövningar"}},{q="Vem är Seer Graytongue?",a="Seer Graytongue är en respekterad andlig äldste som bor söder om Camp Narache och vakar över samt vägleder initiander genom Jordmoderns heliga prövningar.",al={"vem är seer graytongue","graytongues roll"}},{q="Vem är Chief Hawkwind?",a="Chief Hawkwind är stamledaren som styr Camp Narache på Red Cloud Mesa. Hans uppgift är att förbereda unga tauren innan han skickar dem till siarna.",al={"vem är chief hawkwind","hawkwinds roll"}},{q="Vad krävs för att slutföra uppgiften?",a="Du behöver bara färdas söderut från Camp Narache in i kullarna och tala med Seer Graytongue för att meddela att du är redo för prövningarna.",al={"vad behöver jag göra","hur slutför jag uppdraget"}}},fp="24,194,27.268.0,25.248.0,45.103.0,33.96.0,38.150.0,23.140.0,22.111.0,39.125.0"}
P.entries["quest:756"] = {n="Thunderhorn Totem",s="Thunderhorn Totem är en uppgift från Mull Thunderhorn i Bloodhoof Village om att tillverka en helig reningstotem. För att bekämpa föroreningarna som gobliner sprider i Mulgore genom vattenkällorna måste unga hjältar i Horde samla naturliga klor från rovdjur på slätterna. På så vis binds landets urkraft till rituellt trä.",h="Thunderhorn Totem är en uppgift från Mull Thunderhorn i Bloodhoof Village om att tillverka en helig...",kw={"bloodhoof village","rening","cougar claws","flatland cougar","mulgore","mull thunderhorn","prairie stalker","stalker claws","thunderhorn totem","vattenkälla"},ang={["class:Hunter"]="För att samla klorna måste du förstå slätternas inhemska smygjägare och hedra bytet för att bevara ekosystemet.",["class:Shaman"]="Totemisk återställning bygger på att åkalla landets levande andar för att rena vatten som förorenats av onaturlig och vårdslös verksamhet.",["race:Tauren"]="Att försvara Mulgore's grundvatten från utländsk exploatering är en helig plikt för stammen. Den följer Jordmoderns uppmaning att leva i balans i stället för att plundra."},sec={{t="Jakten på slätternas rovdjur",b="När Venture Companys industriella exploatering förgiftar Mulgore's dyrbara vattenkällor arbetar Mull Thunderhorn skyndsamt med att skapa botemedel. Thunderhorn Cleansing Totem kräver naturliga essenser från slätternas mest fokuserade jägare: prairie stalkers och flatland cougars. När du tar klorna från dessa rovdjur som strövar öster och väster om Bloodhoof Village, leder ritualen vilddjurens råa, oförstörda jaktkraft direkt in i totemen."},{t="Jaktens natur",b="Tauren-traditionen ser en djup skillnad mellan jakt för försörjning eller andlig balans och goblinernas hänsynslösa plundring. Mull betonar att den renhet med vilken inhemska rovdjur jagar är avgörande för att rena förorenad jord. Där goblinernas maskiner förorenar källorna med olja och industriavfall ger djurens naturliga styrka, när de kämpar med landet, den andliga kraft som behövs för att återställa Thunderhorn Water Well."}},faq={{q="Varför behöver Mull Thunderhorn klor från rovdjur?",a="Mull använder klorna från prairie stalkers och flatland cougars för att leda slätternas rena, ursprungliga rovdjursande in i en reningstotem. Han tror att de naturliga jägarnas rena ande motverkar konstgjord, industriell förorening.",al={"varför klor","syftet med stalker claws","syftet med cougar claws"}},{q="Vem förorenar vattnet i Mulgore?",a="Goblinerna från Venture Company som verkar i Mulgore förorenar marken och vattnet. Deras hänsynslösa utvinning av resurser och gruvriggar leder giftigt slam in i grundvattnet som försörjer stammarnas brunnar.",al={"vem förgiftade brunnen","varför är brunnen förgiftad","vad förgiftade mulgore"}},{q="Var finns prairie stalkers och flatland cougars?",a="Båda djurarterna strövar på de öppna slätterna i centrala Mulgore, främst utspridda över de böljande savannerna direkt öster och väster om Bloodhoof Village.",al={"stalker-plats","var hittar man cougars","platser för cougar claws"}},{q="Vad händer när Thunderhorn Totem har tillverkats?",a="När Mull har snidat och förtrollat totemen med hjälp av klorna skickar han dig direkt till den förgiftade Thunderhorn Water Well för att utföra reningsritualen och driva bort giftet.",al={"vad händer härnäst","efter thunderhorn totem","fortsättning på totemuppdraget"}},{q="Hur hänger detta samman med den tidigare reningen vid Winterhoof Well?",a="Det här ingår i stammarnas pågående arbete med att bevara Mulgore's heliga vatten. Winterhoof Water Well renades först, och nu hotar föroreningen brunnen Thunderhorn längre norrut.",al={"kopplingen till winterhoof","föregående totemuppdrag"}},{q="Varför använder tauren inte bara örtmedel i stället för djurklor?",a="Taurenernas rituella hantverk hämtar kraft från naturens olika elementära och fysiska aspekter. Toppredatorernas skarpa renhet ger en aktiv, kämpande andlig kraft som särskilt behövs för att skära igenom goblinernas aggressiva industrigifter.",al={"varför inte örter","material till shamanistiska totemer"}}},fx={cb047e40={q="Varför vill Mull Thunderhorn att det här blir gjort?",a="Vattnet i Thunderhorn Water Well blir allt mer förorenat för varje timme som går, förgiftat av vårdslösa goblinverksamheter i närheten. Mull Thunderhorn måste skapa en helig reningstotem för att rena brunnen innan föroreningen sprider sig vidare genom jorden och skadar hans folk.",al={"varför vill mull ha det här","mull thunderhorns motiv","varför tillverka thunderhorn totem"}},["43953f1d"]={q="Vilka ska du jaga efter klorna?",a="Du ska jaga de vilda rovdjur som stryker omkring på Mulgore-slätterna: präriesmygare och slättpumor. De strövar naturligt omkring öster och väster om Bloodhoof Village och lever och jagar som en del av landets naturliga balans.",al={"vad ska jag jaga","vilka är målen","byten för thunderhorn totem"}}},fp="17,236,28.346.0,22.354.0,46.210.0,39.176.0,58.144.0,50.174.1,66.166.0,72.198.0"}
P.entries["quest:757"] = {n="Rite of Strength",s="Kraftprovet är det första provet i Jordmoderns traditionella riter, som unga tauren genomgår i Camp Narache. För att visa sitt mod och försvara stammen måste de unga tauren driva bort Bristleback-kvillyborrar som tränger in i Brambleblade Ravine och lämna sina bälten till Chief Hawkwind.",h="Kraftprovet är det första provet i Jordmoderns traditionella riter, som unga tauren genomgår i Camp Narache.",kw={"brambleblade ravine","bristleback","camp narache","chief hawkwind","jordmodern","mulgore","kvillyborre","kraftprov","seer graytongue"},ang={["faction:Horde"]="Genom att försvara platån säkras ett av Horde viktigaste rekryteringsområden, så att unga krigare och schamaner tryggt kan växa upp och hjälpa den nya alliansen.",["race:Tauren"]="Varje ung tauren börjar sin färd genom dessa urgamla riter och visar sig redo att skydda sitt folk mot hotet från kvillyborrarna innan hen lämnar Red Cloud Mesa."},sec={{t="Det första provet",b="För en ung tauren som vill vinna stamäldstarnas erkännande och så småningom bli accepterad i Thunder Bluff är det en viktig plikt att genomföra Jordmoderns riter. Seer Graytongue utdelar Kraftprovet som det första provet. Det kräver fysiskt mod och beslutsamt handlande för att försvara Red Cloud Mesa, och prövar om en ung tauren kan möta stammens dödsfiender utan att vackla."},{t="Hotet från Bristleback",b="Provet utspelar sig i Brambleblade Ravine, en taggig ravin öster om Camp Narache där Bristleback-kvillyborrar håller till. Dessa aggressiva inkräktare tränger ständigt in på stammens förfäders marker, överfaller jaktlag och plundrar lägrets förråd i skydd av mörkret. Att döda dem och ta deras bälten visar både tapperhet och att bosättningen kan hållas trygg."}},faq={{q="Vad är syftet med Kraftprovet?",a="Det är det första steget i Jordmoderns riter och ska pröva en ung taurenes mod i strid. Genom att undanröja hot mot lägret förtjänar den unga tauren rätten att gå vidare mot verklig respekt i Thunder Bluff.",al={"varför göra kraftprovet","kraftprovets historia","syftet med kraftprovet"}},{q="Vem tilldelar och bedömer provet?",a="Seer Graytongue ger den unga tauren uppdraget och förklarar provets andliga och praktiska krav. När tolv Bristleback-bälten har samlats in ska beviset på tapperhet lämnas direkt till Chief Hawkwind i Camp Narache.",al={"vem ger kraftprovet","vem lämnar in kraftprovet"}},{q="Var ligger Brambleblade Ravine?",a="Brambleblade Ravine ligger öster om Camp Narache på Red Cloud Mesa. Det är en taggig ravin som vimlar av fientliga Bristleback-kvillyborrar.",al={"var ligger brambleblade ravine","brambleblades läge"}},{q="Varför angrips Bristleback?",a="Bristleback tränger in på stammens förfäders jaktmarker. De överfaller gång på gång taurenjägare och stjäl förnödenheter från Camp Narache i mörkret, vilket gör dem till stammens direkta fiender.",al={"varför döda bristleback","vad gjorde kvillyborrarna"}},{q="Varför samla bälten i stället för andra troféer?",a="Bälten är konkreta bevis på besegrade krigare. De visar att den unga tauren mötte kvillyborrarna på nära håll och besegrade vuxna stridskämpar, i stället för att bara leta efter saker på avstånd.",al={"varför bristleback-bälten","varför bälten"}},{q="Vad händer när Kraftprovet är avklarat?",a="Att klara Kraftprovet bevisar den unga taurens tapperhet och gör att hen kan gå vidare till Jordmoderns följande prov. Därmed fortsätter den formella vägen mot vuxenlivet och en andlig ställning inom stammen.",al={"vad händer efter kraftprovet","nästa jordmodersrit"}}},fx={f38315d5={q="Varför skickar Seer Graytongue dig till Bristlebacks?",a="Seer Graytongue vägleder ungdomarna i Camp Narache genom Earthmothers heliga riter. I ditt första prov måste han pröva din kampvilja mot ett verkligt och överhängande hot mot stammen. Bristleback-kvilloarna tränger in på taurenmark, överfaller jägare och stjäl i skydd av mörkret. Genom att skicka dig att möta dem ser Graytongue till att du skyddar ditt folk, bevisar din styrka och vinner stammens respekt.",al={"varför vill graytongue ha det här","seer graytongues motiv","varför rite of strength"}},e0dd8e68={q="Varför skickas du ensam för att klara det här provet?",a="Rite of Strength är en personlig övergångsrit, inte en enkel lägersyssla. Medan lägrets krigare bevakar området måste varje ung tauren på egen hand visa mod och stridsförmåga innan hen erkänns som vuxen i Thunder Bluff. Provet kräver att du själv möter ditt folks fiender, så att de äldste vet att du kan försvara stammen när det behövs.",al={"varför jag ska klara rite of strength","varför inte skicka vakter mot bristlebacks","varför måste jag slåss mot bristlebacks"}}},fp="16,165,15.312.0,22.298.0,44.205.0,34.166.0,37.131.0,40.177.0,44.137.0,49.206.0"}
P.entries["quest:758"] = {n="Thunderhorn Cleansing",s="Thunderhorn Cleansing är en viktig andlig ritual i Mulgore. Den ger resenärer i uppdrag att rena den förorenade Thunderhorn Water Well. Med en rituell totem från Mull Thunderhorn återställer äventyrare källan som är livsviktig för den lokala stammen. En lyckad rening får Thunderhorn-förfädernas innerliga uppskattning.",h="Thunderhorn Cleansing är en viktig andlig ritual i Mulgore.",kw={"förfädernas andar","bloodhoof village","reningstotem","jordmodern","mulgore","mull thunderhorn","thunderhorn cleansing","thunderhorn water well"},ang={["class:Druid"]="När förgiftat vatten renas hejdas fördärvets spridning genom Mulgore ekosystem, och slätternas naturliga harmoni bevaras.",["class:Shaman"]="Att kanalisera förfädernas kraft genom totemer för att läka förorenade källor är själva grunden för schamanens kall.",["faction:Horde"]="När du hjälper taurenfolket att skydda sina heliga källor stärks banden mellan den unga Horden och dess stolta Shu'halo-allierade.",["race:Tauren"]="När du återställer de heliga källorna hedrar du Jordmodern och skyddar ditt folk medan de bygger ett varaktigt och fredligt hem i Mulgore."},sec={{t="En förgiftad livsnerv",b="Brunnar över Mulgore slättland är livsviktiga för taurenfolkets nomadstammar, som nyligen slagit sig ned på gräsmarkerna. När giftiga ämnen förorenar dessa underjordiska källor drabbas både djurlivet och närliggande bosättningar hårt. Thunderhorn Water Well ligger norr om Bloodhoof Village och har förorenats. För att läka det sargade landet krävs ett målmedvetet andligt ingripande."},{t="Förfädernas rening",b="För att motverka fördärvet tillverkar Mull Thunderhorn en helgad Cleansing Totem, laddad med andlig kraft. När äventyrare bär reliken till det förgiftade vattnet kan de leda förfädernas kraft in i källan, skingra gifterna och återställa naturens rena balans. Mull får direkt bekräftelse på att uppdraget lyckats när Thunderhorn-förfädernas andar besöker honom i en dröm och uttrycker sin bestående tacksamhet."}},faq={{q="Var ligger Thunderhorn Water Well?",a="Thunderhorn Water Well ligger på slätterna norr om Bloodhoof Village i Mulgore. Den är en av flera viktiga vattenkällor för de lokala taurenklanerna.",al={"thunderhorn-brunnens plats","var ligger brunnen","var använder jag totemen"}},{q="Vem inleder reningsritualen?",a="Mull Thunderhorn inleder ritualen. Han finns i Bloodhoof Village, där han tillverkar särskilda totemer för att läka Mulgore och dess sargade miljö.",al={"vem ger uppdraget","mull thunderhorns plats","uppdragsgivare"}},{q="Varför måste brunnarna i Mulgore renas?",a="Brunnarna i Mulgore har förgiftats och fördärvats på onaturlig väg. Det hotar slätternas sköra balans och överlevnaden för taurenstammarna som är beroende av rent vatten.",al={"varför rena brunnarna","vad hände med vattnet","varför är brunnen förgiftad"}},{q="Hur vet Mull att ritualen lyckades?",a="När ritualen vid brunnen är fullbordad visar sig Thunderhorn-klanens förfäders andar direkt för Mull i en dröm. De prisar äventyrarens insats och framför sitt tack från förfäderna.",al={"förfädernas dröm","hur mull får veta","resultat efter brunnens rening"}},{q="Vad händer efter att Thunderhorn-brunnen renats?",a="Att rena Thunderhorn-brunnen är en del av en större insats för att skydda Mulgore källor. Därefter skickar Mull resenärer vidare för att hjälpa en annan utsatt region genom att tillverka Wildmane Totem.",al={"vad händer sedan","nästa uppdrag efter thunderhorn","nästa wildmane totem"}},{q="Vad är Thunderhorn Cleansing Totem?",a="Thunderhorn Cleansing Totem är ett rituellt snidat andligt redskap som Mull Thunderhorn har tillverkat särskilt för att rena den förorenade brunnen som tillhör hans klan och förfäder.",al={"reningstotem","vad är totemföremålet","mulls totem"}}},fx={da3030fe={q="Varför behöver Mull Thunderhorn att du renar brunnen?",a="Mull Thunderhorn har tillverkat ritualens fokus, men att rena helig mark är en tjänste- och hedersrit för blivande mästare bland tauren och deras allierade. När du själv bär Thunderhorn Cleansing Totem till den förorenade brunnen visar du din hängivenhet till Earthmother och din klans förfädersandar. Då vinner du gunst och vägledning från förfäderna som vakar över vattnet.",al={"varför jag för mull thunderhorn","varför skickar mull dig","varför utföra reningsritualen"}}},fp="21,203,18.263.0,19.244.0,44.156.0,36.113.0,48.90.0,45.101.0,51.116.0,40.136.0"}
P.entries["quest:759"] = {n="Wildmane Totem",s="Wildmane Totem är det tredje och sista steget i Mull Thunderhorns arbete med att skapa renande totem för Mulgore förgiftade brunnar. För att återställa Wildmane Well kräver ritualen offer från de mest vildsinta rovdjuren i området: alfavargar på prärien.",h="Wildmane Totem är det tredje och sista steget i Mull Thunderhorns arbete med att skapa renande totem för...",kw={"bloodhoof village","mulgore","mull thunderhorn","alfavarg på prärien","thunder bluff","totem","vattenbrunn","wildmane"},ang={["class:Hunter"]="Att spåra upp de listiga alfavargarna kring de höga klipporna prövar en jägares respekt för vildmarken och dess farligaste rovdjur.",["class:Shaman"]="Schamaner uppskattar de varsamma riter som krävs för att harmonisera rovdjurstotem med elementärt vatten och rena bort giftiga plågor.",["race:Tauren"]="Reningen av förfädernas brunnar understryker taurenfolkets skyldighet att återställa den ekologiska balansen och hedra de offer som Jordmodern kräver."},sec={{t="Den sista brunnen",b="När materialen för att helga brunnarna Winterhoof och Thunderhorn har säkrats återstår bara en förorenad källa i centrala Mulgore: Wildmane Well. Det förgiftade vattnet över slätterna hotar både flyttande djurliv och bosättningar, och därför krävs kraftfulla ursprungsingredienser för att återställa jordens naturliga balans."},{t="Rovdjurets styrka",b="För att motverka den starka fördärvskorruptionen som dröjer kvar i vattnet i norr behöver Mull Thunderhorn ett offer präglat av vildsinthet. Alfavargar på prärien strövar över gräsmarkerna, särskilt kring de höga klipporna nedanför Thunder Bluff. När du tar deras tänder kanaliseras Mulgore främsta jägares obevekliga drivkraft och motståndskraft direkt in i det renande totemet."},{t="Offer och balans",b="I taurenfolkets andliga tradition har det emotionell och elementär tyngd att ta hjälp av landets varelser. Mull ser insamlingen av alfavargtänder inte som en erövring, utan som en dyster nödvändighet där Mulgore rovdjur offras för att hela Jordmoderns sargade vatten."}},faq={{q="Vad behövs Wildmane Totem till?",a="Mull Thunderhorn skapar totemet för att rena Wildmane Well, den sista förorenade vattenkällan som hotar taurenfolket i Mulgore.",al={"varför skapa wildmane totem","wildmane totem syfte"}},{q="Varför behövs just alfavargtänder?",a="För att rena den djupa föroreningen i Wildmane Well måste man kanalisera ett topprovdjurs vilda, obevekliga styrka. Tänderna från flockens ledare ger den nödvändiga ursprungskraften.",al={"varför vargtänder","syftet med alfavargtänder"}},{q="Var finns alfavargar på prärien i Mulgore?",a="Alfavargar på prärien strövar på de norra slätterna i Mulgore. De håller ofta till på gräsmarkerna kring foten av Thunder Bluff.",al={"alfavarg på prärien plats","var hittar man alfavargar på prärien"}},{q="Vem skapar totemet?",a="Mull Thunderhorn, en andlig äldste som håller till i Bloodhoof Village, skapar varje renande totem efter att en novis har samlat in de nödvändiga offergåvorna.",al={"vem skapar totemet","totem uppdragsgivare"}},{q="Vad händer när Wildmane Totem har skapats?",a="När Mull Thunderhorn har satt ihop totemet av alfavargtänder skickas du norrut med det för att utföra själva reningen vid Wildmane Well.",al={"what comes next","nästa uppdrag efter wildmane totem"}},{q="Hur speglar ritualen taurenfolkets tro?",a="Taurenfolket ser det som ett högtidligt utbyte med naturen att ta ett djurs liv. Mull erkänner vargarnas offer med både sorg över deras död och stolthet över deras roll i att hela jorden.",al={"taurenfolkets totemfilosofi","mull thunderhorns tro"}}},fx={["054e923c"]={q="Varför vill Mull Thunderhorn att Wildmane Totem tillverkas?",a="Bara en förorenad vattenkälla återstår att rena i Mulgore, den som tillhör Wildmane-klanen. Mull Thunderhorn har vigt sig åt att rena jordens heliga källor, och att tillverka den sista reningstotemen med hjälp av landets rovdjursande är nödvändigt för att fullborda den heliga riten och återställa rent vatten åt stammen.",al={"varför vill mull ha wildmane totem","mull thunderhorns motiv","varför tillverka wildmane totem"}},["2aa23a29"]={q="Vad används Prairie Alpha Tooth till?",a="Prärievargalphans tänder står för offer och den vilda livskraften hos Mulgore-slätternas främsta rovdjur. Mull Thunderhorn binder åtta av dessa huggtänder i Wildmane Totem, så att dess ande kan blidka naturens ordning och stärka ritualen som krävs för att rena vattnet i Wildmane Water Well.",al={"vad prairie alpha tooth används till","vad prärievargalphans tänder används till","tänder till wildmane totem"}},eb5f4bd0={q="Varför jagar du prärievargalfor?",a="Du ska jaga prärievargalfor, de dominerande flockledarna som strövar på slätterna runt foten av Thunder Bluff. Deras styrka och vildhet förkroppsligar slätternas naturliga balans och ger Mull Thunderhorn den kraftfulla essens han behöver för den sista vattenreningsritualen.",al={"varför döda prärievargalfor","mål: prärievargalfa","vem ska du jaga"}}},fp="14,153,14.306.0,23.274.0,21.212.0,38.121.0,55.138.0,47.114.0,21.125.0,48.106.0,44.146.0"}
P.entries["quest:76"] = {n="The Jasperlode Mine",s="Kobolder har tagit över Jasperlode Mine i östra Elwynn. Marshal Dughan skickar ut spejare för att ta reda på hur långt angreppet har spridit sig.",h="Kobolder har tagit över Jasperlode Mine i östra Elwynn.",kw={"azora","dughan","elwynn","fargodeep","goldshire","jasperlode","kobold","gruva","spejare"},ang={["faction:Alliance"]="Som medlem av Alliansen ser du hur sårbara Stormwinds hemtrakter har blivit utan centralt kungligt stöd, nu när både Fargodeep och Jasperlode har gått förlorade.",["profession:Mining"]="Som gruvarbetare ser du värdefulla fyndigheter i Jasperlodes tunnlar, men kobolder som tagit området står mellan dig och malmen.",["race:Human"]="Som människa ser du hur Elwynns landsbygdsinfrastruktur sviktar när gränsområdenas resurser försvinner nära huvudstaden."},sec={{t="Ett andra intrång",b="Efter att kobolder svärmade in i Fargodeep-tunnlarna söder om Goldshire befarade Marshal Dughan att de nått andra gruvor. Jasperlode ligger i de klippiga utlöparna nordost om Tower of Azora och förser kungariket med råsten och metall. Dughan kan inte avvara Stormwinds vakter från patrullerna i staden, så han skickar självständiga äventyrare österut för att undersöka om kobolderna även tagit den här gruvan."},{t="Överansträngt försvar",b="Spejare som når Jasperlodes kamrar upptäcker att kobolder har drivit bort de mänskliga gruvarbetarna och befäst de mörka gångarna. Marshal Dughan drabbas av ännu ett bakslag medan krisen växer. Kung Varian Wrynn är försvunnen, och kungliga trupper hålls borta från avlägsna områden. Den lokala garnisonen har för få soldater för att rensa gruvorna, vilket gör att kungarikets hjärta får brist på mineraler och omringas av hot."}},faq={{q="Var ligger Jasperlode Mine?",a="Jasperlode Mine ligger i de norra utlöparna i östra Elwynn Forest. Färdas österut från Goldshire längs huvudvägen, passera Tower of Azora och fortsätt sedan norrut upp i kullarna.",al={"var ligger jasperlode","jasperlode mines läge","hitta jasperlode"}},{q="Varför behöver Marshal Dughan en spejare i stället för att skicka vakter?",a="Marshal Dughan har för få vakter att avvara. Kung Varian Wrynn är försvunnen, och det politiska dödläget i huvudstaden har gjort att de lokala styrkorna är hårt ansträngda när de skyddar gårdar och städer mot banditer och gnoller. Därför förlitar sig Dughan på civila spejare.",al={"varför skicka äventyrare","varför inga vakter från stormwind","var är vakterna"}},{q="Varför tar kobolder över Elwynns gruvor?",a="Kobolder gräver tunnlar mot mineralådror och fuktiga grottor. När Stormwinds militära närvaro minskade blev de djärvare och trängde in i mänskliga gruvor som Fargodeep och Jasperlode för att lägga beslag på guld, malm och territorium.",al={"varför kobolder i jasperlode","vad vill kobolderna ha","orsak till koboldangreppet"}},{q="Vad händer efter att man har spejat i Jasperlode Mine?",a="När du rapporterar att Jasperlode har fallit står Marshal Dughan inför förlusten av gruvor i öster och hot från flera håll. Han riktar uppmärksamheten mot västra Elwynn, där Riverpaw-gnoller sätter Westbrook Garrison under hård press.",al={"vad händer efter jasperlode","uppföljning efter jasperlode"}},{q="Varför är förlusten av Jasperlode Mine betydelsefull för Stormwind?",a="Elwynns gruvor förser Stormwind med malmen och stenen som staden behöver för sin ekonomi och för att smida vapen och rustningar. Förlusten av Fargodeep och Jasperlode stoppar mineralutvinningen och försvagar kungarikets återhämtning.",al={"varför jasperlode är viktigt","jasperlodes betydelse"}},{q="Vem äger Tower of Azora i närheten?",a="Tower of Azora är ett litet magikertorn längs den östra vägen genom Elwynn Forest. Theocritus, Azoras ärkemagiker, råder där, och Azoras tjänare sköter tornet. Resenärer använder det som landmärke på vägen till de östra utlöparna.",al={"vad är tower of azora","vem bor i azoras torn"}}},fx={a973508b={q="Varför vill Marshal Dughan att Jasperlode Mine undersöks?",a="Marshal Dughan har redan bekräftat att kobolder har tagit över Fargodeep Mine och fruktar att angreppet inte är en isolerad händelse. Han behöver veta om hotet också har spridit sig österut till Jasperlode Mine. Att säkra Elwynns resurser och förstå hela omfattningen av det växande hotet är avgörande för att försvara Goldshire och skydda Stormwinds viktiga handelsvägar.",al={"dughans motiv för jasperlode","varför undersöka jasperlode","varför behöver dughan få jasperlode undersökt"}}},fp="19,146,18.366.0,21.386.0,37.177.0,63.237.0,43.203.0,48.235.0,60.196.0,35.231.0"}
P.entries["quest:760"] = {n="Wildmane Cleansing",s="Wildmane Cleansing markerar höjdpunkten i taurenfolkets ritualer för att rena Mulgore livsviktiga vattenhål. På uppdrag av Mull Thunderhorn i Bloodhoof Village tar hjältar den färdiga Wildmane Cleansing Totem norrut för att rena den sista förgiftade brunnen. När de driver tillbaka goblinernas föroreningar återställs balansen på slätterna och taurenstammarnas pastorala försörjning tryggas.",h="Wildmane Cleansing markerar höjdpunkten i taurenfolkets ritualer för att rena Mulgore livsviktiga vattenhål.",kw={"bloodhoof village","rening","jordmodern","mulgore","mull thunderhorn","totem","venture company","vattenbrunn","wildmane"},ang={["class:Druid"]="Att återställa naturen efter goblinernas miljöförstörelse speglar direkt Cenarionordens uppdrag att läka skadade ekosystem och skydda grönskande betesmarker.",["class:Shaman"]="Att använda rituella totemer för att motverka mekaniska föroreningar visar shamanens plikt att upprätthålla harmoni mellan naturens element och levande samhällen.",["race:Tauren"]="Att återställa Mulgore tre förfädersbrunnar är en grundläggande övergångsrit som bevisar en ung krigares hängivenhet till att bevara Jordmoderns gåvor."},sec={{t="Att rena Jordmoderns gåva",b="Vattnet är heligt livsblod över Mulgore solbelysta slätter och uppehåller hjordarna, jorden och de nomadiska stammar som nyligen samlats kring Thunder Bluff. När Venture Company och gobliner som trängde in i området började förorena dessa grundvattenkällor med giftigt industriavfall insåg taurenäldste att ett existentiellt hot hade uppstått. Efter reningen av Winterhoof Water Well och Thunderhorn Water Well återstår Wildmane Water Well som den tredje och sista förorenade platsen som kräver andlig hjälp."},{t="Wildmane Totem",b="Wildmane Cleansing Totem har tillverkats av särskilda beståndsdelar som samlats in i regionen och kanaliserar förfädernas andars och jordelementets återställande kraft. När totemen planteras intill det stinkande vattnet norr om Thunder Bluff skingras de giftiga kemikalierna, toxinerna drivs ut och det naturliga flödet återupplivas. Genom att fullborda ritualen skyddar tauren sitt folk från sjukdom och sänder ett tydligt budskap om att de inte tolererar skändningen av sin heliga mark."}},faq={{q="Varför förgiftades Wildmane Water Well?",a="Goblinernas verksamhet, driven av industriell girighet och skogsavverkning, förde in gift och kemiskt avfall i Mulgore underjordiska vatten och hotade både det lokala djurlivet och stammarnas bosättningar.",al={"vem förgiftade brunnen","varför är brunnen smutsig","goblingift"}},{q="Var ligger Wildmane Water Well?",a="Wildmane Water Well ligger på slätterna, rakt norr om Thunder Bluffs väldiga mesas.",al={"wildmane-brunnens plats","var ligger wildmane-brunnen","hitta wildmane-brunnen"}},{q="Vem inleder denna reningsritual?",a="Mull Thunderhorn, en äldste i Bloodhoof Village, vägleder dig när du skapar totemerna och skickar dig att rena brunnarna.",al={"vem ger uppdraget wildmane cleansing","uppdragsgivare","mull thunderhorns plats"}},{q="Vilka andra brunnar ingår i reningsarbetet?",a="Wildmane Water Well är den tredje av tre livsviktiga vattenkällor. Söderut ligger först Winterhoof Water Well och sedan Thunderhorn Water Well.",al={"andra brunnar","brunnar i mulgore","winterhoof- och thunderhorn-brunnarna"}},{q="Hur fungerar reningstotemen?",a="Totemen är fylld med förfädernas magi och renade naturämnen och kanaliserar återställande andlig energi ner i grundvattnet för att neutralisera goblinernas föroreningar.",al={"hur reningstotemen fungerar","hur renar totemen vattnet"}},{q="Vad innebär det för Bloodhoof Village att ritualen fullbordas?",a="När de tre brunnarna renas får alla stammar i centrala Mulgore garanterat säkert dricksvatten, och tauren hedrar sin heliga plikt att läka Jordmodern efter industriell exploatering.",al={"uppdragets resultat","varför rena brunnarna","taurenfolkets historia och betydelse"}}},fx={["119d5a48"]={q="Varför vill Mull Thunderhorn att Wildmane Well renas?",a="Mull Thunderhorn vakar över Mulgore och dess andliga balans och livsviktiga resurser. Venture Companys smutsiga verksamhet förgiftade landets värdefulla vattenkällor och hotar stammarnas och deras hjordars överlevnad. Wildmane Well är den sista av de tre uråldriga källorna som fortfarande är förorenad, och att rena den är avgörande för att hela Earth Mother och säkra dricksvatten åt Bloodhoof Village och Thunder Bluff.",al={"mull thunderhorns motiv","varför rena wildmane well","varför bryr sig mull om källorna"}},b4cee6a1={q="Vad är Wildmane Cleansing Totem?",a="Wildmane Cleansing Totem är ett rituellt förberett föremål som Mull Thunderhorn har tillverkat för att kanalisera förfädernas andar och jordandar. När det aktiveras vid den förorenade Wildmane Water Well norr om Thunder Bluff stöter totemen bort det giftiga slammet som goblinernas föroreningar lämnat efter sig. Då renas grundvattnet och källan återfår sitt naturliga, orörda tillstånd.",al={"använda wildmane cleansing totem","vad är wildmane totem","syftet med reningstotemen"}}},fp="18,219,33.421.0,18.420.0,41.180.0,41.92.0,36.115.0,54.145.0,34.155.0,60.169.0"}
P.entries["quest:761"] = {n="Swoop Hunting",s="Swoop Hunting är en jakttradition där spårning och skytte sätts på prov, och den erbjuds av Harken Windtotem i Bloodhoof Village. För att visa sin list och sitt tålamod utmanas jägare och resenärer att smyga sig på de skygga fåglarna över Mulgore. Att återvända med oskadade troféfjädrar visar både hängivenhet till jakten och respekt för Jordmoderns naturliga prövningar.",h="Swoop Hunting är en jakttradition där spårning och skytte sätts på prov, och den erbjuds av Harken Windtotem...",kw={"bloodhoof village","harken windtotem","mulgore","swoop-fågel","swoop-jakt","taurenprövning","trophy swoop quill"},ang={["class:Druid"]="När druider spårar swoop-fåglar över vindpinade platåer kommer de närmare rovfåglarna som upprätthåller balansen på Mulgore himmel.",["class:Hunter"]="Jakten ger en tidig mästarklass i att leda luftburet byte, bedöma beteendemönster och utföra precisa angrepp mot vaksamma rovdjur.",["race:Tauren"]="För unga tauren och vandrare är jakten på Mulgore snabba swoop-fåglar en vördad övergångsrit som vässar spårningsinstinkterna och upprätthåller förfädernas jakttraditioner."},sec={{t="Ett prov för skarpa ögon",b="Mulgore grässtäpper myllrar av bestar, men få prövar en förföljares instinkter som de inhemska swoop-fåglarna. Dessa stora rovfåglar smälter sömlöst in mot himlen och slätterna, kretsar ovanför eller flyger lågt över det höga gräset. Till skillnad från långsamma plainstriders eller betande kodo kräver swoop-fåglar skärpt fokus och snabba fötter för att hinnas ikapp. Därför är jakten en traditionell prövning för unga jägare som vill vinna anseende bland stammarna."},{t="Jaktens kännetecken",b="För Harken Windtotem handlar insamlingen av troféfjädrar mindre om att gallra bland vilda djur och mer om att odla disciplin. I taurenkulturen visar troféer från en svår jakt list och uthållighet. När äventyraren överlämnar de oskadade fjädrarna till de äldre i Bloodhoof Village visar det att hen kan försörja och försvara samhället, och att hovarna är snabba och sinnena skarpa nog att bemästra den större världen."}},faq={{q="Varför ber Harken Windtotem dig jaga swoop-fåglar?",a="Harken Windtotem ger jägare i uppdrag att spåra swoop-fåglar genom Mulgore för att pröva deras list, snabbhet och hängivenhet. Oskadade troféfjädrar är ett erkänt bevis på jägarens skicklighet och ger ära bland tauren i Bloodhoof Village.",al={"varför jaga swoop-fåglar","syftet med harken windtotems uppdrag","syftet med swoop-jakten"}},{q="Var brukar man stöta på swoop-fåglar?",a="Swoop-fåglar finns utspridda över Mulgore öppna slätter. De svävar ovanför prärierna eller spanar efter byte i gräset utanför bosättningar som Bloodhoof Village.",al={"var finns swoop-fåglar","swoop-fåglarnas platser i mulgore","hitta swoop-fåglar"}},{q="Varför är swoop-fåglar svåra att jaga?",a="Till skillnad från flockdjur som rör sig tillsammans över slätterna är swoop-fåglar snabba och vaksamma rovfåglar som håller sig utspridda och observanta. För att smyga sig på dem krävs skarp syn för att upptäcka deras flyktvägar och snabba steg för att fälla dem innan de kommer undan.",al={"varför är swoop-fåglar svåra att fånga","swoop-fåglars beteende"}},{q="Vad betyder troféfjädrarna för tauren?",a="I taurenfolkets traditioner står troféfjädrar från swoop-fåglar för tålamod, skarp syn och en lyckad jakt. Att visa upp dem betyder att jägaren har de instinkter som krävs för att försörja och skydda stammen.",al={"vad troféfjädrar från swoop betyder","fjädrarnas betydelse"}},{q="Vem är Harken Windtotem?",a="Harken Windtotem är en respekterad tauren från Bloodhoof Village som håller uppsikt över nykomlingar och blivande jägare. Hen bedömer deras påhittighet genom traditionella prövningar på slätterna.",al={"vem ger uppdraget swoop hunting","harken windtotems bakgrund"}},{q="Påverkar jakten naturens balans i Mulgore?",a="Taurenfolket ser jakt som en helig dialog med Jordmodern, inte som urskillningslöst dödande. Att samla fjädrar är ett måttfullt disciplinprov som hedrar bytesdjurets list och bevarar stammens balans.",al={"är swoop-jakt överjakt","swoop-fåglarnas balans i mulgore"}}},fx={["0d785fcd"]={q="Varför skickar Harken Windtotem en utomstående för att jaga swoops i stället för att jaga dem själv?",a="Harken Windtotem skickar dig inte för att han själv inte kan jaga, utan för att pröva ditt värde. För tauren kräver det skarp syn, tålamod och snabba hovar att spåra den listiga swoopen över slätterna. När Harken ber dig ta med deras fjädrar tillbaka får du chansen att visa Bloodhoof Village din skicklighet och beslutsamhet och bevisa att du är en jägare av verklig förmåga.",al={"varför skickas jag att jaga swoops","varför behöver harken mig","varför kan harken inte jaga swoops"}}},fp="13,157,19.324.0,18.345.0,59.197.0,39.126.0,41.144.0,48.147.0,24.179.0,55.185.0"}
P.entries["quest:76156"] = {n="Stalk With The Earthmother",s="Boarton Shadetotem ser en talang för diskretion hos dig och ber dig gå in i Venture Companys gruva. Han vill att du tar Seaforium Mining Charges från gruvans förrådsvagnar.",h="Boarton Shadetotem ser en talang för diskretion hos dig och ber dig gå in i Venture Companys gruva.",kw={"sprängmateriel","boarton shadetotem","mask","gruva","seaforium mining charges","diskretion","thunder bluff","venture company"},ang={["class:Rogue"]="Boarton tror att du som rogue har en talang för diskretion och ber dig gå in i Venture Companys gruva."},sec={{t="Ett diskret tillvägagångssätt",b="Boarton Shadetotem i Thunder Bluff tror att du kan gå diskret till väga. Han ger dig en mask och ber dig gå in i Venture Companys närbelägna gruva. Där ska du ta Seaforium Mining Charges från vagnar med sprängmateriel och ta med dem tillbaka till honom."}},faq={{q="Vem ber mig gå in i gruvan?",a="Boarton Shadetotem i Thunder Bluff ber dig gå in i Venture Companys gruva.",al={"vem är boarton","boarton shadetotem","vem gav detta"}},{q="Vad letar jag efter i gruvan?",a="Du ombeds ta Seaforium Mining Charges från vagnar med sprängmateriel.",al={"vad ska stjälas","gruvförråd","seaforium-laddningar"}},{q="Varför ger Boarton mig en mask?",a="Boarton ger dig en mask för att gå in i Venture Companys närbelägna gruva.",al={"mask förklädnad","varför masken","infiltrera gruvan"}},{q="Var ligger Venture Companys gruva?",a="Gruvan ligger sydost om Thunder Bluff.",al={"gruvans läge","var ligger gruvan","venture companys gruva"}},{q="Vem tas materielen från?",a="Materielen finns i Venture Companys gruva.",al={"vem äger materielen","venture companys materiel","bolagets gruva"}}},fp="26,172,17.257.0,30.79.0,34.79.0,32.70.0,34.39.0,32.45.0"}
P.entries["quest:76160"] = {n="Stalk With The Earthmother",s="Boarton Shadetotem ber dig göra en salva av Windfury Cones som finns norr om Thunder Bluff. Han hoppas att den ska få sår från en klinga att bränna med bitter kraft.",h="Boarton Shadetotem ber dig göra en salva av Windfury Cones som finns norr om Thunder Bluff.",kw={"boarton shadetotem","harpyor","mortel och mortelstöt","salva","stalk with the earthmother","thunder bluff","windfury cones"},sec={{t="En bitter salva",b="Boarton Shadetotem i Thunder Bluff vill ha en giftig salva, gjord av kottar som samlas nära harpyornas bon i norr. Du ska krossa Windfury Cones i en mortel med en mortelstöt och sedan ge honom resultatet. Han varnar för att den färdiga salvan kan göra ont även på huden."}},faq={{q="Vem ber om salvan?",a="Boarton Shadetotem i Thunder Bluff ber dig tillreda en salva av Windfury Cones.",al={"vem vill ha salvan","boarton shadetotems begäran"}},{q="Var växer Windfury Cones?",a="Harpyorna norr om Thunder Bluff bygger sina bon i ett träd som producerar det giftiga hartset. Nedfallna kottar ligger runt deras bon.",al={"var finns kottar","var finns windfury cone"}},{q="Vad är salvan tänkt att göra?",a="När salvan stryks på en klinga ska den få en motståndares sår att bränna och förvandla blodet till salt.",al={"vad gör salvan","giftig salva för klingor"}},{q="Varför varnar Boarton för att röra vid den?",a="Boarton säger att även hudkontakt med den färdiga salvan kan göra ont.",al={"varning för salva på huden","är salvan farlig"}}},fp="26,156,14.271.0,28.84.0,33.117.0,30.102.0,40.72.0"}
P.entries["quest:762"] = {n="An Ambassador of Evil",s="Historian Karnik vill att Ambassador Infernus från Angor Fortress röjs ur vägen. Du ska återvända till Badlands och ta med bevis på att du dödat honom till Advisor Belgrum i Ironforge.",h="Historian Karnik vill att Ambassador Infernus från Angor Fortress röjs ur vägen.",kw={"advisor belgrum","ambassador infernus","angor fortress","badlands","historian karnik","ironforge","ragnaros","shadowforge","uldaman"},sec={{t="Ambassadören i Angor Fortress",b="Ragnaros själv skickade Ambassador Infernus till Angor Fortress för att övervaka Shadowforge medan de söker efter förlorade artefakter i Uldaman. Många dvärgar har redan mist livet, och dödstalet stiger. Karnik vågar inte gissa hur många artefakter Shadowforge kan hitta och använda mot Ironforge. Du ska återvända till Badlands, döda Infernus och ta med bevis på segern till Belgrum. Tiden är knapp, eftersom Ragnaros inte väntar på att de ska förbereda sig."},{t="Belgrums tack",b="Belgrum berömmer din hängivenhet till Ironforge och dvärgafolket och skickar bud till Karnik om din framgång. Hjälp kommer också att skickas till Badlands för att återta utgrävningsplatsen. Belgrum har ytterligare en sak att be dig om, i kung Bronzebeards namn."}},faq={{q="Vem är Ambassador Infernus?",a="Ragnaros själv skickade Infernus till Angor Fortress för att övervaka Shadowforge medan de söker efter förlorade artefakter i Uldaman.",al={"vem är infernus","infernus bakgrund","ambassador infernus bakgrund"}},{q="Var finns Ambassador Infernus?",a="I Angor Fortress, i Badlands.",al={"var hittar man ambassador infernus","ambassador infernus plats","var är infernus"}},{q="Varför vill Karnik att Ambassador Infernus dödas?",a="Shadowforges sökande i Uldaman har redan kostat många dvärgar livet, och Karnik fruktar att artefakterna de hittar kan användas mot Ironforge.",al={"varför döda ambassador infernus","vad gör infernus i uldaman","hot mot ironforge i badlands"}},{q="Vem ger och avslutar det här uppdraget?",a="Historian Karnik i Ironforge ger uppdraget, och du lämnar bevis på segern till Advisor Belgrum i Ironforge.",al={"vem startar an ambassador of evil","vem lämnar in an ambassador of evil","uppdragsgivare för an ambassador of evil"}},{q="Vilket bevis behövs?",a="Ambassador Infernus' Bracer, som du visar Advisor Belgrum som bevis på din seger.",al={"vad behöver jag från infernus","bevis på ambassador infernus","infernus armband"}}},fp="21,143,32.427.0,16.241.1,27.105.0,29.58.0,51.142.0,30.115.0,21.75.0"}
P.entries["quest:76240"] = {n="Stalk With The Earthmother",s="Boarton Shadetotem ber dig att filéa en Raw Brilliant Smallfish i Thunder Bluff. Han hoppas att övningen ska avslöja en fallenhet för subtila konster.",h="Boarton Shadetotem ber dig att filéa en Raw Brilliant Smallfish i Thunder Bluff.",kw={"boarton shadetotem","knife set","raw brilliant smallfish","stalk with the earthmother","subtila konster","thunder bluff"},sec={{t="Ett sista prov",b="Boarton Shadetotem i Thunder Bluff ber dig att visa vad som faller sig naturligt med hans Knife Set. Ta med en Raw Brilliant Smallfish till honom och filéa den inför honom. Han hoppas att detta mindre direkta prov ska avslöja en dold talang."},{t="Avskedsord",b="Boarton Shadetotem ser att du saknar den skurkaktiga precision han sökte. Han ger dig en avskedsgåva och låter dig resa vidare, med en önskan om att Horde får hjältar som du."}},faq={{q="Vem ber mig att filéa en fisk?",a="Boarton Shadetotem i Thunder Bluff ber dig att filéa en Raw Brilliant Smallfish med hans Knife Set.",al={"vem är boarton","boarton shadetotem","fisk kniv uppdrag"}},{q="Varför vill Boarton att jag ska filéa en fisk?",a="Boarton hoppas att övningen ska locka fram en dold fallenhet för subtila konster.",al={"varför filéa fisk","vad testar boarton","småfiskprov"}},{q="Vilken fisk ber Boarton om?",a="Boarton ber om en Raw Brilliant Smallfish.",al={"vilken fisk","rå småfisk","lysande fisk"}},{q="Var ska jag filéa fisken?",a="Filéa en Raw Brilliant Smallfish framför Boarton Shadetotem i Thunder Bluff.",al={"var finns fiskuppdraget","thunder bluff fisk","var används knife set"}}},fp="26,141,13.214.0,13.162.1,34.100.0,42.74.0,31.43.0,27.83.0"}
P.entries["quest:763"] = {n="Rites of the Earthmother",s="Rites of the Earthmother markerar en ung taurenkrigares övergång från avskilda Red Cloud Mesa till Mulgore slätter. Efter att du visat vad du går för i Camp Narache skickar Chief Hawkwind dig norrut till Bloodhoof Village med en snidad totem, för att fortsätta de uråldriga prövningarna under Baine Bloodhoof.",h="Rites of the Earthmother markerar en ung taurenkrigares övergång från avskilda Red Cloud Mesa till Mulgore...",kw={"baine bloodhoof","bloodhoof village","cairne bloodhoof","camp narache","chief hawkwind","mulgore","rites of the earthmother","totem of hawkwind"},ang={["faction:Horde"]="De traditionella riterna stärker stammarnas gemenskap i hela Mulgore och ser till att Hordens nya försvarare besitter både krigarkraft och djup andlig förankring.",["race:Tauren"]="Varje ung tauren måste vandra Earthmothers väg för att bevisa sitt värde för de äldste och finna sin plats bland de förenade stammarna."},sec={{t="Lämna mesan",b="I generationer har unga tauren testat sin styrka i Camp Naraches trygga famn på Red Cloud Mesa. De inledande prövningarna visar att man har disciplin och beslutsamhet nog att överleva, men Earthmothers heliga riter kräver långt mer än att överleva bland traktens vilda djur. Chief Hawkwind märker när en novis har vuxit ur mesans skyddade jaktmarker och måste ta steget in i den större gemenskapen."},{t="En gåva till Baine",b="För att underlätta färden mellan Narache och de centrala bosättningarna ger Chief Hawkwind dig en handskuren totem som introduktion. Med emblemet i handen följer du den slingrande stigen till Bloodhoof Village och presenterar dig för Baine Bloodhoof, byns unge hövding och son till överhövding Cairne Bloodhoof. Totemen visar att du är redo för de kommande andliga och visdomsprövningarna."}},faq={{q="Vad är syftet med det här uppdraget?",a="Det är en övergångsrit som leder dig ut ur startområdet Camp Narache och vidare mot Bloodhoof Village, där du får möta nästa del av taurenfolkets ceremoniella prövningar.",al={"varför rites of the earthmother","vad gör uppdraget","syftet med uppdraget"}},{q="Vem är Baine Bloodhoof?",a="Baine Bloodhoof är son till överhövding Cairne Bloodhoof. Han leder Bloodhoof Village och är en respekterad lokal hövding som övervakar de pågående andliga och stridsmässiga prövningarna för unga tauren.",al={"vem är baine","baine bakgrund","cairnes son"}},{q="Vad är Totem of Hawkwind?",a="Det är en trätem som Chief Hawkwind i Camp Narache har snidat för hand. Den fungerar som en officiell legitimation och ett godkännande, som visar Baine Bloodhoof att du har förtjänat Hawkwinds välsignelse att genomgå fler riter.",al={"totem of hawkwind","hawkwinds totem","snidad totem"}},{q="Vilka riter följer efter detta?",a="När du kommer till Bloodhoof Village och träffar Baine får du uppdraget Rite of Vision, som prövar din andliga samhörighet genom heliga syner från förfäderna.",al={"nästa riter","vad kommer efter","nästa uppdrag"}},{q="Var ligger Bloodhoof Village?",a="Bloodhoof Village ligger norr om Camp Narache, vid Stonebull Lakes strand i centrala Mulgore. Följ bara huvudvägen ner från mesan och fortsätt norrut.",al={"var ligger bloodhoof village","hur hittar man bloodhoof village","vägen till bloodhoof"}},{q="Varför måste Earthmothers riter genomföras?",a="Rites of the Earthmother är djupt heliga traditioner bland tauren. Den som klarar alla riter visar fysisk uthållighet, andlig samhörighet och visdom, och vinner därmed erkännande från Thunder Bluffs äldste.",al={"varför earthmothers riter","syftet med taurenfolkets prövningar","rites of the earthmother bakgrund"}}},fx={["4a33bb81"]={q="Varför skickar Chief Hawkwind dig till Bloodhoof Village?",a="Chief Hawkwind har väglett dig genom de inledande prövningarna på Red Cloud Mesa, men Camp Narache har inget mer att lära dig. För att fullborda Earthmothers heliga riter och vinna Thunder Bluffs äldstes acceptans måste du skaffa dig mer erfarenhet på Mulgore slätter. Genom att skicka dig till Baine Bloodhoof med sitt snidade totem överlåter Hawkwind ansvaret för din andliga och fysiska utveckling åt en ledare som kan pröva om du är redo för verkligt vuxenliv.",al={"varför skickas jag till bloodhoof","chief hawkwinds motiv","varför earthmothers riter"}},["9c980781"]={q="Varför måste du själv överlämna totemen?",a="Resan är inte ett enkelt kuriruppdrag, utan en viktig del av din övergångsrit. När du lämnar Red Cloud Mesas skyddade område och följer den öppna vägen in i Mulgore visar du din självständighet och uthållighet. Genom att själv lämna över Totem of Hawkwind kan Baine Bloodhoof se dig, känna igen Hawkwinds personliga rekommendation som är inristad i träet och bedöma din karaktär på nära håll.",al={"varför ska jag ta med totemen","varför kan hawkwind inte skicka en budbärare","varför jag ska genomgå earthmothers riter"}}},fp="24,202,16.337.0,17.388.0,34.120.0,23.170.0,30.223.0,27.128.0,35.156.0,44.193.0"}
P.entries["quest:764"] = {n="The Venture Co.",s="Undersökningen av en skövlad Venture Company-karavan i Mulgore avslöjar att allt fler aggressiva Venture Company-goblins gräver sig in i de östra kullarna. Efter att deras formella ansökningar om gruvtillstånd avslagits blankt valde företaget ändå att bryta i Jordemoderns jord, vilket fick Morin Cloudstalker att beställa ett dödligt svar.",h="Undersökningen av en skövlad Venture Company-karavan i Mulgore avslöjar att allt fler aggressiva Venture...",kw={"goblin","gruvrättigheter","morin cloudstalker","mulgore","ravaged caravan","venture co","venture co-gruvan","venture company"},ang={["faction:Horde"]="När du försvarar Mulgore mot kommersiell exploatering visar du din hängivenhet till att skydda Cairne Bloodhoofs folk medan de arbetar för att trygga sitt nya hemland.",["profession:Mining"]="Venture Company ägnar sig enbart åt hänsynslös utvinning och tar genvägar som destabiliserar landet, utan hänsyn till den naturliga balansen eller säker gruvdrift.",["race:Tauren"]="För tauren är Jordemodern helig. Venture Companys dagbrottsbrytning är inte bara ett intrång, utan en våldsam skändning av deras förfäders hem som kräver att de omedelbart drivs bort med våld."},sec={{t="Industriellt intrång",b="Tauren i Mulgore vördar landet som en förlängning av Jordemodern och värnar dess orörda slätter och balanserade djurliv. När Venture Company vände sig till stammarna för att få rätt att spränga och gräva ut de böljande kullarna efter råmalm avslogs deras ansökningar kategoriskt. Oavskräckt av stammarnas påbud och territoriella självbestämmande smög det hänsynslösa kartellen in tunga maskiner, arbetare och förmän direkt i Mulgore östra bergsryggar för att bedriva olaglig gruvdrift."},{t="Ett otvetydigt budskap",b="Tauren-spejare som Morin Cloudstalker inser att företagens girighet inte går att resonera med genom diplomatiska vädjanden när hackorna väl träffar stenen. Dokument som återfunnits i en skövlad Venture Co.-karavan bekräftar företagets gruvdrift, och Morin skickar därför Horde-mästare för att slå ner både slavdrivarna som viner med piskorna och arbetarna som driver borrarna. Den blodiga vedergällningen ska få Venture Company att inse att priset för intrång är alldeles för högt."}},faq={{q="Varför är Venture Company i Mulgore?",a="Venture Company upprättade en olaglig utpost och gruva längs Mulgore östra kullar för att utvinna mineraler och naturresurser. Efter att tauren formellt nekat dem gruvrättigheter struntade kartellen i stammarnas auktoritet och satte ändå upp sin verksamhet.",al={"varför finns gobliner i mulgore","venture co:s motiv i mulgore","vad vill venture co ha"}},{q="Vem beordrade attacken mot gruvarbetarna?",a="Morin Cloudstalker, en tauren som håller vakt nära Bloodhoof Village, ger ordern. Han ser kartellens vägran att godta stammarnas avslag som ett direkt övertramp som kräver våld, inte fler samtal.",al={"vem ger uppdraget","morin cloudstalkers roll","uppdragsgivare"}},{q="Var ligger Venture Company-gruvan?",a="Venture Companys huvudgruva ligger i bergsfoten öster om Ravaged Caravan och Bloodhoof Village. En mindre grupp företagsanställda kan också påträffas vid en utpost gömd bland klipporna nordost om Thunder Bluffs norra hissar.",al={"venture co-gruvans plats","var finns förmännen","var hittar man venture co"}},{q="Försökte tauren någonsin förhandla med goblinerna?",a="Ja. Venture Company ansökte formellt hos tauren om gruvrättigheter i Mulgore. Stamledarna vägrade låta dem dagbrottsbryta sina förfäders marker, men goblinerna valde helt enkelt att gräva utan tillstånd ändå.",al={"gav tauren tillstånd till gruvdrift","gruvrättigheter i mulgore","bad goblinerna om tillstånd"}},{q="Tillhör de här goblinerna Steamwheedle Cartel?",a="Nej. Venture Company är en oberoende, beryktat rovlysten industrikartell som skiljer sig från neutrala handelsgrupper som Steamwheedle Cartel. De har fientliga relationer med lokalbefolkningen överallt där de utvinner resurser.",al={"är det här ratchet-gobliner","är venture co vänligt","venture company-fraktionen"}},{q="Hur hänger detta ihop med de skövlade karavanerna?",a="Den skövlade karavanen var en Venture Company-konvoj som tauren förstörde. Gruvavdelningens lådor och dokument som återfanns bland vrakresterna avslöjade företagets verksamhet i Mulgore och ledde till anfallet mot deras gruva.",al={"kopplingen till karavanen","attackerade venture co karavaner","kopplingen till den skövlade karavanen"}}},fx={f6df914e={q="Varför vill Morin Cloudstalker att Venture Co. angrips?",a="Venture Company nekades officiellt gruvrättigheter i Mulgore, men ignorerade avslaget och började ändå samla utrustning och arbetare. Morin Cloudstalker kan inte låta dem förstöra landet och plundra dess naturtillgångar ostraffat. Eftersom diplomati och tydliga avslag inte har hejdat deras girighet anser han att tauren måste ge dem ett omisskännligt och kraftfullt budskap: intrång och stöld tolereras inte.",al={"morin cloudstalkers motiv","varför attackera venture co.","varför vill morin döda venture co."}},eda5096c={q="Vilka skickas du att strida mot vid gruvan?",a="Du skickas mot Venture Co. Supervisors och Workers som är stationerade vid deras gruvdrift i östra Mulgore. Dessa gobliner och inhyrda arbetare gräver djupt i de heliga kullarna för att utvinna mineraler utan stammens tillstånd. De leds av vinstdrivna förmän som driver företagets aggressiva och olagliga expansion.",al={"målen i venture co.-uppdraget","vilka är arbetarna i venture co.","vem ska jag slåss mot i gruvan"}}},fp="15,191,20.326.0,23.321.0,38.172.0,40.172.0,42.216.0,54.193.0,50.216.0,46.195.0"}
P.entries["quest:765"] = {n="Supervisor Fizsprocket",s="Supervisor Fizsprocket är en högt uppsatt tillsyningsman för Venture Company, stationerad i gruvgångarna i Mulgore. På uppdrag av Morin Cloudstalker går hordeäventyrare in i gruvan för att sätta stopp för goblinernas planerade plundring, döda honom och återta hans detaljerade skrivplatta.",h="Supervisor Fizsprocket är en högt uppsatt tillsyningsman för Venture Company, stationerad i gruvgångarna i...",kw={"skrivplatta","fizsprocket","gruva","morin cloudstalker","mulgore","tillsyningsman","venture company"},ang={["faction:Horde"]="Genom att hjälpa tauren mot företagets framryckande plundrare stärker du hordens skydd av de nyligen erövrade kärnområdena i Kalimdor.",["race:Tauren"]="Venture Companys öppna plan att fördriva din stam och plundra den heliga jorden gör dödandet av Fizsprocket till en nödvändig handling för att försvara ert område."},sec={{t="En plan mot slätterna",b="Dokument som återfanns i en förstörd karavan från Venture Company visade att företaget inte bara grävde efter malm – de utarbetade medvetet planer för att driva bort tauren från Mulgore för gott. Genom att fördriva lokalbefolkningen ville det glupska företaget få fria händer att tömma de böljande kullarna och djupa underjordiska ådrorna på alla naturresurser."},{t="Slå till mot förmannen",b="Morin Cloudstalker, rasande över företagets övergrepp som planerats mot hans folk, skickar hjältar till Venture Company-gruvan strax öster om de skövlade handelsvagnarna. Supervisor Fizsprocket leder verksamheten långt inne i de högra gångarna, omgiven av arbetare och underordnade chefer. När Fizsprocket fälls och hans skrivplatta tas i beslag slås den lokala samordningen sönder, och viktig information om företagets framtida planer kommer fram."}},faq={{q="Vem är Supervisor Fizsprocket?",a="Supervisor Fizsprocket är en chef för Venture Company som leder arbetet i gruvgångarna i östra Mulgore. Han övervakar arbetsstyrkan som gräver i jorden och genomför företagets strategier för att utöka verksamheten i regionen.",al={"fizsprocket","vem är fizsprocket","fizsprockets bakgrund"}},{q="Varför vill Morin Cloudstalker att Fizsprocket ska dö?",a="Morin hittade dokument i en plundrad karavan som bevisade att Venture Company planerade att driva bort tauren från deras förfäders land för vinnings skull. Fizsprocket är den direkte tillsyningsmannen som genomför dessa beräknande utsugningsplaner.",al={"varför döda fizsprocket","morin cloudstalkers motiv"}},{q="Var finns Supervisor Fizsprocket?",a="Han finns inne i Venture Company-gruvan, rakt öster om Ravaged Caravan i Mulgore. Följ den bortre högra gången inne i gruvan till en kammare där han står omgiven av arbetare och tillsyningsmän.",al={"var finns fizsprocket","fizsprockets gruva","fizsprockets karta"}},{q="Vilket bevis på Fizsprockets nederlag kräver Morin?",a="Morin Cloudstalker kräver Fizsprockets personliga skrivplatta, som innehåller räkenskaper och anteckningar som kan avslöja ytterligare planer från Venture Company i Mulgore.",al={"dödsbevis","fizsprockets skrivplatta"}},{q="Varför är Venture Company i Mulgore?",a="Venture Company är ett skrupelfritt handelskartell som vill skövla orörd mark på timmer, mineraler och värdefulla rikedomar under jord, utan minsta hänsyn till ursprungsbefolkningen eller den ekologiska balansen.",al={"venture company i mulgore","varför är gobliner i mulgore"}},{q="Driver dödandet av Fizsprocket bort Venture Company helt?",a="Nej. Fizsprockets död stör deras lokala ledning och ger Morin Cloudstalker viktiga anteckningar om deras planer, men Venture Company förblir ett ihållande hot i kullarna i Mulgore.",al={"är venture company borta","efter fizsprockets död"}}},fp="22,216,25.239.0,21.285.1,30.187.0,50.189.0,40.158.0,54.129.0,38.156.0,67.165.0"}
P.entries["quest:766"] = {n="Mazzranache",s="Maur Raincaller i Bloodhoof Village har fallit offer för ett giftigt bett från Mazzranache, en legendarisk strider som terroriserade hans farfar en generation tidigare. Taurenen har drabbats av feber och deliriska mardrömmar och behöver ett kraftfullt läkemedel bryggt av Mulgore-vildmarkens djur innan infektionen tar hans liv.",h="Maur Raincaller i Bloodhoof Village har fallit offer för ett giftigt bett från Mazzranache, en legendarisk...",kw={"bloodhoof village","flatland cougar","maur raincaller","mazzranache","mulgore","plainstrider","prairie wolf","swoop"},ang={["class:Hunter"]="När du spårar prärievargar, pumor, striders och swoops genom Mulgore får du praktisk övning i att läsa slätten och förstå savannens olika djur.",["faction:Horde"]="Att trygga Bloodhoof Village mot Mulgore-vildmarkens hårda faror är avgörande för att skapa fred och stabilitet i taurenfolkets hemland.",["race:Tauren"]="Läkemedlet som Maur brygger återspeglar taurenfolkets urgamla sed att hämta botemedel direkt från Jordemoderns flora och fauna."},sec={{t="En slättens sägen",b="I åratal betraktade Maur Raincaller Mazzranache som föga mer än en skrämmande familjesägen som hans farfar hade fört vidare. Den äldre taurenen berättade om en ovanligt vildsint strider med glödande röda ögon, rakbladsvassa klor och ett giftigt bett som trotsade det fredliga sinnelaget hos de flesta djuren i Mulgore. När Maur stötte på besten ute på den öppna grässlätten visade sig sägnen vara alltför verklig. Han blev svårt sårad och kämpade för att ta sig tillbaka i säkerhet."},{t="En kamp mot infektionen",b="Varelsens gift verkar snabbt och orsakar hög feber och mardrömslikt delirium. För att driva ut giftet innan det blir dödligt förlitar sig traditionell taurenmedicin på den lokala faunans livskraft. Maur behöver ett Prairie Wolf Heart, ett Flatland Cougar Femur, en Plainstrider Scale och en Swoop Gizzard. Genom att förena essenserna från dessa olika jägare och asätare kan han brygga en blandning som hejdar den nekrotiska spridningen och hjälper honom att återhämta sig."}},faq={{q="Vad är Mazzranache?",a="Mazzranache är en ökänd strider som strövar omkring på Mulgore-slätterna. Till skillnad från vanliga striders är den känd för sin färgstarka fjäderdräkt, demoniska röda ögon, vassa klor och ovanligt giftiga bett. Den har terroriserat resande i flera generationer.",al={"vem är mazzranache","vad är mazzranache för slags best","mazzranaches bakgrund"}},{q="Vem är Maur Raincaller?",a="Maur Raincaller är en tauren som bor i Bloodhoof Village. När han färdades genom Mulgore överföll Mazzranache honom och bet honom i axeln. Nu ligger han sängbunden med en livshotande, giftig infektion.",al={"maur raincaller","vem gav mig uppdraget","vem är den sjuka taurenen"}},{q="Varför behöver Maur delar från fyra olika djur?",a="Traditionella taurenläkemedel hämtar kraft från slättdjurens naturliga styrka och andliga essenser för att neutralisera starka gifter. Ett varghjärta, den täta märgen i ett puma-lårben, en striders fjäll och en swoops kräva bildar tillsammans ett motgift starkt nog att motverka Mazzranaches gift.",al={"varför varghjärta och pumalårben","varför ingredienser från djur","ingredienser till mazzranaches motgift"}},{q="Dödade Maurs farfar Mazzranache?",a="Nej. Maurs farfar kämpade mot den vildsinta stridern för många år sedan, men kunde inte besegra den. Han överlevde och förde vidare varningshistorier om dess klara färger och våldsamma attacker till sina efterkommande.",al={"besegrade farfar mazzranache","maurs farfar och mazzranache","vem kämpade mot mazzranache tidigare"}},{q="Ska jag jaga Mazzranache?",a="Nej. Maurs främsta mål är att överleva febern. Uppdraget går helt ut på att samla ingredienserna till hans läkemedel, inte på att jaga den legendariska fågeln.",al={"ska jag döda mazzranache","var finns mazzranache","jaga mazzranache"}},{q="Var ligger Bloodhoof Village?",a="Bloodhoof Village ligger i centrala Mulgore, söder om Thunder Bluff och strax öster om Stonebull Lake. Det är den främsta bosättningen för unga taurenkrigare som ger sig ut på de vidsträckta slätterna.",al={"var ligger bloodhoof village","bloodhoof village läge"}}},fx={["3b88d77e"]={q="Varför vill Maur Raincaller att detta görs?",a="Maurs liv står direkt på spel. När han färdades över Mulgore slätter stötte han på Mazzranache, en legendarisk plainstrider som är känd för att ha terroriserat hans farfar. Odjuret bet honom våldsamt och giftigt i axeln. En förlamande feber har brutit ut, gett honom vanvettiga mardrömmar och sprider sig stadigt genom kroppen. Utan de animaliska ingredienser som behövs för att brygga ett läkemedel kommer den rasande infektionen snart att döda honom.",al={"maur raincallers motiv","varför hjälpa maur raincaller","vad hände med maur"}},ce37bf7e={q="Varför behöver Maur en utomstående i stället för att bota sig själv?",a="Maur är för svårt skadad och febrig för att själv jaga Mulgore vilddjur. Mazzranaches giftiga bett har gjort honom omtöcknad och utmattad, så han är bunden till Bloodhoof Village. Tiden håller på att rinna ut innan infektionen blir dödlig, så han måste förlita sig på förbipasserande resenärer för att spåra upp de snabba pumorna, swoops, vargarna och plainstriders som behövs till läkemedlet.",al={"varför kan maur inte skaffa delarna","varför behöver maur dig","varför jag ska ta mig an mazzranache"}}},fp="11,227,22.365.0,20.389.0,20.179.0,23.169.0,52.247.0,40.178.0,55.95.0,35.174.0"}
P.entries["quest:767"] = {n="Rite of Vision",s="Rite of Vision är ett avgörande mognadsprov inom Rites of the Earthmother, där en ung äventyrarens andliga mognad sätts på prov. Baine Bloodhoof inleder uppdraget och hänvisar de prövande till byns siare, Zarlman Two-Moons. Resan är nödvändig för alla som söker de äldstes välsignelse och respekt på Thunder Bluffs höjder.",h="Rite of Vision är ett avgörande mognadsprov inom Rites of the Earthmother, där en ung äventyrarens andliga...",kw={"baine bloodhoof","bloodhoof village","mulgore","rite of vision","rites of the earthmother","taurenprov","thunder bluff","zarlman two-moons"},ang={["class:Druid"]="Att möta Earthmothers visioner direkt stärker druidens kall att lyssna noga till den levande världens visdom och viskningar.",["class:Shaman"]="Att söka upp Zarlman Two-Moons och vandra på visionernas väg känns djupt besläktat med schamanens plikt att balansera världsliga angelägenheter mot förfädernas vilja.",["faction:Horde"]="Att genomgå dessa traditionella heliga riter visar din lojalitet och vördnad för taurenkulturen inför de äldste som hjälper till att vägleda Horden.",["race:Tauren"]="Rite of Vision är en viktig kulturell milstolpe för varje ung tauren och markerar övergången till att bli en betrodd försvarare och andevandrare för stammen."},sec={{t="Ett heligt steg på vägen",b="I generationer har de nomadiska tauren vänt sig till Earthmother för vägledning när folket färdats över Kalimdors slätter. Nu när de samlats inom Mulgore trygga gränser är deras andliga traditioner fortfarande samhällets hörnsten. Rite of Vision är ett av de uråldriga proven som kallas Rites of the Earthmother. Tidigare prov prövar en noviss fysiska styrka och band till jakten, men Rite of Vision kräver en inre resa där unga tauren och hedrade allierade får möta andarna direkt."},{t="Siarens vägledning",b="Innan någon andlig vision kan sökas måste en person med djup kunskap om forntida visdom förbereda den prövande. I Bloodhoof Village vilar det ansvaret på den vördnadsvärde schamanen Zarlman Two-Moons. Baine Bloodhoof har anförtrott honom att förbereda resenärer, och Zarlman har skarp blick nog att känna igen dem som vandrar på förfädernas väg. Han erbjuder de inledande riterna och heliga förberedelserna som krävs för att genomtränga den fysiska världens slöja."}},faq={{q="Vad är Rite of Vision?",a="Rite of Vision är en helig ritual inom Rites of the Earthmother. Den ska vidga en äventyrarens andliga syn, så att hen kan möta förfädernas andar och visa de äldste i Thunder Bluff sin andliga beredskap.",al={"uppdraget rite of vision","vad är rite of vision","lore om rite of vision"}},{q="Vem ger uppdraget?",a="Uppdraget ges av Baine Bloodhoof, son till överhövdingen Cairne Bloodhoof. Baine vakar över bosättningen Bloodhoof Village och hänvisar värdiga resenärer till byns andliga äldste.",al={"vem ger rite of vision","uppdragsgivare för rite of vision"}},{q="Vem är Zarlman Two-Moons?",a="Zarlman Two-Moons är en erfaren tauren-schaman och den andliga ledaren i Bloodhoof Village. Han förbereder resenärer och noviser som vill genomgå heliga prov som Rite of Vision.",al={"vem är zarlman","lore om zarlman two-moons"}},{q="Varför är Rites of the Earthmother viktiga för tauren?",a="Rites of the Earthmother är en traditionell övergångsrit för tauren som når vuxen ålder. Att klara dem visar fysisk förmåga, andlig samklang och varaktig respekt för landet, och ger de högsta äldstes heder.",al={"vad rites of the earthmother betyder","varför genomföra rites of the earthmother"}},{q="Kan andra än tauren genomgå Rite of Vision?",a="Ja. Hordens allierade som färdas genom Mulgore och vinner Bloodhoof-stammens förtroende får vandra på Earthmothers väg. De visar respekt för taurentraditionen och vinner de äldstes välvilja.",al={"kan orcher genomgå rite of vision","andra än tauren och earthmother"}},{q="Var äger provet rum?",a="Provet börjar i Bloodhoof Village, en framstående tauren-bosättning nära Stonebull Lakes stränder i centrala Mulgore, söder om Thunder Bluff.",al={"var finns rite of vision","platsen för rite of vision"}}},fx={["1fa313da"]={q="Varför vill Baine Bloodhoof att du genomgår Rite of Vision?",a="Baine Bloodhoof förbereder dig för att följa dina förfäders väg och visa ditt värde för taurenfolket. När du blir vuxen i Mulgore måste du genomgå Earthmothers heliga riter för att kommunicera med andarna, lära dig vörda landet och till sist vinna de äldstes respekt i Thunder Bluff. Baine hänvisar dig till byns mystiker Zarlman Two-Moons så att du kan inleda den andliga prövningen på rätt sätt.",al={"varför baine skickar dig på rite of vision","baine bloodhoofs motiv för rite of vision","varför genomgå rite of vision"}}},fp="14,235,23.398.0,19.348.0,27.208.0,22.192.0,25.171.0,61.213.0,44.187.0,33.132.0"}
P.entries["quest:768"] = {n="Gathering Leather",s="Gathering Leather är ett enkelt bytesuppdrag som Veren Tallstrider erbjuder på Thunder Bluffs höjder. För att försörja huvudstaden och sätta unga jägare på prov byter Veren ett knippe garvade Light Leather-hudar mot hantverksvaror. Uppdraget visar hur djupt taurenfolkets tradition sitter: att förvandla bytet från jakten på slätterna till nödvändiga kläder och rustningar.",h="Gathering Leather är ett enkelt bytesuppdrag som Veren Tallstrider erbjuder på Thunder Bluffs höjder.",kw={"gathering leather","läderhantverk","light leather","mulgore","taurenjakt","thunder bluff","veren tallstrider"},ang={["class:Hunter"]="Jägare som ger sig ut på Mulgore slätter är naturligt skickliga på att spåra byte och ta till vara de Light Leather-hudar Veren behöver.",["faction:Horde"]="När hantverkare i Thunder Bluff får råmaterial stärks den unga huvudstaden medan den befäster sitt försvar och sina handelsnätverk.",["race:Tauren"]="För taurenjägare är det en viktig kulturell sed, som förts vidare genom generationer, att hedra det fallna djuret genom att göra dess hud till användbara varor."},sec={{t="Att försörja Thunder Bluff",b="I den nyetablerade huvudstaden på Mulgore höga platåer går hantverk och överlevnad hand i hand. Veren Tallstrider bearbetar hudar till kläder och skyddande rustningar som Thunder Bluffs växande befolkning behöver. I stället för att själv samla in allt uppmuntrar han unga äventyrare på väg ut över slätterna att ta med sig sitt byte hem. På så vis blir vanlig jakt en hedervärd samhällsinsats."},{t="Jaktens väg",b="För tauren är jakten på gräsmarkernas bestar ingen sport, utan en hedervärd gärning som ger stammen mat, kläder och skydd. Veren Tallstrider söker jägare som vill ära sin klan och ber särskilt om Light Leather från traktens djur. Som ersättning för tolv välbevarade hudar ger han jägaren hållbara varor och stärker därmed den ömsesidiga hjälp som håller ihop taurens samhälle."}},faq={{q="Vem är Veren Tallstrider?",a="Veren Tallstrider är läderarbetare i Thunder Bluff. Han tillverkar kläder och skyddande rustningar åt taurenfolket och byter sina färdiga varor mot färska hudar från slättens jägare.",al={"veren tallstrider","vem ger uppdraget gathering leather","uppdragsgivare för läder i thunder bluff"}},{q="Vad behöver Veren Tallstrider?",a="Veren ber om tolv bitar Light Leather, från bestar i Mulgore och närliggande områden, för att tillverka varor åt Thunder Bluff.",al={"krav för gathering leather","vad ska veren ha","material till gathering leather"}},{q="Var utspelar sig uppdraget?",a="Uppdraget börjar och slutar hos Veren Tallstrider på Thunder Bluff, men för att slutföra det måste du jaga vilda bestar på gräsmarkerna nedanför.",al={"var finns veren tallstrider","plats för gathering leather"}},{q="Varför lägger tauren så stor vikt vid jakt på bestar?",a="Taurenkulturen ser jakten som en helig balans med Jordmodern. Varje del av ett fällt djur tas till vara: köttet mättar stammen, medan ben och garvade hudar blir verktyg, tält och slitstarka rustningar.",al={"taurenfolkets jaktkultur","varför jaga för läder","taurenfolkets läderlore"}},{q="Kan alla äventyrare i Horde utföra uppgiften?",a="Ja, alla resande som är lojala mot Horde och som Veren anser ivriga att pröva sin styrka på slätterna kan hjälpa honom att samla in hudar.",al={"vem kan göra gathering leather","är gathering leather bara för horde"}},{q="Vad händer när hudarna har lämnats in?",a="Veren granskar hudarnas kvalitet, berömmer jägaren för arbetet och ger ett tillverkat utrustningsföremål som skälig betalning.",al={"lämna in gathering leather","veren tallstriders belöning"}}},fx={["1249c214"]={q="Varför vill Veren Tallstrider ha Light Leather?",a="Veren Tallstrider är en läderarbetare som tillverkar kläder och rustningar åt Thunder Bluffs invånare. För att förse staden och hålla sitt hantverk vid liv behöver han jägare som levererar fina hudar från Mulgore slätter.",al={"varför veren behöver läder","veren tallstriders motiv","varför light leather till veren"}},cd30155e={q="Vad används Light Leather till?",a="Lädret blir till nödvändiga kläder, skyddande rustningar och användbara varor åt tauren som bor högt uppe på Thunder Bluffs platåer, liksom utrustning som tillverkas i utbyte åt resande jägare.",al={"vad light leather används till","användning av light leather","hur veren använder light leather"}}},fp="17,203,24.268.0,19.288.0,25.146.0,33.146.0,33.116.0,61.180.0,45.129.0,43.133.0"}
P.entries["quest:769"] = {n="Kodo Hide Bag",s="Kodo Hide Bag är ett handelsuppdrag från Veren Tallstrider, en skicklig tauren-läderarbetare på de höga platåerna i Thunder Bluff. I utbyte mot grundläggande hantverksmaterial lär han ut den traditionella metoden för att sy slitstarka resväskor av tåligt djurskinn. Det är ett tidigt mandomsprov för lärlingar i läderarbete i Mulgore.",h="Kodo Hide Bag är ett handelsuppdrag från Veren Tallstrider, en skicklig tauren-läderarbetare på de höga...",kw={"coarse thread","kodo","kodo hide bag","läderarbete","light leather","mulgore","thunder bluff","veren tallstrider"},ang={["faction:Horde"]="Thunder Bluffs hantverkare tillhandahåller viktiga förnödenheter som håller Hordens jägare, spejare och krigare utrustade i centrala Kalimdor.",["race:Tauren"]="För Shu'halo är det ett viktigt steg att lära sig tillverka pålitlig utrustning av den mäktiga kodon, både för att hedra Jordmoderns gåvor och bevara förfädernas seder."},sec={{t="En lektion på platån",b="På Thunder Bluffs hantverkshöjder håller Veren Tallstrider fast vid den gamla nomadtraditionen att inte slösa något från jakten. För att få lära sig av honom måste en blivande läderarbetare ge honom garvat Light Leather och slitstark tråd. Genom att visa att de behärskar grundmaterialen bevisar lärlingarna att de är redo att tillverka varor värdiga att bära överlevnadsutrustning genom Kalimdors karga vidder."},{t="Kodonts anda",b="För tauren är kodon en symbol för uthållighet, styrka och beslutsamhet. Dess tjocka hud skyddar mot törnen, bitande vind och djurklor. Att tillverka väskor och kläder av kodohud är inte bara praktiskt, utan också ett uttryck för vördnad för djuret som gett Shu'halo näring och transport genom otaliga generationer på Mulgore slätter."}},faq={{q="Vem erbjuder uppdraget Kodo Hide Bag?",a="Uppdraget erbjuds av Veren Tallstrider, en tauren-tränare i läderarbete och handelsman i Thunder Bluff.",al={"uppdragsgivare","var får man uppdraget kodo hide bag","veren tallstriders plats"}},{q="Vem kan ta sig an uppgiften?",a="Endast äventyrare som tränat i läderarbete och nått minst lärlingsnivå 10 kan få denna träningsuppgift av Veren Tallstrider.",al={"vem kan ta uppdraget","uppdragskrav","yrkeskrav"}},{q="Vilka material behöver Veren Tallstrider?",a="Han behöver fyra stycken Light Leather och fyra spolar Coarse Thread för att fylla på sina handelsvaror innan han delar med sig av sitt mönster.",al={"vilka föremål behövs","material till kodo hide bag","föremål att lämna in för uppdraget"}},{q="Varför är kodohud betydelsefull för tauren-hantverkare?",a="Kodon förkroppsligar motståndskraft och fysisk styrka, egenskaper som tauren värdesätter högt. Att tillverka slitstark utrustning av deras hudar hedrar djurets ande och ger samtidigt resenärer användbara, tåliga saker när de färdas över slätterna.",al={"varför kodohud","kodons betydelse för tauren","kodons vikt"}},{q="Vad lär Veren Tallstrider ut när uppdraget är slutfört?",a="När Veren fått materialet lär han hantverkaren den särskilda kunskap som behövs för att sy en Kodo Hide Bag.",al={"uppdragsbelöning","vad får jag","väskmönster"}},{q="Var kan man få tag på materialen som behövs?",a="Light Leather får man genom att flå vilddjur på låg nivå i Mulgore och närliggande områden, medan Coarse Thread kan köpas direkt av handels- och skräddarleverantörer.",al={"var får man light leather","var får man coarse thread"}}},fx={c94273ea={q="Varför vill Veren Tallstrider att detta görs?",a="Veren Tallstrider är stolt över att fostra nästa generation taurenläderarbetare. Mulgore kodo-djur vördas för sin styrka och uthållighet, och att tillverka en traditionell väska av deras hudar är en grundläggande färdighet. Genom att be dig samla material till hans hantverk prövar Veren din hängivenhet och påhittighet innan han lär dig hantverkets tekniker.",al={"varför veren tallstrider vill ha läder","veren tallstriders motiv","varför uppdraget med kodo-skinnväskan"}},["1f62e959"]={q="Vad ska Light Leather användas till?",a="Light Leather är det grundläggande hantverksmaterial som Veren Tallstrider behöver i utbyte mot sin undervisning. Att bearbeta garvade hudar är kärnan i taurenfolkets läderhantverk. Genom att skaffa fint läder visar du att du behärskar grunderna i att behandla djurhudar innan du lär dig sy särskilda behållare som kodo-skinnväskor.",al={"vad light leather används till","varför ta med light leather","syftet med light leather"}},["7d0f7d7f"]={q="Vad ska Coarse Thread användas till?",a="Coarse Thread är ett viktigt basmaterial inom sömnad och läderarbete, som används för att foga samman tjocka hudar. För att tillverka hållbara packar som klarar Mulgore slätter behöver hantverkaren en stark tråd som inte brister under tung belastning eller hårt väder.",al={"varför coarse thread","syftet med coarse thread","vad coarse thread används till"}}},fp="13,149,20.327.0,18.307.0,35.102.0,39.105.0,46.150.0,59.171.0,50.82.0,46.132.0"}
P.entries["quest:77"] = {n="A Sticky Situation",s="Gilveradin Sunchaser har originalförpackningen till Hinterlands Honey Ripple som Dran Droffers vill ha och hjälper till att packa den mot en avgift på två extra flaskor. Flaskorna finns i lådor runt den övergivna Horde-basen nära Skulk Rock.",h="Gilveradin Sunchaser har originalförpackningen till Hinterlands Honey Ripple som Dran Droffers vill ha och...",kw={"dran droffers","gilveradin sunchaser","the hinterlands","hinterlands honey ripple","geléer","skulk rock","slemvarelser"},sec={{t="En fråga om förpackning",b="Dran Droffers söker efter drycken, och Gilveradin Sunchaser har originalförpackningen till den. Hjälpen är inte gratis: Gilveradin vill ha två extra flaskor som ersättning. Tio flaskor Hinterlands Honey Ripple ska samlas in och tas tillbaka till lägret."},{t="Skulk Rocks ruiner",b="Lådorna står runt den övergivna Horde-basen nära Skulk Rock. Vidriga slemvarelser och geléer klänger sig fast vid ruinerna, och enligt rykten leds de av någon sorts mästargele."}},faq={{q="Vem vill ha Hinterlands Honey Ripple förpackad?",a="Dran Droffers är den som söker efter drycken, och Gilveradin Sunchaser har originalförpackningen till den, som är avsedd för Maltons far.",al={"vem behöver drycken","dran droffers dryck","vem är förpackningen till"}},{q="Vad tar Gilveradin betalt för förpackningen?",a="Gilveradin begär två extra flaskor av drycken som avgift. Tio flaskor ska hämtas från lådorna.",al={"varför tio flaskor","gilveradins avgift","varför så mycket dryck"}},{q="Var finns lådorna med Hinterlands Honey Ripple?",a="De finns i lådor runt den övergivna Horde-basen nära Skulk Rock i The Hinterlands.",al={"dryckens plats","var finns honungsdrycken","skulk rocks lådor"}},{q="Vad finns vid det övergivna lägret vid Skulk Rock?",a="Vidriga slemvarelser och geléer klänger sig fast vid ruinerna, och enligt rykten leds de av en mästargele.",al={"skulk rocks monster","vad finns vid skulk rock","geléer vid skulk rock"}}},fp="18,208,21.209.0,19.176.0,48.121.0,46.94.0,54.82.0,44.82.0"}
P.entries["quest:770"] = {n="The Demon Scarred Cloak",s="Demon Scarred Cloak är en trasig fäll från den legendariska vita vargen Ghost Howl, som strövar över Mulgore grässlätter. Fällen bär ett bestående sår från tidigare strider mot Burning Legion och visar att besten befriats från sitt lidande. När du lämnar den till äldste i Bloodhoof Village får en tragisk lokal legend sitt slut.",h="Demon Scarred Cloak är en trasig fäll från den legendariska vita vargen Ghost Howl, som strövar över Mulgore...",kw={"burning legion","demon scarred cloak","ghost howl","mulgore","skorn whitecloud","vit varg"},ang={["class:Druid"]="Druider ser den demonärrade fällen som en dyster påminnelse om att landet och dess vilda invånare fortfarande bär oläkta sår från demonernas invasion av Kalimdor.",["class:Hunter"]="Att spåra upp en ensam, ärrad alfavarg som Ghost Howl är en viktig övergångsrit. Det ger stor uppskattning och en mästerjägares gåva från den äldre Skorn Whitecloud.",["race:Tauren"]="För Shu'halo är jakten på Ghost Howl ingen grym handling eller erövring, utan en dyster ritual som ska ge en plågad varelse frid från Burning Legions kvardröjande besmittelse."},sec={{t="En relik från demoniska sår",b="Ghost Howl är en svårfångad vit varg, känd i hela Mulgore för sin vildhet och sin sorgsna ylande röst. När besten dödas lämnar den efter sig en fäll som tydligt märkts av ondskefull demonisk korruption. Spåren går tillbaka till vargens desperata strider mot Burning Legions invaderande demoner. Konfrontationen lämnade Ghost Howl sårad till kropp och själ långt efter att det tredje kriget tagit slut."},{t="Frid åt en plågad ande",b="Tauren i Mulgore hyser djup respekt för hemlandets vilda djur och vördar dem som Jordmoderns barn. När du visar den ärrade manteln för Skorn Whitecloud i Bloodhoof Village bekräftar det att den plågade rovbesten är död. Skorn förstår vilken skicklighet som krävdes för att spåra upp och besegra Ghost Howl och uttrycker det dystra hoppet att vargens plågade ande äntligen funnit frid i döden."}},faq={{q="Vad är Demon Scarred Cloak?",a="Det är den trasiga huden från Ghost Howl, en legendarisk vit varg i Mulgore. Fällen har synliga ärr från kaoskrafter, efter en gammal strid mot Burning Legion.",al={"vad är demon scarred cloak","föremålet demon scarred cloak","ghost howls fäll"}},{q="Varifrån kommer demonärren på manteln?",a="Ghost Howl fick sina sår i strider mot Burning Legion, när de demoniska inkräktarna trängde fram över Kalimdor under det tredje kriget.",al={"varför är ghost howl ärrad","hur fick ghost howl sina ärr","ghost howl och legionen"}},{q="Vem ska jag lämna manteln till?",a="Lämna manteln till Skorn Whitecloud, en äldre taurenjägare som bor i Bloodhoof Village i Mulgore.",al={"var lämnar jag in demon scarred cloak","vem vill ha demon scarred cloak","lämna in till skorn whitecloud"}},{q="Varför bryr sig Skorn Whitecloud om Ghost Howl?",a="Skorn Whitecloud är en pensionerad jägare som känner igen Ghost Howl som en mäktig best, svårt plågad av demonisk korruption. Han respekterar skickligheten som krävdes för att fälla en sådan varelse och hoppas att dess ande äntligen kan få ro.",al={"skorn whiteclouds historia","varför vill skorn ha ghost howl"}},{q="Var hittar man Ghost Howl?",a="Ghost Howl är en sällsynt vit varg som strövar över Mulgore öppna slätter. Den ses oftast på de norra eller centrala fälten mellan Red Cloud Mesa och Thunder Bluff.",al={"var hittar man ghost howl","ghost howls plats","ghost howls uppdykning"}},{q="Varför hoppas tauren att vargens ande finner frid?",a="Taurenkulturen betonar harmoni med naturen och vördnad för vilda andar. Eftersom demonisk korruption gav Ghost Howl ett liv i ändlöst lidande ses dess nederlag som en barmhärtig befrielse till Jordmodern.",al={"taurens tro och ghost howl","ghost howls ande"}}},fp="23,231,21.317.0,27.329.0,32.166.0,49.129.0,28.102.0,48.185.0,26.131.0,53.181.0"}
P.entries["quest:7701"] = {n="WANTED: Overseer Maltorius",s="En efterlysning tillkännager att Overseer Maltorius, en avfälling till agent inom Thorium Brotherhood och nyanställd befälhavare för Dark Iron Slag Pit-besättningen i The Cauldron, ska dö. På order av Overseer Oilfist ska hans huvud föras tillbaka som bevis till Lookout Captain Lolo Longstriker.",h="En efterlysning tillkännager att Overseer Maltorius, en avfälling till agent inom Thorium Brotherhood och...",kw={"belöning","cauldron","lolo longstriker","overseer maltorius","overseer oilfist","searing gorge","the slag pit","thorium brotherhood"},sec={{t="Pris på en förrädare",b="Overseer Maltorius, en förrädisk Dark Iron-dvärg, finns någonstans i djupet av The Cauldrons Slag Pit. Ordern är att döda honom, ta hans huvud och föra det tillbaka till Lookout Captain Lolo Longstriker för belöningen."}},faq={{q="Vem är Overseer Maltorius?",a="En förrädisk Dark Iron-dvärg. Efterlysningen kallar honom en avfälling till agent inom Thorium Brotherhood och nyanställd befälhavare för Dark Irons besättning i The Cauldrons Slag Pit.",al={"maltorius bakgrund","vem är maltorius","overseer maltorius bakgrund"}},{q="Var finns Overseer Maltorius?",a="Långt nere i Slag Pit, som tillhör The Cauldron.",al={"maltorius plats","var finns maltorius","hur hittar man overseer maltorius"}},{q="Vem beordrade att Overseer Maltorius skulle dö?",a="Overseer Oilfist, som enligt efterlysningen gav ordern.",al={"vem utfärdade efterlysningen","vem vill se maltorius död","vem beordrade mordet"}},{q="Vem tar emot beviset på Maltorius död?",a="Lookout Captain Lolo Longstriker i Searing Gorge. Maltorius huvud är beviset som efterfrågas.",al={"vem ska få maltorius huvud","vart ska maltorius huvud föras","lolo longstrikers plats"}}},fp="26,259,20.200.0,26.184.0,38.69.0,44.52.0,40.96.0"}
P.entries["quest:7704"] = {n="Look at the Size of It!",s="Du har fått tag i en gigantisk, utsmyckad kudde som en gång tillhörde Chambermaid Pillaclencher. Evonice Sootsmoker i Searing Gorge vill säkert ha den.",h="Du har fått tag i en gigantisk, utsmyckad kudde som en gång tillhörde Chambermaid Pillaclencher.",kw={"chambermaid pillaclencher","evonice sootsmoker","kolla hur stor den är","kudde","searing gorge"},sec={{t="En kudde åt Evonice",b="Kudden som Chambermaid Pillaclencher hade är nu din. Evonice Sootsmoker vill säkert gärna lägga beslag på den. Ta med den till henne i Searing Gorge och se vad hon erbjuder dig för besväret."}},faq={{q="Vem vill ha Chambermaid Pillaclenchers kudde?",a="Evonice Sootsmoker i Searing Gorge väntade sig att vilja ha den väldigt gärna.",al={"vem ska jag ta kudden till","evonice sootsmoker kudde","vart ska kudden"}},{q="Var kommer kudden ifrån?",a="Den tillhörde Chambermaid Pillaclencher och är gigantisk och utsmyckad.",al={"kuddedrop","vem släpper kudden","chambermaids kudde"}},{q="Var hittar man Evonice Sootsmoker?",a="I Searing Gorge.",al={"evonices plats","var finns evonice sootsmoker","evonice searing gorge"}}},fp="23,135,20.166.0,45.91.0,33.71.0,38.43.0"}
P.entries["quest:771"] = {n="Rite of Vision",s="Synriten är ett grundläggande andligt prov för unga tauren som lämnar Red Cloud Mesa och ger sig ut i det större Mulgore. För att skingra slöjan och få vägledning från förfädernas andar måste de invigda samla naturliga ingredienser och brygga Water of the Seers under Zarlman Two-Moons vakande öga i Bloodhoof Village.",h="Synriten är ett grundläggande andligt prov för unga tauren som lämnar Red Cloud Mesa och ger sig ut i det...",kw={"bärnstall","bloodhoof village","jordmodern","mulgore","synriten","water of the seers","brunnsstenar","zarlman two-moons"},ang={["class:Druid"]="Druider hyser stor vördnad för bärnstall och brunnsstenar och ser dem som direkta uttryck för växtligheten och de livgivande vattendrag som upprätthåller balansen i Mulgore.",["class:Shaman"]="Schamaner känner igen tillredningen av Water of the Seers som en traditionell jordningsritual. Den stämmer anden så att den kan läsa osynliga element innan den samtalar direkt med andar.",["race:Tauren"]="För tauren är Synriten en viktig kulturell milstolpe som knyter en blivande krigare, jägare eller mystiker till Jordmoderns och förfädernas andliga arv."},sec={{t="Landets ingredienser",b="Innan någon vision kan uppenbaras måste den invigde visa djup förståelse för naturens gåvor i Mulgore. Zarlman Two-Moons ber sökaren samla brunnsstenar nära de heliga gemensamma vattenbrunnarna och bärnstall som fallit vid rötterna till Mulgore gamla träd. Dessa naturelement är inte bara fysiska föremål. För tauren bär de på Jordmoderns slumrande magi och livskraft, redo att ledas in i ritualen."},{t="Att brygga Water of the Seers",b="När ingredienserna har samlats blandar Zarlman stenarna och bärnstallen till den kraftfulla Water of the Seers. När den dricks intill byns stamflamma klarnar sinnet och en eterisk vägledare kallas fram. Att följa denna uppenbarelse över slätterna är ritualens verkliga kärna. Det prövar den invigdes förmåga att röra sig mellan den fysiska världen och landets andliga viskningar."}},faq={{q="Vad är syftet med Synriten?",a="Synriten är ett andligt prov för tauren som nått vuxen ålder och söker sin väg. Genom att tillreda och dricka Water of the Seers lär sig den invigde att tala med andar och följa förfädernas omen över Mulgore slätter.",al={"vad är synriten","varför genomföra synriten","synritens syfte"}},{q="Vem är Zarlman Two-Moons?",a="Zarlman Two-Moons är en tauren-schaman och siare i Bloodhoof Village. Han leder andliga prov för unga äventyrare, tillreder rituella brygder som Water of the Seers och tolkar Jordmoderns tecken.",al={"vem är zarlman","zarlman two-moons roll","uppdragsgivaren zarlman"}},{q="Var hittar man brunnsstenar och bärnstall?",a="Brunnsstenar samlas från marken nära sötvattenbrunnarna som finns utspridda över Mulgore. Bärnstall ligger vid foten av de stora, utbredda träden i det omgivande gräslandskapet.",al={"var hittar man bärnstall","brunnsstenarnas plats","ingredienser till synriten"}},{q="Vad händer efter att man druckit Water of the Seers?",a="Om man dricker brygden nära stamflamman öppnas den andliga synen och en spöklik djurvägledare visar sig. Sökaren måste följa anden över slätterna för att upptäcka nästa steg på sin heliga resa.",al={"vad händer härnäst i synriten","water of the seers effekt","fortsättning på visionsuppdraget"}},{q="Varför vördar tauren vattenbrunnarna så djupt?",a="Vatten är Mulgore livsblod och en dyrbar gåva från Jordmodern. Brunnarna är heliga gemensamma samlingsplatser som ger näring åt både landet och dess hjordar, så stenarna intill dem är laddade med andlig kraft.",al={"taurenernas vattenbrunnar","varför är brunnarna heliga","vatten i mulgore"}},{q="Leder det här uppdraget vidare till fler ritualer?",a="Ja. Uppgiften ingår i en ceremoni med flera steg. När Zarlman har tillrett Water of the Seers måste de invigda dricka den, följa visionen som visar sig och uppsöka äldre ledare runt om i Mulgore.",al={"nästa uppdrag i synriten","är synriten en uppdragskedja","taurenernas ritualkedja"}}},fx={["6b13f1a7"]={q="Varför vill Zarlman Two-Moons att detta görs?",a="Som stammens schaman ansvarar Zarlman Two-Moons för att vägleda lovande unga äventyrare genom taurenfolkets heliga traditioner. Han kan inte bara skänka dig andlig visdom. Du måste själv vinna Jordmoderns och dina förfäders välvilja genom att delta i ritualen, med början i att samla in landets heliga element.",al={"zarlman two-moons motiv","varför zarlman skickar dig","varför zarlman vill att du genomgår rite of vision"}},cc7474fb={q="Vad ska Well Stones användas till?",a="Well Stones samlas in från de heliga vattenbrunnarna runtom i Mulgore. De är genomsyrade av naturmagi från Jordmoderns renaste källor och är en av de viktiga ingredienser som Zarlman Two-Moons behöver för att brygga det mystiska Water of the Seers.",al={"syftet med well stones","varför behövs well stone","användning av well stone"}},["4efb8f2d"]={q="Vad ska Ambercorn användas till?",a="Ambercorn faller från de mäktiga träden i Mulgore och bär på landets växtlivs naturliga essens. Tillsammans med Well Stones, och efter att Zarlman Two-Moons låtit det dra, ger den de magiska egenskaper som krävs för att brygga Water of the Seers och skänka dig syner från förfäderna.",al={"syftet med ambercorn","vad ambercorn används till","varför skaffa ambercorn"}},["761f0189"]={q="Varför måste du samla ingredienserna i stället för att Zarlman Two-Moons gör det?",a="Rite of Vision är en personlig prövning i andlig utveckling, inte ett rutinärende. För att kommunicera med andarna måste du visa vördnad för landet och samklang med det genom att själv söka upp dess naturliga gåvor. Om någon annan samlade ingredienserna skulle ritualens heliga syfte gå förlorat.",al={"varför måste jag skaffa ambercorn","varför samlar inte zarlman in well stones","varför jag ska genomgå rite of vision"}}},fp="14,198,24.309.0,30.322.0,42.203.0,25.218.0,42.143.0,51.203.1,47.212.0,38.183.1"}
P.entries["quest:772"] = {n="Rite of Vision",s="Synriten är höjdpunkten i en uråldrig prövning som unga taurer genomgår i Bloodhoof Village. Genom att dricka det heliga Water of the Seers vid stammens lägereld kallar de prövade fram en andlig vägvisare som leder dem mot deras öde.",h="Synriten är höjdpunkten i en uråldrig prövning som unga taurer genomgår i Bloodhoof Village.",kw={"bloodhoof village","spökvarg","mulgore","synriten","seer wiserunner","stamlägereld","water of the seers","zarlman two-moons"},ang={["class:Druid"]="Riten stärker vördnaden för naturen och den andliga ödmjukheten inför vägledning från djurformer.",["class:Shaman"]="Att följa en förfädersande i vargskepnad är en tidig läxa i att vandra mellan världar och förankrar en schamans band till andarna som vägleder horden.",["race:Tauren"]="För unga taurer är Synriten en djupt helig övergång till vuxenlivet som visar deras gemenskap med förfäderna och lydnad inför andlig vägledning."},sec={{t="Water of the Seers",b="Efter att ha samlat de nödvändiga ritualörterna och klarat de första trosprövningarna får den prövade Water of the Seers av byns schaman, Zarlman Two-Moons. Denna kraftfulla dryck måste intas framför den dånande stamlägerelden mitt i Bloodhoof Village. När den dricks med fokuserat och vördnadsfullt sinne vidgar det heliga vattnet drickarens sinnen bortom den fysiska synen och överbryggar slöjan mellan den materiella världen och andevärlden."},{t="Att följa Ghost Wolf",b="När brygden har druckits framträder en eterisk gestalt ur lågorna: en uråldrig spökvarg. Anden talar inte och slåss inte, utan travar tyst mot nordväst över Mulgore slätter. En sann prövad måste följa dess stilla väg, spåra dess färd bort från byn och djupt in bland de klippiga kullarna, där eremiten Seer Wiserunner väntar i avskild meditation."},{t="En vandring mot visdom",b="Att nå Seer Wiserunner vid mynningen till hans bergsgrotta innebär att synen har fullbordats. Vandringen över de gräsbevuxna kullarna prövar den prövades tålamod, tillit till förfädernas vägledning och samhörighet med Jordmodern. Den som klarar denna rit får som ung äventyrare rätt att genomgå det yttersta vuxenprovet: Visdomsriten."}},faq={{q="Vad händer när jag dricker Water of the Seers?",a="När du dricker vattnet nära stamlägerelden i Bloodhoof Village öppnas dina andliga sinnen. Strax efteråt visar sig en spöklik varg framför lågorna och vägleder dig.",al={"hur fungerar water of the seers","dricka water of the seers","vad gör vattnet"}},{q="Vart leder anden mig?",a="Den andliga vargen travar mot nordväst från Bloodhoof Village över kullarna i Mulgore och leder dig raka vägen till en klippgrotta där Seer Wiserunner bor.",al={"vart går spökvargen","vem leder vargen till","vargens mål"}},{q="Vem är Zarlman Two-Moons?",a="Zarlman Two-Moons är en framstående taurenschaman i Bloodhoof Village som har i uppgift att förbereda de prövade för andligt vuxenliv genom förfädernas riter och heliga brygder.",al={"vem ger synriten","zarlman two-moons roll"}},{q="Vem är Seer Wiserunner?",a="Seer Wiserunner är en äldre taurenmystiker som lever i begrundan bland klipporna nordväst om Bloodhoof Village. Prövade som följer sin andesyn finner honom och kan slutföra prövningen.",al={"vem är wiserunner","searen i grottan i mulgore"}},{q="Varför måste vattnet drickas nära stamlägerelden?",a="Stamlägerelden fungerar som ett heligt fäste för Bloodhoof Villages förfädersandar. Kombinationen av dess välsignade lågor och det heliga vattnet låter synen överbrygga till den vakna världen.",al={"varför stamlägereld","synriten vid lägerelden"}},{q="Vilken rit följer efter Synriten?",a="När de har fullbordat Synriten med Seer Wiserunner får de prövade i uppdrag att genomgå Visdomsriten, den sista andliga prövningen under deras första tid i Mulgore.",al={"nästa uppdrag efter synriten","what comes next"}}},fx={["659b3713"]={q="Varför vill Zarlman Two-Moons att jag genomgår Rite of Vision?",a="Som schaman i Bloodhoof Village vägleder Zarlman Two-Moons unga tauren längs deras förfäders heliga stigar. När du nu har samlat ingredienserna till Water of the Seers ger han dig brygden så att du kan kommunicera direkt med andarna, bevittna din syn och ta nästa steg mot att upptäcka ditt öde inom stammen.",al={"varför rite of vision","zarlman two-moons motiv","syftet med rite of vision"}},b8c8221c={q="Varför måste jag genomföra ritualen själv?",a="Earthmothers riter är djupt personliga prövningar av mognad och andligt uppvaknande. Ingen vakt eller äldste kan följa andarnas väg åt dig. Bara din egen ande kan ta emot vägledningen som ska visa dig din plats och uppgift bland taurenfolket.",al={"varför måste jag genomföra ritualen","varför jag ska genomgå rite of vision","varför kan inte någon annan genomföra ritualen"}}},fp="14,147,22.349.0,24.288.0,16.306.0,49.162.0,36.134.0,25.152.0,23.189.0,49.160.0,41.153.0"}
P.entries["quest:7721"] = {n="Fuel for the Zapping",s="På The Forgotten Coast i Feralas har Zorbin Fandazzle öppnat en ingenjörsverkstad mot bättre vetande, och de lokala elementalerna är en plåga. De är också en idealisk källa till råkraft för att förädla Ultra-Shrinker, och det är vattenelementalernas kärnor Zorbin vill ha.",h="På The Forgotten Coast i Feralas har Zorbin Fandazzle öppnat en ingenjörsverkstad mot bättre vetande, och de...",kw={"feralas","the forgotten coast","sea elemental","sea spray","ultra-shrinker","vattenelementkärna","zorbin fandazzle"},sec={{t="Kraft från bränningarna",b="Zorbin Fandazzle förbannar elementalismens tygellösa krafter och kallar kustens elementaler för plågoandar. Ändå räknar Zorbin också med dem som en idealisk källa till råkraft vid förädlingen av Ultra-Shrinker. Zorbin vill att du ger kustens Sea Elementals och Sea Sprays vad de tål, behåller deras vattenelementkärnor och tar med dem till Zorbin vid kajen."},{t="Zorbins tack",b="Zorbin är förtjust: kärnorna räcker till fortsatt arbete ett tag, och det finns nu färre elementaler längs kusten. Zorbin tillägger att det varit en anledning att gråta om nätterna att öppna verkstaden på vad som kanske är den sämsta plats man kan tänka sig. Zorbin visar sin tacksamhet med en betalning, trots att det anstränger Zorbins ekonomi."}},faq={{q="Vem efterfrågar elementalernas kärnor?",a="Zorbin Fandazzle, som driver en ingenjörsverkstad på The Forgotten Coast i Feralas, nära kajen där.",al={"vem ger bränsle till zappningen","zorbin fandazzle uppdragsgivare","vem startar fuel for the zapping"}},{q="Varför behöver Zorbin Fandazzle vattenelementkärnor?",a="Zorbin anser att de lokala elementalerna är en idealisk källa till råkraft för att förädla Ultra-Shrinker, och det är vattenelementalernas kärnor Zorbin vill ha.",al={"varför vattenelementkärnor","vad används kärnor till","bränsle till ultra-shrinker"}},{q="Var samlas elementalernas kärnor in?",a="Zorbin vill att du tar dem från Sea Elementals och Sea Sprays som strövar omkring på The Forgotten Coast i Feralas.",al={"var hittar man kärnor","sea elemental plats","var finns sea sprays"}}},fp="20,187,19.309.0,15.293.1,38.122.0,53.141.0,39.89.0"}
P.entries["quest:7722"] = {n="What the Flux?",s="Master Smith Burninate säger att Maltorius tog med sig receptet på Fiery Flux när han lämnade klanen. Det är värt mer än en obefläckad arkansk kristall. Burninate vill ha tillbaka de hemliga planerna och är säker på att de finns nära Maltorius, djupt nere i The Slag Pit.",h="Master Smith Burninate säger att Maltorius tog med sig receptet på Fiery Flux när han lämnade klanen.",kw={"burninate","the cauldron","fiery flux","maltorius","planer","searing gorge","the slag pit"},sec={{t="Det stulna receptet",b="Master Smith Burninate kallar Maltorius en förrädare som lämnade klanen med receptet på Fiery Flux. Burninate skulle slå vad om att receptet följde med Maltorius nya befordran bland Dark Irons, och vill ha tillbaka de hemliga planerna."},{t="Ner i The Slag Pit",b="Burninate är säker på att planerna finns nära Maltorius, nere i djupet av The Slag Pit. Secret Plans: Fiery Flux är det Burninate vill ha tillbaka."}},faq={{q="Vem stal receptet på Fiery Flux?",a="Maltorius, som Master Smith Burninate kallar en förrädare mot deras klan.",al={"vem stal receptet","vem tog planerna","vad förrädaren gjorde med flux"}},{q="Var finns de hemliga planerna?",a="Burninate tror att de finns nära Maltorius, djupt nere i The Slag Pit i The Cauldron.",al={"var finns planerna","plats för secret plans: fiery flux","var hittar man planerna för fiery flux"}},{q="Vem ber om att planerna ska hämtas tillbaka?",a="Det är Burninate, en mästersmed, som vill ha dem tillbaka.",al={"vem ger uppdraget what the flux","vad är flux uppdragsgivare"}},{q="Varför är planerna viktiga för Burninate?",a="Burninate säger att receptet på Fiery Flux är värt mer än en obefläckad arkansk kristall, och att det var klanens egen hemlighet.",al={"varför är fiery flux viktigt","betydelsen av receptet på fiery flux"}}},fp="14,202,17.238.0,17.147.0,36.120.0,27.92.0,39.58.0,37.96.0"}
P.entries["quest:7723"] = {n="Curse These Fat Fingers",s="Hansel Heavyhands i Searing Gorge kan inte längre dela ut stryk som förr, eftersom fingrarna har svullnat. Hansel ber dig gå och banka på de tunga krigsgolemerna åt dem.",h="Hansel Heavyhands i Searing Gorge kan inte längre dela ut stryk som förr, eftersom fingrarna har svullnat.",kw={"the cauldron","tjocka fingrar","hansel heavyhands","tunga krigsgolemer","searing gorge","blodkorvar från thelsamar"},sec={{t="Fingrar som prinskorvar",b="Hansel Heavyhands säger att klimatet i Gorge, med sin tunna luft, får Hansels fingrar att svullna tills de liknar enorma blodkorvar från Thelsamar. Därför kan Hansel inte längre dela ut stryk som förut och behöver att du sköter Hansels ärenden i stället."},{t="Först på listan",b="Först på Hansels dagordning står de tunga krigsgolemerna i Gorge, som Hansel vill att du bankar hårt på. Tjugo av dem ska förstöras. De strövar omkring i områdena runt The Cauldron, och du återvänder till Hansel när tillräckligt många har fallit."}},faq={{q="Vem är Hansel Heavyhands?",a="Någon i Searing Gorge vars svullna fingrar hindrar dem från att slåss, så de ber dig sköta bankandet.",al={"hansel heavyhands","vem ger uppdraget curse these fat fingers","vem ger uppdraget"}},{q="Varför kan Hansel inte slåss mot golemerna själv?",a="Hansel skyller på klimatet och den tunna luften i Gorge, som får fingrarna att svullna. De liknar dem vid enorma blodkorvar från Thelsamar.",al={"varför har hansel tjocka fingrar","lore om tjocka fingrar","hansels svullna händer"}},{q="Vilka fiender måste besegras?",a="Tjugo tunga krigsgolemer.",al={"vilka fiender ska jag slåss mot","vad vill hansel döda"}},{q="Var finns de tunga krigsgolemerna?",a="De strövar omkring i områdena runt The Cauldron i Searing Gorge.",al={"var finns golemerna","plats för tunga krigsgolemer"}}},fp="23,160,21.257.0,17.177.0,25.133.0,47.130.0,29.41.0,39.77.0"}
P.entries["quest:7724"] = {n="Fiery Menace!",s="Hansel Heavyhands säger att varje gång han vill ha en stund för att koppla av och tänka över sitt liv, ger makthavarna honom ännu ett uppdrag. Större lavaspindlar ställer till oreda i Searing Gorge, och han vill att du dödar tjugo av dem.",h="Hansel Heavyhands säger att varje gång han vill ha en stund för att koppla av och tänka över sitt liv, ger...",kw={"brännande hot","större lavaspindlar","hansel heavyhands","oilfist","searing gorge","spindlar"},sec={{t="Ännu ett uppdrag åt Hansel",b="Hansel Heavyhands klagar över att makthavarna aldrig lämnar honom i fred. Större lavaspindlar ställer till oreda, och han vill hellre att du sköter dödandet än att han gör det."},{t="De större lavaspindlarna",b="Oilfist säger att spindlarna skjuter eld från ett olämpligt ställe, vilket gör barnen upprörda. Hansel vill att tjugo större lavaspindlar dödas. De finns på platåerna och vid lavapölarna i Searing Gorge."}},faq={{q="Vem skickar dig efter spindlarna?",a="Hansel Heavyhands i Searing Gorge, som hoppades få en lugn stund men fick ännu ett uppdrag.",al={"uppdragsgivare","vem ger uppdrag","hansel"}},{q="Varför måste spindlarna dödas?",a="Större lavaspindlar ställer till oreda, och Oilfist säger att sättet de skjuter eld på gör barnen upprörda.",al={"varför döda spindlar","vad gjorde spindlarna","spindelproblem"}},{q="Vem berättade för Hansel om spindlarna?",a="Oilfist, som säger att spindlarna skjuter eld från ett olämpligt ställe.",al={"vem klagade på spindlarna","oilfist"}},{q="Hur många större lavaspindlar måste dödas?",a="Hansel ber dig ta kål på tjugo stycken.",al={"hur många spindlar","antal spindlar"}}},fp="13,104,22.191.0,24.204.0,32.100.0,37.100.0,34.70.0,45.52.0"}
P.entries["quest:7725"] = {n="Again With the Zapped Giants",s="Zorbin Fandazzle vet att du redan har samlat in rester, men kan alltid använda fler. Zorbin's Ultra-Shrinker står till ditt förfogande igen för jättarna i Feralas, och Zorbin väntar vid bryggorna på The Forgotten Coast. Zorbin kan inte betala i närheten av lika mycket den här gången, men lovar att sprida ordet om dina tjänster.",h="Zorbin Fandazzle vet att du redan har samlat in rester, men kan alltid använda fler.",kw={"feralas","the forgotten coast","jättar","miniatyriseringsrest","steamwheedle cartel","ultra-shrinker","zorbin fandazzle"},sec={{t="En repris med Ultra-Shrinker",b="Zorbin Fandazzle medger att du redan har samlat in rester, men kallar detta en repris och säger att det alltid finns plats för fler. Zorbin ber dig att zappa jättar i Feralas en gång till med Ultra-Shrinker och ta med tio miniatyriseringsrester från de förminskade jättarna till bryggorna på The Forgotten Coast. Eftersom Zorbin inte kan erbjuda i närheten av lika mycket i gengäld, lovar Zorbin att lovorda dina tjänster bland goblinvänner, som har rätt stora öron."},{t="Zorbins tack",b="Zorbin är överlycklig över att du har ställt upp igen, trots att betalningen är mindre än du är van vid. Zorbin insisterar på att ryktet om dina stordåd för goblinernas sak redan sprids genom Steamwheedle Cartels maktens korridorer."}},faq={{q="Vem ber om fler rester?",a="Zorbin Fandazzle, som väntar vid bryggorna på The Forgotten Coast i Feralas.",al={"uppdragsgivare","zorbin plats","vem ger uppdraget again with the zapped giants"}},{q="Vad hände före detta?",a="Det här följer på Zapped Giants, då du för första gången samlade in rester åt Zorbin Fandazzle.",al={"förutsättning","föregående uppdrag","vad ska jag göra först"}},{q="Hur samlar jag in resterna?",a="Zorbin's Ultra-Shrinker används på valfri sorts jätte i Feralas för att förminska den, och resterna finns på de förminskade jättarna.",al={"hur får jag tag på rester","miniatyriseringsrest","hur förminskar jag jättar"}},{q="Var hittar jag jättarna?",a="Jättarna finns längs Feralas västra kust.",al={"jättarnas plats","var finns jättarna i feralas","jättar vid forgotten coast"}},{q="Kommer Zorbin att ta emot fler rester en annan gång?",a="Zorbin säger att det alltid går att använda fler rester, så du är välkommen tillbaka med ytterligare tio.",al={"kan uppdraget upprepas","kan jag upprepa again with the zapped giants","upprepbart jätteuppdrag"}}},fp="28,224,32.327.0,15.225.1,26.93.0,22.87.0,28.119.0,27.45.0,43.88.0"}
P.entries["quest:7726"] = {n="Refuel for the Zapping",s="Zorbin Fandazzle behöver fler vattenelementarkärnor. Det är svårt att slå upp en butik på The Forgotten Coast, så ersättningen blir mindre, men Zorbin lovar att berätta för alla inom hörhåll om din hjälp och säger sig ha vänner i Cartel.",h="Zorbin Fandazzle behöver fler vattenelementarkärnor.",kw={"feralas","the forgotten coast","sea elemental","sea spray","steamwheedle cartel","vattenelementarkärna","zorbin fandazzle"},sec={{t="Mer av samma",b="Zorbin Fandazzle skämtar om den heroiska bedriften att samla slem inifrån elementarvarelser och undrar om du vill ha mer av samma. Bortsett från dramatiken behöver Zorbin fler vattenelementarkärnor. Att etablera butiken här är en desperat affär, så det finns lite att ge i gengäld, men Zorbin lovar att berätta för alla inom hörhåll hur du hjälpte till och säger att du kan lita på det eftersom Zorbin känner folk i Cartel. Sex kärnor behövs. Ta dem från Sea Elementals och Sea Sprays på The Forgotten Coast och ta dem till Zorbin nära kajen."},{t="Zorbins tack",b="Zorbin är nöjd och medger att betalningen kanske inte är den högsta du någonsin får för ett sådant arbete. Zorbins kamrater i Steamwheedle Cartel får höra om dina insatser, och om du vill ha mer att göra behöver Zorbin fortfarande fler kärnor och liknande saker."}},faq={{q="Vem efterfrågar vattenelementarkärnorna?",a="Zorbin Fandazzle, som finns vid kajen på The Forgotten Coast i Feralas.",al={"vem ger uppdraget","vem är zorbin fandazzle","var finns zorbin"}},{q="Varifrån kommer vattenelementarkärnorna?",a="De tas från Sea Elementals och Sea Sprays på The Forgotten Coast i Feralas.",al={"var får man kärnor","plats för vattenelementarkärna","vilka fiender släpper kärnor"}},{q="Varför behöver Zorbin Fandazzle fler kärnor?",a="Zorbin säger bara att det behövs fler vattenelementarkärnor, samtidigt som Zorbin kämpar för att få en butik på plats vid kusten.",al={"varför vill zorbin ha kärnor","zorbin fandazzles motiv","vad används kärnorna till"}},{q="Vad hände före detta?",a="Det följer på Fuel for the Zapping, då du först samlade elementarkärnor åt Zorbin.",al={"föregående uppdrag","förutsättningsuppdrag","vilket uppdrag kommer först"}}},fp="22,224,16.533.0,15.258.1,44.76.0,45.84.0,42.100.0,22.84.0"}
P.entries["quest:7727"] = {n="Incendosaurs? Whateverosaur is More Like It",s="Hansel Heavyhands säger att hans liktornar har liktornar, och han kan inte döda något med fötterna i så bedrövligt skick. Scrange och Burninate bad honom rensa The Slag Pit från incendosaurs, så han skickar dig i stället för att döda tjugo.",h="Hansel Heavyhands säger att hans liktornar har liktornar, och han kan inte döda något med fötterna i så...",kw={"burninate","the cauldron","hansel heavyhands","incendosaur","scrange","searing gorge","the slag pit"},sec={{t="Liktornar på liktornar",b="Hansel Heavyhands är inte i skick att slåss. Scrange och Burninate bad honom döda incendosaurs så att expeditionsgrupper kan ta sig ner i The Slag Pits lavapölar och utforska dem. Hansel lämnar över arbetet till dig."},{t="Lavapölarna",b="Incendosaurs håller till i lavapölarna nere i The Slag Pit, inne i The Cauldron. Hansel vill att tjugo dödas och vill inte se dig igen förrän du har gjort det."}},faq={{q="Vem är Hansel Heavyhands?",a="Det är han som ger dig det här uppdraget i Searing Gorge. Scrange och Burninate bad honom ta hand om incendosaurs, men han kan inte på grund av sina liktornar.",al={"hansel heavyhands","vem ger uppdraget","vem ger det här uppdraget"}},{q="Varför behöver incendosaurs rensas bort?",a="Scrange och Burninate vill att expeditionsgrupper ska utforska The Slag Pits lavapölar. Det sägs att incendosaurs där orsakar alla möjliga problem.",al={"varför döda incendosaurs","incendosaurernas syfte","varför rensa the slag pit"}},{q="Var hittar man incendosaurs?",a="Nere i lavapölarna i The Slag Pit, inne i The Cauldron.",al={"incendosaurernas plats","var ligger the slag pit","var finns lavapölarna"}},{q="Varför jagar inte Hansel dem själv?",a="Han säger att hans liktornar har liktornar, och att fötterna är i alltför bedrövligt skick för att döda något.",al={"varför slåss inte hansel","hansels fötter","hansels liktornar"}}},fp="43,204,20.220.0,14.121.0,25.156.0,47.155.0,33.77.0,35.97.0"}
P.entries["quest:7728"] = {n="STOLEN: Smithing Tuyere and Lookout's Spyglass",s="En efterlysning gäller två stulna föremål: ett mörkt järnmunstycke och en Lookout's Spyglass. Thorium Brotherhood är säkra på att skrupelfria, avundsjuka Dark Iron-dvärgar från Searing Gorge tog dem, och den som hittar dem ska lämna dem till Taskmaster Scrange mot betalning.",h="En efterlysning gäller två stulna föremål: ett mörkt järnmunstycke och en Lookout's Spyglass.",kw={"dark iron","scrange","searing gorge","smide","kikare","thorium brotherhood","munstycke"},sec={{t="Stöldgods",b="Efterlysningen kallar kikaren ett fint redskap för utkikare och munstycket ett smidesredskap som inte kan ersättas. Det enda man vet är att Dark Iron-dvärgar definitivt tog dem. Den som hittar dem ska återlämna dem till Taskmaster Scrange."}},faq={{q="Vem satte upp efterlysningen?",a="Efterlysningen kommer från Thorium Brotherhood, som är säkra på att Dark Iron-dvärgar tog föremålen.",al={"vem vill ha de stulna föremålen","vem gav uppdraget","uppdragsgivare för stulet smidesmunstycke"}},{q="Vem stal redskapen?",a="Thorium Brotherhood är säkra på att det var skrupelfria och avundsjuka Dark Iron-dvärgar från Searing Gorge.",al={"vem tog munstycket","vem stal kikaren","vem har de stulna föremålen"}},{q="Vem ska få tillbaka föremålen?",a="Taskmaster Scrange i Searing Gorge.",al={"var lämnar jag in det här","vem är taskmaster scrange","vem får kikaren"}},{q="Vad används de stulna föremålen till?",a="Munstycket är ett smidesredskap som inte kan ersättas, och kikaren är ett värdefullt övervakningsredskap för utkikare.",al={"vad är ett smidesmunstycke","varför vill brödraskapet ha munstycket","vad gör kikaren"}}},fp="46,261,12.299.0,22.97.0,20.112.0,33.48.0,30.89.0"}
P.entries["quest:7729"] = {n="JOB OPPORTUNITY: Culling the Competition",s="En anslagstavla meddelar att Taskmaster Scrange söker dugliga arbetare som kan slå ut konkurrenterna i Searing Gorge. Arbetet går ut på att döda Dark Iron Taskmasters och Dark Iron Slavers tills kläderna är tillräckligt blodiga, och sedan återvända till Scrange.",h="En anslagstavla meddelar att Taskmaster Scrange söker dugliga arbetare som kan slå ut konkurrenterna i...",kw={"slå ut konkurrenterna","dark iron slaver","dark iron taskmaster","ledig tjänst","searing gorge","taskmaster scrange"},sec={{t="En ledig tjänst",b="Scrange vill att sökande ger sig ut genom ravinen och slaktar de Dark Iron Taskmasters och Dark Iron Slavers de stöter på: femton av varje. Kom tillbaka när kläderna är tillräckligt blodiga. Du märker när det är dags, och du ska inte fråga."}},faq={{q="Vem erbjuder det här jobbet?",a="Taskmaster Scrange i Searing Gorge, som vill ha hjälp med att slå ut konkurrenterna.",al={"vem erbjuder det här uppdraget","vem vill få taskmasters dödade","vem är taskmaster scrange"}},{q="Vilka fiender måste dödas?",a="Femton Dark Iron Taskmasters och femton Dark Iron Slavers.",al={"vad ska jag döda","mål för ledig tjänst","vilka är konkurrenterna"}},{q="Hur ser Scrange att arbetet är klart?",a="På klädernas skick. Scrange väger dig med och utan kläderna för att vara säker.",al={"hur bevisar jag dödandena","krav på blodiga kläder","hur kontrollerar scrange"}}},fp="40,95,16.211.0,25.75.0,28.65.0,39.96.0"}
P.entries["quest:773"] = {n="Rite of Wisdom",s="Visdomsriten är det avslutande provet i Jordemoderns traditionella riter, som unga äventyrare genomgår i Mulgore. Efter att ha renat sin syn genom Synsriten reser de sökande till Red Rocks heliga gravplats för att tala med en Ancestral Spirit och ta emot de dödas välsignelse.",h="Visdomsriten är det avslutande provet i Jordemoderns traditionella riter, som unga äventyrare genomgår i...",kw={"ancestral spirit","mulgore","red rocks","visdomsriten","jordemoderns riter","seer wiserunner","thunder bluff","water of the seers"},ang={["class:Druid"]="Riten visar balansen mellan de levandes värld och den eviga cykel som Jordemodern vakar över, och förankrar unga druider i deras plikt mot landet.",["class:Shaman"]="Att tala direkt med en Ancestral Spirit stärker den grundläggande shamanplikten att hedra de döda och hålla tron på andarna som vakar över Mulgore.",["race:Tauren"]="För shu'halo är det högtidliga ögonblicket då de tar emot ansvaret från förfäderna vid Red Rocks kulmen på övergången till vuxenlivet och på att bli accepterade bland stammens äldste."},sec={{t="Provet vid Red Rocks",b="Efter att ha klarnat sin varseblivning genom Synsriten skickas unga väktare öster om Thunder Bluff, mot Red Rocks. Denna uråldriga gravplats rymmer de fysiska kvarlevorna och de dröjande andarna efter dem som kämpade och dog för att skapa en fredlig tillvaro i Mulgore. För att klara provet måste du närma dig viloplatsen med vördnad och söka gemenskap, samtidigt som du möter de territoriella hot som strövar omkring i kullarna för att söka de ärade dödas råd."},{t="Att ta emot ansvaret",b="På toppen av Red Rocks är mötet med en Ancestral Spirit inte ett prov på stridsstyrka, utan på andlig beredskap och kontinuitet. Andarna som vilar där representerar den generation som kämpade sida vid sida med Cairne Bloodhoof för att grunda Thunder Bluff och skydda stammarna. Genom att ta emot deras välsignelse ärver den sökande officiellt den högtidliga plikten att skydda staden och förtjänar sin plats som erkänd vuxen och försvarare, värdig att stolt träda in i Thunder Bluff."}},faq={{q="Vad är syftet med Visdomsriten?",a="Visdomsriten fullbordar Jordemoderns riter och förenar ungdomens visionära gemenskap med vuxenlivets högtidliga ansvar. Genom att få förfädernas andars välsignelse visar de sökande att de respekterar föregångarnas uppoffringar och är redo att försvara Thunder Bluff.",al={"varför göra visdomsriten","vad gör visdomsriten","visdomsritens syfte"}},{q="Vem skickar dig på Visdomsriten?",a="Seer Wiserunner, i sin grotta nordväst om Bloodhoof Village, skickar iväg invigda på detta prov när de har klarat Synsriten och druckit av Water of the Seers.",al={"vem ger visdomsriten","var börjar jag visdomsriten"}},{q="Var hittar du Ancestral Spirit?",a="Ancestral Spirit finns vid Red Rocks, en uråldrig tauren-gravplats bland de klippiga höjderna rakt öster om Thunder Bluff.",al={"var finns ancestral spirit","var är anden","var hittar jag ancestral spirit"}},{q="Varför måste du först genomgå Synsriten?",a="Endast de som har druckit av Water of the Seers och fått sin andliga syn renad kan uppfatta och ta emot de uråldriga andarnas välsignelse vid Red Rocks.",al={"varför göra synsriten först","krav för synsriten","krav på water of the seers"}},{q="Vad händer när du har fullbordat Visdomsriten?",a="När de invigda har vunnit förfädernas godkännande får de instruktioner om att göra sin officiella färd till Thunder Bluffs höga höjder.",al={"vad händer efter visdomsriten","nästa uppdrag efter visdomsriten"}},{q="Vilka varelser hotar området vid Red Rocks?",a="Den heliga gravplatsen vid Red Rocks har trängts in på av aggressiva Palemane gnolls, som lurar längs de klippiga stigarna upp till den uråldriga gravplatsen.",al={"fiender vid red rocks","vad vaktar red rocks","gnolls vid red rocks"}}},fx={["740e2883"]={q="Varför skickar Seer Wiserunner dig på Visdomens rit?",a="Seer Wiserunner vägleder lovande unga taurer genom Earthmothers traditionella riter. Efter att ha sett dig uthärda synen från Water of the Seers skickar han dig till Red Rocks, där du kan få förfädernas välsignelse. För Wiserunner och de äldre säkerställer riten att endast de som är andligt redo och erkända av förfäderna välkomnas till Thunder Bluff som stammens beskyddare.",al={"seer wiserunners motiv","varför visdomens rit","varför skicka mig på visdomens rit"}},["8728f84f"]={q="Varför måste du gå i stället för att Seer Wiserunner går själv?",a="Visdomens rit är en personlig övergångsrit, inget ärende som någon annan kan utföra åt dig. För att vinna de äldres förtroende och rätten att gå in i Thunder Bluff måste du själv söka upp Ancestral Spirit vid Red Rocks och visa den andliga klarhet du fått från Water of the Seers. Uppdraget att skydda staden kan bara tilldelas dig direkt.",al={"varför jag på visdomens rit","varför går inte seer wiserunner själv","varför måste jag söka upp ancestral spirit"}}},fp="14,213,22.325.0,18.396.0,42.196.0,36.147.0,39.127.0,41.161.0,49.108.0,49.137.0"}
P.entries["quest:7730"] = {n="Zukk'ash Infestation",s="På Camp Mojache har Hadoken Swiftstrider hört talas om insektsliknande varelser, Zukk'ash, söder om gnollerna. Om de hetsar upp gnollerna till vansinne är de ett lika stort hot som gnollerna, kanske större. Du skickas in i deras hem, The Writhing Deep, för att minska deras antal och ta med tjugo ryggsköldar tillbaka.",h="På Camp Mojache har Hadoken Swiftstrider hört talas om insektsliknande varelser, Zukk'ash, söder om gnollerna.",kw={"camp mojache","ryggsköld","feralas","gnoller","hadoken swiftstrider","insekter","the writhing deep","zukk'ash"},sec={{t="Fienden söder om gnollerna",b="Hadoken Swiftstrider tror att fienden söder om gnollerna är en ras av insektsliknande varelser. Om de kan tänka spelar knappt någon roll för Hadoken. Om de driver gnollerna till vansinne mot Camp Mojache är de lika farliga som gnollerna själva, eller farligare. Du ska ta dig djupt in i deras tillhåll, som kallas The Writhing Deep, och minska deras antal. Tjugo Zukk'ash-ryggsköldar blir ditt bevis, och Hadoken vill höra vad du hittar."},{t="Hadokens dom",b="När du återvänder är Hadoken nöjd. Inget mindre än en fullskalig invasion kan få slut på Zukk'ash-närvaron, men du har gett lägret tid att utforma en ordentlig strategi. Ryggsköldarna ska analyseras, eftersom lägret måste lära sig allt om dessa varelser. Det här har tyvärr blivit ett mycket större problem än någon hade väntat sig."}},faq={{q="Vem skickar dig efter Zukk'ash?",a="Hadoken Swiftstrider, vid Camp Mojache i Feralas.",al={"uppdragsgivare","hadoken swiftstrider","vem startar zukk'ash infestation"}},{q="Vad är Zukk'ash?",a="Hadoken tror att de är en ras av insektsliknande varelser söder om gnollerna. Om de kan tänka spelar ingen roll för Hadoken, bara att de kanske driver gnollerna till vansinne.",al={"vad är zukk'ash","zukk'ash-insekter","insekter i the writhing deep"}},{q="Var ligger The Writhing Deep?",a="Det är där Zukk'ash-insekterna håller till, söder om gnollerna.",al={"the writhing deeps plats","var ligger the writhing deep","var finns insekterna"}},{q="Varför vill Hadoken ha Zukk'ash-ryggsköldar?",a="Hadoken vill ha ryggsköldarna som bevis på ditt arbete mot Zukk'ash.",al={"varför ryggsköldar","användning av zukk'ash-ryggsköld","ryggsköldarnas syfte"}}},fp="20,201,27.379.0,17.310.1,33.60.0,22.177.0,27.66.0,41.71.0"}
P.entries["quest:7731"] = {n="Stinglasher",s="Under spaningen av The Writhing Deep upptäckte en av Hadoken Swiftstriders spejare en jättelik insekt, långt större än de andra, som strövade omkring i den förvridna terrängen. Den har fått namnet Stinglasher, och Hadoken vill att du fäller den och för tillbaka dess sekretkörtlar till Camp Mojache.",h="Under spaningen av The Writhing Deep upptäckte en av Hadoken Swiftstriders spejare en jättelik insekt, långt...",kw={"camp mojache","feralas","körtlar","hadoken swiftstrider","insekt","stinglasher","the writhing deep","zukk'ash"},sec={{t="En jätte bland insekterna",b="En spejare i The Writhing Deep såg en insekt som var mycket större än de andra och strövade omkring i den förvridna terrängen. Den verkar också utstråla en aura som skiljer den från de andra. Den har fått namnet Stinglasher. Dess inälvor skulle vara ovärderliga att studera medan Hadoken kommer på hur det nya hotet ska hanteras, så Hadoken vill att du skär ut dess sekretkörtlar och för dem direkt till Camp Mojache."},{t="Hadokens tack",b="Hadoken är mycket imponerad. Om Stinglasher verkligen är en av de starkaste insekterna kommer det med tiden att bli värdefullt att studera besten, och Hadokens uppdrag är att se till att lägret försvarar sig tillräckligt länge för att dra nytta av det. En belöning i mynt ges, tillsammans med tack från hela lägret."}},faq={{q="Vem skickar dig efter Stinglasher?",a="Hadoken Swiftstrider, i Camp Mojache i Feralas.",al={"uppdragsgivare","vem ger stinglasher","hadoken swiftstrider"}},{q="Var hittar man Stinglasher?",a="Stinglasher strövar omkring i den förvridna terrängen i The Writhing Deep.",al={"stinglashers plats","var finns stinglasher","writhing deeps plats"}},{q="Vad skiljer Stinglasher från de andra insekterna?",a="En spejare rapporterade om en jättelik insekt, som verkar utstråla en aura som de andra saknar.",al={"varför stinglasher","vad är stinglasher","stinglashers aura"}},{q="Varför vill Hadoken ha Stingslashers körtlar?",a="Hadoken säger att det vore ovärderligt att studera dess inälvor medan en plan mot det nya hotet utarbetas.",al={"varför samla körtlar","stinglashers körtlar syfte"}}},fp="11,98,25.343.0,16.250.1,32.76.0,27.61.0,56.110.0,43.116.0"}
P.entries["quest:7732"] = {n="Zukk'ash Report",s="Hadoken Swiftstrider säger att du har gjort dubbelt så bra ifrån dig mot Zukk'ash-insekterna som hotar Camp Mojache, men faran är långt ifrån över. En sista tjänst för horden: ta med ett dokument med allt ni lärt er om Zukk'ash till Orgrimmar, till Zilzibin Drumlore.",h="Hadoken Swiftstrider säger att du har gjort dubbelt så bra ifrån dig mot Zukk'ash-insekterna som hotar Camp...",kw={"camp mojache","drag","feralas","hadoken swiftstrider","orgrimmar","silithider","zilzibin drumlore","zukk'ash report"},sec={{t="Ett dokument till Drag",b="Hadoken Swiftstrider har ett dokument som sammanfattar allt lägret lärt sig om Zukk'ash-insekterna. Faran de utgör är långt ifrån över, och Hadoken ber dig ta med det till Orgrimmar. Där, i Drag, bor Zilzibin Drumlore, en expert på främmande varelser som dessa, och Hadoken hoppas att kunskapen som samlats hittills kommer till nytta."},{t="Expertens dom",b="Zilzibin har väntat på rapporten. Han kallar varelserna du mötte för ett uråldrigt hot som horden gång på gång väljer att ignorera, och säger att Hadoken gjorde klokt i att skicka både rapporten och dig. Zukk'ash är inget annat än varelser som kallas silithider. Vissa tror att de är ett tanklöst irritationsmoment, men Zilzibin försäkrar dig om att de utgör ett mycket större hot än något Alliansen kan uppbåda."}},faq={{q="Vem skickar rapporten till Orgrimmar?",a="Hadoken Swiftstrider vid Camp Mojache i Feralas ger dig dokumentet.",al={"vem ger zukkashrapporten","vem startar zukkashrapporten","uppdragsgivare"}},{q="Till vem överlämnas rapporten?",a="Till Zilzibin Drumlore, som bor i Drag i Orgrimmar.",al={"vart går rapporten","vem får zukkashrapporten","drumlores plats"}},{q="Varför förs dokumentet till Orgrimmar?",a="Zilzibin Drumlore är expert på främmande varelser som Zukk'ash, och Hadoken hoppas att kunskapen som lägret samlat kommer till nytta.",al={"varför skicka till orgrimmar","rapportens syfte"}},{q="Vad hände före den här leveransen?",a="Den följer på dina insatser mot Zukk'ash-insekterna i Zukk'ash Infestation och Stinglasher.",al={"tidigare uppdrag","förkunskapskrav"}}},fp="15,192,23.293.0,20.336.1,34.71.0,32.80.0,39.127.0,31.103.0"}
P.entries["quest:7733"] = {n="Improved Quality",s="Pratt McGrubben har hört talas om ännu finare hudar än de senaste. I norra Feralas, inne i Rage Scar Hold, strövar en annan flock yetier, tuffare än dem du mötte tidigare. Tio av deras hudar behövs vid Feathermoon Stronghold.",h="Pratt McGrubben har hört talas om ännu finare hudar än de senaste.",kw={"feathermoon stronghold","feralas","improved quality","pratt mcgrubben","rage scar hold","thorium","yetihud","yetier"},sec={{t="En tuffare flock yetier",b="Efter The Mark of Quality har Pratt McGrubben fått ett tips om en ännu finare tillgång på hudar. I norra Feralas, inne i Rage Scar Hold, lever en annan flock yetier, tuffare än dem du mötte tidigare. Pratt McGrubben betalar generöst för tio av deras hudar, om du tar dem tillbaka till Feathermoon Stronghold så att saken kan avgöras. Om de håller samma kvalitet som hudarna från Feral Scar kan de visa sig vara lika tåliga som thorium."},{t="Pratts tack",b="Hudarna är ännu bättre än väntat. Pratt McGrubben kan redan se att de blir mycket hårdare när de har garvats ordentligt, och som tack ger han dig en av sina senaste skapelser."}},faq={{q="Vem efterfrågar hudar från Rage Scar-yetierna?",a="Pratt McGrubben, vid Feathermoon Stronghold i Feralas.",al={"vem ger improved quality","uppdragsgivare för improved quality","pratt mcgrubben"}},{q="Var lever Rage Scar-yetierna?",a="Inne i Rage Scar Hold, i norra Feralas.",al={"rage scar-yetiernas plats","var ligger rage scar hold","var får man tag på rage scar-hudar"}},{q="Hur många hudar behövs?",a="Pratt McGrubben vill ha tio hudar från Rage Scar-yetierna.",al={"hur många yetihudar","föremål som behövs för improved quality"}},{q="Vad kom före det här?",a="Det följer på The Mark of Quality, där du tog hand om den första flocken yetier.",al={"förutsättningsuppdrag","vilket uppdrag leder till improved quality","föregående uppdrag"}}},fp="16,134,25.303.0,14.171.1,38.87.0,34.67.0,26.47.0,22.80.0"}
P.entries["quest:7734"] = {n="Improved Quality",s="Jangdor Swiftstrider har hört talas om hudar som är ännu bättre än de förra. Längst uppe i norra Feralas, inne i Rage Scar Hold, strövar en annan flock yetier, tuffare än dem du mötte tidigare. Tio av deras hudar behövs i Camp Mojache.",h="Jangdor Swiftstrider har hört talas om hudar som är ännu bättre än de förra.",kw={"camp mojache","feralas","förbättrad kvalitet","jangdor swiftstrider","rage scar hold","rage scar-yeti","yetihudar"},sec={{t="En tuffare flock yetier",b="Efter The Mark of Quality har Jangdor Swiftstrider fått ett spår till en ännu finare tillgång på hudar. Längst uppe i norra Feralas, inne i Rage Scar Hold, lever en annan flock yetier, tuffare än dem du mötte tidigare. Jangdor Swiftstrider betalar bra för tio av deras hudar, om du tar med dem tillbaka till Camp Mojache och gör upp saken. Om de håller samma kvalitet som Feral Scar-hudarna kan de visa sig vara lika tåliga som thorium."},{t="Jangdors tack",b="Hudarna är ännu bättre än väntat. Jangdor Swiftstrider kan redan se att de blir mycket hårdare när de har garvats ordentligt, och som tack ger han dig ett av sina senaste alster."}},faq={{q="Vem efterfrågar Rage Scar-yetiernas hudar?",a="Jangdor Swiftstrider i Camp Mojache i Feralas.",al={"vem ger förbättrad kvalitet","uppdragsgivare för förbättrad kvalitet","jangdor swiftstrider"}},{q="Var lever Rage Scar-yetierna?",a="Inne i Rage Scar Hold, i norra Feralas.",al={"rage scar-yetiernas plats","var ligger rage scar hold","var får man tag på rage scar-hudar"}},{q="Hur många hudar behövs?",a="Jangdor Swiftstrider vill ha tio hudar från Rage Scar-yetier.",al={"hur många yetihudar","föremål som behövs för förbättrad kvalitet"}},{q="Vad hände före det här?",a="Det följer på The Mark of Quality, då du tog itu med den första flocken yetier.",al={"förutsättningsuppdrag","vilket uppdrag leder till förbättrad kvalitet","föregående uppdrag"}}},fp="16,101,25.287.0,16.172.1,38.82.0,34.68.0,26.52.0,22.78.0"}
P.entries["quest:7735"] = {n="Pristine Yeti Hide",s="Du har fått tag på ett yetiskinn som är ovanligt tjockt och segt, segare än något du sett från yetierna i Rage Scar. Pratt McGrubben vid Feathermoon Stronghold söker yetiskinn, och det här kan intressera honom.",h="Du har fått tag på ett yetiskinn som är ovanligt tjockt och segt, segare än något du sett från yetierna i...",kw={"feathermoon stronghold","feralas","pratt mcgrubben","orört yetiskinn","rage scar","yetiskinn"},sec={{t="Ett ovanligt skinn",b="Skinnet är orört och tydligt tjockare och kraftigare än skinnen från yetierna i Rage Scar. Pratt McGrubben vid Feathermoon Stronghold i Feralas vill köpa yetiskinn, så det här är värt att ta med till honom."},{t="Pratts reaktion",b="Pratt är häpen och undrar högt om det här kan vara det bästa yetiskinn som finns. Han betalar dig för det, mer än ett vanligt skinn brukar inbringa, och tror att något särskilt kan tillverkas av det."}},faq={{q="Vem vill ha det orörda yetiskinnet?",a="Pratt McGrubben vid Feathermoon Stronghold i Feralas, som vill köpa yetiskinn.",al={"vem tar emot orört yetiskinn","var ska jag lämna yetiskinnet","pratt mcgrubben yetiskinn"}},{q="Vad gör skinnet speciellt?",a="Det är ovanligt tjockt och segt, och överträffar till och med skinnen från yetierna i Rage Scar.",al={"var får man orört yetiskinn","vad gör skinnet speciellt","yetiskinn i feralas"}},{q="Var finns Pratt McGrubben?",a="Vid Feathermoon Stronghold i Feralas.",al={"var finns pratt mcgrubben","var lämnar man orört yetiskinn"}}},fp="18,147,26.188.0,16.174.1,33.82.0,29.82.0,25.56.0"}
P.entries["quest:7736"] = {n="Restoring Fiery Flux Supplies via Kingsblood",s="Efter What the Flux? vill Master Smith Burninate fylla på det sinande förrådet av Fiery Flux i Searing Gorge. Burninate vill ha incendosaur scales, Kingsblood och kol, och tar emot allt du kan erbjuda.",h="Efter What the Flux?",kw={"burninate","kol","fiery flux","incendosaur","kingsblood","searing gorge","thorium brotherhood"},sec={{t="Fiery Flux sökes",b="Master Smith Burninate har inte tid med tomt prat. Förrådet av Fiery Flux börjar sina, och Burninate ber om incendosaur scales, Kingsblood och kol: två scales, fyra Kingsblood och kol. Burninate tar emot allt du kan erbjuda."}},faq={{q="Vem ber om de här varorna?",a="Master Smith Burninate i Searing Gorge, som tar emot varorna personligen.",al={"vem ger det här uppdraget","burninate fiery flux","var lämnar man in"}},{q="Vilka material vill Burninate ha?",a="Två incendosaur scales, fyra Kingsblood och lite kol.",al={"vilka föremål behöver jag","material till fiery flux","föremål att lämna till burninate"}},{q="Vad kom före den här begäran?",a="Steget som heter What the Flux?, som Burninate gav dig tidigare.",al={"förutsättning för uppdraget","föregående uppdrag fiery flux","förutsättningen what the flux"}},{q="Varför vill Burninate ha de här varorna?",a="Burninate säger att förrådet av Fiery Flux sinar och vill fylla på det.",al={"varför fiery flux","burninates motiv"}}},fp="44,177,17.181.0,25.91.0,35.66.0,30.70.0,36.78.0"}
P.entries["quest:7738"] = {n="Perfect Yeti Hide",s="Du har hittat ett yetiskinn som mycket väl kan vara perfekt: ovanligt tjockt och slitstarkt, bättre än skinnen från yetierna i Rage Scar. Jangdor Swiftstrider på Camp Mojache letar efter yetiskinn.",h="Du har hittat ett yetiskinn som mycket väl kan vara perfekt: ovanligt tjockt och slitstarkt, bättre än...",kw={"camp mojache","feralas","jangdor swiftstrider","perfect yeti hide","rage scar","yetiskinn"},sec={{t="Ett skinn att visa upp",b="Skinnet är tydligt tjockare och tåligare än skinnen från yetierna i Rage Scar. Jangdor Swiftstrider på Camp Mojache i Feralas vill köpa yetiskinn, så det här är värt att ta dit."},{t="Jangdors omdöme",b="Jangdor blir överlycklig och kallar det det finaste yetiskinn han någonsin har sett. En passande belöning är på sin plats, mer än han brukar betala för ett enda skinn, och han är övertygad om att något särskilt kan tillverkas av det."}},faq={{q="Vem är intresserad av Perfect Yeti Hide?",a="Jangdor Swiftstrider på Camp Mojache i Feralas, som vill köpa yetiskinn.",al={"vem vill ha skinnet","vem lämnar in perfect yeti hide","jangdor yetiskinn"}},{q="Varför anses det här skinnet vara speciellt?",a="Det är ovanligt tjockt och slitstarkt och kan mycket väl vara perfekt, bättre än skinnen från yetierna i Rage Scar.",al={"varför är det perfekt","vad gör skinnet speciellt"}},{q="Var finns Jangdor Swiftstrider?",a="På Camp Mojache i Feralas.",al={"var finns jangdor swiftstrider","vart ska perfect yeti hide tas"}}},fp="17,163,20.175.0,17.177.1,43.72.0,36.92.0,30.51.0"}
P.entries["quest:775"] = {n="Journey into Thunder Bluff",s="Journey into Thunder Bluff är den avslutande pilgrimsfärden som markerar slutet på en ung hjältes prövningar i Mulgore. Efter att ha fullgjort Earthmothers heliga riter under andarnas ledning får äventyraren audiens hos taurenfolkets överhövding, Cairne Bloodhoof.",h="Journey into Thunder Bluff är den avslutande pilgrimsfärden som markerar slutet på en ung hjältes prövningar...",kw={"ancestral spirit","cairne bloodhoof","high rise","journey into thunder bluff","mulgore","earthmothers riter","thunder bluff"},ang={["faction:Horde"]="Att tauren gärna välkomnar allierade folk som fullgör deras heliga traditioner visar på den ömsesidiga respekten som håller det unga Horde samman.",["race:Tauren"]="För en ung tauren är stunden framför Cairne Bloodhoof efter Earthmothers riter den avgörande tröskeln till vuxenlivet och stamheder."},sec={{t="En avslutad övergångsrit",b="Innan någon resenär eller ung krigare kan hävda att de har bevisat sitt värde i Mulgore måste de genomgå Earthmothers uråldriga riter. Prövningarna sätter styrka, syn och visdom på prov över slätterna och vid landets förfädersplatser. När Ancestral Spirit har bekräftat den sista riten anses initianden värdig att träda in i Thunder Bluff, inte som en vanlig besökare utan som en hedrad försvarare av taurenfolket."},{t="Upp till High Rise",b="Uppdraget leder resenären från den heliga mark där andarna vandrar rakt till Thunder Bluffs höga höjder. Staden ligger på mesas och är en fredens fyr, uthuggen ur röd sten och sammanbunden av svepande repbroar och väldiga träplattformshissar. Där väntar taurenfolkets överhövding, Cairne Bloodhoof, på High Rise för att personligen välkomna dem som har vandrat förfädernas väg."}},faq={{q="Vem skickar dig på den här resan?",a="Du får uppdraget av en Ancestral Spirit efter att du har fullgjort Rite of Wisdom, det sista steget i Earthmothers traditionella riter.",al={"vem ger uppdraget","uppdrag från ancestral spirit","uppdragsgivare"}},{q="Var hittar jag Cairne Bloodhoof?",a="Cairne Bloodhoof finns på High Rise, den centrala upphöjda mesan i Thunder Bluff, med utsikt över de omgivande röda platåerna och slätterna.",al={"var finns cairne","var är cairne","ledare i thunder bluff"}},{q="Vad innebär det att fullgöra det här uppdraget?",a="Det markerar den formella avslutningen på startäventyren i Mulgore. När du visar dig för Cairne blir du erkänd av taurenfolkets ledning och redo att ta dig an uppgifter för hela Horde.",al={"varför besöka cairne","riternas betydelse","betydelsen av resan till thunder bluff"}},{q="Är det bara tauren som genomför den här resan?",a="Även om det är en djupt traditionell övergångsrit för tauren får alla medlemmar i Horde som visar sin hängivenhet genom Earthmothers riter samma ära och skickas för att träffa överhövdingen.",al={"kan orcher göra detta","vem kan göra resan till thunder bluff","folk"}},{q="Vad händer när jag har talat med Cairne?",a="Cairne välkomnar dig till sitt hem, erkänner dina bedrifter och visar vägen vidare in i de större konflikter som Horde står inför i Kalimdor.",al={"nästa uppdrag","vad händer efter cairne","efter journey into thunder bluff"}},{q="Hur tar man sig till High Rise i Thunder Bluff?",a="Ta de stora mekaniska hissarna från slätterna nedanför upp till mesorna. Gå sedan över rep- och träbroarna mot den centrala plattformen på High Rise, där överhövdingens hydda står.",al={"ta sig till high rise","hur tar man sig till cairne","hissar i thunder bluff"}}},fx={["74afb15b"]={q="Varför skickar Ancestral Spirit dig till Thunder Bluff?",a="Genom att överleva prövningarna i Mulgore och tala med andarna har du visat din visdom, styrka och hängivenhet genom Earthmothers riter. Ancestral Spirit skickar dig till Thunder Bluff så att taurerna och deras högste ledare, Cairne Bloodhoof, kan erkänna dina gärningar. Att stå inför högstamledaren markerar att du formellt välkomnas in i deras samhälle som en hedrad förkämpe.",al={"varför skickar ancestral spirit dig","ancestral spirits motiv","varför gå till cairne"}},c86a41a9={q="Varför måste du själv överlämna budskapet till Cairne Bloodhoof?",a="Earthmothers riter är en helig, personlig prövning. Ancestral Spirit är en andevarelse som är bunden till Mulgore heliga marker och varken kan eller vill bära budskap från den jordiska världen. Eftersom det var din ande och beslutsamhet som prövades tillhör äran att själv möta högstamledaren Cairne Bloodhoof enbart dig.",al={"varför jag till cairne","varför måste jag besöka cairne","varför måste jag träffa cairne bloodhoof"}}},fp="26,152,27.307.0,26.303.0,30.128.0,34.111.0,50.174.0,37.205.0,38.135.0,48.183.0"}
P.entries["quest:776"] = {n="Rites of the Earthmother",s="Den här prövningen, som High Chieftain Cairne Bloodhoof själv har utsett, låter blivande hjältar spåra upp den väldiga kodon Arra'chea över Mulgore slätter. Även om en novis redan har genomgått de traditionella övergångsriterna, förväntar sig Cairne att hans folk ständigt visar sin styrka, spårningsförmåga och hängivenhet till stammen på nytt. Att återvända med Arra'cheas horn visar att en äventyrare är redo att tjäna den större Horde bortom mesas högplatåer.",h="Den här prövningen, som High Chieftain Cairne Bloodhoof själv har utsett, låter blivande hjältar spåra upp...",kw={"arra'chea","bloodhoof","cairne","earthmother","horn","jakt","kodo","mulgore","thunder bluff"},ang={["class:Hunter"]="Att smyga sig på en ensam, vandrande koloss som Arra'chea över de gyllene slätterna förkroppsligar de uråldriga jaktfilosofier som taurenfolkets spårmästare för vidare genom generationerna.",["faction:Horde"]="När Arra'chea fälls får Thunder Bluff viktig föda, läder och material. Det visar den gemensamma överlevnadsanda som håller den unga Horde vid liv.",["race:Tauren"]="Att stå inför Cairne Bloodhoof och göra anspråk på Arra'cheas horn är den yttersta övergångsriten för en ung shu'halo och bevisar att din skicklighet hedrar både dina förfäder och Mulgore hjordar."},sec={{t="En hövdings måttstock",b="Att nå Thunder Bluff markerar slutet på en taurenungdoms enkla dagar, men High Chieftain Cairne Bloodhoof låter inte unga jägare vila på lagrarna. För Cairne är det bara början på ansvaret för United Tauren Tribes att förtjäna en plats bland de höga klipporna. I stället för att skicka noviser mot obetydliga skadedjur kräver han bevis på verklig fältvana: att spåra upp och ta till vara på ett av Mulgore mest berömda vandrande djur."},{t="Jakten på Arra'chea",b="Bytet är Arra'chea, en enorm och legendarisk kodo vars vindlande vandring går över de gyllene grässlätterna nordost om Thunder Bluff. Att fälla en sådan varelse kräver mer än råstyrka; det kräver tålmodig smygjakt över den öppna savannen och respekt för slätternas titan. Att föra Arra'cheas horn tillbaka till High Rise ger inte bara personlig ära, utan också förnödenheter åt staden, eftersom Cairne genast skickar ut flåare och samlare så att inget av det heliga djuret går till spillo."}},faq={{q="Vem ger det här uppdraget?",a="High Chieftain Cairne Bloodhoof själv ger dig uppdraget från sin plats högst upp på Thunder Bluffs höga klippor.",al={"uppdragsgivare","vem ger rites of the earthmother","cairnes uppdrag"}},{q="Vad är Arra'chea?",a="Arra'chea är en respektingivande och berömd kodo som strövar över Mulgore slätter. Hans väldiga horn bevisar en jägares spårningsförmåga och stridsduglighet.",al={"vem är arra'chea","vad är arra'chea","arra'cheas bakgrund"}},{q="Var hittar jag Arra'chea?",a="Arra'chea strövar vanligtvis längs en vid cirkelbana nordost om Thunder Bluffs klippor och går långsamt medurs runt de öppna, böljande slätterna.",al={"var finns arra'chea","arra'cheas plats","arra'cheas väg"}},{q="Varför ber Cairne mig jaga den här varelsen när jag redan har genomfört de tidigare riterna?",a="I taurenkulturen är den första platsen man förtjänar inte slutet på ens plikter. Cairne lär ut att styrka, ödmjukhet och jaktförmåga måste visas gång på gång för att stammen ska bestå.",al={"varför göra uppdraget","varför döda arra'chea","syftet med riterna"}},{q="Vad händer med Arra'cheas kropp när hornet har tagits?",a="För att följa taurenfolkets tradition att hedra sitt byte skickar Cairne ut en insamlingsgrupp som hämtar köttet och skinnet från det fällda djuret, så att bytet ger Thunder Bluff mat och kläder.",al={"arra'cheas kött","vad händer med kodon","kadaverets bakgrund"}},{q="Är det här samma uppdrag som de tidiga nybörjarriterna?",a="Nej. De tidiga prövningarna i Camp Narache lär en novis grunderna i Rites of the Earthmother, medan den avslutande prövningen i Thunder Bluff är Cairnes personliga test av ditt fortsatta värde som jägare.",al={"skillnader mellan rites of the earthmother","vilket uppdrag med riterna","camp narache-riterna"}}},fx={d7a516d7={q="Vad ska Horn of Arra'chea användas till?",a="Hornet är ett fysiskt bevis på att du lyckats med jakten. Taurernas tradition sätter stor ära i konsten att spåra och fälla mäktiga bestar. När du överlämnar Arra'cheas horn direkt till högstamledaren Cairne Bloodhoof visar du att du har skickligheten som krävs för att försörja och skydda ditt folk.",al={"vad horn of arra'chea används till","varför ta med arra'cheas horn","syftet med horn of arra'chea"}},a7e696eb={q="Varför skickar Cairne Bloodhoof dig i stället för stadsvakterna?",a="Den här jakten är ingen försvarsuppgift eller enkel insamling av resurser. Den är en traditionell prövning. Du kan ha klarat Earthmothers första riter för att nå Thunder Bluff, men Cairne förväntar sig att varje jägare i stammen fortsätter bevisa sitt värde och sin självständighet genom stordåd, i stället för att luta sig mot tidigare meriter.",al={"varför skicka mig","varför inte skicka vakterna efter arra'chea","varför behöver cairne mig"}}},fp="24,265,21.386.0,22.362.0,21.97.0,18.127.0,27.110.0,78.161.0,57.165.0,50.188.0"}
P.entries["quest:777"] = {n="This Is Going to Be Hard",s="Lucien Tosselwrench ger dig kugghjul nummer fem till Lotwil Veriatus och går i skydd, med en inbjudan att följa med.",h="Lucien Tosselwrench ger dig kugghjul nummer fem till Lotwil Veriatus och går i skydd, med en inbjudan att...",kw={"badlands","kugghjul fem","lotwil veriatus","lucien tosselwrench","bojor","det här blir svårt"},sec={{t="I skydd",b="Lucien räcker över kugghjulet och säger att du ska ta det till Lotwil Veriatus. Lucien väntar i skydd och du är välkommen att följa med. När du når Lotwil, som fortfarande böjer sig över bojorna, sträcks en hand fram och fingrarna vinkar otåligt efter kugghjulet."},{t="Skapar historia",b="Lotwil tar kugghjulet och säger att det är perfekt. Lotwil ber dig att ställa dig åt sidan medan förberedelserna görs för att skapa mer historia. Lotwil fortsätter arbeta febrilt."}},faq={{q="Vem lämnar över kugghjulet till Lotwil?",a="Lucien Tosselwrench ger dig kugghjul nummer fem att ta till Lotwil Veriatus.",al={"vem ger kugghjulet","var får jag kugghjul fem","lucien kugghjul"}},{q="Vart går Lucien?",a="Lucien går i skydd och säger att du är välkommen att följa med.",al={"varför gömmer sig lucien","lucien skydd"}},{q="Vad gör Lotwil när du kommer med kugghjulet?",a="Lotwil arbetar med en uppsättning bojor och sträcker otåligt fram handen efter kugghjulet utan att titta upp.",al={"vad gör lotwil","lotwil bojor","lotwils framsteg"}}},fp="24,82,12.250.0,14.145.1,34.65.0,21.55.0,44.130.0"}
P.entries["quest:778"] = {n="This Is Going to Be Hard",s="Lotwil Veriatus förklarar bojorna färdiga och ber Lucien, Servo och dig att bevittna hur en mäktig elementarvarelse kallas fram.",h="Lotwil Veriatus förklarar bojorna färdiga och ber Lucien, Servo och dig att bevittna hur en mäktig...",kw={"badlands","elementarvarelse","fam'retor guardian","lotwil veriatus","lucien","servo","shackles of elemental binding"},sec={{t="En banbrytande dag",b="Lotwil ropar att bojorna är klara och att tiden är inne, och kallar Lucien och Servo att bevittna det tillsammans med dig. Lotwil beskriver bojorna som alkemi, ingenjörskonst och det mystiska i perfekt förening, och tänker kalla fram en mäktig elementarvarelse under vad som utropas till en banbrytande dag för alla där."},{t="Efter framkallningen",b="Resultatet blir inte som Lotwil väntat sig, och Lotwil ber dig hämta Shackles of Elemental Binding när Fam'retor Guardian har besegrats. Efteråt är Lotwil osäker på vad som gick fel, men glad att magierna fanns till hands för att återföra varelsen till planet den kom ifrån."}},faq={{q="Vem är Lotwil Veriatus?",a="Lotwil Veriatus har tillverkat Shackles of Elemental Binding, där alkemi, ingenjörskonst och det mystiska kombineras. Lucien och Servo är där tillsammans med Lotwil i Badlands.",al={"vem är lotwil","lotwil veriatus"}},{q="Vad är Shackles of Elemental Binding?",a="Det är bojorna som Lotwil just har färdigställt, en kombination av alkemi, ingenjörskonst och det mystiska, avsedda för en mäktig elementarvarelse som Lotwil tänker kalla fram.",al={"vad är bojorna","shackles of elemental binding"}},{q="Vilka kallar Lotwil till att bevittna det?",a="Lotwil kallar Lucien och Servo att bevittna framkallningen tillsammans med dig.",al={"vem är lucien","vem är servo"}},{q="Vad kommer före det här steget?",a="Det följer på steget där du tog med cog #5 till Lotwil.",al={"föregående uppdrag","vad ledde hit"}}},fp="24,73,20.272.0,19.273.1,23.149.0,43.155.0,37.67.0,28.42.0"}
P.entries["quest:7781"] = {n="The Lord of Blackrock",s="Nefarians avhuggna huvud förs till Stormwind Keep efter hans nederlag i Blackwing Lair. Highlord Bolvar Fordragon tar emot trofén, ett tecken på att härskaren över Blackrock Mountain har fallit. Segern är en av Alliansens största militära triumfer i mannaminne.",h="Nefarians avhuggna huvud förs till Stormwind Keep efter hans nederlag i Blackwing Lair.",kw={"blackrock mountain","blackwing lair","highlord bolvar fordragon","head of nefarian","lord of blackrock","nefarian","stormwind keep"},ang={["faction:Alliance"]="För Alliansen är överlämnandet av Nefarians huvud en krönande militär bedrift. Det krossar drakflockens planer mot människornas länder.",["race:Human"]="Som människa vet du att Blackrock Mountain har skickat otaliga intrång och ränker mot Stormwind. Härskarens nederlag ger riket den hämnd och lättnad det länge har väntat på."},sec={{t="Ett segermonument",b="Nefarian, yngelmästare över Black Dragonflight och härskare över Upper Blackrock Spire, har länge hotat de omgivande människorikena. Hans nederlag sätter stopp för hans förvridna experiment och planer. När hans stridssargade huvud förs tillbaka till Stormwind blir det ett bevis på att Alliansens största hjältar har besegrat Lord of Blackrock."},{t="Audiens i Stormwind Keep",b="Highlord Bolvar Fordragon styr riket från tronsalen i Stormwind Keep. Drakens avhuggna huvud chockerar det kungliga hovet och inger vördnad. Riket är pressat av inre politiska stridigheter och hot utifrån, och segern stärker moralen och får en plats i Alliansens historia."}},faq={{q="Vad handlar uppdraget Lord of Blackrock om?",a="Du tar Nefarians avhuggna huvud i Blackwing Lair och bär trofén till Stormwind City. Där överlämnar du det till Highlord Bolvar Fordragon för rikets räkning.",al={"uppdraget lord of blackrock","nefarian huvud uppdrag alliansen","head of nefarian stormwind"}},{q="Vem är Nefarian?",a="Nefarian är en mäktig svart drake och son till Deathwing. Han härskar från Blackwing Lair i Blackrock Mountain, för befäl över orcherna i Blackrock och utför ondskefulla experiment för att skapa den kromatiska drakflocken.",al={"vem är nefarian","lord of blackrock","nefarian historia"}},{q="Vem är Highlord Bolvar Fordragon?",a="Highlord Bolvar Fordragon är paladinen som styr Stormwind som regent medan kung Varian Wrynn är borta. Han håller hov i tronsalen i Stormwind Keep och vakar över den unge prins Anduin Wrynn.",al={"bolvar fordragon","vem är bolvar","highlord bolvar"}},{q="Varför förs trofén till Stormwind Keep?",a="Nefarians herravälde i Blackrock Mountain hotar Stormwind och hela den södra kontinenten. När hans huvud förs till rikets militära ledning bekräftas drakens nederlag, och folket får en seger att samlas kring.",al={"varför stormwind","varför föra huvudet till keep","varför bolvar"}},{q="Vad händer när huvudet har överlämnats till Bolvar?",a="Highlord Bolvar Fordragon blir häpen och förklarar att triumfen ska skrivas in i historien. Nästa del av händelsen innebär att huvudet sätts upp offentligt så att alla i Stormwind kan se det.",al={"vad händer sedan","lord of blackrock del två","överlämna nefarian huvud"}},{q="Påverkar överlämnandet av huvudet hela staden?",a="Ja. Nefarians huvud förs till huvudstaden och sätts upp ovanför stadsportarna. Det tillkännager drakens död för invånare och soldater och stärker Stormwinds försvarare med beslutsamhet.",al={"stadsvälsignelse","stridsrop","head of nefarian välsignelse"}}},fx={["150c64a2"]={q="Varför är det viktigt att föra Head of Nefarian till Stormwind?",a="Nefarian var den svarta drake som låg bakom hoten från Blackrock Spire, manipulerade dödliga riken och skapade monstruösa arméer alldeles intill Stormwind. När du överlämnar hans avhuggna huvud till Highlord Bolvar Fordragon bevisar du utan tvivel att draksläktets terror är krossad. Alliansen får en monumental seger att fira och visa upp inför riket.",al={"varför föra head of nefarian till stormwind","head of nefarians betydelse","varför överlämna nefarians huvud"}},["7e2ee731"]={q="Varför måste du bära huvudet till Stormwind i stället för de kungliga vakterna?",a="Du och dina följeslagare kämpade er igenom Blackwing Lair och fällde själva drakherren. Som förkämparna som besegrade honom har ni rätt att föra det makabra bytet tillbaka till Stormwind Keep. Då får Highlord Bolvar Fordragon höra nyheten direkt från hjältarna som faktiskt dödade besten.",al={"varför måste jag överlämna nefarians huvud","varför inte kungliga vakter med nefarians huvud","varför jag med nefarians trofé"}}},fp="21,264,21.326.0,26.287.0,42.168.0,16.211.0,33.197.0,45.214.0,45.152.0,48.190.0"}
P.entries["quest:7782"] = {n="The Lord of Blackrock",s="Vid Stormwinds portar samlas Alliansen för att fira segern över Blackrock. När du har rapporterat till Grand Admiral Jes-Tereth i Stormwind Keep beger sig hjältarna till Valley of Heroes, där Field Marshal Stonebridge förbereder en offentlig högtid för staden.",h="Vid Stormwinds portar samlas Alliansen för att fira segern över Blackrock.",kw={"blackrock","drakdräpare","nefarian","samlande rop","stonebridge","stormwind","valley of heroes"},ang={["class:Warrior"]="Dragonslayerns samlande rop ger styrka åt kämpar som ger sig av för att försvara riket.",["faction:Alliance"]="Nefarians huvud i Valley of Heroes förenar Alliansens raser. Invånare från Ironforge, Darnassus och Gnomeregan ser att de mörka krafter som plågar Eastern Kingdoms kan besegras.",["race:Human"]="För Stormwinds kungarike undanröjer besegrandet av Blackrocks härskare ett allvarligt drakhot vid den norra gränsen."},sec={{t="En stads triumf",b="Alliansens fälttåg mot Blackrock-klanen och den svarta drakflygelns avkomma når sitt offentliga slut. När Nefarians avhuggna huvud har visats upp inne i Stormwind Keep skickar Highlord Bolvar Fordragon mästarna genom staden till Valley of Heroes. Där väntar Field Marshal Stonebridge på att ta emot trofén och inleda firandet."},{t="Alliansen samlas",b="Field Marshal Stonebridge höjer Nefarians avhuggna huvud över de stora valven vid Stormwinds huvudingång. Hela staden ser det, och Dragonslayerns samlande rop inger försvararna, de besökande dignitärerna och invånarna mod. De vet att Deathwings avkomma har lidit ett förkrossande nederlag."}},faq={{q="Vad händer när du slutför det här uppdraget?",a="Field Marshal Stonebridge hänger Nefarians avhuggna huvud högt på stenvalvet vid Valley of Heroes. Dragonslayerns samlande rop stärker sedan vänligt sinnade kämpar och vakter i hela Stormwind City.",al={"lämna in uppdraget med nefarianhuvudet","vad gör stonebridge","utlöser det samlande ropet"}},{q="Vem är Field Marshal Stonebridge?",a="Field Marshal Stonebridge är en högt uppsatt officer i Stormwinds armé, stationerad i Valley of Heroes nära stadens ingång. Hon ordnar offentliga högtider för att fira militära segrar, bland annat genom att visa upp besegrade drakfienders huvuden.",al={"stonebridge","field marshal stonebridge"}},{q="Varför skickar Highlord Bolvar Fordragon dig hit?",a="När Highlord Bolvar Fordragon får besked om Nefarians nederlag i tronsalen skickar han dig till stadsportarna. Där kan Alliansens militär visa upp segern öppet och höja stridsmoralen i huvudstaden.",al={"bolvar","varför gå till valley of heroes"}},{q="Påverkar inlämningen hela staden?",a="Ja. När Stonebridge tar emot trofén ljuder en kungörelse genom Stormwind, och Dragonslayerns samlande rop når alla inom stadens gränser.",al={"nefarian-världsförstärkning","får stormwind en förstärkning"}},{q="Var ligger Valley of Heroes?",a="Valley of Heroes är den storslagna väg som leder in i Stormwind City. Väldiga statyer kantar den och hedrar hjältarna från Andra kriget som gick genom The Dark Portal.",al={"var ligger valley of heroes","var finns stonebridge"}},{q="Vem var ”Blackrocks herre”?",a="Den svarta draken Nefarian var Blackrocks herre. Han är Deathwings son och härskar över de övre spirorna på Blackrock Mountain.",al={"vem är blackrocks herre","nefarian identitet"}}},fx={["3a42f3f3"]={q="Varför skickar Bolvar dig i stället för att gå själv?",a="Du och dina följeslagare var förkämparna som trotsade höjderna i Blackwing Lair och fällde Nefarian. Som segrare är det med rätta du som får äran att överlämna drakens avhuggna huvud till Stormwinds militära ledning och sätta igång stadens firande.",al={"varför skicka mig","varför inte bolvar","varför måste jag överlämna huvudet"}}},fp="21,261,16.338.1,21.299.0,42.221.1,33.240.0,49.213.1,40.162.1,38.164.0,32.124.2"}
P.entries["quest:7783"] = {n="The Lord of Blackrock",s="Nefarians avhuggna huvud förs från Blackrock Mountain till Orgrimmar som bevis på segern. Det överlämnas till krigshövding Thrall och markerar att en mäktig fiende till Horden har fallit.",h="Nefarians avhuggna huvud förs från Blackrock Mountain till Orgrimmar som bevis på segern.",kw={"blackrock","blackwing lair","deathwing","drakdödare","thrall","nefarian","orgrimmar","rallying cry"},ang={["class:Warrior"]="För dig som krigare är det ett stort bevis på krigarära att bära en drakhärskares väldiga, avhuggna skalle till krigshövdingen.",["faction:Horde"]="Nefarians fall återupprättar Hordens heder och befriar Blackrock-regionen från draken som förslavade den avfälliga Dark Horde.",["race:Orc"]="För dig som orch innebär det hämnd att överlämna Nefarians huvud till Thrall, efter bestens manipulation av Rend Blackhand och förslavning av orchklanerna för sina experiment."},sec={{t="En trofé av förödelse",b="Nefarian har äntligen fallit. Han låg bakom Blackwing Lair och ledde den svarta drakflocken i Eastern Kingdoms. Hans väldiga, stridsärrade huvud bevisar att han är död. För Hordens krigare innebär det stor ära att föra trofén från Blackrock Mountains brinnande höjder över Stora havet till Durotar."},{t="Krigshövdingens dom",b="Trofén förs fram till krigshövding Thrall. Han känner väl till Blackrock Mountains fördärv. Han befriade sitt folk från interneringslägren och ledde dem bort från den gamla Hordens demoniska blodtörst. Deathwings son har fallit, och orcherna i Blackrock är fria från den mörka drakens grymma herravälde."},{t="Faderns skuggor",b="Nefarians död sätter stopp för den svarta drakflyktens förvridna experiment, men faran kvarstår. När Thrall ser drakens avhuggna huvud säger han att Deathwing säkert rör på sig när han får höra om sin sons undergång. Segern är verklig, och ännu större fasor sover fortfarande under världen."}},faq={{q="Vem är Nefarian?",a="Nefarian är en mäktig svart drake och Deathwings son. Från sitt näste på toppen av Blackrock Mountain utförde han förvridna experiment för att skapa den kromatiska drakflykten och manipulerade dödliga raser, särskilt Dark Horde, så att de gjorde hans vilja.",al={"nefarian bakgrund","vem är nefarian","svart drakhärskare"}},{q="Varför överlämnas trofén till Thrall?",a="Thrall är Hordens krigshövding. Han ledde orcherna ut ur interneringslägren och bort från den gamla Hordens demoniska blodtörst. Därför hör beviset på att draken som förslavade orcherna i Blackrock och Dark Horde har fallit hemma i hans händer.",al={"varför thrall","vem får huvudet"}},{q="Vad händer i Orgrimmar när huvudet lämnas in?",a="När Nefarians huvud återförs och sätts upp i Orgrimmar firar staden. Hordens medlemmar i närheten av huvudstaden får Drakdödarens stridsrop, som stärker deras stridsförmåga.",al={"huvudets förstärkning","orgrimmar världsbonus","rallying cry-bonus"}},{q="Har uppdraget en motsvarighet för Alliansen?",a="Ja. Alliansens hjältar överlämnar Nefarians huvud till Highlord Bolvar Fordragon i Stormwind Keep, vilket ger deras stad samma välsignelse.",al={"alliansens version","motsvarighet för alliansen"}},{q="Varför är Deathwing ett bekymmer?",a="Deathwing är Nefarians far och överhuvud för Black Dragonflight. Att besegra hans son undanröjer inte faran från drakfadern.",al={"den onde rör på sig","vem är den onde"}},{q="Var kommer huvudet ifrån?",a="Head of Nefarian tas från Nefarians lik på toppen av Blackwing Lair efter att han har besegrats.",al={"hur får man tag på head of nefarian","uppdragsstartföremål"}}},fx={d14146dc={q="Varför måste Head of Nefarian föras till Orgrimmar?",a="När du hugger loss det väldiga, stridsärrade huvudet från den fallna draken får du ett obestridligt bevis på att Blackrock Spires härskare har besegrats. Att föra denna monstruösa trofé tillbaka till Orgrimmar visar Hordens överlägsna styrka, firar en monumental seger över Black Dragonflight och låter krigschefens råd bekräfta att Nefarians förvridna experiment i berget äntligen har upphört.",al={"varför föra nefarians huvud","head of nefarians betydelse","varför ge huvudet till eitrigg"}}},fp="21,141,16.296.0,23.303.0,21.263.1,16.248.0,38.235.0,53.181.0,44.129.0,27.147.0,30.106.0"}
P.entries["quest:7784"] = {n="The Lord of Blackrock",s="I Orgrimmar förs Nefarians avhuggna huvud fram inför Horden. När Thrall bekräftar att den svarta draken är död skickar han segraren till High Overlord Saurfang i Valley of Strength, så att alla får se trofén.",h="I Orgrimmar förs Nefarians avhuggna huvud fram inför Horden.",kw={"blackwing lair","thrall","head of nefarian","saurfang","orgrimmar","nefarian","valley of strength"},ang={["faction:Horde"]="För Horden bevisar den offentliga visningen av Nefarian den reformerade Hordens styrka mot den svarta draken som manipulerade orcherna i Blackrock Mountain. Den stärker Thralls nya ordning.",["race:Orc"]="Som orch kan du känna en djup lättnad när draken som höll Blackrock-klanen i sitt våld faller. Hans nederlag lyfter en vanärande skugga från ditt folk."},sec={{t="En trofé åt horden",b="Nefarians huvud når Orgrimmar efter att den svarta draken har dödats högst upp i Blackwing Lair. Hövding Thrall bekräftar att Deathwings son har fallit och skickar sedan segraren till High Overlord Saurfang i Valley of Strength. Där förbereds kvarlevorna för offentlig visning, som en varning till fienderna och en stridsrop för den sanna Horden."},{t="Göra anspråk på arvet",b="Nefarian härskade över Blackrock Mountains höjder och tvingade Blackrock-orcherna och Dark Horde att lyda honom. Genom att fälla honom och höja hans huvud i Valley of Strength utdelar Thralls Horde ett hårt slag mot Black Dragonflight. Saurfang uppmanar hela Orgrimmar att jubla åt Rallying Cry of the Dragonslayer."}},faq={{q="Vad är syftet med uppdraget?",a="När du har bevisat för Thrall att Nefarian är död rapporterar du till High Overlord Saurfang i Orgrimmars Valley of Strength. Det avhuggna huvudet visas upp offentligt och du hedras.",al={"vad gör uppdraget","överlämning av lord of blackrock","varför gå till saurfang"}},{q="Vem är High Overlord Saurfang?",a="High Overlord Saurfang är en veteran bland orchkrigare och en av Hordens största mästare. Han är stationerad i Orgrimmars Valley of Strength, där han tar emot huvudet och låter montera det så att alla kan se det.",al={"vem är saurfang","high overlord saurfangs roll"}},{q="Varför visas Nefarians huvud upp?",a="Nefarians monterade huvud bevisar att härskaren över Blackrock Mountain har fallit. Visningen stärker moralen hos Orgrimmars försvarare, och alla i staden får Rallying Cry of the Dragonslayer.",al={"varför sätta upp nefarian huvud","nefarian huvud visas upp orgrimmar"}},{q="Vem var Nefarian?",a="Nefarian var en mäktig svart drake och son till Deathwing. Från Blackwing Lair högst upp på Blackrock Mountain styrde han Blackrock-orcherna och Dark Horde och avlade fram den kromatiska drakflocken.",al={"vem var nefarian","nefarian berättelse"}},{q="Var finns High Overlord Saurfang?",a="Saurfang finns i Valley of Strength, Orgrimmars centrala entrédistrikt.",al={"var finns saurfang","saurfangs plats"}},{q="Vilken roll spelar Thrall här?",a="Hövding Thrall tar först emot Nefarians huvud. När han har bekräftat att draken är död skickar han dig till Saurfang för att låta montera trofén officiellt.",al={"varför thrall","thralls inblandning"}}},fp="21,219,22.320.0,19.328.1,34.182.0,30.203.0,38.203.0,17.190.0,40.77.0,35.148.0"}
P.entries["quest:7792"] = {n="A Donation of Wool",s="I Darnassus samlas ylletyg in för att fylla på stadens förråd. Dina sextio tygstycken ger dig erkännande för din generositet.",h="I Darnassus samlas ylletyg in för att fylla på stadens förråd.",kw={"darnassus","donation","erkännande","förråd","ylle","ylletyg"},sec={{t="Förråd av ylletyg",b="Darnassus behöver sextio stycken ylletyg från dig. Andra runt om i riket förväntas stå för resten av förråden. Din donation ger dig fullt erkännande för din generositet."}},faq={{q="Vad behöver Darnassus?",a="Darnassus behöver ylletyg för att fylla på sina förråd.",al={"ylledonation","vilket tyg vill darnassus ha"}},{q="Hur mycket ylletyg behöver jag donera?",a="Du behöver donera sextio stycken ylletyg.",al={"hur många ylletyg","sextio ylletyg"}},{q="Varför samlar Darnassus in ylletyg?",a="Darnassus samlar in ylletyg för att fylla på sina förråd.",al={"varför ylletyg","ylleinsamling"}},{q="Vad får jag för att donera ylletyg?",a="Din donation av sextio tygstycken ger dig fullt erkännande från Darnassus för din generositet.",al={"erkännande för ylledonation","belöning för att donera ylletyg"}}},fp="18,122,11.182.0,25.49.0,34.46.0,33.56.0,32.88.0"}
P.entries["quest:78"] = {n="The Legend of Stalvan",s="Det här uppdraget blir en vändpunkt i avslöjandet av Stalvan Mistmantles historia och för utredarna från Elwynn Forest tillbaka till den skuggiga staden Darkshire. Med hjälp av Marshal Haggards minnen från tjänstgöringen tar du med en återfunnen dagbokssida till Tavernkeep Smitts på Scarlet Raven Tavern för att identifiera den kusliga handstilen.",h="Det här uppdraget blir en vändpunkt i avslöjandet av Stalvan Mistmantles historia och för utredarna från...",kw={"darkshire","duskwood","elwynn","dagbok","marshal haggard","mistmantle","scarlet raven tavern","stalvan","tavernkeep smitts"},ang={["faction:Alliance"]="Uppdraget visar de starka banden mellan rikets forna försvarare och knyter samman pensionerade vakter från Stormwind med samhällsbärare runt om i Kingdom of Stormwind.",["race:Human"]="Det här steget blottar de mörka minnen som gömmer sig i mänskliga bosättningar och visar hur tidigare tragedier i Elwynn och Darkshire vägrar förbli begravda."},sec={{t="Ett spår från Marshal",b="Efter att ha återfunnit en sliten, trasig dagbokssida i Marshal Haggards kista i Elwynn Forest kan den pensionerade befälhavaren inte läsa den bleknade skriften på grund av sin sviktande syn. Haggard inser att spåret leder tillbaka över floden och minns hur han tidigare ledde Stormwind Guard. Han minns också kvällarna på Scarlet Raven Tavern i Darkshire. Han hänvisar dig till Tavernkeep Smitts, en krögare vars långa tjänstgöring har gjort honom till en inofficiell väktare av lokal historia och rykten."},{t="Tillbaka till Scarlet Raven",b="När du tar dig tillbaka genom Duskwoods dystra skogar visar du det bleknade manuskriptet för Smitts bakom disken. Smitts mjuknar genast när han hör namnet på sin gamle bekant Haggard, men beklagar veteranens sviktande hälsa. När krögaren får syn på pergamentet försvinner hans sorglösa uppsyn genast och ersätts av oro. Han känner igen den särpräglade handstilen utan minsta tvivel, och utredningen kommer allt närmare den fasansfulla sanningen om Stalvans vansinne."}},faq={{q="Varför skickar Marshal Haggard mig tillbaka till Darkshire?",a="Marshal Haggard börjar bli gammal och är nästan blind, så han kan inte själv undersöka den återfunna dagbokssidan. Han minns att Tavernkeep Smitts på Scarlet Raven Tavern kunde mycket om lokal historia och traditioner när Haggard tjänstgjorde i Stormwind Guard. Därför är Smitts den perfekta personen att identifiera handstilen.",al={"varför åka till darkshire","haggard till darkshire","varför smitts"}},{q="Var finns Tavernkeep Smitts?",a="Tavernkeep Smitts sköter baren på Scarlet Raven Tavern, som ligger på östra sidan av Darkshire i Duskwood.",al={"var är smitts","smitts plats","scarlet raven tavern plats"}},{q="Vilket föremål har du med dig till Tavernkeep Smitts?",a="Du tar med en A Faded Journal Page, ett utdrag ur Stalvan Mistmantles försvunna dagbok som tidigare hittades inlåst i Marshal Haggards fotkista.",al={"vilket föremål","bleknad dagbokssida","stalvans dagbokssida"}},{q="Känner Tavernkeep Smitts igen handstilen?",a="Ja. Så snart Smitts granskar den bleknade sidan känner han igen handstilen och blir tydligt orolig. Hans igenkänning ger sökandet efter Stalvan ett nytt spår.",al={"känner smitts igen handstilen","smitts reaktion på dagboken"}},{q="Hur känner Smitts Marshal Haggard?",a="Smitts tog emot Haggard för många år sedan, när Haggard ledde patruller från Stormwind Guard in i Duskwood och ofta besökte Scarlet Raven Tavern för att ta sig en drink.",al={"smitts och haggards relation","hur smitts känner haggard"}},{q="Vad händer härnäst i sökandet efter Stalvan?",a="Ta den bleknade dagbokssidan till Smitts på Scarlet Raven Tavern och följ spåret han ger dig.",al={"vad händer härnäst","nästa steg för stalvan","fortsättning på stalvans uppdragskedja"}}},fx={bf062962={q="Varför vill Marshal Haggard att det här ska göras?",a="Marshal Haggard kan inte läsa den blekta dagbokssidan eftersom synen sviktar. Han minns Tavernkeep Smitts som en gammal bekant med stor kunskap om lokal historia och ber dig ta sidan till honom i Darkshire.",al={"varför vill haggard få detta gjort","marshal haggards motiv","varför hjälpa till att hitta stalvan"}},c297959a={q="Varför skickar Marshal Haggard dig i stället för att gå själv?",a="Haggard är en gammal, pensionerad marskalk som lever isolerat och snabbt förlorar synen. Vägarna genom skogarna är farliga, och han saknar helt enkelt ungdomen och orken att ta sig över gränsen till Duskwood. Han förlitar sig på att en kapabel resenär som du uträttar hans ärende och visar dagbokssidan för hans gamla bekant.",al={"varför kan inte haggard gå","varför behöver haggard mig","varför besöker inte haggard smitts"}}},fp="21,112,23.409.0,27.374.1,51.223.0,35.110.0,44.133.0,49.131.0,37.136.0,42.99.0"}
P.entries["quest:780"] = {n="The Battleboars",s="The Battleboars är en jakt som markerar övergången till vuxenlivet och som Grull Hawkwind ger i Camp Narache. Unga taurer får i uppgift att hålla efter de grymma, krigstränade vildsvinen i Brambleblade Ravine för att försvara stammens marker och ge bosättningens unga mat.",h="The Battleboars är en jakt som markerar övergången till vuxenlivet och som Grull Hawkwind ger i Camp Narache.",kw={"stridsvildsvin","brambleblade ravine","bristleback","camp narache","grull hawkwind","mulgore","quilboar","red cloud mesa"},ang={["class:Hunter"]="När unga jägare möter bestar som Bristlebacks tränat för att sprida ondska lär de sig se den skarpa skillnaden mellan vilda djur och djur som förvandlats till krigsvapen.",["profession:Cooking"]="Begäran om flanker och trynen visar taurernas grundläggande matfilosofi: grovt och segt kött kan alltid kokas ner till mustiga, mättande grytor.",["race:Tauren"]="Uppdraget visar hur taurerna balanserar försvaret av Jordmoderns områden med att se till att inget som tas i strid går till spillo. Fiendens krigsdjur blir till mat åt lägrets kalvar."},sec={{t="Ett hot vid gränsen",b="Öster om Red Cloud Mesa ligger Brambleblade Ravine, en törnsnårig ravin som hålls av Bristleback quilboar. När spänningarna mellan Shu'halo och quilboar övergår i öppet krig har Bristlebacks tränat grymma stridsvildsvin att känna av taurernas gränser och terrorisera deras traditionella jaktmarker. Om de lämnas åt sig själva hotar dessa aggressiva bestar inte bara jaktstigarna utan även säkerheten i Camp Narache."},{t="Mat åt stammen",b="För taurerna fyller jakten både ett försvarsbehov och ett behov av gemensam försörjning. Grull Hawkwind instruerar de invigda att ta med trynen och flankerna från de fällda stridsvildsvinen. Inte ens bestar som tränats av quilboar går till spillo; köttet och brosket tas till vara för att laga mustig gryta åt stammens unga. På så vis blir ett quilboar-vapen till näring för nästa generation tauriska försvarare."}},faq={{q="Varför anfaller stridsvildsvinen mesan?",a="Stridsvildsvinen har medvetet fötts upp och tränats av Bristleback quilboar som bor i Brambleblade Ravine. Quilboar använder dem som anfallsdjur för att trakassera taurerna och tränga in på Red Cloud Mesas stammars jaktmarker.",al={"stridsvildsvinens aggressivitet","varför är stridsvildsvin fientliga","stridsvildsvin anfaller"}},{q="Vem skickar ut spelarna på den här jakten?",a="Grull Hawkwind, en framstående jägare och äldre som är stationerad i Camp Narache, leder unga taurer genom de avslutande proven i deras tidiga träning.",al={"uppdragsgivare för stridsvildsvinen","vem ger uppdraget the battleboars","grull hawkwinds roll"}},{q="Var hittar man stridsvildsvinen?",a="De strövar omkring nära och inne i Brambleblade Ravine, en oländig kanjon strax öster om Camp Narache vid Red Cloud Mesas östra kant.",al={"stridsvildsvinens plats","var finns stridsvildsvin","vildsvin i brambleblade ravine"}},{q="Vad händer med köttet från vildsvinen?",a="Stridsvildsvinens flanker och trynen tas tillbaka till Camp Narache och får sjuda till gryta åt bosättningens barn och äldre. På så vis följer man taurernas tradition att ta till vara på allt som jagas.",al={"vad används stridsvildsvinens flanker till","vad används vildsvinsköttet till","vildvinsgryta"}},{q="Hur passar uppdraget in i den lokala konflikten med quilboar?",a="Uppdraget är en tidig introduktion till det öppna kriget mellan taurerna och Bristleback-stammen. Genom att hålla efter deras krigsdjur minskar antalet bestar som trakasserar taurernas jaktmarker, och Bristlebacks i Brambleblade Ravine får ett tydligt budskap.",al={"kriget mellan taurer och quilboar","konflikten med bristleback","quilboars historia"}},{q="Vilket uppdrag kommer före The Battleboars?",a="Före det kommer The Hunt Continues, ett tidigare uppdrag från Grull Hawkwind som går ut på att lära känna Red Cloud Mesas jaktmarker.",al={"förutsättning för the battleboars","föregående uppdrag till the battleboars","the hunt continues uppdragskedja"}}},fx={b70ec92c={q="Varför vill Grull Hawkwind att stridsgaltarna dödas?",a="Stridsgaltarna har trängt ut från Brambleblade Ravine och in på Red Cloud-stammens urgamla jaktmarker. De har fötts upp och tränats till att vara våldsamma av Bristleback quilboar, och deras ökande aggressivitet hotar Camp Narache direkt. Grull Hawkwind tänker ge quilboar ett tydligt besked genom att minska deras krigsbestånd och samtidigt göra jakten till mat åt stammens unga.",al={"varför vill grull hawkwind döda stridsgaltar","grull hawkwinds motiv för stridsgaltarna","varför döda stridsgaltar i mulgore"}},["58a19c3f"]={q="Vad är stridsgaltar?",a="Stridsgaltar är vildsinta bestar som Bristleback quilboar föder upp och tränar i Brambleblade Ravine. Till skillnad från de vilda bergspumorna och slättlöparna som hör hemma på Red Cloud Mesa har de här galtarna medvetet tränats för krig och ondska. De fungerar som levande vapen i Bristlebacks pågående kamp mot taurerna.",al={"vilka är stridsgaltarna","vad är stridsgaltar","stridsgaltarnas bakgrund"}}},fp="15,95,22.329.0,17.340.0,43.182.0,31.117.0,32.113.0,50.140.0,57.224.0,36.114.0"}
P.entries["quest:7802"] = {n="A Donation of Wool",s="I Ironforge hjälper ulldonationer till att fylla förråden. Sextio stycken ger dig fullt erkännande för din generositet.",h="I Ironforge hjälper ulldonationer till att fylla förråden.",kw={"donation","ironforge","erkännande","sextio stycken","förråd","ull","ylletyg"},ang={["faction:Alliance"]="Som resenär i Alliance får du erkännande från Ironforge för din donation av ull."},sec={{t="Ullförråd",b="Ironforge ber dig om sextio stycken ylletyg. Förråden behöver bara så mycket från dig. Andra förväntas ge tillräckligt för att stödja insamlingen."}},faq={{q="Hur mycket ull behöver Ironforge från mig?",a="Sextio stycken ylletyg till Ironforge.",al={"mängd ull att donera","hur mycket ull","sextio ull"}},{q="Vad får jag för att donera ull?",a="Ge Ironforge sextio stycken ylletyg, så får du fullt erkännande för din generositet.",al={"belöning för ulldonation","vad får man för ull","erkännande från ironforge"}},{q="Varför samlar Ironforge in ull?",a="Ironforge samlar in ylletyg för att fylla på sina förråd.",al={"ullinsamling","varför donera ull","ironforge ull"}}},fp="18,110,11.148.0,42.42.0,32.93.0,33.51.0"}
P.entries["quest:7807"] = {n="A Donation of Wool",s="A Donation of Wool är en materialbeställning som Gnomeregan Exiles har ordnat för att samla in viktiga textilier. De landsförvisade gnomerna har förlorat sin teknologiskt avancerade hemstad och förlitar sig på sextio stycken ylletyg från generösa äventyrare runtom i riket för att hålla sitt samhälle vid liv. Den som bidrar får formellt erkännande bland gnomernas flyktingar.",h="A Donation of Wool är en materialbeställning som Gnomeregan Exiles har ordnat för att samla in viktiga...",kw={"tyginsamling","a donation of wool","gnom","gnomeregan","gnomeregan exiles","textilier","ylletyg"},ang={["faction:Alliance"]="När du bidrar med råmaterial till de landsförvisade gnomerna stärker du solidariteten inom alliansen och hjälper till att försörja en viktig allierad som fördrivits från sitt hem i bergen.",["profession:Tailoring"]="Skräddare som samlar in eller väver ylletyg har gott om textilier som flyktingar desperat behöver till grundläggande kläder och förnödenheter.",["race:Gnome"]="När du samlar in ylle hjälper du dina fördrivna släktingar bland gnomerna att fylla på förråden medan de försöker överleva och återuppbygga utanför Gnomeregan."},sec={{t="Ett fördrivet folks behov",b="Efter att Gnomeregan föll för trogginvasion och radioaktiv förorening fördrevs de överlevande gnomerna från sin högteknologiska metropol. Som flyktingar får de främst husrum hos sina dvärgkusiner i Ironforge, men Gnomeregan Exiles har stora logistiska svårigheter. Återkommande insamlingar av basvaror som tyg är viktiga för att hålla folket klätt, försett med förnödenheter och organiserat medan de överlever utanför sina förfäders hallar."},{t="Textilinsamlingen",b="För att undvika att enskilda välgörare belastas för hårt ber insamlingens organisatörer varje frivillig att bidra med exakt sextio stycken ylletyg. Genom att samla in mindre bidrag från hela riket kan de landsförvisade få ihop de stora mängder textilier som behövs till sängkläder, bandage och kläder utan att lägga en ohållbar börda på en enskild leverantör. Som tack erbjuder gnomerna formellt erkännande bland sitt folk till alla som vill hjälpa till med återuppbyggnaden."}},faq={{q="Varför behöver Gnomeregan Exiles ylletyg?",a="Gnomeregan Exiles samlar in resurser för att bygga upp ett grundlager av textilier. Efter att ha drivits bort från sin hemstad behöver folket viktiga material som ylletyg för att försörja flyktingarna och hålla verksamheten igång.",al={"varför ylle","vad används ylle till","syftet med yllebidraget"}},{q="Hur mycket ylletyg behövs?",a="Insamlingen ber varje bidragsgivare skänka sextio stycken ylletyg vid ett enda tillfälle. Organisatörerna räknar med att få in denna mängd från givare runtom i riket för att täcka det övergripande behovet.",al={"hur mycket ylle","bidragsmängd","behövt ylle"}},{q="Vem organiserar insamlingen?",a="Representanter för Gnomeregan Exiles samordnar textilinsamlingen och tar emot bidrag för de fördrivna gnomerna som nu får skydd hos sina allierade.",al={"vem tar emot bidraget","vem tar emot ylle","bidragsmottagare"}},{q="Kan du skänka ylletyg mer än en gång?",a="Beställningen begränsas till ett enda bidrag på sextio stycken från varje givare. De landsförvisade uppger att deras förråd just nu bara behöver den mängden från dig, eftersom de förlitar sig på en större grupp bidragsgivare runtom i riket för att nå sin kvot.",al={"kan jag bidra igen","kan uppdraget upprepas","fler yllebidrag"}},{q="Vilket erkännande erbjuder Gnomeregan Exiles?",a="Om du bidrar med sextio stycken ylle får du fullt erkännande och tacksamhet från Gnomeregan Exiles. Det visar din lojalitet och ditt stöd till deras fördrivna folk under en kris.",al={"anseende hos gnomeregan exiles","gnomernas anseende","erkännande för de landsförvisade"}},{q="Varför är gnomerna landsförvisade?",a="Gnomerna tvingades fly från sitt underjordiska hem Gnomeregan efter en katastrof och en trogginvasion. Nu är de beroende av tillfälliga läger, hjälp från allierade och materialinsamlingar medan de lever som flyktingar.",al={"varför är gnomerna landsförvisade","var ligger gnomeregan","gnomernas flyktingkris"}}},fp="18,211,26.391.0,17.324.0,45.176.0,30.151.0,38.142.0,41.163.0,48.163.0,38.192.0"}
P.entries["quest:781"] = {n="Attack on Camp Narache",s="Attack on Camp Narache är en viktig upptäckt i quilboarernas håla i Brambleblade Ravine. En smutsfläckad karta avslöjar att den aggressiva Bristleback-stammen planerar en samordnad belägring av Camp Narache. När planerna överlämnas till Chief Hawkwind får Camp Narache tid att kalla på hjälp från Bloodhoof Village.",h="Attack on Camp Narache är en viktig upptäckt i quilboarernas håla i Brambleblade Ravine.",kw={"attackplaner","bloodhoof village","brambleblade ravine","bristleback","camp narache","chief hawkwind","dirt-stained map","quilboar","red cloud mesa"},ang={["faction:Horde"]="Om tauren behåller sitt fäste i Mulgore kan Horde bevara sitt viktiga södra fäste i centrala Kalimdor.",["race:Tauren"]="För unga taurenkrigare som genomför sina första riter på platån visar du din lojalitet mot stammen genom att stoppa den här kartan, och skyddar dina fränder från en plötslig massaker."},sec={{t="En plan bland snåren",b="När unga taurenäventyrare spanar djupt inne i grottorna i Brambleblade Ravine hittar de en grov, smutsfläckad karta på klippgolvet. Vid närmare granskning visar pergamentet taktiska markeringar som Bristleback-quilboarerna gjort med avsikt. Quilboarerna nöjer sig inte med enstaka plundringståg, utan samordnar en fullskalig, långvarig belägring av Camp Narache."},{t="Varna hövdingen",b="När attackplanerna förs tillbaka till Camp Narache får Chief Hawkwind viktig information. Han inser vilket allvarligt hot det relativt försvarslösa lägret och dess unga lärlingar står inför och förbereder sig på att skicka bud till Bloodhoof Village efter förstärkningar. Den beslagtagna kartan förvandlar ett möjligt katastrofalt bakhåll till ett försvar man är beredd på."}},faq={{q="Var hittar man Bristleback-attackplanerna?",a="Planerna finns på en smutsfläckad karta inne i en grotta i Brambleblade Ravine, strax uppför stigen till höger om Chief Sharptusks hydda.",al={"kartans plats","var finns dirt-stained map","hitta planerna"}},{q="Vem tar emot Bristleback-attackplanerna?",a="Planerna ska överlämnas direkt till Chief Hawkwind mitt i Camp Narache.",al={"vem ska få planerna","vem får kartan","uppdragets slutperson"}},{q="Varför anfaller Bristleback-quilboarerna Camp Narache?",a="Bristleback-stammen vill driva bort tauren från Red Cloud Mesa och återta Mulgore:s jaktmarker och heliga slätter åt sitt eget folk.",al={"varför anfalla camp narache","quilboarernas motiv i mulgore","bristleback-belägring"}},{q="Hur tänker Chief Hawkwind stoppa belägringen?",a="Tack vare förvarningen från den beslagtagna kartan tänker Chief Hawkwind kalla på sina fränder i Bloodhoof Village för att förstärka platån och slå tillbaka anfallet.",al={"hawkwinds plan","förstärkningar till camp narache"}},{q="Måste man prata med någon innan man hämtar kartan i uppdraget?",a="Nej. Uppdraget börjar direkt vid Dirt-stained Map på grottgolvet i Brambleblade Ravine. När du hämtar den blir den till attackplanerna.",al={"uppdragets start","dirt-stained map som uppdragsstart","hur startar man attack on camp narache"}},{q="Vad händer om Camp Narache faller?",a="Camp Narache är den främsta tillflyktsorten för unga taurenkrigare och deras övergångsriter. Om lägret går förlorat äventyras säkerheten på Red Cloud Mesa och Mulgore förlorar sina andliga träningsmarker.",al={"vad står på spel vid camp narache","varför försvara narache"}}},fp="22,166,22.212.0,21.257.0,45.146.0,42.83.0,56.143.0,50.133.0,69.125.0,35.180.0"}
P.entries["quest:7810"] = {n="Arena Master",s="Finns det mer i att bemästra arenan än så här? Short John Mithril, piraten bakom Gurubashi-evenemanget, kanske har svaret. Du hittar honom i Stranglethorn Arena.",h="Finns det mer i att bemästra arenan än så här?",kw={"arenamästare","gurubashi","pirat","short john mithril","stranglethorn arena","stranglethorn vale"},sec={{t="På jakt efter piraten",b="Vad du än har vunnit i Gurubashi verkar det krävas mer för att bemästra arenan. Short John Mithril, piraten som ordnar tävlingarna där, kanske vet vad. Leta efter honom i Stranglethorn Arena."},{t="Short Johns ord",b="Short John Mithril säger att en enda prydnadssak inte räcker för att göra dig till arenans mästare. Nu, säger han, är det dags att verkligen pröva din styrka."}},faq={{q="Vem ska jag prata med?",a="Short John Mithril, piraten bakom Gurubashi-evenemanget.",al={"vem ska jag prata med","lämna in arenamästare","vart ska jag gå"}},{q="Var finns Short John Mithril?",a="I Stranglethorn Arena, vid Gurubashi i Stranglethorn Vale.",al={"gurubashi plats","var ligger stranglethorn arena","arenans plats"}},{q="Vad antyds om att bli arenans mästare?",a="Bara att det verkar krävas mer för att bemästra arenan än vad du har gjort hittills, och att piraten bakom Gurubashi-evenemanget kanske vet.",al={"hur blir jag arenamästare","är jag arenamästare än"}}},fp="12,98,18.190.0,17.123.1,28.69.0,28.86.0,47.158.0"}
P.entries["quest:78124"] = {n="Nar'thalas Almanac",s="Nar'thalas Almanac är ett sällsynt akademiskt manuskript om forntida magiska studier, eftertraktat av arkivarier som vill utöka bibliotekets samling. När volymen återbördas hamnar förlorad arkan kunskap i trygga händer, där forskare kan studera dess bortglömda insikter.",h="Nar'thalas Almanac är ett sällsynt akademiskt manuskript om forntida magiska studier, eftertraktat av...",kw={"almanacka","arkan","bok","bibliotek","magiska verk","nar'thalas","narthalas","skrift"},ang={["class:Mage"]="Magiker förstår det enorma akademiska värdet i återfunna texter om forntida arkana traditioner, vilket gör bidrag till bibliotekets magiska samling särskilt betydelsefulla.",["faction:Alliance"]="Lärda och kuratorer vid Alliansens arkiv förlitar sig på företagsamma äventyrare som söker upp sällsynta manuskript och utökar rikets samlade kunskap.",["race:NightElf"]="Nar'thalas var en gång ett forntida centrum för kaldorei-forskning om arkan magi, innan Sunderingen krossade den gamla världen. En almanacka med det namnet blir därmed en gripande länk till nattalvernas forntida historia."},sec={{t="En relik från forntida studier",b="Nar'thalas Almanac är en sällsynt skrift om arkan forskning med rötter i nattalvernas uråldriga lärdomstraditioner från tiden före Sunderingen. För dem som förvaltar stora arkiv innebär det att säkra en sådan text att rädda århundraden av kunskap från glömskan och ge hyllorna ett viktigt historiskt verk. Äventyrare som finner dessa länge försummade skrifter hjälper till att överbrygga klyftan mellan bortglömd forntid och modern akademisk förståelse."},{t="Utöka arkiven",b="Arkivarier och forskare söker ständigt efter förlorade avhandlingar, fältanteckningar och krönikor som skingrats över Azeroth. Om Nar'thalas Almanac förs till ett bibliotek som tar hand om den, kan den bevaras, katalogiseras och studeras i stället för att lämnas att förfalla bland ruiner eller hamna i vårdslösa händer. Varje räddad volym ger lärda nya insikter i gångna tiders arkan konst."}},faq={{q="Vad är Nar'thalas Almanac?",a="Nar'thalas Almanac är ett forntida manuskript om magisk lärdom som kuratorer söker för att berika ett biblioteks historiska arkiv. Äventyrare som återfinner sådana sällsynta verk överlämnar dem till lärda, så att deras bevarade insikter kan katalogiseras.",al={"vad är nar'thalas almanac","uppdraget nar'thalas almanac","information om almanackan"}},{q="Vem samlar in Nar'thalas Almanac?",a="Almanackan överlämnas till bibliotekets lärda, som intresserar sig för forntida magiska texter och historiska arkiv. Dessa kuratorer söker aktivt efter tillskott som utökar den gemensamma kunskapen om världens arkana arv.",al={"vem vill ha almanackan","vart ska almanackan","lämna in almanackan"}},{q="Vad syftar namnet Nar'thalas på?",a="Nar'thalas var ett forntida kaldorei-center för lärdom och magiska studier, grundat före den Stora Sunderingen. Bevarade texter med anknytning till namnet utgör fragment av förgrunderingens arkanism och alviska kunskap.",al={"vad är nar'thalas","nar'thalas historia","var ligger nar'thalas"}},{q="Varför samlas magiska texter in till biblioteket?",a="Många historiska dokument och magiska avhandlingar har förskingrats, gått förlorade eller begravts i ruiner över Azeroth. Lärda förlitar sig på återfunna skrifter för att bredda sin förståelse av arkana strömmar och skydda ömtåliga dokument från att gå helt förlorade.",al={"varför samla magiska verk","bibliotekets syfte","varför böcker är viktiga"}},{q="Kan andra magiska verk föras till biblioteket?",a="Lärda välkomnar alla återfunna avhandlingar, verk eller bortglömda manuskript som kastar ljus över arkan teori och forntida historia. De söker ständigt efter tillskott som kan berika hyllorna.",al={"fler magiska böcker","andra verk","fler texter"}},{q="Är Nar'thalas Almanac farlig att hantera?",a="Almanackan är en sammanställning av studier, inte en oberäknelig förbjuden artefakt. Den fungerar främst som ett värdefullt uppslagsverk för historiker och utövare som studerar historisk magi.",al={"är almanackan farlig","har almanackan mörk magi","säker att läsa"}}},fp="18,153,24.370.0,22.342.0,31.226.0,41.195.0,39.191.0,54.236.0,50.157.0,46.162.0"}
P.entries["quest:78127"] = {n="The Dalaran Digest",s="Bibliotekarien ber dig att ta med magiska verk till samlingen. Varje bok tillför kunskap till biblioteket.",h="Bibliotekarien ber dig att ta med magiska verk till samlingen.",kw={"samling","dalaran digest","kunskap","bibliotekarie","bibliotek","magiska verk"},sec={{t="Samlingen",b="Bibliotekarien välkomnar magiska verk som kan vara till nytta för biblioteket. Du tar med en bok till samlingen och bidrar därmed till bibliotekets växande kunskap."}},faq={{q="Vad vill bibliotekarien ha?",a="Bibliotekarien ber dig att ta med magiska verk som kan vara till nytta för samlingen.",al={"vad ska tas med","biblioteksbok","magiska verk"}},{q="Vart ska jag ta boken?",a="Ta boken till bibliotekarien som bad dig att lägga till den i samlingen.",al={"var finns bibliotekarien","bibliotekets plats"}},{q="Varför samlar bibliotekarien på magiska verk?",a="Ditt bidrag tillför mer kunskap till samlingen.",al={"varför samla böcker","bibliotekets syfte"}}},fp="18,106,14.135.0,29.78.0,26.74.0,46.58.0"}
P.entries["quest:78142"] = {n="Bewitchments and Glamours",s="I Ironforge söker biblioteket magiska skrifter till sina hyllor. Du kan hjälpa dess förvaltare att bredda sina kunskaper genom att lämna in böcker som kan berika samlingen.",h="I Ironforge söker biblioteket magiska skrifter till sina hyllor.",kw={"bewitchments and glamours","böcker","samling","ironforge","bibliotek","magiska skrifter"},sec={{t="En växande samling",b="Lämna in magiska skrifter till biblioteket i Ironforge, där varje tillskott kan bredda förvaltarnas kunskaper."}},faq={{q="Vad vill biblioteket ha?",a="Biblioteket söker magiska skrifter som kan berika dess samling.",al={"vad vill de ha","biblioteksböcker","magiska skrifter"}},{q="Var ska jag lämna in de magiska skrifterna?",a="Lämna in de magiska skrifterna till biblioteket i Ironforge.",al={"var lämna in böcker","var ligger biblioteket","ironforge bibliotek"}},{q="Varför samlar de på magiska skrifter?",a="Biblioteket säger att skrifterna kommer att utöka dess kunskaper.",al={"varför samla magiska böcker","vad är samlingen till för"}}},fp="25,168,20.103.0,27.64.0,35.52.0,38.53.0"}
P.entries["quest:78143"] = {n="Secrets of the Dreamers",s="Secrets of the Dreamers ger äventyrare i uppdrag att återfinna sällsynta magiska skrifter som kan berika forskarnas arkiv. Genom att lämna in dessa avhandlingar hjälper upptäcktsresande bibliotekets lärda att utöka samlingen av forntida kunskap.",h="Secrets of the Dreamers ger äventyrare i uppdrag att återfinna sällsynta magiska skrifter som kan berika...",kw={"magisk","dreamers","bibliotek","magiska verk","lärda","secrets of the dreamers","böcker"},ang={["class:Druid"]="Med tanke på hänvisningen till Dreamers har skrifter knutna till naturmagi och The Emerald Dream stor betydelse för dem som utövar Cenarionkonsterna.",["class:Mage"]="Lärda magiker är särskilt lämpade att söka efter obskyra böcker och magiska texter runt om i Azeroth för att berika institutionernas arkiv.",["faction:Alliance"]="Alliansens lärda, särskilt de som ansvarar för stora samlingar, förlitar sig på äventyrliga förkämpar som återfinner förlorad kunskap på farliga platser."},sec={{t="Återfinna glömd kunskap",b="Uppdraget Secrets of the Dreamers går ut på att återfinna sällsynta magiska texter och historiska avhandlingar från hela riket. Lärda som ägnar sig åt att dokumentera Azeroths magiska mysterier förlitar sig på resande äventyrare som gräver fram glömda verk och för dem tryggt till arkiven. I stället för att låta dyrbar kunskap förfalla i forntida ruiner eller privata gömmor ser dessa insamlingar till att viktig lärdom studeras och bevaras för kommande generationer."},{t="Utöka arkiven",b="När avhandlingarna lämnas in införlivar arkivarierna dem i sina permanenta samlingar, vilket utökar bibliotekets förståelse av magiska fenomen. I ett bibliotek som detta söker forskare ständigt efter obskyra manuskript om allt från The Emerald Dream till magisk teori. Arbetet blir aldrig helt färdigt, och de lärda tar gärna emot fler magiska skrifter som hittas ute i världen."}},faq={{q="Vad är syftet med uppdraget Secrets of the Dreamers?",a="Secrets of the Dreamers är ett uppdrag där du återfinner magiska verk och obskyr kunskap för att utöka en lärd samling. Äventyrare hittar relevanta föremål ute i världen och lämnar in dem för att berika forskarnas arkiv.",al={"vad är secrets of the dreamers","uppdraget secrets of the dreamers","vad gör man i det här uppdraget"}},{q="Vem samlar in de magiska texterna?",a="Uppdraget tas emot och lämnas in hos en lärd som ansvarar för ett biblioteks samling och ber resande äventyrare att ta med magiska verk.",al={"vem vill ha secrets of the dreamers","vem ger det här uppdraget","var lämnar man in secrets of the dreamers"}},{q="Var förvaras de återfunna verken?",a="De återfunna skrifterna läggs direkt till ett institutionsbiblioteks växande arkiv, så att sällsynt kunskap och magiska upptäckter katalogiseras och bevaras åt Alliansens lärda och forskare.",al={"vad är det för samling","vilket bibliotek är det till","vart tar böckerna vägen"}},{q="Vad syftar titeln på med ”Dreamers”?",a="Dreamers syftar traditionellt på druider som är knutna till The Emerald Dream eller forntida sovande väsen bundna till naturens sömn. Magiska verk som bär på deras hemligheter bevarar en mystisk urkraft.",al={"vilka är dreamers","dreamers i berättelsen","varför heter det dreamers"}},{q="Kan du lämna in fler magiska verk efter att du har slutfört uppdraget?",a="Arkivarierna välkomnar gärna fler bidrag. När du under dina resor hittar ytterligare magiska verk som kan berika samlingen uppmuntras du att lämna in dem och bidra till fortsatt forskning.",al={"kan jag lämna in fler böcker","kan uppdraget göras om","fler magiska verk"}},{q="Varför är det viktigt för de lärda att samla in dessa magiska skrifter?",a="Bibliotek och forskare runt om i Alliansen försöker ständigt fördjupa sin förståelse av det magiska, naturliga och dunkla. Förlorade eller utspridda avhandlingar innehåller insikter som hjälper lärda att upptäcka världens djupare historia och mysterier.",al={"varför samla magiska böcker","varför behöver biblioteket magiska böcker"}}},fp="23,186,25.278.0,22.248.0,57.121.0,33.106.0,37.165.0,47.179.0,59.151.0,63.173.0"}
P.entries["quest:78145"] = {n="Arcanic Systems Manual",s="Arcanic Systems Manual är ett magiskt verk som efterfrågas till Library i Ironforge. Det hjälper biblioteket att utöka sin kunskap.",h="Arcanic Systems Manual är ett magiskt verk som efterfrågas till Library i Ironforge.",kw={"arcanic","arcanic systems manual","samling","ironforge","bibliotek","magiska verk","handbok"},sec={{t="En plats i biblioteket",b="Library i Ironforge välkomnar magiska verk som kan berika dess samling. Du tar med ett att lägga till, och ditt bidrag hjälper bibliotekets kunskap att växa."}},faq={{q="Vad är Arcanic Systems Manual?",a="Det är ett magiskt verk som efterfrågas till Library i Ironforge.",al={"arcanic handbok","vilken handbok"}},{q="Vem vill ha handboken?",a="Någon på Library i Ironforge ber dig att ta med magiska verk som kan berika dess samling.",al={"vem bad om den","handbok åt vem"}},{q="Varför ta med handboken till biblioteket?",a="Bibliotekets kunskap växer genom bidrag av magiska verk.",al={"varför skänka den","vad är den till för"}}},fp="22,131,22.150.0,35.57.0,21.100.0,36.69.0"}
P.entries["quest:78146"] = {n="Goaz Scrolls",s="Bibliotekarien ber dig att ta med Goaz Scrolls till samlingen. Ditt bidrag utökar bibliotekets kunskap.",h="Bibliotekarien ber dig att ta med Goaz Scrolls till samlingen.",kw={"samling","goaz scrolls","kunskap","bibliotek","magiska verk","rullar"},sec={{t="En växande samling",b="Bibliotekarien tackar dig för att du bidrar med Goaz Scrolls. Fler magiska verk skulle också kunna hjälpa biblioteket, och bibliotekarien tar gärna emot dem."}},faq={{q="Vad används Goaz Scrolls till?",a="Goaz Scrolls utökar bibliotekets samling och kunskap.",al={"goaz scrolls syfte","varför ta med rullar","rullar bibliotek"}},{q="Vem ber om Goaz Scrolls?",a="En bibliotekarie ber dig att ta med Goaz Scrolls till samlingen.",al={"vem vill ha goaz scrolls","rullarnas givare","biblioteksperson"}},{q="Vart ska rullarna?",a="Goaz Scrolls är avsedda för bibliotekets samling.",al={"vart ta rullar","goaz scrolls plats","bibliotekets rullar"}},{q="Vad mer skulle vara till nytta för biblioteket?",a="Bibliotekarien tar gärna emot andra magiska verk som kan vara till nytta för biblioteket.",al={"andra magiska verk","fler biblioteksböcker","vad mer att ta med"}}},fp="12,117,20.135.0,26.61.0,30.62.0,28.52.0,36.74.0"}
P.entries["quest:78147"] = {n="Crimes Against Anatomy",s="En bibliotekarie ber dig att utöka samlingen i Ironforge med magiska verk. Dina upptäckter utökar bibliotekets kunskap.",h="En bibliotekarie ber dig att utöka samlingen i Ironforge med magiska verk.",kw={"samling","crimes against anatomy","ironforge","bibliotekarie","bibliotek","magiska verk"},sec={{t="Till samlingen",b="Biblioteket i Ironforge söker magiska verk som kan berika dess samling. Du kan lämna dina upptäckter till bibliotekarien, vars kunskap växer genom dessa bidrag. Fler verk kan ännu komma till nytta för biblioteket."}},faq={{q="Vem efterfrågar magiska verk?",a="En bibliotekarie i Ironforge ber dig att ta med magiska verk som kan berika samlingen.",al={"vem vill ha böcker","bibliotekets förfrågan"}},{q="Var ska jag lämna verken?",a="Lämna dem till bibliotekarien i Library i Ironforge.",al={"var ligger biblioteket","var lämna böcker"}},{q="Varför samla magiska verk?",a="Verken hjälper till att utöka bibliotekets kunskap.",al={"varför böcker","vad används magiska verk till"}}},fp="22,129,18.219.0,27.91.0,27.56.0,26.48.0"}
P.entries["quest:78148"] = {n="Runes of the Sorcerer-Kings",s="Biblioteket i Ironforge tar gärna emot magiska verk till sin samling. Dina upptäckter hjälper till att utöka dess kunskap.",h="Biblioteket i Ironforge tar gärna emot magiska verk till sin samling.",kw={"samling","ironforge","kunskap","bibliotek","magiska verk","runor","trollkarlskungar"},sec={{t="Samlingen",b="Bibliotekets föreståndare tackar dig när samlingen växer genom dina insatser. Fler magiska verk kan utöka dess kunskap, och föreståndaren tar gärna emot dem till biblioteket."}},faq={{q="Vad vill biblioteket ha?",a="Biblioteket tar gärna emot magiska verk som kan berika dess samling.",al={"vad vill de ha","biblioteksböcker","magiska verk"}},{q="Var ligger biblioteket?",a="Biblioteket ligger i Ironforge.",al={"bibliotekets läge","var ligger biblioteket","biblioteket i ironforge"}},{q="Varför lämna in magiska verk?",a="Dina insatser utökar bibliotekets kunskap.",al={"varför böcker","till vad","hjälpa biblioteket"}}},fp="27,111,14.168.0,27.67.0,21.28.0,24.44.0"}
P.entries["quest:78149"] = {n="Fury of the Land",s="Library i Ironforge söker magiska verk till sin samling. Dina fynd hjälper till att utöka dess kunskap.",h="Library i Ironforge söker magiska verk till sin samling.",kw={"samling","fury of the land","ironforge","kunskap","bibliotek","magiska verk"},sec={{t="En plats för kunskap",b="På Library i Ironforge ombeds du att ta med magiska verk som kan vara till nytta för samlingen. Bibliotekarien välkomnar det du har hittat och uppmanar dig att ta med mer om du hittar något."}},faq={{q="Vad vill biblioteket ha?",a="Library söker magiska verk som kan vara till nytta för samlingen.",al={"vad behöver de","biblioteksböcker","magiska verk"}},{q="Vart ska jag ta magiska verk?",a="Ta dem till bibliotekarien på Library i Ironforge.",al={"vart ska böcker lämnas","bibliotekets läge","lämna verk"}},{q="Varför samlar de på magiska verk?",a="Bibliotekarien säger att varje bidrag utökar deras kunskap.",al={"varför samla magiska böcker","bibliotekets samling","till vad"}}},fp="16,105,21.187.0,27.64.0,35.56.0,38.61.0"}
P.entries["quest:7815"] = {n="Snapjaws, Mon!",s="I The Hinterlands kan Katoom the Angler från Revantusk Village knappt hålla linan i vattnet, eftersom saltvattens-snapjaws hela tiden förstör den och stjäl hans bete. Han vill att du dödar femton av sköldpaddorna.",h="I The Hinterlands kan Katoom the Angler från Revantusk Village knappt hålla linan i vattnet, eftersom...",kw={"fiskare","bete","fiske","hinterlands","katoom","revantusk","snapjaws","sköldpaddor"},sec={{t="Problem på kroken",b="Katoom uppmanar dig att inte låta snapjaw-sköldpaddornas stora ögon lura dig och kallar dem en plåga. Enligt honom kan han inte fiska i ens fem minuter innan en av dem sliter av linan och smiter med betet. Som en tjänst åt honom själv och hans grannar i byn ber han dig utrota hela gänget. Det handlar om femton stycken."}},faq={{q="Vem ber dig jaga sköldpaddorna?",a="Katoom the Angler, en fiskare från Revantusk i The Hinterlands.",al={"vem ger uppdraget om snapjaws","uppdragsgivare för snapjaws","katoom the angler"}},{q="Varför vill Katoom att saltvattens-snapjaws ska dödas?",a="Katoom säger att de sliter av fiskelinan och stjäl betet, så han inte kan fiska i fred i ens fem minuter.",al={"varför döda snapjaws","sköldpaddsproblem","varför döda sköldpaddor i revantusk"}},{q="Hur många snapjaws måste dödas?",a="Femton saltvattens-snapjaw-sköldpaddor.",al={"hur många sköldpaddor","antal snapjaws","antal snapjaws mon"}}},fp="14,134,19.270.0,33.98.0,51.141.0,35.51.0"}
P.entries["quest:7816"] = {n="Gammerita, Mon!",s="Katoom the Angler från Revantusk Village i The Hinterlands har förlorat sitt bästa bete till Gammerita, saltvattenssnapjawernas ledare. Du får i uppdrag att hitta henne och ta tillbaka det.",h="Katoom the Angler från Revantusk Village i The Hinterlands har förlorat sitt bästa bete till Gammerita...",kw={"fiskare","gammerita","hinterlands","katoom","bete","revantusk","snapjaw","sköldpadda"},sec={{t="En tjuv bland sköldpaddorna",b="Katoom beskriver Gammerita som en ovanlig sköldpadda: hon leder saltvattenssnapjawerna, och Katoom kallar henne en tjuv. Hon bet av linan och tog hans bästa bete. Sedan dess har fiskarna inte nappat som förr."},{t="Ta tillbaka betet",b="Katoom vill att du hittar Gammerita och hämtar betet ur hennes mage. Gammerita håller till vid kusten bland de andra sköldpaddorna."},{t="Katooms förhoppningar",b="Med betet tillbaka och färre snapjawer omkring sig räknar Katoom med att fiskarna ska komma i mängder."}},faq={{q="Vem är Katoom the Angler?",a="En fiskare från Revantusk i The Hinterlands som ber dig jaga Gammerita.",al={"vem är katoom","katoom revantusk","katooms plats"}},{q="Vad är Gammerita?",a="En ovanlig sköldpadda som leder saltvattenssnapjawerna och som Katoom kallar en tjuv.",al={"vem är gammerita","vad är gammerita","gammerita sköldpadda"}},{q="Varför vill Katoom döda Gammerita?",a="Gammerita bet av Katooms bästa bete från linan, och sedan dess har fiskarna inte nappat som förr. Katoom vill få tillbaka betet ur hennes mage.",al={"varför döda gammerita","vad stal gammerita","katooms motiv"}},{q="Var kan Gammerita hittas?",a="Vid kusten, där hon håller till bland de andra saltvattenssnapjawsköldpaddorna.",al={"var finns gammerita","gammeritas plats","hitta gammerita"}}},fp="15,145,25.205.0,21.130.0,14.92.1,25.102.0,18.102.0,36.138.0,29.77.0"}
P.entries["quest:782"] = {n="Broken Alliances",s="I Kargath vill Gorn återupprätta Hordens heder efter alliansen med Deathwing. Ogerhövdingen Boss Tho'grun anlitades för att hjälpa till att hitta Sign of the Earth, men vände sig mot Horden och behöll den. Du ska ta tillbaka den vid Camp Boff.",h="I Kargath vill Gorn återupprätta Hordens heder efter alliansen med Deathwing.",kw={"badlands","blacklash","camp boff","deathwing","gorn","hematus","kargath","lethlor ravine","sign of the earth","tho'grun"},sec={{t="En legohär vänder sig mot Horden",b="Under Andra kriget stod Horden på draken Deathwings sida. Blacklash och Hematus, två av hans löjtnanter, låstes in i Lethlor Ravine, långt österut. Gorn menar att dessa fördärvade forna allierade måste tystas för att Hordens heder ska återupprättas. Horden behövde Sign of the Earth för att öppna drakarnas fängelse och anlitade ogrelegosoldater under Boss Tho'grun för att hitta den. Tho'grun vände sig mot dem, övermannade dem och behöll den själv."},{t="Camp Boff",b="Gorn skickar dig sydost om Kargath till Camp Boff för att döda Tho'grun och föra tillbaka Sign of the Earth. Gorn blir glad när Tho'grun är död och säger att ogres inte längre tillhör Horden."},{t="Vad tecknet öppnar",b="När Tho'grun är död räknar Gorn med att ogres hamnar i oordning, en liten seger som leder till en större. Med Sign of the Earth i Hordens händer kan de svarta drakarnas fängelse i Lethlor öppnas och befria dem från ändlös fångenskap, men också leda dem mot undergången."}},faq={{q="Vem är Gorn?",a="Gorn är Hordens företrädare i Kargath som skickar dig efter Sign of the Earth och vill återupprätta Hordens heder genom att tysta dess fördärvade forna allierade.",al={"vem ger uppdraget broken alliances","gorn kargath","gorns bakgrund"}},{q="Varför vill Gorn att Boss Tho'grun ska dö?",a="Horden anlitade Tho'grun och hans ogrelegosoldater för att hjälpa till att få tag i Sign of the Earth. Tho'grun vände sig mot dem, övermannade dem och behöll den.",al={"varför döda thogrun","tho'gruns förräderi","boss thogrun bakgrund"}},{q="Var ligger Camp Boff?",a="Camp Boff ligger sydost om Kargath.",al={"camp boff plats","var är thogrun","hitta boss thogrun"}},{q="Vad är Sign of the Earth?",a="Det är en nyckel som behövs för att låsa upp drakarnas fängelse i Lethlor Ravine.",al={"sign of the earth","vad gör sign of the earth"}},{q="Vilka drakar är fängslade i Lethlor Ravine?",a="Blacklash och Hematus, två av Deathwings löjtnanter från tiden då Horden var allierad med honom under Andra kriget.",al={"vem finns i lethlor ravine","blacklash och hematus","deathwings löjtnanter"}}},fp="16,220,18.455.0,9.186.0,19.300.1,12.157.0,38.151.0,19.36.0,30.85.0,47.161.0"}
P.entries["quest:7820"] = {n="A Donation of Wool",s="Thunder Bluff söker ulltyg, och du kan få fullt erkännande där genom att skänka sextio stycken. Andra givare förväntas bidra med tillräckligt med förnödenheter för att stödja insamlingen.",h="Thunder Bluff söker ulltyg, och du kan få fullt erkännande där genom att skänka sextio stycken.",kw={"tyginsamling","donation","erkännande","sextio stycken","thunder bluff","ull","ulltyg"},sec={{t="En tygdonation",b="Thunder Bluff samlar in ulltyg. Skänk sextio stycken för att få fullt erkännande för din generositet. Andra givare i riket förväntas bidra med tillräckligt för att stödja insamlingen."}},faq={{q="Vad vill Thunder Bluff ha för donationer?",a="Thunder Bluff tar emot donationer av ulltyg.",al={"ulldonation","vilket tyg behövs","skänka ull"}},{q="Hur mycket ulltyg ska jag skänka?",a="Skänk sextio stycken ulltyg för att få fullt erkännande från Thunder Bluff.",al={"hur mycket ull","sextio tygstycken","donationsmängd"}},{q="Vad får jag för att skänka ull?",a="Din gåva på sextio stycken ulltyg ger dig fullt erkännande från Thunder Bluff.",al={"erkännande för ulldonation","vad innebär erkännandet","donationsbelöning"}},{q="Varför samlar Thunder Bluff in ull?",a="Thunder Bluff förväntar sig att andra givare i riket bidrar med tillräckligt med ulltyg för att stödja donationsinsamlingen.",al={"varför ullinsamling","vad används ull till","varför samla in tyg"}}},fp="18,166,16.179.0,37.48.0,34.76.0,32.82.0,37.107.0"}
P.entries["quest:7826"] = {n="A Donation of Wool",s="I Orgrimmar ber uppdraget A Donation of Wool om hjälp med att samla in tyg. Staden har ull i sina förråd och räknar med att fler givare bidrar med tillräckligt för insamlingen.",h="I Orgrimmar ber uppdraget A Donation of Wool om hjälp med att samla in tyg.",kw={"a donation of wool","donation","orgrimmar","erkännande","sextio bitar","ull","ylletyg"},sec={{t="Ull till Orgrimmar",b="Orgrimmar ber dig att skänka sextio stycken ulltyg. I gengäld lovar staden erkännande. Det finns redan en del ull i förråden, och andra givare väntas bidra till insamlingen."}},faq={{q="Vad ber Orgrimmar om?",a="Orgrimmar tar emot donationer av ulltyg.",al={"vad vill de ha","ulldonation"}},{q="Hur mycket ull behöver jag skänka?",a="Orgrimmar ber om sextio stycken ulltyg.",al={"hur mycket ull","sextio ull"}},{q="Vad får jag för att skänka ull?",a="Du får fullt erkännande från Orgrimmar för att skänka sextio stycken ulltyg.",al={"erkännande för donation","belöning för ull"}},{q="Varför samlar Orgrimmar in ull?",a="Orgrimmar samlar in ull för att stödja sin donationskampanj.",al={"ullinsamling","varför ull"}},{q="Har Orgrimmar redan ull?",a="Ja. Orgrimmar har ull i sina förråd och räknar med att andra givare bidrar med tillräckligt för insamlingen.",al={"ullförråd","hur mycket ull"}}},fp="18,153,18.188.0,29.47.0,34.46.0,32.81.0,33.58.0,33.96.0"}
P.entries["quest:78261"] = {n="The Horn of Xelthos",s="En lapp från C ber dig att ensam hämta Horn of Xelthos från Shadowfang Keep. Veenix i Stonetalon Mountains kan hjälpa dig genom porten till borggården.",h="En lapp från C ber dig att ensam hämta Horn of Xelthos från Shadowfang Keep.",kw={"c","hemligt avlämningsställe","horn of xelthos","pyrewood village","shadowfang keep","stonetalon mountains","veenix","xelthos"},sec={{t="I det tysta",b="C lämnar lappen nära Pyrewood Village och anger Veenix som kontakt i Stonetalon Mountains. Horn of Xelthos ligger någonstans inne i Shadowfang Keep, där det vanligtvis krävs förstärkning för att ta sig in. C vill att arbetet sköts i det tysta, så du ska gå ensam och ta med hornet tillbaka till det hemliga avlämningsstället."}},faq={{q="Vem ber om Horn of Xelthos?",a="C lämnar en lapp där du ombeds hämta Horn of Xelthos och lämna det på det hemliga avlämningsstället nära Pyrewood Village.",al={"vem är c","vem vill ha hornet","c hornuppdrag"}},{q="Var finns Horn of Xelthos?",a="Horn of Xelthos finns någonstans inne i Shadowfang Keep.",al={"var finns hornet","hornets plats","hitta xelthos"}},{q="Varför måste jag gå ensam?",a="C säger att arbetet kräver diskretion, så du ska ta dig in i Shadowfang Keep ensam.",al={"varför ensam","varför gå ensam","ingen förstärkning"}},{q="Vem är Veenix?",a="Veenix är C:s kontakt i Stonetalon Mountains och kan hjälpa dig förbi porten till borggården i Shadowfang Keep.",al={"veenix hjälp","vem är veenix","kontakt vid porten"}},{q="Var ska jag lämna tillbaka hornet?",a="Lämna tillbaka hornet på C:s hemliga avlämningsställe nära Pyrewood Village.",al={"var lämna tillbaka hornet","hemliga avlämningsställets plats","lämna in hornet"}}},fp="19,158,16.292.0,38.112.0,29.56.0,26.82.0,14.110.0,27.55.0"}
P.entries["quest:78270"] = {n="Goblin Lockpicks",s="En kontakt från Venture Co. erbjuder sprängämnen för att ta sig förbi Shadowfangs port, men ber dig först hitta en arbetsorder. En annan arbetare från Venture Co. i närheten bör ha en.",h="En kontakt från Venture Co.",kw={"sprängämnen","port","goblin lockpicks","shadowfang","venture co.","arbetsorder"},sec={{t="A Work Order",b="En kontakt från Venture Co. hör att du planerar att ta dig in i Shadowfang ensam. Sprängämnen kan hjälpa dig förbi porten, men kontakten behöver en arbetsorder för att få leveransen att se korrekt ut i företagets bokföring. En annan arbetare från Venture Co. i närheten bör ha dokumentet."}},faq={{q="Varför behöver de en arbetsorder?",a="Kontakten från Venture Co. behöver en arbetsorder för att få sprängämnena att se legitima ut i företagets bokföring.",al={"varför arbetsorder","varför pappersarbete","goblin lockpicks"}},{q="Vad ska sprängämnena användas till?",a="Sprängämnena ska hjälpa dig förbi Shadowfangs port.",al={"vad är sprängämnena till för","shadowfangs port","ta sig förbi porten"}},{q="Vem kan ha arbetsordern?",a="En annan arbetare från Venture Co. i närheten bör ha en arbetsorder.",al={"vem har arbetsorder","hitta pappersarbete","arbetsorder från venture co."}},{q="Ska jag ta mig in i Shadowfang ensam?",a="Kontakten från Venture Co. förstår att du planerar att ta dig in i Shadowfang ensam.",al={"shadowfang ensam","ta sig in ensam","ta sig in i shadowfang"}}},fp="16,176,12.268.0,30.103.0,28.61.0,30.66.0,33.76.0"}
P.entries["quest:7828"] = {n="Stalking the Stalkers",s="Huntsman Markhor från byn Revantusk i The Hinterlands pekar ut Silvermane-vargarna som ett av de största hoten mot byns jägare. Du får i uppdrag att vända på steken och jaga jägarna.",h="Huntsman Markhor från byn Revantusk i The Hinterlands pekar ut Silvermane-vargarna som ett av de största...",kw={"vargar i the hinterlands","huntsman markhor","revantusk","revantusk village","silvermane howler","silvermane stalker","stalking the stalkers"},sec={{t="Vargar i bakhåll",b="Markhor påpekar att många troll redan har fallit offer för vildmarken i The Hinterlands och räknar Silvermane-vargarna bland de största hoten mot jägarna i Revantusk. Vargarna väntar gömda bland buskarna och i terrängen, och kastar sig över sitt byte när tillfället är det rätta. Markhor tänker inte låta det stå oemotsagt och uppmanar dig att tänka som en Silvermane och vända jakten mot jägarna genom att fälla varenda en."},{t="Vad Markhor begär",b="Markhor vill att du dödar femton Silvermane Stalkers och femton Silvermane Howlers. Markhor tillägger att vargarna håller till ute i vildmarken i The Hinterlands."},{t="Revantusks tack",b="När det är gjort tackar Markhor dig å Revantusks vägnar för det du har gjort för dem."}},faq={{q="Vem ber dig jaga vargarna?",a="Huntsman Markhor från byn Revantusk i The Hinterlands.",al={"vem ger stalking the stalkers","uppdragsgivare stalking the stalkers","markhor uppdrag"}},{q="Varför är Silvermane-vargarna ett sådant hot?",a="Markhor räknar dem bland de största hoten mot jägarna i Revantusk: de gömmer sig bland buskarna och i terrängen och slår till när tillfälle ges, och många troll har redan gått förlorade ute i vildmarken.",al={"varför döda silvermane-vargar","silvermane-vargarnas hot","varför gallra ut vargar i the hinterlands"}},{q="Vilka vargar ska gallras ut?",a="Femton Silvermane Stalkers och femton Silvermane Howlers.",al={"vilka vargar ska dödas","mål för stalking the stalkers","vargarter i the hinterlands"}},{q="Var hittar man vargarna?",a="Markhor säger att de håller till ute i vildmarken i The Hinterlands.",al={"var finns silvermane-vargar","silvermane stalker plats","silvermane howler plats"}}},fp="21,120,16.321.0,17.120.0,18.80.1,37.79.0,44.218.0,31.81.0,29.41.0"}
P.entries["quest:7829"] = {n="Hunt the Savages",s="Huntsman Markhor från byn Revantusk i The Hinterlands kallar de vilda ugglebestarna några av områdets mest argsinta varelser och ber dig döda tjugo av dem.",h="Huntsman Markhor från byn Revantusk i The Hinterlands kallar de vilda ugglebestarna några av områdets mest...",kw={"the hinterlands","jakten på vildarna","huntsman markhor","ugglebestar","revantusk","revantusk village","vild ugglebest"},sec={{t="Klor och näbbar",b="Markhor beskriver de vilda ugglebestarna som några av The Hinterlands mer argsinta varelser och säger att deras klor och näbbar har kostat Revantusk många goda krigare. Markhor vill att du dödar varenda en du ser, tills du inte står ut med mer blodspillan. Sedan ska ditt bidrag vägas och bedömas. Tjugo måste falla."},{t="Rensa sinnet",b="Markhors råd inför jakten är att rensa sinnet från orena tankar och förena dig med vildmarken. Ugglebestarna finns ute i The Hinterlands vildmarker."},{t="Markhors dom",b="Efter jakten kallar Markhor dig en värdig vän till Revantusk."}},faq={{q="Vem erbjuder den här jakten?",a="Huntsman Markhor från byn Revantusk i The Hinterlands.",al={"vem ger jakten på vildarna","uppdragsgivare för jakten på vildarna","huntsman markhor uppdrag"}},{q="Varför vill Markhor att de vilda ugglebestarna dödas?",a="Markhor kallar dem argsinta och säger att de har krävt många goda krigare från Revantusk med sina klor och näbbar.",al={"varför döda vilda ugglebestar","orsak till ugglebestjakten","varför jaga vildarna"}},{q="Var finns de vilda ugglebestarna?",a="Markhor säger att de håller till i The Hinterlands vildmarker.",al={"vilda ugglebestars plats","var finns vilda ugglebestar","ugglebestar i the hinterlands"}},{q="Hur många vilda ugglebestar måste dödas?",a="Tjugo vilda ugglebestar.",al={"hur många ugglebestar ska dödas","krav för jakten på vildarna"}}},fp="16,106,15.300.0,17.128.0,18.76.1,21.95.0,50.100.0,40.57.0,40.34.0"}
P.entries["quest:783"] = {n="A Threat Within",s="Frivilliga svarar på Stormwinds uppmaning i Northshire Valley, där det lokala försvaret behöver hjälp. I Northshire Abbey förklarar Marshal McBride att rikets styrkor är hårt ansatta utomlands, så garnisonerna hemma saknar folk när oroligheter uppstår.",h="Frivilliga svarar på Stormwinds uppmaning i Northshire Valley, där det lokala försvaret behöver hjälp.",kw={"ett hot inifrån","kloster","elwynn forest","marshal mcbride","northshire","rekrytering","stormwind guard","frivilliga"},ang={["faction:Alliance"]="Som medlem av Alliansen ser du hur åtaganden i avlägsna länder lämnar även dess kärnland utsatt för oroligheter på hemmaplan.",["race:Human"]="Som mänsklig försvarare från Northshire är ditt svar på Marshal McBrides uppmaning ditt första officiella löfte att skydda ditt hemland och kungariket Stormwind."},sec={{t="Ett rike med spridda styrkor",b="Northshire Valley gav en gång ro för bön, jordbruk och klosterstudier. Nu är dalen Elwynn Forests första försvarslinje mot oroligheter på hemmaplan. Stormwinds reguljära styrkor tjänstgör på avlägsna fronter, så kärnlandet saknar soldater. Med få vakter i närheten måste Stormwind Guard kalla på varje villig frivillig som kommer till klostret."},{t="Marshalens uppmaning",b="Marshal McBride leder försvaret av Northshire Valley från Northshire Abbey medan trycket ökar. Avlägsna faror hotar Alliansen, samtidigt som banditer, skadedjur och ohyra från underjorden utnyttjar bristen på soldater i hemtrakterna. Du svarar på uppmaningen att tjänstgöra i dalen och börjar med marken kring klostret, medan hoten sprider sig över Elwynn."}},faq={{q="Vad är syftet med det här uppdraget?",a="Marshal McBride kallar nyanlända till Northshire Valley för att delta i försvaret. Du går in i Northshire Abbey och rapporterar till honom.",al={"uppdraget hot inifrån","vad är det här för uppdrag","introduktionsuppdrag northshire"}},{q="Vem är Marshal McBride?",a="Marshal McBride är den högste officeren i Stormwind Guard vid Northshire Abbey. Han leder försvaret av dalen och ger rekryterna uppdrag att hantera hot på landsbygden i närheten.",al={"marshal mcbride","vem är mcbride","klostrets befälhavare"}},{q="Varför rekryterar Stormwind frivilliga i stället för att skicka reguljära soldater?",a="Stormwinds reguljära styrkor tjänstgör utomlands för att skydda Alliansen. Eftersom garnisonerna i kärnlandet saknar soldater förlitar sig lokala befälhavare på frivilliga för att försvara hemtrakterna.",al={"varför frivilliga","var är vakterna","varför har stormwind för få soldater"}},{q="Vilka hot plågar Northshire Valley just nu?",a="Kobolder härjar i de närliggande gruvorna och kullarna, medan sjuka eller rovgiriga skadedjur stör vingårdarna. Rövare och fredlösa utnyttjar också dalens försvagade garnison.",al={"hot i dalen","vad anfaller northshire","problem i northshire"}},{q="Vart leder det här uppdraget härnäst?",a="När du har rapporterat till Marshal McBride skickas du för att rensa kullarna från kobolder, hjälpa lokala bönder och arbetare samt undersöka den växande närvaron av organiserade banditer.",al={"nästa uppdrag","vad kommer efter hot inifrån","mcbrides uppföljning"}},{q="Varför används Northshire Abbey som militär ledningspost?",a="Northshire Abbey är en helig plats för studier och tro, men dess stenmurar och centrala läge gör det till dalens praktiska bas. Eftersom den lokala myndigheten är hårt pressad har Stormwind Guard upprättat sitt högkvarter i klostret.",al={"varför militär i klostret","northshires kyrka militär","soldater i det heliga klostret"}}},fx={["2039075b"]={q="Varför skickar Deputy Willem dig till Marshal McBride?",a="Deputy Willem är stationerad utanför Northshire Abbey för att så snabbt som möjligt bedöma nyanlända som är stridsdugliga. Kungarikets militär är hårt ansträngd och flera kriser närmar sig Northshires gränser, så han behöver se till att varje kapabel frivillig tas in i tjänst. I stället för att själv dela ut uppdrag skickar Willem dig direkt till sin befälhavare, Marshal McBride, så att du kan få en formell genomgång och skickas dit dalens försvar sviktar mest.",al={"varför tala med mcbride","willems motiv"}}},fp="15,190,24.301.0,18.295.0,34.129.0,23.170.0,75.167.0,54.175.0,37.171.0,62.230.0"}
P.entries["quest:7830"] = {n="Avenging the Fallen",s="Huntsman Markhor från Revantusk Village säger att Wildhammer tränar gryfer att döda troll, och han vill att regionens äldre gryfer, Skylords, utrotas. Du ska döda en Razorbeak Skylord och ta med dess fjäderplym tillbaka till honom.",h="Huntsman Markhor från Revantusk Village säger att Wildhammer tränar gryfer att döda troll, och han vill att...",kw={"avenging the fallen","gryp","the hinterlands","huntsman markhor","razorbeak skylord","revantusk village","skylords fjäderplym","wildhammer"},sec={{t="Att döda Skylords",b="Markhor, en jägare från Revantusk Village i The Hinterlands, är bitter över att Wildhammer tränar gryfer att döda troll. Rättvisan ska hinna ikapp dem, lovar han, men först vill han att du ger dig på regionens äldre gryfer, Skylords. Döda en och återvänd med dess fjäderplym. Razorbeak Skylord är en sällsynt ras som brukar hålla till i The Hinterlands vildmarker, och Markhor klandrar den för att den föder upp mordiska ungar."},{t="Fjäderplymen granskad",b="Markhor granskar fjäderplymen och undrar högt hur många jägare besten slukade innan den fick möta rättvisan genom din hand."}},faq={{q="Vem erbjuder jakten?",a="Huntsman Markhor erbjuder den i Revantusk Village i The Hinterlands.",al={"uppdragsgivare","vem ger avenging the fallen","var finns markhor"}},{q="Varför vill Huntsman Markhor att en Skylord ska dödas?",a="Markhor säger att Wildhammer tränar gryfer att döda troll, och han vill att regionens äldre gryfer, Skylords, ska utrotas. Han säger att Razorbeak Skylord är en sällsynt ras som föder upp mordiska ungar.",al={"varför döda razorbeak skylord","varför döda skylord","varför jaga gryfer"}},{q="Var kan man hitta en Razorbeak Skylord?",a="Markhor säger att denna sällsynta ras håller till i The Hinterlands vildmarker.",al={"var finns skylord","var finns razorbeak skylord","var finns skylords fjäderplym"}},{q="Vad måste du ta med tillbaka till Markhor?",a="Döda en Razorbeak Skylord och återvänd till Markhor med dess fjäderplym.",al={"vilket föremål behöver jag","målet med avenging the fallen","skylord-byte"}}},fp="19,131,20.383.0,18.110.1,21.73.0,47.190.0,39.78.0,37.64.0"}
P.entries["quest:7833"] = {n="A Donation of Wool",s="Ett troll från Darkspear samlar in ulldonationer, och dina sextio stycken Wool Cloth blir en del av en större insamling.",h="Ett troll från Darkspear samlar in ulldonationer, och dina sextio stycken Wool Cloth blir en del av en större...",kw={"insamling","darkspear","donation","förråd","troll","ull","wool cloth"},sec={{t="En gemensam insamling",b="Trollen i Darkspear samlar in Wool Cloth för att fylla på sina förråd. Insamlaren kan ta emot dina sextio stycken nu, medan hjälp från andra väntas slutföra insamlingen."}},faq={{q="Vad samlas in?",a="Trollen i Darkspear samlar in Wool Cloth.",al={"vad behöver de","ulldonation"}},{q="Hur mycket Wool Cloth behöver de från mig?",a="Insamlaren behöver sextio stycken Wool Cloth från dig.",al={"hur mycket ull","sextio tyg"}},{q="Varför samlar trollen in ull?",a="Trollen samlar in ull för att fylla på sina förråd.",al={"varför ull","till vad"}},{q="Kan jag lämna tyget nu?",a="Ja. Insamlaren kan ta emot dina sextio stycken Wool Cloth nu.",al={"var lämna ull","donera nu"}}},fp="18,103,19.181.0,24.46.0,41.56.0,35.56.0,25.66.0"}
P.entries["quest:7839"] = {n="Vilebranch Hooligans",s="Smith Slagtree från Revantusk Village säger att Vilebranch-troll invaderade byn och stal hans verktyg. Han har reservverktyg, men den stulna uppsättningen var en gåva från en godhjärtad gnom som räddade hans liv när han var en ung orch, och han vill ha den tillbaka.",h="Smith Slagtree från Revantusk Village säger att Vilebranch-troll invaderade byn och stal hans verktyg.",kw={"agol'watha","the hinterlands","markhor","revantusk village","shaol'watha","skulk rock","slagtrees förlorade verktyg","smith slagtree","vilebranch"},sec={{t="En gåva från en gnom",b="Vilebranch-troll invaderade Revantusk Village och stal Smith Slagtree verktyg. Han har reservverktyg, men den stulna uppsättningen var en gåva från en godhjärtad gnom som räddade hans liv när han var en ung orch. Han säger att verktygen betyder allt för honom och ber dig hämta tillbaka dem."},{t="Var verktygen sågs",b="Slagtree säger att Markhor rapporterade att han sett verktygen nära templen Agol'watha och Shaol'watha, i den nordöstra delen av The Hinterlands. Han tillägger att du också bör undersöka Skulk Rock och varnar för att områdets Vilebranch-troll är hänsynslösa och mordiska."}},faq={{q="Varför är de här stulna verktygen så viktiga för Smith Slagtree?",a="Uppsättningen var en gåva från en godhjärtad gnom som räddade Slagtrees liv när han var en ung orch. Han har reservverktyg, men säger att de här betyder allt för honom.",al={"varför bryr sig slagtree om sina verktyg","slagtree förlorade verktyg lore","varför är slagtrees verktyg speciella"}},{q="Vem stal verktygen från Revantusk Village?",a="Vilebranch-troll invaderade byn och stal Smith Slagtree verktyg.",al={"vem tog verktygen","vem stal slagtrees verktyg"}},{q="Vart fördes de försvunna verktygen?",a="Markhor såg dem nära templen Agol'watha och Shaol'watha, i den nordöstra delen av The Hinterlands. Slagtree säger också att du ska undersöka Skulk Rock.",al={"var finns slagtrees verktyg","var hittar man verktygen","slagtree verktygens plats"}},{q="Vem rapporterade att verktygen hade setts efter räden?",a="Markhor var den som berättade för Slagtree var verktygen hade setts.",al={"vem såg verktygen","vem rapporterade om de stulna verktygen"}}},fp="20,162,19.259.0,25.201.0,58.163.0,43.90.0,35.144.0,45.58.0"}
P.entries["quest:784"] = {n="Vanquish the Betrayers",s="Vid Tiragarde Keep håller Kul Tiran-styrkor ett kustfäste i Durotar. Gar'Thok har beordrat en Horde-attack mot löjtnant Benedicts garnison, vars närvaro bryter den bräckliga freden med Theramore.",h="Vid Tiragarde Keep håller Kul Tiran-styrkor ett kustfäste i Durotar.",kw={"daelin proudmoore","durotar","gar'thok","kul tiras","löjtnant benedict","marinsoldater","razor hill","sjömän","tiragarde keep","vanquish the betrayers"},ang={["faction:Horde"]="Kul Tirans ockupation av Tiragarde Keep är en pågående krigshandling vid Durotars gräns. När Benedicts styrkor drivs bort visar Horde att den kan försvara sitt nybyggda hem mot främmande flottor.",["race:Orc"]="Orcher hedrar vapenvilan med Jaina vid Mount Hyjal, men Kul Tiras väcker bittra minnen av det andra kriget. Att strida mot Benedicts marinsoldater handlar om överlevnad och stolthet över förfäderna.",["race:Troll"]="Tiragarde Keep ligger oroväckande nära Sen'jin Village, Darkspear-folkets bosättning. Att driva bort dess fientliga sjömän hjälper till att skydda trollens sårbara nya hem."},sec={{t="En bruten vapenvila",b="Thrall ledde Horde över Great Sea till Kalimdor, där han förenade sig med Lady Jaina Proudmoore mot Burning Legion vid Mount Hyjal. Freden bröts när Jainas främmande far, storamiral Daelin Proudmoore, förde Kul Tiras flotta till Durotar. Han beskyllde alla orcher för den gamla Hordes grymheter och intog kustfästen, däribland Tiragarde Keep. Daelin dog vid Theramore, men resterna av hans flotta vägrar fortfarande alla överenskommelser och ger inte upp sitt hat."},{t="Benedicts återkomst",b="Tiragarde Keep föll en kort tid efter storamiralens nederlag, men reserver från Kul Tiras under löjtnant Benedict återtog det. Fästningen ligger mellan Razor Hill och Sen'jin Village. Därifrån trakasserar sjömän och marinsoldater resenärer och hotar Durotars östra sjövägar. Gar'Thok ser deras position som ett omedelbart hot mot Durotars säkerhet och kallar Hordes krigare till angrepp mot Benedicts befäl."}},faq={{q="Varför anfaller Kul Tiran-människor Durotar?",a="De är rester av storamiral Daelin Proudmoores expeditionsflotta. Daelin avvisade fredlig samexistens mellan människor och orcher och ville förgöra Durotar. Även efter hans död ockuperar hans lojalister fortfarande kustfästen som Tiragarde Keep och trotsar Horde.",al={"varför finns människor i durotar","kul tiras anfaller","tiragarde keep människornas bakgrund"}},{q="Vem är löjtnant Benedict?",a="Löjtnant Benedict leder reserverna från Kul Tiran som håller Tiragarde Keep. Efter storamiral Proudmoores nederlag samlade Benedict de överlevande marinsoldaterna och sjömännen, återtog kustbefästningen och inledde ständiga angrepp mot orcherna.",al={"vem är benedict","löjtnant benedicts bakgrund","ledare för tiragarde keep"}},{q="Stöder Jaina Proudmoore de här människorna?",a="Nej. Jaina slöt en överenskommelse med krigshövding Thrall för att de skulle överleva tillsammans och motarbetade aktivt sin fars aggressiva korståg för att bevara freden. Trupperna vid Tiragarde Keep är rester från Kul Tiras som avvisar Theramores diplomati och ser Jainas vapenvila som förräderi.",al={"stödjer jaina dem","alliansen mellan theramore och kul tiras","jaina proudmoore tiragarde"}},{q="Varför kallas de \"förrädare\"?",a="Gar'Thok kallar dem förrädare eftersom deras invasion bröt den överenskommelse som Thrall och Jaina Proudmoore slöt för att besegra Archimonde under det tredje kriget. Deras fortsatta militära närvaro på Hordes suveräna territorium trotsar de gränser som upprättades på Kalimdor efter kriget.",al={"varför förrädare","vem förrådde vem","förrädarnas betydelse"}},{q="Var ligger Tiragarde Keep?",a="Tiragarde Keep ligger på Durotars östkust, söder om Razor Hill och strax nordost om Sen'jin Village. Dess höga stenmurar blickar ut över kustvattnen och ger inkräktarna en strategisk bas nära Hordes bosättningar.",al={"tiragarde keep plats","var ligger tiragarde keep","var hittar man benedict"}}},fx={["6a077d02"]={q="Varför vill Gar'Thok att Tiragarde Keep rensas?",a="Gar'Thok ansvarar för försvaret av Razor Hill och östra Durotar. Att fientliga Kul Tiran-styrkor återtagit Tiragarde Keep hotar orchernas hemland direkt och trotsar freden mellan Thrall och Jaina Proudmoore. Om en beväpnad människofästning tillåts ligga kvar på Durotars kust utsätts närliggande bosättningar och försörjningsleder omedelbart för invasionsrisk.",al={"gar'thoks motiv","varför rensa tiragarde keep","varför anfaller gar'thok människor"}},["902328ad"]={q="Vilka ska du slå ut i Tiragarde Keep?",a="Du ska slå ut de kvarvarande Kul Tiran-sjöstridskrafterna som ockuperar Tiragarde Keep: sjömännen, marinsoldaterna och deras befälhavare, Lieutenant Benedict. Dessa soldater är resterna av storamiral Daelin Proudmoores flotta och håller en obehörig väpnad landstigning långt inne på Hordens suveräna territorium.",al={"vem ska dödas i tiragarde keep","vilka är målen","mål för att besegra förrädarna"}}},fp="22,207,17.452.0,21.420.0,43.256.0,27.249.0,43.253.0,32.259.0,32.216.0"}
P.entries["quest:7840"] = {n="Lard Lost His Lunch",s="Lard, från byn Revantusk i The Hinterlands, är hungrig och rädd. En Vilebranch slog till Lard under en privat picknick, och Lard flydde utan maten. Du ombeds hämta den från en ö i norr.",h="Lard, från byn Revantusk i The Hinterlands, är hungrig och rädd.",kw={"the hinterlands","ö","lard","mat","picknick","revantusk village","vilebranch"},sec={{t="En avbruten picknick",b="Lard hade picknick på en hemlig plats när en Vilebranch, ful och elak enligt Lard, slog till Lard med en stor käpp. Lard rusade till Revantusk och lämnade maten kvar. Nu är Lard hungrig och rädd för att gå tillbaka."},{t="Ön i norr",b="Picknickplatsen ligger på en ö i norr. Lard hoppas att du går dit, hittar maten och tar tillbaka den, och ser upp för Vilebranch-trollen."},{t="Lards tack",b="Maten visar sig vara en enorm köttbit. Lard slukar den, tackar dig och lovar dig en särskild picknickkorg som tack för hjälpen."}},faq={{q="Vem är Lard?",a="En invånare i Revantusk i The Hinterlands, hungrig och rädd efter att en Vilebranch slog till Lard med en stor käpp.",al={"lard the hinterlands","vem är lard","lard revantusk"}},{q="Var tappade Lard bort maten?",a="På en undangömd picknickplats på en ö i norr.",al={"var är lards mat","lards picknickplats","lards hemliga plats"}},{q="Varför lämnade Lard maten kvar?",a="En Vilebranch slog till Lard med en stor käpp under picknicken, och Lard sprang tillbaka till Revantusk utan maten.",al={"varför sprang lard","vem attackerade lard"}},{q="Vad bör du se upp för på ön?",a="Lard pekar ut Vilebranch-trollen som faran på ön.",al={"vilebranch på ön","faror på lards ö"}}},fp="19,194,20.185.0,20.144.0,13.122.1,12.125.0,30.70.0,35.106.0,44.59.0"}
P.entries["quest:7841"] = {n="Message to the Wildhammer",s="I Revantusk Village i The Hinterlands säger Otho Moji'ko att Wildhammer sluter avtal med trollens fiender, och den här gången är högalverna deras partner. Otho vill skicka ett budskap till Wildhammer-dvärgarna, skrivet i Highvale-högalvernas blod vid Quel'Danil Lodge.",h="I Revantusk Village i The Hinterlands säger Otho Moji'ko att Wildhammer sluter avtal med trollens fiender...",kw={"highvale","hinterlands","budskap till wildhammer","otho mojiko","quel'danil lodge","revantusk village","wildhammer"},sec={{t="Ett budskap i blod",b="Wildhammer knyter nya allianser med trollens fiender, och den här gången är högalverna deras partner. Otho Moji'ko spottar åt tanken. Dvärgarna förtjänar ett budskap, skrivet i deras nya vänners blod: slakta varje Highvale-högälv du stöter på och lämna kropparna som en varning. Highvale Outrunners, Scouts, Marksmen och Rangers samlas vid Quel'Danil Lodge, i nordvästra The Hinterlands."},{t="Nytt från Revantusk Village",b="När du återvänder förklarar Otho att Revantusk också knyter nya allianser och berömmer ditt arbete."}},faq={{q="Vem erbjuder det här uppdraget?",a="Otho Moji'ko, som står i Revantusk Village.",al={"vem ger budskap till wildhammer","otho mojiko uppdrag"}},{q="Var finns Highvale-högalverna?",a="De samlas vid Quel'Danil Lodge, i nordvästra The Hinterlands.",al={"quel danil lodge plats","var finns highvale-alver","var hittar man highvale-scouter"}},{q="Varför vill Otho Moji'ko att högalverna ska attackeras?",a="Otho säger att Wildhammer sluter avtal med trollens fiender, och att de nu samarbetar med högalverna. Otho vill skicka ett budskap till Wildhammer-dvärgarna, skrivet i högalvernas blod.",al={"varför attackera quel danil","varför döda högalver i hinterlands"}},{q="Vilka Highvale-alver vill Otho att du ska slakta?",a="Highvale Outrunners, Scouts, Marksmen och Rangers vid Quel'Danil Lodge.",al={"vilka highvale-alver","highvale marksman","highvale ranger"}}},fp="25,222,18.393.0,25.122.1,22.46.0,42.88.0,51.209.0,48.97.0"}
P.entries["quest:7842"] = {n="Another Message to the Wildhammer",s="Efter det första meddelandet säger Otho Moji'ko i Revantusk Village att Wildhammer och deras gryfer står varandra lika nära som en troll och en partner. Motbjudande, men det kan användas mot dem. Otho vill att gryfer i The Hinterlands dödas för sina fjädrar.",h="Efter det första meddelandet säger Otho Moji'ko i Revantusk Village att Wildhammer och deras gryfer står...",kw={"grýf","hinterlands","long elegant feather","otho moji'ko","revantusk village","wildhammer"},sec={{t="Ett fjädermeddelande",b="Efter Highvale-högalverna har Otho Moji'ko ett nytt meddelande att skicka. Det sägs att Wildhammer och deras gryfer står varandra lika nära som en troll och en partner, vilket Otho tycker är motbjudande men användbart. Döda gryferna du stöter på i The Hinterlands och samla in deras Long Elegant Feathers. Gryfer sägs leva i varje del av området. Av fjädrarna ska Otho göra det sista meddelandet."},{t="Othos förtjusning",b="Otho räknar med att det sista meddelandet ska skrämma bort Wildhammer eller göra dem väldigt, väldigt arga. Otho är förtjust över att bara ett steg återstår innan Wildhammer inser att troll inte kan trotsas."}},faq={{q="Vem ger det här uppdraget?",a="Otho Moji'ko, som står i Revantusk Village.",al={"vem ger ett nytt meddelande till wildhammer","uppdragsgivare för ännu ett meddelande","otho mojiko"}},{q="Varför vill Otho Moji'ko ha gryffjädrar?",a="Otho säger att Wildhammer och deras gryfer står varandra lika nära som en troll och en partner, och vill använda det mot dem. Fjädrarna ska ingå i det sista meddelandet.",al={"varför gryffjädrar","varför döda gryfer i hinterlands"}},{q="Var finns gryfer?",a="Gryfer sägs leva i alla delar av The Hinterlands.",al={"gryffplatser i hinterlands","var finns hinterlands gryfer"}},{q="Vad föregick det här meddelandet?",a="Det följer på Message to the Wildhammer, där Otho lät döda Highvale-högalver som en varning till dvärgarna.",al={"vad kommer före another message to the wildhammer","message to the wildhammer uppdragskedja"}}},fp="33,175,21.332.0,15.167.1,21.54.0,44.165.0,28.49.0,30.118.0"}
P.entries["quest:7843"] = {n="The Final Message to the Wildhammer",s="Otho Moji'ko ger dig ett spjut dränkt i blod och bundet med gripfjädrar. Du ska ta det till Aerie Peak, i västra The Hinterlands, och stöta ner det i jorden bredvid brunnen mitt i staden.",h="Otho Moji'ko ger dig ett spjut dränkt i blod och bundet med gripfjädrar.",kw={"aerie peak","gripfjädrar","hinterlands","otho moji'ko","revantusk village","spjut","wildhammer"},sec={{t="Ett spjut till Aerie Peak",b="Efter Another Message to the Wildhammer ger Otho Moji'ko dig det sista meddelandet: ett spjut dränkt i blod och bundet med gripfjädrar. Bär det till Aerie Peak och plantera det mitt i staden, bredvid brunnen, för att visa dvärgarna att trollen menar allvar. Otho hoppas att du kommer tillbaka levande och varnar för rasande Wildhammer-dvärgar och stökigt Alliance-folk."},{t="Othos förhoppning",b="Otho önskar att han hade fått se dvärgarnas ansikten och undrar högt om de packar sina väskor och lämnar staden. Otho lovar dig stort mojo för dådet."}},faq={{q="Vem skickar dig för att plantera spjutet?",a="Otho Moji'ko, som står i Revantusk Village.",al={"uppdragsgivare","vem ger uppdraget","otho mojiko"}},{q="Var måste spjutet planteras?",a="Bredvid brunnen mitt i Aerie Peak, i västra The Hinterlands.",al={"spjutets plats","var ska jag placera spjutet","aerie peak-brunnen"}},{q="Vad består det sista meddelandet av?",a="Ett spjut dränkt i blod och bundet med gripfjädrar.",al={"vad är spjutet","spjut med gripfjädrar","föremålet sista meddelandet"}},{q="Vad kom före detta i kedjan?",a="Det följer på Another Message to the Wildhammer, där Otho bad om gripfjädrar till detta sista meddelande.",al={"föregående uppdrag","förkunskapskrav","wildhammer-meddelandekedjan"}}},fp="35,185,22.351.0,11.208.1,33.46.0,32.91.0,34.77.0,35.106.0"}
P.entries["quest:7844"] = {n="Cannibalistic Cousins",s="Mystic Yayo'jin i Revantusk Village kallar Vilebranch-trollen ett fördärvat släkte som ger sig på andra troll och humanoider. Eftersom Zul'jin inte är där för att utrota dem ber hon dig döda deras Scalpers och Soothsayers nära templen i norr-nordost.",h="Mystic Yayo'jin i Revantusk Village kallar Vilebranch-trollen ett fördärvat släkte som ger sig på andra troll...",kw={"agol'watha","cannibalistic cousins","mystic yayo'jin","revantusk village","scalper","shaol'watha","soothsayer","vilebranch","zul'jin"},sec={{t="Tre stammar, ett land",b="Tre trollstammar lever i Hinterlands, och Mystic Yayo'jin säger att de, bortsett från att vara troll i samma land, har lite gemensamt. Hon kallar Vilebranch, med rätta, ett fördärvat släkte som ger sig på andra troll och humanoider. Zul'jin skulle lätt ha utrotat dem, men Zul'jin är inte där, och Revantusk får klara sig på egen hand."},{t="Där Vilebranch samlas",b="Yayo'jin ber dig döda Vilebranch Scalpers och Soothsayers, som håller till runt templen Shaol'watha och Agol'watha, i Hinterlands nord-nordöstra del."},{t="Yayo'jins beröm",b="När du kommer tillbaka förklarar Yayo'jin att inte ens Zul'jin hade kunnat göra det bättre."}},faq={{q="Vem erbjuder det här uppdraget?",a="Mystic Yayo'jin, som står i Revantusk Village.",al={"uppdragsgivare för cannibalistic cousins","vem ger cannibalistic cousins","mystic yayo'jin"}},{q="Varför vill Yayo'jin att Vilebranch ska utrotas?",a="Hon kallar Vilebranch ett fördärvat släkte som ger sig på andra troll och humanoider, och säger att det faller på dig att utrota regionens avskum.",al={"varför revantusk slåss mot vilebranch","vilebranch-kannibalism","konflikten mellan revantusk och vilebranch"}},{q="Var hittar man Vilebranch-trollen?",a="Runt templen Shaol'watha och Agol'watha, i Hinterlands nord-nordöstra del.",al={"shaol'wathas plats","agol'wathas plats","var finns vilebranch soothsayers"}},{q="Vilka Vilebranch vill Yayo'jin att du ska utrota?",a="Vilebranch Scalpers och Vilebranch Soothsayers.",al={"mål för cannibalistic cousins","vem ska jag döda för cannibalistic cousins"}},{q="Var är Zul'jin?",a="Inte i Hinterlands just nu. Yayo'jin säger att om Zul'jin vore där skulle han lätt utrota Vilebranch, men han är inte där, så Revantusk får klara sig på egen hand.",al={"är zul'jin här","var är zul'jin i hinterlands","zul'jins status"}}},fp="21,226,22.242.0,27.169.0,17.71.1,22.49.0,48.137.0,41.108.0,46.76.0,17.152.0"}
P.entries["quest:7845"] = {n="Kidnapped Elder Torntusk!",s="Primal Torntusk från Revantusk Village säger att Vilebranch-vildar rövade bort hennes partner, Elder Torntusk, under en djärv nattlig räd. Spioner säger att han lever och hålls fången på toppen av Jintha'alor, och hon ber dig rädda honom.",h="Primal Torntusk från Revantusk Village säger att Vilebranch-vildar rövade bort hennes partner, Elder...",kw={"elder torntusk","hakkar","hexx","hinterlands","jintha'alor","primal torntusk","revantusk","torntusk","vilebranch"},sec={{t="En nattlig räd",b="Vilebranch-vildar slog till mot Revantusk Village vid midnatt och tog Elder Torntusk, Primal Torntusks partner. Hennes spioner säger att han fortfarande lever och hålls fången på toppen av Jintha'alor, Vilebranchs huvudstad i södra Hinterlands. Primal Torntusk fruktar att byn inte skulle klara av att förlora honom."},{t="Den ansiktslösa blodguden",b="Det sägs att Vile Priestess Hexx gör fången redo att offras till Hakkar, den ansiktslösa blodguden."},{t="När du når honom",b="När du når Elder får du veta att du måste skynda dig, för vakterna känner säkert redan till att du har kommit."}},faq={{q="Vem tog Elder Torntusk?",a="Vilebranch-vildar tog honom under en djärv nattlig räd mot Revantusk Village.",al={"vem kidnappade elder torntusk","vem tog torntusk","torntusks kidnappare"}},{q="Var hålls Elder Torntusk fången?",a="Hennes spioner säger att han hålls fången på toppen av Jintha'alor, Vilebranchs huvudstad i södra Hinterlands.",al={"elder torntusks plats","var är elder torntusk","var hålls torntusk fången"}},{q="Vilket öde väntar Elder Torntusk på toppen av Jintha'alor?",a="Det sägs att Vile Priestess Hexx gör honom redo att offras till Hakkar, den ansiktslösa blodguden.",al={"varför tillfångatogs torntusk","vad vill vilebranch med torntusk","hexx offrar torntusk"}},{q="Vem är Primal Torntusk?",a="Primal Torntusk är Elder Torntusks partner, och hon ber dig rädda honom.",al={"vem är primal torntusk","primal torntusks partner"}}},fp="25,147,15.279.0,22.107.0,18.90.1,24.84.0,35.126.0,49.120.0,23.71.0"}
P.entries["quest:7846"] = {n="Recover the Key!",s="I Jintha'alor är Elder Torntusk fjättrad och ber dig befria honom. Hitah'ya the Keeper har hans nyckel i en bevakad grotta i närheten.",h="I Jintha'alor är Elder Torntusk fjättrad och ber dig befria honom.",kw={"elder torntusk","hinterlands","hitah'ya the keeper","jintha'alor","recover the key","revantusk","nyckel till bojorna"},sec={{t="Väktarens grotta",b="Efter Kidnapped Elder Torntusk! hittar du Elder Torntusk fjättrad i Jintha'alor. Hitah'ya the Keeper har nyckeln till hans bojor i en grotta i närheten, där hon är väl bevakad. Elder Torntusk ber dig döda henne och hämta tillbaka nyckeln. Då kan han lossa sina bojor och återvända hem."},{t="Elder Torntusks tack",b="Med nyckeln kan Elder Torntusk resa sig. Han tackar dig och säger att Revantusk ska få höra om dina bedrifter."}},faq={{q="Vem har nyckeln till Elder Torntusks bojor?",a="Hitah'ya the Keeper har nyckeln till Elder Torntusks bojor. Han säger att hon är i en grotta i närheten, där hon är väl bevakad.",al={"vem har nyckeln","hitahya the keeper","var finns nyckeln till bojorna"}},{q="Var hålls Elder Torntusk fången?",a="Elder Torntusk hålls fången i Jintha'alor.",al={"var är elder torntusk","torntusks plats","jintha'alor torntusk"}},{q="Varför behöver Elder Torntusk nyckeln?",a="Nyckeln öppnar Elder Torntusks bojor. Han säger att han kan återvända hem när han är fri.",al={"varför behövs nyckeln till bojorna","vad är nyckeln till för"}}},fp="16,128,17.285.0,23.108.1,47.123.0,29.38.0,37.84.0"}
P.entries["quest:7847"] = {n="Return to Primal Torntusk",s="Elder Torntusk ber dig återvända till hans partner, Primal Torntusk, i Revantusk Village och berätta att han är på väg hem.",h="Elder Torntusk ber dig återvända till hans partner, Primal Torntusk, i Revantusk Village och berätta att han...",kw={"elder torntusk","the hinterlands","jintha'alor","primal torntusk","revantusk","revantusk village"},sec={{t="Nyheter till hans partner",b="Elder Torntusk är fri från sina bojor och ber dig återvända till Revantusk Village. Där ska du berätta för hans partner, Primal Torntusk, att han är på väg hem."},{t="Byborna är tacksamma",b="Primal Torntusk säger att du har gjort mycket för Revantusk och att byn står i stor tacksamhetsskuld till dig."}},faq={{q="Vem skickar dig på den här resan?",a="Elder Torntusk ber dig framföra nyheten om hans räddning till hans partner.",al={"vem startar return to primal torntusk","elder torntusk uppdragsgivare"}},{q="Var finns Primal Torntusk?",a="Primal Torntusk finns i Revantusk Village i The Hinterlands.",al={"var finns primal torntusk","primal torntusk plats","var lämnar man in return to primal torntusk"}},{q="Vad ska jag säga till Primal Torntusk?",a="Att Elder Torntusk är på väg hem.",al={"vad ska sägas till primal torntusk","meddelande till torntusk"}},{q="Vad hände före den här resan?",a="Den följer efter Recover the Key!, efter det tidigare försöket som började med Kidnapped Elder Torntusk!",al={"föregående uppdrag","primal torntusk uppdragskedja"}}},fp="25,98,17.139.0,23.100.1,30.65.0,33.59.0,43.56.0,30.96.0"}
P.entries["quest:7849"] = {n="Separation Anxiety",s="Huntsman Markhor i Revantusk Village har förlorat sin tvillingbror Malkhor, som togs av Vilebranch i samma räd som tog Torntusks partner. Malkhor fick ett snabbt och brutalt slut, och hans kvarlevor åts upp av Vilebranchs slemvarelser och vargar. Markhor säger att hans brors liv inte längre går att rädda, men att hans själ fortfarande kan räddas, och ber dig återfinna kvarlevorna.",h="Huntsman Markhor i Revantusk Village har förlorat sin tvillingbror Malkhor, som togs av Vilebranch i samma...",kw={"ben","hinterlands","jintha'alor","malkhor","markhor","revantusk","skalle","vilebranch","yayo'jin"},sec={{t="En tvillings förlust",b="Markhor säger att många i byn har förlorat nära och kära i vildmarken, och att hans egen förlust är hans tvilling Malkhor. Vilebranch tog Malkhor under räden då de också tog Torntusks partner. Malkhor var dömd att dö, och hans tillfångatagare gav honom en snabb och brutal död."},{t="Där kvarlevorna finns",b="Vilebranch matade sina slemvarelser och vargar med det som återstod av Malkhor. En avfallsgrop full av slemvarelser och ett varggryt ligger båda nära toppen av templet i Jintha'Alor. Hans ben ligger mitt i en slampöl nära det översta planet, och hans skalle ligger på själva översta planet. Markhor tänker ta kvarlevorna till Yayo'jin, som ska förbereda dem för en riktig begravning."}},faq={{q="Vem var Huntsman Malkhor?",a="Malkhor var Huntsman Markhors tvillingbror. Vilebranch tog honom under räden då de också tog Torntusks partner och gav honom en snabb och brutal död.",al={"vem är malkhor","markhors bror","malkhors historia"}},{q="Vart fördes Malkhors kvarlevor?",a="Vilebranch matade sina slemvarelser och vargar med hans kvarlevor. Hans skalle ligger på Jintha'Alors översta plan, och hans ben ligger i en slampöl nära det översta planet.",al={"var finns benen","var finns malkhors skalle","kvarlevor i jintha'alor"}},{q="Vem ska förbereda Malkhor för begravningen?",a="Markhor säger att han ska ta kvarlevorna till Yayo'jin, som ska förbereda dem för en riktig begravning.",al={"begravning för malkhor","vem är yayo'jin","yayo'jin"}},{q="Varför behöver Markhor få tillbaka benen?",a="Markhor kan inte längre rädda sin brors liv, men säger att hans brors själ fortfarande kan räddas. Därför vill han att kvarlevorna återfinns.",al={"varför återfinna kvarlevor","rädda malkhors själ","rädda hans själ"}}},fp="18,263,13.260.0,21.338.0,25.150.0,35.158.0,36.91.0,41.148.0"}
P.entries["quest:7850"] = {n="Dark Vessels",s="Primal Torntusk i Revantusk Village säger att Vilebranch slåss med övernaturlig vildsinthet, ett verk av Vile Priestess Hexx mörka magivävnader. Över hela Jintha'alor finns mörka kärl med besmittat blod, som utstrålar en mörk magi från den ansiktslösa blodguden. Torntusk ber dig stjäla dem och föra tillbaka dem, så att besmittelsen kan avlägsnas.",h="Primal Torntusk i Revantusk Village säger att Vilebranch slåss med övernaturlig vildsinthet, ett verk av Vile...",kw={"blodgud","dark vessels","jintha'alor","primal torntusk","revantusk village","besmittat blod","vile priestess hexx","vilebranch"},sec={{t="Vilebranchs vrede",b="Var du än går i Jintha'alor hittar du kärl med besmittat blod. De utstrålar den ansiktslösa blodgudens mörka kraft, som stärker Vilebranch och driver dem till vansinne. Torntusk tror att om kärlen förs bort och besmittelsen avlägsnas, så släpper blodguden sitt grepp om dem."},{t="När kärlen återvänt",b="När du har kärlen i din hand lyfts den mörka energi som tvingar Vilebranch, men bara för stunden. Torntusk påminner dig om att alltid vara vaksam mot ondskan, eftersom en fallen prästinna snart ersätts av en annan."}},faq={{q="Vem ger uppdraget Dark Vessels?",a="Primal Torntusk ger det i Revantusk Village i The Hinterlands.",al={"vem ger dark vessels","uppdragsgivare för dark vessels"}},{q="Var finns de besmittade kärlen?",a="Mörka kärl med besmittat blod finns över hela Jintha'alor i The Hinterlands.",al={"var finns dark vessels","plats för kärl med besmittat blod","hitta besmittat blod"}},{q="Varför är Vilebranch-trollen så vildsinta?",a="Primal Torntusk ger Vile Priestess Hexx mörka magivävnader skulden. Kärlen med besmittat blod bär också på den ansiktslösa blodgudens kraft, som stärker Vilebranch och driver dem till vansinne.",al={"varför är vilebranch galna","vilebranchs vansinne","vilebranchs vildsinthet"}},{q="Vad planerar Primal Torntusk att göra med kärlen?",a="Torntusk planerar att avlägsna besmittelsen från dem för att blodguden ska släppa sitt grepp om Vilebranch.",al={"varför samla in kärlen","vad händer med blodkärlen"}}},fp="12,227,19.251.0,24.181.1,33.66.0,38.72.0,43.184.0,54.97.0"}
